        if math.isnan(noz) or math.isnan(vol) or noz <= 0.0 or vol < 0.0:
            raise ValueError(
                f"book: nozionale>0 e vol%>=0 richiesti ('{ln}')")
        book.append((parti[0], noz, vol / 100.0, seg))
