def mh327_episodi(eq):
    """Episodi di drawdown: ogni episodio va da un picco al ritorno sopra
    il picco (o alla fine della serie se non recuperato).

    Ritorna una lista di dict con i_picco, v_picco, i_trough, v_trough,
    profondita (%, POSITIVA), durata (periodi picco->trough), recuperato
    (bool), i_recupero, periodi_recupero (None se non recuperato).
    """
    if len(eq) < 30:
        raise ValueError("episodi: servono almeno 30 periodi")
    n = len(eq)
    epis = []
    peak = eq[0]
    i_peak = 0
    in_dd = False
    trough = None
    i_trough = None
    for i in range(1, n):
        v = eq[i]
        if v >= peak:
            if in_dd:
                profondita = (peak - trough) / peak * 100.0
                epis.append({"i_picco": i_peak, "v_picco": peak,
                             "i_trough": i_trough, "v_trough": trough,
                             "profondita": profondita,
                             "durata": i_trough - i_peak,
                             "recuperato": True, "i_recupero": i,
                             "periodi_recupero": i - i_trough})
                in_dd = False
            peak = v
            i_peak = i
        else:
            if not in_dd:
                in_dd = True
                trough = v
                i_trough = i
            elif v < trough:
                trough = v
                i_trough = i
    if in_dd:
        profondita = (peak - trough) / peak * 100.0
        epis.append({"i_picco": i_peak, "v_picco": peak,
                     "i_trough": i_trough, "v_trough": trough,
                     "profondita": profondita,
                     "durata": i_trough - i_peak,
                     "recuperato": False, "i_recupero": None,
                     "periodi_recupero": None})
    return epis


def mh327_cagr(eq, periodi_anno):
    """Tasso di crescita annuo composto (frazione, es. 0.14 = 14%)."""
    import math
    p = mh327_num(periodi_anno, "periodi/anno")
    if p <= 0.0:
        raise ValueError("periodi/anno: deve essere > 0")
    if len(eq) < 30:
        raise ValueError("cagr: servono almeno 30 periodi")
    return (eq[-1] / eq[0]) ** (p / (len(eq) - 1)) - 1.0


def mh327_stat(eq, periodi_anno, n_peggiori):
    """Stat: n, cagr %, max_dd %, avg_worst %, sterling, n_ep, episodi.

    avg_worst = media delle profondita' degli n_peggiori episodi piu'
    profondi (se gli episodi sono meno di n_peggiori, media su tutti).
    sterling = CAGR / avg_worst. Se non c'e' nessun episodio: infinito se
    il CAGR e' positivo, altrimenti serie degenere (ValueError).
    """
    import math
    n = len(eq)
    if n < 30:
        raise ValueError(f"stat: servono almeno 30 periodi, trovati {n}")
    k = mh327_num(n_peggiori, "n peggiori")
    if k < 1.0 or k != int(k):
        raise ValueError("n peggiori: deve essere un intero >= 1")
    k = int(k)
    cagr = mh327_cagr(eq, periodi_anno)
    epis = sorted(mh327_episodi(eq),
                  key=lambda e: e["profondita"], reverse=True)
    n_ep = len(epis)
    if n_ep == 0:
        if cagr <= 0.0:
            raise ValueError(
                "stat: equity piatta o in calo senza drawdown, serie "
                "degenere per lo Sterling ratio")
        return {"n": n, "cagr": cagr * 100.0, "max_dd": 0.0,
                "avg_worst": 0.0, "sterling": float("inf"),
                "n_ep": 0, "episodi": []}
    profondita = [e["profondita"] for e in epis[:k]]
    avg_worst = sum(profondita) / len(profondita)
    sterling = (cagr * 100.0) / avg_worst
    return {"n": n, "cagr": cagr * 100.0, "max_dd": epis[0]["profondita"],
            "avg_worst": avg_worst, "sterling": sterling,
            "n_ep": n_ep, "episodi": epis}


def mh327_verdetto(sterling, n_ep):
    """Verdetto a 3 stati sullo Sterling ratio."""
    import math
    nota = ""
    if n_ep == 1:
        nota = (" (nota: un solo episodio di drawdown: lo Sterling coincide "
                "col Calmar)")
    if math.isinf(sterling) or sterling >= 1.5:
        return (f"sterling ratio ECCELLENTE: "
                f"{'infinito' if math.isinf(sterling) else f'{sterling:.2f}'}{nota}: "
                f"il rendimento batte con margine la media dei peggiori "
                f"drawdown: la strategia incassa colpi senza perdere la "
                f"rotta, profilo robusto.")
    if sterling >= 0.7:
        return (f"sterling ratio MODERATO: {sterling:.2f}{nota}: il rendimento "
                f"batte la media dei peggiori drawdown ma con poco margine: "
                f"gli episodi profondi si ripetono, rivedere sizing e "
                f"stop-loss prima di scalare.")
    return (f"sterling ratio DEBOLE: {sterling:.2f}{nota}: la media dei "
            f"peggiori drawdown mangia il rendimento: la strategia subisce "
            f"colpi profondi ricorrenti, ridimensionare o fermare finche' il "
            f"profilo non cambia.")


