# W481 (15/10/2026) - tab481 "📏 DV01 del portafoglio forward: sensibilità del MtM a uno shift parallelo della curva"
# ===========================================================================

def mh481_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh481_segno(s, nome):
    v = mh481_num(s, nome)
    if v not in (1.0, -1.0):
        raise ValueError(f"{nome}: +1.0 (long) o -1.0 (short)")
    return v


def mh481_mese(m, nome):
    import re
    if not isinstance(m, str) \
            or not re.fullmatch(r"\d{4}-(0[1-9]|1[0-2])", m):
        raise ValueError(f"{nome}: formato YYYY-MM atteso (es. 2026-11)")
    return m


def mh481_posizione(p, k):
    """Valida un dict posizione forward.

    Chiavi: commodity (str), scadenza ("YYYY-MM"), volume_mwh (> 0),
    segno (+1.0 long / -1.0 short), f_fix (EUR/MWh >= 0),
    f_now (EUR/MWh >= 0).
    """
    if not isinstance(p, dict):
        raise ValueError(f"posizioni[{k}]: dict atteso")
    try:
        comm = str(p["commodity"])
        scad = mh481_mese(p["scadenza"], f"posizioni[{k}].scadenza")
        vol = mh481_num(p["volume_mwh"], f"posizioni[{k}].volume_mwh")
        segno = mh481_segno(p["segno"], f"posizioni[{k}].segno")
        ff = mh481_num(p["f_fix"], f"posizioni[{k}].f_fix")
        fn = mh481_num(p["f_now"], f"posizioni[{k}].f_now")
    except KeyError as e:
        raise ValueError(f"posizioni[{k}]: chiave mancante {e}")
    if vol <= 0:
        raise ValueError(f"posizioni[{k}].volume_mwh: > 0")
    if ff < 0:
        raise ValueError(f"posizioni[{k}].f_fix: non negativo")
    if fn < 0:
        raise ValueError(f"posizioni[{k}].f_now: non negativo")
    return {"commodity": comm, "scadenza": scad, "volume_mwh": vol,
            "segno": segno, "f_fix": ff, "f_now": fn}


def mh481_mtm_linea(commodity, scadenza, volume_mwh, segno, f_fix, f_now):
    """Mark-to-market di una posizione forward.

    MtM = segno * (F_now - F_fix) * volume_mwh.
    """
    p = mh481_posizione({"commodity": commodity, "scadenza": scadenza,
                         "volume_mwh": volume_mwh, "segno": segno,
                         "f_fix": f_fix, "f_now": f_now}, "linea")
    return p["segno"] * (p["f_now"] - p["f_fix"]) * p["volume_mwh"]


def mh481_dv01_linea(commodity, scadenza, volume_mwh, segno, f_fix, f_now):
    """DV01 della linea: variazione del MtM per +1 EUR/MWh di shift
    parallelo della curva forward = segno * volume_mwh.

    Indipendente da f_fix/f_now (purezza della posizione), ma i campi
    prezzo vengono comunque validati per coerenza della posizione.
    """
    p = mh481_posizione({"commodity": commodity, "scadenza": scadenza,
                         "volume_mwh": volume_mwh, "segno": segno,
                         "f_fix": f_fix, "f_now": f_now}, "linea")
    return p["segno"] * p["volume_mwh"]


def mh481_aggregazione(posizioni):
    """Aggregazione del portafoglio forward.

    posizioni: lista non vuota di dict (vedi mh481_posizione).
    Ritorna {"mtm_totale", "dv01_totale", "net" (LONG/SHORT/FLAT),
    "per_commodity" {c: {mtm, dv01, n}}, "per_scadenza" {m: {...}},
    "scadenza_dominante" (per |dv01|), "n_posizioni", "righe"}.
    """
    if not isinstance(posizioni, (list, tuple)) or len(posizioni) == 0:
        raise ValueError("posizioni: lista non vuota")
    righe = []
    for k, p in enumerate(posizioni):
        pv = mh481_posizione(p, k)
        righe.append({**pv,
                      "mtm": pv["segno"] * (pv["f_now"] - pv["f_fix"])
                      * pv["volume_mwh"],
                      "dv01": pv["segno"] * pv["volume_mwh"]})
    mtm = sum(r["mtm"] for r in righe)
    dv = sum(r["dv01"] for r in righe)
    per_comm = {}
    per_scad = {}
    for r in righe:
        for coll, key in ((per_comm, r["commodity"]),
                          (per_scad, r["scadenza"])):
            b = coll.setdefault(key, {"mtm": 0.0, "dv01": 0.0, "n": 0})
            b["mtm"] += r["mtm"]
            b["dv01"] += r["dv01"]
            b["n"] += 1
    dom = max(per_scad.items(),
              key=lambda kv: abs(kv[1]["dv01"]))[0]
    net = "FLAT" if dv == 0.0 else ("LONG" if dv > 0 else "SHORT")
    return {"mtm_totale": mtm, "dv01_totale": dv, "net": net,
            "per_commodity": per_comm, "per_scadenza": per_scad,
            "scadenza_dominante": dom, "n_posizioni": len(righe),
            "righe": righe}


def mh481_scenario(mtm_totale, dv01_totale, delta=(1.0, 5.0, 10.0)):
    """MtM sotto shift parallelo ±d EUR/MWh della curva forward.

    Lo shift parallelo è lineare nel MtM: MtM(d) = MtM + DV01 * d.
    delta: ampiezze in EUR/MWh da cui ricavare ±d.
    Ritorna righe {"shift_eur_mwh", "mtm_eur"} ordinate per shift.
    """
    m = mh481_num(mtm_totale, "mtm_totale")
    dv = mh481_num(dv01_totale, "dv01_totale")
    ds = sorted({-mh481_num(d, "delta") for d in delta}
                | {mh481_num(d, "delta") for d in delta})
    return [{"shift_eur_mwh": d, "mtm_eur": m + dv * d} for d in ds]


def mh481_verdetto(posizioni):
    """Giudizio sintetico: esposizione netta + concentrazione.

    concentrazione = |DV01 della scadenza dominante| / Σ|DV01|.
    BILANCIATO: |net|/Σ|DV01| < 0.3 (posizioni che si compensano);
    CONCENTRATO: la scadenza dominante pesa >= 60% di Σ|DV01|;
    ESPOSTO NETTO: altrimenti (rischio direzionale diffuso).
    Ritorna {"verdetto", "net", "concentrazione", "dv01_totale",
    "scadenza_dominante"}.
    """
    agg = mh481_aggregazione(posizioni)
    abs_tot = sum(abs(r["dv01"]) for r in agg["righe"])
    dom = agg["scadenza_dominante"]
    conc = (abs(agg["per_scadenza"][dom]["dv01"]) / abs_tot
            if abs_tot > 0 else 0.0)
    net_rel = (abs(agg["dv01_totale"]) / abs_tot
               if abs_tot > 0 else 0.0)
    if abs_tot == 0.0 or net_rel < 0.3:
        verd = "BILANCIATO"
    elif conc >= 0.6:
        verd = "CONCENTRATO"
    else:
        verd = "ESPOSTO NETTO"
    return {"verdetto": verd, "net": agg["net"],
            "concentrazione": conc, "dv01_totale": agg["dv01_totale"],
            "scadenza_dominante": dom}
# W482 (15/10/2026) - tab482 "🗓️ Ladder delle scadenze: profilo temporale di volumi, MtM e DV01"
# ===========================================================================

def mh482_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh482_segno(s, nome):
    v = mh482_num(s, nome)
    if v not in (1.0, -1.0):
        raise ValueError(f"{nome}: +1.0 (long) o -1.0 (short)")
    return v


def mh482_mese(m, nome):
    import re
    if not isinstance(m, str) \
            or not re.fullmatch(r"\d{4}-(0[1-9]|1[0-2])", m):
        raise ValueError(f"{nome}: formato YYYY-MM atteso (es. 2026-11)")
    return m


def mh482_fine_mese(m):
    """Ultimo giorno del mese di consegna YYYY-MM come datetime.date."""
    import calendar
    import datetime
    mm = mh482_mese(m, "scadenza")
    anno, mese = int(mm[:4]), int(mm[5:7])
    return datetime.date(anno, mese, calendar.monthrange(anno, mese)[1])


def mh482_giorni(m, data_val):
    """Giorni dalla data di valutazione all'ultimo giorno del mese di consegna.

    ValueError se la consegna e' gia' chiusa (mese passato) o se data_val
    non e' una data.
    """
    import datetime
    if not isinstance(data_val, datetime.date):
        raise ValueError("data_val: deve essere una data (datetime.date)")
    g = (mh482_fine_mese(m) - data_val).days
    if g < 0:
        raise ValueError(
            f"scadenza {m}: consegna gia' chiusa alla data di valutazione")
    return g


def mh482_bucket(g):
    """Bucket temporale della ladder; soglie inclusive a destra."""
    import numbers
    if isinstance(g, bool) or not isinstance(g, numbers.Integral):
        raise ValueError("giorni: intero >= 0 atteso")
    g = int(g)
    if g < 0:
        raise ValueError("giorni: intero >= 0 atteso")
    if g <= 30:
        return "\u2264 30 gg"
    if g <= 90:
        return "31\u201390 gg"
    if g <= 180:
        return "91\u2013180 gg"
    if g <= 365:
        return "181\u2013365 gg"
    return "> 365 gg"


def mh482_posizione(p, k, data_val):
    """Valida una riga posizione e la arricchisce con giorni, bucket, MtM e DV01.

    MtM = segno x (F_now - F_fix) x volume; DV01 = segno x volume (come tab481).
    """
    d = dict(p)
    d["commodity"] = str(d.get("commodity", ""))
    d["volume_mwh"] = mh482_num(d.get("volume_mwh"), f"pos{k}.volume_mwh")
    if d["volume_mwh"] < 0.0:
        raise ValueError(f"pos{k}.volume_mwh: >= 0 atteso")
    d["segno"] = mh482_segno(d.get("segno"), f"pos{k}.segno")
    d["f_fix"] = mh482_num(d.get("f_fix"), f"pos{k}.f_fix")
    d["f_now"] = mh482_num(d.get("f_now"), f"pos{k}.f_now")
    d["scadenza"] = mh482_mese(d.get("scadenza"), f"pos{k}.scadenza")
    d["giorni"] = mh482_giorni(d["scadenza"], data_val)
    d["bucket"] = mh482_bucket(d["giorni"])
    d["mtm"] = d["segno"] * (d["f_now"] - d["f_fix"]) * d["volume_mwh"]
    d["dv01"] = d["segno"] * d["volume_mwh"]
    return d


def mh482_aggregazione(posizioni, data_val):
    """Ladder delle scadenze: aggrega le righe validate per bucket temporale.

    duration_gg = media dei giorni alla consegna pesata sui volumi;
    quota_90 / quota_365 = quota di volume con giorni <= 90 / giorni > 365.
    """
    ordine = ("\u2264 30 gg", "31\u201390 gg", "91\u2013180 gg",
              "181\u2013365 gg", "> 365 gg")
    righe = [mh482_posizione(p, i, data_val) for i, p in enumerate(posizioni)]
    if not righe:
        raise ValueError("nessuna posizione")
    per_bucket = {b: {"vol_long": 0.0, "vol_short": 0.0, "vol_net": 0.0,
                      "mtm": 0.0, "dv01": 0.0} for b in ordine}
    for r in righe:
        b = per_bucket[r["bucket"]]
        if r["segno"] > 0.0:
            b["vol_long"] += r["volume_mwh"]
        else:
            b["vol_short"] += r["volume_mwh"]
        b["mtm"] += r["mtm"]
        b["dv01"] += r["dv01"]
    for b in per_bucket.values():
        b["vol_net"] = b["vol_long"] - b["vol_short"]
    tot_vol = sum(r["volume_mwh"] for r in righe)
    if tot_vol <= 0.0:
        raise ValueError("volume totale nullo")
    duration_gg = sum(r["giorni"] * r["volume_mwh"] for r in righe) / tot_vol
    quota_90 = sum(r["volume_mwh"] for r in righe
                   if r["giorni"] <= 90) / tot_vol
    quota_365 = sum(r["volume_mwh"] for r in righe
                    if r["giorni"] > 365) / tot_vol
    per_scadenza = {}
    for r in righe:
        e = per_scadenza.setdefault(r["scadenza"], {"dv01": 0.0})
        e["dv01"] += r["dv01"]
    dom = max(per_scadenza.items(),
              key=lambda kv: abs(kv[1]["dv01"]))[0]
    return {"righe": righe, "per_bucket": per_bucket,
            "n_posizioni": len(righe),
            "mtm_totale": sum(r["mtm"] for r in righe),
            "dv01_totale": sum(r["dv01"] for r in righe),
            "tot_vol": tot_vol,
            "duration_gg": duration_gg,
            "duration_mesi": duration_gg / 30.44,
            "quota_90": quota_90, "quota_365": quota_365,
            "per_scadenza": per_scadenza,
            "scadenza_dominante": dom}


def mh482_verdetto(agg):
    """Verdetto sul profilo temporale del book.

    FRONT-LOADED: >= 60% del volume scade entro 90 giorni (il rischio
    diventa cassa a breve); BACK-LOADED: >= 60% oltre 365 giorni;
    DISTRIBUITO: il resto. Riporta anche la scadenza dominante per |DV01|.
    """
    try:
        quota_90 = mh482_num(agg["quota_90"], "quota_90")
        quota_365 = mh482_num(agg["quota_365"], "quota_365")
        dom = agg["scadenza_dominante"]
        per_scad = agg["per_scadenza"]
    except (KeyError, TypeError, AttributeError):
        raise ValueError("aggregato ladder malformato")
    if quota_90 >= 0.6:
        verd = "FRONT-LOADED"
    elif quota_365 >= 0.6:
        verd = "BACK-LOADED"
    else:
        verd = "DISTRIBUITO"
    abs_tot = sum(abs(e["dv01"]) for e in per_scad.values())
    conc = (abs(per_scad[dom]["dv01"]) / abs_tot
            if abs_tot > 0 else 0.0)
    return {"verdetto": verd, "quota_90": quota_90, "quota_365": quota_365,
            "scadenza_dominante": dom, "concentrazione": conc}

def mh480_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh480_mtm_linea(qta_mwh, segno, prezzo_ieri, prezzo_oggi):
    """Mark-to-market giornaliero di una linea futures.

    segno: +1.0 long, -1.0 short.
    MtM = qta * segno * (prezzo_oggi - prezzo_ieri).
    """
    q = mh480_num(qta_mwh, "qta_mwh")
    s = mh480_num(segno, "segno")
    pi = mh480_num(prezzo_ieri, "prezzo_ieri")
    po = mh480_num(prezzo_oggi, "prezzo_oggi")
    if q < 0:
        raise ValueError("qta_mwh: non negativa")
    if s not in (1.0, -1.0):
        raise ValueError("segno: +1.0 (long) o -1.0 (short)")
    if pi < 0:
        raise ValueError("prezzo_ieri: non negativo")
    if po < 0:
        raise ValueError("prezzo_oggi: non negativo")
    return q * s * (po - pi)


def mh480_mtm_totale(linee):
    """Aggregazione MtM su N linee.

    linee: lista di dict {"nome", "qta_mwh", "segno", "prezzo_ieri",
    "prezzo_oggi"}.
    Ritorna {"totale", "righe" (con "mtm" e "quota" su somma |mtm|),
    "n_linee"}.
    """
    if not isinstance(linee, (list, tuple)) or len(linee) == 0:
        raise ValueError("linee: lista non vuota")
    righe = []
    for k, ln in enumerate(linee):
        try:
            nome = str(ln["nome"])
            q = mh480_num(ln["qta_mwh"], f"linee[{k}].qta_mwh")
            s = mh480_num(ln["segno"], f"linee[{k}].segno")
            pi = mh480_num(ln["prezzo_ieri"], f"linee[{k}].prezzo_ieri")
            po = mh480_num(ln["prezzo_oggi"], f"linee[{k}].prezzo_oggi")
        except (KeyError, TypeError):
            raise ValueError(
                f"linee[{k}]: dict con nome/qta_mwh/segno/prezzo_ieri/"
                "prezzo_oggi")
        mtm = mh480_mtm_linea(q, s, pi, po)
        righe.append({"nome": nome, "qta_mwh": q, "segno": s,
                      "prezzo_ieri": pi, "prezzo_oggi": po, "mtm": mtm})
    tot = sum(r["mtm"] for r in righe)
    base = sum(abs(r["mtm"]) for r in righe)
    for r in righe:
        r["quota"] = (abs(r["mtm"]) / base) if base > 0 else 0.0
    return {"totale": tot, "righe": righe, "n_linee": len(righe)}


def mh480_margine_richiesto(im_linee):
    """IM totale richiesto dal clearing: somma degli IM per linea."""
    if not isinstance(im_linee, (list, tuple)) or len(im_linee) == 0:
        raise ValueError("im_linee: lista non vuota")
    vals = [mh480_num(v, f"im_linee[{k}]")
            for k, v in enumerate(list(im_linee))]
    for k, v in enumerate(vals):
        if v < 0:
            raise ValueError(f"im_linee[{k}]: non negativo")
    return sum(vals)


def mh480_equity(collaterale_eur, mtm_totale):
    """Equity del conto margini: collaterale postato + MtM del giorno."""
    c = mh480_num(collaterale_eur, "collaterale_eur")
    m = mh480_num(mtm_totale, "mtm_totale")
    if c < 0:
        raise ValueError("collaterale_eur: non negativo")
    return c + m


def mh480_call_margine(im_richiesto, equity):
    """Margin call: max(0, IM richiesto - equity)."""
    im = mh480_num(im_richiesto, "im_richiesto")
    eq = mh480_num(equity, "equity")
    if im < 0:
        raise ValueError("im_richiesto: non negativo")
    return max(0.0, im - eq)


def mh480_shock_mtm(linee, shock_pct):
    """MtM avverso sotto stress: per ogni linea -qta * prezzo_oggi *
    shock%/100 (movimento sempre contro la posizione).

    linee: lista di dict {"qta_mwh", "prezzo_oggi"}.
    Ritorna un numero <= 0 (perdita di stress).
    """
    s = mh480_num(shock_pct, "shock_pct")
    if s < 0:
        raise ValueError("shock_pct: non negativo")
    if not isinstance(linee, (list, tuple)) or len(linee) == 0:
        raise ValueError("linee: lista non vuota")
    tot = 0.0
    for k, ln in enumerate(linee):
        try:
            q = mh480_num(ln["qta_mwh"], f"linee[{k}].qta_mwh")
            po = mh480_num(ln["prezzo_oggi"], f"linee[{k}].prezzo_oggi")
        except (KeyError, TypeError):
            raise ValueError(f"linee[{k}]: dict con qta_mwh/prezzo_oggi")
        if q < 0:
            raise ValueError(f"linee[{k}].qta_mwh: non negativa")
        if po < 0:
            raise ValueError(f"linee[{k}].prezzo_oggi: non negativo")
        tot += -q * po * (s / 100.0)
    return tot


def mh480_copertura_liquidita(collaterale_libero_eur, call_eur):
    """Copertura della call con il buffer liquido: libero / call.

    Con call = 0 ritorna inf (nessuna call da coprire).
    """
    lib = mh480_num(collaterale_libero_eur, "collaterale_libero_eur")
    call = mh480_num(call_eur, "call_eur")
    if lib < 0:
        raise ValueError("collaterale_libero_eur: non negativo")
    if call < 0:
        raise ValueError("call_eur: non negativo")
    if call == 0.0:
        return float("inf")
    return lib / call


def mh480_verdetto(call_eur, copertura):
    """Giudizio sintetico sulla liquidita' del conto margini.

    NESSUNA CALL (call = 0) / LIQUIDA (copertura >= 1.5) /
    ATTENZIONE (1.0 <= copertura < 1.5) / CALL IMMINENTE (< 1.0).
    """
    import math
    call = mh480_num(call_eur, "call_eur")
    cop = (float("inf") if copertura == float("inf")
           else mh480_num(copertura, "copertura"))
    if call < 0:
        raise ValueError("call_eur: non negativo")
    if cop < 0:
        raise ValueError("copertura: non negativa")
    if call == 0.0:
        return "NESSUNA CALL"
    if math.isinf(cop):
        return "LIQUIDA"
    if cop >= 1.5:
        return "LIQUIDA"
    if cop >= 1.0:
        return "ATTENZIONE"
    return "CALL IMMINENTE"
# ===========================================================================
# W487 (16/10/2026) - tab487 "📉 VaR ed Expected Shortfall del portafoglio forward: il rischio giornaliero"
# Dopo l'attribuzione del P&L realizzato (theta/delta/rho tab484-486), la domanda
# del risk manager: quanto può perdere il portafoglio forward in UNA giornata?
# VaR parametrico giornaliero per linea: dal DV01 (tab481) e dalla volatilità
# giornaliera della commodity, sigma_mtm = |DV01| * sigma_pct/100 * prezzo.
# VaR_99% = z * sigma_mtm; ES_99% = sigma_mtm * phi(z)/(1-Phi(z)).
# Aggregazione CONSERVATIVA (correlazione = 1: sigma = somma) contro
# indipendenza (RSS): il rapporto mostra il beneficio di diversificazione.
# Verdetto sul rapporto VaR_cons / |MtM|: RISCHIO ELEVATO (>=10%),
# RISCHIO CONTENUTO (<=2%), altrimenti RISCHIO MODERATO; NEUTRALE se MtM nullo.
# ===========================================================================
def mh487_num(x, nome):
    """Coercizione numerica stretta: rifiuta bool/str/None/NaN/inf."""
    import math
    if isinstance(x, bool) or not isinstance(x, (int, float)):
        raise ValueError(f"{nome}: numero non valido ({x!r})")
    if not math.isfinite(x):
        raise ValueError(f"{nome}: deve essere finito ({x!r})")
    return float(x)


def mh487_segno(v, nome):
    """Segno posizione: +1.0 long, -1.0 short; tutto il resto rifiutato."""
    if isinstance(v, bool) or v not in (1, -1, 1.0, -1.0):
        raise ValueError(
            f"{nome}: segno deve essere +1 (long) o -1 (short), got {v!r}")
    return float(v)


def mh487_mese(s, nome):
    """Mese di consegna in formato YYYY-MM, validato."""
    if not isinstance(s, str) or len(s) != 7 or s[4] != "-":
        raise ValueError(f"{nome}: mese non valido ({s!r}), formato YYYY-MM")
    _y487, _m487 = s[:4], s[5:]
    if not (_y487.isdigit() and _m487.isdigit() and 1 <= int(_m487) <= 12):
        raise ValueError(f"{nome}: mese non valido ({s!r}), formato YYYY-MM")
    return s


def mh487_z(conf, nome):
    """Quantile normale standard per confidenza 0.99 o 0.975."""
    _c487 = mh487_num(conf, nome)
    if _c487 == 0.99:
        return 2.3263478740408408
    if _c487 == 0.975:
        return 1.959963984540054
    raise ValueError(
        f"{nome}: confidenza deve essere 0.99 o 0.975, got {conf!r}")


def mh487_phi(z):
    """Densita' normale standard."""
    import math
    return math.exp(-z * z / 2.0) / math.sqrt(2.0 * math.pi)


def mh487_Phi(z):
    """Ripartizione normale standard (via erf)."""
    import math
    return 0.5 * (1.0 + math.erf(z / math.sqrt(2.0)))


def mh487_dv01_linea(segno, volume, nome="dv01"):
    """DV01 della linea: segno * volume (EUR per +1 EUR/MWh)."""
    _s487 = mh487_segno(segno, nome)
    _v487 = mh487_num(volume, nome)
    if _v487 < 0.0:
        raise ValueError(f"{nome}: volume non negativo ({volume!r})")
    return _s487 * _v487


def mh487_sigma_mtm_linea(dv01, sigma_pct, prezzo, nome="sigma"):
    """Volatilita' giornaliera del MtM: |DV01| * sigma_pct/100 * prezzo."""
    _sg487 = mh487_num(sigma_pct, nome)
    if not (0.0 < _sg487 <= 100.0):
        raise ValueError(
            f"{nome}: sigma_pct in (0,100] percento, got {sigma_pct!r}")
    _p487 = mh487_num(prezzo, nome)
    if _p487 < 0.0:
        raise ValueError(f"{nome}: prezzo non negativo ({prezzo!r})")
    return abs(mh487_num(dv01, nome)) * _sg487 / 100.0 * _p487


def mh487_var_linea(sigma_mtm, z, nome="var"):
    """VaR parametrico: z * sigma_mtm (perdita massima al livello z)."""
    _sm487 = mh487_num(sigma_mtm, nome)
    _z487 = mh487_num(z, nome)
    if _sm487 < 0.0:
        raise ValueError(f"{nome}: sigma_mtm non negativa ({sigma_mtm!r})")
    if _z487 <= 0.0:
        raise ValueError(f"{nome}: z deve essere positivo ({z!r})")
    return _z487 * _sm487


def mh487_es_linea(sigma_mtm, z, nome="es"):
    """Expected Shortfall: sigma_mtm * phi(z)/(1-Phi(z)), sempre >= VaR."""
    _sm487 = mh487_num(sigma_mtm, nome)
    _z487 = mh487_num(z, nome)
    if _sm487 < 0.0:
        raise ValueError(f"{nome}: sigma_mtm non negativa ({sigma_mtm!r})")
    if _z487 <= 0.0:
        raise ValueError(f"{nome}: z deve essere positivo ({z!r})")
    _tail487 = 1.0 - mh487_Phi(_z487)
    if _tail487 <= 0.0:
        raise ValueError(f"{nome}: coda nulla per z={z!r}")
    return _sm487 * mh487_phi(_z487) / _tail487


def mh487_riga(commodity, scadenza, volume, segno, f_fix, f_now, sigma_pct,
               nome="riga"):
    """Riga completa: DV01, MtM, sigma giornaliera, VaR, ES."""
    mh487_mese(scadenza, nome)
    _ff487 = mh487_num(f_fix, nome)
    _fn487 = mh487_num(f_now, nome)
    _dv487 = mh487_dv01_linea(segno, volume, nome)
    _sg487 = mh487_sigma_mtm_linea(_dv487, sigma_pct, _fn487, nome)
    return {"commodity": commodity, "scadenza": scadenza,
            "volume_mwh": mh487_num(volume, nome),
            "segno": mh487_segno(segno, nome),
            "f_fix": _ff487, "f_now": _fn487,
            "sigma_pct": mh487_num(sigma_pct, nome),
            "dv01": _dv487, "mtm": _dv487 * (_fn487 - _ff487),
            "sigma_mtm": _sg487}


def mh487_portafoglio(righe, z, nome="portafoglio"):
    """Aggregazione: conservativa (corr=1, somma) vs indipendenza (RSS).

    VaR/ES per linea sono additivi nel caso conservativo; nel caso
    indipendente si applicano a sigma_ind = sqrt(sum(sigma_i^2)).
    """
    if not isinstance(righe, list) or not righe:
        raise ValueError(f"{nome}: servono almeno una riga di posizione")
    _z487 = mh487_num(z, nome)
    _sig487 = [mh487_num(r["sigma_mtm"], nome) for r in righe]
    _var487 = [mh487_var_linea(s, _z487, nome) for s in _sig487]
    _es487 = [mh487_es_linea(s, _z487, nome) for s in _sig487]
    _sc487 = sum(_sig487)
    import math
    _si487 = math.sqrt(sum(s * s for s in _sig487))
    return {"n_posizioni": len(righe),
            "mtm_tot": sum(mh487_num(r["mtm"], nome) for r in righe),
            "sigma_cons": _sc487, "sigma_ind": _si487,
            "var_cons": sum(_var487), "es_cons": sum(_es487),
            "var_ind": mh487_var_linea(_si487, _z487, nome),
            "es_ind": mh487_es_linea(_si487, _z487, nome),
            "div_benefit": (1.0 - _si487 / _sc487) if _sc487 > 0.0 else 0.0,
            "z": _z487}


def mh487_verdetto(righe, z, soglia_elevata=0.10, soglia_contenuta=0.02,
                   nome="verdetto"):
    """Verdetto sul rischio: VaR_cons / |MtM| contro soglie 10% / 2%."""
    _agg487 = mh487_portafoglio(righe, z, nome)
    _var487 = _agg487["var_cons"]
    _mtm487 = _agg487["mtm_tot"]
    _se487 = mh487_num(soglia_elevata, nome)
    _sc487 = mh487_num(soglia_contenuta, nome)
    if not (0.0 < _sc487 < _se487 < 10.0):
        raise ValueError(
            f"{nome}: soglie incoerenti ({soglia_contenuta!r}, "
            f"{soglia_elevata!r})")
    if abs(_mtm487) < 1e-9:
        return {"verdetto": "NEUTRALE", "ratio": None, "var_cons": _var487,
                "mtm_tot": _mtm487, "es_cons": _agg487["es_cons"],
                "var_ind": _agg487["var_ind"], "es_ind": _agg487["es_ind"],
                "div_benefit": _agg487["div_benefit"]}
    _ratio487 = _var487 / abs(_mtm487)
    if _ratio487 >= _se487:
        _v487 = "RISCHIO ELEVATO"
    elif _ratio487 <= _sc487:
        _v487 = "RISCHIO CONTENUTO"
    else:
        _v487 = "RISCHIO MODERATO"
    return {"verdetto": _v487, "ratio": _ratio487, "var_cons": _var487,
            "mtm_tot": _mtm487, "es_cons": _agg487["es_cons"],
            "var_ind": _agg487["var_ind"], "es_ind": _agg487["es_ind"],
            "div_benefit": _agg487["div_benefit"]}


# ===========================================================================
# W488 (16/10/2026) - tab488 "🌪️📉 Stressed VaR: il VaR sotto volatilità stressata"
# Dopo il VaR giornaliero "normale" (tab487), la domanda del risk manager in
# un mercato energetico che nel 2022 ha visto volatilità giornaliere 3-5x
# quelle ordinarie: quanto perde il portafoglio forward se la volatilità
# raddoppia o triplica? Stressed VaR stile Basilea (sVaR):
# sigma_stress = sigma × moltiplicatore (1..10); VaR_stress = z×sigma_stress;
# ES_stress = sigma_stress × phi(z)/(1-Phi(z)), sempre >= VaR_stress.
# Aggregazione conservativa (corr=1, somme) vs indipendenza (RSS) sia in
# regime normale che stressato; il rapporto VaR_stress/VaR mostra
# l'amplificazione del rischio. Verdetto contro il limite di rischio:
# ENTRO IL LIMITE SOTTO STRESS se VaR_stress_cons <= limite, altrimenti
# LIMITE SFONDATO SOTTO STRESS. Moltiplicatore critico = limite/VaR_cons:
# oltre quel moltiplicatore il limite non regge più (reverse stress test).
# ===========================================================================


def mh488_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh488_segno(v, nome):
    _v488 = mh488_num(v, nome)
    if _v488 not in (1.0, -1.0):
        raise ValueError(f"{nome}: segno deve essere +1.0 o -1.0")
    return _v488


def mh488_mese(s, nome):
    if not isinstance(s, str):
        raise ValueError(f"{nome}: scadenza deve essere stringa YYYY-MM")
    _s488 = s.strip()
    _p488 = _s488.split("-")
    if len(_p488) != 2 or len(_p488[0]) != 4 or len(_p488[1]) != 2:
        raise ValueError(f"{nome}: formato YYYY-MM, got {s!r}")
    if not (_p488[0].isdigit() and _p488[1].isdigit()):
        raise ValueError(f"{nome}: formato YYYY-MM, got {s!r}")
    if not (1 <= int(_p488[1]) <= 12):
        raise ValueError(f"{nome}: mese 01-12, got {s!r}")
    return _s488


def mh488_z(conf, nome):
    _c488 = mh488_num(conf, nome)
    if _c488 == 0.99:
        return 2.3263478740408408
    if _c488 == 0.975:
        return 1.959963984540054
    raise ValueError(f"{nome}: confidenza 0.99 o 0.975, got {conf!r}")


def mh488_phi(z):
    """Densita' normale standard."""
    import math
    _z488 = mh488_num(z, "z")
    return math.exp(-_z488 * _z488 / 2.0) / math.sqrt(2.0 * math.pi)


def mh488_Phi(z):
    """Ripartizione normale standard (via erf)."""
    import math
    _z488 = mh488_num(z, "z")
    return 0.5 * (1.0 + math.erf(_z488 / math.sqrt(2.0)))


def mh488_mult(m, nome="moltiplicatore"):
    """Moltiplicatore di stress della volatilita', in [1, 10]."""
    _m488 = mh488_num(m, nome)
    if not (1.0 <= _m488 <= 10.0):
        raise ValueError(f"{nome}: moltiplicatore stress in [1,10], got {m!r}")
    return _m488


def mh488_limite(l, nome="limite"):
    """Limite di rischio VaR in EUR, positivo."""
    _l488 = mh488_num(l, nome)
    if _l488 <= 0.0:
        raise ValueError(f"{nome}: limite VaR positivo in EUR, got {l!r}")
    return _l488


def mh488_dv01_linea(segno, volume, nome="dv01"):
    """DV01 della linea: segno * volume (EUR per +1 EUR/MWh)."""
    _s488 = mh488_segno(segno, nome)
    _v488 = mh488_num(volume, nome)
    if _v488 < 0.0:
        raise ValueError(f"{nome}: volume non negativo ({volume!r})")
    return _s488 * _v488


def mh488_mtm_linea(segno, volume, f_fix, f_now, nome="mtm"):
    """MtM della linea: segno * (f_now - f_fix) * volume."""
    _s488 = mh488_segno(segno, nome)
    _v488 = mh488_num(volume, nome)
    _ff488 = mh488_num(f_fix, nome)
    _fn488 = mh488_num(f_now, nome)
    if _v488 < 0.0:
        raise ValueError(f"{nome}: volume non negativo ({volume!r})")
    if _ff488 < 0.0 or _fn488 < 0.0:
        raise ValueError(f"{nome}: prezzi forward non negativi")
    return _s488 * (_fn488 - _ff488) * _v488


def mh488_sigma_mtm_linea(dv01, sigma_pct, prezzo, nome="sigma"):
    """Volatilita' giornaliera del MtM: |DV01| * sigma_pct/100 * prezzo."""
    _sg488 = mh488_num(sigma_pct, nome)
    if not (0.0 < _sg488 <= 100.0):
        raise ValueError(
            f"{nome}: sigma_pct in (0,100] percento, got {sigma_pct!r}")
    _p488 = mh488_num(prezzo, nome)
    if _p488 < 0.0:
        raise ValueError(f"{nome}: prezzo non negativo ({prezzo!r})")
    return abs(mh488_num(dv01, nome)) * _sg488 / 100.0 * _p488


def mh488_var_es_linea(sigma_mtm, z, mult, nome="linea"):
    """VaR ed ES normali + stressati di una linea (stress = x mult)."""
    _sm488 = mh488_num(sigma_mtm, nome)
    _z488 = mh488_num(z, nome)
    _m488 = mh488_mult(mult, nome)
    if _sm488 < 0.0:
        raise ValueError(f"{nome}: sigma_mtm non negativa ({sigma_mtm!r})")
    if _z488 <= 0.0:
        raise ValueError(f"{nome}: z deve essere positivo ({z!r})")
    _tail488 = 1.0 - mh488_Phi(_z488)
    if _tail488 <= 0.0:
        raise ValueError(f"{nome}: coda nulla per z={z!r}")
    _var488 = _z488 * _sm488
    _es488 = _sm488 * mh488_phi(_z488) / _tail488
    return {"var": _var488, "es": _es488,
            "var_stress": _var488 * _m488, "es_stress": _es488 * _m488}


def mh488_riga(commodity, scadenza, volume, segno, f_fix, f_now, sigma_pct,
               nome="riga"):
    """Riga posizione: validatori + dv01/mtm/sigma_mtm della linea."""
    _sc488 = mh488_mese(scadenza, nome)
    _dv488 = mh488_dv01_linea(segno, volume, nome)
    _mtm488 = mh488_mtm_linea(segno, volume, f_fix, f_now, nome)
    _sg488 = mh488_sigma_mtm_linea(_dv488, sigma_pct, f_now, nome)
    return {"commodity": str(commodity), "scadenza": _sc488,
            "volume_mwh": mh488_num(volume, nome),
            "segno": mh488_segno(segno, nome),
            "f_fix": mh488_num(f_fix, nome), "f_now": mh488_num(f_now, nome),
            "sigma_pct": mh488_num(sigma_pct, nome),
            "dv01": _dv488, "mtm": _mtm488, "sigma_mtm": _sg488}


def mh488_portafoglio(righe, z, mult, nome="portafoglio"):
    """Aggregati normali e stressati: conservativo (corr=1) vs indipendenza."""
    import math
    _z488 = mh488_num(z, nome)
    _m488 = mh488_mult(mult, nome)
    if not righe:
        raise ValueError(f"{nome}: almeno una posizione")
    _lr488 = []
    for _r488 in righe:
        _ve488 = mh488_var_es_linea(_r488["sigma_mtm"], _z488, _m488, nome)
        _lr488.append({**_r488, **_ve488})
    _var_c488 = sum(_x488["var"] for _x488 in _lr488)
    _es_c488 = sum(_x488["es"] for _x488 in _lr488)
    _var_i488 = math.sqrt(sum(_x488["var"] ** 2 for _x488 in _lr488))
    _es_i488 = math.sqrt(sum(_x488["es"] ** 2 for _x488 in _lr488))
    return {"righe": _lr488,
            "mtm_tot": sum(_x488["mtm"] for _x488 in _lr488),
            "var_cons": _var_c488, "es_cons": _es_c488,
            "var_ind": _var_i488, "es_ind": _es_i488,
            "var_stress_cons": _var_c488 * _m488,
            "es_stress_cons": _es_c488 * _m488,
            "var_stress_ind": _var_i488 * _m488,
            "es_stress_ind": _es_i488 * _m488,
            "amplificazione": _m488}


def mh488_moltiplicatore_critico(var_cons, limite, nome="mult_critico"):
    """Moltiplicatore di stress che sfonda il limite: limite / VaR_cons.

    None se il VaR e' nullo (nessuno stress puo' sfondare).
    """
    _v488 = mh488_num(var_cons, nome)
    _l488 = mh488_limite(limite, nome)
    if _v488 <= 0.0:
        return None
    return _l488 / _v488


def mh488_verdetto(righe, z, mult, limite, nome="verdetto"):
    """Verdetto: il VaR stressato conservativo regge il limite?"""
    _agg488 = mh488_portafoglio(righe, z, mult, nome)
    _l488 = mh488_limite(limite, nome)
    _vs488 = _agg488["var_stress_cons"]
    _mc488 = mh488_moltiplicatore_critico(_agg488["var_cons"], _l488, nome)
    _v488 = ("ENTRO IL LIMITE SOTTO STRESS" if _vs488 <= _l488
             else "LIMITE SFONDATO SOTTO STRESS")
    return {"verdetto": _v488, "var_cons": _agg488["var_cons"],
            "var_stress_cons": _vs488, "es_stress_cons": _agg488["es_stress_cons"],
            "limite": _l488, "mult_critico": _mc488,
            "mtm_tot": _agg488["mtm_tot"]}


# ===========================================================================
# W486 (15/10/2026) - tab486 "🧾🔍 P&L spiegato dalle greche: theta, delta e rho contro il ΔMtM realizzato"
# Dopo le greche singole (theta tab484 = roll-down nel tempo, rho tab485 =
# sconto al tasso), la domanda del risk manager: il ΔMtM REALIZZATO tra due
# date di valutazione è spiegato dalle greche? Scomposizione per linea:
#   theta  = segno × (f(tau1) - f(tau0)) × volume            (roll-down)
#   delta  = segno × (f_new - f(tau1)) × volume × df_new     (prezzo puro)
#   rho    = segno × (f_new - f_fix) × volume × (df_new - df_old_a_tau1)
#   ΔMtM   = segno×(f_new-f_fix)×vol×df_new - segno×(f_old-f_fix)×vol×df_old
#   residuo = ΔMtM - theta - delta - rho   (interazioni, forma curva...)
# tau1 = anni da t1 a fine mese consegna; tau0 = tau1 + giorni/365.25;
# df = exp(-r×tau); f(tau) = interpolazione lineare sulla curva a t1 con
# clamp agli estremi (stessa convenzione della tab484).
# Verdetto: SPIEGATO se |residuo| <= max(100 EUR, 5% di |ΔMtM|),
# QUASI SPIEGATO se <= 20%, altrimenti DA INDAGARE.
# ===========================================================================


def mh486_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh486_segno(s, nome):
    v = mh486_num(s, nome)
    if v not in (1.0, -1.0):
        raise ValueError(f"{nome}: +1.0 (long) o -1.0 (short)")
    return v


def mh486_mese(m, nome):
    import re
    if not isinstance(m, str) \
            or not re.fullmatch(r"\d{4}-(0[1-9]|1[0-2])", m):
        raise ValueError(f"{nome}: formato YYYY-MM atteso (es. 2026-11)")
    return m


def mh486_mese_ord(m):
    """\"2026-11\" -> ordinale intero anno*12+mese (per l'aritmetica sui tenor)."""
    mh486_mese(m, "mese")
    a, b = m.split("-")
    return int(a) * 12 + int(b)


def mh486_ord_mese(o):
    """Ordinale intero -> "YYYY-MM". o deve essere un intero >= 1."""
    import numbers
    if isinstance(o, bool) or not isinstance(o, numbers.Integral):
        raise ValueError("ordinale: intero atteso")
    o = int(o)
    if o < 1:
        raise ValueError("ordinale: >= 1")
    y, mm = divmod(o - 1, 12)
    return f"{y:04d}-{mm + 1:02d}"


def mh486_data(d, nome):
    import datetime
    import re
    if not isinstance(d, str) \
            or not re.fullmatch(r"\d{4}-(0[1-9]|1[0-2])-(0[1-9]|[12]\d|3[01])", d):
        raise ValueError(f"{nome}: formato YYYY-MM-DD atteso (es. 2026-10-15)")
    try:
        return datetime.date(int(d[0:4]), int(d[5:7]), int(d[8:10]))
    except ValueError:
        raise ValueError(f"{nome}: data non valida ({d})")


def mh486_fine_mese(anno, mese):
    """Ultimo giorno del mese (anno, mese) come datetime.date."""
    import calendar
    import datetime
    a = int(anno)
    m = int(mese)
    if not 1 <= m <= 12:
        raise ValueError("mese: 1..12")
    return datetime.date(a, m, calendar.monthrange(a, m)[1])


def mh486_tasso(r, nome):
    v = mh486_num(r, nome)
    if not -0.10 <= v <= 0.50:
        raise ValueError(f"{nome}: tra -10% e +50% (decimale)")
    return v


def mh486_curva(curva, nome):
    """Valida una curva forward {"YYYY-MM": prezzo >= 0}.

    Ritorna la lista ordinata [(ordinale, prezzo)] per l'interpolazione.
    """
    if not isinstance(curva, dict) or len(curva) == 0:
        raise ValueError(f"{nome}: dict non vuoto atteso")
    punti = []
    for k, v in curva.items():
        mh486_mese(k, f"{nome}[{k}]")
        p = mh486_num(v, f"{nome}[{k}]")
        if p < 0:
            raise ValueError(f"{nome}[{k}]: prezzo non negativo")
        punti.append((mh486_mese_ord(k), p))
    punti.sort()
    return punti


def mh486_prezzo(punti, ord_f):
    """Prezzo forward al tenor ord_f (float) per interpolazione lineare.

    punti: lista [(ordinale, prezzo)] ordinata (vedi mh486_curva).
    Fuori dalla curva: clamp al punto estremo (niente estrapolazione).
    """
    if not isinstance(punti, (list, tuple)) or len(punti) == 0:
        raise ValueError("punti: lista non vuota")
    t = mh486_num(ord_f, "tenor")
    if t <= punti[0][0]:
        return float(punti[0][1])
    if t >= punti[-1][0]:
        return float(punti[-1][1])
    for (o0, p0), (o1, p1) in zip(punti, punti[1:]):
        if o0 <= t <= o1:
            if o1 == o0:
                return float(p0)
            frac = (t - o0) / (o1 - o0)
            return float(p0 + frac * (p1 - p0))
    return float(punti[-1][1])  # non raggiungibile, sicurezza


def mh486_posizione(p, k):
    """Valida un dict posizione forward con i due prezzi di valutazione.

    Chiavi: commodity (str), scadenza ("YYYY-MM"), volume_mwh (> 0),
    segno (+1.0 long / -1.0 short), f_fix (EUR/MWh >= 0),
    f_old (EUR/MWh >= 0, prezzo alla data vecchia),
    f_new (EUR/MWh >= 0, prezzo alla data nuova).
    """
    if not isinstance(p, dict):
        raise ValueError(f"posizioni[{k}]: dict atteso")
    try:
        comm = str(p["commodity"])
        scad = mh486_mese(p["scadenza"], f"posizioni[{k}].scadenza")
        vol = mh486_num(p["volume_mwh"], f"posizioni[{k}].volume_mwh")
        segno = mh486_segno(p["segno"], f"posizioni[{k}].segno")
        ff = mh486_num(p["f_fix"], f"posizioni[{k}].f_fix")
        fo = mh486_num(p["f_old"], f"posizioni[{k}].f_old")
        fn = mh486_num(p["f_new"], f"posizioni[{k}].f_new")
    except KeyError as e:
        raise ValueError(f"posizioni[{k}]: chiave mancante {e}")
    if vol <= 0:
        raise ValueError(f"posizioni[{k}].volume_mwh: > 0")
    for val, nome in ((ff, "f_fix"), (fo, "f_old"), (fn, "f_new")):
        if val < 0:
            raise ValueError(f"posizioni[{k}].{nome}: non negativo")
    return {"commodity": comm, "scadenza": scad, "volume_mwh": vol,
            "segno": segno, "f_fix": ff, "f_old": fo, "f_new": fn}


def mh486_tau(data_new, scadenza):
    """Tenor alla scadenza: (giorni, anni) dalla data nuova (YYYY-MM-DD)
    alla fine del mese di consegna (YYYY-MM)."""
    import math
    dv = mh486_data(data_new, "data_nuova")
    mh486_mese(scadenza, "scadenza")
    fine = mh486_fine_mese(int(scadenza[0:4]), int(scadenza[5:7]))
    giorni = (fine - dv).days
    if giorni < 0:
        raise ValueError("scadenza: fine mese di consegna prima della "
                         "data di valutazione")
    return giorni, giorni / 365.25


def mh486_riga(commodity, scadenza, volume_mwh, segno, f_fix, f_old, f_new,
               curva, data_new, giorni, r_old, r_new):
    """Attribuzione del ΔMtM di una posizione forward tra due date.

    theta  = segno*(f(tau1)-f(tau0))*volume  (roll-down, curva a t1)
    delta  = segno*(f_new-f(tau1))*volume*df_new  (prezzo oltre il roll)
    rho    = segno*(f_new-f_fix)*volume*(df_new-df_old_a_tau1)  (solo tasso)
    residuo = ΔMtM - theta - delta - rho  (interazioni + forma curva).
    Ritorna il dict della riga con tutti i componenti.
    """
    import math
    p = mh486_posizione({"commodity": commodity, "scadenza": scadenza,
                         "volume_mwh": volume_mwh, "segno": segno,
                         "f_fix": f_fix, "f_old": f_old, "f_new": f_new},
                        "linea")
    g = mh486_num(giorni, "giorni")
    if g <= 0:
        raise ValueError("giorni: > 0")
    ro = mh486_tasso(r_old, "tasso_vecchio")
    rn = mh486_tasso(r_new, "tasso_nuovo")
    mh486_data(data_new, "data_nuova")
    punti = mh486_curva(curva, "curva")
    tau_g, tau1 = mh486_tau(data_new, p["scadenza"])
    tau0 = tau1 + g / 365.25
    f_tau0 = mh486_prezzo(punti, float(mh486_mese_ord(p["scadenza"])) -
                          g / 30.4375)
    f_tau1 = mh486_prezzo(punti, float(mh486_mese_ord(p["scadenza"])))
    df_old_tau0 = math.exp(-ro * tau0)
    df_old_tau1 = math.exp(-ro * tau1)
    df_new = math.exp(-rn * tau1)
    mtm_old = p["segno"] * (p["f_old"] - p["f_fix"]) * p["volume_mwh"] * df_old_tau0
    mtm_new = p["segno"] * (p["f_new"] - p["f_fix"]) * p["volume_mwh"] * df_new
    theta = p["segno"] * (f_tau1 - f_tau0) * p["volume_mwh"]
    delta = p["segno"] * (p["f_new"] - f_tau1) * p["volume_mwh"] * df_new
    rho = p["segno"] * (p["f_new"] - p["f_fix"]) * p["volume_mwh"] * (df_new - df_old_tau1)
    d_mtm = mtm_new - mtm_old
    spiegato = theta + delta + rho
    residuo = d_mtm - spiegato
    return {"commodity": p["commodity"], "scadenza": p["scadenza"],
            "volume_mwh": p["volume_mwh"], "segno": p["segno"],
            "f_fix": p["f_fix"], "f_old": p["f_old"], "f_new": p["f_new"],
            "f_roll_old": f_tau0, "f_roll_new": f_tau1,
            "tau1_anni": tau1, "df_old": df_old_tau0, "df_new": df_new,
            "mtm_old": mtm_old, "mtm_new": mtm_new, "delta_mtm": d_mtm,
            "theta": theta, "delta": delta, "rho": rho,
            "spiegato": spiegato, "residuo": residuo}


def mh486_portafoglio(posizioni, curve, data_new, giorni, r_old, r_new):
    """Attribuzione del ΔMtM del portafoglio forward.

    posizioni: lista non vuota di dict (vedi mh486_posizione).
    curve: {commodity: {"YYYY-MM": prezzo}} (curva a t1); ogni commodity
    delle posizioni deve avere la sua curva.
    Ritorna {"righe", "delta_mtm_tot", "theta_tot", "delta_tot", "rho_tot",
    "spiegato_tot", "residuo_tot", "per_commodity", "n_posizioni"}.
    """
    if not isinstance(posizioni, (list, tuple)) or len(posizioni) == 0:
        raise ValueError("posizioni: lista non vuota")
    if not isinstance(curve, dict):
        raise ValueError("curve: dict {commodity: curva}")
    righe = []
    for k, p in enumerate(posizioni):
        pv = mh486_posizione(p, k)
        if pv["commodity"] not in curve:
            raise ValueError(
                f"posizioni[{k}]: manca la curva di '{pv['commodity']}'")
        righe.append(mh486_riga(
            pv["commodity"], pv["scadenza"], pv["volume_mwh"], pv["segno"],
            pv["f_fix"], pv["f_old"], pv["f_new"], curve[pv["commodity"]],
            data_new, giorni, r_old, r_new))
    per_comm = {}
    for r in righe:
        b = per_comm.setdefault(r["commodity"],
                                {"delta_mtm": 0.0, "theta": 0.0, "delta": 0.0,
                                 "rho": 0.0, "residuo": 0.0, "n": 0})
        for c in ("delta_mtm", "theta", "delta", "rho", "residuo"):
            b[c] += r[c]
        b["n"] += 1
    return {"righe": righe,
            "delta_mtm_tot": sum(r["delta_mtm"] for r in righe),
            "theta_tot": sum(r["theta"] for r in righe),
            "delta_tot": sum(r["delta"] for r in righe),
            "rho_tot": sum(r["rho"] for r in righe),
            "spiegato_tot": sum(r["spiegato"] for r in righe),
            "residuo_tot": sum(r["residuo"] for r in righe),
            "per_commodity": per_comm, "n_posizioni": len(righe)}


def mh486_verdetto(posizioni, curve, data_new, giorni, r_old, r_new):
    """Giudizio sintetico: il ΔMtM realizzato è spiegato dalle greche?

    SPIEGATO: |residuo| <= max(100 EUR, 5% di |ΔMtM|);
    QUASI SPIEGATO: <= 20%; altrimenti DA INDAGARE.
    spiegato_pct = spiegato / ΔMtM (None se ΔMtM == 0).
    Ritorna {"verdetto", "delta_mtm_tot", "spiegato_tot", "residuo_tot",
    "spiegato_pct", "giorni"}.
    """
    agg = mh486_portafoglio(posizioni, curve, data_new, giorni, r_old, r_new)
    d = agg["delta_mtm_tot"]
    res = agg["residuo_tot"]
    sp = agg["spiegato_tot"]
    g = mh486_num(giorni, "giorni")
    if d == 0.0 and res == 0.0:
        return {"verdetto": "NESSUN MOVIMENTO", "delta_mtm_tot": 0.0,
                "spiegato_tot": 0.0, "residuo_tot": 0.0,
                "spiegato_pct": None, "giorni": float(g)}
    pct = sp / d if d != 0.0 else None
    soglia = max(100.0, 0.05 * abs(d))
    if abs(res) <= soglia:
        verd = "SPIEGATO"
    elif abs(res) <= 0.20 * abs(d):
        verd = "QUASI SPIEGATO"
    else:
        verd = "DA INDAGARE"
    return {"verdetto": verd, "delta_mtm_tot": d, "spiegato_tot": sp,
            "residuo_tot": res, "spiegato_pct": pct, "giorni": float(g)}

# ===========================================================================
# W485 (15/10/2026) - tab485 "🏦 Rho del portafoglio forward: il MtM sotto il tasso d'interesse"
# Dopo la theta (tab484, roll-down a prezzi fermi), la seconda gamba del
# tempo: il MtM va scontato al tasso d'interesse. rho = dMtM/dr misura
# quanto "costa" (o rende) il funding del portafoglio forward.
#   mtm   = segno * (f_now - f_fix) * volume * exp(-r * tau)
#   rho   = d(mtm)/dr = -tau * mtm            (per shift di 1.00 = 100%)
#   rho_bp = rho * 0.0001                     (per 1 punto base)
# tau = giorni dalla data di valutazione a fine mese di consegna / 365.25.
# Un MtM positivo lontano nel tempo "vale meno" oggi e si erode se i tassi
# salgono; il funding annuo stimato e' mtm * r (carry del MtM).
# ===========================================================================


def mh485_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh485_segno(s, nome):
    if isinstance(s, str):
        sl = s.strip().lower()
        if sl == "long":
            return 1.0
        if sl == "short":
            return -1.0
        raise ValueError(f"{nome}: 'long'/'short' o +1.0/-1.0")
    v = mh485_num(s, nome)
    if v not in (1.0, -1.0):
        raise ValueError(f"{nome}: +1.0 (long) o -1.0 (short)")
    return v


def mh485_mese(m, nome):
    import re
    if not isinstance(m, str) \
            or not re.fullmatch(r"\d{4}-(0[1-9]|1[0-2])", m):
        raise ValueError(f"{nome}: formato YYYY-MM atteso (es. 2026-11)")
    return m


def mh485_data(d, nome):
    import datetime
    import re
    if not isinstance(d, str) \
            or not re.fullmatch(r"\d{4}-(0[1-9]|1[0-2])-(0[1-9]|[12]\d|3[01])", d):
        raise ValueError(f"{nome}: formato YYYY-MM-DD atteso (es. 2026-10-15)")
    try:
        return datetime.date(int(d[0:4]), int(d[5:7]), int(d[8:10]))
    except ValueError:
        raise ValueError(f"{nome}: data non valida ({d})")


def mh485_fine_mese(anno, mese):
    """Ultimo giorno del mese (anno, mese) come datetime.date."""
    import calendar
    import datetime
    a = int(anno)
    m = int(mese)
    if not 1 <= m <= 12:
        raise ValueError("mese: 1..12")
    return datetime.date(a, m, calendar.monthrange(a, m)[1])


def mh485_tasso(r, nome):
    v = mh485_num(r, nome)
    if not -0.10 <= v <= 0.50:
        raise ValueError(f"{nome}: tra -10% e +50% (decimale)")
    return v


def mh485_posizione(p, k):
    """Valida un dict posizione forward.

    Chiavi: commodity (str), scadenza ("YYYY-MM"), volume_mwh (> 0),
    segno (+1.0 long / -1.0 short, o "long"/"short"), f_fix (EUR/MWh >= 0),
    f_now (EUR/MWh >= 0).
    """
    if not isinstance(p, dict):
        raise ValueError(f"posizioni[{k}]: dict atteso")
    try:
        comm = str(p["commodity"])
        scad = mh485_mese(p["scadenza"], f"posizioni[{k}].scadenza")
        vol = mh485_num(p["volume_mwh"], f"posizioni[{k}].volume_mwh")
        segno = mh485_segno(p["segno"], f"posizioni[{k}].segno")
        ff = mh485_num(p["f_fix"], f"posizioni[{k}].f_fix")
        fn = mh485_num(p["f_now"], f"posizioni[{k}].f_now")
    except KeyError as e:
        raise ValueError(f"posizioni[{k}]: chiave mancante {e}")
    if vol <= 0:
        raise ValueError(f"posizioni[{k}].volume_mwh: > 0")
    if ff < 0:
        raise ValueError(f"posizioni[{k}].f_fix: non negativo")
    if fn < 0:
        raise ValueError(f"posizioni[{k}].f_now: non negativo")
    return {"commodity": comm, "scadenza": scad, "volume_mwh": vol,
            "segno": segno, "f_fix": ff, "f_now": fn}


def mh485_tau(data_val, scadenza):
    """Tenor alla scadenza: (giorni, anni) dalla data di valutazione
    (YYYY-MM-DD) alla fine del mese di consegna (YYYY-MM)."""
    dv = mh485_data(data_val, "data_valutazione")
    mh485_mese(scadenza, "scadenza")
    fine = mh485_fine_mese(int(scadenza[0:4]), int(scadenza[5:7]))
    giorni = (fine - dv).days
    if giorni < 0:
        raise ValueError("scadenza: fine mese di consegna prima della "
                         "data di valutazione")
    return giorni, giorni / 365.25


def mh485_df(tau_anni, r):
    """Fattore di sconto continuo exp(-r*tau)."""
    import math
    t = mh485_num(tau_anni, "tau_anni")
    rr = mh485_tasso(r, "tasso")
    if t < 0:
        raise ValueError("tau_anni: non negativo")
    return math.exp(-rr * t)


def mh485_rho_linea(commodity, scadenza, volume_mwh, segno, f_fix, f_now,
                    data_val, r):
    """MtM scontato e rho di una posizione forward.

    mtm = segno*(f_now - f_fix)*volume*exp(-r*tau); rho = -tau*mtm;
    rho_bp = rho*0.0001; funding_annuo = mtm*r (carry annuo del MtM).
    Ritorna il dict della riga.
    """
    p = mh485_posizione({"commodity": commodity, "scadenza": scadenza,
                         "volume_mwh": volume_mwh, "segno": segno,
                         "f_fix": f_fix, "f_now": f_now}, "linea")
    rr = mh485_tasso(r, "tasso")
    giorni, tau = mh485_tau(data_val, p["scadenza"])
    df = mh485_df(tau, rr)
    mtm = p["segno"] * (p["f_now"] - p["f_fix"]) * p["volume_mwh"] * df
    rho = -tau * mtm
    return {"commodity": p["commodity"], "scadenza": p["scadenza"],
            "volume_mwh": p["volume_mwh"], "segno": p["segno"],
            "f_fix": p["f_fix"], "f_now": p["f_now"],
            "tau_giorni": giorni, "tau_anni": tau, "df": df,
            "mtm": mtm, "rho": rho, "rho_bp": rho * 0.0001,
            "funding_annuo": mtm * rr}


def mh485_rho_portafoglio(posizioni, data_val, r):
    """MtM scontato e rho del portafoglio forward.

    posizioni: lista non vuota di dict (vedi mh485_posizione).
    Ritorna {"righe", "mtm_tot", "rho_tot", "rho_bp_tot", "funding_tot",
    "per_commodity", "per_scadenza", "n_posizioni"}.
    """
    if not isinstance(posizioni, (list, tuple)) or len(posizioni) == 0:
        raise ValueError("posizioni: lista non vuota")
    rr = mh485_tasso(r, "tasso")
    righe = []
    for k, p in enumerate(posizioni):
        pv = mh485_posizione(p, k)
        righe.append(mh485_rho_linea(
            pv["commodity"], pv["scadenza"], pv["volume_mwh"], pv["segno"],
            pv["f_fix"], pv["f_now"], data_val, rr))
    per_comm = {}
    per_scad = {}
    for rg in righe:
        for coll, key in ((per_comm, rg["commodity"]),
                          (per_scad, rg["scadenza"])):
            b = coll.setdefault(key, {"mtm": 0.0, "rho_bp": 0.0, "n": 0})
            b["mtm"] += rg["mtm"]
            b["rho_bp"] += rg["rho_bp"]
            b["n"] += 1
    return {"righe": righe,
            "mtm_tot": sum(rg["mtm"] for rg in righe),
            "rho_tot": sum(rg["rho"] for rg in righe),
            "rho_bp_tot": sum(rg["rho_bp"] for rg in righe),
            "funding_tot": sum(rg["funding_annuo"] for rg in righe),
            "per_commodity": per_comm, "per_scadenza": per_scad,
            "n_posizioni": len(righe)}


def mh485_scenario(posizioni, data_val, r, shifts_bp):
    """MtM scontato del portafoglio sotto shock del tasso.

    shifts_bp: lista non vuota di interi (punti base), es. [-200, 100].
    Ritorna {"base_r", "mtm_base", "rho_bp_tot",
    "scenari": [{"shift_bp", "r", "mtm_stress", "delta"}]}.
    """
    if not isinstance(shifts_bp, (list, tuple)) or len(shifts_bp) == 0:
        raise ValueError("shifts_bp: lista non vuota di interi")
    for s in shifts_bp:
        import numbers
        if isinstance(s, bool) or not isinstance(s, numbers.Integral):
            raise ValueError("shifts_bp: interi (punti base)")
    rr = mh485_tasso(r, "tasso")
    base = mh485_rho_portafoglio(posizioni, data_val, rr)
    out = []
    for bp in shifts_bp:
        r2 = rr + int(bp) / 10000.0
        if not -0.10 <= r2 <= 0.50:
            raise ValueError(f"shift {bp} bp: tasso fuori range")
        agg = mh485_rho_portafoglio(posizioni, data_val, r2)
        out.append({"shift_bp": int(bp), "r": r2,
                    "mtm_stress": agg["mtm_tot"],
                    "delta": agg["mtm_tot"] - base["mtm_tot"]})
    return {"base_r": rr, "mtm_base": base["mtm_tot"],
            "rho_bp_tot": base["rho_bp_tot"], "scenari": out}


def mh485_verdetto(posizioni, data_val, r):
    """Giudizio sintetico sulla sensibilita' al tasso del portafoglio.

    La duration implicita del rho (anni) e':
      dur = |rho_tot| / |mtm_tot|   (media dei tau ponderata su |mtm|)
    RHO BREVE TERMINE: dur <= 0.5 anni; RHO MEDIO TERMINE: dur <= 1.5 anni;
    RHO LUNGO TERMINE: oltre. Se mtm e rho sono nulli: NESSUNA ESPOSIZIONE.
    Ritorna {"verdetto", "mtm_tot", "rho_bp_tot", "duration_anni",
    "funding_annuo", "r"}.
    """
    agg = mh485_rho_portafoglio(posizioni, data_val, r)
    rb = agg["rho_bp_tot"]
    mtm = agg["mtm_tot"]
    rho = agg["rho_tot"]
    if mtm == 0.0 and rho == 0.0:
        verd, dur = "NESSUNA ESPOSIZIONE", 0.0
    else:
        dur = abs(rho) / abs(mtm) if mtm != 0.0 else 0.0
        if dur <= 0.5:
            verd = "RHO BREVE TERMINE"
        elif dur <= 1.5:
            verd = "RHO MEDIO TERMINE"
        else:
            verd = "RHO LUNGO TERMINE"
    return {"verdetto": verd, "mtm_tot": mtm, "rho_bp_tot": rb,
            "duration_anni": dur, "funding_annuo": agg["funding_tot"],
            "r": mh485_tasso(r, "tasso")}

# ===========================================================================
# W484 (15/10/2026) - tab484 "⏳ Theta del portafoglio forward: quanto vale il passare del tempo"
# Dopo lo shock di curva (tab483, spostamento dei prezzi), la domanda duale:
# cosa succede se i prezzi NON si muovono ma passa il tempo? La posizione
# "scivola" lungo la curva forward: il prezzo di riferimento passa dal tenor
# tau al tenor tau-Delta. In backwardation il long "rolla verso l'alto"
# (theta positiva), in contango "rolla verso il basso" (theta negativa).
# theta_linea = segno * (f(tau-Delta) - f(tau)) * volume_mwh, con f
# interpolato linearmente sulla curva {"YYYY-MM": prezzo} e clamp agli
# estremi (niente estrapolazione oltre la curva inserita). MtM e theta sono
# calcolati sui prezzi di curva, per coerenza tra loro.
# ===========================================================================


def mh484_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh484_segno(s, nome):
    v = mh484_num(s, nome)
    if v not in (1.0, -1.0):
        raise ValueError(f"{nome}: +1.0 (long) o -1.0 (short)")
    return v


def mh484_mese(m, nome):
    import re
    if not isinstance(m, str) \
            or not re.fullmatch(r"\d{4}-(0[1-9]|1[0-2])", m):
        raise ValueError(f"{nome}: formato YYYY-MM atteso (es. 2026-11)")
    return m


def mh484_mese_ord(m):
    """"2026-11" -> ordinale intero anno*12+mese (per l'aritmetica sui tenor)."""
    mh484_mese(m, "mese")
    a, b = m.split("-")
    return int(a) * 12 + int(b)


def mh484_ord_mese(o):
    """Ordinale intero -> "YYYY-MM". o deve essere un intero >= 1."""
    import numbers
    if isinstance(o, bool) or not isinstance(o, numbers.Integral):
        raise ValueError("ordinale: intero atteso")
    o = int(o)
    if o < 1:
        raise ValueError("ordinale: >= 1")
    y, mm = divmod(o - 1, 12)
    return f"{y:04d}-{mm + 1:02d}"


def mh484_curva(curva, nome):
    """Valida una curva forward {"YYYY-MM": prezzo >= 0}.

    Ritorna la lista ordinata [(ordinale, prezzo)] per l'interpolazione.
    """
    if not isinstance(curva, dict) or len(curva) == 0:
        raise ValueError(f"{nome}: dict non vuoto atteso")
    punti = []
    for k, v in curva.items():
        mh484_mese(k, f"{nome}[{k}]")
        p = mh484_num(v, f"{nome}[{k}]")
        if p < 0:
            raise ValueError(f"{nome}[{k}]: prezzo non negativo")
        punti.append((mh484_mese_ord(k), p))
    punti.sort()
    return punti


def mh484_posizione(p, k):
    """Valida un dict posizione forward.

    Chiavi: commodity (str), scadenza ("YYYY-MM"), volume_mwh (> 0),
    segno (+1.0 long / -1.0 short), f_fix (EUR/MWh >= 0),
    f_now (EUR/MWh >= 0).
    """
    if not isinstance(p, dict):
        raise ValueError(f"posizioni[{k}]: dict atteso")
    try:
        comm = str(p["commodity"])
        scad = mh484_mese(p["scadenza"], f"posizioni[{k}].scadenza")
        vol = mh484_num(p["volume_mwh"], f"posizioni[{k}].volume_mwh")
        segno = mh484_segno(p["segno"], f"posizioni[{k}].segno")
        ff = mh484_num(p["f_fix"], f"posizioni[{k}].f_fix")
        fn = mh484_num(p["f_now"], f"posizioni[{k}].f_now")
    except KeyError as e:
        raise ValueError(f"posizioni[{k}]: chiave mancante {e}")
    if vol <= 0:
        raise ValueError(f"posizioni[{k}].volume_mwh: > 0")
    if ff < 0:
        raise ValueError(f"posizioni[{k}].f_fix: non negativo")
    if fn < 0:
        raise ValueError(f"posizioni[{k}].f_now: non negativo")
    return {"commodity": comm, "scadenza": scad, "volume_mwh": vol,
            "segno": segno, "f_fix": ff, "f_now": fn}


def mh484_prezzo(punti, ord_f):
    """Prezzo forward al tenor ord_f (float) per interpolazione lineare.

    punti: lista [(ordinale, prezzo)] ordinata (vedi mh484_curva).
    Fuori dalla curva: clamp al punto estremo (niente estrapolazione).
    """
    if not isinstance(punti, (list, tuple)) or len(punti) == 0:
        raise ValueError("punti: lista non vuota")
    t = mh484_num(ord_f, "tenor")
    if t <= punti[0][0]:
        return float(punti[0][1])
    if t >= punti[-1][0]:
        return float(punti[-1][1])
    for (o0, p0), (o1, p1) in zip(punti, punti[1:]):
        if o0 <= t <= o1:
            if o1 == o0:
                return float(p0)
            frac = (t - o0) / (o1 - o0)
            return float(p0 + frac * (p1 - p0))
    return float(punti[-1][1])  # non raggiungibile, sicurezza


def mh484_theta_linea(commodity, scadenza, volume_mwh, segno, f_fix, f_now,
                      curva, giorni):
    """Theta di roll-down di una posizione forward.

    La scadenza "invecchia" di `giorni`: il prezzo di riferimento scivola
    dal tenor tau (curva oggi) al tenor tau - giorni/30.4375.
    theta = segno * (f_futura - f_oggi) * volume_mwh.
    MtM e theta sono calcolati sui prezzi di curva a tau (coerenti tra
    loro); f_now e' validato come campo della posizione ma il prezzo usato
    e' quello di curva.
    Ritorna dict con i campi della riga.
    """
    p = mh484_posizione({"commodity": commodity, "scadenza": scadenza,
                         "volume_mwh": volume_mwh, "segno": segno,
                         "f_fix": f_fix, "f_now": f_now}, "linea")
    g = mh484_num(giorni, "giorni")
    if g <= 0:
        raise ValueError("giorni: > 0")
    punti = mh484_curva(curva, "curva")
    tau0 = float(mh484_mese_ord(p["scadenza"]))
    tau1 = tau0 - g / 30.4375
    f0 = mh484_prezzo(punti, tau0)
    f1 = mh484_prezzo(punti, tau1)
    theta = p["segno"] * (f1 - f0) * p["volume_mwh"]
    mtm = p["segno"] * (f0 - p["f_fix"]) * p["volume_mwh"]
    return {"commodity": p["commodity"], "scadenza": p["scadenza"],
            "volume_mwh": p["volume_mwh"], "segno": p["segno"],
            "f_fix": p["f_fix"], "f_oggi": f0, "f_futura": f1,
            "mtm": mtm, "theta": theta, "theta_giorno": theta / g}


def mh484_theta_portafoglio(posizioni, curve, giorni):
    """Theta di roll-down del portafoglio forward.

    posizioni: lista non vuota di dict (vedi mh484_posizione).
    curve: {commodity: {"YYYY-MM": prezzo}}; ogni commodity delle
    posizioni deve avere la sua curva.
    Ritorna {"righe", "theta_tot", "mtm_tot", "theta_giorno_tot",
    "per_commodity", "per_scadenza", "n_posizioni"}.
    """
    if not isinstance(posizioni, (list, tuple)) or len(posizioni) == 0:
        raise ValueError("posizioni: lista non vuota")
    if not isinstance(curve, dict):
        raise ValueError("curve: dict {commodity: curva}")
    righe = []
    for k, p in enumerate(posizioni):
        pv = mh484_posizione(p, k)
        if pv["commodity"] not in curve:
            raise ValueError(
                f"posizioni[{k}]: manca la curva di '{pv['commodity']}'")
        r = mh484_theta_linea(pv["commodity"], pv["scadenza"],
                              pv["volume_mwh"], pv["segno"], pv["f_fix"],
                              pv["f_now"], curve[pv["commodity"]], giorni)
        righe.append(r)
    theta_tot = sum(r["theta"] for r in righe)
    mtm_tot = sum(r["mtm"] for r in righe)
    tg_tot = sum(r["theta_giorno"] for r in righe)
    per_comm = {}
    per_scad = {}
    for r in righe:
        for coll, key in ((per_comm, r["commodity"]),
                          (per_scad, r["scadenza"])):
            b = coll.setdefault(key, {"theta": 0.0, "mtm": 0.0, "n": 0})
            b["theta"] += r["theta"]
            b["mtm"] += r["mtm"]
            b["n"] += 1
    return {"righe": righe, "theta_tot": theta_tot, "mtm_tot": mtm_tot,
            "theta_giorno_tot": tg_tot, "per_commodity": per_comm,
            "per_scadenza": per_scad, "n_posizioni": len(righe)}


def mh484_roll_path(commodity, scadenza, volume_mwh, segno, f_fix, f_now,
                    curva, giorni):
    """Sentiero giornaliero del prezzo di riferimento e del MtM.

    Ritorna la lista [{"giorno", "prezzo", "mtm"}] per g = 0..giorni
    (interi): utile per il grafico del roll-down nel tempo.
    """
    p = mh484_posizione({"commodity": commodity, "scadenza": scadenza,
                         "volume_mwh": volume_mwh, "segno": segno,
                         "f_fix": f_fix, "f_now": f_now}, "linea")
    g = mh484_num(giorni, "giorni")
    if g <= 0:
        raise ValueError("giorni: > 0")
    if abs(g - round(g)) > 1e-9:
        raise ValueError("giorni: intero atteso per il sentiero")
    punti = mh484_curva(curva, "curva")
    tau0 = float(mh484_mese_ord(p["scadenza"]))
    out = []
    for d in range(int(round(g)) + 1):
        tau = tau0 - d / 30.4375
        f = mh484_prezzo(punti, tau)
        out.append({"giorno": d, "prezzo": f,
                    "mtm": p["segno"] * (f - p["f_fix"]) * p["volume_mwh"]})
    return out


def mh484_verdetto(posizioni, curve, giorni):
    """Giudizio sintetico sulla theta del portafoglio.

    THETA POSITIVA: il tempo lavora a favore (>= max(100 EUR,
    0.5% di |MtM|)); THETA NEGATIVA: il tempo costa; NEUTRA: altrimenti.
    roll_yield_annuo = theta annualizzata / capitale impiegato
    (somma di volume * f_oggi).
    Ritorna {"verdetto", "theta_tot", "mtm_tot", "theta_giorno",
    "roll_yield_annuo", "giorni"}.
    """
    agg = mh484_theta_portafoglio(posizioni, curve, giorni)
    th = agg["theta_tot"]
    mtm = agg["mtm_tot"]
    g = mh484_num(giorni, "giorni")
    soglia = max(100.0, 0.005 * abs(mtm))
    if th > soglia:
        verd = "THETA POSITIVA"
    elif th < -soglia:
        verd = "THETA NEGATIVA"
    else:
        verd = "NEUTRA"
    cap = sum(r["volume_mwh"] * r["f_oggi"] for r in agg["righe"])
    ry = (th / g * 365.0 / cap) if cap > 0 else 0.0
    return {"verdetto": verd, "theta_tot": th, "mtm_tot": mtm,
            "theta_giorno": agg["theta_giorno_tot"],
            "roll_yield_annuo": ry, "giorni": float(g)}

# ===========================================================================
# W483 (15/10/2026) - tab483 "🧪💥 Shock di curva: P&L del portafoglio sotto scenari di prezzo"
# Dopo la ladder temporale (tab482), la domanda operativa: cosa succede al P&L
# se la curva si sposta? Lo shock per bucket vale
#   delta_i = DV01_i * shift_bucket_i   (lineare, coerente col DV01 di tab481)
#   mtm_stress_i = mtm_i + delta_i
# Scenari predefiniti: parallelo +/-10, ripida, inversione, stress gas +25,
# piu' shift personalizzati per bucket. Il verdetto misura la resilienza:
#   ratio = |delta_tot| / max(|mtm_tot|, somma |dv01|)  (fallback se mtm = 0)
# RESILIENTE <= 5%, DA GESTIRE <= 25%, CRITICO oltre.
# ===========================================================================

def _mh483_buckets():
    """Bucket temporali di tab482, condivisi con tab483."""
    return ["≤30 gg", "31–90 gg", "91–180 gg", "181–365 gg", ">365 gg"]


def mh483_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh483_segno(s):
    if isinstance(s, str):
        sl = s.strip().lower()
        if sl == "long":
            return 1.0
        if sl == "short":
            return -1.0
    v = mh483_num(s, "segno")
    if v == 1.0:
        return 1.0
    if v == -1.0:
        return -1.0
    raise ValueError("segno: long/short (oppure +1/-1)")


def mh483_mese(scadenza):
    import re
    m = re.fullmatch(r"(\d{4})-(0[1-9]|1[0-2])", str(scadenza).strip())
    if not m:
        raise ValueError("scadenza: formato YYYY-MM (mese 01-12)")
    return int(m.group(1)), int(m.group(2))


def mh483_fine_mese(anno, mese):
    import calendar
    import datetime
    if not (1 <= mese <= 12):
        raise ValueError("mese: 1-12")
    return datetime.date(anno, mese, calendar.monthrange(anno, mese)[1])


def mh483_giorni(data_val, scadenza):
    import datetime
    if not isinstance(data_val, datetime.date):
        raise ValueError("data_val: data")
    a, m = mh483_mese(scadenza)
    g = (mh483_fine_mese(a, m) - data_val).days
    if g < 0:
        raise ValueError("scadenza: gia' trascorsa rispetto alla data di valutazione")
    return g


def mh483_bucket(giorni):
    g = mh483_num(giorni, "giorni")
    if g < 0:
        raise ValueError("giorni: non negativi")
    if g <= 30:
        return "≤30 gg"
    if g <= 90:
        return "31–90 gg"
    if g <= 180:
        return "91–180 gg"
    if g <= 365:
        return "181–365 gg"
    return ">365 gg"


def mh483_posizione(commodity, scadenza, volume_mwh, segno, f_fix, f_now):
    """Una riga di portafoglio: MtM e DV01 lineari come in tab481."""
    vol = mh483_num(volume_mwh, "volume_mwh")
    sg = mh483_segno(segno)
    ff = mh483_num(f_fix, "f_fix")
    fn = mh483_num(f_now, "f_now")
    if vol < 0:
        raise ValueError("volume_mwh: non negativo")
    if ff < 0 or fn < 0:
        raise ValueError("prezzi forward: non negativi")
    mh483_mese(scadenza)
    return {"commodity": str(commodity), "scadenza": str(scadenza).strip(),
            "volume_mwh": vol, "segno": sg, "f_fix": ff, "f_now": fn,
            "mtm": sg * vol * (fn - ff), "dv01": sg * vol}


def mh483_preset_shock(preset):
    """Shift di prezzo (€/MWh) per bucket temporale per gli scenari standard."""
    presets = {
        "📐 Parallelo +10 €/MWh": {b: 10.0 for b in _mh483_buckets()},
        "📐 Parallelo −10 €/MWh": {b: -10.0 for b in _mh483_buckets()},
        "📈 Ripida (front +10, back −10)": {
            "≤30 gg": 10.0, "31–90 gg": 5.0, "91–180 gg": 0.0,
            "181–365 gg": -5.0, ">365 gg": -10.0},
        "📉 Inversione (front −10, back +10)": {
            "≤30 gg": -10.0, "31–90 gg": -5.0, "91–180 gg": 0.0,
            "181–365 gg": 5.0, ">365 gg": 10.0},
        "🔥 Stress gas +25 €/MWh": {b: 25.0 for b in _mh483_buckets()},
    }
    if preset not in presets:
        raise ValueError(f"preset: uno di {sorted(presets)}")
    return dict(presets[preset])


def mh483_scenario(linee, data_val, shifts):
    """Applica gli shift per bucket alle linee: delta = DV01 * shift.

    linee: lista di dict {commodity, scadenza, volume_mwh, segno, f_fix, f_now}.
    shifts: dict {bucket: shift_€/MWh} (bucket mancanti -> 0).
    Ritorna righe con bucket/shift/delta/mtm_stress, aggregati per bucket
    e totali (mtm_tot, delta_tot, mtm_stress_tot, dv01_tot).
    """
    if not isinstance(linee, (list, tuple)) or len(linee) == 0:
        raise ValueError("linee: lista non vuota")
    if not isinstance(shifts, dict):
        raise ValueError("shifts: dict bucket -> shift (€/MWh)")
    sh = {b: mh483_num(shifts.get(b, 0.0), f"shifts[{b}]")
          for b in _mh483_buckets()}
    righe = []
    for k, ln in enumerate(linee):
        try:
            p = mh483_posizione(ln["commodity"], ln["scadenza"],
                                ln["volume_mwh"], ln["segno"],
                                ln["f_fix"], ln["f_now"])
        except (KeyError, TypeError):
            raise ValueError(
                f"linee[{k}]: dict con commodity/scadenze/volume_mwh/segno/f_fix/f_now")
        g = mh483_giorni(data_val, p["scadenza"])
        b = mh483_bucket(g)
        delta = p["dv01"] * sh[b]
        righe.append({**p, "giorni": g, "bucket": b, "shift": sh[b],
                      "delta": delta, "mtm_stress": p["mtm"] + delta})
    per_bucket = {b: {"mtm": 0.0, "dv01": 0.0, "delta": 0.0,
                      "mtm_stress": 0.0, "n": 0} for b in _mh483_buckets()}
    for r in righe:
        pb = per_bucket[r["bucket"]]
        pb["mtm"] += r["mtm"]
        pb["dv01"] += r["dv01"]
        pb["delta"] += r["delta"]
        pb["mtm_stress"] += r["mtm_stress"]
        pb["n"] += 1
    return {"righe": righe, "per_bucket": per_bucket,
            "mtm_tot": sum(r["mtm"] for r in righe),
            "delta_tot": sum(r["delta"] for r in righe),
            "mtm_stress_tot": sum(r["mtm_stress"] for r in righe),
            "dv01_tot": sum(r["dv01"] for r in righe)}


def mh483_verdetto(delta_tot, per_bucket, mtm_tot, dv01_tot=None,
                   soglie=(0.05, 0.25)):
    """Resilienza del portafoglio allo shock: RESILIENTE / DA GESTIRE / CRITICO.

    ratio = |delta_tot| / base; base = |mtm_tot|, oppure somma |dv01| se
    mtm_tot e' zero. Riporta il bucket col |delta| peggiore.
    """
    d = mh483_num(delta_tot, "delta_tot")
    m = mh483_num(mtm_tot, "mtm_tot")
    base = abs(m)
    if base == 0.0:
        if dv01_tot is None:
            try:
                dv01_tot = sum(abs(pb["dv01"]) for pb in per_bucket.values())
            except (TypeError, KeyError, AttributeError):
                raise ValueError("per_bucket: dict di bucket con dv01")
        base = mh483_num(dv01_tot, "dv01_tot")
    if base == 0.0:
        raise ValueError("portafoglio vuoto: MtM e DV01 nulli")
    if not isinstance(per_bucket, dict) or not per_bucket:
        raise ValueError("per_bucket: dict non vuoto")
    worst = max(per_bucket.items(),
                key=lambda kv: abs(kv[1]["delta"]))
    ratio = abs(d) / base
    if ratio <= soglie[0]:
        verd = "RESILIENTE"
    elif ratio <= soglie[1]:
        verd = "DA GESTIRE"
    else:
        verd = "CRITICO"
    return {"verdetto": verd, "ratio": ratio, "base": base,
            "bucket_peggiore": worst[0], "delta_peggiore": worst[1]["delta"]}

def mh479_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh479_margine_linea(qta_mwh, im_eur_mwh):
    """Margine iniziale di una linea di prodotto: qta x IM unitario."""
    q = mh479_num(qta_mwh, "qta_mwh")
    im = mh479_num(im_eur_mwh, "im_eur_mwh")
    if q < 0:
        raise ValueError("qta_mwh: non negativa")
    if im < 0:
        raise ValueError("im_eur_mwh: non negativo")
    return q * im


def mh479_margine_totale(linee):
    """Aggregazione del margine iniziale su N linee.

    linee: lista di dict {"nome": str, "qta_mwh": n, "im_eur_mwh": n}.
    Ritorna {"totale", "righe" (con "margine" e "quota"), "n_linee"}.
    Linee a quantita' zero restano in tabella con quota 0.
    """
    if not isinstance(linee, (list, tuple)) or len(linee) == 0:
        raise ValueError("linee: lista non vuota")
    righe = []
    for k, ln in enumerate(linee):
        try:
            nome = str(ln["nome"])
            q = mh479_num(ln["qta_mwh"], f"linee[{k}].qta_mwh")
            im = mh479_num(ln["im_eur_mwh"], f"linee[{k}].im_eur_mwh")
        except (KeyError, TypeError):
            raise ValueError(f"linee[{k}]: dict con nome/qta_mwh/im_eur_mwh")
        if q < 0:
            raise ValueError(f"linee[{k}].qta_mwh: non negativa")
        if im < 0:
            raise ValueError(f"linee[{k}].im_eur_mwh: non negativo")
        righe.append({"nome": nome, "qta_mwh": q, "im_eur_mwh": im,
                      "margine": q * im})
    tot = sum(r["margine"] for r in righe)
    for r in righe:
        r["quota"] = (r["margine"] / tot) if tot > 0 else 0.0
    return {"totale": tot, "righe": righe, "n_linee": len(righe)}


def mh479_nozionale(linee, prezzi_eur_mwh):
    """Nozionale del portafoglio: Σ qta x prezzo. Liste stessa lunghezza."""
    _q = [mh479_num(v, f"qta[{k}]") for k, v in enumerate(list(linee))]
    _p = [mh479_num(v, f"prezzi[{k}]") for k, v in enumerate(list(prezzi_eur_mwh))]
    if len(_q) != len(_p):
        raise ValueError("linee/prezzi: stessa lunghezza")
    for k in range(len(_q)):
        if _q[k] < 0:
            raise ValueError(f"qta[{k}]: non negativa")
        if _p[k] < 0:
            raise ValueError(f"prezzi[{k}]: non negativo")
    return sum(q * p for q, p in zip(_q, _p))


def mh479_costo_funding(margine_eur, tasso_pct, giorni):
    """Costo opportunita' del margine fermo al clearing.

    margine x (tasso%/100) x giorni/365 (base ACT/365).
    """
    m = mh479_num(margine_eur, "margine_eur")
    r = mh479_num(tasso_pct, "tasso_pct")
    g = mh479_num(giorni, "giorni")
    if m < 0:
        raise ValueError("margine_eur: non negativo")
    if r < 0:
        raise ValueError("tasso_pct: non negativo")
    if g < 0:
        raise ValueError("giorni: non negativo")
    return m * (r / 100.0) * (g / 365.0)


def mh479_costo_bps(costo_eur, notionale_eur):
    """Costo del funding in bps sul nozionale."""
    c = mh479_num(costo_eur, "costo_eur")
    n = mh479_num(notionale_eur, "notionale_eur")
    if c < 0:
        raise ValueError("costo_eur: non negativo")
    if n <= 0:
        raise ValueError("notionale_eur: deve essere > 0")
    return c / n * 10000.0


def mh479_sensibilita_tasso(margine_eur, giorni, tasso_base, n=9):
    """Costo funding vs tasso: 9 punti da 0 a 2x tasso_base."""
    m = mh479_num(margine_eur, "margine_eur")
    g = mh479_num(giorni, "giorni")
    b = mh479_num(tasso_base, "tasso_base")
    nn = int(mh479_num(n, "n"))
    if m < 0:
        raise ValueError("margine_eur: non negativo")
    if g < 0:
        raise ValueError("giorni: non negativo")
    if b < 0:
        raise ValueError("tasso_base: non negativo")
    if nn < 2:
        raise ValueError("n: almeno 2")
    tassi = [2.0 * b * i / (nn - 1) for i in range(nn)]
    return [{"tasso_pct": t, "costo_eur": m * (t / 100.0) * (g / 365.0)}
            for t in tassi]


def mh479_sensibilita_giorni(margine_eur, tasso_pct, giorni_base, n=9):
    """Costo funding vs giorni di detenzione: 9 punti da 0.5x a 2x base."""
    m = mh479_num(margine_eur, "margine_eur")
    r = mh479_num(tasso_pct, "tasso_pct")
    b = mh479_num(giorni_base, "giorni_base")
    nn = int(mh479_num(n, "n"))
    if m < 0:
        raise ValueError("margine_eur: non negativo")
    if r < 0:
        raise ValueError("tasso_pct: non negativo")
    if b <= 0:
        raise ValueError("giorni_base: deve essere > 0")
    if nn < 2:
        raise ValueError("n: almeno 2")
    gg = [b * (0.5 + 1.5 * i / (nn - 1)) for i in range(nn)]
    return [{"giorni": g, "costo_eur": m * (r / 100.0) * (g / 365.0)}
            for g in gg]


def mh479_verdetto(costo_bps, soglia_bps=5.0):
    """Giudizio sintetico: TRASCURABILE (<= soglia/2), RILEVANTE
    (<= soglia), CRITICO (> soglia)."""
    c = mh479_num(costo_bps, "costo_bps")
    s = mh479_num(soglia_bps, "soglia_bps")
    if c < 0:
        raise ValueError("costo_bps: non negativo")
    if s <= 0:
        raise ValueError("soglia_bps: deve essere > 0")
    if c <= s / 2.0:
        return "TRASCURABILE"
    if c <= s:
        return "RILEVANTE"
    return "CRITICO"

def mh478_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh478_componenti(p_arrivo, mid, px, qty, spread_bps, gamma):
    """Scomposizione dell'implementation shortfall di un buy program.

    Dopo il COSTO stimato ex-ante (tab475), la CALIBRAZIONE (tab476) e lo
    SCHEDULING ottimo (tab477), qui si chiude il loop a consuntivo: dato
    l'ordine eseguito a bucket, quanto del costo realizzato e' spread,
    quanto impatto (temporaneo + permanente) e quanto timing (drift
    esogeno del mercato mentre esegui).

    Benchmark: prezzo mid all'arrivo dell'ordine p_arrivo (decision price).
    Per il bucket i (i = 0..n-1): qty_i > 0 eseguite a px_i con mid
    contemporaneo mid_i e spread spread_bps_i.

    IS (implementation shortfall, buy: positivo = costo) =
        Σ qty_i * (px_i - p_arrivo)
      = Σ qty_i * (px_i - mid_i)        [trading vs mid contemporaneo]
      + Σ qty_i * (mid_i - p_arrivo)    [drift del mid]

    Il primo termine si spacca in:
      spread    = Σ qty_i * mid_i * s_i/20000   (meta' spread pagato)
      temporaneo = Σ qty_i*(px_i - mid_i) - spread  (impatto temporaneo
                   realizzato vs mid: se fai meglio del mid+spread/2
                   puo' essere negativo)

    Il secondo termine si spacca in:
      permanente = gamma * Σ_i qty_i * (X - x_i), con x_i = rimanente
                   dopo il bucket i: e' il costo dell'impatto permanente
                   accumulato progressivamente (stesso gamma di tab477,
                   EUR/unita'^2; per VWAP vale ~= gamma*X^2/2)
      timing     = Σ qty_i*(mid_i - p_arrivo) - permanente  (drift esogeno:
                   quello che il mercato ha fatto da solo, non il nostro
                   impatto)

    Chiusura: residuo = IS - (spread+temporaneo+permanente+timing) ~= 0
    (solo polvere float). is_bps = IS / (X*p_arrivo) * 10000.

    Note oneste: buy program (per un sell i segni si invertono); mid_i e
    px_i sono input misurati, non stimati; gamma e' un input (da tab477);
    il modello non distingue slippage da latenza vs impatto: tutto cio'
    che non e' spread/impatto modellato finisce nel timing.
    """
    pa = mh478_num(p_arrivo, "p_arrivo")
    ga = mh478_num(gamma, "gamma")
    if pa <= 0:
        raise ValueError("p_arrivo: deve essere > 0")
    if ga < 0:
        raise ValueError("gamma: non negativo")
    _mid = [mh478_num(v, f"mid[{k}]") for k, v in enumerate(list(mid))]
    _px = [mh478_num(v, f"px[{k}]") for k, v in enumerate(list(px))]
    _qty = [mh478_num(v, f"qty[{k}]") for k, v in enumerate(list(qty))]
    _sp = [mh478_num(v, f"spread_bps[{k}]")
           for k, v in enumerate(list(spread_bps))]
    n = len(_mid)
    if not (len(_px) == len(_qty) == len(_sp) == n):
        raise ValueError("mid/px/qty/spread_bps: stessa lunghezza")
    if n < 2:
        raise ValueError("servono almeno 2 bucket")
    for k in range(n):
        if _mid[k] <= 0:
            raise ValueError(f"mid[{k}]: deve essere > 0")
        if _px[k] <= 0:
            raise ValueError(f"px[{k}]: deve essere > 0")
        if _qty[k] <= 0:
            raise ValueError(f"qty[{k}]: deve essere > 0")
        if _sp[k] < 0:
            raise ValueError(f"spread_bps[{k}]: non negativo")
    X = sum(_qty)
    notionale = X * pa
    is_tot = sum(q * (p - pa) for q, p in zip(_qty, _px))
    spread = sum(q * m * s / 20000.0
                 for q, m, s in zip(_qty, _mid, _sp))
    temporaneo = (sum(q * (p - m) for q, p, m in zip(_qty, _px, _mid))
                  - spread)
    rimanenti = []
    _cum = 0.0
    for q in _qty:
        _cum += q
        rimanenti.append(X - _cum)
    permanente = ga * sum(q * (X - x)
                          for q, x in zip(_qty, rimanenti))
    timing = (sum(q * (m - pa) for q, m in zip(_qty, _mid))
              - permanente)
    residuo = is_tot - (spread + temporaneo + permanente + timing)
    sp_medio = sum(q * s for q, s in zip(_qty, _sp)) / X
    return {"n": n, "X": X, "notionale": notionale, "p_arrivo": pa,
            "is": is_tot, "is_bps": is_tot / notionale * 10000.0,
            "spread": spread, "temporaneo": temporaneo,
            "permanente": permanente, "timing": timing,
            "residuo": residuo, "spread_medio_bps": sp_medio,
            "gamma": ga}


def mh478_attribuzione(comp):
    """Quote e componente dominante dello shortfall.

    comp: dict da mh478_componenti. Le quote sono frazioni di Σ|.| dei
    quattro componenti (cosi' restano in [0, 1] anche con timing
    negativo); dominante = componente con |.| massimo.
    """
    for _k478 in ("spread", "temporaneo", "permanente", "timing", "is"):
        if not isinstance(comp, dict) or _k478 not in comp:
            raise ValueError(f"comp senza chiave {_k478}")
    _c478 = {k: float(comp[k])
             for k in ("spread", "temporaneo", "permanente", "timing")}
    _den478 = sum(abs(v) for v in _c478.values())
    if _den478 <= 0:
        raise ValueError("componenti tutti nulli: niente da attribuire")
    _quote478 = {k: abs(v) / _den478 for k, v in _c478.items()}
    _dom478 = max(_c478, key=lambda k: abs(_c478[k]))
    return {"quote": _quote478, "dominante": _dom478,
            "segno_dominante": 1 if _c478[_dom478] >= 0 else -1,
            "valore_dominante": _c478[_dom478]}


def mh478_verdetto(comp, spread_medio_bps=None):
    """Verdetto operativo sulla scomposizione.

    Rami: DATI INSUFFICIENTI (n < 2); ESECUZIONE EFFICIENTE (IS entro il
    20% sopra la meta' spread inevitabile: non c'era molto da
    ottimizzare); altrimenti "<COMPONENTE> DOMINANTE" con la quota.
    """
    if not isinstance(comp, dict):
        raise ValueError("comp: dict da mh478_componenti")
    for _k478 in ("n", "is", "is_bps"):
        if _k478 not in comp:
            raise ValueError(f"comp senza chiave {_k478}")
    n = comp["n"]
    if n < 2:
        return ("DATI INSUFFICIENTI — servono almeno 2 bucket per "
                "scomporre lo shortfall.")
    sp = (mh478_num(spread_medio_bps, "spread_medio_bps")
          if spread_medio_bps is not None
          else mh478_num(comp.get("spread_medio_bps", 0.0),
                         "spread_medio_bps"))
    if sp < 0:
        raise ValueError("spread_medio_bps: non negativo")
    is_bps = float(comp["is_bps"])
    if is_bps <= 1.2 * sp / 2.0:
        return (f"ESECUZIONE EFFICIENTE — IS {is_bps:.2f} bps entro il "
                f"20% sopra la meta' spread inevitabile ({sp / 2:.2f} "
                f"bps): il costo e' quasi tutto spread, poco da "
                f"ottimizzare.")
    att = mh478_attribuzione(comp)
    _nomi478 = {"spread": "SPREAD", "temporaneo": "IMPATTO TEMPORANEO",
                "permanente": "IMPATTO PERMANENTE", "timing": "TIMING"}
    dom = _nomi478[att["dominante"]]
    quota = att["quote"][att["dominante"]]
    _segno478 = ("a tuo favore" if att["segno_dominante"] < 0
                 else "a tuo sfavore")
    return (f"{dom} DOMINANTE — {quota:.0%} dello shortfall "
            f"({att['valore_dominante']:,.0f} EUR {_segno478}, IS totale "
            f"{comp['is']:,.0f} EUR = {is_bps:.2f} bps).")
def mh476_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh476_riga(nome, previsto_spread, previsto_impact, realizzato_spread,
               realizzato_impact, nozionale):
    """Una riga del registro: costo PREVISTO (tab475) vs REALIZZATO.

    tab475 stima il costo di esecuzione con c_impact=1.0 di default: un
    modello non calibrato sui costi reali e' decorazione. Il registro di
    tab476 raccoglie per ogni rotazione eseguita il previsto (spread e
    impact dal modello) e il realizzato a consuntivo.
    Costi >= 0 (EUR), nozionale > 0 (EUR); nome: stringa non vuota.
    Ritorna dict con: previsto_tot, realizzato_tot, err_spread,
    err_impact, err_tot (realizzato - previsto) e err_bps =
    err_tot / nozionale * 10000.
    """
    if not isinstance(nome, str) or not nome.strip():
        raise ValueError("nome: stringa non vuota")
    ps = mh476_num(previsto_spread, "previsto_spread")
    pi = mh476_num(previsto_impact, "previsto_impact")
    rs = mh476_num(realizzato_spread, "realizzato_spread")
    ri = mh476_num(realizzato_impact, "realizzato_impact")
    nz = mh476_num(nozionale, "nozionale")
    for _v476, _et476 in ((ps, "previsto_spread"), (pi, "previsto_impact"),
                          (rs, "realizzato_spread"),
                          (ri, "realizzato_impact")):
        if _v476 < 0:
            raise ValueError(f"{_et476}: costo negativo non ammesso")
    if nz <= 0:
        raise ValueError("nozionale: deve essere > 0")
    ptot = ps + pi
    rtot = rs + ri
    err = rtot - ptot
    return {"nome": nome.strip(), "previsto_spread": ps,
            "previsto_impact": pi, "realizzato_spread": rs,
            "realizzato_impact": ri, "nozionale": nz,
            "previsto_tot": ptot, "realizzato_tot": rtot,
            "err_spread": rs - ps, "err_impact": ri - pi,
            "err_tot": err, "err_bps": err / nz * 10000.0}


def mh476_statistiche(righe, tolleranza_bps=5.0):
    """Statistiche d'errore del registro (previsto vs realizzato).

    righe: lista di dict da mh476_riga. tolleranza_bps: soglia per
    l'hit-rate (default 5 bps).
    Ritorna dict: n, previsto_tot, realizzato_tot, bias_tot,
    bias_spread, bias_impact, bias_pct (bias_tot/previsto_tot*100),
    rmse_eur, mae_eur, rmse_bps, hit_rate (frazione righe con
    |err_bps| <= tolleranza_bps).
    Nota onesta: con poche righe la statistica e' rumorosa; il verdetto
    di mh476_verdetto chiede n >= 3.
    """
    tol = mh476_num(tolleranza_bps, "tolleranza_bps")
    if tol < 0:
        raise ValueError("tolleranza_bps: non negativa")
    righe = list(righe)
    if not righe:
        raise ValueError("righe: registro vuoto")
    for _r476 in righe:
        for _k476 in ("previsto_tot", "realizzato_tot", "err_tot",
                      "err_bps", "err_spread", "err_impact"):
            if _k476 not in _r476:
                raise ValueError(f"riga senza chiave {_k476}: "
                                 "usare mh476_riga")
    n = len(righe)
    ptot = sum(_r476["previsto_tot"] for _r476 in righe)
    rtot = sum(_r476["realizzato_tot"] for _r476 in righe)
    if ptot <= 0:
        raise ValueError("previsto_tot nullo: bias_pct non definita")
    import math
    err = [_r476["err_tot"] for _r476 in righe]
    errb = [_r476["err_bps"] for _r476 in righe]
    rmse = math.sqrt(sum(_e476 * _e476 for _e476 in err) / n)
    mae = sum(abs(_e476) for _e476 in err) / n
    rmse_bps = math.sqrt(sum(_e476 * _e476 for _e476 in errb) / n)
    hit = sum(1 for _e476 in errb if abs(_e476) <= tol) / n
    return {"n": n, "previsto_tot": ptot, "realizzato_tot": rtot,
            "bias_tot": rtot - ptot,
            "bias_spread": sum(_r476["err_spread"] for _r476 in righe),
            "bias_impact": sum(_r476["err_impact"] for _r476 in righe),
            "bias_pct": (rtot - ptot) / ptot * 100.0,
            "rmse_eur": rmse, "mae_eur": mae, "rmse_bps": rmse_bps,
            "hit_rate": hit, "tolleranza_bps": tol}


def mh476_calibra_c(righe):
    """Calibra il fattore di scala k dell'impact di tab475.

    OLS senza intercetta: realizzato_impact_i ~= k * previsto_impact_i,
    k = Σ(p_i r_i) / Σ(p_i²). Ritorna dict: k, r2 (bonta' su r),
    n_eff (righe con previsto_impact > 0) e suggerimento (stringa pronta
    per il desk: per quanto moltiplicare c_impact di tab475).
    Richiede almeno una riga con previsto_impact > 0.
    Nota onesta: k su poche righe e' rumoroso; OLS senza intercetta
    assume errore moltiplicativo puro (un bias additivo sistematico
    verrebbe assorbito da k in modo distorto).
    """
    righe = list(righe)
    if not righe:
        raise ValueError("righe: registro vuoto")
    pr = [(_r476["previsto_impact"], _r476["realizzato_impact"])
          for _r476 in righe
          if "previsto_impact" in _r476 and "realizzato_impact" in _r476]
    if not pr:
        raise ValueError("righe senza previsto_impact/realizzato_impact")
    peff = [(_p476, _r476) for _p476, _r476 in pr if _p476 > 0]
    if not peff:
        raise ValueError("nessuna riga con previsto_impact > 0")
    s_pr = sum(_p476 * _r476 for _p476, _r476 in peff)
    s_pp = sum(_p476 * _p476 for _p476, _r476 in peff)
    k = s_pr / s_pp
    res = sum((_r476 - k * _p476) ** 2 for _p476, _r476 in peff)
    rbar = sum(_r476 for _, _r476 in peff) / len(peff)
    den = sum((_r476 - rbar) ** 2 for _, _r476 in peff)
    r2 = 1.0 - res / den if den > 0 else (1.0 if res == 0 else 0.0)
    return {"k": k, "r2": r2, "n_eff": len(peff),
            "suggerimento": (f"moltiplica c_impact di tab475 per {k:.3f} "
                             f"(r²={r2:.2f} su {len(peff)} righe)")}


def mh476_verdetto(stat, calib, tol_bias_pct=10.0):
    """Verdetto di calibrazione: il modello di costo di tab475 tiene?

    stat: dict da mh476_statistiche; calib: dict da mh476_calibra_c
    oppure None; tol_bias_pct: soglia sul bias percentuale.
    Rami: DATI INSUFFICIENTI (n < 3), CALIBRATO (|bias| <= tol),
    SOTTOSTIMA (bias > tol: il modello sottostima i costi reali),
    SOVRASTIMA (bias < -tol).
    E' un formatter puro: non ricalcola nulla, valida solo gli input.
    """
    tol = mh476_num(tol_bias_pct, "tol_bias_pct")
    if tol < 0:
        raise ValueError("tol_bias_pct: non negativa")
    for _k476 in ("n", "bias_pct", "bias_tot", "hit_rate", "rmse_bps"):
        if not isinstance(stat, dict) or _k476 not in stat:
            raise ValueError(f"stat senza chiave {_k476}: "
                             "usare mh476_statistiche")
    if calib is not None and (not isinstance(calib, dict)
                              or "k" not in calib):
        raise ValueError("calib: dict da mh476_calibra_c oppure None")
    n = stat["n"]
    bp = stat["bias_pct"]
    if n < 3:
        return (f"DATI INSUFFICIENTI — solo {n} esecuzioni nel registro "
                f"(servono almeno 3 per giudicare la calibrazione)")
    nota_k = f"; {calib['suggerimento']}" if calib else ""
    if abs(bp) <= tol:
        return (f"CALIBRATO — bias {bp:+.1f}% entro ±{tol:.0f}%, hit-rate "
                f"{stat['hit_rate']:.0%}: il modello di costo regge{nota_k}")
    if bp > tol:
        return (f"SOTTOSTIMA — il modello sottostima i costi reali del "
                f"{bp:.1f}% (bias {stat['bias_tot']:,.0f} EUR){nota_k}")
    return (f"SOVRASTIMA — il modello sovrastima i costi reali del "
            f"{abs(bp):.1f}% (bias {stat['bias_tot']:,.0f} EUR){nota_k}")
def mh475_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh475_esecuzione(segnali, c_impact=1.0, costo_fisso=0.0):
    """Quanto costa DAVVERO eseguire la rotazione di tab473?

    tab473 dice di QUANTO ruotare (delta_i in frazione di taglia) con un
    costo piatto da input del desk; qui il costo diventa una stima del
    modello, per segnale i:
      trade_i = |delta_i| * nozionale_i          (EUR da eseguire)
      costo_spread_i = trade_i * spread_bps_i / 2 / 10000
      costo_impact_i = c_impact * sigma_g_i * trade_i * sqrt(trade_i/adv_i)
    La forma dell'impact e' la legge sqrt del market impact:
    impact_bps_i = c_impact * sigma_g_i * 10000 * sqrt(trade_i / adv_i),
    e costo_impact_i = impact_bps_i / 10000 * trade_i. Il costo fisso
    (commissioni desk/broker per trade) scatta solo se trade_i > 0.
    segnali: lista di tuple (nome, delta, nozionale, adv, spread_bps,
    sigma_g). nozionale = taglia base EUR; adv = volume medio
    giornaliero EUR; spread_bps = bid/ask in bps; sigma_g = vol
    giornaliera come frazione (0.02 = 2%).
    Ritorna dict con: righe (nome, delta, trade_eur, costo_spread,
    costo_impact, costo_fisso, costo_tot), segnali normalizzati,
    c_impact, costo_fisso, totali spread/impact/fisso/tot e
    rotazione_nozionale_tot.
    Note oneste: la legge sqrt e' una regolarita' empirica media (il
    vero slippage dipende da book, timing e urgenza); segnali
    indipendenti come tab468-tab474; il drift residuo di una rotazione
    parziale e' approssimato lineare in mh475_frazione_ottima.
    """
    import math
    _ci = mh475_num(c_impact, "c_impact")
    _cf = mh475_num(costo_fisso, "costo_fisso")
    if _ci < 0.0:
        raise ValueError("esecuzione: c_impact non puo' essere negativo")
    if _cf < 0.0:
        raise ValueError("esecuzione: costo_fisso non puo' essere negativo")
    if not isinstance(segnali, (list, tuple)) or len(segnali) == 0:
        raise ValueError("esecuzione: serve una lista non vuota di segnali")
    _righe = []
    _norm = []
    for _s in segnali:
        if not isinstance(_s, (list, tuple)) or len(_s) != 6:
            raise ValueError("esecuzione: ogni segnale e' (nome, delta, "
                             "nozionale, adv, spread_bps, sigma_g)")
        _nm, _dl, _nz, _av, _sp, _sg = _s
        if not isinstance(_nm, str) or not _nm:
            raise ValueError("esecuzione: nome segnale non valido")
        _dlf = mh475_num(_dl, f"delta {_nm}")
        _nzf = mh475_num(_nz, f"nozionale {_nm}")
        _avf = mh475_num(_av, f"adv {_nm}")
        _spf = mh475_num(_sp, f"spread_bps {_nm}")
        _sgf = mh475_num(_sg, f"sigma_g {_nm}")
        if _nzf <= 0.0:
            raise ValueError(f"esecuzione: segnale {_nm}: nozionale deve "
                             f"essere > 0")
        if _avf <= 0.0:
            raise ValueError(f"esecuzione: segnale {_nm}: adv deve "
                             f"essere > 0")
        if _spf < 0.0:
            raise ValueError(f"esecuzione: segnale {_nm}: spread_bps non "
                             f"puo' essere negativo")
        if _sgf < 0.0:
            raise ValueError(f"esecuzione: segnale {_nm}: sigma_g non "
                             f"puo' essere negativa")
        _trade = abs(_dlf) * _nzf
        _c_spread = _trade * _spf / 2.0 / 10000.0
        _c_impact = _ci * _sgf * _trade * math.sqrt(_trade / _avf) \
            if _trade > 0.0 else 0.0
        _c_fisso = _cf if _trade > 0.0 else 0.0
        _righe.append({"nome": _nm, "delta": _dlf, "trade_eur": _trade,
                       "costo_spread": _c_spread,
                       "costo_impact": _c_impact, "costo_fisso": _c_fisso,
                       "costo_tot": _c_spread + _c_impact + _c_fisso})
        _norm.append((_nm, _dlf, _nzf, _avf, _spf, _sgf))
    return {"n_segnali": len(_righe), "righe": _righe, "segnali": _norm,
            "c_impact": _ci, "costo_fisso": _cf,
            "costo_spread_tot": sum(_r["costo_spread"] for _r in _righe),
            "costo_impact_tot": sum(_r["costo_impact"] for _r in _righe),
            "costo_fisso_tot": sum(_r["costo_fisso"] for _r in _righe),
            "costo_tot": sum(_r["costo_tot"] for _r in _righe),
            "rotazione_nozionale_tot": sum(_r["trade_eur"]
                                           for _r in _righe)}


def mh475_frazione_ottima(exec_full, fuori_budget_eur, n_grid=101):
    """Quale frazione della rotazione conviene eseguire?

    Minimizza C(f) + (1-f)*F su f in [0,1] (grid deterministica):
    C(f) = costo di esecuzione ruotando la frazione f di ogni delta
    (spread lineare in f, impact ~ f^1.5, fisso scattato se f > 0);
    (1-f)*F = drift residuo, con F = fuori_budget_eur di tab473.
    L'approx lineare del residuo e' onesta per rotazioni piccole: il
    drift rimosso e' ~proporzionale alla frazione ruotata.
    Ritorna dict con f_star, costo_exec_fstar, costo_tot_min, dettaglio
    (lista di (f, C(f), totale)) e n_grid.
    """
    _F = mh475_num(fuori_budget_eur, "fuori_budget_eur")
    if _F < 0.0:
        raise ValueError("frazione_ottima: fuori_budget_eur non puo' "
                         "essere negativo")
    _ng = mh475_num(n_grid, "n_grid")
    if _ng < 2 or _ng != int(_ng):
        raise ValueError("frazione_ottima: n_grid intero >= 2")
    _ng = int(_ng)
    _righe = exec_full.get("righe") if isinstance(exec_full, dict) else None
    if not _righe:
        raise ValueError("frazione_ottima: exec_full senza righe")
    _seg = exec_full.get("segnali")
    if not _seg:
        raise ValueError("frazione_ottima: exec_full senza segnali")
    _ci = exec_full.get("c_impact", 1.0)
    _cf = exec_full.get("costo_fisso", 0.0)
    _dett = []
    _best = None
    for _k in range(_ng):
        _f = _k / (_ng - 1)
        _sub = [(_nm, _dl * _f, _nz, _av, _sp, _sg)
                for (_nm, _dl, _nz, _av, _sp, _sg) in _seg]
        _e = mh475_esecuzione(_sub, c_impact=_ci, costo_fisso=_cf)
        _tot = _e["costo_tot"] + (1.0 - _f) * _F
        _dett.append((_f, _e["costo_tot"], _tot))
        if _best is None or _tot < _best[2]:
            _best = (_f, _e["costo_tot"], _tot)
    return {"f_star": _best[0], "costo_exec_fstar": _best[1],
            "costo_tot_min": _best[2], "dettaglio": _dett,
            "n_grid": _ng}


def mh475_verdetto(exec_res, fuori_budget_eur, f_star_info=None):
    """Eseguire, ruotare parziale, o rimandare?

    Confronta il costo di esecuzione modellato (non piu' l'input piatto
    del desk) con gli EUR fuori budget di tab473:
      ESEGUI se costo_tot <= F (conviene ruotare tutto);
      RUOTA PARZIALE f* se il pieno non conviene ma esiste f* con
        C(f*) + (1-f*)*F < F;
      RIMANDA se nemmeno il parziale batte il drift;
      NESSUNA AZIONE se F = 0.
    f_star_info: dict da mh475_frazione_ottima (ricalcolato se None).
    """
    _F = mh475_num(fuori_budget_eur, "fuori_budget_eur")
    if _F < 0.0:
        raise ValueError("verdetto: fuori_budget_eur non puo' essere "
                         "negativo")
    _righe = exec_res.get("righe") if isinstance(exec_res, dict) else None
    if not _righe:
        raise ValueError("verdetto: exec_res senza righe")
    _C = mh475_num(exec_res.get("costo_tot", float("nan")), "costo_tot")
    if _C < 0.0:
        raise ValueError("verdetto: costo_tot non puo' essere negativo")
    if _F == 0.0:
        return "NESSUNA AZIONE \u2014 nessun drift fuori budget"
    if _C <= _F:
        return (f"ESEGUI \u2014 costo modellato {_C:,.0f} EUR <= "
                f"{_F:,.0f} EUR fuori budget: conviene ruotare tutto")
    _fo = mh475_frazione_ottima(exec_res, _F) if f_star_info is None \
        else f_star_info
    if not isinstance(_fo, dict):
        raise ValueError("verdetto: f_star_info non valido")
    _fs = mh475_num(_fo.get("f_star", float("nan")), "f_star")
    _cm = mh475_num(_fo.get("costo_tot_min", float("nan")),
                    "costo_tot_min")
    if not 0.0 <= _fs <= 1.0:
        raise ValueError("verdetto: f_star fuori [0,1]")
    if _cm < _F and _fs > 0.0:
        return (f"RUOTA PARZIALE {_fs:.0%} \u2014 costo pieno "
                f"{_C:,.0f} EUR > {_F:,.0f} EUR fuori budget, ma ruotando "
                f"il {_fs:.0%} il totale (esecuzione + residuo) scende a "
                f"{_cm:,.0f} EUR")
    return (f"RIMANDA \u2014 costo modellato {_C:,.0f} EUR > {_F:,.0f} "
            f"EUR fuori budget: la rotazione costa piu' del drift")
def mh474_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh474_frequenza(costo_ribil, fuori_budget_eur, drift_sett, dev_max,
                    settimane_anno=52.0):
    """Ogni quanto ribilanciare? Frequenza ottimale del ciclo di rotazione.

    Domanda operativa: tab473 dice di QUANTO ruotare una volta sola; qui
    la domanda e' ogni QUANTO ripetere il controllo/ribilanciamento quando
    il drift si ripresenta. Modello chiuso, tutto deterministico:

    - il drift di budget cresce linearmente nel tempo:
      dev(t) = drift_sett * t  (t in settimane, drift_sett = frazione/sett.)
    - il costo extra di ES fuori budget cresce linearmente con la
      deviazione: extra(t) = fuori_budget_eur * dev(t) / dev_max
      (fuori_budget_eur = extra ES annuo a drift pieno, dev_max =
      deviazione massima osservata; entrambe input del desk, default dalla
      demo tab473)
    - costo cumulato di drift in un ciclo di T settimane:
      a * T^2  con  a = fuori_budget_eur * drift_sett / (2 * dev_max)
    - costo totale annuo:
      C(T) = (settimane_anno / T) * (costo_ribil + a * T^2)
    - ottimo in forma chiusa: T* = sqrt(costo_ribil / a)

    All'ottimo il costo si divide 50/50 tra ribilanciamenti e drift
    residuo (proprieta' del modello: costo_ribil / T* = a * T*).
    Approx oneste: drift lineare, extra ES lineare nella deviazione,
    costo di ribilanciamento costante nel tempo, anno = 52 settimane.
    """
    _k = mh474_num(costo_ribil, "costo_ribil")
    _f = mh474_num(fuori_budget_eur, "fuori_budget_eur")
    _g = mh474_num(drift_sett, "drift_sett")
    _d = mh474_num(dev_max, "dev_max")
    _sa = mh474_num(settimane_anno, "settimane_anno")
    if _k <= 0.0:
        raise ValueError("frequenza: costo_ribil deve essere > 0")
    if _f <= 0.0:
        raise ValueError("frequenza: fuori_budget_eur deve essere > 0 "
                         "(se il drift non costa niente non serve "
                         "ribilanciare)")
    if _g <= 0.0:
        raise ValueError("frequenza: drift_sett deve essere > 0")
    if _d <= 0.0:
        raise ValueError("frequenza: dev_max deve essere > 0")
    if _sa <= 0.0:
        raise ValueError("frequenza: settimane_anno deve essere > 0")
    import math
    _a = _f * _g / (2.0 * _d)
    _ts = math.sqrt(_k / _a)
    _cs = _sa * (_k / _ts + _a * _ts)
    _n = _sa / _ts
    _drift_ciclo = _a * _ts ** 2
    return {"a_eur_sett2": _a, "T_star_sett": _ts,
            "costo_annuo_ottimo": _cs,
            "ribilanciamenti_anno": _n,
            "costo_ribil_ciclo": _k,
            "drift_cumulato_ciclo": _drift_ciclo,
            "quota_drift": _drift_ciclo / (_k + _drift_ciclo),
            "quota_ribil": _k / (_k + _drift_ciclo)}


def mh474_costo_annuo(t_sett, costo_ribil, a_eur_sett2, settimane_anno=52.0):
    """Costo annuo totale per un ciclo di ribilanciamento di t_sett settimane.

    C(T) = (settimane_anno / T) * (costo_ribil + a * T^2): il primo termine
    scende con T (meno ribilanciamenti), il secondo sale (piu' drift
    cumulato). T* = sqrt(costo_ribil / a) e' il minimo esatto.
    """
    _t = mh474_num(t_sett, "t_sett")
    _k = mh474_num(costo_ribil, "costo_ribil")
    _a = mh474_num(a_eur_sett2, "a_eur_sett2")
    _sa = mh474_num(settimane_anno, "settimane_anno")
    if _t <= 0.0:
        raise ValueError("costo_annuo: t_sett deve essere > 0")
    if _k < 0.0:
        raise ValueError("costo_annuo: costo_ribil non puo' essere negativo")
    if _a < 0.0:
        raise ValueError("costo_annuo: a_eur_sett2 non puo' essere negativo")
    if _sa <= 0.0:
        raise ValueError("costo_annuo: settimane_anno deve essere > 0")
    return _sa * (_k / _t + _a * _t)


def mh474_verdetto(freq):
    """Verdetto operativo: ogni quante settimane ribilanciare."""
    if not isinstance(freq, dict):
        raise ValueError("verdetto: serve il dict di mh474_frequenza")
    for _kk in ("T_star_sett", "ribilanciamenti_anno", "costo_annuo_ottimo",
                "quota_drift"):
        if _kk not in freq:
            raise ValueError(f"verdetto: chiave mancante '{_kk}'")
    _t = mh474_num(freq["T_star_sett"], "T_star_sett")
    _n = mh474_num(freq["ribilanciamenti_anno"], "ribilanciamenti_anno")
    _c = mh474_num(freq["costo_annuo_ottimo"], "costo_annuo_ottimo")
    _q = mh474_num(freq["quota_drift"], "quota_drift")
    if _t < 0.5:
        _quando = (f"piu' di una volta a settimana (T*={_t:.2f} sett.): "
                   "un ribilanciamento cosi' frequente non e' realistico — "
                   "considera hedge continuo o tolleranza piu' alta")
    elif _t < 2.0:
        _quando = f"ogni {_t:.1f} settimane (~{_n:.0f} volte/anno)"
    else:
        _quando = f"ogni {_t:.0f} settimane (~{_n:.0f} volte/anno)"
    return (f"RIBILANCIA {_quando}. Costo annuo ottimale {_c:,.0f} EUR, "
            f"di cui {_q:.0%} drift residuo e {1.0 - _q:.0%} "
            f"ribilanciamenti: all'ottimo le due voci si equivalgono (il "
            f"drift costa quanto ruotare). Il drift oltre questa cadenza "
            f"costa piu' del ribilanciamento stesso.")
def mh472_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh472_drift(segnali, pesi, budget=None, shock_vol=None, alpha=0.01,
                mult=1.0, tol=0.15, costo_ribil=500.0):
    """I budget di rischio tengono quando la volatilita' si muove?

    Dopo tab471 (risk budgeting: i pesi w_i che allineano ogni segnale al
    suo budget di ES) la domanda operativa del risk desk e': i budget
    TENGONO quando la volatilita' realizzata si muove? Uno shock di vol
    sul segnale i scala la sua deviazione standard di s_i (shock_vol):
      var_i' = var_i * s_i^2   (la media NON si muove: shock di vol, non
      di edge)
    e ricalcola ES e componenti Euleriane ai pesi correnti:
      es' = k*sqrt(somma w_i^2*var_i') - somma w_i*media_i
      comp_i' = k*w_i^2*var_i'/sqrt(somma w_j^2*var_j') - w_i*media_i
    (somma comp_i' = es' esatta: es omogenea di grado 1 in w, come
    tab471). Il target resta la quota di budget sull'ES corrente:
      target_i = b_i * es';  dev_i = (comp_i' - target_i) / target_i.
    Il segnale i va ribilanciato se |dev_i| > tol.
    mh470_shortfall valida i segnali e fornisce la baseline a shock nulli
    (media_i, var_i, k_es); i pesi sono i fattori di scala tab471
    (1.0 = taglia quotata).
    Ritorna dict con: es_atteso (shock nulli), es_corrente, variazione
    relativa dell'ES, righe (nome, peso, shock_vol, budget, target,
    componente, deviazione, flag), fuori_budget_eur (somma dei
    |componente - target|), n_ribilanciare, costo_ribil_tot
    (n_ribilanciare * costo_ribil), top_drift (max |dev_i| con la sua
    deviazione), alpha, mult, tol.
    Note oneste: come tab468-tab471 (approx normale, code pesanti non
    modellate); segnali indipendenti (correlazione: vedi tab465); lo
    shock muove solo la vol, non l'edge (se muore anche l'edge il drift
    vero e' peggiore di quello calcolato); il costo di ribilanciamento
    e' un input del desk, non una stima del modello.
    """
    import math
    if not isinstance(segnali, (list, tuple)) or len(segnali) == 0:
        raise ValueError("drift: serve una lista non vuota di segnali")
    _n = len(segnali)
    _al = mh472_num(alpha, "alpha")
    _ml = mh472_num(mult, "mult")
    _tl = mh472_num(tol, "tol")
    _cr = mh472_num(costo_ribil, "costo_ribil")
    if not 0.0 < _al < 0.5:
        raise ValueError("drift: alpha deve stare in (0, 0.5)")
    if _ml < 1.0:
        raise ValueError("drift: mult deve essere >= 1")
    if not 0.0 < _tl <= 1.0:
        raise ValueError("drift: tol deve stare in (0, 1]")
    if _cr < 0.0:
        raise ValueError("drift: costo_ribil non puo' essere negativo")
    if not isinstance(pesi, (list, tuple)) or len(pesi) != _n:
        raise ValueError("drift: pesi deve avere tanti elementi quanti "
                         "i segnali")
    _w = [mh472_num(_x, "pesi") for _x in pesi]
    if any(_x <= 0.0 for _x in _w):
        raise ValueError("drift: ogni peso deve essere > 0")
    if budget is None:
        _b = [1.0 / _n] * _n
    else:
        if not isinstance(budget, (list, tuple)) or len(budget) != _n:
            raise ValueError("drift: budget deve avere tanti elementi "
                             "quanti i segnali")
        _b = [mh472_num(_x, "budget") for _x in budget]
        if any(_x <= 0.0 for _x in _b):
            raise ValueError("drift: ogni budget deve essere > 0")
        _sb = sum(_b)
        _b = [_x / _sb for _x in _b]
    if shock_vol is None:
        _sh = [1.0] * _n
    else:
        if not isinstance(shock_vol, (list, tuple)) or \
                len(shock_vol) != _n:
            raise ValueError("drift: shock_vol deve avere tanti elementi "
                             "quanti i segnali")
        _sh = [mh472_num(_x, "shock_vol") for _x in shock_vol]
        if any(_x <= 0.0 for _x in _sh):
            raise ValueError("drift: ogni shock_vol deve essere > 0")

    # Baseline a shock nulli via mh470 (valida anche i segnali); k_es e'
    # la costante k = phi(z)/alpha dell'approx normale.
    _sf = mh470_shortfall(segnali, alpha=_al, mult=_ml)
    _k = _sf["k_es"]
    _nomi = [_r["nome"] for _r in _sf["righe"]]
    _med = [_r["media"] for _r in _sf["righe"]]
    _var = [_r["var"] for _r in _sf["righe"]]

    def _es_comps(_vv):
        _M = sum(_w[_i] * _med[_i] for _i in range(_n))
        _V = sum(_w[_i] ** 2 * _vv[_i] for _i in range(_n))
        _std = math.sqrt(_V)
        _es = _k * _std - _M
        _comp = [_k * _w[_i] ** 2 * _vv[_i] / _std - _w[_i] * _med[_i]
                 for _i in range(_n)]
        return _es, _comp

    _es0, _comp0 = _es_comps(_var)
    _var1 = [_var[_i] * _sh[_i] ** 2 for _i in range(_n)]
    _es1, _comp1 = _es_comps(_var1)
    if _es1 <= 0.0:
        raise ValueError("drift: ES corrente <= 0 con questi shock")
    _righe = []
    for _i in range(_n):
        _tgt = _b[_i] * _es1
        _dev = (_comp1[_i] - _tgt) / _tgt
        _righe.append({
            "nome": _nomi[_i],
            "peso": _w[_i],
            "shock_vol": _sh[_i],
            "budget": _b[_i],
            "target": _tgt,
            "componente": _comp1[_i],
            "deviazione": _dev,
            "flag": abs(_dev) > _tl,
        })
    _fuori = sum(abs(_r["componente"] - _r["target"]) for _r in _righe)
    _nflag = sum(1 for _r in _righe if _r["flag"])
    _imax = max(range(_n), key=lambda _i: abs(_righe[_i]["deviazione"]))
    return {
        "n_segnali": _n,
        "nomi": _nomi,
        "pesi": _w,
        "budget": _b,
        "shock_vol": _sh,
        "es_atteso": _es0,
        "es_corrente": _es1,
        "variazione_es": (_es1 - _es0) / _es0
        if _es0 != 0.0 else float("nan"),
        "righe": _righe,
        "fuori_budget_eur": _fuori,
        "n_ribilanciare": _nflag,
        "costo_ribil_unit": _cr,
        "costo_ribil_tot": _nflag * _cr,
        "top_drift": _nomi[_imax],
        "deviazione_top_drift": _righe[_imax]["deviazione"],
        "alpha": _al,
        "mult": _ml,
        "tol": _tl,
    }


def mh472_verdetto(dr):
    """I budget tengono? Verdetto operativo sul drift dei budget.

    dr: dict da mh472_drift. Se nessun segnale esce dalla tolleranza i
    budget sono STABILI; altrimenti nomina i segnali da ribilanciare (il
    peggiore per primo) con il costo stimato del ribilanciamento contro
    gli EUR fuori budget."""
    if not isinstance(dr, dict) or "righe" not in dr:
        raise ValueError("verdetto: serve il dict di mh472_drift")
    _righe = dr["righe"]
    if len(_righe) == 0:
        raise ValueError("verdetto: nessun segnale da valutare")
    _nflag = dr.get("n_ribilanciare", 0)
    if not isinstance(_nflag, int) or isinstance(_nflag, bool) or \
            _nflag < 0:
        raise ValueError("verdetto: n_ribilanciare non valido")
    _fuori = mh472_num(dr.get("fuori_budget_eur", 0.0), "fuori_budget_eur")
    if _fuori < 0.0:
        raise ValueError("verdetto: fuori_budget_eur non puo' essere "
                         "negativo")
    if _nflag == 0:
        _maxd = max(abs(_r["deviazione"]) for _r in _righe)
        _esc = mh472_num(dr.get("es_corrente", 0.0), "es_corrente")
        return ("BUDGET STABILI \u2014 nessuna deviazione oltre la "
                f"tolleranza (max {_maxd:.1%}): i budget tengono, nessun "
                f"ribilanciamento. ES corrente {_esc:,.0f} EUR.")
    _nomi_f = [_r["nome"] for _r in _righe if _r["flag"]]
    _top = dr.get("top_drift", _nomi_f[0])
    _devt = mh472_num(dr.get("deviazione_top_drift", 0.0),
                       "deviazione_top_drift")
    _costo = mh472_num(dr.get("costo_ribil_tot", 0.0), "costo_ribil_tot")
    return (f"DRIFT \u2014 da ribilanciare: {', '.join(_nomi_f)} "
            f"({_nflag} su {len(_righe)}); il peggiore e' {_top} "
            f"({_devt:+.1%} sul budget). Costo stimato {_costo:,.0f} EUR "
            f"contro {_fuori:,.0f} EUR fuori budget: "
            f"{'conviene' if _costo < _fuori else 'valutare se'} "
            f"ribilanciare.")

def mh471_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh471_risk_budget(segnali, budget=None, alpha=0.01, mult=1.0,
                     damp=0.5, max_iter=500, tol=1e-9):
    """Pesi che allineano ogni segnale al suo budget di rischio (ES).

    Dopo tab468 (VaR: la soglia), tab469 (chi la mangia) e tab470 (quanto
    perdi quando perdi), la domanda operativa del risk desk e': COME
    ripartire il capitale tra i segnali? Il risk budgeting assegna a ogni
    segnale un budget b_i (frazione dell'ES di portafoglio, default: parti
    uguali) e calcola i pesi w_i che rendono la componente Euleriana di
    ES di ogni segnale uguale al suo budget:
      comp_i(w) = b_i * es(w).
    Approx normale a segnali indipendenti come tab468/tab469/tab470:
      media_i(w) = w_i*media_i;  var_i(w) = w_i^2*var_i
      (w_i scala il P&L del segnale i: la media scala lineare, la
      varianza quadratica; media_i = lam_i*mu_i e var_i =
      lam_i*(sigma_i^2+mu_i^2) come tab470).
      es(w) = k*sqrt(V(w)) - M(w);  comp_i(w) = w_i * d(es)/d(w_i)
            = k*w_i^2*var_i/sqrt(V(w)) - w_i*media_i
    (somma comp_i = es(w) esatta: es e' omogenea di grado 1 in w).
    mh470_shortfall valida i segnali e fornisce la baseline a pesi
    unitari (media_i, var_i, k_es); l'iterazione calcola es/comp
    direttamente da (media_i, var_i): NON si riusa mh470_shortfall con
    lam scalato, perche' lam scala media e varianza ENTRAMBE linearmente
    mentre il peso w_i deve scalare la varianza quadraticamente
    (bug evitato: comp_i = d(es)/dw_i, non w_i*d(es)/dw_i).
    Solver: punto fisso smorzato w_i <- w_i*(b_i*es/comp_i)^damp con
    rinormalizzazione somma(w) = n a ogni iterazione (es e' omogenea di
    grado 1 in w: la scala non cambia i rapporti). Converge quando ogni
    comp_i > 0 (un segnale con componente <= 0 non puo' assorbire un
    budget positivo: ValueError onesto, non un numero finto).
    Ritorna dict con: pesi, budget normalizzati, es/capitale finali,
    componenti finali (nome, peso, budget, target, componente, scarto),
    componenti iniziali a pesi unitari (per il verdetto "chi mangia piu'
    del dovuto OGGI"), iterazioni, convergenza, deviazione finale,
    top_sovrappeso/top_sottopeso iniziali, alpha, mult, damp.
    Note oneste: come tab468/tab469/tab470 (approx normale, code pesanti
    non modellate); segnali indipendenti (correlazione: vedi tab465); i
    pesi sono fattori di scala sulla taglia quotata (1.0 = taglia
    corrente), non allocazioni percentuali di un portafoglio a somma 1.
    """
    import math
    if not isinstance(segnali, (list, tuple)) or len(segnali) == 0:
        raise ValueError("risk_budget: serve una lista non vuota di segnali")
    _n = len(segnali)
    for _s in segnali:
        if not isinstance(_s, (list, tuple)) or len(_s) != 4:
            raise ValueError(
                "risk_budget: ogni segnale e' (nome, lam, mu, sigma)")
        if not isinstance(_s[0], str) or not _s[0]:
            raise ValueError("risk_budget: nome segnale non valido")
    _al = mh471_num(alpha, "alpha")
    _ml = mh471_num(mult, "mult")
    _dp = mh471_num(damp, "damp")
    _mi = mh471_num(max_iter, "max_iter")
    _tl = mh471_num(tol, "tol")
    if not 0.0 < _al < 0.5:
        raise ValueError("risk_budget: alpha deve stare in (0, 0.5)")
    if _ml < 1.0:
        raise ValueError("risk_budget: mult deve essere >= 1")
    if not 0.0 < _dp <= 1.0:
        raise ValueError("risk_budget: damp deve stare in (0, 1]")
    if _mi < 1 or _mi != int(_mi):
        raise ValueError("risk_budget: max_iter intero >= 1")
    if _tl <= 0.0:
        raise ValueError("risk_budget: tol deve essere > 0")
    if budget is None:
        _b = [1.0 / _n] * _n
    else:
        if not isinstance(budget, (list, tuple)) or len(budget) != _n:
            raise ValueError("risk_budget: budget deve avere tanti "
                             "elementi quanti i segnali")
        _b = [mh471_num(_x, "budget") for _x in budget]
        if any(_x <= 0.0 for _x in _b):
            raise ValueError("risk_budget: ogni budget deve essere > 0")
        _sb = sum(_b)
        _b = [_x / _sb for _x in _b]

    # Baseline a pesi unitari via mh470 (valida anche i segnali); k_es e'
    # la costante k = phi(z)/alpha dell'approx normale.
    _sf0 = mh470_shortfall(segnali, alpha=_al, mult=_ml)
    _k = _sf0["k_es"]
    _nomi = [_r["nome"] for _r in _sf0["righe"]]
    _med = [_r["media"] for _r in _sf0["righe"]]
    _var = [_r["var"] for _r in _sf0["righe"]]
    _es0 = _sf0["es_perdita"]
    if _es0 <= 0.0:
        raise ValueError("risk_budget: ES di portafoglio <= 0 a pesi "
                         "unitari, budgeting senza senso")

    def _es_comps(_w):
        _M = sum(_w[_i] * _med[_i] for _i in range(_n))
        _V = sum(_w[_i] ** 2 * _var[_i] for _i in range(_n))
        _std = math.sqrt(_V)
        _es = _k * _std - _M
        _comp = [_k * _w[_i] ** 2 * _var[_i] / _std - _w[_i] * _med[_i]
                 for _i in range(_n)]
        return _es, _comp

    _comp0 = _es_comps([1.0] * _n)[1]
    _w = [1.0] * _n
    _conv = False
    _dev = float("inf")
    _it = 0
    for _it in range(1, int(_mi) + 1):
        _es, _comp = _es_comps(_w)
        if _es <= 0.0:
            raise ValueError("risk_budget: ES di portafoglio <= 0 "
                             "durante l'iterazione")
        _dev = max(abs(_c - _b[_i] * _es)
                   for _i, _c in enumerate(_comp)) / _es
        if _dev < _tl:
            _conv = True
            break
        for _i, _c in enumerate(_comp):
            if _c <= 0.0:
                raise ValueError(
                    f"risk_budget: segnale {_nomi[_i]}: "
                    f"componente {_c:,.0f} <= 0, non puo' assorbire un "
                    f"budget positivo")
        _w = [_w[_i] * (_b[_i] * _es / _comp[_i]) ** _dp
              for _i in range(_n)]
        _sn = sum(_w) / _n
        _w = [_x / _sn for _x in _w]
    _esf, _compf = _es_comps(_w)
    _righe = []
    for _i in range(_n):
        _tgt = _b[_i] * _esf
        _righe.append({
            "nome": _nomi[_i],
            "peso": _w[_i],
            "budget": _b[_i],
            "target": _tgt,
            "componente": _compf[_i],
            "scarto": _compf[_i] - _tgt,
        })
    _sc0 = [(_comp0[_i] - _b[_i] * _es0) / (_b[_i] * _es0)
            for _i in range(_n)]
    _iover = max(range(_n), key=lambda _i: _sc0[_i])
    _iunder = min(range(_n), key=lambda _i: _sc0[_i])
    return {
        "n_segnali": _n,
        "budget": _b,
        "pesi": _w,
        "iterazioni": _it,
        "convergenza": _conv,
        "deviazione_finale": _dev,
        "es_finale": _esf,
        "capitale_finale": max(0.0, _esf) * _ml,
        "es_iniziale": _es0,
        "capitale_iniziale": _sf0["capitale"],
        "righe": _righe,
        "componenti_iniziali": _comp0,
        "scarti_rel_iniziali": _sc0,
        "top_sovrappeso": _nomi[_iover],
        "top_sottopeso": _nomi[_iunder],
        "scarto_top_sovrappeso": _sc0[_iover],
        "scarto_top_sottopeso": _sc0[_iunder],
        "alpha": _al,
        "mult": _ml,
        "damp": _dp,
    }


def mh471_verdetto(rb):
    """Come ripartire il capitale? Verdetto operativo sul risk budgeting.

    rb: dict da mh471_risk_budget. A pesi unitari (taglie correnti) nomina
    il segnale piu' sovrappesato rispetto al suo budget ("mangia piu'
    capitale del dovuto") e il piu' sottopeso ("ha ancora spazio"), con i
    pesi ricalcolati che li rimettono in budget. Se non converge o il
    capitale e' nullo, lo dice onestamente."""
    if not isinstance(rb, dict) or "righe" not in rb:
        raise ValueError("verdetto: serve il dict di mh471_risk_budget")
    _righe = rb["righe"]
    if len(_righe) == 0:
        raise ValueError("verdetto: nessun segnale da valutare")
    _cap = mh471_num(rb.get("capitale_finale", 0.0), "capitale_finale")
    if _cap < 0.0:
        raise ValueError("verdetto: capitale non puo' essere negativo")
    if not rb.get("convergenza", False):
        return ("BUDGET NON RAGGIUNTI \u2014 il punto fisso non ha "
                f"convergente in {rb.get('iterazioni', '?')} iterazioni "
                f"(deviazione {rb.get('deviazione_finale', float('nan')):.2%}"
                f"): i budget chiesti potrebbero essere irraggiungibili "
                f"con questi segnali")
    if _cap <= 0.0:
        return ("NESSUN CAPITALE DA RIPARTIRE \u2014 Expected Shortfall "
                "\u2264 0: la coda resta in utile, nessun budget da "
                "assegnare")
    _over = rb["top_sovrappeso"]
    _under = rb["top_sottopeso"]
    _sc_over = rb["scarto_top_sovrappeso"]
    _sc_under = rb["scarto_top_sottopeso"]
    _pw = {r["nome"]: r["peso"] for r in _righe}
    return (f"BUDGET RISPETTATI \u2014 a taglie correnti {_over} mangia il "
            f"{_sc_over:+.1%} del suo budget di ES "
            f"({'troppo' if _sc_over > 0 else 'il giusto'}): va "
            f"ridimensionato a {_pw[_over]:.2f}x; {_under} ha ancora spazio "
            f"({_sc_under:+.1%} sul budget): pu\u00f2 salire a "
            f"{_pw[_under]:.2f}x. Capitale finale "
            f"{_cap:,.0f} EUR in {rb['iterazioni']} iterazioni.")

def mh470_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh470_shortfall(segnali, alpha=0.01, mult=1.0):
    """Expected Shortfall di portafoglio + scomposizione Euleriana.

    segnali: lista di (nome, lam, mu, sigma) come tab468/tab469.
    Per segnale i: media_i = lam_i*mu_i; var_i = lam_i*(sigma_i^2+mu_i^2).
    Portafoglio: M = somma media_i; V = somma var_i; std = sqrt(V);
      z = Phi^-1(alpha) < 0 (via mh468_phi_inv); phi = densita' normale
      standard in z (NOTA: mh468_phi e' la CDF, la densita' si calcola
      qui: exp(-z^2/2)/sqrt(2*pi)); k = phi/alpha (> |z|).
    Expected Shortfall (perdita media condizionata a superare il VaR):
      es_perdita = k*std - M  (>= var_perdita = -(M + z*std), SEMPRE:
      k > |z|); capitale = max(0, es_perdita) * mult.
    Componente Euleriana (somma = es_perdita, esatta nell'approx):
      comp_i = d(es)/d(w_i) a pesi 1 = k*var_i/std - media_i
      (w_i scala il P&L del segnale i: media_i*w_i, var_i*w_i^2).
    quota_i = comp_i / es_perdita (0 se es_perdita == 0).
    What-if taglio: es_wo_i = k*sqrt(V-var_i) - (M-media_i);
      capitale_wo_i = max(0, es_wo_i)*mult;
      risparmio_i = capitale - capitale_wo_i (capitale liberato tagliando
      il segnale i; NEGATIVO se il segnale diversifica: tagliarlo
      AUMENTA il capitale richiesto).
    top: segnale con comp_i massima ("il piu' goloso" dell'ES).
    beneficio_diversificazione = somma_i max(0, k*sqrt(var_i)-media_i)
      *mult - capitale (>= 0 in approx normale a segnali indipendenti).
    Note oneste: come tab468/tab469 (approx normale, code pesanti non
      modellate); scomposizione esatta solo nell'approx normale;
      segnali indipendenti (correlazione: vedi tab465)."""
    import math
    if not isinstance(segnali, (list, tuple)) or len(segnali) == 0:
        raise ValueError("shortfall: serve una lista non vuota di segnali")
    _al = mh470_num(alpha, "alpha")
    _ml = mh470_num(mult, "mult")
    if not 0.0 < _al < 0.5:
        raise ValueError("shortfall: alpha deve stare in (0, 0.5)")
    if _ml < 1.0:
        raise ValueError("shortfall: mult deve essere >= 1")
    _z = mh468_phi_inv(_al)
    _phi = math.exp(-0.5 * _z * _z) / math.sqrt(2.0 * math.pi)
    _k = _phi / _al
    _nomi, _medie, _vars = [], [], []
    for _s in segnali:
        if not isinstance(_s, (list, tuple)) or len(_s) != 4:
            raise ValueError(
                "shortfall: ogni segnale e' (nome, lam, mu, sigma)")
        _nome, _lam, _mu, _sg = _s
        if not isinstance(_nome, str) or not _nome:
            raise ValueError("shortfall: nome segnale non valido")
        _lam = mh470_num(_lam, "lam")
        _mu = mh470_num(_mu, "mu")
        _sg = mh470_num(_sg, "sigma")
        if _lam <= 0.0:
            raise ValueError("shortfall: lam deve essere > 0")
        if _sg < 0.0:
            raise ValueError("shortfall: sigma non puo' essere negativo")
        _nomi.append(_nome)
        _medie.append(_lam * _mu)
        _vars.append(_lam * (_sg * _sg + _mu * _mu))
    _M = sum(_medie)
    _V = sum(_vars)
    _std = math.sqrt(_V)
    if _std <= 0.0:
        raise ValueError("shortfall: varianza di portafoglio nulla")
    _es = _k * _std - _M
    _vp = -(_M + _z * _std)
    _cap = max(0.0, _es) * _ml
    _righe = []
    for _i, _nome in enumerate(_nomi):
        _comp = _k * _vars[_i] / _std - _medie[_i]
        _quota = _comp / _es if _es != 0.0 else 0.0
        _es_wo = _k * math.sqrt(_V - _vars[_i]) - (_M - _medie[_i])
        _cap_wo = max(0.0, _es_wo) * _ml
        _righe.append({
            "nome": _nome,
            "media": _medie[_i],
            "var": _vars[_i],
            "std": math.sqrt(_vars[_i]),
            "componente": _comp,
            "quota": _quota,
            "es_perdita_wo": _es_wo,
            "capitale_wo": _cap_wo,
            "risparmio": _cap - _cap_wo,
        })
    _top = max(range(len(_righe)),
               key=lambda _i: _righe[_i]["componente"])
    _ben = sum(max(0.0, _k * math.sqrt(_vars[_i]) - _medie[_i])
               for _i in range(len(_righe))) * _ml - _cap
    return {
        "righe": _righe,
        "media_tot": _M,
        "var_tot": _V,
        "std_tot": _std,
        "z_alpha": _z,
        "k_es": _k,
        "es_perdita": _es,
        "var_perdita": _vp,
        "delta_var": _es - _vp,
        "capitale": _cap,
        "top": _righe[_top]["nome"],
        "top_idx": _top,
        "quota_top": _righe[_top]["quota"],
        "risparmio_top": _righe[_top]["risparmio"],
        "beneficio_diversificazione": _ben,
        "n_segnali": len(_righe),
        "alpha": _al,
        "mult": _ml,
    }


def mh470_verdetto(sf):
    """Quanto perdi quando perdi? Verdetto operativo sull'ES.

    sf: dict da mh470_shortfall. Se capitale <= 0: NESSUN CAPITALE
    RICHIESTO (coda in utile); altrimenti quantifica il Delta ES-VaR
    (quanto peggio della soglia quando la coda colpisce) e nomina "il
    piu' goloso" dell'ES con l'effetto del taglio."""
    if not isinstance(sf, dict) or "righe" not in sf:
        raise ValueError("verdetto: serve il dict di mh470_shortfall")
    _righe = sf["righe"]
    if len(_righe) == 0:
        raise ValueError("verdetto: nessun segnale da valutare")
    _cap = mh470_num(sf.get("capitale", 0.0), "capitale")
    if _cap < 0.0:
        raise ValueError("verdetto: capitale non puo' essere negativo")
    if _cap <= 0.0:
        return ("NESSUN CAPITALE RICHIESTO \u2014 Expected Shortfall "
                "\u2264 0: la coda resta in utile, nessun segnale da "
                "tagliare")
    _top = max(_righe, key=lambda _r: _r["componente"])
    return (f"QUANTO PERDI QUANDO PERDI \u2014 ES "
            f"{sf['es_perdita']:,.0f} EUR vs VaR "
            f"{sf['var_perdita']:,.0f} EUR "
            f"(\u0394 {sf['delta_var']:+,.0f} EUR): quando la coda colpisce "
            f"perdi in media il {sf['delta_var'] / sf['var_perdita']:.1%} "
            f"in pi\u00f9 della soglia; il pi\u00f9 goloso \u00e8 "
            f"{_top['nome']} ({_top['quota']:.0%} dell'ES): tagliandolo il "
            f"capitale scende a {_top['capitale_wo']:,.0f} EUR "
            f"(\u0394 {_top['risparmio']:+,.0f} EUR)")

def mh469_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh469_componenti(segnali, alpha=0.01, mult=1.0):
    """Scomposizione Euleriana del VaR di portafoglio + what-if taglio.

    segnali: lista di (nome, lam, mu, sigma) come tab468.
    Per segnale i: media_i = lam_i*mu_i; var_i = lam_i*(sigma_i^2+mu_i^2).
    Portafoglio: M = somma media_i; V = somma var_i; std = sqrt(V);
      z = Phi^-1(alpha) < 0; var_perdita = -(M + z*std) (come tab468);
      capitale = max(0, var_perdita) * mult.
    Componente Euleriana (somma = var_perdita, esatta nell'approx):
      comp_i = d(var_perdita)/d(w_i) a pesi 1
             = -(media_i + z*var_i/std)
      (w_i scala il P&L del segnale i: media_i*w_i, var_i*w_i^2).
    quota_i = comp_i / var_perdita (0 se var_perdita == 0).
    What-if taglio: var_perdita_wo_i = -((M-media_i) + z*sqrt(V-var_i));
      capitale_wo_i = max(0, var_perdita_wo_i)*mult;
      risparmio_i = capitale - capitale_wo_i (capitale liberato tagliando
      il segnale i; NEGATIVO se il segnale diversifica: tagliarlo
      AUMENTA il capitale richiesto).
    top: segnale con comp_i massima ("il piu' goloso").
    beneficio_diversificazione = somma_i max(0, var_perdita_i)*mult
      - capitale (>= 0: in approx normale a segnali indipendenti la
      diversificazione non aumenta mai il capitale).
    Note oneste: come tab468 (approx normale, code pesanti non
      modellate); decomposizione esatta solo nell'approx normale;
      segnali indipendenti (correlazione: vedi tab465)."""
    import math
    if not isinstance(segnali, (list, tuple)) or len(segnali) == 0:
        raise ValueError("componenti: serve una lista non vuota di segnali")
    _al = mh469_num(alpha, "alpha")
    _ml = mh469_num(mult, "mult")
    if not 0.0 < _al < 0.5:
        raise ValueError("componenti: alpha deve stare in (0, 0.5)")
    if _ml < 1.0:
        raise ValueError("componenti: mult deve essere >= 1")
    _z = mh468_phi_inv(_al)
    _nomi, _medie, _vars = [], [], []
    for _s in segnali:
        if not isinstance(_s, (list, tuple)) or len(_s) != 4:
            raise ValueError(
                "componenti: ogni segnale e' (nome, lam, mu, sigma)")
        _nome, _lam, _mu, _sg = _s
        if not isinstance(_nome, str) or not _nome:
            raise ValueError("componenti: nome segnale non valido")
        _lam = mh469_num(_lam, "lam")
        _mu = mh469_num(_mu, "mu")
        _sg = mh469_num(_sg, "sigma")
        if _lam <= 0.0:
            raise ValueError("componenti: lam deve essere > 0")
        if _sg < 0.0:
            raise ValueError("componenti: sigma non puo' essere negativo")
        _nomi.append(_nome)
        _medie.append(_lam * _mu)
        _vars.append(_lam * (_sg * _sg + _mu * _mu))
    _M = sum(_medie)
    _V = sum(_vars)
    _std = math.sqrt(_V)
    if _std <= 0.0:
        raise ValueError("componenti: varianza di portafoglio nulla")
    _vp = -(_M + _z * _std)
    _cap = max(0.0, _vp) * _ml
    _righe = []
    for _i, _nome in enumerate(_nomi):
        _comp = -(_medie[_i] + _z * _vars[_i] / _std)
        _quota = _comp / _vp if _vp != 0.0 else 0.0
        _vp_wo = -((_M - _medie[_i]) + _z * math.sqrt(_V - _vars[_i]))
        _cap_wo = max(0.0, _vp_wo) * _ml
        _righe.append({
            "nome": _nome,
            "media": _medie[_i],
            "var": _vars[_i],
            "std": math.sqrt(_vars[_i]),
            "componente": _comp,
            "quota": _quota,
            "var_perdita_wo": _vp_wo,
            "capitale_wo": _cap_wo,
            "risparmio": _cap - _cap_wo,
        })
    _top = max(range(len(_righe)),
               key=lambda _i: _righe[_i]["componente"])
    _ben = sum(max(0.0, -(_medie[_i] + _z * math.sqrt(_vars[_i])))
               for _i in range(len(_righe))) * _ml - _cap
    return {
        "righe": _righe,
        "media_tot": _M,
        "var_tot": _V,
        "std_tot": _std,
        "z_alpha": _z,
        "var_perdita": _vp,
        "capitale": _cap,
        "top": _righe[_top]["nome"],
        "top_idx": _top,
        "quota_top": _righe[_top]["quota"],
        "risparmio_top": _righe[_top]["risparmio"],
        "beneficio_diversificazione": _ben,
        "n_segnali": len(_righe),
        "alpha": _al,
        "mult": _ml,
    }


def mh469_verdetto(comp):
    """Chi mangia il capitale? Verdetto operativo sulla scomposizione.

    comp: dict da mh469_componenti. Se capitale <= 0: NESSUN CAPITALE
    RICHIESTO (nessun segnale da tagliare); altrimenti nomina "il piu'
    goloso" (componente max) con quota sul capitale e l'effetto del
    taglio (a quanto scende il capitale)."""
    if not isinstance(comp, dict) or "righe" not in comp:
        raise ValueError("verdetto: serve il dict di mh469_componenti")
    _righe = comp["righe"]
    if len(_righe) == 0:
        raise ValueError("verdetto: nessun segnale da valutare")
    _cap = mh469_num(comp.get("capitale", 0.0), "capitale")
    if _cap < 0.0:
        raise ValueError("verdetto: capitale non puo' essere negativo")
    if _cap <= 0.0:
        return ("NESSUN CAPITALE RICHIESTO \u2014 VaR di portafoglio "
                "\u2264 0: la coda resta in utile, nessun segnale da "
                "tagliare")
    _top = max(_righe, key=lambda _r: _r["componente"])
    return (f"CHI MANGIA IL CAPITALE \u2014 {_top['nome']} assorbe "
            f"{_top['quota']:.0%} del capitale "
            f"({_top['componente']:,.0f} EUR); tagliandolo il capitale "
            f"scende a {_top['capitale_wo']:,.0f} EUR "
            f"(\u0394 {_top['risparmio']:+,.0f} EUR)")

def mh468_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh468_phi(z):
    """CDF della normale standard (via erf)."""
    import math
    _z = mh468_num(z, "z")
    return 0.5 * (1.0 + math.erf(_z / math.sqrt(2.0)))


def mh468_phi_inv(p):
    """Quantile della normale standard (inversa della CDF)."""
    import statistics
    _p = mh468_num(p, "p")
    if not 0.0 < _p < 1.0:
        raise ValueError("phi_inv: p deve stare in (0, 1)")
    return statistics.NormalDist().inv_cdf(_p)


def mh468_rischio(lam, mu, sigma, alpha=0.01, mult=1.0):
    """VaR/ES annuali del P&L e capitale di rischio (approx normale).

    lam: tasso di segnali/anno (> 0); mu: netto medio per trade (EUR,
      da tab466 in produzione); sigma: std del netto per trade (EUR,
      >= 0); alpha: probabilita' di coda (0 < alpha < 0.5, default
      0.01 = quantile 1%); mult: moltiplicatore di prudenza (>= 1).
    media = lam*mu; var = lam*(sigma^2 + mu^2) (compound Poisson,
      come tab467); std = sqrt(var); z = Phi^-1(alpha) (< 0);
    var_perdita = -(media + z*std): perdita al quantile alpha
      (negativa = la coda resta in utile, nessun capitale richiesto);
    capitale = max(0, var_perdita) * mult;
    es = -media + std*phi(z)/alpha: Expected Shortfall della perdita
      (media della perdita oltre il VaR; es >= var_perdita per la
      proprieta' di Mills).
    Note oneste: approx normale (code pesanti non modellate); il
      capitale copre la perdita al quantile alpha, NON lo scenario
      peggiore; mu/sigma vanno stimati sullo storico dei trade."""
    import math
    _lam = mh468_num(lam, "lam")
    _mu = mh468_num(mu, "mu")
    _sg = mh468_num(sigma, "sigma")
    _al = mh468_num(alpha, "alpha")
    _ml = mh468_num(mult, "mult")
    if _lam <= 0.0:
        raise ValueError("rischio: lam deve essere > 0")
    if _sg < 0.0:
        raise ValueError("rischio: sigma non puo' essere negativo")
    if not 0.0 < _al < 0.5:
        raise ValueError("rischio: alpha deve stare in (0, 0.5)")
    if _ml < 1.0:
        raise ValueError("rischio: mult deve essere >= 1")
    _media = _lam * _mu
    _var = _lam * (_sg * _sg + _mu * _mu)
    _std = math.sqrt(_var)
    _z = mh468_phi_inv(_al)
    _vp = -(_media + _z * _std)
    _cap = max(0.0, _vp) * _ml
    _pdf = math.exp(-_z * _z / 2.0) / math.sqrt(2.0 * math.pi)
    _es = -_media + _std * _pdf / _al
    return {
        "lam": _lam,
        "mu": _mu,
        "sigma": _sg,
        "alpha": _al,
        "mult": _ml,
        "media_annua": _media,
        "var_annua": _var,
        "std_annua": _std,
        "z_alpha": _z,
        "var_perdita": _vp,
        "capitale": _cap,
        "es": _es,
    }


def mh468_verdetto(capitale_richiesto, capitale_disp):
    """Adeguatezza del capitale di rischio del desk.

    capitale_richiesto >= 0 (da mh468_rischio, include gia' mult);
    capitale_disp >= 0 (budget del desk, EUR).
    NON RICHIESTO (richiesto <= 0: VaR <= 0, la coda resta in utile) /
    COPERTO (copertura >= 100%) / MARGINALE (copertura >= 50%) /
    SOTTO-CAPITALIZZATO. copertura = disp / richiesto."""
    _cr = mh468_num(capitale_richiesto, "capitale_richiesto")
    _cd = mh468_num(capitale_disp, "capitale_disp")
    if _cr < 0.0:
        raise ValueError("verdetto: capitale_richiesto non puo' "
                         "essere negativo")
    if _cd < 0.0:
        raise ValueError("verdetto: capitale_disp non puo' essere "
                         "negativo")
    if _cr <= 0.0:
        return ("NON RICHIESTO \u2014 VaR \u2264 0: la coda resta in "
                "utile, nessun capitale di rischio necessario")
    _cov = _cd / _cr
    if _cov >= 1.0:
        return f"COPERTO \u2014 copertura {_cov:.0%}"
    if _cov >= 0.5:
        return f"MARGINALE \u2014 copertura {_cov:.0%}"
    return f"SOTTO-CAPITALIZZATO \u2014 copertura {_cov:.0%}"


def mh468_mappa(segnali, capitale_disp, alpha=0.01, mult=1.0):
    """Applica il VaR annuale a una lista di segnali e al portafoglio.

    segnali: lista di (nome, lam, mu, sigma). Il portafoglio somma
      medie e varianze (segnali indipendenti) e ricalcola VaR, ES,
      capitale e verdetto sul totale."""
    if not isinstance(segnali, (list, tuple)) or len(segnali) == 0:
        raise ValueError("mappa: serve una lista non vuota di segnali")
    _cd = mh468_num(capitale_disp, "capitale_disp")
    if _cd < 0.0:
        raise ValueError("mappa: capitale_disp non puo' essere negativo")
    _righe = []
    for _s in segnali:
        if not isinstance(_s, (list, tuple)) or len(_s) != 4:
            raise ValueError(
                "mappa: ogni segnale e' (nome, lam, mu, sigma)")
        _nome, _lam, _mu, _sg = _s
        if not isinstance(_nome, str) or not _nome:
            raise ValueError("mappa: nome segnale non valido")
        _r = mh468_rischio(_lam, _mu, _sg, alpha=alpha, mult=mult)
        _v = mh468_verdetto(_r["capitale"], _cd)
        _righe.append({"nome": _nome, "rischio": _r, "verdetto": _v})
    _media_tot = sum(_r["rischio"]["media_annua"] for _r in _righe)
    _var_tot = sum(_r["rischio"]["var_annua"] for _r in _righe)
    import math as _math
    _std_tot = _math.sqrt(_var_tot)
    _z = mh468_phi_inv(mh468_num(alpha, "alpha"))
    _vp_tot = -(_media_tot + _z * _std_tot)
    _ml = mh468_num(mult, "mult")
    _cap_tot = max(0.0, _vp_tot) * _ml
    _pdf = _math.exp(-_z * _z / 2.0) / _math.sqrt(2.0 * _math.pi)
    _es_tot = -_media_tot + _std_tot * _pdf / mh468_num(alpha, "alpha")
    _vptf = mh468_verdetto(_cap_tot, _cd)
    return {
        "righe": _righe,
        "media_tot": _media_tot,
        "var_tot": _var_tot,
        "std_tot": _std_tot,
        "z_alpha": _z,
        "var_perdita_tot": _vp_tot,
        "capitale_tot": _cap_tot,
        "es_tot": _es_tot,
        "verdetto": _vptf,
        "n_segnali": len(_righe),
        "alpha": mh468_num(alpha, "alpha"),
        "mult": _ml,
        "capitale_disp": _cd,
    }

def mh467_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh467_phi(z):
    """CDF della normale standard (via erf)."""
    import math
    _z = mh467_num(z, "z")
    return 0.5 * (1.0 + math.erf(_z / math.sqrt(2.0)))


def mh467_annuo(lam, mu, sigma):
    """P&L annuo di un segnale ricorrente (compound Poisson).

    lam: tasso di segnali/anno (> 0); mu: netto medio per trade
      (EUR, da tab466 in produzione); sigma: std del netto per trade
      (EUR, >= 0).
    media = lam*mu; var = lam*(sigma^2 + mu^2) (compound Poisson:
      E[n] = Var[n] = lam); std = sqrt(var); p_neg = Phi(-media/std)
      in approx normale; n_target = n. segnali (a n fisso) per
      P(anno in rosso) <= 5%: ceil((1.6449*sigma/mu)^2) se mu > 0
      (1 se sigma == 0), None se mu <= 0.
    Note oneste: arrivi Poisson indipendenti; P(neg) in approx normale
      (code pesanti non modellate); mu/sigma vanno stimati sullo
      storico dei trade; i segnali nel portafoglio sono trattati come
      indipendenti."""
    import math
    _lam = mh467_num(lam, "lam")
    _mu = mh467_num(mu, "mu")
    _sg = mh467_num(sigma, "sigma")
    if _lam <= 0.0:
        raise ValueError("annuo: lam deve essere > 0")
    if _sg < 0.0:
        raise ValueError("annuo: sigma non puo' essere negativo")
    _media = _lam * _mu
    _var = _lam * (_sg * _sg + _mu * _mu)
    _std = math.sqrt(_var)
    if _std == 0.0:
        _p = 0.0 if _media > 0.0 else (1.0 if _media < 0.0 else 0.5)
    else:
        _p = mh467_phi(-_media / _std)
    if _mu <= 0.0:
        _nt = None
    elif _sg == 0.0:
        _nt = 1
    else:
        _nt = int(math.ceil((1.6449 * _sg / _mu) ** 2))
    return {
        "lam": _lam,
        "mu": _mu,
        "sigma": _sg,
        "media_annua": _media,
        "var_annua": _var,
        "std_annua": _std,
        "p_neg": _p,
        "n_target": _nt,
    }


def mh467_verdetto(mu, p_neg, soglia_acc=0.05, soglia_marg=0.30):
    """Classifica un segnale (o il portafoglio) in 4 stati.

    SENZA EDGE (mu <= 0) / MARGINALE (p_neg > soglia_marg) /
    ACCETTABILE (p_neg > soglia_acc) / SOLIDO. soglie in (0, 1) con
    0 < soglia_acc < soglia_marg < 1; default 0.05 / 0.30."""
    _mu = mh467_num(mu, "mu")
    _p = mh467_num(p_neg, "p_neg")
    _sa = mh467_num(soglia_acc, "soglia_acc")
    _sm = mh467_num(soglia_marg, "soglia_marg")
    if not 0.0 < _sa < _sm < 1.0:
        raise ValueError("verdetto: serve 0 < soglia_acc < soglia_marg < 1")
    if not 0.0 <= _p <= 1.0:
        raise ValueError("verdetto: p_neg deve stare in [0, 1]")
    if _mu <= 0.0:
        return "SENZA EDGE"
    if _p > _sm:
        return f"MARGINALE — P(anno in rosso) = {_p:.0%}"
    if _p > _sa:
        return f"ACCETTABILE — P(anno in rosso) = {_p:.0%}"
    return f"SOLIDO — P(anno in rosso) = {_p:.1%}"


def mh467_mappa(segnali, soglia_acc=0.05, soglia_marg=0.30):
    """Applica l'annualizzazione a una lista di segnali e al portafoglio.

    segnali: lista di (nome, lam, mu, sigma). Il portafoglio somma
      medie e varianze (segnali indipendenti) e ricalcola p_neg e
      verdetto sul totale."""
    if not isinstance(segnali, (list, tuple)) or len(segnali) == 0:
        raise ValueError("mappa: serve una lista non vuota di segnali")
    _righe = []
    for _s in segnali:
        if not isinstance(_s, (list, tuple)) or len(_s) != 4:
            raise ValueError(
                "mappa: ogni segnale e' (nome, lam, mu, sigma)")
        _nome, _lam, _mu, _sg = _s
        if not isinstance(_nome, str) or not _nome:
            raise ValueError("mappa: nome segnale non valido")
        _a = mh467_annuo(_lam, _mu, _sg)
        _v = mh467_verdetto(_a["mu"], _a["p_neg"], soglia_acc,
                            soglia_marg)
        _righe.append({"nome": _nome, "annuo": _a, "verdetto": _v})
    _media_tot = sum(_r["annuo"]["media_annua"] for _r in _righe)
    _var_tot = sum(_r["annuo"]["var_annua"] for _r in _righe)
    import math as _math
    _std_tot = _math.sqrt(_var_tot)
    if _std_tot == 0.0:
        _p_tot = (0.0 if _media_tot > 0.0
                  else (1.0 if _media_tot < 0.0 else 0.5))
    else:
        _p_tot = mh467_phi(-_media_tot / _std_tot)
    _mu_medio = (_media_tot / sum(_r["annuo"]["lam"] for _r in _righe)
                 if sum(_r["annuo"]["lam"] for _r in _righe) > 0.0
                 else 0.0)
    _vptf = mh467_verdetto(_mu_medio, _p_tot, soglia_acc, soglia_marg)
    return {
        "righe": _righe,
        "media_tot": _media_tot,
        "var_tot": _var_tot,
        "std_tot": _std_tot,
        "p_neg_tot": _p_tot,
        "verdetto": _vptf,
        "n_segnali": len(_righe),
    }

def mh466_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh466_costi(edge_lordo, qty_mwh, bidask, comm, funding_bps, giorni,
                capitale):
    """Costi veri di un trade e P&L netto.

    edge_lordo: P&L atteso LORDO (EUR) — in produzione da
      mh464_mappa/mh465_mappa (righe alloc_corr: "edge").
    qty_mwh: quantita' negoziata (MWh, > 0).
    bidask: bid-ask spread (EUR/MWh); costo_spread = qty * bidask
      (round-trip: mezzo spread in entrata + mezzo in uscita).
    comm: commissione per lato (EUR); costo_comm = 2 * comm
      (apertura + chiusura).
    funding_bps: costo del capitale in bps/anno; costo_funding =
      capitale * funding_bps/10000 * giorni/365 (pro-rata temporis,
      lineare: ignora il compounding).
    giorni: durata attesa del trade; capitale: capitale impegnato (EUR).
    Ritorna il dict con costo_spread, costo_comm, costo_funding,
    costi_totali, netto (= edge_lordo - costi_totali), frazione
    (= netto/edge_lordo, None se edge_lordo <= 0), costo_per_mwh e
    breakeven_per_mwh (edge per MWh minimo per non perdere).
    Note oneste: bid-ask = stima (sotto stress si allarga); slippage
    di esecuzione non modellato."""
    _e = mh466_num(edge_lordo, "edge_lordo")
    _q = mh466_num(qty_mwh, "qty_mwh")
    _b = mh466_num(bidask, "bidask")
    _c = mh466_num(comm, "comm")
    _f = mh466_num(funding_bps, "funding_bps")
    _g = mh466_num(giorni, "giorni")
    _K = mh466_num(capitale, "capitale")
    if _q <= 0.0:
        raise ValueError("costi: qty_mwh deve essere > 0")
    for _v, _n in ((_b, "bidask"), (_c, "comm"), (_f, "funding_bps"),
                   (_g, "giorni"), (_K, "capitale")):
        if _v < 0.0:
            raise ValueError(f"costi: {_n} non puo' essere negativo")
    _costo_spread = _q * _b
    _costo_comm = 2.0 * _c
    _costo_funding = _K * (_f / 10000.0) * (_g / 365.0)
    _tot = _costo_spread + _costo_comm + _costo_funding
    _net = _e - _tot
    return {
        "edge_lordo": _e,
        "qty_mwh": _q,
        "costo_spread": _costo_spread,
        "costo_comm": _costo_comm,
        "costo_funding": _costo_funding,
        "costi_totali": _tot,
        "netto": _net,
        "frazione": (_net / _e) if _e > 0.0 else None,
        "costo_per_mwh": _tot / _q,
        "breakeven_per_mwh": _tot / _q,
    }


def mh466_verdetto(netto, edge_lordo, soglia=0.5):
    """Classifica un trade (o il portafoglio) in 4 stati.

    SENZA EDGE (edge_lordo <= 0) / NON REGGE (netto <= 0) /
    MARGINE SOTTILE (resta meno di soglia dell'edge) / REGGE.
    soglia in (0, 1), default 0.5: il trade deve tenere almeno meta'
    dell'edge dopo i costi."""
    _n = mh466_num(netto, "netto")
    _e = mh466_num(edge_lordo, "edge_lordo")
    _s = mh466_num(soglia, "soglia")
    if not 0.0 < _s < 1.0:
        raise ValueError("verdetto: soglia deve stare in (0, 1)")
    if _e <= 0.0:
        return "SENZA EDGE"
    if _n <= 0.0:
        return "NON REGGE"
    if _n / _e < _s:
        return f"MARGINE SOTTILE — resta {_n / _e:.0%} dell'edge"
    return f"REGGE — resta {_n / _e:.0%} dell'edge"


def mh466_mappa(trades, bidask, comm, funding_bps, giorni, soglia=0.5):
    """Applica i costi a una lista di trade e al portafoglio.

    trades: lista di (nome, edge_lordo, qty_mwh, capitale).
    Ritorna righe (per trade: costi + verdetto), totali di
    portafoglio (edge_lordo_tot, costi_tot, netto_tot, frazione_tot)
    e verdetto di portafoglio."""
    if not isinstance(trades, (list, tuple)) or len(trades) == 0:
        raise ValueError("mappa: serve una lista non vuota di trade")
    _righe = []
    for _t in trades:
        if not isinstance(_t, (list, tuple)) or len(_t) != 4:
            raise ValueError(
                "mappa: ogni trade e' (nome, edge_lordo, qty_mwh, capitale)")
        _nome, _e, _q, _K = _t
        if not isinstance(_nome, str) or not _nome:
            raise ValueError("mappa: nome trade non valido")
        _cc = mh466_costi(_e, _q, bidask, comm, funding_bps, giorni, _K)
        _v = mh466_verdetto(_cc["netto"], _cc["edge_lordo"], soglia)
        _righe.append({"nome": _nome, "costi": _cc, "verdetto": _v})
    _edge_tot = sum(_r["costi"]["edge_lordo"] for _r in _righe)
    _costi_tot = sum(_r["costi"]["costi_totali"] for _r in _righe)
    _net_tot = sum(_r["costi"]["netto"] for _r in _righe)
    _vptf = mh466_verdetto(_net_tot, _edge_tot, soglia)
    return {
        "righe": _righe,
        "edge_lordo_tot": _edge_tot,
        "costi_tot": _costi_tot,
        "netto_tot": _net_tot,
        "frazione_tot": (_net_tot / _edge_tot) if _edge_tot > 0.0 else None,
        "verdetto": _vptf,
        "n_trade": len(_righe),
    }

def mh465_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh465_dspread(seed_gas, seed_spread, beta, direzione, n=60):
    """Driver del P&L per-step di una coppia: direzione * Delta(spread).

    spread_t = power_t - beta * gas_t con le serie deterministiche di
    mh464_serie(seed_gas, seed_spread, n); direzione "long ..."/"short ..."
    (stringa di mh463_mappa: segno +1/-1). Ritorna la tupla di n-1
    valori dir * (spread_t - spread_{t-1}): a meno di costanti positive
    (h*, size) e' il P&L incrementale del trade, quindi la correlazione
    tra queste serie e' la correlazione tra i P&L dei trade.
    Nota onesta: ignora il profilo di uscita a tranche (tab463) — stima
    il comovimento del driver dominante, non del P&L realizzato."""
    _power, _gas = mh464_serie(seed_gas, seed_spread, n=n)
    _b = mh465_num(beta, "beta")
    if not isinstance(direzione, str):
        raise ValueError(f"dspread: direzione non valida {direzione!r}")
    if direzione.startswith("long"):
        _d = 1.0
    elif direzione.startswith("short"):
        _d = -1.0
    else:
        raise ValueError("dspread: direzione deve iniziare con "
                         f"'long'/'short' (trovato {direzione!r})")
    _sp = [_p - _b * _g for _p, _g in zip(_power, _gas)]
    return tuple(_d * (_sp[_t] - _sp[_t - 1])
                 for _t in range(1, len(_sp)))


def mh465_corr(series):
    """Matrice di correlazione di Pearson tra serie.

    series: lista non vuota di tuple di uguale lunghezza (>= 2 punti).
    Ritorna la matrice n x n come lista di liste (diagonale 1.0,
    simmetrica). Serie a varianza nulla -> ValueError (correlazione non
    definita)."""
    if not isinstance(series, (list, tuple)) or len(series) == 0:
        raise ValueError("corr: serve una lista non vuota di serie")
    import math
    _ss = [list(_s) for _s in series]
    _n = len(_ss[0])
    if _n < 2:
        raise ValueError("corr: ogni serie deve avere almeno 2 punti")
    for _i, _s in enumerate(_ss):
        if len(_s) != _n:
            raise ValueError(f"corr: serie {_i} di lunghezza "
                             f"diversa ({len(_s)} != {_n})")
        for _x in _s:
            mh465_num(_x, f"serie[{_i}]")
    _m = len(_ss)
    _mean = [sum(_s) / _n for _s in _ss]
    _dev = [[_x - _mu for _x in _s] for _s, _mu in zip(_ss, _mean)]
    _var = [sum(_d * _d for _d in _dd) for _dd in _dev]
    for _i, _vv in enumerate(_var):
        if _vv <= 0.0:
            raise ValueError(f"corr: serie {_i} a varianza nulla")
    _C = [[0.0] * _m for _ in range(_m)]
    for _i in range(_m):
        for _j in range(_m):
            _cv = sum(_a * _b for _a, _b in zip(_dev[_i], _dev[_j]))
            _C[_i][_j] = _cv / math.sqrt(_var[_i] * _var[_j])
    return _C


def _mh465_chol(A, b):
    """Risolve A x = b con Cholesky (A simmetrica definita positiva,
    lista di liste n x n). Solleva ValueError se A non e' d.p."""
    import math
    _n = len(A)
    _L = [[0.0] * _n for _ in range(_n)]
    for _i in range(_n):
        for _j in range(_i + 1):
            _s = A[_i][_j] - sum(_L[_i][_k] * _L[_j][_k]
                                 for _k in range(_j))
            if _i == _j:
                if _s <= 0.0:
                    raise ValueError("chol: matrice non definita positiva")
                _L[_i][_j] = math.sqrt(_s)
            else:
                _L[_i][_j] = _s / _L[_j][_j]
    _y = [0.0] * _n
    for _i in range(_n):
        _y[_i] = (b[_i] - sum(_L[_i][_k] * _y[_k]
                               for _k in range(_i))) / _L[_i][_i]
    _x = [0.0] * _n
    for _i in range(_n - 1, -1, -1):
        _x[_i] = (_y[_i] - sum(_L[_k][_i] * _x[_k]
                               for _k in range(_i + 1, _n))) / _L[_i][_i]
    return _x


def _mh465_S(u, C, eps):
    """Covarianza in EUR^2: S_ij = u_i u_j C~_ij con
    C~ = (1-eps) C + eps I (ridge: resta definita positiva anche con
    driver quasi-identici, es. stessa seed di spread)."""
    _n = len(u)
    return [[u[_i] * u[_j] * ((1.0 - eps) * C[_i][_j]
                              + (eps if _i == _j else 0.0))
             for _j in range(_n)] for _i in range(_n)]


def mh465_alloc(mus, sigmas, f_apps, corr, K, rb, f_max, eps=1e-6):
    """Allocazione mean-variance con covarianza PIENA e cap per trade.

    Massimizza l'edge atteso Σ g_i e_i sotto il budget di rischio
    g' S g <= (rb K)^2 e 0 <= g_i <= f_max, dove g_i e' la frazione di
    capitale K sul trade i, e_i = mu_i / f_app_i l'edge in EUR per
    unita' di g, S_ij = u_i u_j C~_ij la covarianza in EUR^2 con
    u_i = sigma_i / f_app_i e C~ la correlazione con ridge eps
    (u_i e' la vol in EUR per unita' di g).
    Risoluzione per enumerazione dei pattern (ogni trade libero / a 0 /
    a f_max: 3^n): sul free set la forma e' chiusa (completamento del
    quadrato per il budget residuo, Cholesky), e il miglior punto del
    pattern dentro i bound e' un candidato ammissibile. Il vero ottimo
    del QP convesso appartiene al suo pattern e la forma chiusa lo
    restituisce esattamente -> il max sui candidati E' l'ottimo
    globale (nessuna euristica greedy: anche i bound "spuri",
    che nel rilassato sembrano violati solo per via dell'hedge,
    vengono risolti dal pattern corretto).
    Con corr = I coincide con mh464_alloc (chiave di coerenza, 1e-12).
    Tutti i mu devono essere > 0 (l'edge negativo non si alloca mai).
    Ritorna dict: righe (una per trade: mu, sigma, f_app, g, eur,
    edge, capped, floored), edge_tot, var_tot, rb_usato, sharpe,
    n_capped, n_floored."""
    _n = len(mus)
    for _v, _nn in ((mus, "mus"), (sigmas, "sigmas"),
                    (f_apps, "f_apps")):
        if not isinstance(_v, (list, tuple)) or len(_v) == 0:
            raise ValueError(f"alloc: {_nn} deve essere una lista non vuota")
    if not (len(sigmas) == _n and len(f_apps) == _n):
        raise ValueError("alloc: mus, sigmas e f_apps devono avere la "
                         "stessa lunghezza")
    if _n > 10:
        raise ValueError("alloc: troppe coppie per l'enumerazione "
                         f"(3^{_n} pattern, max 10)")
    if not isinstance(corr, (list, tuple)) or len(corr) != _n:
        raise ValueError("alloc: corr deve essere una matrice n x n")
    for _i, _row in enumerate(corr):
        if not isinstance(_row, (list, tuple)) or len(_row) != _n:
            raise ValueError(f"alloc: riga corr {_i} non n x n")
    _K = mh465_num(K, "K")
    if _K <= 0.0:
        raise ValueError(f"alloc: K deve essere > 0 (trovato {_K})")
    _rb = mh465_num(rb, "rb")
    if _rb <= 0.0 or _rb > 1.0:
        raise ValueError(f"alloc: rb deve stare in (0, 1] (trovato {_rb})")
    _fm = mh465_num(f_max, "f_max")
    if _fm <= 0.0 or _fm > 1.0:
        raise ValueError(f"alloc: f_max deve stare in (0, 1] "
                         f"(trovato {_fm})")
    _ep = mh465_num(eps, "eps")
    if _ep <= 0.0 or _ep > 0.01:
        raise ValueError(f"alloc: eps deve stare in (0, 0.01] "
                         f"(trovato {_ep})")
    _mu = [mh465_num(_x, f"mu[{_i}]") for _i, _x in enumerate(mus)]
    _sg = [mh465_num(_x, f"sigma[{_i}]") for _i, _x in enumerate(sigmas)]
    _fa = [mh465_num(_x, f"f_app[{_i}]") for _i, _x in enumerate(f_apps)]
    _C = [[mh465_num(_c, f"corr[{_i}][{_j}]")
           for _j, _c in enumerate(_row)] for _i, _row in enumerate(corr)]
    for _i in range(_n):
        if _mu[_i] <= 0.0:
            raise ValueError(f"alloc: mu[{_i}] deve essere > 0 "
                             f"(trovato {_mu[_i]})")
        if _sg[_i] <= 0.0:
            raise ValueError(f"alloc: sigma[{_i}] deve essere > 0 "
                             f"(trovato {_sg[_i]})")
        if _fa[_i] <= 0.0:
            raise ValueError(f"alloc: f_app[{_i}] deve essere > 0 "
                             f"(trovato {_fa[_i]})")
        for _j in range(_n):
            if abs(_C[_i][_j]) > 1.0 + 1e-12:
                raise ValueError(f"alloc: |corr[{_i}][{_j}]| > 1 "
                                 f"(trovato {_C[_i][_j]})")
    import math
    _u = [_sg[_i] / _fa[_i] for _i in range(_n)]
    _e = [_mu[_i] / _fa[_i] for _i in range(_n)]
    _S = _mh465_S(_u, _C, _ep)
    _B = _rb * _K
    _B2 = _B * _B
    _tol_b = 1e-9
    _best = None  # (edge, g, capped, floored)
    for _pat in range(3 ** _n):
        _tmp = _pat
        _st = []
        for _i in range(_n):
            _st.append(_tmp % 3)
            _tmp //= 3
        # _st: 0 = libero, 1 = fissato a 0, 2 = fissato a f_max
        _free = [_i for _i in range(_n) if _st[_i] == 0]
        _fx = {_i: (0.0 if _st[_i] == 1 else _fm)
               for _i in range(_n) if _st[_i] != 0}
        if not _free:
            _g = [_fx[_i] for _i in range(_n)]
            _var = sum(_g[_i] * _S[_i][_j] * _g[_j]
                       for _i in range(_n) for _j in range(_n))
            if _var > _B2 * (1.0 + 1e-9):
                continue
            _edge = sum(_g[_i] * _e[_i] for _i in range(_n))
            if _best is None or _edge > _best[0]:
                _best = (_edge, _g,
                         [_st[_i] == 2 for _i in range(_n)],
                         [_st[_i] == 1 for _i in range(_n)])
            continue
        _m = len(_free)
        _Aff = [[_S[_free[_a]][_free[_b]]
                 for _b in range(_m)] for _a in range(_m)]
        _ef = [_e[_free[_a]] for _a in range(_m)]
        _v = [sum(_S[_free[_a]][_k] * _gv for _k, _gv in _fx.items())
              for _a in range(_m)]
        try:
            _w = _mh465_chol(_Aff, _v) if any(_v) else [0.0] * _m
        except ValueError:
            continue
        _c0 = sum(_fx[_k] * _S[_k][_l] * _fx[_l]
                  for _k in _fx for _l in _fx)
        _B2p = _B2 - _c0 + sum(_vv * _ww for _vv, _ww in zip(_v, _w))
        if _B2p <= 1e-12 * _B2:
            # i fissati saturano (quasi) da soli il budget: unico punto
            # ammissibile del pattern = min-risk point g_free = -w
            _gf = [-_x for _x in _w]
        else:
            _Bp = math.sqrt(_B2p)
            try:
                _y = _mh465_chol(_Aff, _ef)
            except ValueError:
                continue
            _den2 = sum(_ee * _yy for _ee, _yy in zip(_ef, _y))
            if _den2 <= 0.0:
                continue
            _den = math.sqrt(_den2)
            _h = [_Bp * _yy / _den for _yy in _y]
            _gf = [_hh - _ww for _hh, _ww in zip(_h, _w)]
        if any(_x < -_tol_b or _x > _fm + _tol_b for _x in _gf):
            continue  # bound del free violato: il punto sta nel pattern
            # con quei var fissati, gia' enumerato
        _g = [0.0] * _n
        for _a in range(_m):
            _g[_free[_a]] = min(max(_gf[_a], 0.0), _fm)
        for _i, _vv in _fx.items():
            _g[_i] = _vv
        _var = sum(_g[_i] * _S[_i][_j] * _g[_j]
                   for _i in range(_n) for _j in range(_n))
        if _var > _B2 * (1.0 + 1e-9):
            continue
        _edge = sum(_g[_i] * _e[_i] for _i in range(_n))
        if _best is None or _edge > _best[0]:
            _best = (_edge, _g,
                     [_st[_i] == 2 for _i in range(_n)],
                     [_st[_i] == 1 for _i in range(_n)])
    if _best is None:
        raise ValueError("alloc: nessun pattern ammissibile")
    _edge, _g, _capped, _floored = _best
    _var = sum(_g[_i] * _S[_i][_j] * _g[_j]
               for _i in range(_n) for _j in range(_n))
    assert _var <= _B2 * (1.0 + 1e-9), "alloc: invariante budget violata"
    _righe = [{"mu": _mu[_i], "sigma": _sg[_i], "f_app": _fa[_i],
               "g": _g[_i], "eur": _g[_i] * _K,
               "edge": _g[_i] * _e[_i],
               "capped": _capped[_i], "floored": _floored[_i]}
              for _i in range(_n)]
    return {"righe": _righe, "edge_tot": _edge, "var_tot": _var,
            "rb_usato": math.sqrt(_var) / _K,
            "sharpe": _edge / math.sqrt(_var) if _var > 0.0 else 0.0,
            "n_capped": sum(1 for _c in _capped if _c),
            "n_floored": sum(1 for _f in _floored if _f)}


def mh465_verdetto(mappa):
    """Verdetto a 3 stati sulla correlazione dei trade:
    NESSUN TRADE (mappa None: nessuna coppia con trade allocabile),
    CORRELATI (max |rho| >= soglia_corr oppure il rischio vero
    dell'allocazione tab464 supera soglia_rischio x il budget: la
    diversificazione di tab464 e' illusoria su questi driver),
    INDIPENDENTI (correlazioni basse e rischio vero in linea col
    budget: l'ipotesi di indipendenza di tab464 regge).
    mappa: dict di mh465_mappa (o None)."""
    if mappa is None:
        return ("NESSUN TRADE — nessuna coppia con un trade allocabile: "
                "il desk non misura correlazioni sul vuoto.")
    if not isinstance(mappa, dict):
        raise ValueError("verdetto: mappa deve essere il dict di "
                         "mh465_mappa (o None)")
    if mappa.get("alloc_corr") is None:
        return ("NESSUN TRADE — nessuna coppia con un trade allocabile: "
                "il desk non misura correlazioni sul vuoto.")
    _cm = mappa["corr_max"]
    _rp = mappa["rapporto"]
    _sc = mappa["soglia_corr"]
    _sr = mappa["soglia_rischio"]
    if _cm >= _sc or _rp >= _sr:
        return (f"CORRELATI — max |rho| = {_cm:.2f} (soglia {_sc:.2f}), "
                f"rischio vero dell'allocazione tab464 = {_rp:.2f}x il "
                f"budget (soglia {_sr:.2f}x): i trade si muovono insieme, "
                f"la diversificazione e' illusoria — usare l'allocazione "
                f"corretta qui sotto.")
    return (f"INDIPENDENTI — max |rho| = {_cm:.2f} < {_sc:.2f}, rischio "
            f"vero = {_rp:.2f}x il budget: l'ipotesi di indipendenza di "
            f"tab464 regge, la diversificazione e' reale.")


def mh465_mappa(coppie, K=1000000.0, rb=0.05, f_max=0.25,
                z_entry=1.0, costo=0.20, H=10,
                soglia_corr=0.5, soglia_rischio=1.15, eps=1e-6):
    """Mappa completa: correlazione tra i trade + allocazione corretta.

    coppie: lista non vuota di (nome, seed_gas, seed_spread) con nomi
    unici. Per ciascuna la pipeline tab463 (mh464_coppia, nessun
    duplicato); sulle eligibili: serie driver via mh465_dspread,
    matrice di correlazione (mh465_corr), allocazione diagonale tab464
    (mh464_alloc, riusata), rischio vero dell'allocazione diagonale
    sotto la covarianza piena, allocazione con covarianza piena
    (mh465_alloc).
    Ritorna dict: coppie (righe mh464_coppia), eligibili (nomi), corr
    (matrice), corr_max, alloc_diag (mh464_alloc con 'nome' per riga),
    rischio_vero, rapporto (= rischio_vero / (rb K)), alloc_corr
    (mh465_alloc con 'nome' per riga, o None), soglia_corr,
    soglia_rischio, verdetto (mh465_verdetto)."""
    if not isinstance(coppie, (list, tuple)) or len(coppie) == 0:
        raise ValueError("mappa: serve una lista non vuota di "
                         "(nome, seed_gas, seed_spread)")
    _nomi = []
    for _i, _c in enumerate(coppie):
        try:
            _nm, _sg, _ss = _c
        except (TypeError, ValueError):
            raise ValueError(f"mappa: coppia {_i} malformata "
                             f"(serve (nome, seed_gas, seed_spread))")
        if not isinstance(_nm, str) or not _nm.strip():
            raise ValueError(f"mappa: nome coppia {_i} non valido")
        if _nm in _nomi:
            raise ValueError(f"mappa: nome coppia duplicato {_nm!r}")
        _nomi.append(_nm)
    _K = mh465_num(K, "K")
    if _K <= 0.0:
        raise ValueError(f"mappa: K deve essere > 0 (trovato {_K})")
    _rb = mh465_num(rb, "rb")
    if _rb <= 0.0 or _rb > 1.0:
        raise ValueError(f"mappa: rb deve stare in (0, 1] (trovato {_rb})")
    _fm = mh465_num(f_max, "f_max")
    if _fm <= 0.0 or _fm > 1.0:
        raise ValueError(f"mappa: f_max deve stare in (0, 1] "
                         f"(trovato {_fm})")
    _sc = mh465_num(soglia_corr, "soglia_corr")
    if _sc <= 0.0 or _sc >= 1.0:
        raise ValueError(f"mappa: soglia_corr deve stare in (0, 1) "
                         f"(trovato {_sc})")
    _sr = mh465_num(soglia_rischio, "soglia_rischio")
    if _sr < 1.0:
        raise ValueError(f"mappa: soglia_rischio deve essere >= 1 "
                         f"(trovato {_sr})")
    _ep = mh465_num(eps, "eps")
    if _ep <= 0.0 or _ep > 0.01:
        raise ValueError(f"mappa: eps deve stare in (0, 0.01] "
                         f"(trovato {_ep})")
    _righe = [mh464_coppia(_nm, _sg, _ss, K=_K, z_entry=z_entry,
                           costo=costo, H=H, f_max=_fm)
              for _nm, _sg, _ss in coppie]
    _elig = [_r for _r in _righe if _r["eligibile"] and _r["mu"] > 0.0]
    _base = {"coppie": _righe, "eligibili": [],
             "corr": None, "corr_max": 0.0, "alloc_diag": None,
             "rischio_vero": 0.0, "rapporto": 1.0, "alloc_corr": None,
             "soglia_corr": _sc, "soglia_rischio": _sr, "verdetto": ""}
    if not _elig:
        _base["verdetto"] = mh465_verdetto(None)
        return _base
    _enomi = [_r["nome"] for _r in _elig]
    _seed = {_nm: (_sg, _ss) for _nm, _sg, _ss in coppie}
    _series = [mh465_dspread(_seed[_nm][0], _seed[_nm][1],
                             _r["beta"], _r["direzione"])
               for _r, _nm in zip(_elig, _enomi)]
    _corr = mh465_corr(_series)
    _ne = len(_elig)
    _cm = max(abs(_corr[_i][_j])
              for _i in range(_ne) for _j in range(_ne)
              if _i != _j) if _ne > 1 else 0.0
    _mus = [_r["mu"] for _r in _elig]
    _sgs = [_r["sigma"] for _r in _elig]
    _fas = [_r["f_app"] for _r in _elig]
    _adiag = mh464_alloc(_mus, _sgs, _fas, _K, _rb, _fm)
    _u = [_sgs[_i] / _fas[_i] for _i in range(_ne)]
    _S = _mh465_S(_u, _corr, _ep)
    import math
    _gd = [_r["g"] for _r in _adiag["righe"]]
    _rv = math.sqrt(sum(_gd[_i] * _S[_i][_j] * _gd[_j]
                        for _i in range(_ne) for _j in range(_ne)))
    _acorr = mh465_alloc(_mus, _sgs, _fas, _corr, _K, _rb, _fm,
                         eps=_ep)
    for _r, _nm in zip(_adiag["righe"], _enomi):
        _r["nome"] = _nm
    for _r, _nm in zip(_acorr["righe"], _enomi):
        _r["nome"] = _nm
    _base.update({"eligibili": _enomi, "corr": _corr, "corr_max": _cm,
                  "alloc_diag": _adiag, "rischio_vero": _rv,
                  "rapporto": _rv / (_rb * _K), "alloc_corr": _acorr})
    _base["verdetto"] = mh465_verdetto(_base)
    return _base

def mh464_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh464_serie(seed_gas, seed_spread, n=60):
    """Serie demo deterministiche per una coppia di spread power-gas.

    gas: random walk da 40.0 con innovazioni N(0, 0.5^2), seed seed_gas;
    spread: AR(1) phi=0.6 da 0.0 con innovazioni N(0, 0.5^2),
    seed seed_spread;
    power = 1.5 * gas + spread + 55.0 (cointegrata per costruzione).
    Ritorna (power, gas): tuple di n livelli ciascuna.
    seed_gas/seed_spread: interi >= 0; n: intero >= 30."""
    import random
    for _s, _n in ((seed_gas, "seed_gas"), (seed_spread, "seed_spread")):
        if isinstance(_s, bool) or not isinstance(_s, int) or _s < 0:
            raise ValueError(f"serie: {_n} deve essere un intero >= 0 "
                             f"(trovato {_s!r})")
    if isinstance(n, bool) or not isinstance(n, int) or n < 30:
        raise ValueError(f"serie: n deve essere un intero >= 30 "
                         f"(trovato {n!r})")
    _rg = random.Random(seed_gas)
    _rs = random.Random(seed_spread)
    _gas = [40.0]
    for _ in range(1, n):
        _gas.append(_gas[-1] + _rg.gauss(0.0, 0.5))
    _sp = [0.0]
    for _ in range(1, n):
        _sp.append(0.6 * _sp[-1] + _rs.gauss(0.0, 0.5))
    _power = tuple(1.5 * _g + _s + 55.0 for _g, _s in zip(_gas, _sp))
    return _power, tuple(_gas)


def mh464_coppia(nome, seed_gas, seed_spread, K=1000000.0,
                 z_entry=1.0, costo=0.20, H=10, f_max=0.25):
    """Pipeline tab463 completa per una coppia candidata.

    Genera le serie con mh464_serie(seed_gas, seed_spread) e lancia
    mh463_mappa con i parametri del trade (stessi default della demo
    tab463; K = capitale di riferimento per il dimensionamento).
    Ritorna un dict con: nome, eligibile (bool), motivo (None se
    eligibile), beta, z, h_star, segnale, mu_pnl, sigma_pnl, f_app,
    size, direzione, mu (= netto atteso del MIGLIOR schedule di uscita
    tab463, EUR), sigma (= sigma_pnl, conservativo: non ridotto dal cap
    stop/target), sched_best, netto_best.
    Se mh463_mappa solleva ValueError (es. Johansen fallito) la coppia e'
    marcata non eligibile con il motivo, senza propagare l'errore.
    Nota onesta: mu usa l'uscita ottima ma sigma e' quello del trade
    senza cap — il rischio e' quindi sovrastimato, mai sottostimato."""
    if not isinstance(nome, str) or not nome.strip():
        raise ValueError(f"coppia: nome deve essere una stringa non vuota "
                         f"(trovato {nome!r})")
    _K = mh464_num(K, "K")
    if _K <= 0.0:
        raise ValueError(f"coppia: K deve essere > 0 (trovato {_K})")
    _power, _gas = mh464_serie(seed_gas, seed_spread)
    _base = {"nome": nome, "eligibile": False, "motivo": None,
             "beta": 0.0, "z": 0.0, "h_star": 0, "segnale": False,
             "mu_pnl": 0.0, "sigma_pnl": 0.0, "f_app": 0.0, "size": 0.0,
             "direzione": "", "mu": 0.0, "sigma": 0.0,
             "sched_best": "", "netto_best": 0.0}
    try:
        _m = mh463_mappa(_power, _gas, z_entry=z_entry, costo=costo, H=H,
                         capitale=_K, f_max=f_max,
                         ks_min=0.25, ks_max=3.0, n_ks=21,
                         kt_min=0.5, kt_max=4.0, n_kt=21,
                         vincola_pstop=False, p_stop_max=0.15,
                         tau_min=1.0, tau_max=10.0, n_tau=10,
                         costo_tempo=0.0)
    except ValueError as _e:
        _base["motivo"] = str(_e)
        return _base
    if _m["zero_motivo"] is not None or _m["scala"] is None:
        _base["motivo"] = (_m["zero_motivo"]
                           if _m["zero_motivo"] is not None
                           else "nessun trade identificato")
        _base.update({"beta": _m["beta"], "z": _m["z"],
                      "h_star": _m["h_star"], "segnale": _m["segnale"]})
        return _base
    _best = _m["scala"]["best"]
    _mu = float(_best["netto"])
    _sg = float(_m["sigma_pnl"])
    _fa = float(_m["f_app"])
    _elig = _mu > 0.0 and _sg > 0.0 and _fa > 0.0
    _base.update({"eligibile": _elig,
                  "motivo": None if _elig else "edge non positivo",
                  "beta": _m["beta"], "z": _m["z"],
                  "h_star": _m["h_star"], "segnale": _m["segnale"],
                  "mu_pnl": _m["mu_pnl"], "sigma_pnl": _m["sigma_pnl"],
                  "f_app": _fa, "size": _m["size"],
                  "direzione": _m["direzione"],
                  "mu": _mu, "sigma": _sg,
                  "sched_best": _best["sched"],
                  "netto_best": float(_best["netto"])})
    return _base


def mh464_alloc(mus, sigmas, f_apps, K, rb, f_max):
    """Allocazione mean-variance a covarianza diagonale con cap per trade.

    Massimizza l'edge atteso Σ g_i·rho_i sotto il budget di rischio
    Σ (g_i·s_i)² ≤ rb² e 0 ≤ g_i ≤ f_max, dove g_i e' la frazione di
    capitale K impiegata sul trade i, rho_i = mu_i/(f_app_i·K) l'edge
    per EUR impiegato e s_i = sigma_i/(f_app_i·K) la vol per EUR
    impiegato (f_app_i = frazione di riferimento del trade i).
    Soluzione chiusa sui trade non vincolati:
    g_i = rb_residuo · a_i / S', con a_i = mu_i·f_app_i·K/sigma_i² e
    S' = sqrt(Σ (mu_j/sigma_j)²); i cap si applicano in modo iterativo
    (fissa i vincolati a f_max, riottimizza il resto sul budget
    residuo — water-filling, converge alla soluzione esatta del QP
    diagonale). Il budget residuo resta sempre > 0: un trade viene
    cappato solo se l'ottimo non vincolato vuole g_i > f_max, e allora
    (f_max·s_i)² < rb_residuo² per costruzione — i cap non possono mai
    sforare il budget (il punto g = 0 e' sempre ammissibile).
    Tutti i mu devono essere > 0 (l'edge negativo non si alloca mai).
    Nota onesta: covarianza diagonale = trade assunti indipendenti; se
    gli spread sono correlati il rischio vero e' maggiore di var_tot.
    Ritorna dict: righe (una per trade: mu, sigma, f_app, rho, s, g,
    eur, edge, risk, capped), edge_tot, var_tot, rb_usato (= sqrt(var_tot)/K),
    sharpe (= edge_tot/sqrt(var_tot)), n_capped."""
    for _v, _n in ((mus, "mus"), (sigmas, "sigmas"),
                   (f_apps, "f_apps")):
        if not isinstance(_v, (list, tuple)) or len(_v) == 0:
            raise ValueError(f"alloc: {_n} deve essere una lista non vuota")
    _n = len(mus)
    if not (len(sigmas) == _n and len(f_apps) == _n):
        raise ValueError("alloc: mus, sigmas e f_apps devono avere la "
                         "stessa lunghezza")
    _K = mh464_num(K, "K")
    if _K <= 0.0:
        raise ValueError(f"alloc: K deve essere > 0 (trovato {_K})")
    _rb = mh464_num(rb, "rb")
    if _rb <= 0.0 or _rb > 1.0:
        raise ValueError(f"alloc: rb deve stare in (0, 1] (trovato {_rb})")
    _fm = mh464_num(f_max, "f_max")
    if _fm <= 0.0 or _fm > 1.0:
        raise ValueError(f"alloc: f_max deve stare in (0, 1] "
                         f"(trovato {_fm})")
    _mu = [mh464_num(_x, f"mu[{_i}]") for _i, _x in enumerate(mus)]
    _sg = [mh464_num(_x, f"sigma[{_i}]") for _i, _x in enumerate(sigmas)]
    _fa = [mh464_num(_x, f"f_app[{_i}]") for _i, _x in enumerate(f_apps)]
    for _i in range(_n):
        if _mu[_i] <= 0.0:
            raise ValueError(f"alloc: mu[{_i}] deve essere > 0 "
                             f"(trovato {_mu[_i]})")
        if _sg[_i] <= 0.0:
            raise ValueError(f"alloc: sigma[{_i}] deve essere > 0 "
                             f"(trovato {_sg[_i]})")
        if _fa[_i] <= 0.0:
            raise ValueError(f"alloc: f_app[{_i}] deve essere > 0 "
                             f"(trovato {_fa[_i]})")
    _g = [0.0] * _n
    _capped = [False] * _n
    while True:
        _R = [i for i in range(_n) if not _capped[i]]
        if not _R:
            break
        _usato = sum((_g[j] * _sg[j] / (_fa[j] * _K)) ** 2
                     for j in range(_n) if _capped[j])
        _rb2 = _rb * _rb - _usato
        # _rb2 > 0 sempre: un trade e' cappato solo se g_i non vincolato
        # > f_max, e allora (f_max·s_i)² < rb_residuo² (vedi docstring)
        assert _rb2 > 0.0, "alloc: invariante budget violata"
        _rb_r = _rb2 ** 0.5
        _S2 = sum((_mu[i] / _sg[i]) ** 2 for i in _R)
        _S = _S2 ** 0.5
        for i in _R:
            _a = _mu[i] * _fa[i] * _K / (_sg[i] ** 2)
            _g[i] = _rb_r * _a / _S
        _nuovi = [i for i in _R if _g[i] > _fm]
        if not _nuovi:
            break
        for i in _nuovi:
            _g[i] = _fm
            _capped[i] = True
    _righe = []
    for i in range(_n):
        _rho = _mu[i] / (_fa[i] * _K)
        _s = _sg[i] / (_fa[i] * _K)
        _eur = _g[i] * _K
        _edge = _g[i] * _rho * _K
        _risk = _g[i] * _s * _K
        _righe.append({"mu": _mu[i], "sigma": _sg[i], "f_app": _fa[i],
                       "rho": _rho, "s": _s, "g": _g[i], "eur": _eur,
                       "edge": _edge, "risk": _risk,
                       "capped": _capped[i]})
    _edge_tot = sum(_r["edge"] for _r in _righe)
    _var_tot = sum(_r["risk"] ** 2 for _r in _righe)
    _rb_usato = (_var_tot ** 0.5) / _K
    _sharpe = _edge_tot / (_var_tot ** 0.5) if _var_tot > 0.0 else 0.0
    return {"righe": _righe, "edge_tot": _edge_tot, "var_tot": _var_tot,
            "rb_usato": _rb_usato, "sharpe": _sharpe,
            "n_capped": sum(1 for _c in _capped if _c)}


def mh464_verdetto(alloc, nomi):
    """Verdetto a 3 stati (+ NESSUN TRADE ereditato dalle coppie):
    NESSUN TRADE (alloc None: nessuna coppia con trade allocabile),
    CONCENTRATO (una coppia assorbe oltre il 50% del capitale
    impiegato: il portafoglio e' di fatto un singolo trade),
    DIVERSIFICATO (il capitale e' distribuito su piu' trade).
    Nota aggiunta in coda se ci sono cap f_max vincolanti (nomi delle
    coppie: l'ottimo non vincolato vorrebbe di piu').
    alloc: dict di mh464_alloc con 'nome' aggiunto a ogni riga (o None);
    nomi: lista dei nomi, stesso ordine delle righe."""
    if alloc is None:
        return ("NESSUN TRADE — nessuna coppia con un trade allocabile: "
                "il desk non costruisce un portafoglio sul vuoto.")
    if not isinstance(alloc, dict) or "righe" not in alloc:
        raise ValueError("verdetto: alloc deve essere il dict di "
                         "mh464_alloc (o None)")
    _righe = alloc["righe"]
    if not isinstance(nomi, (list, tuple)) or len(nomi) != len(_righe):
        raise ValueError("verdetto: nomi deve allinearsi alle righe "
                         "di alloc")
    _tot = sum(_r["g"] for _r in _righe)
    if _tot <= 0.0:
        return ("NESSUN TRADE — allocazione nulla: nessun trade con "
                "edge positivo da distribuire.")
    _imax = max(range(len(_righe)), key=lambda i: _righe[i]["g"])
    if _righe[_imax]["g"] > 0.5 * _tot:
        _v = (f"CONCENTRATO — '{nomi[_imax]}' assorbe "
              f"{_righe[_imax]['g'] / _tot:.0%} del capitale impiegato "
              f"({_righe[_imax]['g']:.1%} del capitale totale): il "
              f"portafoglio e' di fatto un singolo trade.")
    else:
        _v = (f"DIVERSIFICATO — capitale distribuito su "
              f"{len(_righe)} trade (max "
              f"{_righe[_imax]['g'] / _tot:.0%} su '{nomi[_imax]}'): "
              f"nessun singolo trade domina il rischio.")
    _capn = [nomi[i] for i, _r in enumerate(_righe) if _r["capped"]]
    if _capn:
        _v += (f" Cap f_max vincolante su: {', '.join(_capn)} (l'ottimo "
               f"non vincolato vorrebbe di piu').")
    return _v


def mh464_mappa(coppie, K=1000000.0, rb=0.05, f_max=0.25,
                z_entry=1.0, costo=0.20, H=10):
    """Mappa completa: quante coppie, quanto capitale su ciascuna.

    coppie: lista non vuota di (nome, seed_gas, seed_spread) con nomi
    unici. Per ciascuna la pipeline tab463 (mh464_coppia); l'allocazione
    (mh464_alloc) gira sui soli trade eligibili con mu > 0.
    Ritorna dict: coppie (righe mh464_coppia), eligibili (nomi),
    alloc (dict di mh464_alloc con 'nome' per riga, o None),
    verdetto (mh464_verdetto)."""
    if not isinstance(coppie, (list, tuple)) or len(coppie) == 0:
        raise ValueError("mappa: serve una lista non vuota di "
                         "(nome, seed_gas, seed_spread)")
    _nomi = []
    for _i, _c in enumerate(coppie):
        try:
            _nm, _sg, _ss = _c
        except (TypeError, ValueError):
            raise ValueError(f"mappa: coppia {_i} malformata "
                             f"(serve (nome, seed_gas, seed_spread))")
        if not isinstance(_nm, str) or not _nm.strip():
            raise ValueError(f"mappa: nome coppia {_i} non valido")
        if _nm in _nomi:
            raise ValueError(f"mappa: nome coppia duplicato {_nm!r}")
        _nomi.append(_nm)
    _K = mh464_num(K, "K")
    if _K <= 0.0:
        raise ValueError(f"mappa: K deve essere > 0 (trovato {_K})")
    _rb = mh464_num(rb, "rb")
    if _rb <= 0.0 or _rb > 1.0:
        raise ValueError(f"mappa: rb deve stare in (0, 1] (trovato {_rb})")
    _fm = mh464_num(f_max, "f_max")
    if _fm <= 0.0 or _fm > 1.0:
        raise ValueError(f"mappa: f_max deve stare in (0, 1] "
                         f"(trovato {_fm})")
    _righe = [mh464_coppia(_nm, _sg, _ss, K=_K, z_entry=z_entry,
                           costo=costo, H=H, f_max=_fm)
              for _nm, _sg, _ss in coppie]
    _elig = [_r for _r in _righe if _r["eligibile"] and _r["mu"] > 0.0]
    if not _elig:
        return {"coppie": _righe, "eligibili": [], "alloc": None,
                "verdetto": mh464_verdetto(None, [])}
    _alloc = mh464_alloc([_r["mu"] for _r in _elig],
                         [_r["sigma"] for _r in _elig],
                         [_r["f_app"] for _r in _elig],
                         _K, _rb, _fm)
    _enomi = [_r["nome"] for _r in _elig]
    for _r, _nm in zip(_alloc["righe"], _enomi):
        _r["nome"] = _nm
    return {"coppie": _righe, "eligibili": _enomi, "alloc": _alloc,
            "verdetto": mh464_verdetto(_alloc, _enomi)}

def mh463_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh463_sched(nome, tau_star):
    """Espande uno schedule di uscita nominato in tupla di (frazione, tau).

    Gli schedule sono frazioni dell'orizzonte di uscita tau_star (il time
    stop di tab462): "one-shot" esce tutto a tau_star, gli altri
    distribuiscono la size in tranche a tau frazionari.
    Ritorna ((f1, tau1), ...) con frazioni in (0, 1] che sommano a 1 e
    0 < tau_i <= tau_star. Nomi noti: "one-shot", "3-pari", "5-pari",
    "front-50-50", "back-25-75", "10-graduale"."""
    if not isinstance(nome, str):
        raise ValueError(f"sched: nome deve essere una stringa "
                         f"(trovato {type(nome).__name__})")
    ts = mh463_num(tau_star, "tau_star")
    if ts <= 0.0:
        raise ValueError(f"sched: tau_star deve essere > 0 (trovato {ts})")
    if nome == "one-shot":
        return ((1.0, ts),)
    if nome == "3-pari":
        return tuple((1.0 / 3.0, ts * i / 3.0) for i in (1, 2, 3))
    if nome == "5-pari":
        return tuple((0.2, ts * i / 5.0) for i in (1, 2, 3, 4, 5))
    if nome == "front-50-50":
        return ((0.5, ts / 2.0), (0.5, ts))
    if nome == "back-25-75":
        return ((0.25, ts / 2.0), (0.75, ts))
    if nome == "10-graduale":
        return tuple((0.1, ts * i / 10.0) for i in range(1, 11))
    raise ValueError(f"sched: nome sconosciuto {nome!r} (noti: one-shot, "
                     f"3-pari, 5-pari, front-50-50, back-25-75, 10-graduale)")


def mh463_tranche(mu, sigma, h, tau, stop_eur, target_eur, costo_tempo=0.0):
    """Singola tranche in uscita al tempo tau.

    Y_tau in scaling browniano da h (mh462_scala); payoff atteso con
    stop/target FISSI in EUR E[min(max(Y_tau,stop),target)] in forma
    chiusa (mh462_piani -> mh460_piani: nessun duplicato), al netto del
    costo tempo costo_tempo*tau (EUR/giorno: funding o costo
    opportunita' del capitale impegnato nella tranche).
    Richiede 0 < tau <= h, stop_eur < 0 < target_eur, costo_tempo >= 0."""
    muf = mh463_num(mu, "mu")
    sigf = mh463_num(sigma, "sigma")
    if sigf <= 0.0:
        raise ValueError(f"tranche: sigma deve essere > 0 (trovato {sigf})")
    hf = mh463_num(h, "h")
    if hf <= 0.0:
        raise ValueError(f"tranche: h deve essere > 0 (trovato {hf})")
    tauf = mh463_num(tau, "tau")
    if tauf <= 0.0 or tauf > hf:
        raise ValueError(f"tranche: serve 0 < tau <= h "
                         f"(trovato tau={tauf}, h={hf})")
    se = mh463_num(stop_eur, "stop_eur")
    te = mh463_num(target_eur, "target_eur")
    if se >= 0.0:
        raise ValueError(f"tranche: stop_eur deve essere < 0 (trovato {se})")
    if te <= 0.0:
        raise ValueError(f"tranche: target_eur deve essere > 0 "
                         f"(trovato {te})")
    ct = mh463_num(costo_tempo, "costo_tempo")
    if ct < 0.0:
        raise ValueError(f"tranche: costo_tempo non puo' essere negativo "
                         f"(trovato {ct})")
    mut, sgt = mh462_scala(muf, sigf, hf, tauf)
    p = mh462_piani(mut, sgt, se, te)
    return {"tau": tauf, "mu_tau": mut, "sigma_tau": sgt,
            "pnl_capped": p["pnl_capped"],
            "net": p["pnl_capped"] - ct * tauf,
            "p_stop": p["p_stop"], "p_target": p["p_target"],
            "p_open": p["p_open"], "stop": p["stop"],
            "target": p["target"]}


def mh463_atteso(tranches, mu, sigma, h, stop_eur, target_eur,
                 costo_tempo=0.0):
    """P&L atteso netto di uno schedule di uscita.

    tranches: lista di (frazione, tau) con frazioni in (0, 1] che sommano
    a 1 (tol 1e-9). Ogni tranche e' valutata come payoff capped
    "europeo" indipendente al suo tau (mh463_tranche, stessi stop/target
    fissi in EUR): la dipendenza di percorso tra tranche — es. una
    tranche precedente che tocca lo stop — NON e' modellata (nota
    onesta: il modello non sa che le tranche condividono lo stesso
    percorso di prezzo).
    Ritorna tranche (righe), netto = somma f_i*net_i, tempo_medio =
    somma f_i*tau_i (giorni medi di esposizione della size)."""
    if not isinstance(tranches, (list, tuple)) or len(tranches) == 0:
        raise ValueError("atteso: serve una lista non vuota di "
                         "(frazione, tau)")
    righe = []
    tot = 0.0
    for i, tr in enumerate(tranches):
        try:
            f, tau = tr
        except (TypeError, ValueError):
            raise ValueError(f"atteso: tranche {i} malformata "
                             f"(serve (frazione, tau))")
        ff = mh463_num(f, f"frazione[{i}]")
        if ff <= 0.0 or ff > 1.0:
            raise ValueError(f"atteso: frazione[{i}] deve stare in (0, 1] "
                             f"(trovato {ff})")
        r = mh463_tranche(mu, sigma, h, tau, stop_eur, target_eur,
                          costo_tempo=costo_tempo)
        r["frazione"] = ff
        righe.append(r)
        tot += ff
    if abs(tot - 1.0) > 1e-9:
        raise ValueError(f"atteso: le frazioni devono sommare a 1 "
                         f"(trovato {tot})")
    netto = sum(r["frazione"] * r["net"] for r in righe)
    tempo_medio = sum(r["frazione"] * r["tau"] for r in righe)
    return {"tranche": righe, "netto": netto, "tempo_medio": tempo_medio,
            "n_tranche": len(righe)}


def mh463_verdetto(best, gain, mu, zero_motivo=None):
    """Verdetto a 3 stati (+ NESSUN TRADE ereditato da tab462):
    NESSUN TRADE (zero_motivo non None),
    A PEZZI CONVIENE (il miglior schedule batte uscire tutto insieme a
    tau* di oltre l'1% dell'edge),
    TUTTO INSIEME (uscire tutto insieme a tau* e' entro l'1% dell'ottimo:
    lo scale-out non paga, e l'uscita singola e' piu' semplice da
    eseguire).
    best: riga di mh463_mappa["scala"] (solo sched usata qui)."""
    if zero_motivo is not None:
        return (f"NESSUN TRADE — {zero_motivo} Il desk non cerca uno "
                f"schedule di uscita su una posizione che non esiste.")
    if not isinstance(best, dict) or "sched" not in best:
        raise ValueError("verdetto: best deve essere la riga "
                         "di mh463_mappa[\"scala\"]")
    gf = mh463_num(gain, "gain")
    muf = mh463_num(mu, "mu")
    if gf > 0.01 * abs(muf):
        return (f"A PEZZI CONVIENE — lo schedule '{best['sched']}' batte "
                f"uscire tutto insieme a tau* di {gf:,.0f} EUR "
                f"({gf / abs(muf):.1%} dell'edge): il desk esce a tranche "
                f"invece che in un'unica soluzione.")
    return (f"TUTTO INSIEME — uscire tutto insieme a tau* e' entro l'1% "
            f"dell'ottimo (gain {gf:+,.0f} EUR): lo scale-out non paga, "
            f"e l'uscita singola costa meno in operativita'.")


def mh463_mappa(power, gas, beta=None, z_entry=1.0, costo=0.20, H=10,
                capitale=1000000.0, f_max=0.25,
                ks_min=0.25, ks_max=3.0, n_ks=21,
                kt_min=0.5, kt_max=4.0, n_kt=21,
                vincola_pstop=False, p_stop_max=0.15,
                tau_min=1.0, tau_max=None, n_tau=11, costo_tempo=0.0,
                scheds=("one-shot", "3-pari", "5-pari",
                        "front-50-50", "back-25-75", "10-graduale")):
    """Mappa completa: time stop di tab462 + confronto schedule di uscita.

    Gli stop/target ottimi di tab461 restano FISSATI in EUR; tau_star e'
    il time stop di tab462 (best tau della griglia). Ogni schedule esce
    a tranche a frazioni di tau_star: atteso netto = somma
    f_i*(capped(tau_i) - costo_tempo*tau_i) in forma chiusa
    (mh463_atteso -> mh462_piani -> mh460_piani: nessun duplicato).
    scheds: tupla non vuota di nomi noti, senza duplicati; deve includere
    "one-shot" (riferimento). A parita' di netto vince lo schedule che
    compare per primo ("one-shot" e' il primo: i pareggi vanno all'uscita
    singola, piu' semplice da eseguire).
    Se il trade non passa il filtro di tab462: scala None e verdetto
    NESSUN TRADE."""
    if not isinstance(scheds, (list, tuple)) or len(scheds) == 0:
        raise ValueError("mappa: serve una tupla non vuota di schedule")
    noti = ("one-shot", "3-pari", "5-pari",
            "front-50-50", "back-25-75", "10-graduale")
    for s in scheds:
        if s not in noti:
            raise ValueError(f"mappa: schedule sconosciuto {s!r}")
    if len(set(scheds)) != len(scheds):
        raise ValueError("mappa: schedule duplicati")
    if "one-shot" not in scheds:
        raise ValueError("mappa: serve lo schedule 'one-shot' "
                         "come riferimento")
    t = mh462_mappa(power, gas, beta=beta, z_entry=z_entry, costo=costo,
                    H=H, capitale=capitale, f_max=f_max,
                    ks_min=ks_min, ks_max=ks_max, n_ks=n_ks,
                    kt_min=kt_min, kt_max=kt_max, n_kt=n_kt,
                    vincola_pstop=vincola_pstop, p_stop_max=p_stop_max,
                    tau_min=tau_min, tau_max=tau_max, n_tau=n_tau,
                    costo_tempo=costo_tempo)
    base = dict(t)
    base.update({"scheds": tuple(scheds)})
    if t["zero_motivo"] is not None or t["tempo"] is None:
        zm = (t["zero_motivo"] if t["zero_motivo"] is not None
              else "NESSUN TRADE")
        base.update({"scala": None,
                     "verdetto": mh463_verdetto(
                         None, 0.0, 0.0, zero_motivo=zm)})
        return base
    tau_star = t["tempo"]["best"]["tau"]
    b = t["ottimo"]["best"]
    mu, sg, h = t["mu_pnl"], t["sigma_pnl"], t["h_star"]
    ct = t["costo_tempo"]
    righe = []
    for nome in scheds:
        a = mh463_atteso(mh463_sched(nome, tau_star), mu, sg, h,
                         b["stop"], b["target"], costo_tempo=ct)
        righe.append({"sched": nome, "netto": a["netto"],
                      "tempo_medio": a["tempo_medio"],
                      "n_tranche": a["n_tranche"],
                      "tranche": a["tranche"]})
    one = next(r for r in righe if r["sched"] == "one-shot")
    best = righe[0]
    for r in righe[1:]:
        if r["netto"] > best["netto"]:
            best = r
    gain = best["netto"] - one["netto"]
    base["scala"] = {"righe": righe, "best": best, "one_shot": one,
                     "gain": gain, "tau_star": tau_star}
    base["verdetto"] = mh463_verdetto(best, gain, mu)
    return base

def mh462_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh462_asse(vmin, vmax, n, nome):
    """Asse di n punti equispaziati in [vmin, vmax] (tempi in giorni).

    vmin > 0, vmax > vmin, n intero >= 2. Ritorna una tupla di float."""
    v0 = mh462_num(vmin, nome + "_min")
    v1 = mh462_num(vmax, nome + "_max")
    if v0 <= 0.0:
        raise ValueError(f"{nome}: min deve essere > 0 (trovato {v0})")
    if v1 <= v0:
        raise ValueError(f"{nome}: max deve essere > min "
                         f"(trovato {v0}, {v1})")
    if isinstance(n, bool) or not isinstance(n, int):
        raise ValueError(f"{nome}: n punti deve essere un intero >= 2")
    if n < 2:
        raise ValueError(f"{nome}: n punti deve essere >= 2 "
                         f"(trovato {n})")
    return tuple(v0 + i * (v1 - v0) / (n - 1) for i in range(n))


def mh462_scala(mu, sigma, h, tau):
    """Scaling browniano del P&L dall'orizzonte h al tempo tau:
    Y_tau ~ N(mu*tau/h, sigma^2*tau/h) (incrementi indipendenti).

    Richiede h > 0, sigma > 0, 0 < tau <= h. Ritorna (mu_tau, sigma_tau)."""
    import math
    muf = mh462_num(mu, "mu")
    sigf = mh462_num(sigma, "sigma")
    hf = mh462_num(h, "h")
    tauf = mh462_num(tau, "tau")
    if hf <= 0.0:
        raise ValueError(f"scala: h deve essere > 0 (trovato {hf})")
    if sigf <= 0.0:
        raise ValueError(f"scala: sigma deve essere > 0 (trovato {sigf})")
    if tauf <= 0.0:
        raise ValueError(f"scala: tau deve essere > 0 (trovato {tauf})")
    if tauf > hf:
        raise ValueError(f"scala: tau non puo' superare h "
                         f"(tau={tauf}, h={hf})")
    return (muf * tauf / hf, sigf * math.sqrt(tauf / hf))


def mh462_piani(mu_tau, sigma_tau, stop_eur, target_eur):
    """Stop/target FISSI in EUR sul P&L al tempo tau
    (Y_tau ~ N(mu_tau, sigma_tau^2)).

    Riusa mh460_piani esprimendo i livelli fissi come k della sigma al
    tempo tau (stop = -k_stop*sigma_tau): nessun duplicato della forma
    chiusa. Richiede stop_eur < 0 < target_eur.
    Aggiunge p_open = P(stop < Y_tau < target): il trade e' ancora
    aperto al tempo tau (non ha toccato stop ne' target)."""
    muf = mh462_num(mu_tau, "mu_tau")
    sgt = mh462_num(sigma_tau, "sigma_tau")
    if sgt <= 0.0:
        raise ValueError(f"piani: sigma_tau deve essere > 0 "
                         f"(trovato {sgt})")
    se = mh462_num(stop_eur, "stop_eur")
    te = mh462_num(target_eur, "target_eur")
    if se >= 0.0:
        raise ValueError(f"piani: stop_eur deve essere < 0 (trovato {se})")
    if te <= 0.0:
        raise ValueError(f"piani: target_eur deve essere > 0 "
                         f"(trovato {te})")
    p = dict(mh460_piani(muf, sgt, -se / sgt, te / sgt))
    p["p_open"] = 1.0 - p["p_stop"] - p["p_target"]
    p["mu_tau"] = muf
    p["sigma_tau"] = sgt
    return p


def mh462_tempo(mu, sigma, h, stop_eur, target_eur, tau_min=1.0, tau_max=None,
                n_tau=11, costo_tempo=0.0):
    """Grid search sul tempo di uscita: per ogni tau della griglia calcola
    il P&L atteso con stop/target E[min(max(Y_tau,stop),target)] in forma
    chiusa (mh462_piani -> mh460_piani) con scaling browniano
    (mh462_scala), al netto del costo tempo costo_tempo*tau (EUR/giorno:
    funding o costo opportunita' del capitale impegnato).

    tau_max None -> h. Richiede 0 < tau_min < tau_max <= h,
    costo_tempo >= 0.
    Ritorna assi, righe, miglior punto (netto massimo; a parita' vince il
    tau piu' piccolo), hold (ultimo punto della griglia = tenere fino a
    tau_max), gain (best - hold) e on_edge (il miglior tau tocca un bordo
    della griglia: il massimo potrebbe stare fuori dal range)."""
    muf = mh462_num(mu, "mu")
    sigf = mh462_num(sigma, "sigma")
    if sigf <= 0.0:
        raise ValueError(f"tempo: sigma deve essere > 0 (trovato {sigf})")
    hf = mh462_num(h, "h")
    if hf <= 0.0:
        raise ValueError(f"tempo: h deve essere > 0 (trovato {hf})")
    se = mh462_num(stop_eur, "stop_eur")
    te = mh462_num(target_eur, "target_eur")
    if se >= 0.0:
        raise ValueError(f"tempo: stop_eur deve essere < 0 (trovato {se})")
    if te <= 0.0:
        raise ValueError(f"tempo: target_eur deve essere > 0 "
                         f"(trovato {te})")
    tmin = mh462_num(tau_min, "tau_min")
    if tmin <= 0.0:
        raise ValueError(f"tempo: tau_min deve essere > 0 "
                         f"(trovato {tmin})")
    if tau_max is None:
        tmax = hf
    else:
        tmax = mh462_num(tau_max, "tau_max")
    if tmax > hf:
        raise ValueError(f"tempo: tau_max non puo' superare h "
                         f"(tau_max={tmax}, h={hf})")
    if tmax <= tmin:
        raise ValueError(f"tempo: serve tau_min < tau_max "
                         f"(trovato {tmin}, {tmax})")
    ct = mh462_num(costo_tempo, "costo_tempo")
    if ct < 0.0:
        raise ValueError(f"tempo: costo_tempo non puo' essere negativo "
                         f"(trovato {ct})")
    taus = mh462_asse(tmin, tmax, n_tau, "tau")
    best = None
    righe = []
    for i, tau in enumerate(taus):
        mut, sgt = mh462_scala(muf, sigf, hf, tau)
        p = mh462_piani(mut, sgt, se, te)
        net = p["pnl_capped"] - ct * tau
        riga = {"tau": tau, "i": i, "mu_tau": mut, "sigma_tau": sgt,
                "pnl_capped": p["pnl_capped"], "net": net,
                "p_stop": p["p_stop"], "p_target": p["p_target"],
                "p_open": p["p_open"], "stop": p["stop"],
                "target": p["target"]}
        righe.append(riga)
        if best is None or net > best["net"]:
            best = riga
    hold = righe[-1]
    gain = best["net"] - hold["net"]
    on_edge = (best["i"] == 0 or best["i"] == len(taus) - 1)
    return {"taus": taus, "righe": righe, "best": best, "hold": hold,
            "gain": gain, "on_edge": on_edge,
            "stop_eur": se, "target_eur": te,
            "tau_min": tmin, "tau_max": tmax, "n_tau": len(taus),
            "costo_tempo": ct, "h": hf}


def mh462_verdetto(best, gain, on_edge, mu, h_star, zero_motivo=None):
    """Verdetto a 4 stati (+ NESSUN TRADE ereditato da tab461):
    NESSUN TRADE (zero_motivo non None),
    AI BORDI (il miglior tau tocca un bordo ESTENDIBILE della griglia:
    estendere il range),
    TIME STOP UTILE (uscire a tau* batte tenere fino a h* di oltre
    l'1% dell'edge),
    TENERE FINO A h* (tenere la posizione fino all'orizzonte e' entro
    l'1% dell'ottimo: il time stop non paga).
    Il bordo superiore NON e' estendibile quando coincide con h*
    (tau* = tau_max = h*): in quel caso il verdetto cade su
    TIME STOP UTILE / TENERE FINO A h* in base al gain.
    best: riga di mh462_tempo (solo tau usata qui)."""
    if zero_motivo is not None:
        return (f"NESSUN TRADE — {zero_motivo} Il desk non cerca un time "
                f"stop su una posizione che non esiste.")
    if not isinstance(best, dict) or "tau" not in best:
        raise ValueError("verdetto: best deve essere la riga "
                         "di mh462_tempo")
    gf = mh462_num(gain, "gain")
    muf = mh462_num(mu, "mu")
    hf = mh462_num(h_star, "h_star")
    tauf = mh462_num(best["tau"], "best.tau")
    # bordo superiore a h*: non estendibile, non e' un AI BORDI
    top_at_h = abs(tauf - hf) < 1e-9
    if on_edge and not top_at_h:
        return (f"AI BORDI — il miglior tau ({tauf:.1f} giorni) tocca un "
                f"bordo estendibile della griglia: il massimo potrebbe "
                f"stare fuori dal range. Estendi gli estremi e rilancia "
                f"la ricerca.")
    if gf > 0.01 * abs(muf):
        return (f"TIME STOP UTILE — uscire a {tauf:.1f} giorni batte "
                f"tenere fino a h* = {hf:.0f} giorni di {gf:,.0f} EUR "
                f"({gf / abs(muf):.1%} dell'edge): il desk chiude a tau* "
                f"se il trade non ha toccato stop/target.")
    return (f"TENERE FINO A h* — tenere la posizione fino a {hf:.0f} "
            f"giorni e' entro l'1% dell'ottimo (gain {gf:+,.0f} EUR): "
            f"il time stop non paga.")


def mh462_mappa(power, gas, beta=None, z_entry=1.0, costo=0.20, H=10,
                capitale=1000000.0, f_max=0.25,
                ks_min=0.25, ks_max=3.0, n_ks=21,
                kt_min=0.5, kt_max=4.0, n_kt=21,
                vincola_pstop=False, p_stop_max=0.15,
                tau_min=1.0, tau_max=None, n_tau=11, costo_tempo=0.0):
    """Mappa completa: grid search stop/target di tab461 + grid search sul
    tempo di uscita (mh462_tempo) con gli stop/target ottimi FISSATI in EUR.

    tau_max None -> h*; se tau_max supera h* viene limitato a h*.
    Se il trade non passa il filtro di tab461: tempo None e verdetto
    NESSUN TRADE."""
    tmin = mh462_num(tau_min, "tau_min")
    if tmin <= 0.0:
        raise ValueError(f"mappa: tau_min deve essere > 0 "
                         f"(trovato {tmin})")
    if tau_max is not None:
        tmax0 = mh462_num(tau_max, "tau_max")
        if tmax0 <= 0.0:
            raise ValueError(f"mappa: tau_max deve essere > 0 "
                             f"(trovato {tmax0})")
    ct = mh462_num(costo_tempo, "costo_tempo")
    if ct < 0.0:
        raise ValueError(f"mappa: costo_tempo non puo' essere negativo "
                         f"(trovato {ct})")
    m = mh461_mappa(power, gas, beta=beta, z_entry=z_entry, costo=costo,
                    H=H, capitale=capitale, f_max=f_max,
                    ks_min=ks_min, ks_max=ks_max, n_ks=n_ks,
                    kt_min=kt_min, kt_max=kt_max, n_kt=n_kt,
                    vincola_pstop=vincola_pstop, p_stop_max=p_stop_max)
    base = dict(m)
    base.update({"tau_min": tmin, "tau_max_in": tau_max, "n_tau": n_tau,
                 "costo_tempo": ct})
    if m["zero_motivo"] is not None or m["ottimo"] is None:
        zm = (m["zero_motivo"] if m["zero_motivo"] is not None
              else "NESSUN TRADE")
        base.update({"tempo": None, "tau_max_eff": None,
                     "verdetto": mh462_verdetto(
                         None, 0.0, False, 0.0, 0.0, zero_motivo=zm)})
        return base
    b = m["ottimo"]["best"]
    tmax_eff = m["h_star"] if tau_max is None else min(tmax0, m["h_star"])
    if tmax_eff <= tmin:
        raise ValueError(f"mappa: tau_min ({tmin}) deve stare sotto il "
                         f"tau_max effettivo ({tmax_eff}, "
                         f"h*={m['h_star']})")
    t = mh462_tempo(m["mu_pnl"], m["sigma_pnl"], m["h_star"],
                    b["stop"], b["target"],
                    tau_min=tmin, tau_max=tmax_eff, n_tau=n_tau,
                    costo_tempo=ct)
    base["tempo"] = t
    base["tau_max_eff"] = tmax_eff
    base["verdetto"] = mh462_verdetto(
        t["best"], t["gain"], t["on_edge"], m["mu_pnl"], m["h_star"])
    return base

def mh461_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh461_asse(vmin, vmax, n, nome):
    """Asse di n punti equispaziati in [vmin, vmax] (k in multipli di sigma).

    vmin > 0, vmax > vmin, n intero >= 2. Ritorna una tupla di float."""
    v0 = mh461_num(vmin, nome + "_min")
    v1 = mh461_num(vmax, nome + "_max")
    if v0 <= 0.0:
        raise ValueError(f"{nome}: min deve essere > 0 (trovato {v0})")
    if v1 <= v0:
        raise ValueError(f"{nome}: max deve essere > min "
                         f"(trovato {v0}, {v1})")
    if isinstance(n, bool) or not isinstance(n, int):
        raise ValueError(f"{nome}: n punti deve essere un intero >= 2")
    if n < 2:
        raise ValueError(f"{nome}: n punti deve essere >= 2 "
                         f"(trovato {n})")
    return tuple(v0 + i * (v1 - v0) / (n - 1) for i in range(n))


def mh461_ottimo(mu, sigma, ks_min=0.25, ks_max=3.0, n_ks=21,
                 kt_min=0.5, kt_max=4.0, n_kt=21, p_stop_max=None):
    """Grid search sui k di stop/target: massimizza il P&L atteso con
    stop/target E[min(max(Y, stop), target)] in forma chiusa (mh460_piani)
    sul P&L a h* Y ~ N(mu, sigma^2).

    k_stop = -stop/sigma, k_target = target/sigma (multipli di sigma).
    p_stop_max: se dato, scarta i punti con P(stop) > p_stop_max
    (deve stare in (0, 1)); se nessun punto e' fattibile -> ValueError.
    Ritorna assi, miglior punto, piani convenzionali (1.0, 2.0), gain
    (ottimo - convenzionali) e on_edge (l'ottimo tocca un bordo della
    griglia: il massimo potrebbe stare fuori dal range)."""
    muf = mh461_num(mu, "mu")
    sigf = mh461_num(sigma, "sigma")
    if sigf <= 0.0:
        raise ValueError(f"ottimo: sigma deve essere > 0 (trovato {sigf})")
    ks = mh461_asse(ks_min, ks_max, n_ks, "k_stop")
    kt = mh461_asse(kt_min, kt_max, n_kt, "k_target")
    pmf = None
    if p_stop_max is not None:
        pmf = mh461_num(p_stop_max, "p_stop_max")
        if not 0.0 < pmf < 1.0:
            raise ValueError(f"ottimo: p_stop_max deve stare in (0, 1) "
                             f"(trovato {pmf})")
    best = None
    righe = []
    for i, kss in enumerate(ks):
        for j, ktt in enumerate(kt):
            p = mh460_piani(muf, sigf, kss, ktt)
            if pmf is not None and p["p_stop"] > pmf:
                continue
            righe.append({"k_stop": kss, "k_target": ktt,
                          "pnl_capped": p["pnl_capped"],
                          "p_stop": p["p_stop"],
                          "p_target": p["p_target"]})
            if best is None or p["pnl_capped"] > best["pnl_capped"]:
                best = {"k_stop": kss, "k_target": ktt, "i": i, "j": j,
                        "stop": p["stop"], "target": p["target"],
                        "p_stop": p["p_stop"], "p_target": p["p_target"],
                        "pnl_capped": p["pnl_capped"],
                        "delta": p["delta"]}
    if best is None:
        raise ValueError("ottimo: vincolo P(stop) troppo stretto, nessun "
                         "punto della griglia e' fattibile")
    conv = mh460_piani(muf, sigf, 1.0, 2.0)
    gain = best["pnl_capped"] - conv["pnl_capped"]
    on_edge = (best["i"] == 0 or best["i"] == len(ks) - 1
               or best["j"] == 0 or best["j"] == len(kt) - 1)
    return {"ks": ks, "kt": kt, "best": best, "conventional": conv,
            "gain": gain, "on_edge": on_edge, "righe": righe,
            "fattibili": len(righe), "p_stop_max": pmf}


def mh461_verdetto(best, gain, on_edge, mu, zero_motivo=None):
    """Verdetto a 4 stati (+ NESSUN TRADE ereditato da tab458):
    NESSUN TRADE (zero_motivo non None),
    AI BORDI (l'ottimo tocca un bordo della griglia: estendere il range),
    OTTIMO TROVATO (gain > 1% dell'edge vs k convenzionali),
    CONVENZIONALI OK (i k standard sono gia' quasi ottimi).
    best: dict di mh461_ottimo (solo k_stop/k_target usati qui)."""
    if zero_motivo is not None:
        return (f"NESSUN TRADE — {zero_motivo} Il desk non ottimizza "
                f"stop/target su una posizione che non esiste.")
    if (not isinstance(best, dict) or "k_stop" not in best
            or "k_target" not in best):
        raise ValueError("verdetto: best deve essere il dict "
                         "di mh461_ottimo")
    gf = mh461_num(gain, "gain")
    muf = mh461_num(mu, "mu")
    ks = mh461_num(best["k_stop"], "best.k_stop")
    kt = mh461_num(best["k_target"], "best.k_target")
    if on_edge:
        return (f"AI BORDI — l'ottimo (k_stop = {ks:.2f}, k_target = "
                f"{kt:.2f}) tocca un bordo della griglia: il massimo "
                f"potrebbe stare fuori dal range. Estendi gli estremi e "
                f"rilancia la ricerca.")
    if gf > 0.01 * abs(muf):
        return (f"OTTIMO TROVATO — (k_stop, k_target) = ({ks:.2f}, "
                f"{kt:.2f}) batte i k convenzionali (1.0, 2.0) di "
                f"{gf:,.0f} EUR ({gf / abs(muf):.1%} dell'edge): il desk "
                f"usa questi k.")
    return (f"CONVENZIONALI OK — i k standard (1.0, 2.0) sono entro l'1% "
            f"dell'ottimo (gain {gf:+,.0f} EUR): non serve complicare.")


def mh461_mappa(power, gas, beta=None, z_entry=1.0, costo=0.20, H=10,
                capitale=1000000.0, f_max=0.25,
                ks_min=0.25, ks_max=3.0, n_ks=21,
                kt_min=0.5, kt_max=4.0, n_kt=21,
                vincola_pstop=False, p_stop_max=0.15):
    """Mappa completa: sizing/VaR di tab458 + grid search sui k di
    stop/target (mh461_ottimo).

    vincola_pstop: se True, scarta i punti con P(stop) > p_stop_max.
    Se il trade non passa il filtro di tab458: rischio zero, ottimo
    None e verdetto NESSUN TRADE."""
    mh461_asse(ks_min, ks_max, n_ks, "k_stop")
    mh461_asse(kt_min, kt_max, n_kt, "k_target")
    if not isinstance(vincola_pstop, bool):
        raise ValueError("mappa: vincola_pstop deve essere un booleano")
    pmf = mh461_num(p_stop_max, "p_stop_max")
    if not 0.0 < pmf < 1.0:
        raise ValueError(f"mappa: p_stop_max deve stare in (0, 1) "
                         f"(trovato {pmf})")
    m = mh458_mappa(power, gas, beta=beta, z_entry=z_entry, costo=costo,
                    H=H, capitale=capitale, f_max=f_max)
    base = dict(m)
    base.update({"ks_min": ks_min, "ks_max": ks_max, "n_ks": n_ks,
                 "kt_min": kt_min, "kt_max": kt_max, "n_kt": n_kt,
                 "vincola_pstop": vincola_pstop,
                 "p_stop_max": pmf})
    if m["zero_motivo"] is not None or m["size"] <= 0.0:
        base.update({"ottimo": None,
                     "verdetto": mh461_verdetto(
                         None, 0.0, False, 0.0,
                         zero_motivo=m["zero_motivo"])})
        return base
    ott = mh461_ottimo(m["mu_pnl"], m["sigma_pnl"],
                       ks_min=ks_min, ks_max=ks_max, n_ks=n_ks,
                       kt_min=kt_min, kt_max=kt_max, n_kt=n_kt,
                       p_stop_max=pmf if vincola_pstop else None)
    base["ottimo"] = ott
    base["verdetto"] = mh461_verdetto(
        ott["best"], ott["gain"], ott["on_edge"], m["mu_pnl"])
    return base

def mh460_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh460_piani(mu, sigma, k_stop, k_target):
    """Stop/target in EUR sul P&L a h* (Y ~ N(mu, sigma^2)).

    stop = -k_stop*sigma (perdita massima tollerata),
    target = +k_target*sigma (profitto obiettivo), k > 0.
    p_stop = P(Y <= stop), p_target = P(Y >= target),
    pnl_capped = E[min(max(Y, stop), target)] in forma chiusa
    (normali troncate), delta = pnl_capped - mu (puo' essere
    positivo: lo stop taglia la coda sinistra e alza l'atteso)."""
    muf = mh460_num(mu, "mu")
    sigf = mh460_num(sigma, "sigma")
    if sigf <= 0.0:
        raise ValueError(f"piani: sigma deve essere > 0 (trovato {sigf})")
    ksf = mh460_num(k_stop, "k_stop")
    if ksf <= 0.0:
        raise ValueError(f"piani: k_stop deve essere > 0 (trovato {ksf})")
    ktf = mh460_num(k_target, "k_target")
    if ktf <= 0.0:
        raise ValueError(f"piani: k_target deve essere > 0 "
                         f"(trovato {ktf})")
    stop = -ksf * sigf
    target = ktf * sigf
    a = (stop - muf) / sigf
    b = (target - muf) / sigf
    Fa = mh456_phi(a)
    Fb = mh456_phi(b)
    pa = mh458_pdf(a)
    pb = mh458_pdf(b)
    pnl_capped = (stop * Fa + target * (1.0 - Fb)
                  + muf * (Fb - Fa) + sigf * (pa - pb))
    return {"stop": stop, "target": target,
            "k_stop": ksf, "k_target": ktf,
            "p_stop": Fa, "p_target": 1.0 - Fb,
            "pnl_capped": pnl_capped,
            "delta": pnl_capped - muf}


def mh460_verdetto(p_stop, p_target, pnl_capped, mu, zero_motivo=None):
    """Verdetto a 4 stati (+ NESSUN TRADE ereditato da tab458):
    NESSUN TRADE (zero_motivo non None),
    STOP STRETTO (p_stop >= 15%: lo stop scatta per rumore),
    TARGET LONTANO (p_target < 5%: target quasi irraggiungibile),
    BILANCIATO."""
    if zero_motivo is not None:
        return (f"NESSUN TRADE — {zero_motivo} Il desk non piazza "
                f"stop/target su una posizione che non esiste.")
    psf = mh460_num(p_stop, "p_stop")
    ptf = mh460_num(p_target, "p_target")
    pcf = mh460_num(pnl_capped, "pnl_capped")
    muf = mh460_num(mu, "mu")
    if not 0.0 <= psf <= 1.0:
        raise ValueError(f"verdetto: p_stop fuori [0, 1] (trovato {psf})")
    if not 0.0 <= ptf <= 1.0:
        raise ValueError(f"verdetto: p_target fuori [0, 1] (trovato {ptf})")
    if psf >= 0.15:
        return (f"STOP STRETTO — P(stop) = {psf:.1%}: lo stop scatta "
                f"per rumore piu' di una volta su sette, taglia il "
                f"trade prima che il rientro faccia effetto. Allarga "
                f"k_stop.")
    if ptf < 0.05:
        return (f"TARGET LONTANO — P(target) = {ptf:.1%}: il target e' "
                f"quasi irraggiungibile a h*, il piano e' di fatto solo "
                f"uno stop-loss. Avvicina k_target o accetta il profilo "
                f"asimmetrico.")
    _delta = pcf - muf
    return (f"BILANCIATO — stop a P = {psf:.1%}, target a P = {ptf:.1%}, "
            f"P&L atteso con stop/target = {pcf:,.0f} EUR "
            f"(delta vs senza {_delta:+,.0f} EUR): il piano protegge "
            f"senza strozzare l'edge.")


def mh460_mappa(power, gas, beta=None, z_entry=1.0, costo=0.20, H=10,
                capitale=1000000.0, f_max=0.25, k_stop=1.0, k_target=2.0):
    """Mappa completa: sizing/VaR di tab458 + stop/target.

    k_stop/k_target: multipli di sigma_pnl (> 0). Riusa mh458_mappa
    per sizing e P&L a h*; ritorna la sua mappa + stop, target,
    p_stop, p_target, pnl_capped, delta, k_stop, k_target e verdetto
    a 4 stati."""
    ksf = mh460_num(k_stop, "k_stop")
    if ksf <= 0.0:
        raise ValueError(f"mappa: k_stop deve essere > 0 (trovato {ksf})")
    ktf = mh460_num(k_target, "k_target")
    if ktf <= 0.0:
        raise ValueError(f"mappa: k_target deve essere > 0 "
                         f"(trovato {ktf})")
    m = mh458_mappa(power, gas, beta=beta, z_entry=z_entry, costo=costo,
                    H=H, capitale=capitale, f_max=f_max)
    base = dict(m)
    base.update({"k_stop": ksf, "k_target": ktf})
    if m["zero_motivo"] is not None or m["size"] <= 0.0:
        base.update({"stop": 0.0, "target": 0.0,
                     "p_stop": 0.0, "p_target": 0.0,
                     "pnl_capped": 0.0, "delta": 0.0,
                     "verdetto": mh460_verdetto(
                         0.0, 0.0, 0.0, 0.0,
                         zero_motivo=m["zero_motivo"])})
        return base
    p = mh460_piani(m["mu_pnl"], m["sigma_pnl"], ksf, ktf)
    base.update(p)
    base["verdetto"] = mh460_verdetto(
        p["p_stop"], p["p_target"], p["pnl_capped"], m["mu_pnl"])
    return base

def mh459_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh459_shock(mu, sigma, k_vol, drift):
    """Parametri stressati: (mu - drift*sigma, k_vol*sigma).

    k_vol >= 1 (shock amplificativo sulla volatilita'), drift >= 0
    (drift avverso alla posizione, in unita' di sigma)."""
    muf = mh459_num(mu, "mu")
    sigf = mh459_num(sigma, "sigma")
    if sigf <= 0.0:
        raise ValueError(f"shock: sigma deve essere > 0 (trovato {sigf})")
    kf = mh459_num(k_vol, "k_vol")
    if kf < 1.0:
        raise ValueError(f"shock: k_vol deve essere >= 1 (trovato {kf})")
    df = mh459_num(drift, "drift")
    if df < 0.0:
        raise ValueError(f"shock: drift deve essere >= 0 (trovato {df})")
    return {"mu_s": muf - df * sigf, "sigma_s": kf * sigf,
            "k_vol": kf, "drift": df}


def mh459_verdetto(var_worst, var_base, limite, alpha, zero_motivo=None,
                   size_max_stress=None, f_lim_stress=None):
    """Verdetto a 4 stati sullo stress test (+ SIZING ZERO ereditato):
    SIZING ZERO (zero_motivo non None), OLTRE LIMITE (VaR base gia'
    oltre il limite), VULNERABILE (base entro, almeno uno scenario
    oltre), RESILIENTE (tutti gli scenari entro il limite)."""
    if zero_motivo is not None:
        return (f"SIZING ZERO — {zero_motivo} Il desk non stressa "
                f"una posizione che non esiste.")
    vwf = mh459_num(var_worst, "var_worst")
    vbf = mh459_num(var_base, "var_base")
    lf = mh459_num(limite, "limite")
    if lf <= 0.0:
        raise ValueError(f"verdetto: limite deve essere > 0 (trovato {lf})")
    af = mh459_num(alpha, "alpha")
    if af <= 0.0 or af >= 1.0:
        raise ValueError(f"verdetto: alpha deve stare in (0, 1) "
                         f"(trovato {af})")
    pct = 100.0 * (1.0 - af)
    extra = ""
    if size_max_stress is not None and f_lim_stress is not None:
        smf = mh459_num(size_max_stress, "size_max_stress")
        flf = mh459_num(f_lim_stress, "f_lim_stress")
        extra = (f" Size massima compatibile col limite nello scenario "
                 f"peggiore: {smf:,.0f} unita' di spread "
                 f"(f = {flf:.2%} del capitale).")
    if vbf > lf:
        return (f"OLTRE LIMITE — VaR {pct:.0f}% base = {vbf:,.0f} EUR gia' "
                f"oltre il limite di {lf:,.0f} EUR: lo stress test non "
                f"cambia la diagnosi di tab458, la size va ridotta "
                f"comunque." + extra)
    if vwf > lf:
        return (f"VULNERABILE — VaR {pct:.0f}% base = {vbf:,.0f} EUR entro "
                f"il limite di {lf:,.0f} EUR, ma sotto shock sale a "
                f"{vwf:,.0f} EUR: il trade regge il mercato di oggi, non "
                f"quello di domani." + extra)
    return (f"RESILIENTE — VaR {pct:.0f}% resta entro il limite di "
            f"{lf:,.0f} EUR in tutti gli scenari (peggiore {vwf:,.0f} "
            f"EUR): il trade regge anche sotto shock.")


def mh459_mappa(power, gas, beta=None, z_entry=1.0, costo=0.20, H=10,
                capitale=1000000.0, f_max=0.25, alpha=0.05, limite=None,
                k_vol=1.5, drift=0.5):
    """Mappa completa: VaR/ES di tab458 ricalcolati sotto shock.

    k_vol: moltiplicatore di volatilita' (>= 1); drift: drift avverso
    in unita' di sigma (>= 0); limite None -> 2% del capitale.
    Quattro scenari (BASE, VOL SHOCK, DRIFT SHOCK, COMBINATO) con
    mu_s = mu - drift*sigma, sigma_s = k_vol*sigma; per ognuno VaR/ES
    via mh458_var_es, P(perdita) via mh456_phi, esito via
    mh458_verdetto. Ritorna la mappa di mh458_mappa + scenari,
    worst, var/es/p_perdita peggiori, var_unit_worst, size_max_stress,
    f_lim_stress e verdetto a 4 stati."""
    K = mh459_num(capitale, "capitale")
    if K <= 0.0:
        raise ValueError(f"mappa: capitale deve essere > 0 (trovato {K})")
    af = mh459_num(alpha, "alpha")
    if af <= 0.0 or af >= 1.0:
        raise ValueError(f"mappa: alpha deve stare in (0, 1) "
                         f"(trovato {af})")
    lim = 0.02 * K if limite is None else mh459_num(limite, "limite")
    if lim <= 0.0:
        raise ValueError(f"mappa: limite deve essere > 0 (trovato {lim})")
    kf = mh459_num(k_vol, "k_vol")
    if kf < 1.0:
        raise ValueError(f"mappa: k_vol deve essere >= 1 (trovato {kf})")
    df = mh459_num(drift, "drift")
    if df < 0.0:
        raise ValueError(f"mappa: drift deve essere >= 0 (trovato {df})")
    m = mh458_mappa(power, gas, beta=beta, z_entry=z_entry, costo=costo,
                    H=H, capitale=K, f_max=f_max, alpha=af, limite=lim)
    base = dict(m)
    base.update({"k_vol": kf, "drift": df})
    if m["zero_motivo"] is not None or m["size"] <= 0.0:
        base.update({"scenari": [], "worst": None, "var_worst": 0.0,
                     "es_worst": 0.0, "p_perdita_worst": 0.0,
                     "var_unit_worst": 0.0, "size_max_stress": 0.0,
                     "f_lim_stress": 0.0,
                     "verdetto": mh459_verdetto(
                         0.0, 0.0, lim, af,
                         zero_motivo=m["zero_motivo"])})
        return base
    mu, sigma = m["mu_pnl"], m["sigma_pnl"]
    scenari = []
    for nome, kk, dd in (("BASE", 1.0, 0.0),
                         ("VOL SHOCK", kf, 0.0),
                         ("DRIFT SHOCK", 1.0, df),
                         ("COMBINATO", kf, df)):
        sh = mh459_shock(mu, sigma, kk, dd)
        ve = mh458_var_es(sh["mu_s"], sh["sigma_s"], af)
        p_s = 1.0 - mh456_phi(sh["mu_s"] / sh["sigma_s"])
        esito = mh458_verdetto(ve["var"], lim, af)
        scenari.append({"nome": nome, "k_vol": sh["k_vol"],
                        "drift": sh["drift"], "mu_s": sh["mu_s"],
                        "sigma_s": sh["sigma_s"], "var": ve["var"],
                        "es": ve["es"], "p_perdita": p_s,
                        "esito": esito.split(" — ")[0]})
    worst = max(scenari, key=lambda s: s["var"])
    z_1 = mh458_quantile(1.0 - af)
    var_unit_worst = (-(m["netto_star"] - df * m["se_star"])
                      + z_1 * kf * m["se_star"])
    if worst["var"] <= lim:
        size_max_stress, f_lim_stress = m["size"], m["f_app"]
    else:
        size_max_stress = (lim / var_unit_worst if var_unit_worst > 0.0
                           else m["size"])
        f_lim_stress = size_max_stress * m["L"] / K
    base.update({"scenari": scenari, "worst": worst["nome"],
                 "var_worst": worst["var"], "es_worst": worst["es"],
                 "p_perdita_worst": worst["p_perdita"],
                 "var_unit_worst": var_unit_worst,
                 "size_max_stress": size_max_stress,
                 "f_lim_stress": f_lim_stress,
                 "verdetto": mh459_verdetto(
                     worst["var"], m["var"], lim, af,
                     size_max_stress=size_max_stress,
                     f_lim_stress=f_lim_stress)})
    return base

def mh458_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh458_pdf(x):
    """Densita' normale standard in x."""
    import math
    xf = mh458_num(x, "x")
    return math.exp(-0.5 * xf * xf) / math.sqrt(2.0 * math.pi)


def mh458_quantile(alpha):
    """Quantile normale standard Phi^-1(alpha), bisezione su mh456_phi.

    alpha in (0, 1) stretto; 200 iterazioni su [-10, 10] (errore ~1e-15
    sui valori noti)."""
    af = mh458_num(alpha, "alpha")
    if af <= 0.0 or af >= 1.0:
        raise ValueError(f"quantile: alpha deve stare in (0, 1) "
                         f"(trovato {af})")
    lo, hi = -10.0, 10.0
    for _ in range(200):
        mid = 0.5 * (lo + hi)
        if mh456_phi(mid) < af:
            lo = mid
        else:
            hi = mid
    return 0.5 * (lo + hi)


def mh458_var_es(mu, sigma, alpha):
    """VaR ed ES (come perdite positive) di N(mu, sigma^2) al livello alpha.

    VaR = -(mu + z_alpha * sigma), ES = -mu + sigma * phi(z_alpha) / alpha,
    z_alpha = Phi^-1(alpha). sigma > 0, alpha in (0, 1)."""
    muf = mh458_num(mu, "mu")
    sigf = mh458_num(sigma, "sigma")
    if sigf <= 0.0:
        raise ValueError(f"var_es: sigma deve essere > 0 (trovato {sigf})")
    af = mh458_num(alpha, "alpha")
    if af <= 0.0 or af >= 1.0:
        raise ValueError(f"var_es: alpha deve stare in (0, 1) "
                         f"(trovato {af})")
    z = mh458_quantile(af)
    var = -(muf + z * sigf)
    es = -muf + sigf * mh458_pdf(z) / af
    return {"var": var, "es": es, "z": z, "alpha": af}


def mh458_verdetto(var, limite, alpha, zero_motivo=None, size=None,
                   size_max=None, f_lim=None):
    """Verdetto a 3 stati sul rischio della posizione dimensionata
    (+ SIZING ZERO ereditato da tab457):
    SIZING ZERO (zero_motivo non None), ENTRO LIMITE (var <= limite),
    OLTRE LIMITE (var > limite, con size massima compatibile se
    size_max/f_lim forniti). var/limite numeri finiti, limite > 0,
    alpha in (0, 1)."""
    if zero_motivo is not None:
        return (f"SIZING ZERO — {zero_motivo} Il desk non misura il "
                f"rischio di una posizione che non esiste.")
    vf = mh458_num(var, "var")
    lf = mh458_num(limite, "limite")
    if lf <= 0.0:
        raise ValueError(f"verdetto: limite deve essere > 0 "
                         f"(trovato {lf})")
    af = mh458_num(alpha, "alpha")
    if af <= 0.0 or af >= 1.0:
        raise ValueError(f"verdetto: alpha deve stare in (0, 1) "
                         f"(trovato {af})")
    pct = 100.0 * (1.0 - af)
    if vf <= lf:
        return (f"ENTRO LIMITE — VaR {pct:.0f}% = {vf:,.0f} EUR entro il "
                f"limite di {lf:,.0f} EUR. La size di tab457 resta valida "
                f"per il vincolo di rischio del desk.")
    extra = ""
    if size_max is not None and f_lim is not None:
        smf = mh458_num(size_max, "size_max")
        flf = mh458_num(f_lim, "f_lim")
        extra = (f" Size massima compatibile col limite: {smf:,.0f} "
                 f"unita' di spread (f = {flf:.2%} del capitale).")
    return (f"OLTRE LIMITE — VaR {pct:.0f}% = {vf:,.0f} EUR oltre il limite "
            f"di {lf:,.0f} EUR: il Kelly di tab457 rispetta l'edge ma sfora "
            f"il vincolo di rischio del desk." + extra)


def mh458_mappa(power, gas, beta=None, z_entry=1.0, costo=0.20, H=10,
                capitale=1000000.0, f_max=0.25, alpha=0.05, limite=None):
    """Mappa completa: sizing tab457 + VaR/ES della posizione a h*.

    limite: soglia VaR in EUR; None -> 2% del capitale.
    Se il trade non passa il filtro di tab457 (segnale False o
    netto_star <= 0) ritorna rischio zero con zero_motivo = verdetto
    tab457. Altrimenti: se_star da mh455_forecast sulla stessa spread di
    tab456/457, mu_pnl = pnl_atteso, sigma_pnl = size * se_star,
    var/es a h*, var per unita' di spread, size_max/f_lim compatibili
    col limite, var_h/es_h/pnl_h per orizzonte, verdetto a 3-4 stati."""
    K = mh458_num(capitale, "capitale")
    if K <= 0.0:
        raise ValueError(f"mappa: capitale deve essere > 0 (trovato {K})")
    af = mh458_num(alpha, "alpha")
    if af <= 0.0 or af >= 1.0:
        raise ValueError(f"mappa: alpha deve stare in (0, 1) "
                         f"(trovato {af})")
    lim = 0.02 * K if limite is None else mh458_num(limite, "limite")
    if lim <= 0.0:
        raise ValueError(f"mappa: limite deve essere > 0 (trovato {lim})")
    m = mh457_mappa(power, gas, beta=beta, z_entry=z_entry, costo=costo,
                    H=H, capitale=K, f_max=f_max)
    base = {"n": m["n"], "T": m["T"], "H": m["H"], "beta": m["beta"],
            "z_entry": m["z_entry"], "costo": m["costo"],
            "z": m["z"], "segnale": m["segnale"],
            "spread_last": m["spread_last"], "h_star": m["h_star"],
            "lordo_star": m["lordo_star"], "netto_star": m["netto_star"],
            "prob_star": m["prob_star"], "size": m["size"],
            "f_star": m["f_star"], "f_app": m["f_app"],
            "pnl_atteso": m["pnl_atteso"], "p": m["p"], "L": m["L"],
            "direzione": m["direzione"], "verdetto_457": m["verdetto"],
            "capitale": K, "f_max": m["f_max"],
            "alpha": af, "limite": lim, "zero_motivo": m["zero_motivo"]}
    if m["zero_motivo"] is not None or m["size"] <= 0.0:
        base.update({"mu_pnl": 0.0, "sigma_pnl": 0.0, "se_star": 0.0,
                     "var": 0.0, "es": 0.0, "p_perdita": 0.0,
                     "var_pct": 0.0, "var_unit": 0.0,
                     "size_max": 0.0, "f_lim": 0.0,
                     "var_h": [], "es_h": [], "pnl_h": [],
                     "verdetto": mh458_verdetto(0.0, lim, af,
                                                zero_motivo=m["zero_motivo"])})
        return base
    # se_star dalla stessa forecast di tab455 usata da tab456/457
    sp = tuple(p - m["beta"] * g for p, g in zip(power, gas))
    fc = mh455_forecast(sp, H=m["H"])
    se_star = fc["se_h"][m["h_star"] - 1]
    mu_pnl = m["pnl_atteso"]
    sigma_pnl = m["size"] * se_star
    ve = mh458_var_es(mu_pnl, sigma_pnl, af)
    p_perdita = 1.0 - m["p"]
    var_pct = ve["var"] / K
    z_1 = mh458_quantile(1.0 - af)
    var_unit = -m["netto_star"] + z_1 * se_star
    if ve["var"] <= lim:
        size_max, f_lim = m["size"], m["f_app"]
    else:
        size_max = lim / var_unit if var_unit > 0.0 else m["size"]
        f_lim = size_max * m["L"] / K
    var_h, es_h, pnl_h = [], [], []
    last = sp[-1]
    for h in range(m["H"]):
        lordo_h = abs(fc["forecast"][h] - last)
        netto_h = lordo_h - m["costo"]
        veh = mh458_var_es(m["size"] * netto_h,
                           m["size"] * fc["se_h"][h], af)
        var_h.append(veh["var"])
        es_h.append(veh["es"])
        pnl_h.append(m["size"] * netto_h)
    base.update({"mu_pnl": mu_pnl, "sigma_pnl": sigma_pnl,
                 "se_star": se_star,
                 "var": ve["var"], "es": ve["es"],
                 "p_perdita": p_perdita, "var_pct": var_pct,
                 "var_unit": var_unit, "size_max": size_max,
                 "f_lim": f_lim, "var_h": var_h, "es_h": es_h,
                 "pnl_h": pnl_h,
                 "verdetto": mh458_verdetto(ve["var"], lim, af,
                                            size=m["size"],
                                            size_max=size_max,
                                            f_lim=f_lim)})
    return base

def mh457_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh457_mills(d):
    """Inverse Mills ratio phi(d)/Phi(d), d numero finito.

    Phi(d) <= 0 -> ValueError (nessuna massa sopra la soglia)."""
    import math
    dd = mh457_num(d, "d")
    Phi = mh456_phi(dd)
    if Phi <= 0.0:
        raise ValueError(f"mills: Phi({dd}) = 0, rapporto non definito")
    return math.exp(-0.5 * dd * dd) / math.sqrt(2.0 * math.pi) / Phi


def mh457_winloss(lordo, se, costo):
    """Momenti binari del trade: X ~ N(lordo, se^2), soglia = costo.

    Ritorna dict con d, p = P(X > costo), q = 1 - p,
    W = E[(X - costo) | X > costo], L = E[(costo - X) | X <= costo],
    b = W / L (odds del trade).
    se <= 0 -> ValueError; p non in (0, 1) -> ValueError;
    W <= 0 o L <= 0 -> ValueError."""
    lg = mh457_num(lordo, "lordo")
    sef = mh457_num(se, "se")
    co = mh457_num(costo, "costo")
    if sef <= 0.0:
        raise ValueError(f"winloss: se deve essere > 0 (trovato {sef})")
    d = (lg - co) / sef
    p = mh456_phi(d)
    if p <= 0.0 or p >= 1.0:
        raise ValueError(f"winloss: p = {p} fuori (0, 1), sizing "
                         f"impossibile")
    q = 1.0 - p
    phi_d = mh457_mills(d) * p  # phi(d) = Mills(d) * Phi(d)
    W = (lg - co) + sef * phi_d / p
    L = (co - lg) + sef * phi_d / q
    if W <= 0.0 or L <= 0.0:
        raise ValueError(f"winloss: W = {W}, L = {L} devono essere > 0")
    return {"d": d, "p": p, "q": q, "W": W, "L": L, "b": W / L}


def mh457_kelly(p, W, L):
    """Frazione di Kelly f* = p - q/b, b = W/L.

    p in [0, 1], W > 0, L > 0; f* puo' essere <= 0 (nessun edge ->
    il chiamante mette size zero)."""
    pf = mh457_num(p, "p")
    Wf = mh457_num(W, "W")
    Lf = mh457_num(L, "L")
    if pf < 0.0 or pf > 1.0:
        raise ValueError(f"kelly: p deve stare in [0, 1] (trovato {pf})")
    if Wf <= 0.0 or Lf <= 0.0:
        raise ValueError(f"kelly: W e L devono essere > 0 "
                         f"(trovati {Wf}, {Lf})")
    b = Wf / Lf
    return pf - (1.0 - pf) / b


def mh457_growth(p, b, f):
    """Crescita logaritmica attesa per trade: g(f) = p*ln(1 + f*b)
    + (1 - p)*ln(1 - f). f in [0, 1), b > 0, p in [0, 1]."""
    pf = mh457_num(p, "p")
    bf = mh457_num(b, "b")
    ff = mh457_num(f, "f")
    if pf < 0.0 or pf > 1.0:
        raise ValueError(f"growth: p deve stare in [0, 1] (trovato {pf})")
    if bf <= 0.0:
        raise ValueError(f"growth: b deve essere > 0 (trovato {bf})")
    if ff < 0.0 or ff >= 1.0:
        raise ValueError(f"growth: f deve stare in [0, 1) (trovato {ff})")
    import math
    return pf * math.log(1.0 + ff * bf) + (1.0 - pf) * math.log(1.0 - ff)


def mh457_verdetto(f_star, f_app, capped, zero_motivo=None):
    """Verdetto a 5 stati sul sizing:
    SIZING ZERO (il trade non passa il filtro tab456: zero_motivo
    e' il verdetto di tab456), NESSUN EDGE (f* <= 0), CAPPATO
    (f* > f_max: il cap operativo taglia il Kelly pieno), OK
    (f* applicato per intero), RIDOTTO (half-Kelly sotto il cap?
    no: l'half e' solo informativo, lo stato resta OK/CAPPATO).
    zero_motivo non None -> SIZING ZERO; altrimenti f_star numero
    finito, f_app in [0, 1], capped bool."""
    if zero_motivo is not None:
        return (f"SIZING ZERO — {zero_motivo} Il desk non apre "
                f"posizioni su un trade che non passa il filtro.")
    fs = mh457_num(f_star, "f_star")
    fa = mh457_num(f_app, "f_app")
    if not isinstance(capped, bool):
        raise ValueError("verdetto: capped deve essere un bool")
    if fa < 0.0 or fa > 1.0:
        raise ValueError(f"verdetto: f_app deve stare in [0, 1] "
                         f"(trovato {fa})")
    if fs <= 0.0:
        return (f"NESSUN EDGE — f* = {fs:.2%}: l'edge stimato non "
                f"copre le odds del trade. Size zero.")
    if capped:
        return (f"CAPPATO — f* = {fs:.2%} supera il cap operativo: "
                f"size applicata f = {fa:.2%} del capitale. Il Kelly "
                f"pieno su edge stimato e' aggressivo: il cap protegge "
                f"dal sovradimensionamento.")
    return (f"OK — f* = {fs:.2%} entro il cap: size applicata "
            f"f = {fa:.2%} del capitale. Half-Kelly ({fs / 2:.2%}) "
            f"resta l'opzione prudente con edge stimato.")


def mh457_mappa(power, gas, beta=None, z_entry=1.0, costo=0.20, H=10,
                capitale=1000000.0, f_max=0.25):
    """Mappa completa: trade di rientro (tab456) + sizing Kelly.

    capitale > 0 (EUR); f_max in (0, 1] (cap operativo sulla frazione).
    Se il trade non passa il filtro di tab456 (segnale False o
    netto_star <= 0) ritorna size zero con zero_motivo = verdetto
    tab456. Altrimenti calcola W/L/b a h*, f*, half-Kelly,
    f_applicata = min(max(f*, 0), f_max), size in unita' di spread,
    gambe power/gas in MWh (contro la deviazione), rischio = size*L,
    P&L atteso = size*netto_star, crescita logaritmica per i tre
    scenari, verdetto a 5 stati."""
    K = mh457_num(capitale, "capitale")
    if K <= 0.0:
        raise ValueError(f"mappa: capitale deve essere > 0 (trovato {K})")
    fm = mh457_num(f_max, "f_max")
    if fm <= 0.0 or fm > 1.0:
        raise ValueError(f"mappa: f_max deve stare in (0, 1] "
                         f"(trovato {fm})")
    m = mh456_mappa(power, gas, beta=beta, z_entry=z_entry,
                    costo=costo, H=H)
    base = {"n": m["n"], "T": m["T"], "H": m["H"], "beta": m["beta"],
            "z_entry": m["z_entry"], "costo": m["costo"],
            "z": m["z"], "segnale": m["segnale"],
            "spread_last": m["spread_last"],
            "h_star": m["h_star"], "lordo_star": m["lordo_star"],
            "netto_star": m["netto_star"], "prob_star": m["prob_star"],
            "verdetto_456": m["verdetto"],
            "capitale": K, "f_max": fm}
    if (not m["segnale"]) or m["netto_star"] <= 0.0:
        base.update({"f_star": 0.0, "f_half": 0.0, "f_app": 0.0,
                     "capped": False, "size": 0.0,
                     "gamba_power": 0.0, "gamba_gas": 0.0,
                     "direzione": "nessuna",
                     "p": 0.0, "q": 1.0, "W": 0.0, "L": 0.0, "b": 0.0,
                     "rischio": 0.0, "pnl_atteso": 0.0,
                     "g_kelly": 0.0, "g_half": 0.0, "g_app": 0.0,
                     "zero_motivo": m["verdetto"],
                     "verdetto": mh457_verdetto(0.0, 0.0, False,
                                                zero_motivo=m["verdetto"])})
        return base
    se_star = m["se_h"][m["h_star"] - 1]
    wl = mh457_winloss(m["lordo_star"], se_star, m["costo"])
    f_star = mh457_kelly(wl["p"], wl["W"], wl["L"])
    f_half = f_star / 2.0
    capped = f_star > fm
    f_app = min(max(f_star, 0.0), fm)
    size = f_app * K / wl["L"]
    # contro la deviazione: z < 0 -> long spread (long power, short gas)
    if m["z"] < 0.0:
        direzione = "long spread (long power / short gas)"
        gamba_power, gamba_gas = size, -size * m["beta"]
    else:
        direzione = "short spread (short power / long gas)"
        gamba_power, gamba_gas = -size, size * m["beta"]
    g_k = mh457_growth(wl["p"], wl["b"], min(max(f_star, 0.0), 0.999999))
    g_h = mh457_growth(wl["p"], wl["b"], min(max(f_half, 0.0), 0.999999))
    g_a = mh457_growth(wl["p"], wl["b"], min(f_app, 0.999999))
    base.update({"f_star": f_star, "f_half": f_half, "f_app": f_app,
                 "capped": capped, "size": size,
                 "gamba_power": gamba_power, "gamba_gas": gamba_gas,
                 "direzione": direzione,
                 "p": wl["p"], "q": wl["q"], "W": wl["W"], "L": wl["L"],
                 "b": wl["b"],
                 "rischio": size * wl["L"],
                 "pnl_atteso": size * m["netto_star"],
                 "g_kelly": g_k, "g_half": g_h, "g_app": g_a,
                 "zero_motivo": None,
                 "verdetto": mh457_verdetto(f_star, f_app, capped)})
    return base

def mh455_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh455_parse_serie(txt):
    """Una riga = un livello di prezzo; la virgola vale come decimale."""
    if not isinstance(txt, str):
        raise ValueError("serie: serve testo, un valore per riga")
    xs = []
    for i, ln in enumerate(txt.split("\n"), 1):
        s = ln.strip().replace(",", ".")
        if not s:
            continue
        try:
            v = float(s)
        except ValueError:
            raise ValueError(f"serie: riga {i} non numerica: {ln!r}")
        import math
        if math.isnan(v) or math.isinf(v):
            raise ValueError(f"serie: riga {i} non finita")
        xs.append(v)
    if len(xs) < 30:
        raise ValueError(f"serie: servono almeno 30 valori "
                         f"(trovati {len(xs)})")
    return tuple(xs)


def _mh455_seq(xs, nome):
    """Valida una sequenza di livelli: tupla di float, >= 30."""
    if xs is None:
        raise ValueError(f"{nome}: serve una sequenza di livelli")
    vs = tuple(mh455_num(x, nome) for x in xs)
    if len(vs) < 30:
        raise ValueError(f"{nome}: servono almeno 30 valori "
                         f"(trovati {len(vs)})")
    return vs


def _mh455_solve(A, B):
    """Risolve A X = B (A nxn, B nxm) con Gauss-Jordan + pivoting
    parziale. A singolare (pivot < 1e-12) -> ValueError."""
    n = len(A)
    if n == 0:
        raise ValueError("solve: matrice vuota")
    m = len(B[0])
    if any(len(row) != n for row in A) or len(B) != n:
        raise ValueError("solve: dimensioni incoerenti")
    aug = [list(map(float, A[i])) + list(map(float, B[i]))
           for i in range(n)]
    for col in range(n):
        piv = max(range(col, n), key=lambda r: abs(aug[r][col]))
        if abs(aug[piv][col]) < 1e-12:
            raise ValueError("solve: matrice singolare")
        aug[col], aug[piv] = aug[piv], aug[col]
        pv = aug[col][col]
        aug[col] = [v / pv for v in aug[col]]
        for r in range(n):
            if r != col and aug[r][col] != 0.0:
                f = aug[r][col]
                aug[r] = [v - f * w for v, w in zip(aug[r], aug[col])]
    return [row[n:] for row in aug]


def _mh455_ols(Z, Y):
    """OLS via equazioni normali: beta = (Z'Z)^-1 Z'Y.
    Z: T righe x k regressori, Y: T righe x m risposte."""
    T = len(Z)
    k = len(Z[0])
    m = len(Y[0])
    xtx = [[sum(Z[t][i] * Z[t][j] for t in range(T))
            for j in range(k)] for i in range(k)]
    xty = [[sum(Z[t][i] * Y[t][j] for t in range(T))
            for j in range(m)] for i in range(k)]
    return _mh455_solve(xtx, xty)


def mh455_ar1(spread):
    """AR(1) con intercetta sullo spread: spread_t = c + rho * spread_{t-1}
    + e_t (OLS su T = n - 1 osservazioni effettive).
    Ritorna dict con n, T, c, rho, s2 (varianza residua, T - 2 gdl),
    mu = c / (1 - rho) (media di lungo periodo), sigma (std campionaria
    dello spread). |rho| >= 1 -> ValueError: niente forecast che
    esplode o diverge (prima il test formale di tab454). s2 <= 0 ->
    ValueError."""
    import math
    ys = _mh455_seq(spread, "spread")
    n = len(ys)
    mu0 = sum(ys) / n
    if sum((v - mu0) ** 2 for v in ys) <= 0.0:
        raise ValueError("ar1: spread costante")
    Z = [[1.0, ys[t - 1]] for t in range(1, n)]
    Y = [[ys[t]] for t in range(1, n)]
    T = n - 1
    b = _mh455_ols(Z, Y)
    c, rho = b[0][0], b[1][0]
    if abs(rho) >= 1.0:
        raise ValueError(f"ar1: |rho| = {abs(rho):.4f} >= 1: lo spread "
                         f"non e' mean-reverting, il forecast non "
                         f"rientrerebbe mai (usa tab454 per il test "
                         f"formale)")
    resid = [Y[t][0] - (c + rho * Z[t][1]) for t in range(T)]
    s2 = sum(r * r for r in resid) / (T - 2)
    if s2 <= 0.0:
        raise ValueError("ar1: varianza residua nulla")
    mu = c / (1.0 - rho)
    sigma = math.sqrt(sum((v - mu0) ** 2 for v in ys) / n)
    return {"n": n, "T": T, "c": c, "rho": rho, "s2": s2,
            "mu": mu, "sigma": sigma}


def mh455_forecast(spread, H=10):
    """Forecast mean-reversion a H passi dallo spread.

    f_h = mu + rho^h * (spread_T - mu); bande 68/95% da
    var_h = s2 * (1 - rho^{2h}) / (1 - rho^2).
    half_life = ln(0.5) / ln(rho) se 0 < rho < 1, altrimenti None
    (rho negativo: rientro oscillante, non monotono).
    z = (spread_T - mu) / sigma (z-score corrente).
    rientro = primo h in [1, H] con |f_h - mu| <= 0.5 * sigma,
    None se oltre l'orizzonte.
    H intero in [1, 30], altrimenti ValueError.
    Ritorna dict con n, T, H, c, rho, s2, mu, sigma, half_life, z,
    spread_last, forecast, se_h, lo68, hi68, lo95, hi95, rientro."""
    import math
    if isinstance(H, bool) or not isinstance(H, int):
        raise ValueError("forecast: H deve essere un intero")
    if H < 1 or H > 30:
        raise ValueError(f"forecast: H deve stare in [1, 30] "
                         f"(trovato {H})")
    r = mh455_ar1(spread)
    rho, mu, s2, sigma = r["rho"], r["mu"], r["s2"], r["sigma"]
    ys = _mh455_seq(spread, "spread")
    last = ys[-1]
    fc, se = [], []
    for h in range(1, H + 1):
        fc.append(mu + (rho ** h) * (last - mu))
        var_h = s2 * (1.0 - rho ** (2 * h)) / (1.0 - rho ** 2)
        se.append(math.sqrt(max(var_h, 0.0)))
    lo68 = [f - s for f, s in zip(fc, se)]
    hi68 = [f + s for f, s in zip(fc, se)]
    lo95 = [f - 1.96 * s for f, s in zip(fc, se)]
    hi95 = [f + 1.96 * s for f, s in zip(fc, se)]
    hl = (math.log(0.5) / math.log(rho) if 0.0 < rho < 1.0 else None)
    z = (last - mu) / sigma if sigma > 0.0 else 0.0
    rientro = next((h for h, f in enumerate(fc, 1)
                    if abs(f - mu) <= 0.5 * sigma), None)
    return {"n": r["n"], "T": r["T"], "H": H, "c": r["c"], "rho": rho,
            "s2": s2, "mu": mu, "sigma": sigma, "half_life": hl,
            "z": z, "spread_last": last, "forecast": fc, "se_h": se,
            "lo68": lo68, "hi68": hi68, "lo95": lo95, "hi95": hi95,
            "rientro": rientro}


def mh455_verdetto(z, rientro, H=10):
    """Verdetto a 5 stati sullo z-score corrente
    z = (spread_T - mu) / sigma:
    SPREAD MOLTO ALTO (z >= 2), SPREAD ALTO (1 <= z < 2),
    IN EQUILIBRIO (-1 < z < 1), SPREAD BASSO (-2 < z <= -1),
    SPREAD MOLTO BASSO (z <= -2).
    Il testo riporta il rientro atteso (giorni) o "oltre l'orizzonte".
    z NaN/inf/non numero -> ValueError; rientro non None e non
    intero >= 1 -> ValueError."""
    import math
    if isinstance(z, bool):
        raise ValueError("verdetto: z deve essere un numero")
    try:
        zf = float(z)
    except (TypeError, ValueError):
        raise ValueError("verdetto: z deve essere un numero")
    if math.isnan(zf) or math.isinf(zf):
        raise ValueError("verdetto: z deve essere finito")
    if rientro is not None:
        if isinstance(rientro, bool) or not isinstance(rientro, int):
            raise ValueError("verdetto: rientro deve essere un intero "
                             "o None")
        if rientro < 1:
            raise ValueError("verdetto: rientro deve essere >= 1")
    if isinstance(H, bool) or not isinstance(H, int) or H < 1:
        raise ValueError("verdetto: H deve essere un intero >= 1")
    if rientro is None:
        rtxt = (f"rientro atteso oltre l'orizzonte di {H} giorni: lo "
                f"spread resta lontano dall'equilibrio per tutto "
                f"l'orizzonte")
    elif rientro == 1:
        rtxt = "rientro atteso in 1 giorno"
    else:
        rtxt = f"rientro atteso in {rientro} giorni"
    if zf >= 2.0:
        return (f"SPREAD MOLTO ALTO — z = {zf:.2f}: lo spread e' oltre "
                f"2 sigma sopra l'equilibrio, {rtxt}.")
    if zf >= 1.0:
        return (f"SPREAD ALTO — z = {zf:.2f}: lo spread e' sopra "
                f"l'equilibrio di oltre 1 sigma, {rtxt}.")
    if zf > -1.0:
        return (f"IN EQUILIBRIO — z = {zf:.2f}: lo spread e' entro "
                f"1 sigma dall'equilibrio, nessun trade di rientro "
                f"segnalato ({rtxt}).")
    if zf > -2.0:
        return (f"SPREAD BASSO — z = {zf:.2f}: lo spread e' sotto "
                f"l'equilibrio di oltre 1 sigma, {rtxt}.")
    return (f"SPREAD MOLTO BASSO — z = {zf:.2f}: lo spread e' oltre "
            f"2 sigma sotto l'equilibrio, {rtxt}.")


def mh455_mappa(power, gas, beta=None, H=10):
    """Mappa completa: spread di cointegrazione + forecast mean-reversion.

    beta None -> stimata con mh447_eig (Johansen, tab447, p = 1) su
    tutto il campione, con controllo rango 1 su ENTRAMBI i test
    (traccia e max-autovalore); beta esplicita -> validata come numero
    finito (responsabilita' dell'utente).
    Ritorna dict con n, T, H, beta, spread, c, rho, s2, mu, sigma,
    half_life, z, spread_last, forecast, se_h, lo68/hi68/lo95/hi95,
    rientro, verdetto."""
    ys = _mh455_seq(power, "power")
    gs = _mh455_seq(gas, "gas")
    if len(ys) != len(gs):
        raise ValueError(f"power e gas devono avere la stessa "
                         f"lunghezza ({len(ys)} vs {len(gs)})")
    n = len(ys)
    for seq, nome in ((ys, "power"), (gs, "gas")):
        mu = sum(seq) / n
        if sum((v - mu) ** 2 for v in seq) <= 0.0:
            raise ValueError(f"mappa: serie {nome} costante")
    if beta is None:
        eig = mh447_eig(ys, gs)
        lam1, lam2, Te = eig["lam1"], eig["lam2"], eig["T"]
        r_tr = mh447_rango((lam1, lam2), Te, "trace")
        r_mx = mh447_rango((lam1, lam2), Te, "max")
        if r_tr != 1 or r_mx != 1:
            if r_tr == 0 or r_mx == 0:
                raise ValueError(
                    "mappa: Johansen non trova cointegrazione "
                    f"(rango traccia={r_tr}, max={r_mx}): lo spread "
                    "non e' identificato")
            raise ValueError(
                "mappa: Johansen trova rango 2 (entrambe "
                "stazionarie): usa un VAR sulle serie, non un VECM")
        beta = eig["beta"]
    else:
        beta = mh455_num(beta, "beta")
    spread = [y - beta * g for y, g in zip(ys, gs)]
    r = mh455_forecast(spread, H=H)
    return {"n": n, "T": r["T"], "H": H, "beta": beta,
            "spread": spread, "c": r["c"], "rho": r["rho"],
            "s2": r["s2"], "mu": r["mu"], "sigma": r["sigma"],
            "half_life": r["half_life"], "z": r["z"],
            "spread_last": r["spread_last"], "forecast": r["forecast"],
            "se_h": r["se_h"], "lo68": r["lo68"], "hi68": r["hi68"],
            "lo95": r["lo95"], "hi95": r["hi95"],
            "rientro": r["rientro"],
            "verdetto": mh455_verdetto(r["z"], r["rientro"], H)}

def mh454_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh454_parse_serie(txt):
    """Una riga = un livello di prezzo; la virgola vale come decimale."""
    if not isinstance(txt, str):
        raise ValueError("serie: serve testo, un valore per riga")
    xs = []
    for i, ln in enumerate(txt.split("\n"), 1):
        s = ln.strip().replace(",", ".")
        if not s:
            continue
        try:
            v = float(s)
        except ValueError:
            raise ValueError(f"serie: riga {i} non numerica: {ln!r}")
        import math
        if math.isnan(v) or math.isinf(v):
            raise ValueError(f"serie: riga {i} non finita")
        xs.append(v)
    if len(xs) < 30:
        raise ValueError(f"serie: servono almeno 30 valori "
                         f"(trovati {len(xs)})")
    return tuple(xs)


def _mh454_seq(xs, nome):
    """Valida una sequenza di livelli: tupla di float, >= 30."""
    if xs is None:
        raise ValueError(f"{nome}: serve una sequenza di livelli")
    vs = tuple(mh454_num(x, nome) for x in xs)
    if len(vs) < 30:
        raise ValueError(f"{nome}: servono almeno 30 valori "
                         f"(trovati {len(vs)})")
    return vs


def _mh454_solve(A, B):
    """Risolve A X = B (A nxn, B nxm) con Gauss-Jordan + pivoting
    parziale. A singolare (pivot < 1e-12) -> ValueError."""
    n = len(A)
    if n == 0:
        raise ValueError("solve: matrice vuota")
    m = len(B[0])
    if any(len(row) != n for row in A) or len(B) != n:
        raise ValueError("solve: dimensioni incoerenti")
    aug = [list(map(float, A[i])) + list(map(float, B[i]))
           for i in range(n)]
    for col in range(n):
        piv = max(range(col, n), key=lambda r: abs(aug[r][col]))
        if abs(aug[piv][col]) < 1e-12:
            raise ValueError("solve: matrice singolare")
        aug[col], aug[piv] = aug[piv], aug[col]
        pv = aug[col][col]
        aug[col] = [v / pv for v in aug[col]]
        for r in range(n):
            if r != col and aug[r][col] != 0.0:
                f = aug[r][col]
                aug[r] = [v - f * w for v, w in zip(aug[r], aug[col])]
    return [row[n:] for row in aug]


def _mh454_ols(Z, Y):
    """OLS via equazioni normali: beta = (Z'Z)^-1 Z'Y.
    Z: T righe x k regressori, Y: T righe x m risposte."""
    T = len(Z)
    k = len(Z[0])
    m = len(Y[0])
    xtx = [[sum(Z[t][i] * Z[t][j] for t in range(T))
            for j in range(k)] for i in range(k)]
    xty = [[sum(Z[t][i] * Y[t][j] for t in range(T))
            for j in range(m)] for i in range(k)]
    return _mh454_solve(xtx, xty)


def mh454_critico(livello):
    """Valori critici Dickey-Fuller (costante, senza trend, ~60 oss.):
    1% -> -3.51, 5% -> -2.89, 10% -> -2.58 (MacKinnon, approssimazione:
    il verdetto sulla demo, t = -4.32, non dipende dalla scelta fine)."""
    if livello == 1:
        return -3.51
    if livello == 5:
        return -2.89
    if livello == 10:
        return -2.58
    raise ValueError("critico: livello deve essere 1, 5 o 10")


def mh454_adf(spread, lags=1):
    """Test ADF sullo spread (H0: radice unitaria).

    Lo spread viene demeaned; regressione di d(spread)_t su
    [1, spread_{t-1}, d(spread)_{t-1}, ..., d(spread)_{t-lags}].
    t-stat = gamma / se(gamma) con se dalla varianza OLS
    s2 * (Z'Z)^{-1}[1,1]. lags intero in [0, 4].
    Ritorna dict con n, T (osservazioni effettive), lags, gamma,
    se_gamma, t_stat, half_life (None se non rientra)."""
    import math
    if isinstance(lags, bool) or not isinstance(lags, int):
        raise ValueError("adf: lags deve essere un intero")
    if lags < 0 or lags > 4:
        raise ValueError(f"adf: lags deve stare in [0, 4] "
                         f"(trovato {lags})")
    ys = _mh454_seq(spread, "spread")
    n = len(ys)
    mu = sum(ys) / n
    if sum((v - mu) ** 2 for v in ys) <= 0.0:
        raise ValueError("adf: spread costante")
    y = [v - mu for v in ys]
    dy = [y[t] - y[t - 1] for t in range(1, n)]
    Z = []
    Y = []
    for t in range(lags + 1, n):
        Z.append([1.0, y[t - 1]] +
                 [dy[t - 1 - j] for j in range(1, lags + 1)])
        Y.append([dy[t - 1]])
    T = len(Z)
    k = len(Z[0])
    b = _mh454_ols(Z, Y)
    resid = [Y[t][0] - sum(Z[t][i] * b[i][0] for i in range(k))
             for t in range(T)]
    s2 = sum(r * r for r in resid) / (T - k)
    if s2 <= 0.0:
        raise ValueError("adf: varianza residua nulla")
    xtx = [[sum(Z[t][i] * Z[t][j] for t in range(T))
            for j in range(k)] for i in range(k)]
    eye = [[1.0 if i == j else 0.0 for j in range(k)]
           for i in range(k)]
    inv = _mh454_solve(xtx, eye)
    gamma = b[1][0]
    se_gamma = math.sqrt(s2 * inv[1][1])
    t_stat = gamma / se_gamma
    half = (math.log(0.5) / math.log(1.0 + gamma)
            if -2.0 < gamma < 0.0 else None)
    return {"n": n, "T": T, "lags": lags, "gamma": gamma,
            "se_gamma": se_gamma, "t_stat": t_stat,
            "half_life": half}


def mh454_verdetto(t_stat):
    """Verdetto a 5 stati sulla t-stat ADF:
    STAZIONARIO (t < -3.51, rifiuto all'1%),
    PROBABILMENTE STAZIONARIO (-3.51 <= t < -2.89, rifiuto al 5%),
    DUBBIO (-2.89 <= t < -2.58),
    PROBABILMENTE NON STAZIONARIO (-2.58 <= t < 0),
    NON STAZIONARIO (t >= 0).
    t_stat NaN/inf/non numero -> ValueError."""
    import math
    if isinstance(t_stat, bool):
        raise ValueError("verdetto: t_stat deve essere un numero")
    try:
        s = float(t_stat)
    except (TypeError, ValueError):
        raise ValueError("verdetto: t_stat deve essere un numero")
    if math.isnan(s) or math.isinf(s):
        raise ValueError("verdetto: t_stat deve essere finito")
    c1, c5, c10 = (mh454_critico(1), mh454_critico(5),
                   mh454_critico(10))
    if s < c1:
        return ("STAZIONARIO — rifiuto la radice unitaria all'1%: "
                "lo spread rientra verso la media, la relazione di "
                "lungo periodo regge.")
    if s < c5:
        return ("PROBABILMENTE STAZIONARIO — rifiuto al 5% ma non "
                "all'1%: lo spread sembra rientrare, ma con meno "
                "forza statistica.")
    if s < c10:
        return ("DUBBIO — tra il 5% e il 10%: non si puo' concludere, "
                "servono piu' osservazioni o un modello diverso.")
    if s < 0.0:
        return ("PROBABILMENTE NON STAZIONARIO — nessun rifiuto: lo "
                "spread potrebbe non rientrare, attenzione a usarlo "
                "come segnale.")
    return ("NON STAZIONARIO — t-stat >= 0: lo spread non mostra "
            "alcun rientro, la cointegrazione non e' sfruttabile.")


def mh454_mappa(power, gas, beta=None, lags=1):
    """Mappa completa: spread di cointegrazione + test ADF.

    beta None -> stimata con mh447_eig (Johansen, tab447, p = 1) su
    tutto il campione, con controllo rango 1 su ENTRAMBI i test
    (traccia e max-autovalore); beta esplicita -> validata come numero
    finito (responsabilita' dell'utente).
    Ritorna dict con n, beta, lags, spread, spread_mean, spread_std,
    gamma, se_gamma, t_stat, T, half_life, cv1/cv5/cv10, verdetto."""
    import math
    ys = _mh454_seq(power, "power")
    gs = _mh454_seq(gas, "gas")
    if len(ys) != len(gs):
        raise ValueError(f"power e gas devono avere la stessa "
                         f"lunghezza ({len(ys)} vs {len(gs)})")
    n = len(ys)
    for seq, nome in ((ys, "power"), (gs, "gas")):
        mu = sum(seq) / n
        if sum((v - mu) ** 2 for v in seq) <= 0.0:
            raise ValueError(f"mappa: serie {nome} costante")
    if beta is None:
        eig = mh447_eig(ys, gs)
        lam1, lam2, Te = eig["lam1"], eig["lam2"], eig["T"]
        r_tr = mh447_rango((lam1, lam2), Te, "trace")
        r_mx = mh447_rango((lam1, lam2), Te, "max")
        if r_tr != 1 or r_mx != 1:
            if r_tr == 0 or r_mx == 0:
                raise ValueError(
                    "mappa: Johansen non trova cointegrazione "
                    f"(rango traccia={r_tr}, max={r_mx}): lo spread "
                    "non e' identificato")
            raise ValueError(
                "mappa: Johansen trova rango 2 (entrambe "
                "stazionarie): usa un VAR sulle serie, non un VECM")
        beta = eig["beta"]
    else:
        beta = mh454_num(beta, "beta")
    spread = [y - beta * g for y, g in zip(ys, gs)]
    mu_s = sum(spread) / n
    sd_s = math.sqrt(sum((v - mu_s) ** 2 for v in spread) / n)
    r = mh454_adf(spread, lags=lags)
    return {"n": n, "beta": beta, "lags": lags,
            "spread": spread, "spread_mean": mu_s, "spread_std": sd_s,
            "gamma": r["gamma"], "se_gamma": r["se_gamma"],
            "t_stat": r["t_stat"], "T": r["T"],
            "half_life": r["half_life"],
            "cv1": mh454_critico(1), "cv5": mh454_critico(5),
            "cv10": mh454_critico(10),
            "verdetto": mh454_verdetto(r["t_stat"])}

def mh453_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh453_parse_serie(txt):
    """Una riga = un livello di prezzo; la virgola vale come decimale."""
    if not isinstance(txt, str):
        raise ValueError("serie: serve testo, un valore per riga")
    xs = []
    for i, ln in enumerate(txt.split("\n"), 1):
        s = ln.strip().replace(",", ".")
        if not s:
            continue
        try:
            v = float(s)
        except ValueError:
            raise ValueError(f"serie: riga {i} non numerica: {ln!r}")
        import math
        if math.isnan(v) or math.isinf(v):
            raise ValueError(f"serie: riga {i} non finita")
        xs.append(v)
    if len(xs) < 30:
        raise ValueError(f"serie: servono almeno 30 valori "
                         f"(trovati {len(xs)})")
