def _mh453_seq(xs, nome):
    """Valida una sequenza di livelli: tupla di float, >= 30."""
    if xs is None:
        raise ValueError(f"{nome}: serve una sequenza di livelli")
    vs = tuple(mh453_num(x, nome) for x in xs)
    if len(vs) < 30:
        raise ValueError(f"{nome}: servono almeno 30 valori "
                         f"(trovati {len(vs)})")
    return vs


def _mh453_solve(A, B):
    """Risolve A X = B (A nxn, B nxm) con Gauss-Jordan + pivoting
    parziale. A singolare (pivot < 1e-12) -> ValueError."""
    n = len(A)
    if n == 0:
        raise ValueError("solve: matrice vuota")
    m = len(B[0])
    if any(len(row) != n for row in A) or len(B) != n:
        raise ValueError("solve: dimensioni incoerenti")
    aug = [list(map(float, A[i])) + list(map(float, B[i]))
           for i in range(n)]
    for col in range(n):
        piv = max(range(col, n), key=lambda r: abs(aug[r][col]))
        if abs(aug[piv][col]) < 1e-12:
            raise ValueError("solve: matrice singolare")
        aug[col], aug[piv] = aug[piv], aug[col]
        pv = aug[col][col]
        aug[col] = [v / pv for v in aug[col]]
        for r in range(n):
            if r != col and aug[r][col] != 0.0:
                f = aug[r][col]
                aug[r] = [v - f * w for v, w in zip(aug[r], aug[col])]
    return [row[n:] for row in aug]


def _mh453_ols(Z, Y):
    """OLS via equazioni normali: beta = (Z'Z)^-1 Z'Y.
    Z: T righe x k regressori, Y: T righe x m risposte."""
    T = len(Z)
    k = len(Z[0])
    m = len(Y[0])
    xtx = [[sum(Z[t][i] * Z[t][j] for t in range(T))
            for j in range(k)] for i in range(k)]
    xty = [[sum(Z[t][i] * Y[t][j] for t in range(T))
            for j in range(m)] for i in range(k)]
    return _mh453_solve(xtx, xty)


def _mh453_phi(x):
    """Ripartizione della normale standard (via erf)."""
    import math
    return 0.5 * (1.0 + math.erf(x / math.sqrt(2.0)))


def _mh453_ecm_fit(ys_w, gs_w, beta):
    """Stima ECM per equazione su una finestra + forma VAR(1) in
    livelli. ys_w/gs_w: finestre di uguale lunghezza (>= 2).
    Ritorna (A, c, alpha_power, alpha_gas) con z = [gas, power]:
      A = [[1 - a_g*beta, a_g], [-a_p*beta, 1 + a_p]],
      c = [c_g - a_g*mu, c_p - a_p*mu] (l'ec e' demeaned con media mu:
      senza il termine -alpha*mu la previsione in livelli avrebbe un
      bias sistematico; stessa correzione di mh452_forecast, fix
      14/10/2026)."""
    n = len(ys_w)
    ec_raw = [y - beta * g for y, g in zip(ys_w, gs_w)]
    mu = sum(ec_raw) / n
    ec = [v - mu for v in ec_raw]
    if sum(v * v for v in ec) <= 0.0:
        raise ValueError("ecm_fit: termine di correzione costante "
                         "(spread nullo?)")
    alphas = {}
    consts = {}
    for nome, y in (("power", ys_w), ("gas", gs_w)):
        Z = [[ec[t - 1], 1.0] for t in range(1, n)]
        Y = [[y[t] - y[t - 1]] for t in range(1, n)]
        b = _mh453_ols(Z, Y)
        alphas[nome], consts[nome] = b[0][0], b[1][0]
    a_p, a_g = alphas["power"], alphas["gas"]
    A = [[1.0 - a_g * beta, a_g],
         [-a_p * beta, 1.0 + a_p]]
    c = [consts["gas"] - a_g * mu, consts["power"] - a_p * mu]
    return A, c, a_p, a_g


def mh453_backtest(power, gas, W=40, beta=None):
    """Backtest rolling one-step-ahead del VECM(1) contro random walk
    e AR(1) con intercept.

    Stima: beta da mh447_eig (Johansen, tab447, p = 1) UNA volta su
    tutto il campione, con controllo rango 1 su ENTRAMBI i test
    (traccia e max-autovalore); poi per ogni i = W..n-1 si stima
    l'ECM sulla finestra [i-W, i) (_mh453_ecm_fit) e si prevede il
    power a i: VECM = A[1,:] z_{i-1} + c[1], RW = y_{i-1}, AR(1) =
    a*y_{i-1} + c stimato sulla finestra.
    W intero in [30, n-1] (almeno 1 forecast; per il test DM servono
    almeno 2 forecast, cioe' W <= n-2).
    Ritorna dict con n, W, K (= n - W), beta, actual, fc_vecm, fc_rw,
    fc_ar1, rmse_/mae_ per modello, A_last/c_last (fit dell'ultima
    finestra), last_power."""
    import math
    if isinstance(W, bool) or not isinstance(W, int):
        raise ValueError("backtest: W deve essere un intero")
    ys = _mh453_seq(power, "power")
    gs = _mh453_seq(gas, "gas")
    if len(ys) != len(gs):
        raise ValueError(f"power e gas devono avere la stessa "
                         f"lunghezza ({len(ys)} vs {len(gs)})")
    n = len(ys)
    for seq, nome in ((ys, "power"), (gs, "gas")):
        mu = sum(seq) / n
        if sum((v - mu) ** 2 for v in seq) <= 0.0:
            raise ValueError(f"backtest: serie {nome} costante")
    if W < 30 or W > n - 1:
        raise ValueError(f"backtest: W deve stare in [30, n-1] "
                         f"(n = {n})")
    if beta is None:
        eig = mh447_eig(ys, gs)
        lam1, lam2, Te = eig["lam1"], eig["lam2"], eig["T"]
        r_tr = mh447_rango((lam1, lam2), Te, "trace")
        r_mx = mh447_rango((lam1, lam2), Te, "max")
        if r_tr != 1 or r_mx != 1:
            if r_tr == 0 or r_mx == 0:
                raise ValueError(
                    "backtest: Johansen non trova cointegrazione "
                    f"(rango traccia={r_tr}, max={r_mx}): il backtest "
                    "VECM non e' identificato")
            raise ValueError(
                "backtest: Johansen trova rango 2 (entrambe "
                "stazionarie): usa un VAR sulle serie, non un VECM")
        beta = eig["beta"]
    else:
        beta = mh453_num(beta, "beta")
        eig = mh447_eig(ys, gs)
        lam1, lam2 = eig["lam1"], eig["lam2"]
    K = n - W
    actual, f_v, f_r, f_a = [], [], [], []
    A_last = c_last = None
    for i in range(W, n):
        yw = ys[i - W:i]
        gw = gs[i - W:i]
        A, c, _, _ = _mh453_ecm_fit(yw, gw, beta)
        A_last, c_last = A, c
        f_v.append(A[1][0] * gs[i - 1] + A[1][1] * ys[i - 1] + c[1])
        f_r.append(ys[i - 1])
        Za = [[yw[t - 1], 1.0] for t in range(1, W)]
        Ya = [[yw[t]] for t in range(1, W)]
        ba = _mh453_ols(Za, Ya)
        f_a.append(ba[0][0] * ys[i - 1] + ba[1][0])
        actual.append(ys[i])
    out = {"n": n, "W": W, "K": K, "beta": beta,
           "lam1": lam1, "lam2": lam2,
           "actual": actual, "fc_vecm": f_v, "fc_rw": f_r,
           "fc_ar1": f_a,
           "A_last": A_last, "c_last": c_last,
           "last_power": ys[-1]}
    for nome, fc in (("vecm", f_v), ("rw", f_r), ("ar1", f_a)):
        out[f"rmse_{nome}"] = math.sqrt(
            sum((a - f) ** 2 for a, f in zip(actual, fc)) / K)
        out[f"mae_{nome}"] = (sum(abs(a - f)
                                  for a, f in zip(actual, fc)) / K)
    return out


def mh453_metrics(actual, fc):
    """RMSE e MAE tra actual e forecast (stessa lunghezza, >= 1)."""
    import math
    if actual is None or fc is None:
        raise ValueError("metrics: servono actual e forecast")
    a = [mh453_num(x, "actual") for x in actual]
    f = [mh453_num(x, "fc") for x in fc]
    if len(a) != len(f) or len(a) == 0:
        raise ValueError("metrics: stessa lunghezza non vuota")
    n = len(a)
    return {"n": n,
            "rmse": math.sqrt(sum((x - y) ** 2
                                  for x, y in zip(a, f)) / n),
            "mae": sum(abs(x - y) for x, y in zip(a, f)) / n}


def mh453_dm(e_v, e_b):
    """Test di Diebold-Mariano (loss quadratica, h = 1: niente HAC).

    d_t = e_b^2 - e_v^2 (> 0: il VECM e' meglio del benchmark);
    DM = media(d) / sqrt(var(d)/K), p-value two-sided dalla normale
    standard. var(d) <= 0 -> DM = 0, p = 1 (indistinguibili).
    Servono almeno 2 errori per modello."""
    import math
    if e_v is None or e_b is None:
        raise ValueError("dm: servono gli errori dei due modelli")
    ev = [mh453_num(x, "e_v") for x in e_v]
    eb = [mh453_num(x, "e_b") for x in e_b]
    if len(ev) != len(eb) or len(ev) < 2:
        raise ValueError("dm: stessa lunghezza, almeno 2 errori")
    K = len(ev)
    d = [b * b - v * v for v, b in zip(ev, eb)]
    mean_d = sum(d) / K
    var_d = sum((x - mean_d) ** 2 for x in d) / (K - 1)
    if var_d <= 0.0:
        dm, p = 0.0, 1.0
    else:
        dm = mean_d / math.sqrt(var_d / K)
        p = 2.0 * (1.0 - _mh453_phi(abs(dm)))
    return {"n": K, "mean_d": mean_d, "var_d": var_d,
            "dm": dm, "p": p}


def mh453_verdetto(dm, p):
    """Verdetto a 5 stati sul DM VECM vs benchmark:
    BATTE NETTAMENTE (dm > 0, p < 0.01), BATTE (dm > 0, p < 0.05),
    PARI (p >= 0.05), PEGGIORE (dm < 0, p < 0.05),
    PEGGIORE NETTAMENTE (dm < 0, p < 0.01).
    dm/p NaN/inf/non numeri -> ValueError."""
    import math
    for v, nome in ((dm, "dm"), (p, "p")):
        if isinstance(v, bool):
            raise ValueError(f"verdetto: {nome} deve essere un numero")
        try:
            s = float(v)
        except (TypeError, ValueError):
            raise ValueError(f"verdetto: {nome} deve essere un numero")
        if math.isnan(s) or math.isinf(s):
            raise ValueError(f"verdetto: {nome} deve essere finito")
    dm_f, p_f = float(dm), float(p)
    if dm_f > 0.0:
        if p_f < 0.01:
            return ("BATTE NETTAMENTE — il VECM(1) batte il benchmark "
                    "in modo significativo (p < 1%): la cointegrazione "
                    "aiuta davvero la previsione a 1 passo.")
        if p_f < 0.05:
            return ("BATTE — il VECM(1) batte il benchmark (p < 5%): "
                    "la cointegrazione aggiunge potere previsivo a "
                    "1 passo.")
        return ("PARI — nessuna differenza significativa tra VECM(1) "
                "e benchmark (p >= 5%): la cointegrazione non aggiunge "
                "potere previsivo a 1 passo su questo campione.")
    if p_f < 0.01:
        return ("PEGGIORE NETTAMENTE — il VECM(1) perde contro il "
                "benchmark in modo significativo (p < 1%): meglio il "
                "benchmark, il modello e' mal specificato.")
    if p_f < 0.05:
        return ("PEGGIORE — il VECM(1) perde contro il benchmark "
                "(p < 5%): meglio il benchmark su questo campione.")
    return ("PARI — nessuna differenza significativa tra VECM(1) "
            "e benchmark (p >= 5%): la cointegrazione non aggiunge "
            "potere previsivo a 1 passo su questo campione.")


def mh453_mappa(power, gas, W=40, beta=None):
    """Mappa completa: backtest rolling VECM(1) vs RW e AR(1) +
    Diebold-Mariano + verdetti. Con K < 2 il DM non e' calcolabile
    (dm_rw/dm_ar1 = None, verdetti None)."""
    b = mh453_backtest(power, gas, W, beta)
    e_v = [a - f for a, f in zip(b["actual"], b["fc_vecm"])]
    e_r = [a - f for a, f in zip(b["actual"], b["fc_rw"])]
    e_a = [a - f for a, f in zip(b["actual"], b["fc_ar1"])]
    if b["K"] >= 2:
        dm_rw = mh453_dm(e_v, e_r)
        dm_ar1 = mh453_dm(e_v, e_a)
        b["dm_rw"] = dm_rw
        b["dm_ar1"] = dm_ar1
        b["verdetto_rw"] = mh453_verdetto(dm_rw["dm"], dm_rw["p"])
        b["verdetto_ar1"] = mh453_verdetto(dm_ar1["dm"], dm_ar1["p"])
    else:
        b["dm_rw"] = None
        b["dm_ar1"] = None
        b["verdetto_rw"] = None
        b["verdetto_ar1"] = None
    return b

def mh452_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh452_parse_serie(txt):
    """Una riga = un livello di prezzo; la virgola vale come decimale."""
    if not isinstance(txt, str):
        raise ValueError("serie: serve testo, un valore per riga")
    xs = []
    for i, ln in enumerate(txt.split("\n"), 1):
        s = ln.strip().replace(",", ".")
        if not s:
            continue
        try:
            v = float(s)
        except ValueError:
            raise ValueError(f"serie: riga {i} non numerica: {ln!r}")
        import math
        if math.isnan(v) or math.isinf(v):
            raise ValueError(f"serie: riga {i} non finita")
        xs.append(v)
    if len(xs) < 30:
        raise ValueError(f"serie: servono almeno 30 valori "
                         f"(trovati {len(xs)})")
    return tuple(xs)


def _mh452_seq(xs, nome):
    """Valida una sequenza di livelli: tupla di float, >= 30."""
    if xs is None:
        raise ValueError(f"{nome}: serve una sequenza di livelli")
    vs = tuple(mh452_num(x, nome) for x in xs)
    if len(vs) < 30:
        raise ValueError(f"{nome}: servono almeno 30 valori "
                         f"(trovati {len(vs)})")
    return vs


def _mh452_solve(A, B):
    """Risolve A X = B (A nxn, B nxm) con Gauss-Jordan + pivoting
    parziale. A singolare (pivot < 1e-12) -> ValueError."""
    n = len(A)
    if n == 0:
        raise ValueError("solve: matrice vuota")
    m = len(B[0])
    if any(len(row) != n for row in A) or len(B) != n:
        raise ValueError("solve: dimensioni incoerenti")
    aug = [list(map(float, A[i])) + list(map(float, B[i]))
           for i in range(n)]
    for col in range(n):
        piv = max(range(col, n), key=lambda r: abs(aug[r][col]))
        if abs(aug[piv][col]) < 1e-12:
            raise ValueError("solve: matrice singolare")
        aug[col], aug[piv] = aug[piv], aug[col]
        pv = aug[col][col]
        aug[col] = [v / pv for v in aug[col]]
        for r in range(n):
            if r != col and aug[r][col] != 0.0:
                f = aug[r][col]
                aug[r] = [v - f * w for v, w in zip(aug[r], aug[col])]
    return [row[n:] for row in aug]


def _mh452_ols(Z, Y):
    """OLS via equazioni normali: beta = (Z'Z)^-1 Z'Y.
    Z: T righe x k regressori, Y: T righe x m risposte."""
    T = len(Z)
    k = len(Z[0])
    m = len(Y[0])
    xtx = [[sum(Z[t][i] * Z[t][j] for t in range(T))
            for j in range(k)] for i in range(k)]
    xty = [[sum(Z[t][i] * Y[t][j] for t in range(T))
            for j in range(m)] for i in range(k)]
    return _mh452_solve(xtx, xty)


def _mh452_matmul(A, B):
    """Prodotto 2x2."""
    return [[A[0][0] * B[0][0] + A[0][1] * B[1][0],
             A[0][0] * B[0][1] + A[0][1] * B[1][1]],
            [A[1][0] * B[0][0] + A[1][1] * B[1][0],
             A[1][0] * B[0][1] + A[1][1] * B[1][1]]]


def mh452_forecast(power, gas, beta=None, H=20):
    """Previsione a H passi dal VECM(1) bivariato [gas, power].

    Stima: beta da mh447_eig (Johansen, tab447, p = 1) se None, con
    controllo rango 1 su ENTRAMBI i test (traccia e max-autovalore);
    ECM per equazione (OLS di dy su [ec_{t-1}, 1], stessa meccanica
    di tab448/449/450/451); Sigma_e dai residui (dof T - 2).
    Forma VAR(1) in livelli z_t = A z_{t-1} + c + e_t, z = [gas,
    power]:
      A = [[1 - a_g*beta, a_g], [-a_p*beta, 1 + a_p]],
      c = [c_g - a_g*mu_ec, c_p - a_p*mu_ec] (l'ec e' demeaned con media
      mu_ec: senza il termine -alpha*mu_ec la previsione in livelli
      avrebbe un bias sistematico di -alpha*mu_ec per passo).
    Previsione puntuale: zh_0 = z_n, zh_{k+1} = A zh_k + c.
    Covarianza errore: F_0 = 0, F_{k+1} = Sigma_e + A F_k A'.
    Bande: punto +/- 1.96*sqrt(diag F_k) (95%), +/- 1.0 (68%).
    Niente identificazione strutturale: niente Cholesky, la banda a
    h=1 usa la deviazione MARGINALE dei residui.
    H intero in [1, 60].
    Ritorna dict con n, T (= n - 1), H, beta, lam1, lam2,
    alpha_power, const_power, se_power, t_power, alpha_gas,
    const_gas, se_gas, t_gas, sigma_g, sigma_p (marginali),
    corr_resid, A, c, last_power, last_gas, pw_pt/gs_pt (punti, H),
    pw_var/gs_var (varianze errore, H), pw_lo95/pw_hi95/pw_lo68/
    pw_hi68 e gs_* (bande, H), chg_pw/chg_gs (variazione % attesa a
    H sul last), w95_pw/w95_gs (ampiezza banda 95% a H / last),
    gas_esogeno (|t_alpha_gas| < 2)."""
    import math
    if isinstance(H, bool) or not isinstance(H, int):
        raise ValueError("forecast: H deve essere un intero")
    if H < 1 or H > 60:
        raise ValueError("forecast: H deve stare in [1, 60] (oltre, "
                         "le bande del trend comune dominano)")
    ys = _mh452_seq(power, "power")
    gs = _mh452_seq(gas, "gas")
    if len(ys) != len(gs):
        raise ValueError(f"power e gas devono avere la stessa "
                         f"lunghezza ({len(ys)} vs {len(gs)})")
    n = len(ys)
    for seq, nome in ((ys, "power"), (gs, "gas")):
        mu = sum(seq) / n
        if sum((v - mu) ** 2 for v in seq) <= 0.0:
            raise ValueError(f"forecast: serie {nome} costante")
    if ys[-1] == 0.0 or gs[-1] == 0.0:
        raise ValueError("forecast: ultimo livello nullo (variazione "
                         "% non definita)")
    if beta is None:
        eig = mh447_eig(ys, gs)
        lam1, lam2, Te = eig["lam1"], eig["lam2"], eig["T"]
        r_tr = mh447_rango((lam1, lam2), Te, "trace")
        r_mx = mh447_rango((lam1, lam2), Te, "max")
        if r_tr != 1 or r_mx != 1:
            if r_tr == 0 or r_mx == 0:
                raise ValueError(
                    "forecast: Johansen non trova cointegrazione "
                    f"(rango traccia={r_tr}, max={r_mx}): la "
                    "previsione VECM non e' identificata")
            raise ValueError(
                "forecast: Johansen trova rango 2 (entrambe "
                "stazionarie): usa un VAR sulle serie, non un VECM")
        beta = eig["beta"]
    else:
        beta = mh452_num(beta, "beta")
        eig = mh447_eig(ys, gs)
        lam1, lam2 = eig["lam1"], eig["lam2"]
    ec_raw = [y - beta * g for y, g in zip(ys, gs)]
    mu_ec = sum(ec_raw) / n
    ec = tuple(v - mu_ec for v in ec_raw)
    if sum(v * v for v in ec) <= 0.0:
        raise ValueError("forecast: termine di correzione costante "
                         "(spread nullo?)")
    T = n - 1
    out = {"n": n, "T": T, "H": H, "beta": beta,
           "lam1": lam1, "lam2": lam2}
    resid = {}
    for nome, y in (("power", ys), ("gas", gs)):
        Z = [[ec[t - 1], 1.0] for t in range(1, n)]
        Y = [[y[t] - y[t - 1]] for t in range(1, n)]
        b = _mh452_ols(Z, Y)
        alpha, cst = b[0][0], b[1][0]
        rs = [Y[t][0] - (alpha * Z[t][0] + cst * Z[t][1])
              for t in range(T)]
        dof = T - 2
        s2 = sum(r * r for r in rs) / dof
        xtx = [[sum(Z[t][i] * Z[t][j] for t in range(T))
                for j in range(2)] for i in range(2)]
        inv = _mh452_solve(xtx, [[1.0, 0.0], [0.0, 1.0]])
        if s2 <= 0.0 or inv[0][0] <= 0.0:
            raise ValueError(f"forecast: varianza residua nulla "
                             f"su {nome}")
        se = math.sqrt(s2 * inv[0][0])
        out[f"alpha_{nome}"] = alpha
        out[f"const_{nome}"] = cst
        out[f"se_{nome}"] = se
        out[f"t_{nome}"] = alpha / se
        resid[nome] = rs
    ex, ey = resid["gas"], resid["power"]
    dof = T - 2
    s00 = sum(v * v for v in ex) / dof
    s11 = sum(v * v for v in ey) / dof
    s01 = sum(a * b_ for a, b_ in zip(ex, ey)) / dof
    Sigma = [[s00, s01], [s01, s11]]
    out["sigma_g"] = math.sqrt(s00)
    out["sigma_p"] = math.sqrt(s11)
    out["corr_resid"] = s01 / math.sqrt(s00 * s11)
    bta = beta
    a_g, a_p = out["alpha_gas"], out["alpha_power"]
    A = [[1.0 - a_g * bta, a_g],
         [-a_p * bta, 1.0 + a_p]]
    # FIX 14/10/2026: l'ec e' demeaned (media mu_ec), quindi la
    # costante del VAR(1) in livelli deve compensare: c = cst -
    # alpha*mu_ec. Prima mancava il termine -alpha*mu_ec e la
    # previsione in livelli aveva un bias sistematico di -alpha*mu_ec
    # per passo (sulla demo: -(-0.2605)*42.36 = +11.03 EUR/MWh sul
    # power a ogni passo).
    c = [out["const_gas"] - out["alpha_gas"] * mu_ec,
         out["const_power"] - out["alpha_power"] * mu_ec]
    out["A"] = [row[:] for row in A]
    out["c"] = c[:]
    out["last_power"] = ys[-1]
    out["last_gas"] = gs[-1]
    # previsione puntuale ricorsiva in livelli, da zh_0 = z_n
    zh = [gs[-1], ys[-1]]
    gs_pt, pw_pt = [], []
    for _ in range(H):
        zh = [A[0][0] * zh[0] + A[0][1] * zh[1] + c[0],
              A[1][0] * zh[0] + A[1][1] * zh[1] + c[1]]
        gs_pt.append(zh[0])
        pw_pt.append(zh[1])
    # covarianza dell'errore: F_{k+1} = Sigma_e + A F_k A'
    F = [[0.0, 0.0], [0.0, 0.0]]
    At = [[A[0][0], A[1][0]], [A[0][1], A[1][1]]]
    gs_v, pw_v = [], []
    for _ in range(H):
        AFA = _mh452_matmul(_mh452_matmul(A, F), At)
        F = [[Sigma[0][0] + AFA[0][0], Sigma[0][1] + AFA[0][1]],
             [Sigma[1][0] + AFA[1][0], Sigma[1][1] + AFA[1][1]]]
        if F[0][0] <= 0.0 or F[1][1] <= 0.0:
            raise ValueError("forecast: varianza di forecast nulla")
        gs_v.append(F[0][0])
        pw_v.append(F[1][1])
    out["pw_pt"] = pw_pt
    out["gs_pt"] = gs_pt
    out["pw_var"] = pw_v
    out["gs_var"] = gs_v

    def _bande(pt, var):
        lo95, hi95, lo68, hi68 = [], [], [], []
        for p_, v_ in zip(pt, var):
            s_ = math.sqrt(v_)
            lo95.append(p_ - 1.96 * s_)
            hi95.append(p_ + 1.96 * s_)
            lo68.append(p_ - s_)
            hi68.append(p_ + s_)
        return lo95, hi95, lo68, hi68

    (out["pw_lo95"], out["pw_hi95"],
     out["pw_lo68"], out["pw_hi68"]) = _bande(pw_pt, pw_v)
    (out["gs_lo95"], out["gs_hi95"],
     out["gs_lo68"], out["gs_hi68"]) = _bande(gs_pt, gs_v)
    out["chg_pw"] = (pw_pt[-1] - ys[-1]) / ys[-1]
    out["chg_gs"] = (gs_pt[-1] - gs[-1]) / gs[-1]
    out["w95_pw"] = (out["pw_hi95"][-1] - out["pw_lo95"][-1]) / ys[-1]
    out["w95_gs"] = (out["gs_hi95"][-1] - out["gs_lo95"][-1]) / gs[-1]
    out["gas_esogeno"] = abs(out["t_gas"]) < 2.0
    return out


def mh452_verdetto(chg):
    """Verdetto a 5 stati sulla variazione % attesa del power a H
    giorni dalla previsione VECM(1):
    RIALZO FORTE (chg >= +5%), RIALZO (+1%..+5%), LATERALE
    (-1%..+1%), RIBASSO (-5%..-1%), RIBASSO FORTE (chg <= -5%).
    chg NaN/inf/non numero -> ValueError."""
    import math
    if isinstance(chg, bool):
        raise ValueError("verdetto: chg deve essere un numero")
    try:
        s = float(chg)
    except (TypeError, ValueError):
        raise ValueError("verdetto: chg deve essere un numero")
    if math.isnan(s) or math.isinf(s):
        raise ValueError("verdetto: chg deve essere finito")
    pct = s * 100.0
    if s >= 0.05:
        return (f"RIALZO FORTE — la previsione VECM(1) vede il power "
                f"a {pct:+.1f}% in H giorni: lo spread e' sotto "
                f"l'equilibrio e il rientro spinge i prezzi su.")
    if s >= 0.01:
        return (f"RIALZO — la previsione VECM(1) vede il power a "
                f"{pct:+.1f}% in H giorni: rientro parziale dello "
                f"spread verso l'equilibrio.")
    if s > -0.01:
        return (f"LATERALE — la previsione VECM(1) vede il power a "
                f"{pct:+.1f}% in H giorni: lo spread e' vicino "
                f"all'equilibrio, nessun movimento atteso.")
    if s > -0.05:
        return (f"RIBASSO — la previsione VECM(1) vede il power a "
                f"{pct:+.1f}% in H giorni: lo spread sopra "
                f"l'equilibrio rientra verso il basso.")
    return (f"RIBASSO FORTE — la previsione VECM(1) vede il power a "
            f"{pct:+.1f}% in H giorni: lo spread e' molto sopra "
            f"l'equilibrio e il rientro e' marcato.")


def mh452_mappa(power, gas, beta=None, H=20):
    """Mappa completa: previsione VECM(1) + verdetto sulla direzione
    attesa del power + flag di debole esogeneita' del gas
    (|t_alpha_gas| < 2 -> il gas non corregge)."""
    f = mh452_forecast(power, gas, beta, H)
    f["verdetto"] = mh452_verdetto(f["chg_pw"])
    return f

def mh451_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh451_parse_serie(txt):
    """Una riga = un livello di prezzo; la virgola vale come decimale."""
    if not isinstance(txt, str):
        raise ValueError("serie: serve testo, un valore per riga")
    xs = []
    for i, ln in enumerate(txt.split("\n"), 1):
        s = ln.strip().replace(",", ".")
        if not s:
            continue
        try:
            v = float(s)
        except ValueError:
            raise ValueError(f"serie: riga {i} non numerica: {ln!r}")
        import math
        if math.isnan(v) or math.isinf(v):
            raise ValueError(f"serie: riga {i} non finita")
        xs.append(v)
    if len(xs) < 30:
        raise ValueError(f"serie: servono almeno 30 valori "
                         f"(trovati {len(xs)})")
    return tuple(xs)


def _mh451_seq(xs, nome):
    """Valida una sequenza di livelli: tupla di float, >= 30."""
    if xs is None:
        raise ValueError(f"{nome}: serve una sequenza di livelli")
    vs = tuple(mh451_num(x, nome) for x in xs)
    if len(vs) < 30:
        raise ValueError(f"{nome}: servono almeno 30 valori "
                         f"(trovati {len(vs)})")
    return vs


def _mh451_solve(A, B):
    """Risolve A X = B (A nxn, B nxm) con Gauss-Jordan + pivoting
    parziale. A singolare (pivot < 1e-12) -> ValueError."""
    n = len(A)
    if n == 0:
        raise ValueError("solve: matrice vuota")
    m = len(B[0])
    if any(len(row) != n for row in A) or len(B) != n:
        raise ValueError("solve: dimensioni incoerenti")
    aug = [list(map(float, A[i])) + list(map(float, B[i]))
           for i in range(n)]
    for col in range(n):
        piv = max(range(col, n), key=lambda r: abs(aug[r][col]))
        if abs(aug[piv][col]) < 1e-12:
            raise ValueError("solve: matrice singolare")
        aug[col], aug[piv] = aug[piv], aug[col]
        pv = aug[col][col]
        aug[col] = [v / pv for v in aug[col]]
        for r in range(n):
            if r != col and aug[r][col] != 0.0:
                f = aug[r][col]
                aug[r] = [v - f * w for v, w in zip(aug[r], aug[col])]
    return [row[n:] for row in aug]


def _mh451_ols(Z, Y):
    """OLS via equazioni normali: beta = (Z'Z)^-1 Z'Y.
    Z: T righe x k regressori, Y: T righe x m risposte."""
    T = len(Z)
    k = len(Z[0])
    m = len(Y[0])
    xtx = [[sum(Z[t][i] * Z[t][j] for t in range(T))
            for j in range(k)] for i in range(k)]
    xty = [[sum(Z[t][i] * Y[t][j] for t in range(T))
            for j in range(m)] for i in range(k)]
    return _mh451_solve(xtx, xty)


def _mh451_chol(s00, s01, s11):
    """Cholesky 2x2 (lower) di [[s00, s01], [s01, s11]]:
    ritorna (l00, l10, l11). Non pos-def -> ValueError."""
    import math
    if s00 <= 0.0:
        raise ValueError("cholesky: varianza gas nulla o negativa")
    l00 = math.sqrt(s00)
    l10 = s01 / l00
    d = s11 - l10 * l10
    if d <= 1e-12 * max(1.0, s11):
        raise ValueError("cholesky: covarianza singolare "
                         "(residui power/gas quasi perfettamente "
                         "correlati?)")
    return (l00, l10, math.sqrt(d))


def _mh451_matmul(A, B):
    """Prodotto 2x2."""
    return [[A[0][0] * B[0][0] + A[0][1] * B[1][0],
             A[0][0] * B[0][1] + A[0][1] * B[1][1]],
            [A[1][0] * B[0][0] + A[1][1] * B[1][0],
             A[1][0] * B[0][1] + A[1][1] * B[1][1]]]


def mh451_spillover(power, gas, beta=None, H=20):
    """Tabella di spillover Diebold-Yilmaz dal VECM(1) bivariato
    [gas, power]: per h = 1..H calcola
      S_pg[h] = quota della varianza dell'errore di previsione power
                spiegata dagli shock gas   (gas -> power)
      S_gp[h] = quota della varianza dell'errore di previsione gas
                spiegata dagli shock power (power -> gas)
    con S_pg + S_pp = 1 e S_gp + S_gg = 1 a ogni h (identita' FEVD).
    Indice di spillover totale(h) = (S_pg + S_gp) / 2; netto(h) =
    S_pg - S_gp (positivo: il gas trasmette in netto).

    H intero in [1, 120] (puro modello simulato: puo' superare T,
    come l'IRF di tab449).
    beta = None -> da mh447_eig (Johansen, tab447, p = 1); richiede
    rango 1 con ENTRAMBI i test (traccia e max-autovalore),
    altrimenti ValueError.
    Ritorna dict con n, T (= n - 1), H, beta, lam1, lam2,
    alpha_power, se_power, t_power, alpha_gas, se_gas, t_gas,
    sigma_g, sigma_p, corr_resid, S_pg/S_pp/S_gp/S_gg/tot/net
    (liste H), g2p/p2g/spill/spill_net (valori a H),
    gas_esogeno (|t_alpha_gas| < 2)."""
    import math
    if isinstance(H, bool) or not isinstance(H, int):
        raise ValueError("spillover: H deve essere un intero")
    if H < 1 or H > 120:
        raise ValueError("spillover: H deve stare in [1, 120]")
    ys = _mh451_seq(power, "power")
    gs = _mh451_seq(gas, "gas")
    if len(ys) != len(gs):
        raise ValueError(f"power e gas devono avere la stessa "
                         f"lunghezza ({len(ys)} vs {len(gs)})")
    n = len(ys)
    for seq, nome in ((ys, "power"), (gs, "gas")):
        mu = sum(seq) / n
        if sum((v - mu) ** 2 for v in seq) <= 0.0:
            raise ValueError(f"spillover: serie {nome} costante")
    if beta is None:
        eig = mh447_eig(ys, gs)
        lam1, lam2, Te = eig["lam1"], eig["lam2"], eig["T"]
        r_tr = mh447_rango((lam1, lam2), Te, "trace")
        r_mx = mh447_rango((lam1, lam2), Te, "max")
        if r_tr != 1 or r_mx != 1:
            if r_tr == 0 or r_mx == 0:
                raise ValueError(
                    "spillover: Johansen non trova cointegrazione "
                    f"(rango traccia={r_tr}, max={r_mx}): lo "
                    "spillover non e' identificato")
            raise ValueError(
                "spillover: Johansen trova rango 2 (entrambe "
                "stazionarie): usa un VAR sulle serie, non un VECM")
        beta = eig["beta"]
    else:
        beta = mh451_num(beta, "beta")
        eig = mh447_eig(ys, gs)
        lam1, lam2 = eig["lam1"], eig["lam2"]
    ec_raw = [y - beta * g for y, g in zip(ys, gs)]
    mu_ec = sum(ec_raw) / n
    ec = tuple(v - mu_ec for v in ec_raw)
    if sum(v * v for v in ec) <= 0.0:
        raise ValueError("spillover: termine di correzione costante "
                         "(spread nullo?)")
    T = n - 1
    out = {"n": n, "T": T, "H": H, "beta": beta,
           "lam1": lam1, "lam2": lam2}
    resid = {}
    for nome, y in (("power", ys), ("gas", gs)):
        Z = [[ec[t - 1], 1.0] for t in range(1, n)]
        Y = [[y[t] - y[t - 1]] for t in range(1, n)]
        b = _mh451_ols(Z, Y)
        alpha, const = b[0][0], b[1][0]
        rs = [Y[t][0] - (alpha * Z[t][0] + const * Z[t][1])
              for t in range(T)]
        dof = T - 2
        s2 = sum(r * r for r in rs) / dof
        xtx = [[sum(Z[t][i] * Z[t][j] for t in range(T))
                for j in range(2)] for i in range(2)]
        inv = _mh451_solve(xtx, [[1.0, 0.0], [0.0, 1.0]])
        if s2 <= 0.0 or inv[0][0] <= 0.0:
            raise ValueError(f"spillover: varianza residua nulla "
                             f"su {nome}")
        se = math.sqrt(s2 * inv[0][0])
        out[f"alpha_{nome}"] = alpha
        out[f"se_{nome}"] = se
        out[f"t_{nome}"] = alpha / se
        resid[nome] = rs
    ex, ey = resid["gas"], resid["power"]
    dof = T - 2
    s00 = sum(v * v for v in ex) / dof
    s11 = sum(v * v for v in ey) / dof
    s01 = sum(a * b_ for a, b_ in zip(ex, ey)) / dof
    l00, l10, l11 = _mh451_chol(s00, s01, s11)
    out["sigma_g"] = l00
    out["sigma_p"] = l11
    out["corr_resid"] = s01 / math.sqrt(s00 * s11)
    bta = beta
    a_x, a_y = out["alpha_gas"], out["alpha_power"]
    A = [[1.0 - a_x * bta, a_x],
         [-a_y * bta, 1.0 + a_y]]
    # (Phi_{h-1} L): somme cumulative dei quadrati per riga
    Phi = [[1.0, 0.0], [0.0, 1.0]]
    c_pg = c_pp = c_gp = c_gg = 0.0
    S_pg, S_pp, S_gp, S_gg, tot, net = [], [], [], [], [], []
    for _ in range(H):
        r_pg = Phi[1][0] * l00 + Phi[1][1] * l10
        r_pp = Phi[1][1] * l11
        r_gg = Phi[0][0] * l00 + Phi[0][1] * l10
        r_gp = Phi[0][1] * l11
        c_pg += r_pg * r_pg
        c_pp += r_pp * r_pp
        c_gg += r_gg * r_gg
        c_gp += r_gp * r_gp
        tp = c_pg + c_pp
        tg = c_gg + c_gp
        if tp <= 0.0 or tg <= 0.0:
            raise ValueError("spillover: varianza di forecast nulla")
        v_pg = c_pg / tp
        v_pp = c_pp / tp
        v_gp = c_gp / tg
        v_gg = c_gg / tg
        S_pg.append(v_pg)
        S_pp.append(v_pp)
        S_gp.append(v_gp)
        S_gg.append(v_gg)
        tot.append((v_pg + v_gp) / 2.0)
        net.append(v_pg - v_gp)
        Phi = _mh451_matmul(A, Phi)
    out["S_pg"] = S_pg
    out["S_pp"] = S_pp
    out["S_gp"] = S_gp
    out["S_gg"] = S_gg
    out["tot"] = tot
    out["net"] = net
    out["g2p"] = S_pg[-1]
    out["p2g"] = S_gp[-1]
    out["spill"] = tot[-1]
    out["spill_net"] = net[-1]
    out["gas_esogeno"] = abs(out["t_gas"]) < 2.0
    return out


def mh451_verdetto(spill):
    """Verdetto a 5 stati sull'indice di spillover totale
    Diebold-Yilmaz (quota media della varianza di forecast spiegata
    dagli shock incrociati):
    MERCATI FUSI (indice >= 0.60), FORTEMENTE CONNESSI (0.40-0.60),
    CONNESSI (0.25-0.40), DEBOLMENTE CONNESSI (0.10-0.25),
    SCOLLEGATI (< 0.10).
    spill NaN/inf/negativo -> ValueError."""
    import math
    if isinstance(spill, bool):
        raise ValueError("verdetto: spill deve essere un numero")
    try:
        s = float(spill)
    except (TypeError, ValueError):
        raise ValueError("verdetto: spill deve essere un numero")
    if math.isnan(s) or math.isinf(s) or s < 0.0:
        raise ValueError("verdetto: spill deve essere >= 0 e finito")
    if s >= 0.60:
        return (f"MERCATI FUSI — l'indice di spillover e' "
                f"{s * 100.0:.1f}%: power e gas si muovono insieme, "
                f"gli shock si trasmettono quasi integralmente da un "
                f"mercato all'altro.")
    if s >= 0.40:
        return (f"FORTEMENTE CONNESSI — l'indice di spillover e' "
                f"{s * 100.0:.1f}%: buona parte dell'incertezza di "
                f"previsione di ciascun mercato viene dall'altro; il "
                f"rischio gas e il rischio power vanno coperti insieme.")
    if s >= 0.25:
        return (f"CONNESSI — l'indice di spillover e' "
                f"{s * 100.0:.1f}%: c'e' trasmissione di shock tra i "
                f"mercati, ma ciascuno conserva una sua dinamica.")
    if s >= 0.10:
        return (f"DEBOLMENTE CONNESSI — l'indice di spillover e' solo "
                f"{s * 100.0:.1f}%: gli shock restano perlopiu' dentro "
                f"il proprio mercato.")
    return (f"SCOLLEGATI — l'indice di spillover e' appena "
            f"{s * 100.0:.1f}%: power e gas si muovono per fatti "
            f"propri, niente trasmissione di shock.")


def mh451_mappa(power, gas, beta=None, H=20):
    """Mappa completa: tabella di spillover + verdetto + flag di
    debole esogeneita' del gas (|t_alpha_gas| < 2 -> il gas non
    corregge)."""
    s = mh451_spillover(power, gas, beta, H)
    s["verdetto"] = mh451_verdetto(s["spill"])
    return s

def mh450_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh450_parse_serie(txt):
    """Una riga = un livello di prezzo; la virgola vale come decimale."""
    if not isinstance(txt, str):
        raise ValueError("serie: serve testo, un valore per riga")
    xs = []
    for i, ln in enumerate(txt.split("\n"), 1):
        s = ln.strip().replace(",", ".")
        if not s:
            continue
        try:
            v = float(s)
        except ValueError:
            raise ValueError(f"serie: riga {i} non numerica: {ln!r}")
        import math
        if math.isnan(v) or math.isinf(v):
            raise ValueError(f"serie: riga {i} non finita")
        xs.append(v)
    if len(xs) < 30:
        raise ValueError(f"serie: servono almeno 30 valori "
                         f"(trovati {len(xs)})")
    return tuple(xs)


def _mh450_seq(xs, nome):
    """Valida una sequenza di livelli: tupla di float, >= 30."""
    if xs is None:
        raise ValueError(f"{nome}: serve una sequenza di livelli")
    vs = tuple(mh450_num(x, nome) for x in xs)
    if len(vs) < 30:
        raise ValueError(f"{nome}: servono almeno 30 valori "
                         f"(trovati {len(vs)})")
    return vs


def _mh450_solve(A, B):
    """Risolve A X = B (A nxn, B nxm) con Gauss-Jordan + pivoting
    parziale. A singolare (pivot < 1e-12) -> ValueError."""
    n = len(A)
    if n == 0:
        raise ValueError("solve: matrice vuota")
    m = len(B[0])
    if any(len(row) != n for row in A) or len(B) != n:
        raise ValueError("solve: dimensioni incoerenti")
    aug = [list(map(float, A[i])) + list(map(float, B[i]))
           for i in range(n)]
    for col in range(n):
        piv = max(range(col, n), key=lambda r: abs(aug[r][col]))
        if abs(aug[piv][col]) < 1e-12:
            raise ValueError("solve: matrice singolare")
        aug[col], aug[piv] = aug[piv], aug[col]
        pv = aug[col][col]
        aug[col] = [v / pv for v in aug[col]]
        for r in range(n):
            if r != col and aug[r][col] != 0.0:
                f = aug[r][col]
                aug[r] = [v - f * w for v, w in zip(aug[r], aug[col])]
    return [row[n:] for row in aug]


def _mh450_ols(Z, Y):
    """OLS via equazioni normali: beta = (Z'Z)^-1 Z'Y.
    Z: T righe x k regressori, Y: T righe x m risposte."""
    T = len(Z)
    k = len(Z[0])
    m = len(Y[0])
    xtx = [[sum(Z[t][i] * Z[t][j] for t in range(T))
            for j in range(k)] for i in range(k)]
    xty = [[sum(Z[t][i] * Y[t][j] for t in range(T))
            for j in range(m)] for i in range(k)]
    return _mh450_solve(xtx, xty)


def _mh450_chol(s00, s01, s11):
    """Cholesky 2x2 (lower) di [[s00, s01], [s01, s11]]:
    ritorna (l00, l10, l11). Non pos-def -> ValueError."""
    import math
    if s00 <= 0.0:
        raise ValueError("cholesky: varianza gas nulla o negativa")
    l00 = math.sqrt(s00)
    l10 = s01 / l00
    d = s11 - l10 * l10
    if d <= 1e-12 * max(1.0, s11):
        raise ValueError("cholesky: covarianza singolare "
                         "(residui power/gas quasi perfettamente "
                         "correlati?)")
    return (l00, l10, math.sqrt(d))


def _mh450_matmul(A, B):
    """Prodotto 2x2."""
    return [[A[0][0] * B[0][0] + A[0][1] * B[1][0],
             A[0][0] * B[0][1] + A[0][1] * B[1][1]],
            [A[1][0] * B[0][0] + A[1][1] * B[1][0],
             A[1][0] * B[0][1] + A[1][1] * B[1][1]]]


def mh450_hd(power, gas, beta=None):
    """Scomposizione storica della power: per t = 0..T decompone
    power_t in contributo degli shock gas (g_t) + contributo degli
    shock propri (o_t) + base (b_t = condizioni iniziali + drift
    deterministico).

    beta = None -> da mh447_eig (Johansen, tab447, p = 1); richiede
    rango 1 con ENTRAMBI i test (traccia e max-autovalore),
    altrimenti ValueError.
    Shock strutturali u_t = L^{-1} e_t (sostituzione in avanti,
    Cholesky con gas primo); g_t e o_t sono le convoluzioni delle
    colonne di (Phi_j L) con gli shock realizzati.
    Ritorna dict con n, T (= n - 1), beta, lam1, lam2, alpha_power,
    se_power, t_power, alpha_gas, se_gas, t_gas, sigma_g, sigma_p,
    corr_resid, g/o/base (liste n, g[0] = o[0] = 0,
    base[0] = power[0]), dg/do/db/dpower (liste T: variazioni per
    periodo), share_gas/share_own (= var(dg|do)/var(dpower)),
    g_T/o_T/drift (contributi netti sul campione), tmax (periodo
    1-based di max |dg|), dg_max, gas_esogeno (|t_alpha_gas| < 2)."""
    import math
    ys = _mh450_seq(power, "power")
    gs = _mh450_seq(gas, "gas")
    if len(ys) != len(gs):
        raise ValueError(f"power e gas devono avere la stessa "
                         f"lunghezza ({len(ys)} vs {len(gs)})")
    n = len(ys)
    for seq, nome in ((ys, "power"), (gs, "gas")):
        mu = sum(seq) / n
        if sum((v - mu) ** 2 for v in seq) <= 0.0:
            raise ValueError(f"hd: serie {nome} costante")
    if beta is None:
        eig = mh447_eig(ys, gs)
        lam1, lam2, Te = eig["lam1"], eig["lam2"], eig["T"]
        r_tr = mh447_rango((lam1, lam2), Te, "trace")
        r_mx = mh447_rango((lam1, lam2), Te, "max")
        if r_tr != 1 or r_mx != 1:
            if r_tr == 0 or r_mx == 0:
                raise ValueError(
                    "hd: Johansen non trova cointegrazione "
                    f"(rango traccia={r_tr}, max={r_mx}): la "
                    "scomposizione storica non e' identificata")
            raise ValueError(
                "hd: Johansen trova rango 2 (entrambe stazionarie): "
                "usa un VAR sulle serie, non un VECM")
        beta = eig["beta"]
    else:
        beta = mh450_num(beta, "beta")
        eig = mh447_eig(ys, gs)
        lam1, lam2 = eig["lam1"], eig["lam2"]
    ec_raw = [y - beta * g for y, g in zip(ys, gs)]
    mu_ec = sum(ec_raw) / n
    ec = tuple(v - mu_ec for v in ec_raw)
    if sum(v * v for v in ec) <= 0.0:
        raise ValueError("hd: termine di correzione costante "
                         "(spread nullo?)")
    T = n - 1
    out = {"n": n, "T": T, "beta": beta, "lam1": lam1, "lam2": lam2}
    resid = {}
    for nome, y in (("power", ys), ("gas", gs)):
        Z = [[ec[t - 1], 1.0] for t in range(1, n)]
        Y = [[y[t] - y[t - 1]] for t in range(1, n)]
        b = _mh450_ols(Z, Y)
        alpha, const = b[0][0], b[1][0]
        rs = [Y[t][0] - (alpha * Z[t][0] + const * Z[t][1])
              for t in range(T)]
        dof = T - 2
        s2 = sum(r * r for r in rs) / dof
        xtx = [[sum(Z[t][i] * Z[t][j] for t in range(T))
                for j in range(2)] for i in range(2)]
        inv = _mh450_solve(xtx, [[1.0, 0.0], [0.0, 1.0]])
        if s2 <= 0.0 or inv[0][0] <= 0.0:
            raise ValueError(f"hd: varianza residua nulla su {nome}")
        se = math.sqrt(s2 * inv[0][0])
        out[f"alpha_{nome}"] = alpha
        out[f"se_{nome}"] = se
        out[f"t_{nome}"] = alpha / se
        resid[nome] = rs
    ex, ey = resid["gas"], resid["power"]
    dof = T - 2
    s00 = sum(v * v for v in ex) / dof
    s11 = sum(v * v for v in ey) / dof
    s01 = sum(a * b_ for a, b_ in zip(ex, ey)) / dof
    l00, l10, l11 = _mh450_chol(s00, s01, s11)
    out["sigma_g"] = l00
    out["sigma_p"] = l11
    out["corr_resid"] = s01 / math.sqrt(s00 * s11)
    bta = beta
    a_x, a_y = out["alpha_gas"], out["alpha_power"]
    A = [[1.0 - a_x * bta, a_x],
         [-a_y * bta, 1.0 + a_y]]
    # shock strutturali: u = L^{-1} e (sostituzione in avanti)
    ug = [v / l00 for v in ex]
    up = [(v - l10 * w) / l11 for v, w in zip(ey, ug)]
    # (Phi_j L) per j = 0..T-1
    Phi = [[1.0, 0.0], [0.0, 1.0]]
    pl10, pl11 = [], []
    for _ in range(T):
        pl10.append(Phi[1][0] * l00 + Phi[1][1] * l10)
        pl11.append(Phi[1][1] * l11)
        Phi = _mh450_matmul(A, Phi)
    # convoluzione con gli shock realizzati
    g = [0.0] * n
    o = [0.0] * n
    for t in range(1, n):
        sg = 0.0
        so = 0.0
        for j in range(t):
            sg += pl10[j] * ug[t - 1 - j]
            so += pl11[j] * up[t - 1 - j]
        g[t] = sg
        o[t] = so
    base = [y - gv - ov for y, gv, ov in zip(ys, g, o)]
    dg = [g[t + 1] - g[t] for t in range(T)]
    do = [o[t + 1] - o[t] for t in range(T)]
    db = [base[t + 1] - base[t] for t in range(T)]
    dpower = [ys[t + 1] - ys[t] for t in range(T)]

    def _var(xs):
        mu = sum(xs) / len(xs)
        return sum((v - mu) ** 2 for v in xs) / len(xs)

    v_dp = _var(dpower)
    if v_dp <= 0.0:
        raise ValueError("hd: variazioni power nulle "
                         "(serie power lineare?)")
    out["g"] = g
    out["o"] = o
    out["base"] = base
    out["dg"] = dg
    out["do"] = do
    out["db"] = db
    out["dpower"] = dpower
    out["share_gas"] = _var(dg) / v_dp
    out["share_own"] = _var(do) / v_dp
    out["g_T"] = g[T]
    out["o_T"] = o[T]
    out["drift"] = base[T] - base[0]
    tmax = max(range(T), key=lambda t: abs(dg[t])) + 1
    out["tmax"] = tmax
    out["dg_max"] = dg[tmax - 1]
    out["gas_esogeno"] = abs(out["t_gas"]) < 2.0
    return out


def mh450_verdetto(share):
    """Verdetto a 5 stati sulla quota di varianza delle variazioni
    power spiegata dai contributi degli shock gas:
    IL GAS HA DETTATO LA STORIA (share >= 0.50), STORIA A TRAZIONE
    GAS (0.25-0.50), GAS PARZIALE (0.10-0.25), STORIA QUASI DOMESTICA
    (0.02-0.10), STORIA DOMESTICA (< 0.02).
    share NaN/inf/negativa -> ValueError; share > 1 ammessa (i
    contributi possono essere anticorrelati: resta nel verdetto piu'
    alto)."""
    import math
    if isinstance(share, bool):
        raise ValueError("verdetto: share deve essere un numero")
    try:
        s = float(share)
    except (TypeError, ValueError):
        raise ValueError("verdetto: share deve essere un numero")
    if math.isnan(s) or math.isinf(s) or s < 0.0:
        raise ValueError("verdetto: share deve essere >= 0 e finita")
    if s >= 0.50:
        return (f"IL GAS HA DETTATO LA STORIA — il {s * 100.0:.1f}% "
                f"della varianza delle variazioni osservate della "
                f"power viene dai contributi degli shock gas: in "
                f"questo campione il prezzo power ha seguito il TTF, "
                f"coprirsi sul gas copriva (quasi) tutto.")
    if s >= 0.25:
        return (f"STORIA A TRAZIONE GAS — il {s * 100.0:.1f}% della "
                f"varianza delle variazioni power viene dagli shock "
                f"gas: il TTF ha guidato buona parte dei movimenti, "
                f"ma i fattori propri della power contano.")
    if s >= 0.10:
        return (f"GAS PARZIALE — solo il {s * 100.0:.1f}% della "
                f"varianza delle variazioni power viene dagli shock "
                f"gas: il gas ha mosso il prezzo solo in parte.")
    if s >= 0.02:
        return (f"STORIA QUASI DOMESTICA — appena il {s * 100.0:.1f}% "
                f"della varianza delle variazioni power viene dagli "
                f"shock gas: la power si e' mossa per fatti suoi.")
    return (f"STORIA DOMESTICA — lo {s * 100.0:.1f}% della varianza "
            f"delle variazioni power viene dagli shock gas: il gas "
            f"non ha mosso il power in questo campione.")


def mh450_mappa(power, gas, beta=None):
    """Mappa completa: scomposizione storica + verdetto + flag di
    debole esogeneita' del gas (|t_alpha_gas| < 2 -> il gas non
    corregge)."""
    h = mh450_hd(power, gas, beta)
    h["verdetto"] = mh450_verdetto(h["share_gas"])
    return h

def mh449_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh449_parse_serie(txt):
    """Una riga = un livello di prezzo; la virgola vale come decimale."""
    if not isinstance(txt, str):
        raise ValueError("serie: serve testo, un valore per riga")
    xs = []
    for i, ln in enumerate(txt.split("\n"), 1):
        s = ln.strip().replace(",", ".")
        if not s:
            continue
        try:
            v = float(s)
        except ValueError:
            raise ValueError(f"serie: riga {i} non numerica: {ln!r}")
        import math
        if math.isnan(v) or math.isinf(v):
            raise ValueError(f"serie: riga {i} non finita")
        xs.append(v)
    if len(xs) < 30:
        raise ValueError(f"serie: servono almeno 30 valori "
                         f"(trovati {len(xs)})")
    return tuple(xs)


def _mh449_seq(xs, nome):
    """Valida una sequenza di livelli: tupla di float, >= 30."""
    if xs is None:
        raise ValueError(f"{nome}: serve una sequenza di livelli")
    vs = tuple(mh449_num(x, nome) for x in xs)
    if len(vs) < 30:
        raise ValueError(f"{nome}: servono almeno 30 valori "
                         f"(trovati {len(vs)})")
    return vs


def _mh449_solve(A, B):
    """Risolve A X = B (A nxn, B nxm) con Gauss-Jordan + pivoting
    parziale. A singolare (pivot < 1e-12) -> ValueError."""
    n = len(A)
    if n == 0:
        raise ValueError("solve: matrice vuota")
    m = len(B[0])
    if any(len(row) != n for row in A) or len(B) != n:
        raise ValueError("solve: dimensioni incoerenti")
    aug = [list(map(float, A[i])) + list(map(float, B[i]))
           for i in range(n)]
    for col in range(n):
        piv = max(range(col, n), key=lambda r: abs(aug[r][col]))
        if abs(aug[piv][col]) < 1e-12:
            raise ValueError("solve: matrice singolare")
        aug[col], aug[piv] = aug[piv], aug[col]
        pv = aug[col][col]
        aug[col] = [v / pv for v in aug[col]]
        for r in range(n):
            if r != col and aug[r][col] != 0.0:
                f = aug[r][col]
                aug[r] = [v - f * w for v, w in zip(aug[r], aug[col])]
    return [row[n:] for row in aug]


def _mh449_ols(Z, Y):
    """OLS via equazioni normali: beta = (Z'Z)^-1 Z'Y.
    Z: T righe x k regressori, Y: T righe x m risposte."""
    T = len(Z)
    k = len(Z[0])
    m = len(Y[0])
    xtx = [[sum(Z[t][i] * Z[t][j] for t in range(T))
            for j in range(k)] for i in range(k)]
    xty = [[sum(Z[t][i] * Y[t][j] for t in range(T))
            for j in range(m)] for i in range(k)]
    return _mh449_solve(xtx, xty)


def _mh449_chol(s00, s01, s11):
    """Cholesky 2x2 (lower) di [[s00, s01], [s01, s11]]:
    ritorna (l00, l10, l11). Non pos-def -> ValueError."""
    import math
    if s00 <= 0.0:
        raise ValueError("cholesky: varianza gas nulla o negativa")
    l00 = math.sqrt(s00)
    l10 = s01 / l00
    d = s11 - l10 * l10
    if d <= 1e-12 * max(1.0, s11):
        raise ValueError("cholesky: covarianza singolare "
                         "(residui power/gas quasi perfettamente "
                         "correlati?)")
    return (l00, l10, math.sqrt(d))


def _mh449_matmul(A, B):
    """Prodotto 2x2."""
    return [[A[0][0] * B[0][0] + A[0][1] * B[1][0],
             A[0][0] * B[0][1] + A[0][1] * B[1][1]],
            [A[1][0] * B[0][0] + A[1][1] * B[1][0],
             A[1][0] * B[0][1] + A[1][1] * B[1][1]]]


def mh449_vecm(power, gas, beta=None):
    """VECM(1) bivariato [gas, power] e sua forma VAR(1) in livelli.

    beta = None -> da mh447_eig (Johansen, tab447, p = 1); richiede
    rango 1 con ENTRAMBI i test (traccia e max-autovalore),
    altrimenti ValueError: senza cointegrazione l'IRF di lungo
    periodo non e' identificata.
    Ritorna dict con n, T (= n - 1), beta, lam1, lam2, alpha_power,
    se_power, t_power, alpha_gas, se_gas, t_gas, sigma_g, sigma_p,
    corr_resid, Sigma, L = (l00, l10, l11) di Cholesky, A (VAR 2x2
    in livelli, ordinamento [gas, power]), ec."""
    import math
    ys = _mh449_seq(power, "power")
    gs = _mh449_seq(gas, "gas")
    if len(ys) != len(gs):
        raise ValueError(f"power e gas devono avere la stessa "
                         f"lunghezza ({len(ys)} vs {len(gs)})")
    n = len(ys)
    for seq, nome in ((ys, "power"), (gs, "gas")):
        mu = sum(seq) / n
        if sum((v - mu) ** 2 for v in seq) <= 0.0:
            raise ValueError(f"vecm: serie {nome} costante")
    if beta is None:
        eig = mh447_eig(ys, gs)
        lam1, lam2, Te = eig["lam1"], eig["lam2"], eig["T"]
        r_tr = mh447_rango((lam1, lam2), Te, "trace")
        r_mx = mh447_rango((lam1, lam2), Te, "max")
        if r_tr != 1 or r_mx != 1:
            if r_tr == 0 or r_mx == 0:
                raise ValueError(
                    "vecm: Johansen non trova cointegrazione "
                    f"(rango traccia={r_tr}, max={r_mx}): l'IRF di "
                    "lungo periodo non e' identificata")
            raise ValueError(
                "vecm: Johansen trova rango 2 (entrambe stazionarie): "
                "usa un VAR sulle serie, non un VECM")
        beta = eig["beta"]
    else:
        beta = mh449_num(beta, "beta")
        eig = mh447_eig(ys, gs)
        lam1, lam2 = eig["lam1"], eig["lam2"]
    ec_raw = [y - beta * g for y, g in zip(ys, gs)]
    mu_ec = sum(ec_raw) / n
    ec = tuple(v - mu_ec for v in ec_raw)
    if sum(v * v for v in ec) <= 0.0:
        raise ValueError("vecm: termine di correzione costante "
                         "(spread nullo?)")
    T = n - 1
    out = {"n": n, "T": T, "beta": beta, "lam1": lam1, "lam2": lam2,
           "ec": ec}
    residui = {}
    for nome, y in (("power", ys), ("gas", gs)):
        Z = [[ec[t - 1], 1.0] for t in range(1, n)]
        Y = [[y[t] - y[t - 1]] for t in range(1, n)]
        b = _mh449_ols(Z, Y)
        alpha, const = b[0][0], b[1][0]
        resid = [Y[t][0] - (alpha * Z[t][0] + const * Z[t][1])
                 for t in range(T)]
        dof = T - 2
        s2 = sum(r * r for r in resid) / dof
        xtx = [[sum(Z[t][i] * Z[t][j] for t in range(T))
                for j in range(2)] for i in range(2)]
        inv = _mh449_solve(xtx, [[1.0, 0.0], [0.0, 1.0]])
        if s2 <= 0.0 or inv[0][0] <= 0.0:
            raise ValueError(f"vecm: varianza residua nulla su {nome}")
        se = math.sqrt(s2 * inv[0][0])
        out[f"alpha_{nome}"] = alpha
        out[f"se_{nome}"] = se
        out[f"t_{nome}"] = alpha / se
        residui[nome] = resid
    rx, ry = residui["gas"], residui["power"]
    dof = T - 2
    s00 = sum(v * v for v in rx) / dof
    s11 = sum(v * v for v in ry) / dof
    s01 = sum(a * b_ for a, b_ in zip(rx, ry)) / dof
    out["Sigma"] = [[s00, s01], [s01, s11]]
    l00, l10, l11 = _mh449_chol(s00, s01, s11)
    out["L"] = (l00, l10, l11)
    out["sigma_g"] = l00
    out["sigma_p"] = l11
    out["corr_resid"] = s01 / math.sqrt(s00 * s11)
    b = beta
    a_x, a_y = out["alpha_gas"], out["alpha_power"]
    out["A"] = [[1.0 - a_x * b, a_x],
                [-a_y * b, 1.0 + a_y]]
    return out


def mh449_irf(power, gas, H=24, beta=None):
    """Funzione di risposta all'impulso della power a uno shock del
    gas di +1 sigma_g (Cholesky, gas primo: driver esogeno).

    H intero in [1, 120]. Ritorna dict con H, beta, sigma_g,
    irf (lista H+1: risposta power a h = 0..H), irf_gas (risposta
    gas), gen (IRF generalizzata Pesaran-Shin della power),
    fevd (lista H: quota FEVD del gas a h = 1..H), lr e lr_gas
    (moltiplicatori di lungo periodo: Phi a 200 periodi), t50
    (primo h con irf >= lr/2; None se lr <= 0)."""
    import math
    if isinstance(H, bool) or not isinstance(H, int):
        raise ValueError("irf: H deve essere un intero")
    if H < 1 or H > 120:
        raise ValueError("irf: H deve stare in [1, 120]")
    v = mh449_vecm(power, gas, beta)
    A = v["A"]
    l00, l10, l11 = v["L"]
    s00 = v["Sigma"][0][0]
    s01 = v["Sigma"][0][1]
    Phi = [[1.0, 0.0], [0.0, 1.0]]
    phis = [Phi]
    irf, irf_gas, own, gen = [], [], [], []
    for _ in range(H + 1):
        irf.append(Phi[1][0] * l00 + Phi[1][1] * l10)
        irf_gas.append(Phi[0][0] * l00 + Phi[0][1] * l10)
        own.append(Phi[1][1] * l11)
        gen.append((Phi[1][0] * s00 + Phi[1][1] * s01)
                   / math.sqrt(s00))
        Phi = _mh449_matmul(A, Phi)
        phis.append(Phi)
    fevd = []
    for h in range(1, H + 1):
        num = sum(irf[k] ** 2 for k in range(h))
        den = num + sum(own[k] ** 2 for k in range(h))
        fevd.append(num / den if den > 0.0 else 0.0)
    Pbig = [[1.0, 0.0], [0.0, 1.0]]
    for _ in range(200):
        Pbig = _mh449_matmul(A, Pbig)
    lr = Pbig[1][0] * l00 + Pbig[1][1] * l10
    lr_gas = Pbig[0][0] * l00 + Pbig[0][1] * l10
    t50 = None
    if lr > 0.0:
        t50 = next((h for h in range(H + 1) if irf[h] >= lr / 2.0),
                   H)
    return {"H": H, "beta": v["beta"], "sigma_g": l00,
            "sigma_p": l11, "corr_resid": v["corr_resid"],
            "alpha_power": v["alpha_power"],
            "alpha_gas": v["alpha_gas"],
            "irf": irf, "irf_gas": irf_gas, "gen": gen,
            "fevd": fevd, "lr": lr, "lr_gas": lr_gas, "t50": t50,
            "n": v["n"], "T": v["T"]}


def mh449_verdetto(share):
    """Verdetto a 5 stati sulla quota FEVD del gas a H:
    IL GAS GUIDA IL POWER (share >= 0.50), TRASMISSIONE FORTE
    (0.25-0.50), TRASMISSIONE MODERATA (0.10-0.25), TRASMISSIONE
    DEBOLE (0.02-0.10), NESSUNA TRASMISSIONE (< 0.02).
    share fuori [0, 1] o NaN/inf -> ValueError."""
    import math
    if isinstance(share, bool):
        raise ValueError("verdetto: share deve essere un numero")
    try:
        s = float(share)
    except (TypeError, ValueError):
        raise ValueError("verdetto: share deve essere un numero")
    if math.isnan(s) or math.isinf(s) or s < 0.0 or s > 1.0:
        raise ValueError("verdetto: share deve stare in [0, 1]")
    if s >= 0.50:
        return (f"IL GAS GUIDA IL POWER — a H periodi il "
                f"{s * 100.0:.1f}% della varianza di forecast della "
                f"power viene dagli shock del gas: il TTF detta il "
                f"prezzo power, coprirsi sul gas copre (quasi) tutto.")
    if s >= 0.25:
        return (f"TRASMISSIONE FORTE — il {s * 100.0:.1f}% della "
                f"varianza di forecast della power a H periodi viene "
                f"dagli shock gas: l'hedge va fatto sul gas.")
    if s >= 0.10:
        return (f"TRASMISSIONE MODERATA — solo il {s * 100.0:.1f}% "
                f"della varianza di forecast della power viene dagli "
                f"shock gas: il gas conta ma non detta il prezzo.")
    if s >= 0.02:
        return (f"TRASMISSIONE DEBOLE — appena il {s * 100.0:.1f}% "
                f"della varianza di forecast della power viene dagli "
                f"shock gas: altri driver dominano.")
    return (f"NESSUNA TRASMISSIONE — lo {s * 100.0:.1f}% della "
            f"varianza di forecast della power viene dagli shock "
            f"gas: il gas non muove il power.")


def mh449_mappa(power, gas, H=24, beta=None):
    """Mappa completa: vecm + irf + verdetto + flag di debole
    esogeneita' del gas (|t_alpha_gas| < 2 -> il gas non corregge)."""
    v = mh449_vecm(power, gas, beta)
    r = mh449_irf(power, gas, H, beta)
    verdict = mh449_verdetto(r["fevd"][-1])
    return {"n": v["n"], "T": v["T"], "H": H, "beta": v["beta"],
            "lam1": v["lam1"], "lam2": v["lam2"],
            "alpha_power": v["alpha_power"],
            "se_power": v["se_power"], "t_power": v["t_power"],
            "alpha_gas": v["alpha_gas"], "se_gas": v["se_gas"],
            "t_gas": v["t_gas"],
            "sigma_g": r["sigma_g"], "sigma_p": r["sigma_p"],
            "corr_resid": r["corr_resid"],
            "irf": r["irf"], "irf_gas": r["irf_gas"], "gen": r["gen"],
            "fevd": r["fevd"], "lr": r["lr"], "lr_gas": r["lr_gas"],
            "t50": r["t50"], "irf0": r["irf"][0],
            "share_H": r["fevd"][-1],
            "gas_esogeno": abs(v["t_gas"]) < 2.0,
            "verdetto": verdict}

def mh448_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh448_parse_serie(txt):
    """Una riga = un livello di prezzo; la virgola vale come decimale."""
    if not isinstance(txt, str):
        raise ValueError("serie: serve testo, un valore per riga")
    xs = []
    for i, ln in enumerate(txt.split("\n"), 1):
        s = ln.strip().replace(",", ".")
        if not s:
            continue
        try:
            v = float(s)
        except ValueError:
            raise ValueError(f"serie: riga {i} non numerica: {ln!r}")
        import math
        if math.isnan(v) or math.isinf(v):
            raise ValueError(f"serie: riga {i} non finita")
        xs.append(v)
    if len(xs) < 30:
        raise ValueError(f"serie: servono almeno 30 valori "
                         f"(trovati {len(xs)})")
    return tuple(xs)


def _mh448_seq(xs, nome):
    """Valida una sequenza di livelli: tupla di float, >= 30."""
    if xs is None:
        raise ValueError(f"{nome}: serve una sequenza di livelli")
    vs = tuple(mh448_num(x, nome) for x in xs)
    if len(vs) < 30:
        raise ValueError(f"{nome}: servono almeno 30 valori "
                         f"(trovati {len(vs)})")
    return vs


def _mh448_solve(A, B):
    """Risolve A X = B (A nxn, B nxm) con Gauss-Jordan + pivoting
    parziale. A singolare (pivot < 1e-12) -> ValueError."""
    n = len(A)
    if n == 0:
        raise ValueError("solve: matrice vuota")
    m = len(B[0])
    if any(len(row) != n for row in A) or len(B) != n:
        raise ValueError("solve: dimensioni incoerenti")
    aug = [list(map(float, A[i])) + list(map(float, B[i]))
           for i in range(n)]
    for col in range(n):
        piv = max(range(col, n), key=lambda r: abs(aug[r][col]))
        if abs(aug[piv][col]) < 1e-12:
            raise ValueError("solve: matrice singolare")
        aug[col], aug[piv] = aug[piv], aug[col]
        pv = aug[col][col]
        aug[col] = [v / pv for v in aug[col]]
        for r in range(n):
            if r != col and aug[r][col] != 0.0:
                f = aug[r][col]
                aug[r] = [v - f * w for v, w in zip(aug[r], aug[col])]
    return [row[n:] for row in aug]


def _mh448_ols(Z, Y):
    """OLS via equazioni normali: beta = (Z'Z)^-1 Z'Y.
    Z: T righe x k regressori, Y: T righe x m risposte."""
    T = len(Z)
    k = len(Z[0])
    m = len(Y[0])
    xtx = [[sum(Z[t][i] * Z[t][j] for t in range(T))
            for j in range(k)] for i in range(k)]
    xty = [[sum(Z[t][i] * Y[t][j] for t in range(T))
            for j in range(m)] for i in range(k)]
    return _mh448_solve(xtx, xty)


def mh448_ecm(power, gas, beta=None):
    """Stima l'ECM bivariato: Dy_t = alpha_y * ec_{t-1} + c + eps_t
    per y in (power, gas), con ec = power - beta * gas demeaned.
    beta = None -> da mh447_eig (Johansen, tab447, p = 1).
    Ritorna dict con n, T (= n - 1), beta, ec, e per ciascuna serie
    alpha, se, t, r2, piu' hl_power (half-life da alpha_power)."""
    import math
    ys = _mh448_seq(power, "power")
    gs = _mh448_seq(gas, "gas")
    if len(ys) != len(gs):
        raise ValueError(f"power e gas devono avere la stessa "
                         f"lunghezza ({len(ys)} vs {len(gs)})")
    n = len(ys)
    for seq, nome in ((ys, "power"), (gs, "gas")):
        mu = sum(seq) / n
        if sum((v - mu) ** 2 for v in seq) <= 0.0:
            raise ValueError(f"ecm: serie {nome} costante")
    if beta is None:
        beta = mh447_eig(ys, gs)["beta"]
    else:
        beta = mh448_num(beta, "beta")
    ec_raw = [y - beta * g for y, g in zip(ys, gs)]
    mu_ec = sum(ec_raw) / n
    ec = tuple(v - mu_ec for v in ec_raw)
    if sum(v * v for v in ec) <= 0.0:
        raise ValueError("ecm: termine di correzione costante "
                         "(spread nullo?)")
    T = n - 1
    out = {"n": n, "T": T, "beta": beta, "ec": ec}
    for nome, y in (("power", ys), ("gas", gs)):
        Z = [[ec[t - 1], 1.0] for t in range(1, n)]
        Y = [[y[t] - y[t - 1]] for t in range(1, n)]
        b = _mh448_ols(Z, Y)
        alpha, const = b[0][0], b[1][0]
        resid = [Y[t][0] - (alpha * Z[t][0] + const * Z[t][1])
                 for t in range(T)]
        dof = T - 2
        s2 = sum(r * r for r in resid) / dof
        xtx = [[sum(Z[t][i] * Z[t][j] for t in range(T))
                for j in range(2)] for i in range(2)]
        inv = _mh448_solve(xtx, [[1.0, 0.0], [0.0, 1.0]])
        if s2 <= 0.0 or inv[0][0] <= 0.0:
            raise ValueError(f"ecm: varianza residua nulla su {nome}")
        se = math.sqrt(s2 * inv[0][0])
        tstat = alpha / se
        ym = sum(Y[t][0] for t in range(T)) / T
        sst = sum((Y[t][0] - ym) ** 2 for t in range(T))
        r2 = 1.0 - sum(r * r for r in resid) / sst if sst > 0 else 0.0
        out[f"alpha_{nome}"] = alpha
        out[f"se_{nome}"] = se
        out[f"t_{nome}"] = tstat
        out[f"r2_{nome}"] = r2
    out["hl_power"] = mh448_half_life(out["alpha_power"])
    return out


def mh448_half_life(alpha):
    """Half-life dello squilibrio: -ln(2)/ln(1 + alpha) per
    -2 < alpha < 0 (alpha = -1 -> 1.0: rientro totale in un
    periodo); None se alpha >= 0 o alpha <= -2 (nessun rientro
    convergente). alpha non numero o NaN/inf -> ValueError."""
    import math
    alpha = mh448_num(alpha, "alpha")
    if alpha == -1.0:
        return 1.0
    if -2.0 < alpha < 0.0:
        return -math.log(2.0) / math.log(1.0 + alpha)
    return None


def mh448_verdetto(alpha_power, hl):
    """Verdetto a 5 stati da (alpha_power, hl): DIVERGENZA
    (alpha >= 0), DIVERGENZA OSCILLANTE (alpha <= -2), CONVERGENZA
    RAPIDA (hl <= 2), CONVERGENZA MODERATA (2 < hl <= 6),
    CONVERGENZA LENTA (hl > 6). alpha non numero o NaN/inf ->
    ValueError; hl None con alpha in (-2, 0) -> ValueError; hl NaN
    -> ValueError."""
    import math
    alpha = mh448_num(alpha_power, "alpha_power")
    if hl is not None:
        if isinstance(hl, bool):
            raise ValueError("verdetto: hl deve essere un numero o None")
        hl = float(hl)
        if math.isnan(hl) or math.isinf(hl) or hl <= 0.0:
            raise ValueError("verdetto: hl deve essere positiva e finita")
    if alpha >= 0.0:
        return ("DIVERGENZA — alpha >= 0: nessuno squilibrio viene "
                "riassorbito, la power si allontana dall'equilibrio "
                "col gas (o non lo guarda proprio).")
    if alpha <= -2.0:
        return ("DIVERGENZA OSCILLANTE — alpha <= -2: la correzione "
                "e' eccessiva, lo squilibrio rimbalza di segno in "
                "segno in modo divergente.")
    if hl is None:
        raise ValueError("verdetto: hl mancante con alpha in (-2, 0)")
    if hl <= 2.0:
        return (f"CONVERGENZA RAPIDA — half-life {hl:.2f} periodi: "
                "lo squilibrio si dimezza in al massimo 2 periodi, "
                "la power torna in fretta all'equilibrio col gas.")
    if hl <= 6.0:
        return (f"CONVERGENZA MODERATA — half-life {hl:.2f} periodi: "
                "la power riassorbe lo squilibrio in alcuni periodi.")
    return (f"CONVERGENZA LENTA — half-life {hl:.2f} periodi: il "
            "rientro e' lentissimo, l'equilibrio col gas conta poco "
            "nel breve periodo.")


def mh448_mappa(power, gas, beta=None):
    """Mappa completa: ecm + hl_power + verdetto + flag di debole
    esogeneita' del gas (|t_alpha_gas| < 2 -> il gas non corregge)."""
    e = mh448_ecm(power, gas, beta)
    v = mh448_verdetto(e["alpha_power"], e["hl_power"])
    return {"n": e["n"], "T": e["T"], "beta": e["beta"], "ec": e["ec"],
            "alpha_power": e["alpha_power"], "se_power": e["se_power"],
            "t_power": e["t_power"], "r2_power": e["r2_power"],
            "hl_power": e["hl_power"],
            "alpha_gas": e["alpha_gas"], "se_gas": e["se_gas"],
            "t_gas": e["t_gas"], "r2_gas": e["r2_gas"],
            "gas_esogeno": abs(e["t_gas"]) < 2.0,
            "verdetto": v}

def mh447_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh447_parse_serie(txt):
    """Una riga = un livello di prezzo; la virgola vale come decimale."""
    if not isinstance(txt, str):
        raise ValueError("serie: serve testo, un valore per riga")
    xs = []
    for i, ln in enumerate(txt.split("\n"), 1):
        s = ln.strip().replace(",", ".")
        if not s:
            continue
        try:
            v = float(s)
        except ValueError:
            raise ValueError(f"serie: riga {i} non numerica: {ln!r}")
        import math
        if math.isnan(v) or math.isinf(v):
            raise ValueError(f"serie: riga {i} non finita")
        xs.append(v)
    if len(xs) < 30:
        raise ValueError(f"serie: servono almeno 30 valori "
                         f"(trovati {len(xs)})")
    return tuple(xs)


def _mh447_seq(xs, nome):
    """Valida una sequenza di livelli: tupla di float, >= 30."""
    if xs is None:
        raise ValueError(f"{nome}: serve una sequenza di livelli")
    vs = tuple(mh447_num(x, nome) for x in xs)
    if len(vs) < 30:
        raise ValueError(f"{nome}: servono almeno 30 valori "
                         f"(trovati {len(vs)})")
    return vs


def _mh447_solve(A, B):
    """Risolve A X = B (A nxn, B nxm) con Gauss-Jordan + pivoting
    parziale. A singolare (pivot < 1e-12) -> ValueError."""
    n = len(A)
    if n == 0:
        raise ValueError("solve: matrice vuota")
    m = len(B[0])
    if any(len(row) != n for row in A) or len(B) != n:
        raise ValueError("solve: dimensioni incoerenti")
    aug = [list(map(float, A[i])) + list(map(float, B[i]))
           for i in range(n)]
    for col in range(n):
        piv = max(range(col, n), key=lambda r: abs(aug[r][col]))
        if abs(aug[piv][col]) < 1e-12:
            raise ValueError("solve: matrice singolare")
        aug[col], aug[piv] = aug[piv], aug[col]
        pv = aug[col][col]
        aug[col] = [v / pv for v in aug[col]]
        for r in range(n):
            if r != col and aug[r][col] != 0.0:
                f = aug[r][col]
                aug[r] = [v - f * w for v, w in zip(aug[r], aug[col])]
    return [row[n:] for row in aug]


def _mh447_mul(A, B):
    """Prodotto di matrici (liste di liste)."""
    n, k, m = len(A), len(B), len(B[0])
    if any(len(row) != k for row in A) or any(len(row) != m for row in B):
        raise ValueError("mul: dimensioni incoerenti")
    return [[sum(A[i][t] * B[t][j] for t in range(k))
             for j in range(m)] for i in range(n)]


def _mh447_transp(A):
    """Trasposta."""
    return [[A[i][j] for i in range(len(A))] for j in range(len(A[0]))]


def _mh447_ols(Z, Y):
    """OLS via equazioni normali: beta = (Z'Z)^-1 Z'Y.
    Z: T righe x k regressori, Y: T righe x m risposte."""
    T = len(Z)
    k = len(Z[0])
    m = len(Y[0])
    xtx = [[sum(Z[t][i] * Z[t][j] for t in range(T))
            for j in range(k)] for i in range(k)]
    xty = [[sum(Z[t][i] * Y[t][j] for t in range(T))
            for j in range(m)] for i in range(k)]
    return _mh447_solve(xtx, xty)


def mh447_eig(power, gas, p=1):
    """Autovalori di Johansen per (power, gas): {n, T, p, lam1,
    lam2, S00, S11, S01, M, beta}. VECM con p ritardi delle
    differenze + costante non ristretta. lam1 >= lam2 in [0, 1);
    beta = coefficiente del vettore cointegrante (1, -beta)."""
    import math
    ys = _mh447_seq(power, "power")
    gs = _mh447_seq(gas, "gas")
    if len(ys) != len(gs):
        raise ValueError(f"power e gas devono avere la stessa "
                         f"lunghezza ({len(ys)} vs {len(gs)})")
    n = len(ys)
    if isinstance(p, bool) or not isinstance(p, int):
        raise ValueError("eig: p deve essere un intero")
    if p < 1 or p > 4:
        raise ValueError("eig: p deve stare in [1, 4]")
    T = n - p - 1
    if T < 20:
        raise ValueError(f"eig: osservazioni effettive T = {T} < 20")
    for seq, nome in ((ys, "power"), (gs, "gas")):
        mu = sum(seq) / n
        if sum((v - mu) ** 2 for v in seq) <= 0.0:
            raise ValueError(f"eig: serie {nome} costante")
    D, L, Z = [], [], []
    for t in range(p + 1, n):
        D.append([ys[t] - ys[t - 1], gs[t] - gs[t - 1]])
        L.append([ys[t - 1], gs[t - 1]])
        z = []
        for i in range(1, p + 1):
            z.append(ys[t - i] - ys[t - i - 1])
            z.append(gs[t - i] - gs[t - i - 1])
        z.append(1.0)
        Z.append(z)
    k = len(Z[0])
    b0 = _mh447_ols(Z, D)
    b1 = _mh447_ols(Z, L)
    R0 = [[D[t][j] - sum(Z[t][i] * b0[i][j] for i in range(k))
           for j in range(2)] for t in range(T)]
    R1 = [[L[t][j] - sum(Z[t][i] * b1[i][j] for i in range(k))
           for j in range(2)] for t in range(T)]
    S00 = [[sum(R0[t][i] * R0[t][j] for t in range(T)) / T
            for j in range(2)] for i in range(2)]
    S11 = [[sum(R1[t][i] * R1[t][j] for t in range(T)) / T
            for j in range(2)] for i in range(2)]
    S01 = [[sum(R0[t][i] * R1[t][j] for t in range(T)) / T
            for j in range(2)] for i in range(2)]
    for S, nome in ((S00, "S00"), (S11, "S11")):
        scala = S[0][0] * S[1][1]
        det = S[0][0] * S[1][1] - S[0][1] * S[1][0]
        if scala <= 0.0 or det <= 1e-9 * scala:
            raise ValueError(f"eig: {nome} singolare (serie "
                             "identiche o collinearita' perfetta?)")
    S10 = _mh447_transp(S01)
    M = _mh447_mul(_mh447_solve(S11, S10),
                   _mh447_solve(S00, S01))
    tr = M[0][0] + M[1][1]
    det = M[0][0] * M[1][1] - M[0][1] * M[1][0]
    disc = tr * tr - 4.0 * det
    if disc < 0.0:
        if disc < -1e-9:
            raise ValueError("eig: discriminante negativo "
                             "(autovalori complessi)")
        disc = 0.0
    sq = math.sqrt(disc)
    lam1 = (tr + sq) / 2.0
    lam2 = (tr - sq) / 2.0
    lams = []
    for lam in (lam1, lam2):
        if lam < 0.0:
            if lam < -1e-9:
                raise ValueError("eig: autovalore negativo")
            lam = 0.0
        if lam >= 1.0:
            if lam > 1.0 + 1e-9:
                raise ValueError("eig: autovalore >= 1")
            lam = 1.0 - 1e-12
        lams.append(lam)
    lam1, lam2 = lams
    # vettore cointegrante: autovettore di M per lam1.
    # v = (M01, lam1 - M00) soddisfa (M - lam1 I) v = 0 perche'
    # det(M - lam1 I) = 0; se nullo, usa l'altra riga.
    v = [M[0][1], lam1 - M[0][0]]
    if v[0] * v[0] + v[1] * v[1] <= 1e-24:
        v = [lam1 - M[1][1], M[1][0]]
    if v[0] * v[0] + v[1] * v[1] <= 1e-24:
        raise ValueError("eig: vettore cointegrante degenere")
    if abs(v[0]) <= 1e-12:
        raise ValueError("eig: vettore cointegrante degenere "
                         "(componente power nulla)")
    beta = -v[1] / v[0]
    return {"n": n, "T": T, "p": p, "lam1": lam1, "lam2": lam2,
            "S00": S00, "S11": S11, "S01": S01, "M": M, "beta": beta}


def mh447_critico(r, test):
    """Valore critico Osterwald-Lenum (1992), caso costante non
    ristretta, 2 variabili, livello 5%: traccia r=0 -> 15.41,
    r<=1 -> 3.76; max-autovalore r=0 -> 14.07, r<=1 -> 3.76.
    r in (0, 1), test in ('trace', 'max'), altrimenti ValueError."""
    if isinstance(r, bool) or not isinstance(r, int) or r not in (0, 1):
        raise ValueError("critico: r deve essere 0 o 1")
    if test not in ("trace", "max"):
        raise ValueError("critico: test deve essere 'trace' o 'max'")
    if test == "trace":
        return 15.41 if r == 0 else 3.76
    return 14.07 if r == 0 else 3.76


def _mh447_lam_T(lam, T):
    """Valida lam = (lam1, lam2) con 0 <= lam2 <= lam1 < 1 e
    T intero >= 20."""
    if lam is None:
        raise ValueError("serve la coppia (lam1, lam2)")
    try:
        lams = (float(lam[0]), float(lam[1]))
    except (TypeError, IndexError, ValueError):
        raise ValueError("lam deve essere una coppia (lam1, lam2)")
    import math
    for v in lams:
        if math.isnan(v) or math.isinf(v):
            raise ValueError("lam: NaN/inf non ammessi")
        if v < 0.0 or v >= 1.0:
            raise ValueError("lam: ogni autovalore deve stare "
                             "in [0, 1)")
    if lams[1] > lams[0]:
        raise ValueError("lam: serve lam1 >= lam2")
    if isinstance(T, bool) or not isinstance(T, int):
        raise ValueError("T deve essere un intero")
    if T < 20:
        raise ValueError("T deve essere >= 20")
    return lams


def mh447_trace(lam, T, r):
    """Statistica TRACCIA: -T * sum_{i>r} ln(1 - lam_i), H0:
    rango <= r contro H1: rango = 2. r in (0, 1), altrimenti
    ValueError."""
    import math
    lams = _mh447_lam_T(lam, T)
    if isinstance(r, bool) or not isinstance(r, int) or r not in (0, 1):
        raise ValueError("trace: r deve essere 0 o 1")
    return -T * sum(math.log(1.0 - lams[i]) for i in range(r, 2))


def mh447_max(lam, T, r):
    """Statistica MAX-AUTOVALORE: -T * ln(1 - lam_{r+1}), H0:
    rango <= r contro H1: rango = r + 1. r in (0, 1),
    altrimenti ValueError."""
    import math
    lams = _mh447_lam_T(lam, T)
    if isinstance(r, bool) or not isinstance(r, int) or r not in (0, 1):
        raise ValueError("max: r deve essere 0 o 1")
    return -T * math.log(1.0 - lams[r])


def mh447_rango(lam, T, test):
    """Rango sequenziale con un solo test ('trace' o 'max'):
    0 se la statistica a r=0 non supera il critico, 1 se supera
    a r=0 ma non a r=1, 2 se supera anche a r=1."""
    if test == "trace":
        stat = mh447_trace
    elif test == "max":
        stat = mh447_max
    else:
        raise ValueError("rango: test deve essere 'trace' o 'max'")
    if stat(lam, T, 0) <= mh447_critico(0, test):
        return 0
    if stat(lam, T, 1) <= mh447_critico(1, test):
        return 1
    return 2


def mh447_verdetto(r_trace, r_max, beta):
    """Verdetto a 4 stati da (rango traccia, rango max, beta):
    NESSUNA COINTEGRAZIONE (0, 0), COINTEGRAZIONE (1, 1),
    ENTRAMBE STAZIONARIE (2, 2), DISACCORDO (ranghi diversi).
    Ranghi interi in (0, 1, 2), beta numero finito, altrimenti
    ValueError."""
    import math
    for r, nome in ((r_trace, "r_trace"), (r_max, "r_max")):
        if isinstance(r, bool) or not isinstance(r, int) \
                or r not in (0, 1, 2):
            raise ValueError(f"verdetto: {nome} deve essere 0, 1 o 2")
    if isinstance(beta, bool) or not isinstance(beta, (int, float)):
        raise ValueError("verdetto: beta deve essere un numero")
    beta = float(beta)
    if math.isnan(beta) or math.isinf(beta):
        raise ValueError("verdetto: beta deve essere finito")
    if r_trace == 0 and r_max == 0:
        return ("NESSUNA COINTEGRAZIONE — traccia e max non "
                "rifiutano r = 0: nessuna relazione di lungo "
                "periodo, la beta gas-power e' una regressione "
                "spuria sul lungo periodo.")
    if r_trace == 1 and r_max == 1:
        return (f"COINTEGRAZIONE (rango 1) — una relazione di "
                f"lungo periodo: power ~= {beta:.4f} * gas + "
                "spread stazionario. L'hedge statico col gas "
                "regge nel lungo periodo.")
    if r_trace == 2 and r_max == 2:
        return ("ENTRAMBE STAZIONARIE (rango 2) — rango pieno: le "
                "serie non sono I(1), il test di cointegrazione "
                "non si applica (usare VAR in livelli).")
    return (f"DISACCORDO traccia/max — traccia: rango {r_trace}, "
            f"max: rango {r_max}: guardare le statistiche prima "
            "di decidere (la traccia e' piu' potente, il max "
            "piu' mirato).")


def mh447_mappa(power, gas, p=1):
    """Mappa completa: n, T, p, lam1, lam2, trace0, trace1, max0,
    max1, critici, r_trace, r_max, beta, spread, spread_mean,
    spread_sd, verdetto."""
    import math
    ys = _mh447_seq(power, "power")
    gs = _mh447_seq(gas, "gas")
    e = mh447_eig(ys, gs, p)
    lam = (e["lam1"], e["lam2"])
    trace0 = mh447_trace(lam, e["T"], 0)
    trace1 = mh447_trace(lam, e["T"], 1)
    max0 = mh447_max(lam, e["T"], 0)
    max1 = mh447_max(lam, e["T"], 1)
    r_trace = mh447_rango(lam, e["T"], "trace")
    r_max = mh447_rango(lam, e["T"], "max")
    spread = tuple(y - e["beta"] * g for y, g in zip(ys, gs))
    mu = sum(spread) / len(spread)
    sd = math.sqrt(sum((v - mu) ** 2 for v in spread) / len(spread))
    return {"n": e["n"], "T": e["T"], "p": e["p"],
            "lam1": e["lam1"], "lam2": e["lam2"],
            "trace0": trace0, "trace1": trace1,
            "max0": max0, "max1": max1,
            "crit_trace0": mh447_critico(0, "trace"),
            "crit_trace1": mh447_critico(1, "trace"),
            "crit_max0": mh447_critico(0, "max"),
            "crit_max1": mh447_critico(1, "max"),
            "r_trace": r_trace, "r_max": r_max,
            "beta": e["beta"], "spread": spread,
            "spread_mean": mu, "spread_sd": sd,
            "verdetto": mh447_verdetto(r_trace, r_max, e["beta"])}

def mh446_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh446_parse_serie(txt):
    """Una riga = un rendimento %; la virgola vale come decimale."""
    if not isinstance(txt, str):
        raise ValueError("serie: serve testo, un valore per riga")
    xs = []
    for i, ln in enumerate(txt.split("\n"), 1):
        s = ln.strip().replace(",", ".")
        if not s:
            continue
        try:
            v = float(s)
        except ValueError:
            raise ValueError(f"serie: riga {i} non numerica: {ln!r}")
        import math
        if math.isnan(v) or math.isinf(v):
            raise ValueError(f"serie: riga {i} non finita")
        xs.append(v)
    if len(xs) < 20:
        raise ValueError(f"serie: servono almeno 20 valori "
                         f"(trovati {len(xs)})")
    return tuple(xs)


def _mh446_vs(xs):
    """Valida una sequenza di rendimenti: tupla di float, >= 20."""
    if xs is None:
        raise ValueError("serve una sequenza di rendimenti")
    vs = tuple(mh446_num(x, "rendimento") for x in xs)
    if len(vs) < 20:
        raise ValueError("servono almeno 20 valori")
    return vs


def _mh446_mu_s(vs):
    """Media e S = sum((r - mu)^2); S == 0 -> serie costante."""
    mu = sum(vs) / len(vs)
    s = sum((x - mu) ** 2 for x in vs)
    if s <= 0.0:
        raise ValueError("serie costante: variance ratio non definito "
                         "(varianza nulla)")
    return mu, s


def mh446_mean(xs):
    """Media dei rendimenti %."""
    vs = _mh446_vs(xs)
    return sum(vs) / len(vs)


def mh446_sd(xs):
    """Deviazione standard ML dei rendimenti % (denominatore N)."""
    import math
    vs = _mh446_vs(xs)
    mu, s = _mh446_mu_s(vs)
    return math.sqrt(s / len(vs))


def mh446_autocorr(xs, k):
    """Autocorrelazione campionaria lag k: C_k / S, con
    C_k = sum_{t>k} d_t d_{t-k}, S = sum d_t^2 (denominatore S,
    stessa normalizzazione della forma autocorrelazioni del VR).
    k intero in [1, N-1], altrimenti ValueError; serie costante
    -> ValueError."""
    vs = _mh446_vs(xs)
    mu, s = _mh446_mu_s(vs)
    if isinstance(k, bool) or not isinstance(k, int):
        raise ValueError("autocorr: k deve essere un intero")
    if k < 1 or k >= len(vs):
        raise ValueError("autocorr: k fuori [1, N-1]")
    d = [x - mu for x in vs]
    return sum(d[t] * d[t - k] for t in range(k, len(vs))) / s


def mh446_vr(xs, q):
    """Variance ratio VR(q) = 1 + 2*sum_{k=1}^{q-1} (1-k/q)*rho_k
    (forma autocorrelazioni di Campbell-Lo-MacKinlay). q intero
    in [1, N], altrimenti ValueError; q = 1 -> 1.0 esatto."""
    vs = _mh446_vs(xs)
    _mh446_mu_s(vs)
    if isinstance(q, bool) or not isinstance(q, int):
        raise ValueError("vr: q deve essere un intero")
    if q < 1 or q > len(vs):
        raise ValueError("vr: q fuori [1, N]")
    if q == 1:
        return 1.0
    return 1.0 + 2.0 * sum((1.0 - k / q) * mh446_autocorr(vs, k)
                           for k in range(1, q))


def mh446_phi(q, n):
    """Varianza asintotica omoschedastica di (VR(q)-1):
    phi(q) = 2(2q-1)(q-1) / (3qN). q intero >= 2, n intero >= 20,
    altrimenti ValueError."""
    if isinstance(q, bool) or not isinstance(q, int):
        raise ValueError("phi: q deve essere un intero")
    if q < 2:
        raise ValueError("phi: q >= 2")
    if isinstance(n, bool) or not isinstance(n, int):
        raise ValueError("phi: n deve essere un intero")
    if n < 20:
        raise ValueError("phi: n >= 20")
    return 2.0 * (2 * q - 1) * (q - 1) / (3.0 * q * n)


def mh446_phi_star(xs, q):
    """Varianza asintotica ROBUSTA all'eteroschedasticita' di
    (VR(q)-1): phi*(q) = sum_{k=1}^{q-1} [2(q-k)/q]^2 * delta_k,
    delta_k = sum_{t>k} d_t^2 d_{t-k}^2 / S^2. q intero >= 2,
    altrimenti ValueError."""
    vs = _mh446_vs(xs)
    mu, s = _mh446_mu_s(vs)
    if isinstance(q, bool) or not isinstance(q, int):
        raise ValueError("phi_star: q deve essere un intero")
    if q < 2:
        raise ValueError("phi_star: q >= 2")
    if q > len(vs):
        raise ValueError("phi_star: q oltre la lunghezza della serie")
    d = [x - mu for x in vs]
    tot = 0.0
    for k in range(1, q):
        dk = (sum(d[t] ** 2 * d[t - k] ** 2
                  for t in range(k, len(vs))) / (s * s))
        tot += (2.0 * (q - k) / q) ** 2 * dk
    return tot


def mh446_norm_cdf(x):
    """CDF normale standard Phi(x) via erf."""
    import math
    if isinstance(x, bool) or not isinstance(x, (int, float)):
        raise ValueError("norm_cdf: serve un numero")
    return 0.5 * (1.0 + math.erf(float(x) / math.sqrt(2.0)))


def mh446_norm_ppf(p):
    """Inversa della CDF normale standard (Acklam, ~1e-9).
    p in (0, 1) aperto, altrimenti ValueError."""
    import math
    if isinstance(p, bool) or not isinstance(p, (int, float)):
        raise ValueError("norm_ppf: serve un numero")
    p = float(p)
    if not (0.0 < p < 1.0):
        raise ValueError("norm_ppf: p deve stare in (0, 1)")
    a = [-3.969683028665376e+01, 2.209460984245205e+02,
         -2.759285104469687e+02, 1.383577518672690e+02,
         -3.066479806614716e+01, 2.506628277459239e+00]
    b = [-5.447609879822406e+01, 1.615858368580409e+02,
         -1.556989798598866e+02, 6.680131188771972e+01,
         -1.328068155288572e+01]
    c = [-7.784894002430293e-03, -3.223964580411365e-01,
         -2.400758277161838e+00, -2.549732539343734e+00,
         4.374664141464968e+00, 2.938163982698783e+00]
    dd = [7.784695709041462e-03, 3.224671290700398e-01,
          2.445134137142996e+00, 3.754408661907416e+00]
    plow, phigh = 0.02425, 1.0 - 0.02425
    if p < plow:
        qv = math.sqrt(-2.0 * math.log(p))
        return (((((c[0] * qv + c[1]) * qv + c[2]) * qv + c[3]) * qv
                 + c[4]) * qv + c[5]) / ((((dd[0] * qv + dd[1]) * qv
                 + dd[2]) * qv + dd[3]) * qv + 1.0)
    if p <= phigh:
        qv = p - 0.5
        r = qv * qv
        return (((((a[0] * r + a[1]) * r + a[2]) * r + a[3]) * r
                 + a[4]) * r + a[5]) * qv / (((((b[0] * r + b[1]) * r
                 + b[2]) * r + b[3]) * r + b[4]) * r + 1.0)
    qv = math.sqrt(-2.0 * math.log(1.0 - p))
    return -(((((c[0] * qv + c[1]) * qv + c[2]) * qv + c[3]) * qv
              + c[4]) * qv + c[5]) / ((((dd[0] * qv + dd[1]) * qv
              + dd[2]) * qv + dd[3]) * qv + 1.0)


def mh446_smm_critico(m, alpha=0.05):
    """Critico SMM (Studentized Maximum Modulus) per il test
    congiunto su m statistiche al livello alpha:
    alpha* = 1 - (1-alpha)^(1/m), critico = Phi^{-1}(1 -
    alpha*/2). m intero >= 1, alpha in (0, 1), altrimenti
    ValueError."""
    if isinstance(m, bool) or not isinstance(m, int):
        raise ValueError("smm_critico: m deve essere un intero")
    if m < 1:
        raise ValueError("smm_critico: m >= 1")
    if isinstance(alpha, bool) or not isinstance(alpha, (int, float)):
        raise ValueError("smm_critico: alpha deve essere un numero")
    alpha = float(alpha)
    if not (0.0 < alpha < 1.0):
        raise ValueError("smm_critico: alpha deve stare in (0, 1)")
    astar = 1.0 - (1.0 - alpha) ** (1.0 / m)
    return mh446_norm_ppf(1.0 - astar / 2.0)


def mh446_z(xs, q):
    """Riga del test per un orizzonte q: {q, vr, z, z_star, p,
    p_star}. z = test omoschedastico (iid), z* = test robusto
    all'eteroschedasticita' (quello decisionale). q intero >= 2,
    altrimenti ValueError."""
    import math
    vs = _mh446_vs(xs)
    _mh446_mu_s(vs)
    if isinstance(q, bool) or not isinstance(q, int):
        raise ValueError("z: q deve essere un intero")
    if q < 2:
        raise ValueError("z: q >= 2 (q=1: VR=1 per costruzione)")
    if q > len(vs):
        raise ValueError("z: q oltre la lunghezza della serie")
    vr = mh446_vr(vs, q)
    z = (vr - 1.0) / math.sqrt(mh446_phi(q, len(vs)))
    zstar = (vr - 1.0) / math.sqrt(mh446_phi_star(vs, q))
    return {"q": q, "vr": vr, "z": z, "z_star": zstar,
            "p": 2.0 * (1.0 - mh446_norm_cdf(abs(z))),
            "p_star": 2.0 * (1.0 - mh446_norm_cdf(abs(zstar)))}


def mh446_joint(xs, qs=(2, 4, 8, 16), alpha=0.05):
    """Test CONGIUNTO di Chow-Denning: {rows, zmax, qmax, critico,
    rifiuta, m, alpha}. Z* = max_q |z*(q)|; H0 (random walk) si
    rifiuta se Z* > critico SMM al livello alpha. Griglia qs non
    vuota, valori interi >= 2 e <= N, altrimenti ValueError."""
    vs = _mh446_vs(xs)
    _mh446_mu_s(vs)
    try:
        qraw = list(qs)
    except TypeError:
        raise ValueError("joint: qs deve essere una sequenza")
    if not qraw:
        raise ValueError("joint: griglia qs vuota")
    for v in qraw:
        if isinstance(v, bool) or not isinstance(v, int):
            raise ValueError("joint: qs deve contenere interi")
    qlist = sorted(set(qraw))
    for q in qlist:
        if q < 2 or q > len(vs):
            raise ValueError("joint: q fuori [2, N]")
    rows = [mh446_z(vs, q) for q in qlist]
    zmax = max(abs(r["z_star"]) for r in rows)
    qmax = [r["q"] for r in rows if abs(r["z_star"]) == zmax][0]
    critico = mh446_smm_critico(len(rows), alpha)
    return {"rows": rows, "zmax": zmax, "qmax": qmax,
            "critico": critico, "rifiuta": zmax > critico,
            "m": len(rows), "alpha": alpha}


def mh446_verdetto(vr2, rifiuta):
    """Verdetto a 6 stati dal test congiunto + direzione VR(2):
    RANDOM WALK (non rifiuta), TRENDING / TRENDING FORTE
    (rifiuta, VR(2) > 1), MEAN REVERSION / MEAN REVERSION FORTE
    (rifiuta, VR(2) < 1), MISTO (rifiuta ma VR(2) = 1.0 esatto:
    segnali contrastanti tra orizzonti). vr2 numero finito o
    +-inf (NaN -> ValueError); rifiuta deve essere bool."""
    import math
    if isinstance(vr2, bool) or not isinstance(vr2, (int, float)):
        raise ValueError("verdetto: serve un numero")
    vr2 = float(vr2)
    if math.isnan(vr2):
        raise ValueError("verdetto: NaN non ammesso")
    if not isinstance(rifiuta, bool):
        raise ValueError("verdetto: rifiuta deve essere bool")
    if not rifiuta:
        return ("RANDOM WALK — il test congiunto NON rifiuta H0 "
                f"(VR(2) = {vr2:.4f}): i rendimenti passati non "
                "prevedono i successivi, il prezzo si comporta "
                "come un random walk.")
    if vr2 == 1.0:
        return ("MISTO — il test congiunto rifiuta H0 ma VR(2) = "
                "1.0000 esatto: segnali contrastanti tra orizzonti, "
                "guardare la curva VR(q) prima di decidere.")
    if vr2 > 1.0:
        if vr2 >= 1.5:
            return (f"TRENDING FORTE — H0 rifiutata, VR(2) = "
                    f"{vr2:.4f} >= 1.5: autocorrelazione positiva "
                    "forte, i rendimenti si auto-rinforzano "
                    "(momentum marcato).")
        return (f"TRENDING — H0 rifiutata, VR(2) = {vr2:.4f} in "
                "(1, 1.5): autocorrelazione positiva "
                "debole-moderata (momentum).")
    if vr2 <= 0.6:
        return (f"MEAN REVERSION FORTE — H0 rifiutata, VR(2) = "
                f"{vr2:.4f} <= 0.6: autocorrelazione negativa "
                "forte, rientro rapido verso la media.")
    return (f"MEAN REVERSION — H0 rifiutata, VR(2) = {vr2:.4f} in "
            "(0.6, 1): autocorrelazione negativa debole-moderata "
            "(rientro verso la media).")


def mh446_mappa(xs, qs=(2, 4, 8, 16), alpha=0.05):
    """Mappa completa: n, mean, sd, qs, rows, vr2, zmax, qmax,
    critico, rifiuta, alpha, verdetto."""
    vs = _mh446_vs(xs)
    mu, _s = _mh446_mu_s(vs)
    joint = mh446_joint(vs, qs, alpha)
    vr2 = mh446_vr(vs, 2)
    return {"n": len(vs), "mean": mu, "sd": mh446_sd(vs),
            "qs": tuple(r["q"] for r in joint["rows"]),
            "rows": joint["rows"], "vr2": vr2,
            "zmax": joint["zmax"], "qmax": joint["qmax"],
            "critico": joint["critico"],
            "rifiuta": joint["rifiuta"], "alpha": alpha,
            "verdetto": mh446_verdetto(vr2, joint["rifiuta"])}

def mh445_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh445_parse_serie(txt):
    """Una riga = un rendimento %; la virgola vale come decimale."""
    if not isinstance(txt, str):
        raise ValueError("serie: serve testo, un valore per riga")
    xs = []
    for i, ln in enumerate(txt.split("\n"), 1):
        s = ln.strip().replace(",", ".")
        if not s:
            continue
        try:
            v = float(s)
        except ValueError:
            raise ValueError(f"serie: riga {i} non numerica: {ln!r}")
        import math
        if math.isnan(v) or math.isinf(v):
            raise ValueError(f"serie: riga {i} non finita")
        xs.append(v)
    if len(xs) < 20:
        raise ValueError(f"serie: servono almeno 20 valori "
                         f"(trovati {len(xs)})")
    return tuple(xs)


def mh445_equity(xs):
    """Equity composta dai rendimenti % (parte da 100.0), un valore
    per periodo."""
    if xs is None:
        raise ValueError("serve una sequenza di rendimenti")
    vs = tuple(mh445_num(x, "rendimento") for x in xs)
    if len(vs) < 20:
        raise ValueError("equity: servono almeno 20 valori")
    eq = 100.0
    out = []
    for x in vs:
        eq *= 1.0 + x / 100.0
        out.append(eq)
    return tuple(out)


def mh445_peaks(xs):
    """Running max dell'equity (picco iniziale 100.0), un valore
    per periodo. Stessa convenzione di tab424/tab427/tab428/
    tab429/tab430/tab431/tab432/tab433/tab434/tab435/tab436/
    tab437/tab438/tab439/tab440/tab441/tab442/tab443/tab444."""
    eq = mh445_equity(xs)
    peak = 100.0
    out = []
    for e in eq:
        if e > peak:
            peak = e
        out.append(peak)
    return tuple(out)


def mh445_drawdowns(xs):
    """Drawdown % (magnitudine >= 0) dal running max dell'equity,
    un valore per periodo. Peak iniziale = 100.0."""
    eq = mh445_equity(xs)
    peak = 100.0
    out = []
    for e in eq:
        if e > peak:
            peak = e
        out.append((peak - e) / peak * 100.0)
    return tuple(out)


def mh445_max_dd(xs):
    """Drawdown massimo di percorso (magnitudine % >= 0)."""
    dds = mh445_drawdowns(xs)
    return max(dds) if dds else 0.0


def mh445_window_dds(xs, start, w):
    """Drawdown % INTERNI a una finestra di w rendimenti che parte
    al periodo start (1-based): l'equity di finestra riparte da
    100.0 e il picco si resetta all'inizio della finestra.
    Restituisce una tupla di w drawdown % (uno per periodo di
    finestra). W >= 2, 1 <= start <= N-W+1, altrimenti
    ValueError."""
    if xs is None:
        raise ValueError("serve una sequenza di rendimenti")
    vs = tuple(mh445_num(x, "rendimento") for x in xs)
    if len(vs) < 20:
        raise ValueError("window_dds: servono almeno 20 valori")
    if isinstance(w, bool) or not isinstance(w, int):
        raise ValueError("window_dds: W deve essere un intero")
    if w < 2:
        raise ValueError("window_dds: W >= 2")
    if w > len(vs):
        raise ValueError("window_dds: W oltre la lunghezza della serie")
    if isinstance(start, bool) or not isinstance(start, int):
        raise ValueError("window_dds: start deve essere un intero")
    if start < 1 or start > len(vs) - w + 1:
        raise ValueError("window_dds: start fuori [1, N-W+1]")
    eq = 100.0
    peak = 100.0
    out = []
    for x in vs[start - 1:start - 1 + w]:
        eq *= 1.0 + x / 100.0
        if eq > peak:
            peak = eq
        out.append((peak - eq) / peak * 100.0)
    return tuple(out)


def mh445_window_max_dd(xs, start, w):
    """Max drawdown % dentro una finestra (picco resettato)."""
    return max(mh445_window_dds(xs, start, w))


def mh445_rolling(xs, w):
    """Rolling dei maxDD di finestra: una dict per finestra
    {start, end, max_dd}, start = 1..N-W+1, end = start+W-1.
    W >= 2 e W <= N, altrimenti ValueError."""
    if xs is None:
        raise ValueError("serve una sequenza di rendimenti")
    vs = tuple(mh445_num(x, "rendimento") for x in xs)
    if len(vs) < 20:
        raise ValueError("rolling: servono almeno 20 valori")
    if isinstance(w, bool) or not isinstance(w, int):
        raise ValueError("rolling: W deve essere un intero")
    if w < 2:
        raise ValueError("rolling: W >= 2")
    if w > len(vs):
        raise ValueError("rolling: W oltre la lunghezza della serie")
    return [{"start": s, "end": s + w - 1,
             "max_dd": max(mh445_window_dds(vs, s, w))}
            for s in range(1, len(vs) - w + 2)]


def mh445_worst_window(xs, w):
    """Finestra peggiore: {start, end, max_dd, peak_period,
    trough_period}. In caso di parita' vince la finestra con
    start minore. peak_period e' il periodo (globale, 1-based)
    del picco interno che precede il minimo; se la finestra
    cade da subito, peak_period = start - 1 (livello
    d'ingresso). trough_period e' il periodo del minimo."""
    wins = mh445_rolling(xs, w)
    best = max(wins, key=lambda d: d["max_dd"])
    start = best["start"]
    vs = tuple(mh445_num(x, "rendimento") for x in xs)
    sub = vs[start - 1:start - 1 + w]
    pts = [100.0]
    eq = 100.0
    for x in sub:
        eq *= 1.0 + x / 100.0
        pts.append(eq)
    pk = 100.0
    dds = []
    for j in range(w):
        pk = max(pk, pts[j + 1])
        dds.append((pk - pts[j + 1]) / pk * 100.0)
    jstar = dds.index(max(dds))
    peak_val = max(pts[:jstar + 2])
    peak_idx = pts[:jstar + 2].index(peak_val)
    return {"start": start, "end": start + w - 1,
            "max_dd": best["max_dd"],
            "peak_period": start - 1 + peak_idx,
            "trough_period": start + jstar}


def mh445_curva_w(xs, ws=(3, 6, 12, 18, 24)):
    """Curva worst rolling vs W: per ogni W in `ws` una dict
    {w, worst, n_win, mean_win, share_over} (share_over = quota
    % di finestre con maxDD > 20.0%). Proprieta' (testata sulla
    demo): worst e' NON DECRESCENTE in W e satura al maxDD
    totale non appena W supera la durata del peggior calo."""
    if xs is None:
        raise ValueError("serve una sequenza di rendimenti")
    vs = tuple(mh445_num(x, "rendimento") for x in xs)
    if len(vs) < 20:
        raise ValueError("curva_w: servono almeno 20 valori")
    try:
        wlist = tuple(int(v) for v in ws)
    except TypeError:
        raise ValueError("curva_w: ws deve essere una sequenza")
    if not wlist:
        raise ValueError("curva_w: griglia W vuota")
    out = []
    for w in sorted(set(wlist)):
        wins = mh445_rolling(vs, w)
        mdds = [d["max_dd"] for d in wins]
        out.append({"w": w, "worst": max(mdds),
                    "n_win": len(wins),
                    "mean_win": sum(mdds) / len(mdds),
                    "share_over": (sum(1 for v in mdds if v > 20.0)
                                   / len(mdds) * 100.0)})
    return out


def mh445_verdetto(worst):
    """Verdetto a 6 stati sul worst rolling % (minore = migliore):
    < 5 ECCEZIONALE (in nessuna finestra si scende oltre il 5%),
    < 10 OTTIMO, < 20 BUONO, < 30 DISCRETO, < 40 DEBOLE,
    altrimenti NEGATIVO. +inf -> NEGATIVO, -inf -> ECCEZIONALE.
    NaN o non-numero -> ValueError."""
    import math
    if isinstance(worst, bool) or not isinstance(worst, (int, float)):
        raise ValueError("verdetto: serve un numero")
    s = float(worst)
    if math.isnan(s):
        raise ValueError("verdetto: NaN non ammesso")
    if s < 5.0:
        return (f"ECCEZIONALE — worst rolling {s:.4f}%: in nessuna "
                f"finestra si scende oltre il 5%.")
    if s < 10.0:
        return (f"OTTIMO — worst rolling {s:.4f}%: 5-10% di calo "
                f"massimo in finestra.")
    if s < 20.0:
        return (f"BUONO — worst rolling {s:.4f}%: 10-20% di calo "
                f"massimo in finestra.")
    if s < 30.0:
        return (f"DISCRETO — worst rolling {s:.4f}%: 20-30% di "
                f"calo massimo in finestra.")
    if s < 40.0:
        return (f"DEBOLE — worst rolling {s:.4f}%: 30-40% di calo "
                f"massimo in finestra.")
    return (f"NEGATIVO — worst rolling {s:.4f}%: oltre il 40% di "
            f"calo in almeno una finestra.")


def mh445_mappa(xs, w=12):
    """Mappa completa: n, mean, max_dd, pain, total, tuw, w,
    n_win, worst, best, median, mean_win, worst_start,
    worst_end, worst_peak, worst_trough, share_over, verdetto,
    equity, peaks, dds, windows (tuple di dict rolling)."""
    import statistics
    if xs is None:
        raise ValueError("serve una sequenza di rendimenti")
    vs = tuple(mh445_num(x, "rendimento") for x in xs)
    if len(vs) < 20:
        raise ValueError("mappa: servono almeno 20 valori")
    eq = mh445_equity(vs)
    if any(e <= 0.0 for e in eq):
        raise ValueError("mappa: equity azzerata (rendimento <= -100%)")
    pk = mh445_peaks(vs)
    dds = mh445_drawdowns(vs)
    dd = max(dds) if dds else 0.0
    pain = sum(dds) / len(dds) if dds else 0.0
    tuw = sum(1 for d in dds if d > 0.0) / len(dds) * 100.0
    tot = (eq[-1] / 100.0 - 1.0) * 100.0
    wins = mh445_rolling(vs, w)
    mdds = [d["max_dd"] for d in wins]
    worst_w = mh445_worst_window(vs, w)
    worst = max(mdds)
    return {"n": len(vs), "mean": sum(vs) / len(vs),
            "max_dd": dd, "pain": pain,
            "total": tot, "tuw": tuw, "w": w,
            "n_win": len(wins), "worst": worst,
            "best": min(mdds),
            "median": statistics.median(mdds),
            "mean_win": sum(mdds) / len(mdds),
            "worst_start": worst_w["start"],
            "worst_end": worst_w["end"],
            "worst_peak": worst_w["peak_period"],
            "worst_trough": worst_w["trough_period"],
            "share_over": (sum(1 for v in mdds if v > 20.0)
                           / len(mdds) * 100.0),
            "verdetto": mh445_verdetto(worst),
            "equity": eq, "peaks": pk, "dds": dds,
            "windows": tuple(wins)}

def mh444_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh444_parse_serie(txt):
    """Una riga = un rendimento %; la virgola vale come decimale."""
    if not isinstance(txt, str):
        raise ValueError("serie: serve testo, un valore per riga")
    xs = []
    for i, ln in enumerate(txt.split("\n"), 1):
        s = ln.strip().replace(",", ".")
        if not s:
            continue
        try:
            v = float(s)
        except ValueError:
            raise ValueError(f"serie: riga {i} non numerica: {ln!r}")
        import math
