def mh444_drawdowns(xs):
    """Drawdown % (magnitudine >= 0) dal running max dell'equity,
    un valore per periodo. Peak iniziale = 100.0."""
    eq = mh444_equity(xs)
    peak = 100.0
    out = []
    for e in eq:
        if e > peak:
            peak = e
        out.append((peak - e) / peak * 100.0)
    return tuple(out)


def mh444_max_dd(xs):
    """Drawdown massimo di percorso (magnitudine % >= 0)."""
    dds = mh444_drawdowns(xs)
    return max(dds) if dds else 0.0


def mh444_lake(xs):
    """Lake ratio % = somma dei deficit (picco - equity) /
    somma dei picchi * 100. Area del dolore normalizzata sul
    percorso del picco. Range [0, 100): 0 se mai sott'acqua.
    Equity azzerata (rendimento <= -100%) -> ValueError."""
    if xs is None:
        raise ValueError("serve una sequenza di rendimenti")
    vs = tuple(mh444_num(x, "rendimento") for x in xs)
    if len(vs) < 20:
        raise ValueError("lake: servono almeno 20 valori")
    eq = mh444_equity(vs)
    if any(e <= 0.0 for e in eq):
        raise ValueError("lake: equity azzerata (rendimento <= -100%)")
    pk = mh444_peaks(vs)
    deficit = sum(p - e for p, e in zip(pk, eq))
    return deficit / sum(pk) * 100.0


def mh444_curva_orizzonte(xs, extra=(0, 6, 12, 24), fill=3.0):
    """Curva Lake vs orizzonte: alla serie si appendono `extra`
    periodi al rendimento fisso `fill` % (default +3%) e si
    ricalcolano Lake, TUW e maxDD. Lista di dict con extra, n,
    lake, tuw, max_dd. Proprieta' (testata sulla demo): il
    Lake NON e' monotono in extra — cresce finche' l'equity
    resta sott'acqua (ogni nuovo periodo aggiunge deficit) e
    cala solo quando l'equity torna sopra il picco."""
    if xs is None:
        raise ValueError("serve una sequenza di rendimenti")
    vs = tuple(mh444_num(x, "rendimento") for x in xs)
    if len(vs) < 20:
        raise ValueError("curva_orizzonte: servono almeno 20 valori")
    f = mh444_num(fill, "fill")
    try:
        ex = tuple(int(e) for e in extra)
    except TypeError:
        raise ValueError("curva_orizzonte: extra deve essere "
                         "una sequenza")
    if not ex:
        raise ValueError("curva_orizzonte: griglia extra vuota")
    for e in ex:
        if e < 0:
            raise ValueError("curva_orizzonte: extra negativo")
    out = []
    for e in sorted(ex):
        ext = vs + tuple([f] * e)
        dds = mh444_drawdowns(ext)
        out.append({"extra": e, "n": len(ext),
                    "lake": mh444_lake(ext),
                    "tuw": (sum(1 for d in dds if d > 0.0)
                            / len(dds) * 100.0),
                    "max_dd": max(dds) if dds else 0.0})
    return out


def mh444_verdetto(lake):
    """Verdetto a 6 stati sul Lake ratio % (minore = migliore):
    < 1 ECCEZIONALE (lago quasi asciutto), < 3 OTTIMO,
    < 6 BUONO, < 10 DISCRETO, < 15 DEBOLE, altrimenti
    NEGATIVO. +inf -> NEGATIVO, -inf -> ECCEZIONALE.
    NaN o non-numero -> ValueError."""
    import math
    if isinstance(lake, bool) or not isinstance(lake, (int, float)):
        raise ValueError("verdetto: serve un numero")
    s = float(lake)
    if math.isnan(s):
        raise ValueError("verdetto: NaN non ammesso")
    if s < 1.0:
        return (f"ECCEZIONALE — Lake {s:.4f}%: lago quasi asciutto, "
                f"meno dell'1% del percorso sommerso.")
    if s < 3.0:
        return (f"OTTIMO — Lake {s:.4f}%: 1-3% del percorso "
                f"sommerso.")
    if s < 6.0:
        return (f"BUONO — Lake {s:.4f}%: 3-6% del percorso "
                f"sommerso.")
    if s < 10.0:
        return (f"DISCRETO — Lake {s:.4f}%: 6-10% del percorso "
                f"sommerso.")
    if s < 15.0:
        return (f"DEBOLE — Lake {s:.4f}%: 10-15% del percorso "
                f"sommerso.")
    return (f"NEGATIVO — Lake {s:.4f}%: oltre il 15% del percorso "
            f"sommerso.")


def mh444_mappa(xs):
    """Mappa completa: n, mean, max_dd, pain, total (composto),
    lake, tuw, n_dd, sum_dd, sum_peak, verdetto, equity,
    peaks, dds, sotto (bool per periodo: True se drawdown > 0),
    deficit (picco - equity per periodo)."""
    if xs is None:
        raise ValueError("serve una sequenza di rendimenti")
    vs = tuple(mh444_num(x, "rendimento") for x in xs)
    if len(vs) < 20:
        raise ValueError("mappa: servono almeno 20 valori")
    eq = mh444_equity(vs)
    if any(e <= 0.0 for e in eq):
        raise ValueError("mappa: equity azzerata (rendimento <= -100%)")
    pk = mh444_peaks(vs)
    dds = mh444_drawdowns(vs)
    dd = max(dds) if dds else 0.0
    pain = sum(dds) / len(dds) if dds else 0.0
    deficit = tuple(p - e for p, e in zip(pk, eq))
    lake = sum(deficit) / sum(pk) * 100.0
    tuw = sum(1 for d in dds if d > 0.0) / len(dds) * 100.0
    tot = (eq[-1] / 100.0 - 1.0) * 100.0
    return {"n": len(vs), "mean": sum(vs) / len(vs),
            "max_dd": dd, "pain": pain,
            "total": tot, "lake": lake, "tuw": tuw,
            "n_dd": sum(1 for d in dds if d > 0.0),
            "sum_dd": sum(dds), "sum_peak": sum(pk),
            "verdetto": mh444_verdetto(lake),
            "equity": eq, "peaks": pk, "dds": dds,
            "sotto": tuple(d > 0.0 for d in dds),
            "deficit": deficit}

def mh443_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh443_parse_serie(txt):
    """Una riga = un rendimento %; la virgola vale come decimale."""
    if not isinstance(txt, str):
        raise ValueError("serie: serve testo, un valore per riga")
    xs = []
    for i, ln in enumerate(txt.split("\n"), 1):
        s = ln.strip().replace(",", ".")
        if not s:
            continue
        try:
            v = float(s)
        except ValueError:
            raise ValueError(f"serie: riga {i} non numerica: {ln!r}")
        import math
        if math.isnan(v) or math.isinf(v):
            raise ValueError(f"serie: riga {i} non finita")
        xs.append(v)
    if len(xs) < 20:
        raise ValueError(f"serie: servono almeno 20 valori "
                         f"(trovati {len(xs)})")
    return tuple(xs)


def mh443_equity(xs):
    """Equity composta dai rendimenti % (parte da 100.0), un valore
    per periodo. Serve solo per maxDD/Pain (coerenza con la
    famiglia); il GPR in se' non usa l'equity."""
    if xs is None:
        raise ValueError("serve una sequenza di rendimenti")
    vs = tuple(mh443_num(x, "rendimento") for x in xs)
    if len(vs) < 20:
        raise ValueError("equity: servono almeno 20 valori")
    eq = 100.0
    out = []
    for x in vs:
        eq *= 1.0 + x / 100.0
        out.append(eq)
    return tuple(out)


def mh443_drawdowns(xs):
    """Drawdown % (magnitudine >= 0) dal running max dell'equity,
    un valore per periodo. Peak iniziale = 100.0 (stessa
    convenzione di tab424/tab427/tab428/tab429/tab430/tab431/
    tab432/tab433/tab434/tab435/tab436/tab437/tab438/tab439/
    tab440/tab441/tab442)."""
    eq = mh443_equity(xs)
    peak = 100.0
    out = []
    for e in eq:
        if e > peak:
            peak = e
        out.append((peak - e) / peak * 100.0)
    return tuple(out)


def mh443_max_dd(xs):
    """Drawdown massimo di percorso (magnitudine % >= 0)."""
    dds = mh443_drawdowns(xs)
    return max(dds) if dds else 0.0


def mh443_gains(xs):
    """Guadagni totali: somma dei rendimenti > 0 (punti %)."""
    if xs is None:
        raise ValueError("serve una sequenza di rendimenti")
    vs = tuple(mh443_num(x, "rendimento") for x in xs)
    if len(vs) < 20:
        raise ValueError("gains: servono almeno 20 valori")
    return sum(v for v in vs if v > 0.0)


def mh443_losses(xs):
    """Perdite totali: |somma dei rendimenti < 0| (punti %,
    magnitudine >= 0)."""
    if xs is None:
        raise ValueError("serve una sequenza di rendimenti")
    vs = tuple(mh443_num(x, "rendimento") for x in xs)
    if len(vs) < 20:
        raise ValueError("losses: servono almeno 20 valori")
    return abs(sum(v for v in vs if v < 0.0))


def mh443_gain_to_pain(xs):
    """Gain-to-Pain ratio = guadagni totali / |perdite totali|.
    Convenzioni ai bordi: perdite 0 e guadagni > 0 -> +inf
    (solo guadagni), guadagni 0 -> 0.0 (serie piatta o solo
    perdite)."""
    import math
    g = mh443_gains(xs)
    l = mh443_losses(xs)
    if l == 0.0:
        if g > 0.0:
            return math.inf
        return 0.0
    return g / l


def mh443_curva_orizzonte(xs, extra=(0, 6, 12, 24), fill=3.0):
    """Curva GPR vs orizzonte: alla serie si appendono `extra`
    periodi al rendimento fisso `fill` % (default +3%) e si
    ricalcolano guadagni, perdite e GPR. Lista di dict con
    extra, n, gains, losses, gpr. Proprieta' (testate sulla
    demo): con fill > 0 le perdite restano FISSE e i guadagni
    crescono di fill * extra, quindi il GPR cresce LINEARE
    in extra."""
    if xs is None:
        raise ValueError("serve una sequenza di rendimenti")
    vs = tuple(mh443_num(x, "rendimento") for x in xs)
    if len(vs) < 20:
        raise ValueError("curva_orizzonte: servono almeno 20 valori")
    f = mh443_num(fill, "fill")
    try:
        ex = tuple(int(e) for e in extra)
    except TypeError:
        raise ValueError("curva_orizzonte: extra deve essere "
                         "una sequenza")
    if not ex:
        raise ValueError("curva_orizzonte: griglia extra vuota")
    for e in ex:
        if e < 0:
            raise ValueError("curva_orizzonte: extra negativo")
    out = []
    for e in sorted(ex):
        ext = vs + tuple([f] * e)
        g = mh443_gains(ext)
        l = mh443_losses(ext)
        gpr = mh443_gain_to_pain(ext)
        out.append({"extra": e, "n": len(ext), "gains": g,
                    "losses": l, "gpr": gpr})
    return out


def mh443_verdetto(gpr):
    """Verdetto a 6 stati sul Gain-to-Pain ratio: < 1 NEGATIVO
    (perdi piu' di quanto guadagni), < 1.5 DEBOLE, < 2
    DISCRETO, < 3 BUONO, < 5 OTTIMO, altrimenti ECCEZIONALE.
    +inf -> ECCEZIONALE (nessuna perdita da sopportare),
    -inf -> NEGATIVO. NaN o non-numero -> ValueError."""
    import math
    if isinstance(gpr, bool) or not isinstance(gpr, (int, float)):
        raise ValueError("verdetto: serve un numero")
    s = float(gpr)
    if math.isnan(s):
        raise ValueError("verdetto: NaN non ammesso")
    if s < 1.0:
        return (f"NEGATIVO — Gain-to-Pain {s:.4f}: perdi piu' di "
                f"quanto guadagni (meno di 1 punto guadagnato "
                f"per ogni punto perso).")
    if s < 1.5:
        return (f"DEBOLE — Gain-to-Pain {s:.4f}: 1-1.5 punti "
                f"guadagnati per ogni punto perso.")
    if s < 2.0:
        return (f"DISCRETO — Gain-to-Pain {s:.4f}: 1.5-2 punti "
                f"guadagnati per ogni punto perso.")
    if s < 3.0:
        return (f"BUONO — Gain-to-Pain {s:.4f}: 2-3 punti "
                f"guadagnati per ogni punto perso.")
    if s < 5.0:
        return (f"OTTIMO — Gain-to-Pain {s:.4f}: 3-5 punti "
                f"guadagnati per ogni punto perso.")
    return (f"ECCEZIONALE — Gain-to-Pain {s:.4f}: oltre 5 punti "
            f"guadagnati per ogni punto perso.")


def mh443_mappa(xs):
    """Mappa completa: n, mean, gains, losses, gpr, n_win,
    n_loss, win_rate, avg_win, avg_loss, payoff, max_dd, pain,
    total (composto), verdetto, equity, drawdowns, sotto (bool
    per periodo: True se drawdown > 0), cum_gains, cum_losses
    (magnitudine, per periodo)."""
    if xs is None:
        raise ValueError("serve una sequenza di rendimenti")
    vs = tuple(mh443_num(x, "rendimento") for x in xs)
    if len(vs) < 20:
        raise ValueError("mappa: servono almeno 20 valori")
    eq = mh443_equity(vs)
    if any(e <= 0.0 for e in eq):
        raise ValueError("mappa: equity azzerata (rendimento <= -100%)")
    dds = mh443_drawdowns(vs)
    dd = max(dds) if dds else 0.0
    pain = sum(dds) / len(dds) if dds else 0.0
    gains = sum(v for v in vs if v > 0.0)
    losses = abs(sum(v for v in vs if v < 0.0))
    gpr = mh443_gain_to_pain(vs)
    n_win = sum(1 for v in vs if v > 0.0)
    n_loss = sum(1 for v in vs if v < 0.0)
    win_rate = n_win / len(vs) * 100.0
    avg_win = gains / n_win if n_win else 0.0
    avg_loss = -losses / n_loss if n_loss else 0.0
    payoff = avg_win / abs(avg_loss) if n_loss and avg_loss != 0.0 else 0.0
    tot = (eq[-1] / 100.0 - 1.0) * 100.0
    cg = []
    cl = []
    _g = 0.0
    _l = 0.0
    for v in vs:
        if v > 0.0:
            _g += v
        elif v < 0.0:
            _l += -v
        cg.append(_g)
        cl.append(_l)
    return {"n": len(vs), "mean": sum(vs) / len(vs),
            "gains": gains, "losses": losses, "gpr": gpr,
            "n_win": n_win, "n_loss": n_loss,
            "win_rate": win_rate, "avg_win": avg_win,
            "avg_loss": avg_loss, "payoff": payoff,
            "max_dd": dd, "pain": pain,
            "n_dd": sum(1 for d in dds if d > 0.0), "total": tot,
            "verdetto": mh443_verdetto(gpr),
            "equity": eq, "dds": dds,
            "sotto": tuple(d > 0.0 for d in dds),
            "cum_gains": tuple(cg), "cum_losses": tuple(cl)}

def mh442_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh442_parse_serie(txt):
    """Una riga = un rendimento %; la virgola vale come decimale."""
    if not isinstance(txt, str):
        raise ValueError("serie: serve testo, un valore per riga")
    xs = []
    for i, ln in enumerate(txt.split("\n"), 1):
        s = ln.strip().replace(",", ".")
        if not s:
            continue
        try:
            v = float(s)
        except ValueError:
            raise ValueError(f"serie: riga {i} non numerica: {ln!r}")
        import math
        if math.isnan(v) or math.isinf(v):
            raise ValueError(f"serie: riga {i} non finita")
        xs.append(v)
    if len(xs) < 20:
        raise ValueError(f"serie: servono almeno 20 valori "
                         f"(trovati {len(xs)})")
    return tuple(xs)


def mh442_equity(xs):
    """Equity composta dai rendimenti % (parte da 100.0), un valore
    per periodo."""
    if xs is None:
        raise ValueError("serve una sequenza di rendimenti")
    vs = tuple(mh442_num(x, "rendimento") for x in xs)
    if len(vs) < 20:
        raise ValueError("equity: servono almeno 20 valori")
    eq = 100.0
    out = []
    for x in vs:
        eq *= 1.0 + x / 100.0
        out.append(eq)
    return tuple(out)


def mh442_drawdowns(xs):
    """Drawdown % (magnitudine >= 0) dal running max dell'equity,
    un valore per periodo. Peak iniziale = 100.0 (stessa
    convenzione di tab424/tab427/tab428/tab429/tab430/tab431/
    tab432/tab433/tab434/tab435/tab436/tab437/tab438/tab439/
    tab440/tab441)."""
    eq = mh442_equity(xs)
    peak = 100.0
    out = []
    for e in eq:
        if e > peak:
            peak = e
        out.append((peak - e) / peak * 100.0)
    return tuple(out)


def mh442_max_dd(xs):
    """Drawdown massimo di percorso (magnitudine % >= 0)."""
    dds = mh442_drawdowns(xs)
    return max(dds) if dds else 0.0


def mh442_total_return(xs):
    """Rendimento totale composto %: (equity finale / 100 - 1) *
    100. E' il profitto composto vero (include il volatility
    drag), NON la media annualizzata. Equity finale <= 0 ->
    ValueError (rendimento <= -100%)."""
    eq = mh442_equity(xs)
    if eq[-1] <= 0.0:
        raise ValueError("total_return: equity azzerata "
                         "(rendimento <= -100%)")
    return (eq[-1] / 100.0 - 1.0) * 100.0


def mh442_ann_return(xs, ppy):
    """Rendimento annualizzato % (mean-based, come tab431-441):
    ((1 + media/100) ** ppy - 1) * 100, dove media = media dei
    rendimenti % per periodo e ppy = periodi per anno. ppy deve
    essere > 0 e finito (non serve intero: nessun blocco annuo)."""
    vs = tuple(mh442_num(x, "rendimento") for x in xs) if xs is not None else None
    if vs is None:
        raise ValueError("serve una sequenza di rendimenti")
    if len(vs) < 20:
        raise ValueError("ann_return: servono almeno 20 valori")
    p = mh442_num(ppy, "periodi/anno")
    if not p > 0.0:
        raise ValueError("ann_return: periodi/anno fuori (0, +inf)")
    media = sum(vs) / len(vs)
    if media <= -100.0:
        raise ValueError("ann_return: media <= -100%")
    return ((1.0 + media / 100.0) ** p - 1.0) * 100.0


def mh442_geo_ann(xs, ppy):
    """CAGR geometrico %: ((equity finale / 100) ** (ppy/n) - 1) *
    100. E' l'annualizzazione del totale composto vero: a
    parita' di media, scende quando la volatilita' sale (drag).
    Differenza ann - geo_ann = drag in punti annui."""
    eq = mh442_equity(xs)
    if eq[-1] <= 0.0:
        raise ValueError("geo_ann: equity azzerata "
                         "(rendimento <= -100%)")
    p = mh442_num(ppy, "periodi/anno")
    if not p > 0.0:
        raise ValueError("geo_ann: periodi/anno fuori (0, +inf)")
    return ((eq[-1] / 100.0) ** (p / len(eq)) - 1.0) * 100.0


def mh442_geo_calmar(xs, ppy):
    """Calmar geometrico = CAGR geometrico % / maxDD %. Convenzioni
    ai bordi (maxDD = 0): CAGR > 0 -> +inf (solo guadagni),
    CAGR = 0 -> 0.0 (serie piatta), CAGR < 0 -> -inf
    (irraggiungibile in pratica: un totale negativo implica un
    drawdown > 0)."""
    import math
    geo = mh442_geo_ann(xs, ppy)
    dd = mh442_max_dd(xs)
    if dd == 0.0:
        if geo > 0.0:
            return math.inf
        if geo == 0.0:
            return 0.0
        return -math.inf
    return geo / dd


def mh442_curva_orizzonte(xs, extra=(0, 6, 12, 24), fill=3.0, ppy=12.0):
    """Curva GeoCalmar (e RF) vs orizzonte: alla serie si appendono
    `extra` periodi al rendimento fisso `fill` % (default +3%) e
    si ricalcolano totale, maxDD, CAGR, GeoCalmar e RF. Lista di
    dict con extra, n, total, max_dd, geo_ann, geo_calmar, rf.
    Proprieta' (testate sulla demo): a maxDD fisso il GeoCalmar
    e' NON DECRESCENTE in extra quando fill > 0, ma cresce
    LENTO (i nuovi guadagni si diluiscono su un orizzonte piu'
    lungo) mentre l'RF cresce VELOCE."""
    if xs is None:
        raise ValueError("serve una sequenza di rendimenti")
    vs = tuple(mh442_num(x, "rendimento") for x in xs)
    if len(vs) < 20:
        raise ValueError("curva_orizzonte: servono almeno 20 valori")
    f = mh442_num(fill, "fill")
    p = mh442_num(ppy, "periodi/anno")
    if not p > 0.0:
        raise ValueError("curva_orizzonte: periodi/anno fuori (0, +inf)")
    try:
        ex = tuple(int(e) for e in extra)
    except TypeError:
        raise ValueError("curva_orizzonte: extra deve essere "
                         "una sequenza")
    if not ex:
        raise ValueError("curva_orizzonte: griglia extra vuota")
    for e in ex:
        if e < 0:
            raise ValueError("curva_orizzonte: extra negativo")
    out = []
    for e in sorted(ex):
        ext = vs + tuple([f] * e)
        tot = mh442_total_return(ext)
        dd = mh442_max_dd(ext)
        geo = mh442_geo_ann(ext, p)
        gc = mh442_geo_calmar(ext, p)
        rf = tot / dd if dd != 0.0 else (float("inf") if tot > 0.0 else 0.0)
        out.append({"extra": e, "n": len(ext), "total": tot,
                    "max_dd": dd, "geo_ann": geo,
                    "geo_calmar": gc, "rf": rf})
    return out


def mh442_verdetto(gc):
    """Verdetto a 6 stati sul Calmar geometrico (STESSA scala del
    Calmar tab431): < 0 NEGATIVO, < 0.5 DEBOLE, < 1 DISCRETO,
    < 2 BUONO, < 3 OTTIMO, altrimenti ECCEZIONALE. +inf ->
    ECCEZIONALE (nessun calo da sopportare), -inf -> NEGATIVO.
    NaN o non-numero -> ValueError."""
    import math
    if isinstance(gc, bool) or not isinstance(gc, (int, float)):
        raise ValueError("verdetto: serve un numero")
    s = float(gc)
    if math.isnan(s):
        raise ValueError("verdetto: NaN non ammesso")
    if s < 0.0:
        return (f"NEGATIVO — Calmar geometrico {s:.4f}: il CAGR "
                f"composto e' negativo, il drawdown non e' "
                f"compensato.")
    if s < 0.5:
        return (f"DEBOLE — Calmar geometrico {s:.4f}: meno di 0.5 "
                f"punti di CAGR composto per ogni punto di "
                f"peggior drawdown.")
    if s < 1.0:
        return (f"DISCRETO — Calmar geometrico {s:.4f}: circa un "
                f"punto di CAGR composto per ogni punto di "
                f"peggior drawdown.")
    if s < 2.0:
        return (f"BUONO — Calmar geometrico {s:.4f}: 1-2 punti di "
                f"CAGR composto per ogni punto di peggior "
                f"drawdown.")
    if s < 3.0:
        return (f"OTTIMO — Calmar geometrico {s:.4f}: 2-3 punti di "
                f"CAGR composto per ogni punto di peggior "
                f"drawdown.")
    return (f"ECCEZIONALE — Calmar geometrico {s:.4f}: oltre 3 "
            f"punti di CAGR composto per ogni punto di peggior "
            f"drawdown.")


def mh442_mappa(xs, ppy):
    """Mappa completa: n, media, max_dd, pain, total, geo_ann,
    ann, drag (ann - geo_ann), geo_calmar, calmar (ann / maxDD,
    tab431), rf (totale / maxDD, tab441), ppy, n_dd,
    sotto (bool per periodo: True se l'equity del periodo sta
    sotto il running max, cioe' drawdown > 0), verdetto,
    equity, drawdowns."""
    if xs is None:
        raise ValueError("serve una sequenza di rendimenti")
    vs = tuple(mh442_num(x, "rendimento") for x in xs)
    if len(vs) < 20:
        raise ValueError("mappa: servono almeno 20 valori")
    p = mh442_num(ppy, "periodi/anno")
    if not p > 0.0:
        raise ValueError("mappa: periodi/anno fuori (0, +inf)")
    eq = mh442_equity(vs)
    if any(e <= 0.0 for e in eq):
        raise ValueError("mappa: equity azzerata (rendimento <= -100%)")
    dds = mh442_drawdowns(vs)
    dd = max(dds) if dds else 0.0
    pain = sum(dds) / len(dds) if dds else 0.0
    tot = mh442_total_return(vs)
    ann = mh442_ann_return(vs, p)
    geo = mh442_geo_ann(vs, p)
    gc = mh442_geo_calmar(vs, p)
    calmar = ann / dd if dd != 0.0 else float("inf")
    rf = tot / dd if dd != 0.0 else (float("inf") if tot > 0.0 else 0.0)
    return {"n": len(vs), "mean": sum(vs) / len(vs),
            "max_dd": dd, "pain": pain,
            "total": tot, "geo_ann": geo, "ann": ann,
            "drag": ann - geo, "geo_calmar": gc, "calmar": calmar,
            "rf": rf, "ppy": p,
            "n_dd": sum(1 for d in dds if d > 0.0),
            "sotto": tuple(d > 0.0 for d in dds),
            "verdetto": mh442_verdetto(gc),
            "equity": eq, "dds": dds}

def mh441_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh441_parse_serie(txt):
    """Una riga = un rendimento %; la virgola vale come decimale."""
    if not isinstance(txt, str):
        raise ValueError("serie: serve testo, un valore per riga")
    xs = []
    for i, ln in enumerate(txt.split("\n"), 1):
        s = ln.strip().replace(",", ".")
        if not s:
            continue
        try:
            v = float(s)
        except ValueError:
            raise ValueError(f"serie: riga {i} non numerica: {ln!r}")
        import math
        if math.isnan(v) or math.isinf(v):
            raise ValueError(f"serie: riga {i} non finita")
        xs.append(v)
    if len(xs) < 20:
        raise ValueError(f"serie: servono almeno 20 valori "
                         f"(trovati {len(xs)})")
    return tuple(xs)


def mh441_equity(xs):
    """Equity composta dai rendimenti % (parte da 100.0), un valore
    per periodo."""
    if xs is None:
        raise ValueError("serve una sequenza di rendimenti")
    vs = tuple(mh441_num(x, "rendimento") for x in xs)
    if len(vs) < 20:
        raise ValueError("equity: servono almeno 20 valori")
    eq = 100.0
    out = []
    for x in vs:
        eq *= 1.0 + x / 100.0
        out.append(eq)
    return tuple(out)


def mh441_drawdowns(xs):
    """Drawdown % (magnitudine >= 0) dal running max dell'equity,
    un valore per periodo. Peak iniziale = 100.0 (stessa
    convenzione di tab424/tab427/tab428/tab429/tab430/tab431/
    tab432/tab433/tab434/tab435/tab436/tab437/tab438/tab439/
    tab440)."""
    eq = mh441_equity(xs)
    peak = 100.0
    out = []
    for e in eq:
        if e > peak:
            peak = e
        out.append((peak - e) / peak * 100.0)
    return tuple(out)


def mh441_max_dd(xs):
    """Drawdown massimo di percorso (magnitudine % >= 0)."""
    dds = mh441_drawdowns(xs)
    return max(dds) if dds else 0.0


def mh441_total_return(xs):
    """Rendimento totale composto %: (equity finale / 100 - 1) *
    100. E' il profitto composto vero (include il volatility
    drag), NON la media annualizzata. Equity finale <= 0 ->
    ValueError (rendimento <= -100%)."""
    eq = mh441_equity(xs)
    if eq[-1] <= 0.0:
        raise ValueError("total_return: equity azzerata "
                         "(rendimento <= -100%)")
    return (eq[-1] / 100.0 - 1.0) * 100.0


def mh441_ann_return(xs, ppy):
    """Rendimento annualizzato % (mean-based, come tab431-440):
    ((1 + media/100) ** ppy - 1) * 100, dove media = media dei
    rendimenti % per periodo e ppy = periodi per anno. ppy deve
    essere > 0 e finito (non serve intero: nessun blocco annuo)."""
    vs = tuple(mh441_num(x, "rendimento") for x in xs) if xs is not None else None
    if vs is None:
        raise ValueError("serve una sequenza di rendimenti")
    if len(vs) < 20:
        raise ValueError("ann_return: servono almeno 20 valori")
    p = mh441_num(ppy, "periodi/anno")
    if not p > 0.0:
        raise ValueError("ann_return: periodi/anno fuori (0, +inf)")
    media = sum(vs) / len(vs)
    if media <= -100.0:
        raise ValueError("ann_return: media <= -100%")
    return ((1.0 + media / 100.0) ** p - 1.0) * 100.0


def mh441_geo_ann(xs, ppy):
    """CAGR geometrico %: ((equity finale / 100) ** (ppy/n) - 1) *
    100. E' l'annualizzazione del totale composto vero: a
    parita' di media, scende quando la volatilita' sale (drag).
    Differenza ann - geo_ann = drag in punti annui."""
    eq = mh441_equity(xs)
    if eq[-1] <= 0.0:
        raise ValueError("geo_ann: equity azzerata "
                         "(rendimento <= -100%)")
    p = mh441_num(ppy, "periodi/anno")
    if not p > 0.0:
        raise ValueError("geo_ann: periodi/anno fuori (0, +inf)")
    return ((eq[-1] / 100.0) ** (p / len(eq)) - 1.0) * 100.0


def mh441_recovery_factor(xs):
    """Recovery Factor = totale composto % / maxDD %. Convenzioni
    ai bordi (maxDD = 0): totale > 0 -> +inf (solo guadagni),
    totale = 0 -> 0.0 (serie piatta), totale < 0 -> -inf
    (irraggiungibile in pratica: un totale negativo implica un
    drawdown > 0)."""
    import math
    tot = mh441_total_return(xs)
    dd = mh441_max_dd(xs)
    if dd == 0.0:
        if tot > 0.0:
            return math.inf
        if tot == 0.0:
            return 0.0
        return -math.inf
    return tot / dd


def mh441_curva_orizzonte(xs, extra=(0, 6, 12, 24), fill=3.0):
    """Curva RF vs orizzonte: alla serie si appendono `extra`
    periodi al rendimento fisso `fill` % (default +3%) e si
    ricalcolano totale, maxDD e RF. Lista di dict con extra, n,
    total, max_dd, rf. Proprieta' (testate sulla demo): a maxDD
    fisso (il picco non viene superato dai nuovi periodi finche'
    l'equity resta sotto il picco, poi il maxDD resta comunque
    il peggior calo storico) l'RF e' NON DECRESCENTE in extra
    quando fill > 0 e il totale cresce."""
    if xs is None:
        raise ValueError("serve una sequenza di rendimenti")
    vs = tuple(mh441_num(x, "rendimento") for x in xs)
    if len(vs) < 20:
        raise ValueError("curva_orizzonte: servono almeno 20 valori")
    f = mh441_num(fill, "fill")
    try:
        ex = tuple(int(e) for e in extra)
    except TypeError:
        raise ValueError("curva_orizzonte: extra deve essere "
                         "una sequenza")
    if not ex:
        raise ValueError("curva_orizzonte: griglia extra vuota")
    for e in ex:
        if e < 0:
            raise ValueError("curva_orizzonte: extra negativo")
    out = []
    for e in sorted(ex):
        ext = vs + tuple([f] * e)
        tot = mh441_total_return(ext)
        dd = mh441_max_dd(ext)
        rf = mh441_recovery_factor(ext)
        out.append({"extra": e, "n": len(ext), "total": tot,
                    "max_dd": dd, "rf": rf})
    return out


def mh441_verdetto(rf):
    """Verdetto a 6 stati sull'RF (maggiore = migliore): < 0
    NEGATIVO, < 0.5 MOLTO DEBOLE, < 1 DEBOLE, < 2 DISCRETO,
    < 4 BUONO, altrimenti OTTIMO. +inf -> OTTIMO (nessun calo
    da sopportare). NaN o -inf o non-numero -> ValueError
    (il -inf non e' un RF valido: un totale negativo implica
    un drawdown > 0)."""
    import math
    if isinstance(rf, bool) or not isinstance(rf, (int, float)):
        raise ValueError("verdetto: serve un numero")
    s = float(rf)
    if math.isnan(s) or math.isinf(s) and s < 0.0:
        raise ValueError("verdetto: NaN/-inf non ammessi")
    if math.isinf(s):
        return (f"OTTIMO — RF +inf: nessun drawdown (solo "
                f"guadagni), profitto senza calo da sopportare.")
    if s < 0.0:
        return (f"NEGATIVO — RF {s:.4f}: il profitto totale e' "
                f"negativo, il peggior calo non e' stato "
                f"recuperato.")
    if s < 0.5:
        return (f"MOLTO DEBOLE — RF {s:.4f}: il profitto totale "
                f"vale meno di meta' del peggior calo.")
    if s < 1.0:
        return (f"DEBOLE — RF {s:.4f}: il profitto totale non "
                f"copre il peggior calo.")
    if s < 2.0:
        return (f"DISCRETO — RF {s:.4f}: il profitto totale vale "
                f"{s:.4f} volte il peggior calo.")
    if s < 4.0:
        return (f"BUONO — RF {s:.4f}: il profitto totale vale "
                f"{s:.4f} volte il peggior calo.")
    return (f"OTTIMO — RF {s:.4f}: il profitto totale vale "
            f"{s:.4f} volte il peggior calo.")


def mh441_mappa(xs, ppy):
    """Mappa completa: n, media, max_dd, pain, total, geo_ann,
    ann, drag (ann - geo_ann), rf, calmar (ann / maxDD, tab431),
    rf_nodrag (RF che avresti senza drag), ppy, n_dd,
    sotto (bool per periodo: True se l'equity del periodo sta
    sotto il running max, cioe' drawdown > 0), verdetto,
    equity, drawdowns."""
    if xs is None:
        raise ValueError("serve una sequenza di rendimenti")
    vs = tuple(mh441_num(x, "rendimento") for x in xs)
    if len(vs) < 20:
        raise ValueError("mappa: servono almeno 20 valori")
    p = mh441_num(ppy, "periodi/anno")
    if not p > 0.0:
        raise ValueError("mappa: periodi/anno fuori (0, +inf)")
    eq = mh441_equity(vs)
    if any(e <= 0.0 for e in eq):
        raise ValueError("mappa: equity azzerata (rendimento <= -100%)")
    dds = mh441_drawdowns(vs)
    dd = max(dds) if dds else 0.0
    pain = sum(dds) / len(dds) if dds else 0.0
    tot = mh441_total_return(vs)
    ann = mh441_ann_return(vs, p)
    geo = mh441_geo_ann(vs, p)
    rf = mh441_recovery_factor(vs)
    calmar = ann / dd if dd != 0.0 else float("inf")
    rf_nodrag = ((((1.0 + ann / 100.0) ** (len(vs) / p) - 1.0) * 100.0)
                 / dd) if dd != 0.0 else float("inf")
    return {"n": len(vs), "mean": sum(vs) / len(vs),
            "max_dd": dd, "pain": pain,
            "total": tot, "geo_ann": geo, "ann": ann,
            "drag": ann - geo, "rf": rf, "calmar": calmar,
            "rf_nodrag": rf_nodrag, "ppy": p,
            "n_dd": sum(1 for d in dds if d > 0.0),
            "sotto": tuple(d > 0.0 for d in dds),
            "verdetto": mh441_verdetto(rf),
            "equity": eq, "dds": dds}

def mh440_num(x, nome):
    import math
