def mh440_ann_return(xs, ppy):
    """Rendimento annualizzato %: ((1 + media/100) ** ppy - 1) * 100,
    dove media = media dei rendimenti % per periodo e ppy = periodi
    per anno. ppy deve essere > 0 e finito (non serve intero:
    nessun blocco annuo)."""
    vs = tuple(mh440_num(x, "rendimento") for x in xs) if xs is not None else None
    if vs is None:
        raise ValueError("serve una sequenza di rendimenti")
    if len(vs) < 20:
        raise ValueError("ann_return: servono almeno 20 valori")
    p = mh440_num(ppy, "periodi/anno")
    if not p > 0.0:
        raise ValueError("ann_return: periodi/anno fuori (0, +inf)")
    media = sum(vs) / len(vs)
    if media <= -100.0:
        raise ValueError("ann_return: media <= -100%")
    return ((1.0 + media / 100.0) ** p - 1.0) * 100.0


def mh440_dar(xs, alpha):
    """DaR(alpha): il k-esimo drawdown peggiore, k = ceil(alpha /
    100 * n) = il piu' piccolo dei top-k = soglia VaR-DD della
    coda. Ritorna dict con alpha, k, dar, cdar (media dei top-k),
    gap (cdar - dar), pain, max_dd, n_ge (periodi con drawdown >=
    dar), n_gt (periodi con drawdown > dar). Proprieta' (testate):
    dar <= cdar <= max_dd; gap >= 0; k == 1 -> dar == cdar ==
    max_dd; alpha = 100% -> dar = drawdown minimo; dar
    decrescente in alpha; dar NON dipende da ppy (non e' un
    rendimento annualizzato)."""
    if xs is None:
        raise ValueError("serve una sequenza di rendimenti")
    vs = tuple(mh440_num(x, "rendimento") for x in xs)
    if len(vs) < 20:
        raise ValueError("dar: servono almeno 20 valori")
    a = mh440_num(alpha, "alpha")
    if not 0.0 < a <= 100.0:
        raise ValueError("dar: alpha fuori (0, 100]")
    import math
    dds = sorted(mh440_drawdowns(vs), reverse=True)
    n = len(dds)
    k = math.ceil(a / 100.0 * n)
    k = max(1, min(k, n))
    top = dds[:k]
    dar = top[-1]
    cdar = sum(top) / k
    pain = sum(dds) / n
    return {"alpha": a, "k": k, "dar": dar, "cdar": cdar,
            "gap": cdar - dar, "pain": pain, "max_dd": dds[0],
            "n_ge": sum(1 for d in dds if d >= dar),
            "n_gt": sum(1 for d in dds if d > dar)}


def mh440_curva(xs, alphas=(5.0, 10.0, 20.0, 25.0, 50.0, 100.0)):
    """Curva DaR/CDaR su una griglia di alpha: lista di dict con
    alpha, k, dar, cdar, gap. La curva DaR e' monotona NON
    CRESCENTE in alpha (a gradini: crolla a 0 quando k supera i
    periodi sott'acqua); la curva CDaR e' monotona NON CRESCENTE
    e resta > 0 finche' c'e' almeno un periodo sott'acqua."""
    if xs is None:
        raise ValueError("serve una sequenza di rendimenti")
    vs = tuple(mh440_num(x, "rendimento") for x in xs)
    if len(vs) < 20:
        raise ValueError("curva: servono almeno 20 valori")
    try:
        al = tuple(mh440_num(a, "alpha") for a in alphas)
    except TypeError:
        raise ValueError("curva: alphas deve essere una sequenza")
    if not al:
        raise ValueError("curva: griglia alpha vuota")
    for a in al:
        if not 0.0 < a <= 100.0:
            raise ValueError("curva: alpha fuori (0, 100]")
    out = []
    for a in sorted(al):
        c = mh440_dar(vs, a)
        out.append({"alpha": a, "k": c["k"], "dar": c["dar"],
                    "cdar": c["cdar"], "gap": c["gap"]})
    return out


def mh440_verdetto(dar):
    """Verdetto a 6 stati sul DaR (soglia di perdita: minore =
    migliore): <= 5 ECCEZIONALE, <= 10 OTTIMO, <= 20 BUONO,
    <= 30 DISCRETO, <= 40 DEBOLE, altrimenti CRITICO. Un DaR
    negativo non e' una magnitudine valida -> ValueError."""
    import math
    if isinstance(dar, bool) or not isinstance(dar, (int, float)):
        raise ValueError("verdetto: serve un numero")
    s = float(dar)
    if math.isnan(s):
        raise ValueError("verdetto: NaN non ammesso")
    if math.isinf(s):
        return (f"CRITICO — DaR +inf%: la soglia di coda non e' "
                f"finita, il drawdown peggiore domina la serie.")
    if s < 0.0:
        raise ValueError("verdetto: DaR negativo non valido")
    if s <= 5.0:
        return (f"ECCEZIONALE — DaR {s:.4f}%: solo l'alpha% dei "
                f"periodi supera un drawdown del {s:.4f}% — la "
                f"soglia della coda e' bassissima.")
    if s <= 10.0:
        return (f"OTTIMO — DaR {s:.4f}%: solo l'alpha% dei periodi "
                f"supera un drawdown del {s:.4f}%.")
    if s <= 20.0:
        return (f"BUONO — DaR {s:.4f}%: solo l'alpha% dei periodi "
                f"supera un drawdown del {s:.4f}%.")
    if s <= 30.0:
        return (f"DISCRETO — DaR {s:.4f}%: l'alpha% dei periodi "
                f"supera un drawdown del {s:.4f}% — soglia della "
                f"coda alta, da coprire con margine.")
    if s <= 40.0:
        return (f"DEBOLE — DaR {s:.4f}%: l'alpha% dei periodi "
                f"supera un drawdown del {s:.4f}% — la coda "
                f"inizia molto in basso.")
    return (f"CRITICO — DaR {s:.4f}%: l'alpha% dei periodi supera "
            f"un drawdown del {s:.4f}% — la coda inizia oltre "
            f"il -40%.")


def mh440_mappa(xs, alpha, ppy):
    """Mappa completa: n, media, max_dd, pain, alpha, k, dar,
    cdar, gap, n_ge, n_gt, ann, ppy, n_dd, in_coda (bool per
    periodo: True se il drawdown del periodo sta nei top-k
    peggiori, spareggio a parita' sul periodo piu' antico),
    oltre (bool per periodo: True se il drawdown supera
    strettamente il DaR), verdetto, equity, drawdowns."""
    if xs is None:
        raise ValueError("serve una sequenza di rendimenti")
    vs = tuple(mh440_num(x, "rendimento") for x in xs)
    if len(vs) < 20:
        raise ValueError("mappa: servono almeno 20 valori")
    p = mh440_num(ppy, "periodi/anno")
    if not p > 0.0:
        raise ValueError("mappa: periodi/anno fuori (0, +inf)")
    eq = mh440_equity(vs)
    if any(e <= 0.0 for e in eq):
        raise ValueError("mappa: equity azzerata (rendimento <= -100%)")
    dds = mh440_drawdowns(vs)
    dd = max(dds) if dds else 0.0
    pain = sum(dds) / len(dds) if dds else 0.0
    ann = mh440_ann_return(vs, p)
    c = mh440_dar(vs, alpha)
    order = sorted(range(len(dds)), key=lambda i: (-dds[i], i))
    coda_idx = set(order[:c["k"]])
    in_coda = tuple(i in coda_idx for i in range(len(dds)))
    oltre = tuple(d > c["dar"] for d in dds)
    return {"n": len(vs), "mean": sum(vs) / len(vs),
            "max_dd": dd, "pain": pain,
            "alpha": c["alpha"], "k": c["k"], "dar": c["dar"],
            "cdar": c["cdar"], "gap": c["gap"],
            "n_ge": c["n_ge"], "n_gt": c["n_gt"],
            "ann": ann, "ppy": p,
            "n_dd": sum(1 for d in dds if d > 0.0),
            "in_coda": in_coda, "oltre": oltre,
            "verdetto": mh440_verdetto(c["dar"]),
            "equity": eq, "dds": dds}

