def mh431_calmar(xs, ppy):
    """Calmar ratio = rendimento annualizzato / maxDD. Convenzioni ai
    bordi (maxDD == 0): ann == 0 -> 0.0; ann > 0 -> +inf;
    ann < 0 -> -inf."""
    ann = mh431_ann_return(xs, ppy)
    dd = mh431_max_dd(xs)
    if dd == 0.0:
        if ann == 0.0:
            return 0.0
        return float("inf") if ann > 0.0 else float("-inf")
    return ann / dd


def mh431_verdetto(calmar):
    """Verdetto a 6 stati sul Calmar: < 0 NEGATIVO, < 0.5 DEBOLE,
    < 1 DISCRETO, < 2 BUONO, < 3 OTTIMO, altrimenti ECCEZIONALE."""
    import math
    if isinstance(calmar, bool) or not isinstance(calmar, (int, float)):
        raise ValueError("verdetto: serve un numero")
