    return {"n": len(vs), "mean": sum(vs) / len(vs),
            "max_dd": dd, "pain": sum(dds) / len(dds) if dds else 0.0,
            "ann": ann, "calmar": cal, "ppy": p,
            "verdetto": mh431_verdetto(cal),
            "equity": eq, "dds": dds}

