def mh430_rebound(dd):
    """Rimbalzo % necessario per recuperare un drawdown dd %:
    (1 - dd/100) * (1 + R/100) = 1  =>  R = dd / (100 - dd) * 100.
    dd in [0, 100): dd = 0 -> R = 0; dd -> 100 -> R -> +inf
    (da equity zero non si risale: il caso dd = 100 e' rifiutato
    dai chiamanti con ValueError)."""
    d = mh430_num(dd, "drawdown")
    if not 0.0 <= d < 100.0:
        raise ValueError("rebound: drawdown fuori [0, 100)")
    return d / (100.0 - d) * 100.0


def mh430_episodes(xs):
    """Episodi di drawdown: sequenze massimali di periodi consecutivi
    con drawdown > 0. Ritorna una tupla di dict con peak_idx
    (indice 0-based dell'equity di picco, -1 = valore iniziale 100
    prima della serie), peak_per (periodo 1-based del picco,
    0 = prima della serie), trough_idx / trough_per (minimo),
    start / end (indici 0-based dell'episodio, estremi inclusi),
    durata (periodi sott'acqua), peak_eq / trough_eq, max_dd
    (picco di drawdown nell'episodio), rebound (rimbalzo % per
    tornare al picco), chiuso (True se il drawdown e' tornato a 0
    prima della fine serie, False se l'episodio e' APERTO),
    rec_periods (periodi dal minimo al recupero, incluso il
    periodo di recupero; None se aperto).
    Proprieta' (testate): la somma delle durate e' il numero di
    periodi sott'acqua; l'ultimo episodio e' aperto <=> il
    drawdown finale > 0; trough * (1 + rebound/100) = peak."""
    if xs is None:
        raise ValueError("serve una sequenza di rendimenti")
    vs = tuple(mh430_num(x, "rendimento") for x in xs)
    if len(vs) < 20:
        raise ValueError("episodes: servono almeno 20 valori")
    eqs = mh430_equity(vs)
    if any(e <= 0.0 for e in eqs):
        raise ValueError("episodi: equity azzerata (rendimento <= -100%)")
    dds = mh430_drawdowns(vs)
    n = len(dds)
    eps = []
    i = 0
    while i < n:
        if dds[i] > 0.0:
            s = i
            peak_eq = 100.0
            peak_idx = -1
            for k in range(s):
                if eqs[k] > peak_eq:
                    peak_eq = eqs[k]
                    peak_idx = k
            while i < n and dds[i] > 0.0:
                i += 1
            e = i - 1
            seg_eq = eqs[s:e + 1]
            trough_off = seg_eq.index(min(seg_eq))
            trough_idx = s + trough_off
            trough_eq = seg_eq[trough_off]
            max_dd = (peak_eq - trough_eq) / peak_eq * 100.0
            chiuso = e + 1 < n
            eps.append({"peak_idx": peak_idx, "peak_per": peak_idx + 1,
                        "trough_idx": trough_idx,
                        "trough_per": trough_idx + 1,
                        "start": s, "end": e, "durata": e - s + 1,
                        "peak_eq": peak_eq, "trough_eq": trough_eq,
                        "max_dd": max_dd,
                        "rebound": mh430_rebound(max_dd),
                        "chiuso": chiuso,
                        "rec_periods": (e + 1 - trough_idx)
                        if chiuso else None})
        else:
            i += 1
    return tuple(eps)


def mh430_worst(xs):
    """Episodio peggiore (maxDD massimo) + mean / pain di percorso.
    Se maxDD == 0 (mai sott'acqua): peak_idx = trough_idx = -1,
    peak_per = trough_per = 0, max_dd = 0.0, peak_eq = trough_eq
    = 100.0, rebound = 0.0, chiuso = True, rec_periods = 0."""
    if xs is None:
        raise ValueError("serve una sequenza di rendimenti")
    vs = tuple(mh430_num(x, "rendimento") for x in xs)
    if len(vs) < 20:
        raise ValueError("worst: servono almeno 20 valori")
    eqs = mh430_equity(vs)
    if any(e <= 0.0 for e in eqs):
        raise ValueError("worst: equity azzerata (rendimento <= -100%)")
    dds = mh430_drawdowns(vs)
    max_dd = max(dds)
    mean = sum(vs) / len(vs)
    pain = sum(dds) / len(dds)
    if max_dd == 0.0:
        return {"peak_idx": -1, "trough_idx": -1, "peak_per": 0,
                "trough_per": 0, "start": None, "end": None,
                "durata": 0, "max_dd": 0.0, "peak_eq": 100.0,
                "trough_eq": 100.0, "rebound": 0.0, "chiuso": True,
                "rec_periods": 0, "mean": mean, "pain": pain}
    eps = mh430_episodes(vs)
    w = max(eps, key=lambda e: e["max_dd"])
    return {"peak_idx": w["peak_idx"], "trough_idx": w["trough_idx"],
            "peak_per": w["peak_per"], "trough_per": w["trough_per"],
            "start": w["start"], "end": w["end"],
            "durata": w["durata"], "max_dd": w["max_dd"],
            "peak_eq": w["peak_eq"], "trough_eq": w["trough_eq"],
            "rebound": w["rebound"], "chiuso": w["chiuso"],
            "rec_periods": w["rec_periods"], "mean": mean,
            "pain": pain}


def mh430_recovery(xs):
    """Metriche di recupero: dict con n, mean, pain, max_dd,
    rebound (rimbalzo % per recuperare il drawdown massimo),
    n_ep (episodi), episodi (tupla mh430_episodes), worst
    (dict mh430_worst), n_chiusi / n_aperti, rec_medio
    (media dei periodi al recupero sugli episodi CHIUSI, None se
    nessun episodio chiuso), rec_max (massimo, None se nessuno
    chiuso), equity (tupla), dds (tupla drawdown).
    Proprieta' (testate): somma durate episodi == periodi
    sott'acqua; worst == episodio con max_dd massimo; rebound
    soddisfa (1 - maxDD/100) * (1 + rebound/100) = 1."""
    if xs is None:
        raise ValueError("serve una sequenza di rendimenti")
    vs = tuple(mh430_num(x, "rendimento") for x in xs)
    if len(vs) < 20:
        raise ValueError("recovery: servono almeno 20 valori")
    dds = mh430_drawdowns(vs)
    eps = mh430_episodes(vs)
    max_dd = max(dds) if dds else 0.0
    worst = mh430_worst(vs)
    chiusi = [e for e in eps if e["chiuso"]]
    return {"n": len(vs), "mean": sum(vs) / len(vs),
            "pain": sum(dds) / len(dds), "max_dd": max_dd,
            "n_ep": len(eps), "episodi": eps,
            "worst": worst,
            "rebound": mh430_rebound(max_dd) if max_dd > 0.0 else 0.0,
            "n_chiusi": len(chiusi),
            "n_aperti": len(eps) - len(chiusi),
            "rec_medio": (sum(e["rec_periods"] for e in chiusi)
                          / len(chiusi) if chiusi else None),
            "rec_max": (max(e["rec_periods"] for e in chiusi)
                        if chiusi else None),
            "equity": mh430_equity(vs), "dds": dds}


def mh430_verdetto(rebound, soglia):
    """Verdetto a 6 stati sul rapporto r = rebound / soglia:
    rebound == 0 ROBUSTO, r < 0.5 FACILE, r < 1.0 MODERATO,
    r < 1.5 DURO, r < 2.0 ESTREMO, altrimenti CRITICO."""
    r_ = mh430_num(rebound, "rebound")
    if r_ < 0.0:
        raise ValueError("verdetto: rebound negativo")
    s = mh430_num(soglia, "soglia")
    if not 0.0 < s <= 100.0:
        raise ValueError("verdetto: soglia fuori (0, 100]")
    if r_ == 0.0:
        return ("ROBUSTO: nessun drawdown — nessun rimbalzo "
                "necessario per tornare al picco")
    r = r_ / s
    if r < 0.5:
        return (f"FACILE: rimbalzo {r_:.4f}% pari al {r * 100.0:.0f}% "
                f"della soglia {s:.1f}% — il recupero e' a portata")
    if r < 1.0:
        return (f"MODERATO: rimbalzo {r_:.4f}% pari al "
                f"{r * 100.0:.0f}% della soglia {s:.1f}% — serve un "
                f"recupero solido ma realistico")
    if r < 1.5:
        return (f"DURO: rimbalzo {r_:.4f}% sopra la soglia {s:.1f}% "
                f"(x{r:.2f}) — il recupero richiede un rally "
                f"importante")
    if r < 2.0:
        return (f"ESTREMO: rimbalzo {r_:.4f}% quasi il doppio della "
                f"soglia {s:.1f}% (x{r:.2f}) — tornare al picco "
                f"richiede un rimbalzo eccezionale")
    return (f"CRITICO: rimbalzo {r_:.4f}% oltre il doppio della "
            f"soglia {s:.1f}% (x{r:.2f}) — il picco e' quasi "
            f"irraggiungibile")


def mh430_mappa(xs, soglia=50.0):
    """Mappa completa per la UI: recupero, soglia rimbalzo, verdetto."""
    if xs is None:
        raise ValueError("serve una sequenza di rendimenti")
    vs = tuple(mh430_num(x, "rendimento") for x in xs)
    if len(vs) < 20:
        raise ValueError("mappa: servono almeno 20 valori")
    rec = mh430_recovery(vs)
    s = mh430_num(soglia, "soglia")
    if not 0.0 < s <= 100.0:
        raise ValueError("mappa: soglia fuori (0, 100]")
    return {"n": len(vs), "rec": rec, "soglia": s,
            "verdetto": mh430_verdetto(rec["rebound"], s)}

def mh429_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh429_parse_serie(txt):
    """Una riga = un rendimento %; la virgola vale come decimale."""
    if not isinstance(txt, str):
        raise ValueError("serie: serve testo, un valore per riga")
    xs = []
    for i, ln in enumerate(txt.split("\n"), 1):
        s = ln.strip().replace(",", ".")
        if not s:
            continue
        try:
            v = float(s)
        except ValueError:
            raise ValueError(f"serie: riga {i} non numerica: {ln!r}")
        import math
        if math.isnan(v) or math.isinf(v):
            raise ValueError(f"serie: riga {i} non finita")
        xs.append(v)
    if len(xs) < 20:
        raise ValueError(f"serie: servono almeno 20 valori "
                         f"(trovati {len(xs)})")
    return tuple(xs)


def mh429_equity(xs):
    """Equity composta dai rendimenti % (parte da 100.0), un valore
    per periodo."""
    if xs is None:
        raise ValueError("serve una sequenza di rendimenti")
    vs = tuple(mh429_num(x, "rendimento") for x in xs)
    if len(vs) < 20:
        raise ValueError("equity: servono almeno 20 valori")
    eq = 100.0
    out = []
    for x in vs:
        eq *= 1.0 + x / 100.0
        out.append(eq)
    return tuple(out)


def mh429_drawdowns(xs):
    """Drawdown % (magnitudine >= 0) dal running max dell'equity,
    un valore per periodo. Peak iniziale = 100.0 (stessa
    convenzione di tab424/tab427/tab428)."""
    eq = mh429_equity(xs)
    peak = 100.0
    out = []
    for e in eq:
        if e > peak:
            peak = e
        out.append((peak - e) / peak * 100.0)
    return tuple(out)


def mh429_worst(xs):
    """Episodio peggiore: picco -> minimo del drawdown massimo.
    Ritorna dict con peak_idx (indice 0-based dell'equity di
    picco, -1 = valore iniziale 100 prima della serie), trough_idx
    (indice 0-based del minimo), peak_per (periodo 1-based del
    picco, 0 = prima della serie), trough_per (periodo 1-based
    del minimo), max_dd, peak_eq (equity al picco).
    Se maxDD == 0 (mai sott'acqua): peak_idx = trough_idx = -1,
    peak_per = trough_per = 0, max_dd = 0.0, peak_eq = 100.0."""
    if xs is None:
        raise ValueError("serve una sequenza di rendimenti")
    vs = tuple(mh429_num(x, "rendimento") for x in xs)
    if len(vs) < 20:
        raise ValueError("worst: servono almeno 20 valori")
    eqs = mh429_equity(vs)
    dds = mh429_drawdowns(vs)
    max_dd = max(dds)
    if max_dd == 0.0:
        return {"peak_idx": -1, "trough_idx": -1, "peak_per": 0,
                "trough_per": 0, "max_dd": 0.0, "peak_eq": 100.0}
    trough = dds.index(max_dd)
    peak_idx = -1
    peak_eq = 100.0
    for i in range(trough + 1):
        if eqs[i] > peak_eq:
            peak_eq = eqs[i]
            peak_idx = i
    return {"peak_idx": peak_idx, "trough_idx": trough,
            "peak_per": peak_idx + 1, "trough_per": trough + 1,
            "max_dd": max_dd, "peak_eq": peak_eq}


def mh429_attribution(xs):
    """Attribuzione del peggior drawdown: dict con n, max_dd,
    peak_idx/trough_idx/peak_per/trough_per/peak_eq (da
    mh429_worst), n_attr (periodi con rendimento != 0 tra picco
    e minimo), contributi (tupla di dict con idx 0-based, per
    1-based, r rendimento %, quota % del calo, quota_cum %
    cumulata, dd_dopo % drawdown dopo il periodo rispetto al
    picco dell'episodio), top1 (quota massima), top1_idx,
    top1_per (periodo del peggior contributo), top3 (somma
    delle 3 quote causative maggiori), hhi (concentrazione
    HHI sulle quote causative), somma (somma quote = 100% se
    maxDD > 0, 0.0 altrimenti), n_caus (quote > 0), n_mit
    (quote < 0), mean, pain.
    Proprieta' (testate): somma quote == 100%; dd_dopo
    dell'ultimo contributo == maxDD; quota_cum finale == 100%;
    max_dd == maxDD di percorso."""
    if xs is None:
        raise ValueError("serve una sequenza di rendimenti")
    vs = tuple(mh429_num(x, "rendimento") for x in xs)
    if len(vs) < 20:
        raise ValueError("attribution: servono almeno 20 valori")
    import math
    dds = mh429_drawdowns(vs)
    n = len(dds)
    w = mh429_worst(vs)
    if w["max_dd"] == 0.0:
        return {"n": n, "max_dd": 0.0, "peak_idx": -1,
                "trough_idx": -1, "peak_per": 0, "trough_per": 0,
                "peak_eq": 100.0, "n_attr": 0, "contributi": (),
                "top1": 0.0, "top1_idx": None, "top1_per": None,
                "top3": 0.0, "hhi": 0.0, "somma": 0.0, "n_caus": 0,
                "n_mit": 0, "mean": sum(vs) / n,
                "pain": sum(dds) / n}
    seg = vs[w["peak_idx"] + 1: w["trough_idx"] + 1]
    for _r in seg:
        if _r <= -100.0:
            raise ValueError("attribution: rendimento <= -100% "
                             "(equity azzerata, log indefinito)")
    tot = math.log(1.0 - w["max_dd"] / 100.0)
    contribs = []
    eq = w["peak_eq"]
    cum = 0.0
    for _k, _r in enumerate(seg):
        if _r == 0.0:
            continue
        _q = math.log(1.0 + _r / 100.0) / tot * 100.0
        cum += _q
        eq *= 1.0 + _r / 100.0
        contribs.append({"idx": w["peak_idx"] + 1 + _k,
                         "per": w["peak_idx"] + 2 + _k,
                         "r": _r, "quota": _q, "quota_cum": cum,
                         "dd_dopo": (w["peak_eq"] - eq) / w["peak_eq"]
                         * 100.0})
    pos = sorted((c["quota"] for c in contribs if c["quota"] > 0.0),
                 reverse=True)
    _s = sum(pos)
    hhi = sum((_q / _s) ** 2 for _q in pos) if _s else 0.0
    top = max(contribs, key=lambda c: c["quota"])
    return {"n": n, "max_dd": w["max_dd"],
            "peak_idx": w["peak_idx"], "trough_idx": w["trough_idx"],
            "peak_per": w["peak_per"], "trough_per": w["trough_per"],
            "peak_eq": w["peak_eq"], "n_attr": len(contribs),
            "contributi": tuple(contribs), "top1": top["quota"],
            "top1_idx": top["idx"], "top1_per": top["per"],
            "top3": sum(pos[:3]), "hhi": hhi,
            "somma": sum(c["quota"] for c in contribs),
            "n_caus": sum(1 for c in contribs if c["quota"] > 0.0),
            "n_mit": sum(1 for c in contribs if c["quota"] < 0.0),
            "mean": sum(vs) / n, "pain": sum(dds) / n}


def mh429_verdetto(top1, soglia):
    """Verdetto a 6 stati sul rapporto r = top1 / soglia:
    top1 == 0 ROBUSTO, r < 0.5 DIFFUSA, r < 1.0 EQUILIBRATA,
    r < 1.5 CONCENTRATA, r < 1.8 MOLTO CONCENTRATA, r < 2.0
    DOMINATA, altrimenti MONO-EVENTO."""
    t = mh429_num(top1, "top1")
    if t < 0.0:
        raise ValueError("verdetto: top1 negativo")
    s = mh429_num(soglia, "soglia")
    if not 0.0 < s <= 100.0:
        raise ValueError("verdetto: soglia fuori (0, 100]")
    if t == 0.0:
        return ("ROBUSTO: nessun drawdown — nessun periodo ha "
                "causato alcun calo, niente da attribuire")
    r = t / s
    if r < 0.5:
        return (f"DIFFUSA: il peggior periodo spiega solo il "
                f"{t:.4f}% del calo (r={r:.2f} sulla soglia "
                f"{s:.1f}%) — il drawdown e' un'emorragia lenta, "
                f"non un singolo evento")
    if r < 1.0:
        return (f"EQUILIBRATA: il peggior periodo spiega il "
                f"{t:.4f}% del calo (r={r:.2f} sulla soglia "
                f"{s:.1f}%) — nessun giorno domina, ma i primi "
                f"pochi contano")
    if r < 1.5:
        return (f"CONCENTRATA: il peggior periodo spiega il "
                f"{t:.4f}% del calo (r={r:.2f} sulla soglia "
                f"{s:.1f}%) — un evento identificabile guida "
                f"il calo")
    if r < 1.8:
        return (f"MOLTO CONCENTRATA: il peggior periodo spiega "
                f"il {t:.4f}% del calo (r={r:.2f} sulla soglia "
                f"{s:.1f}%) — il calo ha un colpevole chiaro")
    if r < 2.0:
        return (f"DOMINATA: il peggior periodo spiega il "
                f"{t:.4f}% del calo (r={r:.2f} sulla soglia "
                f"{s:.1f}%) — quasi tutto il calo e' un solo "
                f"evento")
    return (f"MONO-EVENTO: il peggior periodo spiega il "
            f"{t:.4f}% del calo (r={r:.2f} sulla soglia "
            f"{s:.1f}%) — il calo E' un solo evento, il resto "
            f"e' rumore o rimbalzo")


def mh429_mappa(xs, soglia=50.0):
    """Mappa completa per la UI: attribuzione, soglia top1, verdetto."""
    if xs is None:
        raise ValueError("serve una sequenza di rendimenti")
    vs = tuple(mh429_num(x, "rendimento") for x in xs)
    if len(vs) < 20:
        raise ValueError("mappa: servono almeno 20 valori")
    attr = mh429_attribution(vs)
    s = mh429_num(soglia, "soglia")
    if not 0.0 < s <= 100.0:
        raise ValueError("mappa: soglia fuori (0, 100]")
    return {"n": len(vs), "attr": attr, "soglia": s,
            "verdetto": mh429_verdetto(attr["top1"], s)}
