def mh426_drawdowns(xs):
    """Drawdown % (magnitudine >= 0) dal running max dell'equity,
    un valore per periodo. Peak iniziale = 100.0 (stessa
    convenzione di tab424)."""
    eq = mh426_equity(xs)
    peak = 100.0
    out = []
    for e in eq:
        if e > peak:
            peak = e
        out.append((peak - e) / peak * 100.0)
    return tuple(out)


def mh426_path(xs):
    """Metriche di percorso di una sequenza: dict con mean (media
    % per periodo), max_dd, pain (media dei drawdown), ulcer (RMS
    dei drawdown), calmar (mean / max_dd; max_dd=0 -> +inf se
    mean>0, -inf se mean<0, 0.0 se mean==0), n. Proprieta'
    (testate): ulcer >= pain >= 0 (RMS >= AM) e max_dd >= pain."""
    if xs is None:
        raise ValueError("serve una sequenza di rendimenti")
    vs = tuple(mh426_num(x, "rendimento") for x in xs)
    if len(vs) < 20:
        raise ValueError("path: servono almeno 20 valori")
    import math
    dds = mh426_drawdowns(vs)
    n = len(dds)
    mean = sum(vs) / n
    max_dd = max(dds)
    pain = sum(dds) / n
    ulcer = math.sqrt(sum(d * d for d in dds) / n)
    if max_dd == 0.0:
        cal = math.inf if mean > 0.0 else (-math.inf if mean < 0.0 else 0.0)
    else:
        cal = mean / max_dd
    return {"mean": mean, "max_dd": max_dd, "pain": pain,
            "ulcer": ulcer, "calmar": cal, "n": n}


def mh426_bound(xs):
    """Bound superiore del maxDD su OGNI ordinamento: 1 - prod(1 +
    perdita_i) sulle sole perdite, in %. Raggiunto dagli
    ordinamenti 'tutti i guadagni poi tutte le perdite' e 'tutte
    le perdite poi tutti i guadagni' (chiave 1)."""
    if xs is None:
        raise ValueError("serve una sequenza di rendimenti")
    vs = tuple(mh426_num(x, "rendimento") for x in xs)
    if len(vs) < 20:
        raise ValueError("bound: servono almeno 20 valori")
    prod = 1.0
    for x in vs:
        if x < 0.0:
            prod *= 1.0 + x / 100.0
    return (1.0 - prod) * 100.0


def mh426_percentile(vals, p):
    """Percentile nearest-rank: vals ordinato crescente, p in
    [0, 100]. p=50 -> mediana."""
    pp = mh426_num(p, "percentile")
    if not 0.0 <= pp <= 100.0:
        raise ValueError("percentile: p fuori [0, 100]")
    import math
    if vals is None:
        raise ValueError("percentile: serve una lista di valori")
    sv = sorted(float(v) for v in vals)
    if not sv:
        raise ValueError("percentile: lista vuota")
    i = math.ceil(pp / 100.0 * len(sv)) - 1
    return sv[max(0, min(i, len(sv) - 1))]


def mh426_shuffle(xs, seed):
    """Una permutazione deterministica della serie: random.Random
    (seed).sample. Stesso seed -> stessa permutazione; la serie
    restituita ha lo stesso multiset (stessi momenti per-periodo)."""
    if xs is None:
        raise ValueError("serve una sequenza di rendimenti")
    vs = tuple(mh426_num(x, "rendimento") for x in xs)
    if len(vs) < 20:
        raise ValueError("shuffle: servono almeno 20 valori")
    if isinstance(seed, bool) or not isinstance(seed, int):
        raise ValueError("shuffle: seed deve essere un intero")
    import random
    return tuple(random.Random(seed).sample(list(vs), len(vs)))


def mh426_simulazione(xs, n_sim=200, soglia=30.0, seed_base=426000):
    """N shuffle deterministici (seed_base + i) e distribuzione
    delle metriche di percorso. Ritorna dict con n_sim, soglia,
    liste maxdds/pains/calmars, med/p5/p95/min/max/mean dei maxDD,
    med/p95 del pain, p_gt_soglia (frazione di shuffle con
    maxDD > soglia), worst (i 5 shuffle peggiori per maxDD, con
    seed/max_dd/pain/calmar), sims (tutte le righe per export CSV).
    Deterministica: stessi input -> stessi output."""
    if xs is None:
        raise ValueError("serve una sequenza di rendimenti")
    vs = tuple(mh426_num(x, "rendimento") for x in xs)
    if len(vs) < 20:
        raise ValueError("simulazione: servono almeno 20 valori")
    if isinstance(n_sim, bool) or not isinstance(n_sim, int):
        raise ValueError("simulazione: n_sim deve essere un intero")
    if not 10 <= n_sim <= 2000:
        raise ValueError("simulazione: n_sim fuori [10, 2000]")
    s = mh426_num(soglia, "soglia")
    if not 0.0 <= s <= 100.0:
        raise ValueError("simulazione: soglia fuori [0, 100]")
    if isinstance(seed_base, bool) or not isinstance(seed_base, int):
        raise ValueError("simulazione: seed_base deve essere un intero")
    sims = []
    for i in range(n_sim):
        seed = seed_base + i
        m = mh426_path(mh426_shuffle(vs, seed))
        sims.append({"seed": seed, "max_dd": m["max_dd"],
                     "pain": m["pain"], "ulcer": m["ulcer"],
                     "calmar": m["calmar"]})
    maxdds = [r["max_dd"] for r in sims]
    pains = [r["pain"] for r in sims]
    ulcers = [r["ulcer"] for r in sims]
    worst = sorted(sims, key=lambda r: -r["max_dd"])[:5]
    return {"n_sim": n_sim, "soglia": s,
            "maxdds": maxdds, "pains": pains,
            "calmars": [r["calmar"] for r in sims],
            "med_maxdd": mh426_percentile(maxdds, 50),
            "p5_maxdd": mh426_percentile(maxdds, 5),
            "p95_maxdd": mh426_percentile(maxdds, 95),
            "min_maxdd": min(maxdds), "max_maxdd": max(maxdds),
            "mean_maxdd": sum(maxdds) / len(maxdds),
            "med_pain": mh426_percentile(pains, 50),
            "p95_pain": mh426_percentile(pains, 95),
            "med_ulcer": mh426_percentile(ulcers, 50),
            "p_gt_soglia": sum(1 for v in maxdds if v > s) / len(maxdds),
            "worst": worst, "sims": sims}


def mh426_verdetto(p_gt):
    """Verdetto a 6 stati su P(maxDD > soglia) negli shuffle:
    0 ROBUSTO, <10% CONTROLLATO, <25% SENSIBILE, <50% FRAGILE,
    <75% MOLTO FRAGILE, altrimenti CRITICO."""
    p = mh426_num(p_gt, "p_gt_soglia")
    if not 0.0 <= p <= 1.0:
        raise ValueError("verdetto: p fuori [0, 1]")
    pct = p * 100.0
    if p == 0.0:
        return ("ROBUSTO: nessuno shuffle supera la soglia di maxDD "
                "(0.0%) — l'ordine dei rendimenti non puo' farti male")
    if p < 0.10:
        return (f"CONTROLLATO: solo il {pct:.1f}% degli ordinamenti "
                f"supera la soglia di maxDD — il rischio di sequenza "
                f"e' contenuto")
    if p < 0.25:
        return (f"SENSIBILE: il {pct:.1f}% degli ordinamenti supera "
                f"la soglia di maxDD — l'ordine conta, attento al "
                f"timing del crash")
    if p < 0.50:
        return (f"FRAGILE: il {pct:.1f}% degli ordinamenti supera la "
                f"soglia di maxDD — quasi un lancio di moneta sul "
                f"timing del crash")
    if p < 0.75:
        return (f"MOLTO FRAGILE: il {pct:.1f}% degli ordinamenti "
                f"supera la soglia di maxDD — il drawdown dipende "
                f"quasi solo dalla fortuna dell'ordine")
    return (f"CRITICO: il {pct:.1f}% degli ordinamenti supera la "
            f"soglia di maxDD — il drawdown e' quasi certo "
            f"qualunque sia l'ordine")


def mh426_mappa(xs, n_sim=200, soglia=30.0, seed_base=426000):
    """Mappa completa per la UI: demo (path + bound), simulazione,
    ordinamenti estremi asc/desc, verdetto. Demo e' l'ordinamento
    'guadagni poi perdite' -> il suo maxDD E' il bound."""
    if xs is None:
        raise ValueError("serve una sequenza di rendimenti")
    vs = tuple(mh426_num(x, "rendimento") for x in xs)
    if len(vs) < 20:
        raise ValueError("mappa: servono almeno 20 valori")
    demo = mh426_path(vs)
    sim = mh426_simulazione(vs, n_sim, soglia, seed_base)
    asc = mh426_path(tuple(sorted(vs)))
    desc = mh426_path(tuple(sorted(vs, reverse=True)))
    bnd = mh426_bound(vs)
    return {"n": len(vs), "demo": demo, "bound": bnd,
            "sim": sim, "asc": asc, "desc": desc,
            "p_gt_soglia": sim["p_gt_soglia"],
            "verdetto": mh426_verdetto(sim["p_gt_soglia"])}
def mh425_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh425_parse_serie(txt):
    """Una riga = un rendimento %; la virgola vale come decimale."""
    if not isinstance(txt, str):
        raise ValueError("serie: serve testo, un valore per riga")
    xs = []
    for i, ln in enumerate(txt.split("\n"), 1):
        s = ln.strip().replace(",", ".")
        if not s:
            continue
        try:
            v = float(s)
        except ValueError:
            raise ValueError(f"serie: riga {i} non numerica: {ln!r}")
        import math
        if math.isnan(v) or math.isinf(v):
            raise ValueError(f"serie: riga {i} non finita")
        xs.append(v)
    if len(xs) < 20:
        raise ValueError(f"serie: servono almeno 20 valori "
                         f"(trovati {len(xs)})")
    return tuple(xs)


def mh425_updown(xs):
    """Scomposizione per-periodo contro la soglia T=0 implicita nei
    rendimenti gia' in eccesso: ritorna dict con up (E[max(r,0)] =
    guadagno atteso), dd (downside deviation = RMS di max(-r,0)),
    e_loss (E[max(-r,0)] = perdita attesa, per il confronto con il
    Gain-Loss tab420), n_up, n_dn, n. Proprieta' (testate):
    dd >= e_loss >= 0 (RMS >= AM) e dd >= 0."""
    vs = tuple(mh425_num(x, "rendimento") for x in xs)
    if len(vs) < 20:
        raise ValueError("updown: servono almeno 20 valori")
    import math
    n = len(vs)
    ups = [x for x in vs if x > 0.0]
    dns = [-x for x in vs if x < 0.0]
    up = sum(ups) / n
    e_loss = sum(dns) / n
    dd = math.sqrt(sum(d * d for d in dns) / n)
    return {"up": up, "dd": dd, "e_loss": e_loss,
            "n_up": len(ups), "n_dn": len(dns), "n": n}


def mh425_ratio(xs, target):
    """Upside Potential ratio = E[max(R-T,0)] / DD(T).

    xs: sequenza di rendimenti % (almeno 20). target: T in %.
    Ritorna dict con upr, up, dd, e_loss, n_up, n_dn, n, target.
    dd=0 & up>0 (mai sotto la soglia) -> upr=+inf; dd=0 & up=0
    (serie piatta sulla soglia) -> ValueError; up=0 & dd>0 ->
    upr=0.0. upr >= 0 sempre (-inf impossibile).
    """
    if xs is None:
        raise ValueError("upr: serve una sequenza di rendimenti")
    vs = tuple(mh425_num(x, "rendimento") for x in xs)
    if len(vs) < 20:
        raise ValueError("upr: servono almeno 20 valori")
    import math
    T = mh425_num(target, "target")
    n = len(vs)
    ups = [x - T for x in vs if x > T]
    dns = [T - x for x in vs if x < T]
    up = sum(ups) / n
    dd = math.sqrt(sum(d * d for d in dns) / n)
    e_loss = sum(dns) / n
    if dd == 0.0:
        if up > 0.0:
            u = math.inf
        else:
            raise ValueError("upr: serie piatta sulla soglia, rapporto "
                             "non definito")
    else:
        u = up / dd
    return {"upr": u, "up": up, "dd": dd, "e_loss": e_loss,
            "n_up": len(ups), "n_dn": len(dns), "n": n, "target": T}


def mh425_verdetto(upr):
    """Verdetto a 6 stati, breakeven 1.0 (stessa scala di tab418-424).
    +inf (mai sotto la soglia) -> MOLTO FORTE; NaN/bool ->
    ValueError. upr >= 0 sempre: -inf non puo' capitare."""
    import math
    if isinstance(upr, bool):
        raise ValueError("verdetto: serve un numero")
    if upr == math.inf:
        return ("MOLTO FORTE: UPR >= 5.0 — il potenziale di guadagno "
                "e' molto superiore al rischio al ribasso (o nessun "
                "downside).")
    r = float(upr)
    if math.isnan(r):
        raise ValueError("verdetto: NaN non ammesso")
    if r < 0.0:
        raise ValueError("verdetto: UPR negativo impossibile")
    if r < 1.0:
        return ("NEGATIVO: l'UPR e' sotto 1.0 — la downside deviation "
                "mangia il potenziale di guadagno: il rischio al "
                "ribasso costa piu' di quanto rende l'upside.")
    if r < 1.5:
        return ("DEBOLE: UPR tra 1.0 e 1.5 — potenziale di guadagno "
                "appena sopra il rischio al ribasso, cuscinetto minimo.")
    if r < 2.0:
        return ("ACCETTABILE: UPR tra 1.5 e 2.0 — ogni punto di "
                "downside deviation rende da uno e mezzo a due punti "
                "di guadagno atteso.")
    if r < 3.0:
        return ("BUONO: UPR tra 2.0 e 3.0 — il potenziale di guadagno "
                "compensa bene il rischio al ribasso.")
    if r < 5.0:
        return ("FORTE: UPR tra 3.0 e 5.0 — rischio al ribasso "
                "contenuto rispetto al potenziale di guadagno.")
    return ("MOLTO FORTE: UPR >= 5.0 — il potenziale di guadagno "
            "e' molto superiore al rischio al ribasso (o nessun "
            "downside).")


def mh425_curva(xs, tmin=-5.0, tmax=5.0, step=0.5):
    """UPR al variare del target T: lista di (T, u|None).
    None = non definito (serie piatta sulla soglia) o |u| infinito."""
    if xs is None:
        raise ValueError("curva: serve una sequenza di rendimenti")
    a = mh425_num(tmin, "tmin")
    b = mh425_num(tmax, "tmax")
    s = mh425_num(step, "step")
    if a > b:
        raise ValueError("curva: tmin deve essere <= tmax")
    if s <= 0.0:
        raise ValueError("curva: step deve essere > 0")
    import math
    out = []
    T = a
    while T <= b + 1e-12:
        Tr = round(T, 10)
        try:
            u = mh425_ratio(xs, Tr)["upr"]
            out.append((Tr, None if math.isinf(u) else u))
        except ValueError:
            out.append((Tr, None))
        T += s
    return out


def mh425_mappa(xs, target=0.0):
    """Wrapper UI: accetta testo grezzo o tupla; dict pronto per le
    metriche, con upr, up, dd, e_loss, n_up, n_dn, verdetto, n,
    target, piu' gain_loss (cross-check tab420: UPR <= GL per
    RMS >= AM) e ft21 (cross-check tab417: UPR = FT_{1,2})."""
    if xs is None:
        raise ValueError("mappa: serve una serie di rendimenti")
    _xs = mh425_parse_serie(xs) if isinstance(xs, str) else tuple(
        mh425_num(x, "rendimento") for x in xs)
    k = mh425_ratio(_xs, target)
    k["verdetto"] = mh425_verdetto(k["upr"])
    k["gain_loss"] = mh420_gain_loss(_xs)["gl"] if target == 0.0 else None
    k["ft21"] = mh417_ft(_xs, target, 1, 2)["upr"]
    return k

