def mh423_maxdd(xs):
    """Peggior drawdown: dict con max_dd, worst_i (periodo 1-based
    del picco di drawdown), mean_dd, n_dd (periodi in drawdown), n.
    Proprieta' (testate): max_dd >= mean_dd."""
    vs = tuple(mh423_num(x, "rendimento") for x in xs)
    if len(vs) < 20:
        raise ValueError("maxdd: servono almeno 20 valori")
    dds = mh423_drawdowns(vs)
    m = max(dds)
    return {"max_dd": m,
            "worst_i": dds.index(m) + 1,
            "mean_dd": sum(dds) / len(dds),
            "n_dd": sum(1 for d in dds if d > 0.0),
            "n": len(dds)}


def mh423_cagr(xs):
    """CAGR per periodo in % dall'equity composta: dict con cagr,
    eq_finale, n. CAGR = (E_n/100)^(1/n) - 1.
    Rendimento < -100% (fattore negativo) -> ValueError (come
    tab411); E_n = 0 (perdita totale) -> cagr = -100.0.
    Proprieta' (testate): cagr <= media aritmetica (AM >= GM sui
    fattori 1+r/100 > 0), uguaglianza sse rendimenti costanti."""
    vs = tuple(mh423_num(x, "rendimento") for x in xs)
    if len(vs) < 20:
        raise ValueError("cagr: servono almeno 20 valori")
    import math
    eq = 100.0
    for x in vs:
        f = 1.0 + x / 100.0
        if f < 0.0:
            raise ValueError("cagr: rendimento < -100% non ammesso")
        eq *= f
    n = len(vs)
    if eq <= 0.0:
        cagr = -100.0
    else:
        cagr = (math.pow(eq / 100.0, 1.0 / n) - 1.0) * 100.0
    return {"cagr": cagr, "eq_finale": eq, "n": n}


def mh423_mar(xs, target):
    """MAR ratio = (CAGR - T) / maxDD.

    xs: sequenza di rendimenti % (almeno 20). target: T in %.
    Ritorna dict con mar, cagr, mean, excess, max_dd, worst_i,
    mean_dd, n_dd, n, target. maxDD=0 & excess=0 (serie piatta) ->
    ValueError; maxDD=0 & excess>0 -> mar=+inf; maxDD=0 &
    excess<0 -> mar=-inf.
    """
    if xs is None:
        raise ValueError("mar: serve una sequenza di rendimenti")
    vs = tuple(mh423_num(x, "rendimento") for x in xs)
    if len(vs) < 20:
        raise ValueError("mar: servono almeno 20 valori")
    import math
    T = mh423_num(target, "target")
    u = mh423_maxdd(vs)
    g = mh423_cagr(vs)["cagr"]
    mean = sum(vs) / len(vs)
    exc = g - T
    if u["max_dd"] == 0.0:
        if exc > 0.0:
            mar = math.inf
        elif exc < 0.0:
            mar = -math.inf
        else:
            raise ValueError("mar: serie piatta, rapporto non "
                             "definito")
    else:
        mar = exc / u["max_dd"]
    return {"mar": mar, "cagr": g, "mean": mean, "excess": exc,
            "max_dd": u["max_dd"], "worst_i": u["worst_i"],
            "mean_dd": u["mean_dd"], "n_dd": u["n_dd"],
            "n": len(vs), "target": T}


