def mh417_upm(vs, soglia, p):
    """Upper partial moment di ordine p contro la soglia.

    UPM_p(T) = media(max(r-T, 0)^p). p = intero in [1, 6]: ordini piu'
    alti premiano di piu' l'upside (norma L^p crescente in p su misura
    di probabilita'). Solleva ValueError per p non intero o fuori
    [1, 6] e per sequenze con meno di 20 valori.
    """
    if vs is None:
        raise ValueError("upm: serve una sequenza di rendimenti")
    T = mh417_num(soglia, "soglia")
    _p = mh417_num(p, "ordine p")
    if _p != int(_p) or not 1 <= _p <= 6:
        raise ValueError("upm: p deve essere un intero in [1, 6] "
                         "(premia l'upside: ordini alti, code destre)")
    xs = tuple(mh417_num(x, "rendimento") for x in vs)
    if len(xs) < 20:
        raise ValueError("upm: servono almeno 20 valori")
    P = int(_p)
    return sum(max(r - T, 0.0) ** P for r in xs) / len(xs)


def mh417_lpm(vs, soglia, q):
    """Lower partial moment di ordine q contro la soglia.

    LPM_q(T) = media(max(T-r, 0)^q). q = intero in [1, 6]: ordini piu'
    alti puniscono di piu' il downside. Solleva ValueError per q non
    intero o fuori [1, 6] e per sequenze con meno di 20 valori.
    """
    if vs is None:
        raise ValueError("lpm: serve una sequenza di rendimenti")
    T = mh417_num(soglia, "soglia")
    _q = mh417_num(q, "ordine q")
    if _q != int(_q) or not 1 <= _q <= 6:
        raise ValueError("lpm: q deve essere un intero in [1, 6] "
                         "(punisce il downside: ordini alti, code)")
    xs = tuple(mh417_num(x, "rendimento") for x in vs)
    if len(xs) < 20:
        raise ValueError("lpm: servono almeno 20 valori")
    Q = int(_q)
    return sum(max(T - r, 0.0) ** Q for r in xs) / len(xs)


def mh417_ft(xs, soglia=0.0, p=1, q=2):
    """FT_{p,q} = UPM_p(T)^(1/p) / LPM_q(T)^(1/q) contro la soglia T.

    Ritorna p, q, soglia, media, excess, upm_p, upm_1, lpm_q, lpm_1,
    up_pot, down_pot, ft (all'ordine p, q), ft11 (= Omega, cross-check
    tab412), upr (= FT_{1,2} = upside/downside deviation = Upside
    potential ratio), omega (= ft11), p_sopra. ft=+inf se down_pot=0 ed
    up_pot>0 (nessun downside: profilo tutto sopra la soglia);
    ValueError se la serie e' piatta sulla soglia (FT non definito).
    """
    import math
    if xs is None:
        raise ValueError("ft: serve una sequenza di rendimenti")
    T = mh417_num(soglia, "soglia")
    _p = mh417_num(p, "ordine p")
    _q = mh417_num(q, "ordine q")
    if _p != int(_p) or not 1 <= _p <= 6:
        raise ValueError("ft: p deve essere un intero in [1, 6]")
    if _q != int(_q) or not 1 <= _q <= 6:
        raise ValueError("ft: q deve essere un intero in [1, 6]")
    vs = tuple(mh417_num(x, "rendimento") for x in xs)
    if len(vs) < 20:
        raise ValueError("ft: servono almeno 20 valori")
    P, Q = int(_p), int(_q)
    m = len(vs)
    media = sum(vs) / m
    exc = media - T
    ups = [r - T if r > T else 0.0 for r in vs]
    dns = [T - r if r < T else 0.0 for r in vs]
    su = sum(ups)
    sd = sum(dns)
    if su == 0.0 and sd == 0.0:
        raise ValueError("ft: serie piatta sulla soglia, "
                         "Farinelli-Tibiletti non definito")
    upm_p = sum(u ** P for u in ups) / m
    upm_1 = su / m
    lpm_q = sum(d ** Q for d in dns) / m
    lpm_1 = sd / m
    up_pot = upm_p ** (1.0 / P)
    down_pot = lpm_q ** (1.0 / Q) if lpm_q > 0.0 else 0.0
    if down_pot == 0.0:
        ftv = math.inf
    else:
        ftv = up_pot / down_pot
    ft11 = (upm_1 / lpm_1) if lpm_1 > 0.0 else math.inf
    dd = math.sqrt(sum(d ** 2 for d in dns) / m)
    upr = upm_1 / dd if dd > 0.0 else math.inf
    n_up = sum(1 for r in vs if r > T)
    return {"p": P, "q": Q, "soglia": T, "media": media, "excess": exc,
            "upm_p": upm_p, "upm_1": upm_1, "lpm_q": lpm_q,
            "lpm_1": lpm_1, "up_pot": up_pot, "down_pot": down_pot,
            "ft": ftv, "ft11": ft11, "upr": upr, "omega": ft11,
            "p_sopra": n_up / m}


def mh417_verdetto(ft):
    """Verdetto a 6 stati sul Farinelli-Tibiletti (scala Omega-family)."""
    import numbers
    import math
    if isinstance(ft, bool) or not isinstance(ft, numbers.Real):
        raise ValueError("verdetto: serve FT come numero")
    if math.isnan(ft):
        raise ValueError("verdetto: NaN non ammesso")
    F = float(ft)
    if F < 1.0:
        stato = (f"NEGATIVO - FT={F:.2f}: il downside potential domina "
                 f"l'upside (breakeven 1.0). Il profilo paga piu' rischio "
                 f"di coda di quanto l'upside compensi: la soglia T e' "
                 f"troppo ambiziosa o le code troppo grasse.")
    elif F < 1.50:
        stato = (f"DEBOLE - FT={F:.2f}: upside appena sopra il downside "
                 f"(1.0-1.5). Il margine e' sottile: basta punire un po' "
                 f"di piu' il downside (q piu' alto) e la metrica crolla "
                 f"sotto 1.")
    elif F < 2.0:
        stato = (f"ACCETTABILE - FT={F:.2f}: l'upside potential regge al "
                 f"downside di ordine q, ma il cuscinetto e' modesto: le "
                 f"code contano piu' della media.")
    elif F < 3.0:
        stato = (f"BUONO - FT={F:.2f}: upside nettamente sopra il "
                 f"downside di ordine q. Il profilo paga il rischio di "
                 f"coda con margine.")
    elif F < 5.0:
        stato = (f"FORTE - FT={F:.2f}: l'upside domina il downside di "
                 f"oltre 3 volte. Asimmetria favorevole anche punendo le "
                 f"code con q alto.")
    else:
        stato = (f"MOLTO FORTE - FT={F:.2f}: upside schiacciante sul "
                 f"downside. Verificare comunque che la serie non sia "
                 f"cherry-picked prima di allocare capitale.")
    return stato


def mh417_mappa(xs, soglia=0.0, p=1, q=2):
    """Pipeline completa: serie -> FT_{p,q} + verdetto."""
    if xs is None:
        raise ValueError("mappa: serve una sequenza di rendimenti")
    _xs = mh417_parse_serie(xs) if isinstance(xs, str) else tuple(
        mh417_num(x, "rendimento") for x in xs)
    if len(_xs) < 20:
        raise ValueError("mappa: servono almeno 20 valori")
    k = mh417_ft(_xs, soglia, p, q)
    out = dict(k)
    out["verdetto"] = mh417_verdetto(k["ft"])
    return out

