def mh416_lpm(vs, soglia, n):
    """Lower partial moment di ordine n contro la soglia.

    LPM_n(T) = media(max(T-r, 0)^n). n = intero in [1, 6]: ordini piu'
    alti pesano esponenzialmente le code (n=1 downside atteso, n=2
    varianza del downside). Solleva ValueError per n non intero o fuori
    [1, 6] e per sequenze con meno di 20 valori.
    """
    if vs is None:
        raise ValueError("lpm: serve una sequenza di rendimenti")
    T = mh416_num(soglia, "soglia")
    _n = mh416_num(n, "ordine n")
    if _n != int(_n) or not 1 <= _n <= 6:
        raise ValueError("lpm: n deve essere un intero in [1, 6] "
                         "(ordini 1..6: oltre, le code dominano tutto)")
    xs = tuple(mh416_num(x, "rendimento") for x in vs)
    if len(xs) < 20:
        raise ValueError("lpm: servono almeno 20 valori")
    N = int(_n)
    return sum(max(T - r, 0.0) ** N for r in xs) / len(xs)


def mh416_kappa(xs, soglia=0.0, n=2):
    """Kappa_n = E[r-T] / LPM_n(T)^(1/n) contro la soglia T.

    Ritorna n, soglia, media, excess, upside, downside (= LPM_1),
    lpm_n, downside_dev (sqrt(LPM_2)), kappa (all'ordine n), kappa1
    (= Omega-1, cross-check tab412), kappa2 (= Sortino), omega
    (= kappa1+1), p_sopra. kappa=+inf se LPM_n=0 ed excess>0 (nessun
    downside: profilo tutto sopra la soglia); ValueError se la serie e'
    piatta sulla soglia (Kappa non definito).
    """
    import math
    if xs is None:
        raise ValueError("kappa: serve una sequenza di rendimenti")
    T = mh416_num(soglia, "soglia")
    _n = mh416_num(n, "ordine n")
    if _n != int(_n) or not 1 <= _n <= 6:
        raise ValueError("kappa: n deve essere un intero in [1, 6]")
    vs = tuple(mh416_num(x, "rendimento") for x in xs)
    if len(vs) < 20:
        raise ValueError("kappa: servono almeno 20 valori")
    N = int(_n)
    m = len(vs)
    media = sum(vs) / m
    exc = media - T
    ups = [r - T if r > T else 0.0 for r in vs]
    dns = [T - r if r < T else 0.0 for r in vs]
    su = sum(ups)
    sd = sum(dns)
    if su == 0.0 and sd == 0.0:
        raise ValueError("kappa: serie piatta sulla soglia, "
                         "Kappa non definito")
    lpm_n = sum(d ** N for d in dns) / m
    lpm_1 = sd / m
    lpm_2 = sum(d ** 2 for d in dns) / m
    if lpm_n == 0.0:
        kap = math.inf
    else:
        kap = exc / (lpm_n ** (1.0 / N))
    k1 = (su - sd) / sd if sd > 0.0 else math.inf
    dd = math.sqrt(lpm_2)
    k2 = exc / dd if dd > 0.0 else math.inf
    om = k1 + 1.0
    n_up = sum(1 for r in vs if r > T)
    return {"n": N, "soglia": T, "media": media, "excess": exc,
            "upside": su / m, "downside": lpm_1, "lpm_n": lpm_n,
            "downside_dev": dd, "kappa": kap, "kappa1": k1, "kappa2": k2,
            "omega": om, "p_sopra": n_up / m}


def mh416_verdetto(kappa):
    """Verdetto a 6 stati sul Kappa_n."""
    import numbers
    import math
    if isinstance(kappa, bool) or not isinstance(kappa, numbers.Real):
        raise ValueError("verdetto: serve Kappa come numero")
    if math.isnan(kappa):
        raise ValueError("verdetto: NaN non ammesso")
    K = float(kappa)
    if K < 0.0:
        stato = (f"NEGATIVO - Kappa={K:.2f}: l'excess atteso contro la "
                 f"soglia e' negativo. Il profilo distrugge valore anche "
                 f"prima di guardare le code.")
    elif K < 0.50:
        stato = (f"DEBOLE - Kappa={K:.2f}: excess positivo ma il downside "
                 f"di ordine n lo mangia quasi tutto. Poco meglio di una "
                 f"moneta corretta per le code.")
    elif K < 1.0:
        stato = (f"ACCETTABILE - Kappa={K:.2f}: l'excess atteso regge al "
                 f"downside di ordine n, ma il margine e' sottile: le code "
                 f"contano piu' della media.")
    elif K < 2.0:
        stato = (f"BUONO - Kappa={K:.2f}: excess solido contro il downside "
                 f"di ordine n. Il profilo paga il rischio di coda.")
    elif K < 3.0:
        stato = (f"FORTE - Kappa={K:.2f}: l'excess domina il downside di "
                 f"ordine n di oltre 2 volte. Asimmetria favorevole anche "
                 f"penalizzando le code.")
    else:
        stato = (f"MOLTO FORTE - Kappa={K:.2f}: excess schiacciante sul "
                 f"downside di ordine n. Verificare comunque che la serie "
                 f"non sia cherry-picked prima di allocare capitale.")
    return stato


def mh416_mappa(xs, soglia=0.0, n=2):
    """Pipeline completa: serie -> Kappa_n + verdetto."""
    if xs is None:
        raise ValueError("mappa: serve una sequenza di rendimenti")
    _xs = mh416_parse_serie(xs) if isinstance(xs, str) else tuple(
        mh416_num(x, "rendimento") for x in xs)
    if len(_xs) < 20:
        raise ValueError("mappa: servono almeno 20 valori")
    k = mh416_kappa(_xs, soglia, n)
    out = dict(k)
    out["verdetto"] = mh416_verdetto(k["kappa"])
    return out

def mh415_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh415_parse_serie(txt):
    """Una riga = un rendimento %; la virgola vale come decimale."""
    if not isinstance(txt, str):
        raise ValueError("serie: serve testo, un valore per riga")
    xs = []
    for i, ln in enumerate(txt.split("\n"), 1):
        s = ln.strip().replace(",", ".")
        if not s:
            continue
        try:
            v = float(s)
        except ValueError:
            raise ValueError(f"serie: riga {i} non numerica: {ln!r}")
        import math
        if math.isnan(v) or math.isinf(v):
            raise ValueError(f"serie: riga {i} non finita")
        xs.append(v)
    if len(xs) < 20:
        raise ValueError(f"serie: servono almeno 20 valori "
                         f"(trovati {len(xs)})")
    return tuple(xs)


def mh415_phi(z):
    """CDF della normale standard via erf."""
    import math
    _z = mh415_num(z, "z")
    return 0.5 * (1.0 + math.erf(_z / math.sqrt(2.0)))


def mh415_ppf(p):
    """Quantile della normale standard via bisezione su mh415_phi.

    Solleva ValueError per p fuori (0, 1): ai bordi il quantile e'
    +-inf, quindi non e' un numero finito utilizzabile.
    """
    _p = mh415_num(p, "probabilita'")
    if not 0.0 < _p < 1.0:
        raise ValueError("ppf: p deve stare in (0, 1) "
                         "(agli estremi il quantile e' +-inf)")
    _lo, _hi = -12.0, 12.0
    for _ in range(120):
        _mid = 0.5 * (_lo + _hi)
        if mh415_phi(_mid) < _p:
            _lo = _mid
        else:
            _hi = _mid
    return 0.5 * (_lo + _hi)


def mh415_stats(xs, rf=0.0):
    """Momenti della serie di rendimenti % (excess = r - rf).

    skew e curtosi = momenti centrali di POPOLAZIONE; curtosi NON in
    eccesso (curt_ecc = curtosi - 3); std = campionaria (ddof=1) per lo
    Sharpe. Solleva ValueError se std=0 (Sharpe non definito) o n<20.
    """
    import math
    if xs is None:
        raise ValueError("stats: serve una sequenza di rendimenti")
    R = mh415_num(rf, "risk-free")
    vs = tuple(mh415_num(x, "rendimento") for x in xs)
    if len(vs) < 20:
        raise ValueError("stats: servono almeno 20 valori")
    n = len(vs)
    exc = [v - R for v in vs]
    media = sum(exc) / n
    ss = sum((e - media) ** 2 for e in exc)
    if ss <= 0.0:
        raise ValueError("stats: serie piatta, Sharpe non definito")
    vpop = ss / n
    std = math.sqrt(ss / (n - 1))
    skew = (sum((e - media) ** 3 for e in exc) / n) / (vpop ** 1.5)
    kurt = (sum((e - media) ** 4 for e in exc) / n) / (vpop ** 2)
    return {"n": n, "rf": R, "media": media, "std": std,
            "skew": skew, "kurt_ecc": kurt - 3.0, "kurt": kurt,
            "sharpe": media / std, "exc": tuple(exc)}


def mh415_sigma2(skew, kurt, sharpe):
    """Varianza stimata dello Sharpe corretta per skew/curtosi.

    sigma_SR^2 = 1 - skew*SR + ((curtosi-1)/4)*SR^2, con curtosi di
    popolazione (NON in eccesso). Solleva ValueError se <= 0 (momenti
    estremi: la stima non e' affidabile).
    """
    _sk = mh415_num(skew, "skew")
    _ku = mh415_num(kurt, "curtosi")
    _sr = mh415_num(sharpe, "sharpe")
    s2 = 1.0 - _sk * _sr + ((_ku - 1.0) / 4.0) * _sr ** 2
    if not s2 > 0.0:
        raise ValueError("sigma2: varianza stimata dello Sharpe <= 0 "
                         "(momenti estremi, serie inaffidabile)")
    return s2


def mh415_e0(k, v):
    """Sharpe atteso sotto l'ipotesi nulla (False Strategy Theorem).

    E[SR_0] = sqrt(V)*((1-gamma)*Phi^-1(1-1/K) + gamma*Phi^-1(1-1/(K*e))),
    gamma = costante di Eulero-Mascheroni ~0.5772156649 (inline: appfuncs
    estrae solo FunctionDef, niente globali di modulo). K = numero di
    backtest (intero >= 2), V = varianza dei K Sharpe osservati (>= 0).
    """
    import math
    _k = mh415_num(k, "numero backtest K")
    if _k != int(_k) or _k < 2:
        raise ValueError("e0: K deve essere un intero >= 2 "
                         "(con un solo trial non c'e' selection bias)")
    _v = mh415_num(v, "varianza V")
    if _v < 0.0:
        raise ValueError("e0: V deve essere >= 0")
    K = int(_k)
    _gam = 0.5772156649015329
    _q1 = mh415_ppf(1.0 - 1.0 / K)
    _q2 = mh415_ppf(1.0 - 1.0 / (K * math.e))
    return math.sqrt(_v) * ((1.0 - _gam) * _q1 + _gam * _q2)


def mh415_dsr_da_stat(s, k, v, sr0=0.0):
    """DSR da un dict di mh415_stats + K, V, hurdle SR0.

    Ritorna K, V, e0, sigma2, sigma, z, dsr, z_psr e psr (PSR single-trial
    con lo stesso hurdle, per confronto), haircut_pp = (psr - dsr)*100
    (confidenza mangiata dai backtest multipli) e bias_ratio =
    e0/(SR-SR0) (frazione dello Sharpe spiegata dal selection bias; +inf
    se SR <= SR0).
    """
    import math
    if not isinstance(s, dict):
        raise ValueError("dsr_da_stat: serve il dict di mh415_stats")
    for _k in ("n", "sharpe", "skew", "kurt"):
        if _k not in s:
            raise ValueError(f"dsr_da_stat: manca {_k} nelle stats")
    S0 = mh415_num(sr0, "hurdle SR0")
    sr = float(s["sharpe"])
    n = int(s["n"])
    _e0 = mh415_e0(k, v)
    s2 = mh415_sigma2(s["skew"], s["kurt"], sr)
    sig = math.sqrt(s2)
    z = (sr - S0 - _e0) * math.sqrt(n - 1) / sig
    z_p = (sr - S0) * math.sqrt(n - 1) / sig
    p = mh415_phi(z)
    p_p = mh415_phi(z_p)
    if sr > S0:
        bias = _e0 / (sr - S0)
    else:
        bias = float("inf")
    return {"sr0": S0, "k": k, "v": v, "e0": _e0, "sigma2": s2,
            "sigma": sig, "z": z, "dsr": p, "z_psr": z_p, "psr": p_p,
            "haircut_pp": (p_p - p) * 100.0, "bias_ratio": bias}


def mh415_verdetto(dsr):
    """Verdetto a 6 stati sul DSR."""
    import numbers
    import math
    if isinstance(dsr, bool) or not isinstance(dsr, numbers.Real):
        raise ValueError("verdetto: serve il DSR come numero")
    if math.isnan(dsr):
        raise ValueError("verdetto: NaN non ammesso")
    P = float(dsr)
    if P < 0.50:
        stato = (f"NON SIGNIFICATIVO - DSR={P:.2f}: dopo K backtest non "
                 f"si puo' escludere che il vero Sharpe stia sotto "
                 f"l'hurdle. Il selection bias mangia lo Sharpe "
                 f"osservato: non allocare capitale.")
    elif P < 0.75:
        stato = (f"DEBOLE - DSR={P:.2f}: evidenza debole anche al netto "
                 f"dei backtest multipli, poco meglio di una moneta "
                 f"corretta per le code.")
    elif P < 0.90:
        stato = (f"ACCETTABILE - DSR={P:.2f}: il vero Sharpe batte "
                 f"probabilmente l'hurdle anche al netto del selection "
                 f"bias, ma il 95% e' lontano.")
    elif P < 0.95:
        stato = (f"BUONO - DSR={P:.2f}: evidenza solida al netto dei "
                 f"backtest multipli, vicino alla soglia di "
                 f"significativita' del 95%.")
    elif P < 0.99:
        stato = (f"FORTE - DSR={P:.2f}: il vero Sharpe batte l'hurdle "
                 f"con confidenza superiore al 95% anche dopo K "
                 f"backtest e con le code grasse.")
    else:
        stato = (f"MOLTO FORTE - DSR={P:.2f}: evidenza schiacciante "
                 f"al netto del selection bias. Verificare comunque "
                 f"che la serie non sia cherry-picked prima di allocare "
                 f"capitale.")
    return stato


def mh415_mappa(xs, rf=0.0, k=10, v=0.25, sr0=0.0):
    """Pipeline completa: serie -> stats + DSR + verdetto."""
    if xs is None:
        raise ValueError("mappa: serve una sequenza di rendimenti")
    R = mh415_num(rf, "risk-free")
    _xs = mh415_parse_serie(xs) if isinstance(xs, str) else tuple(
        mh415_num(x, "rendimento") for x in xs)
    if len(_xs) < 20:
        raise ValueError("mappa: servono almeno 20 valori")
    s = mh415_stats(_xs, R)
    p = mh415_dsr_da_stat(s, k, v, sr0)
    out = {"n_per": s["n"], "rf": s["rf"], "media": s["media"],
           "std": s["std"], "skew": s["skew"], "kurt_ecc": s["kurt_ecc"],
           "kurt": s["kurt"], "sharpe": s["sharpe"], "exc": s["exc"]}
    out.update(p)
    out["verdetto"] = mh415_verdetto(p["dsr"])
    return out

