def mh373_f_kelly(mu, sg):
    mm = mh373_num(mu, "mu")
    ss = mh373_num(sg, "sigma")
    if ss <= 0.0:
        raise ValueError("sigma: deve essere > 0")
    if mm <= 0.0:
        return 0.0
    return mm / (ss * ss)


def mh373_f_var(limite, sg, z):
    ll = mh373_num(limite, "limite")
    ss = mh373_num(sg, "sigma")
    zz = mh373_num(z, "z")
    if ll <= 0.0:
        raise ValueError("limite: deve essere > 0")
    if ss <= 0.0:
        raise ValueError("sigma: deve essere > 0")
    if zz <= 0.0:
        raise ValueError("z: deve essere > 0")
    return ll / (zz * ss)


def mh373_crescita(f, mu, sg):
    ff = mh373_num(f, "f")
    mm = mh373_num(mu, "mu")
    ss = mh373_num(sg, "sigma")
    if ss <= 0.0:
        raise ValueError("sigma: deve essere > 0")
    return ff * mm - 0.5 * ff * ff * ss * ss


def mh373_vol(f, sg):
    ss = mh373_num(sg, "sigma")
    if ss <= 0.0:
        raise ValueError("sigma: deve essere > 0")
    return abs(mh373_num(f, "f")) * ss


def mh373_var_usato(f, sg, z):
    ss = mh373_num(sg, "sigma")
    zz = mh373_num(z, "z")
    if ss <= 0.0:
        raise ValueError("sigma: deve essere > 0")
    if zz <= 0.0:
        raise ValueError("z: deve essere > 0")
    return zz * abs(mh373_num(f, "f")) * ss


def mh373_verdetto(f_star, f_var):
    fs = mh373_num(f_star, "f_star")
    fv = mh373_num(f_var, "f_var")
    if fs <= 0.0:
        return (0.0, "NESSUN EDGE (mu <= 0): nessuna posizione")
    if fv >= fs:
        return (fs, "KELLY LIBERO: il vincolo VaR non morde")
    return (fv, "VINCOLO VaR: sizing ridotto al limite di perdita")


def mh373_analisi(mu, sg, limite, alpha):
    import math
    mm = mh373_num(mu, "mu")
    ss = mh373_num(sg, "sigma")
    ll = mh373_num(limite, "limite")
    if ss <= 0.0:
        raise ValueError("sigma: deve essere > 0")
    if ll <= 0.0:
        raise ValueError("limite: deve essere > 0")
    z = mh373_z(alpha)
    f_star = mh373_f_kelly(mm, ss)
    f_var = mh373_f_var(ll, ss, z)
    f, verdetto = mh373_verdetto(f_star, f_var)
    g_star = mh373_crescita(f_star, mm, ss)
    g = mh373_crescita(f, mm, ss)
    var_usato = mh373_var_usato(f, ss, z)
    raddoppio = math.log(2.0) / g if g > 0.0 else None
    return {
        "mu": mm,
        "sigma": ss,
        "limite": ll,
        "alpha": mh373_num(alpha, "alpha"),
        "z": z,
        "f_star": f_star,
        "f_var": f_var,
        "f": f,
        "verdetto": verdetto,
        "g_star": g_star,
        "g": g,
        "g_persa": g_star - g,
        "vol": mh373_vol(f, ss),
        "var_usato": var_usato,
        "slack": ll - var_usato,
        "raddoppio": raddoppio,
    }
def mh372_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh372_int(x, nome, minimo):
    if isinstance(x, bool):
        raise ValueError(f"{nome}: deve essere un intero")
    if isinstance(x, float) and x.is_integer():
        x = int(x)
    if not isinstance(x, int):
        raise ValueError(f"{nome}: deve essere un intero")
    if x < minimo:
        raise ValueError(f"{nome}: deve essere >= {minimo}")
    return x


def mh372_paths(q, mu, sg, h, n, seed):
    import math
    import random
    qq = mh372_num(q, "q")
    mm = mh372_num(mu, "mu")
    ss = mh372_num(sg, "sigma")
    hh = mh372_int(h, "h", 1)
    nn = mh372_int(n, "n", 100)
    sd = mh372_int(seed, "seed", 0)
    if qq <= 0.0:
        raise ValueError("q: deve essere > 0")
    if ss <= 0.0:
        raise ValueError("sigma: deve essere > 0")
    rng = random.Random(sd)
    drift = mm * hh
    vol = ss * math.sqrt(float(hh))
    return [qq * (drift + vol * rng.gauss(0.0, 1.0)) for _ in range(nn)]


def mh372_quantile(vals, q):
    import math
    qq = mh372_num(q, "q")
    if not 0.0 <= qq <= 1.0:
        raise ValueError("q: deve essere in [0, 1]")
    s = sorted(float(v) for v in vals)
    if not s:
        raise ValueError("vals: lista vuota")
    pos = qq * (len(s) - 1)
    lo = int(math.floor(pos))
    hi = int(math.ceil(pos))
    if lo == hi:
        return s[lo]
    return s[lo] + (s[hi] - s[lo]) * (pos - lo)


def mh372_var(vals, alpha):
    aa = mh372_num(alpha, "alpha")
    if not 0.0 < aa < 1.0:
        raise ValueError("alpha: deve essere in (0, 1)")
    return -mh372_quantile(vals, 1.0 - aa)


def mh372_es(vals, alpha):
    aa = mh372_num(alpha, "alpha")
    if not 0.0 < aa < 1.0:
        raise ValueError("alpha: deve essere in (0, 1)")
    cut = mh372_quantile(vals, 1.0 - aa)
    tail = [float(v) for v in vals if float(v) <= cut]
    if not tail:
        return None
    return -sum(tail) / len(tail)


def mh372_prob_perdita(vals):
    s = [float(v) for v in vals]
    if not s:
        raise ValueError("vals: lista vuota")
    return sum(1 for v in s if v < 0.0) / len(s)


def mh372_quota_var(var_eur, notionale):
    vv = mh372_num(var_eur, "var_eur")
    nn = mh372_num(notionale, "notionale")
    if nn <= 0.0:
        return None
    return vv / nn


def mh372_verdetto(quota):
    if quota is None:
        return "DATI INSUFFICIENTI: notionale nullo o non positivo"
    qq = mh372_num(quota, "quota")
    if qq < 0.02:
        return "BASSO: VaR sotto il 2% del notionale"
    if qq < 0.05:
        return "MODERATO: VaR tra il 2% e il 5% del notionale"
    if qq < 0.10:
        return "ELEVATO: VaR tra il 5% e il 10% del notionale"
    return "CRITICO: VaR oltre il 10% del notionale"


def mh372_var_teorico(q, sg, h, alpha):
    import math
    from statistics import NormalDist
    qq = mh372_num(q, "q")
    ss = mh372_num(sg, "sigma")
    hh = mh372_num(h, "h")
    aa = mh372_num(alpha, "alpha")
    if qq <= 0.0:
        raise ValueError("q: deve essere > 0")
    if ss <= 0.0:
        raise ValueError("sigma: deve essere > 0")
    if hh <= 0.0:
        raise ValueError("h: deve essere > 0")
    if not 0.0 < aa < 1.0:
        raise ValueError("alpha: deve essere in (0, 1)")
    return qq * ss * math.sqrt(hh) * NormalDist().inv_cdf(aa)


def mh372_analisi(q, prezzo, mu, sg, h, n, seed, alpha):
    qq = mh372_num(q, "q")
    pp = mh372_num(prezzo, "prezzo")
    mm = mh372_num(mu, "mu")
    ss = mh372_num(sg, "sigma")
    aa = mh372_num(alpha, "alpha")
    if pp <= 0.0:
        raise ValueError("prezzo: deve essere > 0")
    if not 0.0 < aa < 1.0:
        raise ValueError("alpha: deve essere in (0, 1)")
    paths = mh372_paths(qq, mm, ss, h, n, seed)
    var = mh372_var(paths, aa)
    es = mh372_es(paths, aa)
    notionale = qq * pp
    quota = mh372_quota_var(var, notionale)
    return {
        "q": qq,
        "prezzo": pp,
        "mu": mm,
        "sigma": ss,
        "h": h,
        "n": n,
        "seed": seed,
        "alpha": aa,
        "notionale": notionale,
        "pnl_medio": sum(paths) / len(paths),
        "pnl_min": min(paths),
        "pnl_max": max(paths),
        "var": var,
        "es": es,
        "prob_perdita": mh372_prob_perdita(paths),
        "quota_var": quota,
        "var_teorico": mh372_var_teorico(qq, ss, h, aa),
        "verdetto": mh372_verdetto(quota),
    }
def mh371_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh371_fstar(mu, sigma):
    mm = mh371_num(mu, "mu")
    ss = mh371_num(sigma, "sigma")
    if ss <= 0.0:
        raise ValueError("sigma: deve essere > 0")
    return mm / (ss * ss)


def mh371_growth(f, mu, sigma):
    ff = mh371_num(f, "f")
    mm = mh371_num(mu, "mu")
    ss = mh371_num(sigma, "sigma")
    if ff < 0.0:
        raise ValueError("f: deve essere >= 0")
    if ss <= 0.0:
        raise ValueError("sigma: deve essere > 0")
    return ff * mm - 0.5 * (ff * ss) ** 2


def mh371_vol_log(f, sigma):
    ff = mh371_num(f, "f")
    ss = mh371_num(sigma, "sigma")
    if ff < 0.0:
        raise ValueError("f: deve essere >= 0")
    if ss <= 0.0:
        raise ValueError("sigma: deve essere > 0")
    return ff * ss


def mh371_sharpe(mu, sigma):
    mm = mh371_num(mu, "mu")
    ss = mh371_num(sigma, "sigma")
    if ss <= 0.0:
        raise ValueError("sigma: deve essere > 0")
    return mm / ss


def mh371_frazione_target(v_target, f_star, sigma):
    vv = mh371_num(v_target, "v_target")
    fs = mh371_num(f_star, "f_star")
    ss = mh371_num(sigma, "sigma")
    if vv < 0.0:
        raise ValueError("v_target: deve essere >= 0")
    if fs <= 0.0:
        raise ValueError("f_star: deve essere > 0")
    if ss <= 0.0:
        raise ValueError("sigma: deve essere > 0")
    return min(1.0, vv / (fs * ss))


def mh371_f_fraz(c, f_star):
    cc = mh371_num(c, "c")
    fs = mh371_num(f_star, "f_star")
    if not 0.0 <= cc <= 1.0:
        raise ValueError("c: deve essere in [0, 1]")
    if fs <= 0.0:
        raise ValueError("f_star: deve essere > 0")
    return cc * fs


def mh371_trade_raddoppio(g):
    import math
    gg = mh371_num(g, "g")
    if gg <= 0.0:
        return None
    return math.log(2.0) / gg


def mh371_curva(mu, sigma, n=81):
    mm = mh371_num(mu, "mu")
    ss = mh371_num(sigma, "sigma")
    if ss <= 0.0:
        raise ValueError("sigma: deve essere > 0")
    fs = mm / (ss * ss)
    cs = [i / (n - 1) for i in range(n)]
    gs = [mh371_growth(c * fs, mm, ss) for c in cs]
    vols = [mh371_vol_log(c * fs, ss) for c in cs]
    return {"cs": cs, "gs": gs, "vols": vols}


def mh371_verdetto(mu, c_star):
    mm = mh371_num(mu, "mu")
    cc = mh371_num(c_star, "c_star")
    if mm <= 0.0:
        return ("NESSUN EDGE: mu <= 0, la frazione ottimale e' zero "
                "(non aprire la posizione).")
    if cc >= 1.0:
        return ("PIENO: il budget di volatilita' copre f* Kelly, "
                "applica la size piena f = f*.")
    if cc <= 0.0:
        return ("NESSUNA POSIZIONE: budget di volatilita' nullo, "
                "size zero.")
    return (f"FRAZIONARIO: applica c = {cc:.0%} di f* Kelly "
            f"(f = {cc:.0%} x f*) per rispettare il budget di vol.")


def mh371_analisi(mu, sigma, v_target):
    mm = mh371_num(mu, "mu")
    ss = mh371_num(sigma, "sigma")
    vv = mh371_num(v_target, "v_target")
    fs = mh371_fstar(mm, ss)
    c_star = mh371_frazione_target(vv, fs, ss)
    f = mh371_f_fraz(c_star, fs)
    g = mh371_growth(f, mm, ss)
    return {
        "mu": mm,
        "sigma": ss,
        "v_target": vv,
        "f_star": fs,
        "vol_star": mh371_vol_log(fs, ss),
        "sharpe": mh371_sharpe(mm, ss),
        "c_star": c_star,
        "f": f,
        "g": g,
        "vol": mh371_vol_log(f, ss),
        "trade_raddoppio": mh371_trade_raddoppio(g),
        "verdetto": mh371_verdetto(mm, c_star),
        "curva": mh371_curva(mm, ss),
    }
def mh370_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh370_growth(f, mu, sigma):
    ff = mh370_num(f, "f")
    mm = mh370_num(mu, "mu")
    ss = mh370_num(sigma, "sigma")
    if ff < 0.0:
        raise ValueError("f: deve essere >= 0")
    if ss <= 0.0:
        raise ValueError("sigma: deve essere > 0")
    return ff * mm - 0.5 * (ff * ss) ** 2


def mh370_vol_log(f, sigma):
    ff = mh370_num(f, "f")
    ss = mh370_num(sigma, "sigma")
    if ff < 0.0:
        raise ValueError("f: deve essere >= 0")
    if ss <= 0.0:
        raise ValueError("sigma: deve essere > 0")
    return ff * ss


def mh370_sharpe(mu, sigma):
    mm = mh370_num(mu, "mu")
    ss = mh370_num(sigma, "sigma")
    if ss <= 0.0:
        raise ValueError("sigma: deve essere > 0")
    return mm / ss


def mh370_fstar(mu, sigma):
    mm = mh370_num(mu, "mu")
    ss = mh370_num(sigma, "sigma")
    if ss <= 0.0:
        raise ValueError("sigma: deve essere > 0")
    return max(mm / (ss * ss), 0.0)


def mh370_proba_drawdown(f, mu, sigma, d):
    ff = mh370_num(f, "f")
    mm = mh370_num(mu, "mu")
    ss = mh370_num(sigma, "sigma")
    dd = mh370_num(d, "D")
    if ff < 0.0:
        raise ValueError("f: deve essere >= 0")
    if ss <= 0.0:
        raise ValueError("sigma: deve essere > 0")
    if dd <= 0.0 or dd >= 1.0:
        raise ValueError("D: deve essere in (0, 1)")
    if ff == 0.0:
        return 0.0
    gg = mh370_growth(ff, mm, ss)
    vv = mh370_vol_log(ff, ss)
    if gg <= 0.0:
        return 1.0
    return (1.0 - dd) ** (2.0 * gg / (vv * vv))


def mh370_trade_raddoppio(f, mu, sigma):
    gg = mh370_growth(f, mu, sigma)
    if gg <= 0.0:
        return None
    import math
    return math.log(2.0) / gg


def mh370_verdetto(p, g, f, d):
    pp = mh370_num(p, "p")
    gg = mh370_num(g, "g")
    ff = mh370_num(f, "f")
    dd = mh370_num(d, "D")
    if not 0.0 <= pp <= 1.0:
        raise ValueError("p: deve essere in [0, 1]")
    if gg <= 0.0:
        return (f"NESSUN EDGE: drift logaritmico g = {gg:.3%} <= 0 con "
                f"f = {ff:.0%}: toccare il drawdown {dd:.0%} e' certo "
                "(P = 100%): riduci la size o cerca edge con mu maggiore.")
    if pp >= 0.50:
        return (f"RISCHIO CRITICO: P = {pp:.1%} di toccare un max drawdown "
                f"{dd:.0%} dal picco con f = {ff:.0%}: dimezza la size o "
                "alza il livello di stop prima di tradare.")
    if pp >= 0.25:
        return (f"RISCHIO ALTO: P = {pp:.1%} di toccare un max drawdown "
                f"{dd:.0%} dal picco con f = {ff:.0%}: sizing aggressivo, "
                "valuta frazione ridotta o stop piu' stretto.")
    if pp >= 0.10:
        return (f"RISCHIO MODERATO: P = {pp:.1%} di toccare un max "
                f"drawdown {dd:.0%} con f = {ff:.0%}: accettabile solo con "
                "stop disciplinati e monitoraggio.")
    return (f"RISCHIO CONTENUTO: P = {pp:.1%} di toccare un max drawdown "
            f"{dd:.0%} con f = {ff:.0%}: profilo difensivo, drag di "
            "volatilita' contenuto.")


def mh370_curva_rischio(f_max, mu, sigma, d, n=81):
    fm = mh370_num(f_max, "f_max")
    mm = mh370_num(mu, "mu")
    ss = mh370_num(sigma, "sigma")
    dd = mh370_num(d, "D")
    nn = mh370_num(n, "n")
    if nn != int(nn) or int(nn) < 2:
        raise ValueError("n: deve essere intero >= 2")
    nn = int(nn)
    if fm <= 0.0:
        raise ValueError("f_max: deve essere > 0")
    if ss <= 0.0:
        raise ValueError("sigma: deve essere > 0")
    if dd <= 0.0 or dd >= 1.0:
        raise ValueError("D: deve essere in (0, 1)")
    fs = [fm * i / (nn - 1) for i in range(nn)]
    ps = [mh370_proba_drawdown(f, mm, ss, dd) for f in fs]
    return {"fs": fs, "ps": ps}


def mh370_mappa(f_max, mu, sigma, d_min, d_max, nf=25, nd=13):
    fm = mh370_num(f_max, "f_max")
    mm = mh370_num(mu, "mu")
    ss = mh370_num(sigma, "sigma")
    d0 = mh370_num(d_min, "d_min")
    d1 = mh370_num(d_max, "d_max")
    nff = mh370_num(nf, "nf")
    ndd = mh370_num(nd, "nd")
    if nff != int(nff) or int(nff) < 2:
        raise ValueError("nf: deve essere intero >= 2")
    if ndd != int(ndd) or int(ndd) < 2:
        raise ValueError("nd: deve essere intero >= 2")
    nff, ndd = int(nff), int(ndd)
    if fm <= 0.0:
        raise ValueError("f_max: deve essere > 0")
    if ss <= 0.0:
        raise ValueError("sigma: deve essere > 0")
    if not 0.0 < d0 < d1 < 1.0:
        raise ValueError("d_min/d_max: deve valere 0 < d_min < d_max < 1")
    fs = [0.05 + (fm - 0.05) * i / (nff - 1) for i in range(nff)]
    ds = [d0 + (d1 - d0) * j / (ndd - 1) for j in range(ndd)]
    z = [[mh370_proba_drawdown(f, mm, ss, d) for f in fs] for d in ds]
    return {"fs": fs, "ds": ds, "z": z}


def mh370_analisi(f, mu, sigma, d, n=81):
    ff = mh370_num(f, "f")
    mm = mh370_num(mu, "mu")
    ss = mh370_num(sigma, "sigma")
    dd = mh370_num(d, "D")
    if ff < 0.0:
        raise ValueError("f: deve essere >= 0")
    if ss <= 0.0:
        raise ValueError("sigma: deve essere > 0")
    if dd <= 0.0 or dd >= 1.0:
        raise ValueError("D: deve essere in (0, 1)")
    gg = mh370_growth(ff, mm, ss)
    vv = mh370_vol_log(ff, ss)
    fs_ = mh370_fstar(mm, ss)
    pp = mh370_proba_drawdown(ff, mm, ss, dd)
    f_plot = max(ff, fs_) * 1.25
    if f_plot < 0.5:
        f_plot = 0.5
    return {"f": ff, "mu": mm, "sigma": ss, "D": dd,
            "g": gg, "vol": vv, "sharpe": mh370_sharpe(mm, ss),
            "f_star": fs_, "p_drawdown": pp,
            "trade_raddoppio": mh370_trade_raddoppio(ff, mm, ss),
            "verdetto": mh370_verdetto(pp, gg, ff, dd),
            "curva": mh370_curva_rischio(f_plot, mm, ss, dd, n),
            "mappa": mh370_mappa(f_plot, mm, ss, 0.05, 0.60)}
def mh369_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh369_fstar_lordo(mu, sigma):
    mm = mh369_num(mu, "mu")
    ss = mh369_num(sigma, "sigma")
    if ss <= 0.0:
        raise ValueError("sigma: deve essere > 0")
    return max(mm / (ss * ss), 0.0)


def mh369_fstar_netto(mu, sigma, c):
    mm = mh369_num(mu, "mu")
    ss = mh369_num(sigma, "sigma")
    cc = mh369_num(c, "c")
    if ss <= 0.0:
        raise ValueError("sigma: deve essere > 0")
    if cc < 0.0:
        raise ValueError("c: deve essere >= 0")
    return max((mm - cc) / (ss * ss), 0.0)


def mh369_growth_lordo(f, mu, sigma):
    ff = mh369_num(f, "f")
    mm = mh369_num(mu, "mu")
    ss = mh369_num(sigma, "sigma")
    if ff < 0.0:
        raise ValueError("f: deve essere >= 0")
    if ss <= 0.0:
        raise ValueError("sigma: deve essere > 0")
    return ff * mm - 0.5 * (ff * ss) ** 2


def mh369_growth_netto(f, mu, sigma, c):
    ff = mh369_num(f, "f")
    mm = mh369_num(mu, "mu")
    ss = mh369_num(sigma, "sigma")
    cc = mh369_num(c, "c")
    if ff < 0.0:
        raise ValueError("f: deve essere >= 0")
    if ss <= 0.0:
        raise ValueError("sigma: deve essere > 0")
    if cc < 0.0:
        raise ValueError("c: deve essere >= 0")
    return ff * (mm - cc) - 0.5 * (ff * ss) ** 2


def mh369_vol_log(f, sigma):
    ff = mh369_num(f, "f")
    ss = mh369_num(sigma, "sigma")
    if ff < 0.0:
        raise ValueError("f: deve essere >= 0")
    if ss <= 0.0:
        raise ValueError("sigma: deve essere > 0")
    return ff * ss


def mh369_sharpe(mu, sigma):
    mm = mh369_num(mu, "mu")
    ss = mh369_num(sigma, "sigma")
    if ss <= 0.0:
        raise ValueError("sigma: deve essere > 0")
    return mm / ss


def mh369_breakeven(c):
    cc = mh369_num(c, "c")
    if cc < 0.0:
        raise ValueError("c: deve essere >= 0")
    return cc


def mh369_edge_tax(mu, c):
    mm = mh369_num(mu, "mu")
    cc = mh369_num(c, "c")
    if mm <= 0.0:
        raise ValueError("mu: deve essere > 0 per l'edge tax")
    if cc < 0.0:
        raise ValueError("c: deve essere >= 0")
    return cc / mm


def mh369_curva(f_max, mu, sigma, c, n=81):
    fm = mh369_num(f_max, "f_max")
    mm = mh369_num(mu, "mu")
    ss = mh369_num(sigma, "sigma")
    cc = mh369_num(c, "c")
    nn = mh369_num(n, "n")
    if nn != int(nn) or int(nn) < 2:
        raise ValueError("n: deve essere intero >= 2")
    nn = int(nn)
    if fm <= 0.0:
        raise ValueError("f_max: deve essere > 0")
    if ss <= 0.0:
        raise ValueError("sigma: deve essere > 0")
    if cc < 0.0:
        raise ValueError("c: deve essere >= 0")
    fs = [fm * i / (nn - 1) for i in range(nn)]
    gl = [mh369_growth_lordo(f, mm, ss) for f in fs]
    gn = [mh369_growth_netto(f, mm, ss, cc) for f in fs]
    return {"fs": fs, "gs_lordo": gl, "gs_netto": gn}


def mh369_verdetto(f_netto, cap, mu, c):
    fn = mh369_num(f_netto, "f_netto")
    cp = mh369_num(cap, "cap")
    mm = mh369_num(mu, "mu")
    cc = mh369_num(c, "c")
    if cp <= 0.0:
        raise ValueError("cap: deve essere > 0")
    if cc < 0.0:
        raise ValueError("c: deve essere >= 0")
    if mm <= cc or fn <= 0.0:
        return (f"NESSUN EDGE NETTO: μ = {mm:.3%} non copre il costo "
                f"c = {cc:.3%} per trade: la frazione ottimale netta e' "
                "zero, resta liquido o cerca edge con μ > c.")
    if fn > cp:
        return (f"CAP VINCOLANTE: f*_netto = {fn:.0%} supera il tuo limite "
                f"{cp:.0%}: applichi il cap e accetti una crescita netta "
                "ridotta; valuta se alzare il limite, ridurre la size o "
                "tagliare i costi di transazione.")
    if fn >= 0.9 * cp:
        return (f"SIZING PIENO: f*_netto = {fn:.0%} usa quasi tutto il "
                f"limite {cp:.0%}: sizing aggressivo ma dentro i vincoli.")
    return (f"SOTTO-SIZING OK: f*_netto = {fn:.0%} sotto il limite "
            f"{cp:.0%}: tieni cash, drag di volatilita' contenuto.")


def mh369_analisi(mu, sigma, c, cap, n=81):
    mm = mh369_num(mu, "mu")
    ss = mh369_num(sigma, "sigma")
    cc = mh369_num(c, "c")
    cp = mh369_num(cap, "cap")
    if ss <= 0.0:
        raise ValueError("sigma: deve essere > 0")
    if cc < 0.0:
        raise ValueError("c: deve essere >= 0")
    if cp <= 0.0:
        raise ValueError("cap: deve essere > 0")
    fl = mh369_fstar_lordo(mm, ss)
    fn = mh369_fstar_netto(mm, ss, cc)
    fe = min(fn, cp)
    f_plot = max(fl, fn, cp) * 1.25
    if f_plot < 0.5:
        f_plot = 0.5
    return {"mu": mm, "sigma": ss, "c": cc, "cap": cp,
            "f_lordo": fl, "f_netto": fn, "f_eff": fe,
            "g_netto_star": mh369_growth_netto(fn, mm, ss, cc),
            "g_netto_eff": mh369_growth_netto(fe, mm, ss, cc),
            "g_lordo_eff": mh369_growth_lordo(fe, mm, ss),
            "vol_eff": mh369_vol_log(fe, ss),
            "sharpe": mh369_sharpe(mm, ss),
            "breakeven": mh369_breakeven(cc),
            "edge_tax": mh369_edge_tax(mm, cc) if mm > 0.0 else None,
            "verdetto": mh369_verdetto(fn, cp, mm, cc),
            "curva": mh369_curva(f_plot, mm, ss, cc, n)}
def mh368_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh368_fstar(mu, sigma):
    mm = mh368_num(mu, "mu")
    ss = mh368_num(sigma, "sigma")
    if ss <= 0.0:
        raise ValueError("sigma: deve essere > 0")
    return max(mm / (ss * ss), 0.0)


def mh368_growth(f, mu, sigma):
    ff = mh368_num(f, "f")
    mm = mh368_num(mu, "mu")
    ss = mh368_num(sigma, "sigma")
    if ff < 0.0:
        raise ValueError("f: deve essere >= 0")
    if ss <= 0.0:
        raise ValueError("sigma: deve essere > 0")
    return ff * mm - 0.5 * (ff * ss) ** 2


def mh368_vol_log(f, sigma):
    ff = mh368_num(f, "f")
    ss = mh368_num(sigma, "sigma")
    if ff < 0.0:
        raise ValueError("f: deve essere >= 0")
    if ss <= 0.0:
        raise ValueError("sigma: deve essere > 0")
    return ff * ss


def mh368_sharpe(mu, sigma):
    mm = mh368_num(mu, "mu")
    ss = mh368_num(sigma, "sigma")
    if ss <= 0.0:
        raise ValueError("sigma: deve essere > 0")
    return mm / ss


def mh368_drag(sigma):
    ss = mh368_num(sigma, "sigma")
    if ss <= 0.0:
        raise ValueError("sigma: deve essere > 0")
    return 0.5 * ss * ss


def mh368_curva(f_max, mu, sigma, n=81):
    fm = mh368_num(f_max, "f_max")
    mm = mh368_num(mu, "mu")
    ss = mh368_num(sigma, "sigma")
    nn = mh368_num(n, "n")
    if nn != int(nn) or int(nn) < 2:
        raise ValueError("n: deve essere intero >= 2")
    nn = int(nn)
    if fm <= 0.0:
        raise ValueError("f_max: deve essere > 0")
    if ss <= 0.0:
        raise ValueError("sigma: deve essere > 0")
    fs = [fm * i / (nn - 1) for i in range(nn)]
    gs = [mh368_growth(f, mm, ss) for f in fs]
    return {"fs": fs, "gs": gs}


def mh368_verdetto(f_star, cap, mu):
    fs = mh368_num(f_star, "f_star")
    cc = mh368_num(cap, "cap")
    mm = mh368_num(mu, "mu")
    if cc <= 0.0:
        raise ValueError("cap: deve essere > 0")
    if mm <= 0.0 or fs <= 0.0:
        return ("NESSUN EDGE: rendimento atteso non positivo (mu <= 0): "
                "la frazione ottimale e' zero, resta liquido.")
    if fs > cc:
        return (f"CAP VINCOLANTE: f* = {fs:.0%} supera il tuo limite "
                f"{cc:.0%}: applichi il cap e accetti una crescita ridotta; "
                "valuta se alzare il limite o ridurre la size.")
    if fs >= 0.9 * cc:
        return (f"SIZING PIENO: f* = {fs:.0%} usa quasi tutto il limite "
                f"{cc:.0%}: sizing aggressivo ma dentro i vincoli.")
    return (f"SOTTO-SIZING OK: f* = {fs:.0%} sotto il limite {cc:.0%}: "
            "tieni cash, drag di volatilita' contenuto.")


def mh368_analisi(mu, sigma, cap, n=81):
    mm = mh368_num(mu, "mu")
    ss = mh368_num(sigma, "sigma")
    cc = mh368_num(cap, "cap")
    if ss <= 0.0:
        raise ValueError("sigma: deve essere > 0")
    if cc <= 0.0:
        raise ValueError("cap: deve essere > 0")
    fs = mh368_fstar(mm, ss)
    fe = min(fs, cc)
    f_plot = max(fs, cc) * 1.25
    if f_plot < 0.5:
        f_plot = 0.5
    return {"mu": mm, "sigma": ss, "cap": cc,
            "f_star": fs, "f_eff": fe,
            "g_star": mh368_growth(fs, mm, ss),
            "g_eff": mh368_growth(fe, mm, ss),
            "vol_star": mh368_vol_log(fs, ss),
            "vol_eff": mh368_vol_log(fe, ss),
            "sharpe": mh368_sharpe(mm, ss),
            "drag": mh368_drag(ss),
            "verdetto": mh368_verdetto(fs, cc, mm),
            "curva": mh368_curva(f_plot, mm, ss, n)}
def mh367_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh367_fstar(p, b):
    pp = mh367_num(p, "p")
    bb = mh367_num(b, "b")
    if not 0.0 < pp < 1.0:
        raise ValueError("p: deve stare in (0, 1)")
    if bb <= 0.0:
        raise ValueError("b: deve essere > 0")
    return max((pp * bb - (1.0 - pp)) / bb, 0.0)


def mh367_log_g(f, p, b):
    import math
    ff = mh367_num(f, "f")
    pp = mh367_num(p, "p")
    bb = mh367_num(b, "b")
    if not 0.0 <= ff < 1.0:
        raise ValueError("f: deve stare in [0, 1)")
    if not 0.0 < pp < 1.0:
        raise ValueError("p: deve stare in (0, 1)")
    if bb <= 0.0:
        raise ValueError("b: deve essere > 0")
    return (pp * math.log(1.0 + bb * ff)
            + (1.0 - pp) * math.log(1.0 - ff))


def mh367_p_edge(b):
    bb = mh367_num(b, "b")
    if bb <= 0.0:
        raise ValueError("b: deve essere > 0")
    return 1.0 / (1.0 + bb)


def mh367_margine(p, b):
    pp = mh367_num(p, "p")
    bb = mh367_num(b, "b")
    if not 0.0 < pp < 1.0:
        raise ValueError("p: deve stare in (0, 1)")
    if bb <= 0.0:
        raise ValueError("b: deve essere > 0")
    pe = mh367_p_edge(bb)
    return {"p_edge": pe, "delta_p": pp - pe}


def mh367_griglia(p_min, p_max, b_min, b_max, n):
    p0 = mh367_num(p_min, "p_min")
    p1 = mh367_num(p_max, "p_max")
    b0 = mh367_num(b_min, "b_min")
    b1 = mh367_num(b_max, "b_max")
    nn = mh367_num(n, "n")
    if nn != int(nn) or int(nn) < 2:
        raise ValueError("n: deve essere intero >= 2")
    nn = int(nn)
    if not 0.0 < p0 < p1 < 1.0:
        raise ValueError("p_min/p_max: deve valere 0 < p_min < p_max < 1")
    if not 0.0 < b0 < b1:
        raise ValueError("b_min/b_max: deve valere 0 < b_min < b_max")
    ps = [p0 + (p1 - p0) * i / (nn - 1) for i in range(nn)]
    bs = [b0 + (b1 - b0) * i / (nn - 1) for i in range(nn)]
    fstar = [[mh367_fstar(p, b) for p in ps] for b in bs]
    gg = [[mh367_log_g(f, p, b) for p, f in zip(ps, fr)]
          for b, fr in zip(bs, fstar)]
    return {"ps": ps, "bs": bs, "fstar": fstar, "g": gg}


def mh367_verdetto(delta_p, g):
    dp = mh367_num(delta_p, "delta_p")
    gg = mh367_num(g, "g")
    if gg <= 0.0 or dp <= 0.0:
        return ("NESSUN EDGE: margine nullo o negativo (o g <= 0): la stima "
                "corrente non regge alcun sizing, rivedi p e b.")
    if dp < 0.05:
        return (f"MARGINE SOTTILE: cuscinetto di {dp:.1%} su p: basta una "
                "stima di p ottimistica di pochi punti per azzerare l'edge, "
                "usa la mezza Kelly o riduci la size.")
    if dp < 0.15:
        return (f"MARGINE ADEGUATO: cuscinetto di {dp:.1%} su p: il sizing "
                "regge errori di stima moderati, mezza Kelly consigliata "
                "per prudenza.")
    return (f"MARGINE AMPIO: cuscinetto di {dp:.1%} su p: l'edge sopravvive "
            "anche a stime di p decisamente ottimistiche.")


def mh367_analisi(p0, b0, p_min=0.30, p_max=0.90, b_min=0.20, b_max=3.00,
                  n=41):
    pp = mh367_num(p0, "p0")
    bb = mh367_num(b0, "b0")
    if not 0.0 < pp < 1.0:
        raise ValueError("p0: deve stare in (0, 1)")
    if bb <= 0.0:
        raise ValueError("b0: deve essere > 0")
    f = mh367_fstar(pp, bb)
    g = mh367_log_g(f, pp, bb)
    m = mh367_margine(pp, bb)
    gr = mh367_griglia(p_min, p_max, b_min, b_max, n)
    return {"p0": pp, "b0": bb, "f_star": f, "g": g,
            "p_edge": m["p_edge"], "delta_p": m["delta_p"],
            "verdetto": mh367_verdetto(m["delta_p"], g),
            "griglia": gr}

def mh366_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh366_int(x, nome, minimo):
    v = mh366_num(x, nome)
    if v != int(v):
        raise ValueError(f"{nome}: deve essere intero")
    v = int(v)
    if v < minimo:
        raise ValueError(f"{nome}: deve essere >= {minimo}")
    return v


def mh366_fstar(p, b):
    pp = mh366_num(p, "p")
    bb = mh366_num(b, "b")
    if not 0.0 < pp < 1.0:
        raise ValueError("p: deve stare in (0, 1)")
    if bb <= 0.0:
        raise ValueError("b: deve essere > 0")
    return max((pp * bb - (1.0 - pp)) / bb, 0.0)


def mh366_log_g(f, p, b):
    import math
    ff = mh366_num(f, "f")
    pp = mh366_num(p, "p")
    bb = mh366_num(b, "b")
    if not 0.0 <= ff < 1.0:
        raise ValueError("f: deve stare in [0, 1)")
    if not 0.0 < pp < 1.0:
        raise ValueError("p: deve stare in (0, 1)")
    if bb <= 0.0:
        raise ValueError("b: deve essere > 0")
    return (pp * math.log(1.0 + bb * ff)
            + (1.0 - pp) * math.log(1.0 - ff))


def mh366_pmf(k, n, p):
    import math
    kk = mh366_int(k, "k", 0)
    nn = mh366_int(n, "n", 1)
    pp = mh366_num(p, "p")
    if not 0.0 <= pp <= 1.0:
        raise ValueError("p: deve stare in [0, 1]")
    if kk > nn:
        raise ValueError("k: non puo' superare n")
    return math.comb(nn, kk) * (pp ** kk) * ((1.0 - pp) ** (nn - kk))


def mh366_p_raddoppio(f, p, b, n):
    import math
    nn = mh366_int(n, "n", 1)
    ff = mh366_num(f, "f")
    bb = mh366_num(b, "b")
    if not 0.0 <= ff < 1.0:
        raise ValueError("f: deve stare in [0, 1)")
    if bb <= 0.0:
        raise ValueError("b: deve essere > 0")
    lgw = math.log(1.0 + bb * ff)
    lgl = math.log(1.0 - ff)
    soglia = math.log(2.0)
    tot = 0.0
    for k in range(nn + 1):
        if k * lgw + (nn - k) * lgl >= soglia:
            tot += mh366_pmf(k, nn, p)
    return min(max(tot, 0.0), 1.0)


def mh366_p_dimezzamento(f, p, b, n):
    import math
    nn = mh366_int(n, "n", 1)
    ff = mh366_num(f, "f")
    bb = mh366_num(b, "b")
    if not 0.0 <= ff < 1.0:
        raise ValueError("f: deve stare in [0, 1)")
    if bb <= 0.0:
        raise ValueError("b: deve essere > 0")
    lgw = math.log(1.0 + bb * ff)
    lgl = math.log(1.0 - ff)
    soglia = math.log(0.5)
    tot = 0.0
    for k in range(nn + 1):
        if k * lgw + (nn - k) * lgl <= soglia:
            tot += mh366_pmf(k, nn, p)
    return min(max(tot, 0.0), 1.0)


def mh366_quantili(f, p, b, n, qs=(0.05, 0.25, 0.5, 0.75, 0.95)):
    import math
    nn = mh366_int(n, "n", 1)
    ff = mh366_num(f, "f")
    bb = mh366_num(b, "b")
    if not 0.0 <= ff < 1.0:
        raise ValueError("f: deve stare in [0, 1)")
    if bb <= 0.0:
        raise ValueError("b: deve essere > 0")
    lgw = math.log(1.0 + bb * ff)
    lgl = math.log(1.0 - ff)
    qlist = [mh366_num(q, "q") for q in qs]
    for q in qlist:
        if not 0.0 < q < 1.0:
            raise ValueError("qs: ogni quantile deve stare in (0, 1)")
    out = {}
    cum = 0.0
    qi = 0
    order = sorted(range(len(qlist)), key=lambda i: qlist[i])
    for k in range(nn + 1):
        cum += mh366_pmf(k, nn, p)
        while qi < len(order) and cum >= qlist[order[qi]]:
            q = qlist[order[qi]]
            out[q] = math.exp(k * lgw + (nn - k) * lgl)
            qi += 1
        if qi >= len(order):
            break
    return out


def mh366_verdetto(p_radd, p_dim, g):
    pr = mh366_num(p_radd, "p_radd")
    pd = mh366_num(p_dim, "p_dim")
    gg = mh366_num(g, "g")
    if not 0.0 <= pr <= 1.0 or not 0.0 <= pd <= 1.0:
        raise ValueError("p_radd, p_dim: devono stare in [0, 1]")
    if gg <= 0.0:
        return ("NESSUN EDGE: g(f*) <= 0, su N trade il capitale non "
                "cresce in media geometrica: nessun sizing.")
    if pr >= 0.80 and pd <= 0.05:
        return (f"CRESCITA SOLIDA: P(raddoppio) = {pr:.0%} con "
                f"P(dimezzamento) = {pd:.1%}: l'orizzonte premia il "
                "sizing pieno.")
    if pr >= 0.50:
        return (f"CRESCITA PROBABILE: P(raddoppio) = {pr:.0%} "
                f"(P(dimezzamento) = {pd:.1%}): edge positivo ma "
                "orizzonte corto, valuta la mezza Kelly.")
    return (f"CRESCITA INCERTA: P(raddoppio) = {pr:.0%} "
            f"(P(dimezzamento) = {pd:.1%}): su questo orizzonte il "
            "risultato e' dominato dal caso.")


def mh366_analisi(p, b, n):
    import math
    nn = mh366_int(n, "n", 1)
    f = mh366_fstar(p, b)
    g = mh366_log_g(f, p, b)
    log_att = nn * g
    pr = mh366_p_raddoppio(f, p, b, nn)
    pd = mh366_p_dimezzamento(f, p, b, nn)
    qs = mh366_quantili(f, p, b, nn)
    return {"p": float(p), "b": float(b), "n": nn, "f_star": f, "g": g,
            "log_atteso": log_att,
            "moltiplicatore_geometrico": math.exp(log_att),
            "p_raddoppio": pr, "p_dimezzamento": pd, "quantili": qs,
            "verdetto": mh366_verdetto(pr, pd, g)}

def mh365_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh365_int(x, nome, minimo):
    v = mh365_num(x, nome)
    if v != int(v):
        raise ValueError(f"{nome}: deve essere intero")
    v = int(v)
    if v < minimo:
        raise ValueError(f"{nome}: deve essere >= {minimo}")
    return v


def mh365_betacf(a, b, x):
    aa = mh365_num(a, "a")
    bb = mh365_num(b, "b")
    xx = mh365_num(x, "x")
    if aa <= 0.0 or bb <= 0.0:
        raise ValueError("a, b: devono essere > 0")
    if not 0.0 <= xx <= 1.0:
        raise ValueError("x: deve stare in [0, 1]")
    MAXIT, EPS, FPMIN = 200, 3.0e-9, 1.0e-300
    qab = aa + bb
    qap = aa + 1.0
    qam = aa - 1.0
    c = 1.0
    d = 1.0 - qab * xx / qap
    if abs(d) < FPMIN:
        d = FPMIN
    d = 1.0 / d
    h = d
    for m in range(1, MAXIT + 1):
        m2 = 2 * m
        aat = m * (bb - m) * xx / ((qam + m2) * (aa + m2))
        d = 1.0 + aat * d
        if abs(d) < FPMIN:
            d = FPMIN
        c = 1.0 + aat / c
        if abs(c) < FPMIN:
            c = FPMIN
        d = 1.0 / d
        h *= d * c
        aat = -(aa + m) * (qab + m) * xx / ((aa + m2) * (qap + m2))
        d = 1.0 + aat * d
        if abs(d) < FPMIN:
            d = FPMIN
        c = 1.0 + aat / c
        if abs(c) < FPMIN:
            c = FPMIN
        d = 1.0 / d
        dl = d * c
        h *= dl
        if abs(dl - 1.0) < EPS:
            break
    return h


def mh365_betai(a, b, x):
    import math
    aa = mh365_num(a, "a")
    bb = mh365_num(b, "b")
    xx = mh365_num(x, "x")
    if aa <= 0.0 or bb <= 0.0:
        raise ValueError("a, b: devono essere > 0")
    if not 0.0 <= xx <= 1.0:
        raise ValueError("x: deve stare in [0, 1]")
    if xx == 0.0 or xx == 1.0:
        return xx
    lb = (math.lgamma(aa + bb) - math.lgamma(aa) - math.lgamma(bb)
          + aa * math.log(xx) + bb * math.log(1.0 - xx))
    if xx < (aa + 1.0) / (aa + bb + 2.0):
        return math.exp(lb) * mh365_betacf(aa, bb, xx) / aa
    return 1.0 - math.exp(lb) * mh365_betacf(bb, aa, 1.0 - xx) / bb


def mh365_beta_ppf(q, a, b):
    qq = mh365_num(q, "q")
    if not 0.0 < qq < 1.0:
        raise ValueError("q: deve stare in (0, 1)")
    aa = mh365_num(a, "a")
    bb = mh365_num(b, "b")
    if aa <= 0.0 or bb <= 0.0:
        raise ValueError("a, b: devono essere > 0")
    lo, hi = 0.0, 1.0
    for _ in range(200):
        mid = 0.5 * (lo + hi)
        if mh365_betai(aa, bb, mid) < qq:
            lo = mid
        else:
            hi = mid
    return 0.5 * (lo + hi)


def mh365_beta_pdf(a, b, x):
    import math
    aa = mh365_num(a, "a")
    bb = mh365_num(b, "b")
    xx = mh365_num(x, "x")
    if aa <= 0.0 or bb <= 0.0:
        raise ValueError("a, b: devono essere > 0")
    if xx <= 0.0 or xx >= 1.0:
        return 0.0
    lp = (math.lgamma(aa + bb) - math.lgamma(aa) - math.lgamma(bb)
          + (aa - 1.0) * math.log(xx) + (bb - 1.0) * math.log(1.0 - xx))
    return math.exp(lp)


def mh365_posterior(k, n):
    kk = mh365_int(k, "k", 0)
    nn = mh365_int(n, "n", 1)
    if kk > nn:
        raise ValueError("k: non puo' superare n")
    a = kk + 1
    b = nn - kk + 1
    return {"k": kk, "n": nn, "a": a, "b": b,
            "p_hat": a / (a + b)}


def mh365_p_low(k, n, alpha):
    al = mh365_num(alpha, "alpha")
    if not 0.0 < al <= 0.5:
        raise ValueError("alpha: deve stare in (0, 0.5]")
    post = mh365_posterior(k, n)
    return mh365_beta_ppf(al, post["a"], post["b"])


def mh365_fstar(p, b):
    pp = mh365_num(p, "p")
    bb = mh365_num(b, "b")
    if not 0.0 < pp < 1.0:
        raise ValueError("p: deve stare in (0, 1)")
    if bb <= 0.0:
        raise ValueError("b: deve essere > 0")
    return max((pp * bb - (1.0 - pp)) / bb, 0.0)


def mh365_haircut(f_hat, f_low):
    fh = mh365_num(f_hat, "f_hat")
    fl = mh365_num(f_low, "f_low")
    if fh < 0.0 or fl < 0.0:
        raise ValueError("f_hat, f_low: devono essere >= 0")
    if fh <= 0.0:
        return 1.0
    return max(min(fl / fh, 1.0), 0.0)


def mh365_verdetto(f_hat, haircut):
    fh = mh365_num(f_hat, "f_hat")
    hc = mh365_num(haircut, "haircut")
    if not 0.0 <= hc <= 1.0:
        raise ValueError("haircut: deve stare in [0, 1]")
    if fh <= 0.0:
        return "NESSUN EDGE: f* sulla p stimata = 0, nessun sizing."
    if hc >= 0.80:
        return (f"STIMA SOLIDA: haircut {hc:.0%} — la stima di p e' "
                f"affidabile, puoi usare fino a f* = {fh:.2%}.")
    if hc >= 0.60:
        return (f"STIMA INCERTA: haircut {hc:.0%} — riduci il sizing "
                f"verso il Kelly prudente (f* {fh:.2%} -> "
                f"{fh * hc:.2%}).")
    return (f"STIMA FRAGILE: haircut {hc:.0%} — il campione e' troppo "
            f"piccolo per fidarsi di f* = {fh:.2%}: raccogli piu' trade "
            f"o usa il Kelly prudente ({fh * hc:.2%}).")


def mh365_posterior_grid(k, n, m=51):
    kk = mh365_int(k, "k", 0)
    nn = mh365_int(n, "n", 1)
    if kk > nn:
        raise ValueError("k: non puo' superare n")
    mm = int(m)
    if mm < 5:
        raise ValueError("m: almeno 5 punti")
    post = mh365_posterior(kk, nn)
    out = []
    for i in range(mm):
        x = i / (mm - 1)
        out.append({"p": x,
                    "d": mh365_beta_pdf(post["a"], post["b"], x)})
    return out


def mh365_analisi(k, n, b, alpha):
    bb = mh365_num(b, "b")
    if bb <= 0.0:
        raise ValueError("b: deve essere > 0")
    post = mh365_posterior(k, n)
    p_hat = post["p_hat"]
    p_low = mh365_p_low(k, n, alpha)
    f_hat = mh365_fstar(p_hat, bb)
    f_low = mh365_fstar(p_low, bb)
    hc = mh365_haircut(f_hat, f_low)
    return {"k": post["k"], "n": post["n"], "a": post["a"], "b": post["b"],
            "alpha": float(alpha), "p_hat": p_hat, "p_low": p_low,
            "f_hat": f_hat, "f_low": f_low, "half_kelly": f_hat / 2.0,
            "haircut": hc, "verdetto": mh365_verdetto(f_hat, hc)}

def mh364_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh364_parse_seq(s):
    if not isinstance(s, str):
        raise ValueError("seq: deve essere una stringa")
    t = s.strip().upper().replace(" ", "").replace(",", "")
    if not t:
        raise ValueError("seq: vuota")
    bad = sorted({ch for ch in t if ch not in "WL"})
    if bad:
        raise ValueError(f"seq: caratteri non validi {bad} (solo W/L)")
    return tuple(t)


def mh364_fstar_sl(p, b, L):
    pp = mh364_num(p, "p")
    bb = mh364_num(b, "b")
    ll = mh364_num(L, "L")
    if not 0.0 < pp < 1.0:
        raise ValueError("p: deve stare in (0, 1)")
    if bb <= 0.0:
        raise ValueError("b: deve essere > 0")
    if not 0.0 < ll <= 1.0:
        raise ValueError("L: deve stare in (0, 1]")
    return max((pp * bb - (1.0 - pp) * ll) / (ll * bb), 0.0)


def mh364_g_sl(f, p, b, L):
    import math
    ff = mh364_num(f, "f")
    pp = mh364_num(p, "p")
    bb = mh364_num(b, "b")
    ll = mh364_num(L, "L")
    if not 0.0 <= ff < 1.0 / ll:
        raise ValueError("f: deve stare in [0, 1/L)")
    if not 0.0 < pp < 1.0:
        raise ValueError("p: deve stare in (0, 1)")
    if bb <= 0.0:
        raise ValueError("b: deve essere > 0")
    if not 0.0 < ll <= 1.0:
        raise ValueError("L: deve stare in (0, 1]")
    return pp * math.log(1.0 + ff * bb) + (1.0 - pp) * math.log(1.0 - ff * ll)


def mh364_cap(f, f_cap):
    ff = mh364_num(f, "f")
    fc = mh364_num(f_cap, "f_cap")
    if ff < 0.0:
        raise ValueError("f: deve essere >= 0")
    if not 0.0 < fc < 1.0:
        raise ValueError("f_cap: deve stare in (0, 1)")
    return min(ff, fc)


def mh364_lotti(f, lot):
    import math
    ff = mh364_num(f, "f")
    lt = mh364_num(lot, "lot")
    if ff < 0.0:
        raise ValueError("f: deve essere >= 0")
    if not 0.0 < lt <= 1.0:
        raise ValueError("lot: deve stare in (0, 1]")
    return math.floor(ff / lt + 1e-9) * lt


def mh364_dd_mult(dd, dd_max):
    d = mh364_num(dd, "dd")
    dm = mh364_num(dd_max, "dd_max")
    if d < 0.0:
        raise ValueError("dd: deve essere >= 0")
    if dm <= 0.0:
        raise ValueError("dd_max: deve essere > 0")
    if d >= dm:
        return 0.0
    return 1.0 - d / dm


def mh364_bindings(f_star, f_dopo_cap, f_dopo_lotti, dd_m):
    fs = mh364_num(f_star, "f_star")
    fc = mh364_num(f_dopo_cap, "f_dopo_cap")
    fl = mh364_num(f_dopo_lotti, "f_dopo_lotti")
    m = mh364_num(dd_m, "dd_m")
    out = []
    if fc < fs - 1e-12:
        out.append("cap")
    if fl < fc - 1e-12:
        out.append("lotti")
    if m < 1.0 - 1e-12:
        out.append("drawdown")
    return out


def mh364_verdetto(f_star, f_fin, g_ratio, bindings):
    fs = mh364_num(f_star, "f_star")
    ff = mh364_num(f_fin, "f_fin")
    gr = mh364_num(g_ratio, "g_ratio")
    if not isinstance(bindings, (list, tuple)):
        raise ValueError("bindings: deve essere una lista")
    if fs <= 0.0:
        return "NESSUN EDGE: f* con stop-loss = 0, nessun sizing."
    if not bindings:
        return (f"NON VINCOLANTI: nessun vincolo attivo, "
                f"il sizing resta f* = {fs:.2%}.")
    bl = ", ".join(bindings)
    if gr >= 0.95:
        return (f"VINCOLI LEGGERI ({bl}): il tasso di crescita resta "
                f"il {gr:.1%} dell'ottimo (f* {fs:.2%} -> {ff:.2%}).")
    if gr >= 0.75:
        return (f"VINCOLI SIGNIFICATIVI ({bl}): il tasso di crescita "
                f"scende al {gr:.1%} dell'ottimo (f* {fs:.2%} -> {ff:.2%}).")
    return (f"VINCOLI FORTI ({bl}): il tasso di crescita crolla al "
            f"{gr:.1%} dell'ottimo (f* {fs:.2%} -> {ff:.2%}). "
            f"Valuta se tutti i vincoli sono davvero necessari.")


def mh364_walk(seq, f, b, L):
    ff = mh364_num(f, "f")
    bb = mh364_num(b, "b")
    ll = mh364_num(L, "L")
    if not 0.0 <= ff < 1.0 / ll:
        raise ValueError("f: deve stare in [0, 1/L)")
    if bb <= 0.0:
        raise ValueError("b: deve essere > 0")
    if not 0.0 < ll <= 1.0:
        raise ValueError("L: deve stare in (0, 1]")
    mult = {"W": 1.0 + ff * bb, "L": 1.0 - ff * ll}
    eq = [1.0]
    peak = 1.0
    max_dd = 0.0
    for ch in seq:
        v = eq[-1] * mult[ch]
        eq.append(v)
        if v > peak:
            peak = v
        dd = 1.0 - v / peak
        if dd > max_dd:
            max_dd = dd
    return {"equity": eq, "finale": eq[-1], "max_dd": max_dd,
            "n": len(seq)}


def mh364_curva(p, b, L, f_hi, n=25):
    pp = mh364_num(p, "p")
    bb = mh364_num(b, "b")
    ll = mh364_num(L, "L")
    fh = mh364_num(f_hi, "f_hi")
    nn = int(n)
    if not 0.0 < pp < 1.0:
        raise ValueError("p: deve stare in (0, 1)")
    if bb <= 0.0:
        raise ValueError("b: deve essere > 0")
    if not 0.0 < ll <= 1.0:
        raise ValueError("L: deve stare in (0, 1]")
    if not 0.0 < fh < 1.0 / ll:
        raise ValueError("f_hi: deve stare in (0, 1/L)")
    if nn < 2:
        raise ValueError("n: almeno 2 punti")
    return [{"f": fh * i / (nn - 1),
             "g": mh364_g_sl(fh * i / (nn - 1), pp, bb, ll)}
            for i in range(nn)]


def mh364_analisi(p, b, L, f_cap, lot, dd, dd_max, seq):
    pp = mh364_num(p, "p")
    bb = mh364_num(b, "b")
    ll = mh364_num(L, "L")
    fc = mh364_num(f_cap, "f_cap")
    lt = mh364_num(lot, "lot")
    d = mh364_num(dd, "dd")
    dm = mh364_num(dd_max, "dd_max")
    if not 0.0 < pp < 1.0:
        raise ValueError("p: deve stare in (0, 1)")
    if bb <= 0.0:
        raise ValueError("b: deve essere > 0")
    if not 0.0 < ll <= 1.0:
        raise ValueError("L: deve stare in (0, 1]")
    if not 0.0 < fc < 1.0:
        raise ValueError("f_cap: deve stare in (0, 1)")
    if not 0.0 < lt <= 1.0:
        raise ValueError("lot: deve stare in (0, 1]")
    if d < 0.0:
        raise ValueError("dd: deve essere >= 0")
    if dm <= 0.0:
        raise ValueError("dd_max: deve essere > 0")
    sq = mh364_parse_seq(seq)
    f1 = mh364_fstar_sl(pp, bb, ll)
    f2 = mh364_cap(f1, fc)
    f3 = mh364_lotti(f2, lt)
    m = mh364_dd_mult(d, dm)
    f4 = f3 * m
    g1 = mh364_g_sl(f1, pp, bb, ll)
    g4 = mh364_g_sl(f4, pp, bb, ll)
    gr = g4 / g1 if g1 > 0.0 else 1.0
    bd = mh364_bindings(f1, f2, f3, m)
    wk = mh364_walk(sq, f1, bb, ll)
    wv = mh364_walk(sq, f4, bb, ll)
    return {"p": pp, "b": bb, "L": ll, "f_cap": fc, "lot": lt,
            "dd": d, "dd_max": dm,
            "f_star": f1, "f_dopo_cap": f2, "f_dopo_lotti": f3,
            "dd_mult": m, "f_fin": f4,
            "g_star": g1, "g_fin": g4, "g_ratio": gr,
            "bindings": bd,
            "verdetto": mh364_verdetto(f1, f4, gr, bd),
            "eqk": wk["equity"], "eqv": wv["equity"],
            "finalek": wk["finale"], "finalev": wv["finale"],
            "ddk": wk["max_dd"], "ddv": wv["max_dd"], "n": wk["n"],
            "seq": "".join(sq)}

def mh363_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh363_parse_seq(s):
    if not isinstance(s, str):
        raise ValueError("seq: deve essere una stringa")
    t = s.strip().upper().replace(" ", "").replace(",", "")
    if not t:
        raise ValueError("seq: vuota")
    bad = sorted({ch for ch in t if ch not in "WL"})
    if bad:
        raise ValueError(f"seq: caratteri non validi {bad} (solo W/L)")
    return tuple(t)


def mh363_g(f, p, b):
    import math
    ff = mh363_num(f, "f")
    if not 0.0 <= ff < 1.0:
        raise ValueError("f: deve stare in [0, 1)")
    return p * math.log(1.0 + ff * b) + (1.0 - p) * math.log(1.0 - ff)


def mh363_fstar(p, b):
    pp = mh363_num(p, "p")
    bb = mh363_num(b, "b")
    if not 0.0 < pp < 1.0:
        raise ValueError("p: deve stare in (0, 1)")
    if bb <= 0.0:
        raise ValueError("b: deve essere > 0")
    return max((pp * bb - (1.0 - pp)) / bb, 0.0)


def mh363_feff(f_kelly, f_max):
    fk = mh363_num(f_kelly, "f_kelly")
    fm = mh363_num(f_max, "f_max")
    if fk < 0.0:
        raise ValueError("f_kelly: deve essere >= 0")
    if not 0.0 < fm < 1.0:
        raise ValueError("f_max: deve stare in (0, 1)")
    return min(fk, fm)


def mh363_verdetto(f_kelly, f_max, f_eff, g_ratio):
    fk = mh363_num(f_kelly, "f_kelly")
    fm = mh363_num(f_max, "f_max")
    fe = mh363_num(f_eff, "f_eff")
    gr = mh363_num(g_ratio, "g_ratio")
    if fk <= 0.0:
        return ("NESSUN EDGE: f* di Kelly = 0, il cap e' irrilevante.")
    if fk <= fm:
        return (f"CAP NON VINCOLANTE: f* = {fk:.2%} <= cap {fm:.2%}, "
                f"il sizing resta quello di Kelly.")
    if gr >= 0.95:
        return (f"VINCOLO LEGGERO: cap {fm:.2%} su f* {fk:.2%}, "
                f"il tasso di crescita resta il {gr:.1%} dell'ottimo.")
    if gr >= 0.75:
        return (f"VINCOLO SIGNIFICATIVO: cap {fm:.2%} su f* {fk:.2%}, "
                f"il tasso di crescita scende al {gr:.1%} dell'ottimo "
                f"({fe:.2%} invece di {fk:.2%}).")
    return (f"VINCOLO FORTE: cap {fm:.2%} su f* {fk:.2%} taglia il tasso "
            f"di crescita al {gr:.1%} dell'ottimo. "
            f"Valuta se il limite e' davvero necessario.")


def mh363_walk(seq, f, b):
    ff = mh363_num(f, "f")
    bb = mh363_num(b, "b")
    if not 0.0 <= ff < 1.0:
        raise ValueError("f: deve stare in [0, 1)")
    if bb <= 0.0:
        raise ValueError("b: deve essere > 0")
    mult = {"W": 1.0 + ff * bb, "L": 1.0 - ff}
    eq = [1.0]
    peak = 1.0
    max_dd = 0.0
    for ch in seq:
        v = eq[-1] * mult[ch]
        eq.append(v)
        if v > peak:
            peak = v
        dd = 1.0 - v / peak
        if dd > max_dd:
            max_dd = dd
    return {"equity": eq, "finale": eq[-1], "max_dd": max_dd,
            "n": len(seq)}


def mh363_curva(p, b, f_max_grid, n=25):
    pp = mh363_num(p, "p")
    bb = mh363_num(b, "b")
    fm = mh363_num(f_max_grid, "f_max_grid")
    nn = int(n)
    if not 0.0 < pp < 1.0:
        raise ValueError("p: deve stare in (0, 1)")
    if bb <= 0.0:
        raise ValueError("b: deve essere > 0")
    if not 0.0 < fm < 1.0:
        raise ValueError("f_max_grid: deve stare in (0, 1)")
    if nn < 2:
        raise ValueError("n: almeno 2 punti")
    return [{"f": fm * i / (nn - 1),
             "g": mh363_g(fm * i / (nn - 1), pp, bb)}
            for i in range(nn)]


def mh363_analisi(p, b, f_max, seq):
    pp = mh363_num(p, "p")
    bb = mh363_num(b, "b")
    fm = mh363_num(f_max, "f_max")
    if not 0.0 < pp < 1.0:
        raise ValueError("p: deve stare in (0, 1)")
    if bb <= 0.0:
        raise ValueError("b: deve essere > 0")
    if not 0.0 < fm < 1.0:
        raise ValueError("f_max: deve stare in (0, 1)")
    sq = mh363_parse_seq(seq)
    fk = mh363_fstar(pp, bb)
    fe = mh363_feff(fk, fm)
    gk = mh363_g(fk, pp, bb)
    ge = mh363_g(fe, pp, bb)
    gr = ge / gk if gk > 0.0 else 1.0
    wk = mh363_walk(sq, fk, bb)
    we = mh363_walk(sq, fe, bb)
    return {"p": pp, "b": bb, "f_max": fm, "f_kelly": fk, "f_eff": fe,
            "g_kelly": gk, "g_eff": ge, "g_ratio": gr,
            "verdetto": mh363_verdetto(fk, fm, fe, gr),
            "eqk": wk["equity"], "eqe": we["equity"],
            "finalek": wk["finale"], "finalee": we["finale"],
            "ddk": wk["max_dd"], "dde": we["max_dd"], "n": wk["n"],
            "seq": "".join(sq)}

def mh362_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh362_parse_seq(s):
    if not isinstance(s, str):
        raise ValueError("seq: deve essere una stringa")
    t = s.strip().upper().replace(" ", "").replace(",", "")
    if not t:
        raise ValueError("seq: vuota")
    bad = sorted({ch for ch in t if ch not in "WML"})
    if bad:
        raise ValueError(f"seq: caratteri non validi {bad} (solo W/M/L)")
    return tuple(t)


def mh362_g(f, p_w, p_m, p_l, b, m):
    import math
    ff = mh362_num(f, "f")
    if not 0.0 <= ff < 1.0:
        raise ValueError("f: deve stare in [0, 1)")
    return (p_w * math.log(1.0 + ff * b) + p_m * math.log(1.0 - ff * m)
            + p_l * math.log(1.0 - ff))


def mh362_gbin(f, p_w, p_l2, b):
    import math
    ff = mh362_num(f, "f")
    if not 0.0 <= ff < 1.0:
        raise ValueError("f: deve stare in [0, 1)")
    return p_w * math.log(1.0 + ff * b) + p_l2 * math.log(1.0 - ff)


def mh362_gprime0(p_w, p_m, p_l, b, m):
    return p_w * b - p_m * m - p_l


def mh362_fstar(p_w, p_m, p_l, b, m):
    pw = mh362_num(p_w, "p_w")
    pm = mh362_num(p_m, "p_m")
    pl = mh362_num(p_l, "p_l")
    bb = mh362_num(b, "b")
    mm = mh362_num(m, "m")
    if bb <= 0.0:
        raise ValueError("b: deve essere > 0")
    if not 0.0 < mm < 1.0:
        raise ValueError("m: deve stare in (0, 1)")
    if mh362_gprime0(pw, pm, pl, bb, mm) <= 0.0:
        return 0.0, 0.0
    import math
    lo, hi = 0.0, 1.0 - 1e-9
    gr = (math.sqrt(5.0) - 1.0) / 2.0
    c = hi - gr * (hi - lo)
    d = lo + gr * (hi - lo)
    gc = mh362_g(c, pw, pm, pl, bb, mm)
    gd = mh362_g(d, pw, pm, pl, bb, mm)
    for _ in range(200):
        if gc < gd:
            lo, c, gc = c, d, gd
            d = lo + gr * (hi - lo)
            gd = mh362_g(d, pw, pm, pl, bb, mm)
        else:
            hi, d, gd = d, c, gc
            c = hi - gr * (hi - lo)
            gc = mh362_g(c, pw, pm, pl, bb, mm)
    f = 0.5 * (lo + hi)
    return f, mh362_g(f, pw, pm, pl, bb, mm)


def mh362_fstar_bin(p_w, p_l2, b):
    pw = mh362_num(p_w, "p_w")
    pl2 = mh362_num(p_l2, "p_l2")
    bb = mh362_num(b, "b")
    if bb <= 0.0:
        raise ValueError("b: deve essere > 0")
    return max((pw * bb - pl2) / bb, 0.0)


def mh362_verdetto(f3, fbin):
    a = mh362_num(f3, "f3")
    c = mh362_num(fbin, "fbin")
    if a <= 0.0:
        return ("NESSUN EDGE: con tre esiti non c'e' edge sfruttabile "
                "(g'(0) <= 0, f* = 0).")
    if c <= 0.0:
        return (f"BINARIO INUTILIZZABILE: il modello binario vede edge <= 0 "
                f"(f*_bin = 0) ma con tre esiti f* = {a:.2%}.")
    r = a / c
    if r >= 1.5:
        return (f"BINARIO CONSERVATIVO: il modello a 2 esiti sottostima f* "
                f"({c:.2%} vs {a:.2%} con tre esiti, {r:.2f}x). "
                f"Stai puntando troppo poco.")
    if r >= 1.05:
        return (f"DIFFERENZA MODERATA: tre esiti danno f* = {a:.2%} contro "
                f"{c:.2%} del binario ({r:.2f}x).")
    if r >= 0.95:
        return (f"BINARIO ADEGUATO: f* tre esiti {a:.2%} ~ f* binario {c:.2%}. "
                f"L'approssimazione a 2 esiti basta.")
    if r >= 0.70:
        return (f"DIFFERENZA MODERATA: tre esiti danno f* = {a:.2%} contro "
                f"{c:.2%} del binario ({r:.2f}x).")
    return (f"BINARIO AGGRESSIVO: il modello a 2 esiti sovrastima f* "
            f"({c:.2%} vs {a:.2%} con tre esiti, {r:.2f}x). "
            f"Stai rischiando troppo.")


def mh362_walk(seq, f, b, m):
    ff = mh362_num(f, "f")
    bb = mh362_num(b, "b")
    mm = mh362_num(m, "m")
    if not 0.0 <= ff < 1.0:
        raise ValueError("f: deve stare in [0, 1)")
    if bb <= 0.0:
        raise ValueError("b: deve essere > 0")
    if not 0.0 < mm < 1.0:
        raise ValueError("m: deve stare in (0, 1)")
    mult = {"W": 1.0 + ff * bb, "M": 1.0 - ff * mm, "L": 1.0 - ff}
    eq = [1.0]
    peak = 1.0
    max_dd = 0.0
    for ch in seq:
        v = eq[-1] * mult[ch]
        eq.append(v)
        if v > peak:
            peak = v
        dd = 1.0 - v / peak
        if dd > max_dd:
            max_dd = dd
    return {"equity": eq, "finale": eq[-1], "max_dd": max_dd,
            "n": len(seq)}


def mh362_curva(p_w, p_m, p_l, b, m, f_max, n=25):
    pw = mh362_num(p_w, "p_w")
    pm = mh362_num(p_m, "p_m")
    pl = mh362_num(p_l, "p_l")
    bb = mh362_num(b, "b")
    mm = mh362_num(m, "m")
    fm = mh362_num(f_max, "f_max")
    nn = int(n)
    if not 0.0 < fm < 1.0:
        raise ValueError("f_max: deve stare in (0, 1)")
    if nn < 2:
        raise ValueError("n: almeno 2 punti")
    out = []
    for i in range(nn):
        f = fm * i / (nn - 1)
        out.append({"f": f,
                    "g_3esiti": mh362_g(f, pw, pm, pl, bb, mm),
                    "g_binario": mh362_gbin(f, pw, pm + pl, bb)})
    return out


def mh362_analisi(p_w, p_m, b, m, seq):
    pw = mh362_num(p_w, "p_w")
    pm = mh362_num(p_m, "p_m")
    bb = mh362_num(b, "b")
    mm = mh362_num(m, "m")
    if not 0.0 <= pw <= 1.0:
        raise ValueError("p_w: deve stare in [0, 1]")
    if not 0.0 <= pm <= 1.0:
        raise ValueError("p_m: deve stare in [0, 1]")
    if pw + pm > 1.0:
        raise ValueError("p_w + p_m deve essere <= 1")
    if bb <= 0.0:
        raise ValueError("b: deve essere > 0")
    if not 0.0 < mm < 1.0:
        raise ValueError("m: deve stare in (0, 1)")
    pl = 1.0 - pw - pm
    sq = mh362_parse_seq(seq)
    f3, g3 = mh362_fstar(pw, pm, pl, bb, mm)
    fbin = mh362_fstar_bin(pw, pm + pl, bb)
    gbin = mh362_gbin(fbin, pw, pm + pl, bb)
    w3 = mh362_walk(sq, f3, bb, mm)
    wb = mh362_walk(sq, fbin, bb, mm)
    return {"p_w": pw, "p_m": pm, "p_l": pl, "b": bb, "m": mm,
            "f3": f3, "g3": g3, "fbin": fbin, "gbin": gbin,
            "verdetto": mh362_verdetto(f3, fbin),
            "eq3": w3["equity"], "eqb": wb["equity"],
            "finale3": w3["finale"], "finaleb": wb["finale"],
            "dd3": w3["max_dd"], "ddb": wb["max_dd"], "n": w3["n"],
            "seq": "".join(sq)}

def mh361_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh361_kelly(p, b):
    pp = mh361_num(p, "p")
    bb = mh361_num(b, "b")
    if not 0.0 <= pp <= 1.0:
        raise ValueError("p: deve stare in [0, 1]")
    if bb <= 0.0:
        raise ValueError("b: deve essere > 0")
    return max((pp * bb - (1.0 - pp)) / bb, 0.0)


def mh361_griglia(f, b, dd_max, goal_mult):
    """Discretizza il random walk log in unita' di down-step.

    Ritorna n_livelli (N, barriera assorbente target), k (livello di
    partenza, barriera rovina in 0), up (passi su per vincita),
    goal_steps (vincite nette per il target). Se N > 600 raddoppia
    l'unita' finche' la griglia resta trattabile.
    """
    import math
    ff = mh361_num(f, "f")
    bb = mh361_num(b, "b")
    dd = mh361_num(dd_max, "drawdown max")
    gm = mh361_num(goal_mult, "target")
    if not 0.0 < ff < 1.0:
        raise ValueError("f: deve stare in (0, 1)")
    if bb <= 0.0:
        raise ValueError("b: deve essere > 0")
    if not 0.0 < dd < 1.0:
        raise ValueError("drawdown max: deve stare in (0, 1)")
    if gm <= 1.0:
        raise ValueError("target: deve essere > 1")
    d = -math.log(1.0 - ff)
    u = math.log(1.0 + ff * bb)
    B = -math.log(1.0 - dd)
    G = math.log(gm)
    unit = d
    for _ in range(10):
        k = max(1, int(round(B / unit)))
        up = max(1, int(round(u / unit)))
        gs = max(1, int(round(G / u)))
        N = k + up * gs
        if N <= 600:
            break
        unit *= 2.0
    return {"n_livelli": N, "k": k, "up": up, "goal_steps": gs}


def mh361_rischio(p, b, f, dd_max, goal_mult):
    """P(rovina) e trade attesi all'assorbimento via value iteration."""
    pp = mh361_num(p, "p")
    bb = mh361_num(b, "b")
    ff = mh361_num(f, "f")
    dd = mh361_num(dd_max, "drawdown max")
    gm = mh361_num(goal_mult, "target")
    if not 0.0 <= pp <= 1.0:
        raise ValueError("p: deve stare in [0, 1]")
    if bb <= 0.0:
        raise ValueError("b: deve essere > 0")
    if not 0.0 <= ff < 1.0:
        raise ValueError("f: deve stare in [0, 1)")
    if not 0.0 < dd < 1.0:
        raise ValueError("drawdown max: deve stare in (0, 1)")
    if gm <= 1.0:
        raise ValueError("target: deve essere > 1")
    base = {"p": pp, "b": bb, "f": ff, "dd_max": dd, "goal_mult": gm}
    if ff == 0.0:
        # nessuna puntata: l'equity non si muove mai
        return dict(base, ror=0.0, trades_attesi=float("inf"),
                    n_livelli=0, k=0, up=0, goal_steps=0)
    gr = mh361_griglia(ff, bb, dd, gm)
    N, k, up = gr["n_livelli"], gr["k"], gr["up"]
    q = 1.0 - pp
    P = [0.0] * (N + 1)
    P[0] = 1.0
    for _ in range(20000):
        delta = 0.0
        for i in range(1, N):
            j = i + up
            if j > N:
                j = N
            v = q * P[i - 1] + pp * P[j]
            dv = abs(v - P[i])
            if dv > delta:
                delta = dv
            P[i] = v
        if delta < 1e-13:
            break
    E = [0.0] * (N + 1)
    for _ in range(20000):
        delta = 0.0
        for i in range(1, N):
            j = i + up
            if j > N:
                j = N
            v = 1.0 + q * E[i - 1] + pp * E[j]
            dv = abs(v - E[i])
            if dv > delta:
                delta = dv
            E[i] = v
        if delta < 1e-13:
            break
    return dict(base, ror=P[k], trades_attesi=E[k],
                n_livelli=N, k=k, up=up, goal_steps=gr["goal_steps"])


def mh361_verdetto(ror, edge):
    rr = mh361_num(ror, "P(rovina)")
    ee = mh361_num(edge, "edge")
    if not 0.0 <= rr <= 1.0:
        raise ValueError("P(rovina): deve stare in [0, 1]")
    nota_edge = ""
    if ee <= 0.0:
        nota_edge = (f" Attenzione: edge {ee:+.2f} per unita' puntata "
                     "(<= 0): il drift e' nullo o negativo, sul lungo "
                     "periodo la rovina e' quasi certa anche partendo da "
                     "qui. Rivedi il setup prima del sizing.")
    if rr >= 0.25:
        return (f"CRITICO: P(rovina) = {rr:.1%}: piu' di 1 volta su 4 "
                f"tocchi il drawdown massimo prima del target. Riduci f "
                f"subito o alza il target: questo sizing non e' "
                f"sostenibile.{nota_edge}")
    if rr >= 0.10:
        return (f"ELEVATO: P(rovina) = {rr:.1%}: quasi 1 volta su 5 "
                f"o piu' finisci sul drawdown massimo prima del target. "
                f"Considera di dimezzare f: la curva qui sotto mostra "
                f"quanto scende il rischio.{nota_edge}")
    if rr >= 0.05:
        return (f"MODERATO: P(rovina) = {rr:.1%}: rischio non trascurabile "
                f"ma gestibile se il drawdown massimo e' davvero "
                f"sopportabile. Non alzare f oltre questo punto.{nota_edge}")
    if rr >= 0.01:
        return (f"CONTENUTO: P(rovina) = {rr:.1%}: il sizing e' prudente, "
                f"la rovina prima del target e' un evento raro. Hai "
                f"margine per salire un po' con f se cerchi piu' "
                f"crescita.{nota_edge}")
    return (f"TRASCURABILE: P(rovina) = {rr:.2%}: con questo sizing "
            f"toccare il drawdown massimo prima del target e' quasi "
            f"impossibile. Stai pagando il rischio con crescita molto "
            f"lenta: valuta se alzare f.{nota_edge}")


def mh361_curva(p, b, dd_max, goal_mult, f_max, n=25):
    """P(rovina) su una griglia di n valori di f in (0, f_max]."""
    pp = mh361_num(p, "p")
    bb = mh361_num(b, "b")
    dd = mh361_num(dd_max, "drawdown max")
    gm = mh361_num(goal_mult, "target")
    fm = mh361_num(f_max, "f_max")
    nn = mh361_num(n, "n")
    if not 0.0 <= pp <= 1.0:
        raise ValueError("p: deve stare in [0, 1]")
    if bb <= 0.0:
        raise ValueError("b: deve essere > 0")
    if not 0.0 < dd < 1.0:
        raise ValueError("drawdown max: deve stare in (0, 1)")
    if gm <= 1.0:
        raise ValueError("target: deve essere > 1")
    if fm <= 0.0 or fm >= 1.0:
        raise ValueError("f_max: deve stare in (0, 1)")
    ni = int(nn)
    if ni < 3:
        raise ValueError("n: almeno 3 punti")
    out = []
    for i in range(ni):
        ff = fm * (i + 1) / ni
        out.append({"f": ff,
                    "ror": mh361_rischio(pp, bb, ff, dd, gm)["ror"]})
    return out


def mh361_analisi(p, b, f, dd_max, goal_mult):
    pp = mh361_num(p, "p")
    bb = mh361_num(b, "b")
    r = mh361_rischio(pp, bb, f, dd_max, goal_mult)
    edge = pp * bb - (1.0 - pp)
    r["edge"] = edge
    r["f_star"] = mh361_kelly(pp, bb)
    r["verdetto"] = mh361_verdetto(r["ror"], edge)
    return r

def mh360_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh360_parse_seq(s):
    if not isinstance(s, str):
        raise ValueError("sequenza: deve essere una stringa")
    out = []
    for ch in s:
        if ch in "Ww1":
            out.append(1)
        elif ch in "Ll0":
            out.append(0)
        elif ch in " ,;|-\t\n":
            continue
        else:
            raise ValueError(
                f"sequenza: carattere non valido {ch!r} "
                "(usa W/L oppure 1/0)")
    if not out:
        raise ValueError("sequenza: nessun esito valido")
    return tuple(out)


def mh360_kelly(p, b):
    pp = mh360_num(p, "p")
    bb = mh360_num(b, "b")
    if not 0.0 <= pp <= 1.0:
        raise ValueError("p: deve stare in [0, 1]")
    if bb <= 0.0:
        raise ValueError("b: deve essere > 0")
    return max((pp * bb - (1.0 - pp)) / bb, 0.0)


def mh360_verdetto(p, b, lam):
    pp = mh360_num(p, "p")
    bb = mh360_num(b, "b")
    ll = mh360_num(lam, "λ")
    if not 0.0 <= pp <= 1.0:
        raise ValueError("p: deve stare in [0, 1]")
    if bb <= 0.0:
        raise ValueError("b: deve essere > 0")
    if ll <= 0.0:
        raise ValueError("λ: deve essere > 0")
    qq = 1.0 - pp
    edge = pp * bb - qq
    if edge <= 0.0:
        return ("NESSUN EDGE: il valore atteso per unita' puntata e' "
                f"{edge:+.2f} (<= 0): nessuna frazione di Kelly lo salva, "
                "f* = 0. Il sizing frazionario non crea un edge che non "
                "c'e'. Rivedi il setup.")
    if ll > 1.0:
        return (f"LEVA: λ = {ll:.2f} sopra 1: punti OLTRE il Kelly pieno "
                f"(f* = {edge / bb:.2%} -> f_eff = {ll * edge / bb:.2%}): "
                "l'overbetting riduce la crescita attesa e amplifica il "
                "drawdown rispetto al Kelly pieno. Torna a λ <= 1.")
    if ll >= 0.95:
        return (f"FULL-KELLY: λ = {ll:.2f} ~ 1: crescita teorica massima "
                f"(f* = {edge / bb:.2%}), ma drawdown atteso profondo e "
                "volatilita' massima. Va bene solo con stime di p e b "
                "molto affidabili; al primo dubbio scendi a 0.5.")
    if ll >= 0.45:
        return (f"HALF-KELLY: λ = {ll:.2f} e' il compromesso classico: "
                "circa il 75% della crescita attesa del Kelly pieno con "
                "circa meta' del drawdown e della volatilita'. La scelta "
                "standard quando le stime di win-rate e payoff sono "
                "incerte.")
    return (f"FRAZIONE PRUDENTE: λ = {ll:.2f} sotto 0.45: sizing molto "
            f"difensivo (f_eff = {ll * edge / bb:.2%} contro Kelly pieno "
            f"{edge / bb:.2%}): drawdown contenuto ma crescita sacrificata. "
            "Va bene per capitale che non puo' permettersi cali, "
            "altrimenti valuta di salire verso 0.5.")


def mh360_walk(seq, b, p, lam, equity0):
    bb = mh360_num(b, "b")
    pp = mh360_num(p, "p")
    ll = mh360_num(lam, "λ")
    eq0 = mh360_num(equity0, "equity0")
    if bb <= 0.0:
        raise ValueError("b: deve essere > 0")
    if not 0.0 <= pp <= 1.0:
        raise ValueError("p: deve stare in [0, 1]")
    if ll <= 0.0:
        raise ValueError("λ: deve essere > 0")
    if eq0 <= 0.0:
        raise ValueError("equity0: deve essere > 0")
    if not seq:
        raise ValueError("sequenza: vuota")
    for x in seq:
        if x not in (0, 1):
            raise ValueError("sequenza: valori 0/1")
    fk = mh360_kelly(pp, bb)
    fe = ll * fk
    eqf_path = [eq0]
    eqb_path = [eq0]
    righe = []
    eq_f = eq0
    eq_b = eq0
    for i, x in enumerate(seq):
        eq_f = eq_f * (1.0 + fe * bb) if x else eq_f * (1.0 - fe)
        eq_b = eq_b * (1.0 + fk * bb) if x else eq_b * (1.0 - fk)
        righe.append({"trade": i + 1, "esito": "W" if x else "L",
                      "eq_frac": eq_f, "eq_full": eq_b})
        eqf_path.append(eq_f)
        eqb_path.append(eq_b)
    n = len(seq)
    gap = eqf_path[-1] - eqb_path[-1]
    gap_pct = gap / eqb_path[-1] if eqb_path[-1] != 0 else 0.0
    growth_f = (eqf_path[-1] / eq0) ** (1.0 / n) - 1.0
    growth_b = (eqb_path[-1] / eq0) ** (1.0 / n) - 1.0
    max_dd_f = 1.0 - min(eqf_path[i] / max(eqf_path[:i + 1])
                         for i in range(len(eqf_path)))
    max_dd_b = 1.0 - min(eqb_path[i] / max(eqb_path[:i + 1])
                         for i in range(len(eqb_path)))
    return {"n": n, "n_wins": sum(seq), "f_eff": fe, "f_full": fk,
            "lam": ll, "eqf_path": eqf_path, "eqb_path": eqb_path,
            "eqf_fin": eqf_path[-1], "eqb_fin": eqb_path[-1],
            "gap": gap, "gap_pct": gap_pct,
            "growth_frac": growth_f, "growth_full": growth_b,
            "max_dd_frac": max_dd_f, "max_dd_full": max_dd_b,
            "righe": righe, "p": pp, "b": bb, "lam_out": ll,
            "equity0": eq0,
            "verdetto": mh360_verdetto(pp, bb, ll)}


def mh360_confronto(seq_s, b, p, lam, equity0):
    seq = mh360_parse_seq(seq_s)
    w = mh360_walk(seq, b, p, lam, equity0)
    w["seq_str"] = "".join("W" if x else "L" for x in seq)
    return w

def mh359_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh359_parse_seq(s):
    if not isinstance(s, str):
        raise ValueError("sequenza: deve essere una stringa")
    out = []
    for ch in s:
        if ch in "Ww1":
            out.append(1)
        elif ch in "Ll0":
            out.append(0)
        elif ch in " ,;|-\t\n":
            continue
        else:
            raise ValueError(
                f"sequenza: carattere non valido {ch!r} "
                "(usa W/L oppure 1/0)")
    if not out:
        raise ValueError("sequenza: nessun esito valido")
    return tuple(out)


def mh359_kelly_tp(p, t):
    pp = mh359_num(p, "p")
    tt = mh359_num(t, "t")
    if not 0.0 <= pp <= 1.0:
        raise ValueError("p: deve stare in [0, 1]")
    if tt <= 0.0:
        raise ValueError("t: deve essere > 0")
    edge = pp * tt - (1.0 - pp)
    return max(edge / tt, 0.0)


def mh359_kelly_base(p, b):
    pp = mh359_num(p, "p")
    bb = mh359_num(b, "b")
    if not 0.0 <= pp <= 1.0:
        raise ValueError("p: deve stare in [0, 1]")
    if bb <= 0.0:
        raise ValueError("b: deve essere > 0")
    return max((pp * bb - (1.0 - pp)) / bb, 0.0)


def mh359_verdetto(p, b, t):
    pp = mh359_num(p, "p")
    bb = mh359_num(b, "b")
    tt = mh359_num(t, "t")
    if not 0.0 <= pp <= 1.0:
        raise ValueError("p: deve stare in [0, 1]")
    if bb <= 0.0:
        raise ValueError("b: deve essere > 0")
    if tt <= 0.0:
        raise ValueError("t: deve essere > 0")
    qq = 1.0 - pp
    edge = pp * tt - qq
    if edge <= 0.0:
        return ("NESSUN EDGE: con il take-profit il valore atteso per "
                f"unita' puntata e' {edge:+.2f} (<= 0): nessun sizing lo "
                "salva, il take-profit non puo' creare un edge che non "
                "c'e'. Rivedi il setup.")
    if tt >= bb:
        fb0 = max((pp * bb - qq) / bb, 0.0)
        return (f"TP INUTILE: il take-profit a {tt:.2f}x la puntata e' sopra "
                "la vincita media dichiarata b: non tronca nulla e il "
                f"sizing resta quello base (f* {fb0:.2%}). Abbassa il "
                "take-profit sotto b per avere un effetto.")
    fk = edge / tt
    fb = max((pp * bb - qq) / bb, 0.0)
    r = fk / fb if fb > 0.0 else 0.0
    if r <= 0.5:
        return (f"TAGLIO FORTE: il take-profit a {tt:.2f}x dimezza il Kelly "
                f"(da {fb:.2%} a {fk:.2%}, rapporto {r:.2f}x): il TP "
                "mangia buona parte dell'edge. O accetti un sizing molto "
                "prudente, o allenti il take-profit per lasciare correre "
                "di piu' i profitti.")
    if r < 0.9:
        return (f"TAGLIO MODERATO: il take-profit a {tt:.2f}x porta il Kelly "
                f"da {fb:.2%} a {fk:.2%} (rapporto {r:.2f}x): edge ridotto "
                "ma sizing ancora applicabile, con margine di sicurezza "
                "sui cali di win-rate.")
    return (f"TAGLIO LEGGERO: il take-profit a {tt:.2f}x sfiora appena il "
            f"Kelly ({fb:.2%} -> {fk:.2%}, rapporto {r:.2f}x): il TP e' "
            "quasi ininfluente sul sizing, puoi trattarlo come se non "
            "ci fosse.")


def mh359_walk(seq, b, p, t, equity0):
    bb = mh359_num(b, "b")
    pp = mh359_num(p, "p")
    tt = mh359_num(t, "t")
    eq0 = mh359_num(equity0, "equity0")
    if bb <= 0.0:
        raise ValueError("b: deve essere > 0")
    if not 0.0 <= pp <= 1.0:
        raise ValueError("p: deve stare in [0, 1]")
    if tt <= 0.0:
        raise ValueError("t: deve essere > 0")
    if eq0 <= 0.0:
        raise ValueError("equity0: deve essere > 0")
    if not seq:
        raise ValueError("sequenza: vuota")
    for x in seq:
        if x not in (0, 1):
            raise ValueError("sequenza: valori 0/1")
    fk = mh359_kelly_tp(pp, tt)
    fb = mh359_kelly_base(pp, bb)
    eq_s = eq0
    eq_b = eq0
    eqs_path = [eq_s]
    eqb_path = [eq_b]
    righe = []
    for i, x in enumerate(seq):
        eq_s = eq_s * (1.0 + fk * tt) if x else eq_s * (1.0 - fk)
        eq_b = eq_b * (1.0 + fb * bb) if x else eq_b * (1.0 - fb)
        righe.append({"trade": i + 1, "esito": "W" if x else "L",
                      "eq_tp": eq_s, "eq_base": eq_b})
        eqs_path.append(eq_s)
        eqb_path.append(eq_b)
    gap = eqs_path[-1] - eqb_path[-1]
    gap_pct = gap / eqb_path[-1] if eqb_path[-1] != 0 else 0.0
    max_dd = 1.0 - min(eqs_path[i] / max(eqs_path[:i + 1])
                       for i in range(len(eqs_path)))
    ratio = fk / fb if fb > 0.0 else 0.0
    return {"n": len(seq), "n_wins": sum(seq), "f_tp": fk, "f_base": fb,
            "ratio": ratio, "eqs_path": eqs_path, "eqb_path": eqb_path,
            "eqs_fin": eqs_path[-1], "eqb_fin": eqb_path[-1],
            "gap": gap, "gap_pct": gap_pct, "max_dd_tp": max_dd,
            "righe": righe, "p": pp, "b": bb, "t": tt, "equity0": eq0,
            "verdetto": mh359_verdetto(pp, bb, tt)}


def mh359_confronto(seq_s, b, p, t, equity0):
    seq = mh359_parse_seq(seq_s)
    w = mh359_walk(seq, b, p, t, equity0)
    w["seq_str"] = "".join("W" if x else "L" for x in seq)
    return w

def mh358_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh358_parse_seq(s):
    if not isinstance(s, str):
        raise ValueError("sequenza: deve essere una stringa")
    out = []
    for ch in s:
        if ch in "Ww1":
            out.append(1)
        elif ch in "Ll0":
            out.append(0)
        elif ch in " ,;|-\t\n":
            continue
        else:
            raise ValueError(
                f"sequenza: carattere non valido {ch!r} "
                "(usa W/L oppure 1/0)")
    if not out:
        raise ValueError("sequenza: nessun esito valido")
    return tuple(out)


def mh358_kelly_stop(p, b, s):
    pp = mh358_num(p, "p")
    bb = mh358_num(b, "b")
    ss = mh358_num(s, "s")
    if not 0.0 <= pp <= 1.0:
        raise ValueError("p: deve stare in [0, 1]")
    if bb <= 0.0:
        raise ValueError("b: deve essere > 0")
    if ss <= 0.0:
        raise ValueError("s: deve essere > 0")
    edge = pp * bb - (1.0 - pp) * ss
    return max(edge / (bb * ss), 0.0)


def mh358_kelly_base(p, b):
    pp = mh358_num(p, "p")
    bb = mh358_num(b, "b")
    if not 0.0 <= pp <= 1.0:
        raise ValueError("p: deve stare in [0, 1]")
    if bb <= 0.0:
        raise ValueError("b: deve essere > 0")
    return max((pp * bb - (1.0 - pp)) / bb, 0.0)


def mh358_verdetto(p, b, s):
    pp = mh358_num(p, "p")
    bb = mh358_num(b, "b")
    ss = mh358_num(s, "s")
    if not 0.0 <= pp <= 1.0:
        raise ValueError("p: deve stare in [0, 1]")
    if bb <= 0.0:
        raise ValueError("b: deve essere > 0")
    if ss <= 0.0:
        raise ValueError("s: deve essere > 0")
    qq = 1.0 - pp
    edge = pp * bb - qq * ss
    if edge <= 0.0:
        return ("NESSUN EDGE: anche con lo stop-loss il valore atteso per "
                f"unita' puntata e' {edge:+.2f} (<= 0): nessun sizing lo "
                "salva, rivedi il setup prima di aumentare la size.")
    if ss >= 1.0:
        fb0 = max((pp * bb - qq) / bb, 0.0)
        return (f"STOP INUTILE: lo stop al {ss:.0%} della puntata e' sopra "
                "la perdita piena: non tronca nulla e il sizing resta "
                f"quello base (f* {fb0:.2%}). Stringi lo stop sotto il "
                "100% per avere un effetto.")
    fk = edge / (bb * ss)
    fb = max((pp * bb - qq) / bb, 0.0)
    if fk >= 1.0:
        return (f"SIZING ESTREMO: con lo stop al {ss:.0%} il Kelly diventa "
                f"{fk:.2%} (>= 100% del capitale): servirebbe leva, oppure "
                "lo stop e' troppo stretto per il payoff dichiarato. "
                "Riduci la frazione (es. mezzo Kelly) o allarga lo stop.")
    m = fk / fb if fb > 0.0 else float("inf")
    if m >= 2.5:
        extra = (" lo stop CREA l'edge: senza stop il setup sarebbe in "
                 "perdita." if fb <= 0.0
                 else f" ({m:.1f}x il Kelly base {fb:.2%}).")
        return (f"BOOST FORTE: lo stop al {ss:.0%} porta il Kelly a "
                f"{fk:.2%}.{extra} Verifica che lo stop sia eseguibile: "
                "slippage e gap possono allargare la perdita reale oltre "
                "il livello dichiarato.")
    return (f"BOOST MODERATO: lo stop al {ss:.0%} porta il Kelly da "
            f"{fb:.2%} a {fk:.2%} (x{m:.1f}): edge migliorato senza "
            "sizing estremi, sizing applicabile con margine di sicurezza.")


def mh358_walk(seq, b, p, s, equity0):
    bb = mh358_num(b, "b")
    pp = mh358_num(p, "p")
    ss = mh358_num(s, "s")
    eq0 = mh358_num(equity0, "equity0")
    if bb <= 0.0:
        raise ValueError("b: deve essere > 0")
    if not 0.0 <= pp <= 1.0:
        raise ValueError("p: deve stare in [0, 1]")
    if ss <= 0.0:
        raise ValueError("s: deve essere > 0")
    if eq0 <= 0.0:
        raise ValueError("equity0: deve essere > 0")
    if not seq:
        raise ValueError("sequenza: vuota")
    for x in seq:
        if x not in (0, 1):
            raise ValueError("sequenza: valori 0/1")
    fk = mh358_kelly_stop(pp, bb, ss)
    fb = mh358_kelly_base(pp, bb)
    eq_s = eq0
    eq_b = eq0
    eqs_path = [eq_s]
    eqb_path = [eq_b]
    righe = []
    for i, x in enumerate(seq):
        eq_s = eq_s * (1.0 + fk * bb) if x else eq_s * (1.0 - fk * ss)
        eq_b = eq_b * (1.0 + fb * bb) if x else eq_b * (1.0 - fb)
        righe.append({"trade": i + 1, "esito": "W" if x else "L",
                      "eq_stop": eq_s, "eq_base": eq_b})
        eqs_path.append(eq_s)
        eqb_path.append(eq_b)
    gap = eqs_path[-1] - eqb_path[-1]
    gap_pct = gap / eqb_path[-1] if eqb_path[-1] != 0 else 0.0
    max_dd = 1.0 - min(eqs_path[i] / max(eqs_path[:i + 1])
                       for i in range(len(eqs_path)))
    boost = fk / fb if fb > 0.0 else float("inf")
    return {"n": len(seq), "n_wins": sum(seq), "f_stop": fk, "f_base": fb,
            "boost": boost, "eqs_path": eqs_path, "eqb_path": eqb_path,
            "eqs_fin": eqs_path[-1], "eqb_fin": eqb_path[-1],
            "gap": gap, "gap_pct": gap_pct, "max_dd_stop": max_dd,
            "righe": righe, "p": pp, "b": bb, "s": ss, "equity0": eq0,
            "verdetto": mh358_verdetto(pp, bb, ss)}


def mh358_confronto(seq_s, b, p, s, equity0):
    seq = mh358_parse_seq(seq_s)
    w = mh358_walk(seq, b, p, s, equity0)
    w["seq_str"] = "".join("W" if x else "L" for x in seq)
    return w

def mh357_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh357_parse_seq(s):
    if not isinstance(s, str):
        raise ValueError("sequenza: deve essere una stringa")
    out = []
    for ch in s:
        if ch in "Ww1":
            out.append(1)
        elif ch in "Ll0":
            out.append(0)
        elif ch in " ,;|-\t\n":
            continue
        else:
            raise ValueError(
                f"sequenza: carattere non valido {ch!r} "
                "(usa W/L oppure 1/0)")
    if not out:
        raise ValueError("sequenza: nessun esito valido")
    return tuple(out)


def mh357_kelly_f(p, b):
    pp = mh357_num(p, "p")
    bb = mh357_num(b, "b")
    if not 0.0 <= pp <= 1.0:
        raise ValueError("p: deve stare in [0, 1]")
    if bb <= 0.0:
        raise ValueError("b: deve essere > 0")
    return max((pp * bb - (1.0 - pp)) / bb, 0.0)


def mh357_lotti(f_kelly, equity, lotto):
    import math
    fk = mh357_num(f_kelly, "f_kelly")
    eq = mh357_num(equity, "equity")
    lo = mh357_num(lotto, "lotto")
    if fk < 0.0:
        raise ValueError("f_kelly: deve essere >= 0")
    if eq <= 0.0:
        raise ValueError("equity: deve essere > 0")
    if lo <= 0.0:
        raise ValueError("lotto: deve essere > 0")
    n = int(math.floor(fk * eq / lo + 1e-9))
    return n, n * lo / eq


def mh357_verdetto(f_kelly, equity, lotto):
    fk = mh357_num(f_kelly, "f_kelly")
    eq = mh357_num(equity, "equity")
    lo = mh357_num(lotto, "lotto")
    if eq <= 0.0:
        raise ValueError("equity: deve essere > 0")
    if lo <= 0.0:
        raise ValueError("lotto: deve essere > 0")
    if fk <= 0.0:
        return ("NESSUN EDGE: f_kelly = 0, il setup non ha edge positivo: "
                "nessun lotto va aperto a prescindere dal capitale.")
    n, f_eff = mh357_lotti(fk, eq, lo)
    if n == 0:
        return (f"CAPITALE INSUFFICIENTE: con equity {eq:,.0f} e lotto "
                f"{lo:,.0f} non si apre nemmeno un lotto "
                f"(f_kelly {fk:.2%} -> 0 lotti). Aumenta il capitale o "
                f"cerca strumenti con taglio minimo piu' piccolo.")
    if f_eff < 0.75 * fk:
        return (f"LOTTO ECCESSIVO: il lotto da {lo:,.0f} mangia piu' di un "
                f"quarto del Kelly (f_eff {f_eff:.2%} vs f_kelly {fk:.2%}): "
                f"il drag di arrotondamento e' eccessivo, riduci il taglio.")
    if f_eff < 0.9 * fk:
        return (f"DRAG MODERATO: il lotto da {lo:,.0f} taglia il Kelly "
                f"di {(1.0 - f_eff / fk):.0%} "
                f"(f_eff {f_eff:.2%} vs f_kelly {fk:.2%}): sizing discreto "
                f"accettabile ma con drag misurabile.")
    return (f"ARROTONDAMENTO OK: il lotto da {lo:,.0f} lascia quasi tutto "
            f"il Kelly (f_eff {f_eff:.2%} vs f_kelly {fk:.2%}): il drag di "
            f"arrotondamento e' trascurabile.")


def mh357_walk(seq, b, p, equity0, lotto):
    bb = mh357_num(b, "b")
    pp = mh357_num(p, "p")
    eq0 = mh357_num(equity0, "equity0")
    lo = mh357_num(lotto, "lotto")
    if bb <= 0.0:
        raise ValueError("b: deve essere > 0")
    if not 0.0 <= pp <= 1.0:
        raise ValueError("p: deve stare in [0, 1]")
    if eq0 <= 0.0:
        raise ValueError("equity0: deve essere > 0")
    if lo <= 0.0:
        raise ValueError("lotto: deve essere > 0")
    if not seq:
        raise ValueError("sequenza: vuota")
    for x in seq:
        if x not in (0, 1):
            raise ValueError("sequenza: valori 0/1")
    fk = mh357_kelly_f(pp, bb)
    n0, f0 = mh357_lotti(fk, eq0, lo)
    eq = eq0
    eqc = eq0
    eq_path = [eq]
    eqc_path = [eqc]
    righe = []
    for i, x in enumerate(seq):
        n, f_eff = mh357_lotti(fk, eq, lo)
        eq = eq * (1.0 + f_eff * bb) if x else eq * (1.0 - f_eff)
        eqc = eqc * (1.0 + fk * bb) if x else eqc * (1.0 - fk)
        righe.append({"trade": i + 1, "esito": "W" if x else "L",
                      "lotti": n, "f_eff": f_eff,
                      "equity": eq, "equity_cont": eqc})
        eq_path.append(eq)
        eqc_path.append(eqc)
    drag = eqc_path[-1] - eq_path[-1]
    drag_pct = drag / eqc_path[-1] if eqc_path[-1] != 0 else 0.0
    max_dd = 1.0 - min(eq_path[i] / max(eq_path[:i + 1])
                       for i in range(len(eq_path)))
    return {"n": len(seq), "n_wins": sum(seq), "f_kelly": fk,
            "lotti_iniz": n0, "f_eff_iniz": f0,
            "eq_path": eq_path, "eqc_path": eqc_path,
            "eq_fin": eq_path[-1], "eqc_fin": eqc_path[-1],
            "drag": drag, "drag_pct": drag_pct, "max_dd": max_dd,
            "righe": righe, "p": pp, "b": bb,
            "equity0": eq0, "lotto": lo,
            "verdetto": mh357_verdetto(fk, eq0, lo)}


def mh357_confronto(seq_s, b, p, equity0, lotto):
    seq = mh357_parse_seq(seq_s)
    w = mh357_walk(seq, b, p, equity0, lotto)
    w["seq_str"] = "".join("W" if x else "L" for x in seq)
    return w


def mh356_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh356_beta_reg(a, b, x):
    import math
    aa = mh356_num(a, "a")
    bb = mh356_num(b, "b")
    xx = mh356_num(x, "x")
    if aa <= 0.0 or bb <= 0.0:
        raise ValueError("a, b: devono essere > 0")
    if not 0.0 <= xx <= 1.0:
        raise ValueError("x: deve stare in [0, 1]")
    if xx == 0.0:
        return 0.0
    if xx == 1.0:
        return 1.0

    def _betacf(ca, cb, cx):
        maxit = 200
        eps = 3.0e-12
        fpmin = 1.0e-300
        qab = ca + cb
        qap = ca + 1.0
        qam = ca - 1.0
        c = 1.0
        d = 1.0 - qab * cx / qap
        if abs(d) < fpmin:
            d = fpmin
        d = 1.0 / d
        h = d
        for mm in range(1, maxit + 1):
            m2 = 2 * mm
            t = mm * (cb - mm) * cx / ((qam + m2) * (ca + m2))
            d = 1.0 + t * d
            if abs(d) < fpmin:
                d = fpmin
            c = 1.0 + t / c
            if abs(c) < fpmin:
                c = fpmin
            d = 1.0 / d
            h *= d * c
            t = -(ca + mm) * (qab + mm) * cx / ((ca + m2) * (qap + m2))
            d = 1.0 + t * d
            if abs(d) < fpmin:
                d = fpmin
            c = 1.0 + t / c
            if abs(c) < fpmin:
                c = fpmin
            d = 1.0 / d
            delt = c * d
            h *= delt
            if abs(delt - 1.0) < eps:
                break
        return h

    bt = math.exp(math.lgamma(aa + bb) - math.lgamma(aa) - math.lgamma(bb)
                  + aa * math.log(xx) + bb * math.log(1.0 - xx))
    if xx < (aa + 1.0) / (aa + bb + 2.0):
        return bt * _betacf(aa, bb, xx) / aa
    return 1.0 - bt * _betacf(bb, aa, 1.0 - xx) / bb


def mh356_p_quantile(a, b, q, niter=200):
    aa = mh356_num(a, "a")
    bb = mh356_num(b, "b")
    qq = mh356_num(q, "q")
    if aa <= 0.0 or bb <= 0.0:
        raise ValueError("a, b: devono essere > 0")
    if not 0.0 < qq < 1.0:
        raise ValueError("q: deve stare in (0, 1)")
    lo, hi = 0.0, 1.0
    for _ in range(int(niter)):
        mid = 0.5 * (lo + hi)
        if mh356_beta_reg(aa, bb, mid) < qq:
            lo = mid
        else:
            hi = mid
    return 0.5 * (lo + hi)


def mh356_parse_seq(s):
    if not isinstance(s, str):
        raise ValueError("sequenza: deve essere una stringa")
    out = []
    for ch in s:
        if ch in "Ww1":
            out.append(1)
        elif ch in "Ll0":
            out.append(0)
        elif ch in " ,;|-\t\n":
            continue
        else:
            raise ValueError(
                f"sequenza: carattere non valido {ch!r} "
                "(usa W/L oppure 1/0)")
    if not out:
        raise ValueError("sequenza: nessun esito valido")
    return tuple(out)


def mh356_kelly_f(p, b):
    pp = mh356_num(p, "p")
    bb = mh356_num(b, "b")
    if not 0.0 <= pp <= 1.0:
        raise ValueError("p: deve stare in [0, 1]")
    if bb <= 0.0:
        raise ValueError("b: deve essere > 0")
    return max((pp * bb - (1.0 - pp)) / bb, 0.0)


def mh356_posterior(alpha, beta, seq):
    al = mh356_num(alpha, "alpha")
    be = mh356_num(beta, "beta")
    if al <= 0.0 or be <= 0.0:
        raise ValueError("alpha, beta: devono essere > 0")
    w = sum(seq)
    return al + w, be + len(seq) - w


def mh356_edge_prob(a, b, b_odds):
    aa = mh356_num(a, "a")
    bb = mh356_num(b, "b")
    bo = mh356_num(b_odds, "b")
    if aa <= 0.0 or bb <= 0.0:
        raise ValueError("a, b: devono essere > 0")
    if bo <= 0.0:
        raise ValueError("b: deve essere > 0")
    return 1.0 - mh356_beta_reg(aa, bb, 1.0 / (1.0 + bo))


def mh356_verdetto(edge_prob, n, min_n=10):
    ep = mh356_num(edge_prob, "edge_prob")
    nn = mh356_num(n, "n")
    mn = mh356_num(min_n, "min_n")
    if not 0.0 <= ep <= 1.0:
        raise ValueError("edge_prob: deve stare in [0, 1]")
    if nn < 1:
        raise ValueError("n: deve essere >= 1")
    if nn < mn:
        return (f"DATI INSUFFICIENTI: solo {int(nn)} trade registrati "
                f"(minimo {int(mn)}). Con pochi dati la posterior e' quasi "
                f"tutta prior: registra piu' esiti.")
    if ep >= 0.90:
        return (f"EDGE ATTENDIBILE: la posterior da' {ep:.1%} di "
                f"probabilita' che il vero win-rate batta il break-even. "
                f"Il sizing bayesiano puo' essere usato a pieno.")
    if ep >= 0.50:
        return (f"EDGE MARGINALE: la posterior da' {ep:.1%} di "
                f"probabilita' che il vero win-rate batta il break-even. "
                f"Considera la modalita' prudente (quantile 5%).")
    return (f"EDGE NON ATTENDIBILE: la posterior da' solo {ep:.1%} di "
            f"probabilita' che il vero win-rate batta il break-even. "
            f"Non tradare questo setup, o riduci drasticamente la size.")


def mh356_walk(seq, b, alpha, beta, modo="media"):
    bb = mh356_num(b, "b")
    if bb <= 0.0:
        raise ValueError("b: deve essere > 0")
    if not seq:
        raise ValueError("sequenza: vuota")
    for x in seq:
        if x not in (0, 1):
            raise ValueError("sequenza: valori 0/1")
    if modo not in ("media", "prudente"):
        raise ValueError("modo: 'media' o 'prudente'")
    a_post, b_post = mh356_posterior(alpha, beta, ())
    eq = 1.0
    eq_path = [eq]
    righe = []
    for i, x in enumerate(seq):
        p_est = (a_post / (a_post + b_post) if modo == "media"
                 else mh356_p_quantile(a_post, b_post, 0.05))
        f = mh356_kelly_f(p_est, bb)
        eq = eq * (1.0 + f * bb) if x else eq * (1.0 - f)
        a_post += x
        b_post += 1 - x
        righe.append({"trade": i + 1, "esito": "W" if x else "L",
                      "a": a_post, "b": b_post,
                      "p_est": p_est, "f": f, "equity": eq})
        eq_path.append(eq)
    n = len(seq)
    p_mean = a_post / (a_post + b_post)
    p_q05 = mh356_p_quantile(a_post, b_post, 0.05)
    edge_prob = mh356_edge_prob(a_post, b_post, bb)
    p_final = p_mean if modo == "media" else p_q05
    max_dd = 1.0 - min(eq_path[i] / max(eq_path[:i + 1])
                       for i in range(len(eq_path)))
    return {"n": n, "n_wins": sum(seq), "p_freq": sum(seq) / n,
            "a_post": a_post, "b_post": b_post, "p_mean": p_mean,
            "p_quant05": p_q05, "edge_prob": edge_prob,
            "p_est": p_final, "f": mh356_kelly_f(p_final, bb),
            "eq_path": eq_path, "eq_fin": eq_path[-1], "max_dd": max_dd,
            "righe": righe, "modo": modo,
            "alpha": mh356_num(alpha, "alpha"),
            "beta": mh356_num(beta, "beta"), "b": bb,
            "p_be": 1.0 / (1.0 + bb),
            "verdetto": mh356_verdetto(edge_prob, n)}


def mh356_confronto(seq_s, b, alpha, beta, modo="media", min_n=10):
    seq = mh356_parse_seq(seq_s)
    w = mh356_walk(seq, b, alpha, beta, modo)
    w["verdetto"] = mh356_verdetto(w["edge_prob"], w["n"], min_n)
    w["seq_str"] = "".join("W" if x else "L" for x in seq)
    w["min_n"] = min_n
    return w


def mh355_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh355_parse_seq(s):
    if not isinstance(s, str):
        raise ValueError("sequenza: deve essere una stringa")
    out = []
    for ch in s:
        if ch in "Ww1":
            out.append(1)
        elif ch in "Ll0":
            out.append(0)
        elif ch in " ,;|-\t\n":
            continue
        else:
            raise ValueError(
                f"sequenza: carattere non valido {ch!r} "
                "(usa W/L oppure 1/0)")
    if not out:
        raise ValueError("sequenza: nessun esito valido")
    return tuple(out)


def mh355_kelly_f(p, b):
    pp = mh355_num(p, "p")
    bb = mh355_num(b, "b")
    if not 0.0 < pp < 1.0:
        raise ValueError("p: deve stare in (0, 1)")
    if bb <= 0.0:
        raise ValueError("b: deve essere > 0")
    return max((pp * bb - (1.0 - pp)) / bb, 0.0)


def mh355_fattore(sigma, sigma_target, f_min=0.25, f_max=2.0):
    s = mh355_num(sigma, "sigma")
    st = mh355_num(sigma_target, "sigma_target")
    fmin = mh355_num(f_min, "f_min")
    fmax = mh355_num(f_max, "f_max")
    if s <= 0.0:
        raise ValueError("sigma: deve essere > 0")
    if st <= 0.0:
        raise ValueError("sigma_target: deve essere > 0")
    if not 0.0 < fmin <= fmax:
        raise ValueError("limiti fattore: serve 0 < f_min <= f_max")
    return max(fmin, min(fmax, st / s))


def mh355_walk(seq, b, f_kelly, sigma, sigma_target,
               f_min=0.25, f_max=2.0):
    bb = mh355_num(b, "b")
    fk = mh355_num(f_kelly, "f_kelly")
    if bb <= 0.0:
        raise ValueError("b: deve essere > 0")
    if fk < 0.0 or fk > 1.0:
        raise ValueError("f_kelly: deve stare in [0, 1]")
    if not seq:
        raise ValueError("sequenza: vuota")
    for x in seq:
        if x not in (0, 1):
            raise ValueError("sequenza: valori 0/1")
    fattore = mh355_fattore(sigma, sigma_target, f_min, f_max)
    f_eff = fk * fattore
    eq = 1.0
    eq_base = 1.0
    eq_path = [eq]
    base_path = [eq_base]
    for x in seq:
        eq = eq * (1.0 + f_eff * bb) if x else eq * (1.0 - f_eff)
        eq_base = eq_base * (1.0 + fk * bb) if x else eq_base * (1.0 - fk)
        eq_path.append(eq)
        base_path.append(eq_base)
    n = len(seq)
    n_wins = sum(seq)
    max_dd = 1.0 - min(eq_path[i] / max(eq_path[:i + 1])
                       for i in range(len(eq_path)))
    return {"n": n, "n_wins": n_wins, "p_freq": n_wins / n,
            "eq_path": eq_path, "base_path": base_path,
            "eq_fin": eq_path[-1], "eq_base_fin": base_path[-1],
            "max_dd": max_dd, "fattore": fattore, "f_eff": f_eff,
            "b": bb, "f_kelly": fk, "sigma": mh355_num(sigma, "sigma"),
            "sigma_target": mh355_num(sigma_target, "sigma_target")}


def mh355_verdetto(sigma, sigma_target, f_eff, f_kelly, n, min_n=10):
    s = mh355_num(sigma, "sigma")
    st = mh355_num(sigma_target, "sigma_target")
    fe = mh355_num(f_eff, "f_effettiva")
    fk = mh355_num(f_kelly, "f_kelly")
    nn = mh355_num(n, "n")
    mn = mh355_num(min_n, "min_n")
    if s <= 0.0:
        raise ValueError("sigma: deve essere > 0")
    if st <= 0.0:
        raise ValueError("sigma_target: deve essere > 0")
    if fe < 0.0 or fk < 0.0:
        raise ValueError("frazioni: devono essere >= 0")
    if nn < 1:
        raise ValueError("n: deve essere >= 1")
    if nn < mn:
        return (f"DATI INSUFFICIENTI: solo {int(nn)} trade registrati "
                f"(minimo {int(mn)}). Il volatility targeting ha senso su "
                f"un campione piu' ampio: registra piu' esiti.")
    fatt = fe / fk if fk > 0.0 else 0.0
    if fatt <= 0.9:
        return (f"VOL ELEVATA - RIDUZIONE: sigma {s:.1%} sopra il target "
                f"{st:.1%}. Il fattore di scala e' {fatt:.1%}: la size "
                f"effettiva scende a f={fe:.2%} contro f_kelly={fk:.2%}. "
                f"Ridotto il rischio in regime di volatilita' alta.")
    if fatt >= 1.1:
        return (f"VOL BASSA - AUMENTO: sigma {s:.1%} sotto il target "
                f"{st:.1%}. Il fattore di scala e' {fatt:.1%}: la size "
                f"effettiva sale a f={fe:.2%} contro f_kelly={fk:.2%}. "
                f"Sfrutta il regime di volatilita' bassa.")
    return (f"NEUTRA: sigma {s:.1%} vicina al target {st:.1%} "
            f"(fattore {fatt:.1%}). La size effettiva f={fe:.2%} resta "
            f"quasi uguale al Kelly f={fk:.2%}: nessuna modifica.")


def mh355_confronto(seq_s, b, f_kelly, sigma, sigma_target, min_n=10):
    seq = mh355_parse_seq(seq_s)
    w = mh355_walk(seq, b, f_kelly, sigma, sigma_target)
    w["verdetto"] = mh355_verdetto(w["sigma"], w["sigma_target"],
                                   w["f_eff"], w["f_kelly"], w["n"], min_n)
    w["seq_str"] = "".join("W" if x else "L" for x in seq)
    righe = []
    for i, x in enumerate(seq):
        righe.append({"trade": i + 1, "esito": "W" if x else "L",
                      "equity": w["eq_path"][i + 1],
                      "equity_base": w["base_path"][i + 1],
                      "f_effettiva": w["f_eff"]})
    w["righe"] = righe
    w["min_n"] = min_n
    return w


def mh354_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh354_parse_seq(s):
    if not isinstance(s, str):
        raise ValueError("sequenza: deve essere una stringa")
    out = []
    for ch in s:
        if ch in "Ww1":
            out.append(1)
        elif ch in "Ll0":
            out.append(0)
        elif ch in " ,;|-\t\n":
            continue
        else:
            raise ValueError(
                f"sequenza: carattere non valido {ch!r} "
                "(usa W/L oppure 1/0)")
    if not out:
        raise ValueError("sequenza: nessun esito valido")
    return tuple(out)


def mh354_kelly_f(p, b):
    pp = mh354_num(p, "p")
    bb = mh354_num(b, "b")
    if not 0.0 < pp < 1.0:
        raise ValueError("p: deve stare in (0, 1)")
    if bb <= 0.0:
        raise ValueError("b: deve essere > 0")
    return max((pp * bb - (1.0 - pp)) / bb, 0.0)


def mh354_fattore(dd, dd_max):
    d = mh354_num(dd, "drawdown")
    dm = mh354_num(dd_max, "dd_max")
    if d < 0.0:
        raise ValueError("drawdown: non puo' essere negativo")
    if not 0.0 < dm < 1.0:
        raise ValueError("dd_max: deve stare in (0, 1)")
    return max(0.0, 1.0 - d / dm)


def mh354_walk(seq, b, f_kelly, dd_max):
    bb = mh354_num(b, "b")
    fk = mh354_num(f_kelly, "f_kelly")
    dm = mh354_num(dd_max, "dd_max")
    if bb <= 0.0:
        raise ValueError("b: deve essere > 0")
    if fk < 0.0 or fk > 1.0:
        raise ValueError("f_kelly: deve stare in [0, 1]")
    if not 0.0 < dm < 1.0:
        raise ValueError("dd_max: deve stare in (0, 1)")
    if not seq:
        raise ValueError("sequenza: vuota")
    for x in seq:
        if x not in (0, 1):
            raise ValueError("sequenza: valori 0/1")
    eq = 1.0
    peak = 1.0
    eq_path = [eq]
    dd_path = [0.0]
    f_path = []
    for x in seq:
        dd = (peak - eq) / peak
        f_eff = fk * mh354_fattore(dd, dm)
        f_path.append(f_eff)
        eq = eq * (1.0 + f_eff * bb) if x else eq * (1.0 - f_eff)
        if eq > peak:
            peak = eq
        eq_path.append(eq)
        dd_path.append((peak - eq) / peak)
    n = len(seq)
    n_wins = sum(seq)
    return {"n": n, "n_wins": n_wins, "p_freq": n_wins / n,
            "eq_path": eq_path, "dd_path": dd_path, "f_path": f_path,
            "eq_fin": eq_path[-1], "dd_fin": dd_path[-1],
            "max_dd": max(dd_path), "f_fin": f_path[-1],
            "fattore_fin": mh354_fattore(dd_path[-1], dm),
            "b": bb, "f_kelly": fk, "dd_max": dm}


def mh354_verdetto(dd, dd_max, f_eff, f_kelly, n, min_n=10):
    d = mh354_num(dd, "drawdown")
    dm = mh354_num(dd_max, "dd_max")
    fe = mh354_num(f_eff, "f_effettiva")
    fk = mh354_num(f_kelly, "f_kelly")
    nn = mh354_num(n, "n")
    mn = mh354_num(min_n, "min_n")
    if d < 0.0:
        raise ValueError("drawdown: non puo' essere negativo")
    if not 0.0 < dm < 1.0:
        raise ValueError("dd_max: deve stare in (0, 1)")
    if fe < 0.0 or fk < 0.0:
        raise ValueError("frazioni: devono essere >= 0")
    if nn < 1:
        raise ValueError("n: deve essere >= 1")
    if nn < mn:
        return (f"DATI INSUFFICIENTI: solo {int(nn)} trade registrati "
                f"(minimo {int(mn)}). Il controllo drawdown ha senso su "
                f"un campione piu' ampio: registra piu' esiti.")
    if d >= dm:
        return (f"STOP: drawdown {d:.1%} >= soglia {dm:.0%}. La size "
                f"effettiva e' zero: chiudi o non aprire nuove posizioni "
                f"finche' l'equity non recupera sopra la soglia.")
    fatt = fe / fk if fk > 0.0 else 0.0
    if d > 2.0 * dm / 3.0:
        return (f"RIDUZIONE SEVERA: drawdown {d:.1%} oltre i 2/3 della "
                f"soglia {dm:.0%}. La size effettiva e' f={fe:.2%} contro "
                f"f_kelly={fk:.2%} (fattore {fatt:.1%}). Riduci "
                f"drasticamente l'esposizione.")
    if d > dm / 3.0:
        return (f"RIDUZIONE: drawdown {d:.1%} sopra 1/3 della soglia "
                f"{dm:.0%}. La size effettiva e' f={fe:.2%} contro "
                f"f_kelly={fk:.2%}: taglia l'esposizione finche' il "
                f"drawdown non rientra.")
    return (f"SIZE PIENA: drawdown {d:.1%} entro 1/3 della soglia "
            f"{dm:.0%}. La size effettiva f={fe:.2%} resta vicina al "
            f"Kelly pieno f={fk:.2%}: nessuna riduzione necessaria.")


def mh354_confronto(seq_s, b, f_kelly, dd_max, min_n=10):
    seq = mh354_parse_seq(seq_s)
    w = mh354_walk(seq, b, f_kelly, dd_max)
    w["verdetto"] = mh354_verdetto(w["dd_fin"], w["dd_max"], w["f_fin"],
                                   w["f_kelly"], w["n"], min_n)
    w["seq_str"] = "".join("W" if x else "L" for x in seq)
    righe = []
    for i, x in enumerate(seq):
        righe.append({"trade": i + 1, "esito": "W" if x else "L",
                      "equity": w["eq_path"][i + 1],
                      "drawdown": w["dd_path"][i + 1],
                      "f_effettiva": w["f_path"][i]})
    w["righe"] = righe
    w["min_n"] = min_n
    return w

def mh353_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh353_parse_seq(s):
    if not isinstance(s, str):
        raise ValueError("sequenza: deve essere una stringa")
    out = []
    for ch in s:
        if ch in "Ww1":
            out.append(1)
        elif ch in "Ll0":
            out.append(0)
        elif ch in " ,;|-\t\n":
            continue
        else:
            raise ValueError(
                f"sequenza: carattere non valido {ch!r} (usa W/L oppure 1/0)")
    if not out:
        raise ValueError("sequenza: nessun esito valido")
    return tuple(out)


def mh353_ewma_p(seq, lam, p_prior):
    ll = mh353_num(lam, "lambda")
    pp = mh353_num(p_prior, "p_prior")
    if not 0.0 < ll <= 1.0:
        raise ValueError("lambda: deve stare in (0, 1]")
    if not 0.0 < pp < 1.0:
        raise ValueError("p_prior: deve stare in (0, 1)")
    if not seq:
        raise ValueError("sequenza: vuota")
    p = pp
    for x in seq:
        if x not in (0, 1):
            raise ValueError("sequenza: valori 0/1")
        p = ll * p + (1.0 - ll) * x
    return p


def mh353_kelly_f(p, b):
    pp = mh353_num(p, "p")
    bb = mh353_num(b, "b")
    if not 0.0 < pp < 1.0:
        raise ValueError("p: deve stare in (0, 1)")
    if bb <= 0.0:
        raise ValueError("b: deve essere > 0")
    edge = pp * bb - (1.0 - pp)
    return max(edge / bb, 0.0)


def mh353_adaptive(seq, b, lam, p_prior, f_cap, max_step):
    bb = mh353_num(b, "b")
    ll = mh353_num(lam, "lambda")
    pp = mh353_num(p_prior, "p_prior")
    fc = mh353_num(f_cap, "f_cap")
    ms = mh353_num(max_step, "max_step")
    if bb <= 0.0:
        raise ValueError("b: deve essere > 0")
    if not 0.0 < ll <= 1.0:
        raise ValueError("lambda: deve stare in (0, 1]")
    if not 0.0 < pp < 1.0:
        raise ValueError("p_prior: deve stare in (0, 1)")
    if not 0.0 < fc <= 1.0:
        raise ValueError("f_cap: deve stare in (0, 1]")
    if ms <= 0.0:
        raise ValueError("max_step: deve essere > 0")
    if not seq:
        raise ValueError("sequenza: vuota")
    for x in seq:
        if x not in (0, 1):
            raise ValueError("sequenza: valori 0/1")
    p_cur = pp
    f_cur = min(mh353_kelly_f(p_cur, bb), fc)
    p_path = [p_cur]
    f_path = [f_cur]
    for x in seq:
        p_cur = ll * p_cur + (1.0 - ll) * x
        f_raw = mh353_kelly_f(p_cur, bb)
        lo = max(0.0, f_cur - ms)
        hi = min(fc, f_cur + ms)
        f_cur = min(max(f_raw, lo), hi)
        p_path.append(p_cur)
        f_path.append(f_cur)
    n = len(seq)
    n_wins = sum(seq)
    p_freq = n_wins / n
    f_static = min(mh353_kelly_f(p_freq, bb), fc)
    return {"n": n, "n_wins": n_wins, "p_freq": p_freq, "p_ewma": p_cur,
            "p_path": p_path, "f_static": f_static, "f_path": f_path,
            "f_final": f_cur, "b": bb, "lam": ll, "p_prior": pp,
            "f_cap": fc, "max_step": ms}


def mh353_verdetto(f_final, f_static, p_ewma, p_freq, n, min_n=10):
    ff = mh353_num(f_final, "f_final")
    fs = mh353_num(f_static, "f_static")
    pe = mh353_num(p_ewma, "p_ewma")
    pf = mh353_num(p_freq, "p_freq")
    nn = mh353_num(n, "n")
    mn = mh353_num(min_n, "min_n")
    if ff < 0.0 or fs < 0.0:
        raise ValueError("frazioni: devono essere >= 0")
    if not 0.0 < pe < 1.0 or not 0.0 <= pf <= 1.0:
        raise ValueError("probabilita': fuori intervallo")
    if nn < 1:
        raise ValueError("n: deve essere >= 1")
    if nn < mn:
        return (f"DATI INSUFFICIENTI: solo {int(nn)} trade registrati "
                f"(minimo {int(mn)}). La size adattiva resta al valore "
                f"corrente f={ff:.2%}: registra piu' esiti prima di "
                f"fidarti dell'adattamento.")
    if ff <= 0.0:
        return (f"PAUSA: l'edge stimato sui dati recenti e' nullo o "
                f"negativo (p_ewma={pe:.1%}, f*={ff:.2%}). Non aprire "
                f"nuove posizioni finche' la win-rate rolling non torna "
                f"sopra la soglia di edge.")
    df = ff - fs
    if df > 0.02:
        return (f"AUMENTO SIZE: la win-rate recente (p_ewma={pe:.1%}) e' "
                f"sopra la media storica ({pf:.1%}): il Kelly adattivo "
                f"sale a f={ff:.2%} contro f_static={fs:.2%} "
                f"({df:+.2%}). Il regime recente e' piu' favorevole: "
                f"puoi spingere la size, restando sotto il cap.")
    if df < -0.02:
        return (f"RIDUZIONE SIZE: la win-rate recente (p_ewma={pe:.1%}) e' "
                f"sotto la media storica ({pf:.1%}): il Kelly adattivo "
                f"scende a f={ff:.2%} contro f_static={fs:.2%} "
                f"({df:+.2%}). Il regime recente si e' deteriorato: "
                f"taglia la size finche' i dati non migliorano.")
    return (f"STABILE: p_ewma={pe:.1%} in linea con la media storica "
            f"({pf:.1%}): f_adattivo={ff:.2%} circa f_static={fs:.2%} "
            f"({df:+.2%}). Nessun cambio di regime rilevato: mantieni "
            f"la size corrente.")


def mh353_confronto(seq_s, b, lam, p_prior, f_cap, max_step, min_n=10):
    seq = mh353_parse_seq(seq_s)
    a = mh353_adaptive(seq, b, lam, p_prior, f_cap, max_step)
    a["verdetto"] = mh353_verdetto(a["f_final"], a["f_static"],
                                   a["p_ewma"], a["p_freq"], a["n"], min_n)
    a["seq_str"] = "".join("W" if x else "L" for x in seq)
    righe = []
    for i, x in enumerate(seq):
        righe.append({"trade": i + 1, "esito": "W" if x else "L",
                      "p_ewma": a["p_path"][i + 1],
                      "f_adattivo": a["f_path"][i + 1]})
    a["righe"] = righe
    a["min_n"] = min_n
    return a

def mh352_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh352_kelly_f(p, b):
    pp = mh352_num(p, "p")
    bb = mh352_num(b, "b")
    if not 0.0 < pp < 1.0:
        raise ValueError("p: deve stare in (0, 1)")
    if bb <= 0.0:
        raise ValueError("b: deve essere > 0")
    edge = pp * bb - (1.0 - pp)
    if edge <= 0.0:
        return 0.0
    return edge / bb


def mh352_pq(p1, p2):
    pp1 = mh352_num(p1, "p1")
    pp2 = mh352_num(p2, "p2")
    if not 0.0 < pp1 < 1.0:
        raise ValueError("p1: deve stare in (0, 1)")
    if not 0.0 < pp2 < 1.0:
        raise ValueError("p2: deve stare in (0, 1)")
    return pp1, pp2, 1.0 - pp1, 1.0 - pp2


def mh352_rho_bounds(p1, p2):
    import math
    pp1, pp2, q1, q2 = mh352_pq(p1, p2)
    s = math.sqrt(pp1 * q1 * pp2 * q2)
    return {"rho_min": max(-pp1 * pp2 / s, -q1 * q2 / s),
            "rho_max": min(pp1 * q2 / s, q1 * pp2 / s)}


def mh352_joint_probs(p1, p2, rho):
    import math
    pp1, pp2, q1, q2 = mh352_pq(p1, p2)
    rr = mh352_num(rho, "rho")
    bnd = mh352_rho_bounds(pp1, pp2)
    if not bnd["rho_min"] - 1e-9 <= rr <= bnd["rho_max"] + 1e-9:
        raise ValueError(
            f"rho={rr}: fuori dall'intervallo ammissibile "
            f"[{bnd['rho_min']:.3f}, {bnd['rho_max']:.3f}] per p1, p2")
    d = rr * math.sqrt(pp1 * q1 * pp2 * q2)
    probs = (pp1 * pp2 + d, pp1 * q2 - d, q1 * pp2 - d, q1 * q2 + d)
    probs = tuple(max(x, 0.0) for x in probs)
    return {"pww": probs[0], "pwl": probs[1], "plw": probs[2], "pll": probs[3]}


def mh352_logstats2(p1, b1, f1, p2, b2, f2, rho):
    import math
    pp1 = mh352_num(p1, "p1")
    bb1 = mh352_num(b1, "b1")
    ff1 = mh352_num(f1, "f1")
    pp2 = mh352_num(p2, "p2")
    bb2 = mh352_num(b2, "b2")
    ff2 = mh352_num(f2, "f2")
    if not 0.0 < pp1 < 1.0:
        raise ValueError("p1: deve stare in (0, 1)")
    if not 0.0 < pp2 < 1.0:
        raise ValueError("p2: deve stare in (0, 1)")
    if bb1 <= 0.0 or bb2 <= 0.0:
        raise ValueError("b1/b2: devono essere > 0")
    if ff1 < 0.0 or ff2 < 0.0:
        raise ValueError("f1/f2: devono essere >= 0")
    if ff1 + ff2 >= 1.0:
        raise ValueError("f1+f2: deve stare < 1 (capitale positivo)")
    jp = mh352_joint_probs(pp1, pp2, rho)
    stati = ((jp["pww"], 1.0 + ff1 * bb1 + ff2 * bb2),
             (jp["pwl"], 1.0 + ff1 * bb1 - ff2),
             (jp["plw"], 1.0 - ff1 + ff2 * bb2),
             (jp["pll"], 1.0 - ff1 - ff2))
    g = sum(_p * math.log(_r) for _p, _r in stati)
    var = sum(_p * math.log(_r) ** 2 for _p, _r in stati) - g * g
    return {"g": g, "sigma": math.sqrt(max(var, 0.0))}


def mh352_ottimo(p1, b1, p2, b2, rho, step=0.01):
    pp1 = mh352_num(p1, "p1")
    bb1 = mh352_num(b1, "b1")
    pp2 = mh352_num(p2, "p2")
    bb2 = mh352_num(b2, "b2")
    rr = mh352_num(rho, "rho")
    st = mh352_num(step, "step")
    if not 0.0 < pp1 < 1.0:
        raise ValueError("p1: deve stare in (0, 1)")
    if not 0.0 < pp2 < 1.0:
        raise ValueError("p2: deve stare in (0, 1)")
    if bb1 <= 0.0 or bb2 <= 0.0:
        raise ValueError("b1/b2: devono essere > 0")
    if not 0.0 < st <= 0.1:
        raise ValueError("step: deve stare in (0, 0.1]")
    bnd = mh352_rho_bounds(pp1, pp2)
    if not bnd["rho_min"] - 1e-9 <= rr <= bnd["rho_max"] + 1e-9:
        raise ValueError("rho: fuori dall'intervallo ammissibile")
    if mh352_kelly_f(pp1, bb1) <= 0.0 and mh352_kelly_f(pp2, bb2) <= 0.0:
        return {"f1": 0.0, "f2": 0.0, "g": 0.0, "sigma": 0.0}
    n = int(0.99 / st)
    best = {"f1": 0.0, "f2": 0.0, "g": float("-inf"), "sigma": 0.0}
    for i in range(n + 1):
        for j in range(n + 1):
            f1, f2 = i * st, j * st
            if f1 + f2 >= 1.0:
                continue
            s = mh352_logstats2(pp1, bb1, f1, pp2, bb2, f2, rr)
            if s["g"] > best["g"]:
                best = {"f1": f1, "f2": f2, "g": s["g"], "sigma": s["sigma"]}
    return best


def mh352_verdetto(f1_ind, f2_ind, f1_opt, f2_opt, g_ind, sigma_ind,
                   g_opt, sigma_opt, rho):
    i1 = mh352_num(f1_ind, "f1_ind")
    i2 = mh352_num(f2_ind, "f2_ind")
    o1 = mh352_num(f1_opt, "f1_opt")
    o2 = mh352_num(f2_opt, "f2_opt")
    go = mh352_num(g_opt, "g_opt")
    so = mh352_num(sigma_opt, "sigma_opt")
    rr = mh352_num(rho, "rho")
    if i1 < 0.0 or i2 < 0.0 or o1 < 0.0 or o2 < 0.0:
        raise ValueError("frazioni: devono essere >= 0")
    if o1 + o2 >= 1.0:
        raise ValueError("f1_opt+f2_opt: deve stare < 1")
    if not -1.0 <= rr <= 1.0:
        raise ValueError("rho: deve stare in [-1, 1]")
    if o1 <= 0.0 and o2 <= 0.0:
        return ("NESSUN EDGE — NON TRADARE: nessuna delle due posizioni ha "
                "edge positivo, il sizing ottimale e' zero.")
    if i1 <= 0.0:
        return (f"SOLO POSIZIONE 2: la posizione 1 non ha edge (f1*=0). "
                f"Size ottima f2={o2:.2%} con g={go:+.3%}/round e "
                f"σ={so:.2%}/round (ρ={rr:+.2f}).")
    if i2 <= 0.0:
        return (f"SOLO POSIZIONE 1: la posizione 2 non ha edge (f2*=0). "
                f"Size ottima f1={o1:.2%} con g={go:+.3%}/round e "
                f"σ={so:.2%}/round (ρ={rr:+.2f}).")
    if g_ind is None or sigma_ind is None:
        somma = i1 + i2
        return (f"RISCHIO ROVINA: le Kelly indipendenti sommano al {somma:.0%} "
                f">= 100%: nello scenario peggiore il capitale si azzera. "
                f"L'ottimo congiunto (ρ={rr:+.2f}) usa f1={o1:.2%}, "
                f"f2={o2:.2%} (somma {o1+o2:.0%}) con g={go:+.3%}/round e "
                f"σ={so:.2%}/round.")
    gi = mh352_num(g_ind, "g_ind")
    si = mh352_num(sigma_ind, "sigma_ind")
    if si <= 0.0:
        raise ValueError("sigma_ind: deve essere > 0")
    rid_sig = (si - so) / si
    dg = go - gi
    migliora = rid_sig > 0.05 or dg > 0.0005
    if rr < -0.05 and migliora:
        return (f"DIVERSIFICAZIONE: con ρ={rr:+.2f} le due posizioni si "
                f"compensano (quando una perde, l'altra tende a vincere). "
                f"L'ottimo congiunto (f1={o1:.2%}, f2={o2:.2%}) dà "
                f"g={go:+.3%}/round contro {gi:+.3%} ({dg:+.2%}) con "
                f"σ={so:.2%} contro {si:.2%}. "
                f"La correlazione negativa permette size più aggressive: "
                f"più crescita attesa, ma volatilità più alta.")
    if rr > 0.30 and migliora:
        return (f"CONTAGIO: con ρ={rr:+.2f} le due posizioni si muovono "
                f"insieme — la doppia perdita diventa più probabile. "
                f"Le Kelly indipendenti (f1={i1:.2%}, f2={i2:.2%}) "
                f"sovrastimano la size: l'ottimo congiunto usa "
                f"f1={o1:.2%}, f2={o2:.2%} con g={go:+.3%}/round "
                f"({dg:+.2%}) e σ={so:.2%} contro {si:.2%}.")
    if migliora:
        return (f"RIDUCI LE SIZE: le Kelly indipendenti (f1={i1:.2%}, "
                f"f2={i2:.2%}) sovrastimano la size congiunta. L'ottimo "
                f"(f1={o1:.2%}, f2={o2:.2%}) dà g={go:+.3%}/round contro "
                f"{gi:+.3%} ({dg:+.2%}) con σ={so:.2%} contro {si:.2%} "
                f"({rid_sig:+.0%} di volatilità).")
    return (f"OTTIMO ≈ INDIPENDENTI: con f1={i1:.2%} e f2={i2:.2%} le due "
            f"posizioni sono quasi indipendenti nel sizing (ottimo congiunto "
            f"f1={o1:.2%}, f2={o2:.2%}, Δg={dg:+.3%}/round, ρ={rr:+.2f}). "
            f"Puoi usare le Kelly calcolate separatamente.")


def mh352_confronto(p1, win1, loss1, p2, win2, loss2, rho):
    pp1 = mh352_num(p1, "p1")
    pp2 = mh352_num(p2, "p2")
    if not 0.0 < pp1 < 1.0:
        raise ValueError("p1: deve stare in (0, 1)")
    if not 0.0 < pp2 < 1.0:
        raise ValueError("p2: deve stare in (0, 1)")
    w1 = mh352_num(win1, "vincita 1")
    l1 = mh352_num(loss1, "perdita 1")
    w2 = mh352_num(win2, "vincita 2")
    l2 = mh352_num(loss2, "perdita 2")
    rr = mh352_num(rho, "rho")
    if w1 <= 0.0 or l1 <= 0.0 or w2 <= 0.0 or l2 <= 0.0:
        raise ValueError("vincite/perdite: devono essere > 0")
    b1, b2 = w1 / l1, w2 / l2
    bnd = mh352_rho_bounds(pp1, pp2)
    if not bnd["rho_min"] - 1e-9 <= rr <= bnd["rho_max"] + 1e-9:
        raise ValueError(
            f"rho={rr}: fuori da [{bnd['rho_min']:.3f}, {bnd['rho_max']:.3f}]")
    f1_ind = mh352_kelly_f(pp1, b1)
    f2_ind = mh352_kelly_f(pp2, b2)
    opt = mh352_ottimo(pp1, b1, pp2, b2, rr)
    if f1_ind + f2_ind < 1.0:
        s_ind = mh352_logstats2(pp1, b1, f1_ind, pp2, b2, f2_ind, rr)
        g_ind, sigma_ind = s_ind["g"], s_ind["sigma"]
    else:
        g_ind, sigma_ind = None, None
    s_half = mh352_logstats2(pp1, b1, f1_ind / 2.0, pp2, b2, f2_ind / 2.0, rr)
    strategie = [
        {"strategia": "Kelly indipendenti", "f1": f1_ind, "f2": f2_ind,
         "somma": f1_ind + f2_ind, "g": g_ind, "sigma": sigma_ind},
        {"strategia": "Half-Kelly indipendenti", "f1": f1_ind / 2.0,
         "f2": f2_ind / 2.0, "somma": (f1_ind + f2_ind) / 2.0,
         "g": s_half["g"], "sigma": s_half["sigma"]},
        {"strategia": f"Ottimo congiunto (ρ={rr:+.2f})",
         "f1": opt["f1"], "f2": opt["f2"],
         "somma": opt["f1"] + opt["f2"], "g": opt["g"],
         "sigma": opt["sigma"]},
    ]
    tabella_rho = []
    for r0 in (-0.5, 0.0, 0.5):
        if bnd["rho_min"] - 1e-9 <= r0 <= bnd["rho_max"] + 1e-9:
            o0 = mh352_ottimo(pp1, b1, pp2, b2, r0)
            tabella_rho.append({"rho": r0, "f1": o0["f1"], "f2": o0["f2"],
                                "g": o0["g"], "sigma": o0["sigma"]})
    verdetto = mh352_verdetto(f1_ind, f2_ind, opt["f1"], opt["f2"],
                              g_ind, sigma_ind, opt["g"], opt["sigma"], rr)
    return {"p1": pp1, "p2": pp2, "win1": w1, "loss1": l1, "win2": w2,
            "loss2": l2, "b1": b1, "b2": b2, "rho": rr,
            "rho_min": bnd["rho_min"], "rho_max": bnd["rho_max"],
            "f1_ind": f1_ind, "f2_ind": f2_ind,
            "f1_opt": opt["f1"], "f2_opt": opt["f2"],
            "g_opt": opt["g"], "sigma_opt": opt["sigma"],
            "g_ind": g_ind, "sigma_ind": sigma_ind,
            "strategie": strategie, "tabella_rho": tabella_rho,
            "verdetto": verdetto}

def mh351_num(x, nome):
    """Valida uno scalare numerico reale: no bool, no NaN/inf."""
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh351_kelly_f(p, b):
    """Frazione di Kelly f* = (p*b - q)/b; 0.0 se l'edge e' <= 0."""
    pp = mh351_num(p, "p")
    bb = mh351_num(b, "b")
    if not 0.0 < pp < 1.0:
        raise ValueError("p: deve stare in (0, 1)")
    if bb <= 0.0:
        raise ValueError("b: deve essere > 0")
    edge = pp * bb - (1.0 - pp)
    if edge <= 0.0:
        return 0.0
    return edge / bb


def mh351_logstats2(p1, b1, f1, p2, b2, f2):
    """Statistiche del log-return congiunto per round (4 stati).

    Ritorna {"g", "sigma"}: g = crescita logaritmica attesa, sigma =
    deviazione standard del log-return. Vincolo f1+f2 < 1.
    """
    import math
    pp1 = mh351_num(p1, "p1")
    bb1 = mh351_num(b1, "b1")
    ff1 = mh351_num(f1, "f1")
    pp2 = mh351_num(p2, "p2")
    bb2 = mh351_num(b2, "b2")
    ff2 = mh351_num(f2, "f2")
    for _pp, _nm in ((pp1, "p1"), (pp2, "p2")):
        if not 0.0 < _pp < 1.0:
            raise ValueError(f"{_nm}: deve stare in (0, 1)")
    for _bb, _nm in ((bb1, "b1"), (bb2, "b2")):
        if _bb <= 0.0:
            raise ValueError(f"{_nm}: deve essere > 0")
    if ff1 < 0.0 or ff2 < 0.0:
        raise ValueError("f1/f2: devono essere >= 0")
    if ff1 + ff2 >= 1.0:
        raise ValueError("f1+f2: deve stare < 1 (capitale positivo)")
    qq1, qq2 = 1.0 - pp1, 1.0 - pp2
    stati = ((pp1 * pp2, 1.0 + ff1 * bb1 + ff2 * bb2),
             (pp1 * qq2, 1.0 + ff1 * bb1 - ff2),
             (qq1 * pp2, 1.0 - ff1 + ff2 * bb2),
             (qq1 * qq2, 1.0 - ff1 - ff2))
    g = sum(_p * math.log(_r) for _p, _r in stati)
    var = sum(_p * math.log(_r) ** 2 for _p, _r in stati) - g * g
    return {"g": g, "sigma": math.sqrt(max(var, 0.0))}


def mh351_ottimo(p1, b1, p2, b2, step=0.01):
    """Ottimo congiunto (f1, f2): scansione a griglia deterministica.

    Griglia [0, 0.99] a passo `step` con vincolo f1+f2 < 1; tiene il
    primo punto di massimo di g (ordine di scansione crescente).
    Ritorna {"f1", "f2", "g", "sigma"}; se nessuna posizione ha edge,
    ritorna zeri.
    """
    pp1 = mh351_num(p1, "p1")
    bb1 = mh351_num(b1, "b1")
    pp2 = mh351_num(p2, "p2")
    bb2 = mh351_num(b2, "b2")
    st = mh351_num(step, "step")
    if not 0.0 < pp1 < 1.0:
        raise ValueError("p1: deve stare in (0, 1)")
    if not 0.0 < pp2 < 1.0:
        raise ValueError("p2: deve stare in (0, 1)")
    if bb1 <= 0.0 or bb2 <= 0.0:
        raise ValueError("b1/b2: devono essere > 0")
    if not 0.0 < st <= 0.1:
        raise ValueError("step: deve stare in (0, 0.1]")
    if mh351_kelly_f(pp1, bb1) <= 0.0 and mh351_kelly_f(pp2, bb2) <= 0.0:
        return {"f1": 0.0, "f2": 0.0, "g": 0.0, "sigma": 0.0}
    n = int(0.99 / st)
    best = {"f1": 0.0, "f2": 0.0, "g": float("-inf"), "sigma": 0.0}
    for i in range(n + 1):
        for j in range(n + 1):
            f1, f2 = i * st, j * st
            if f1 + f2 >= 1.0:
                continue
            s = mh351_logstats2(pp1, bb1, f1, pp2, bb2, f2)
            if s["g"] > best["g"]:
                best = {"f1": f1, "f2": f2, "g": s["g"],
                        "sigma": s["sigma"]}
    return best


def mh351_verdetto(f1_ind, f2_ind, f1_opt, f2_opt, g_ind, sigma_ind,
                   g_opt, sigma_opt):
    """Verdetto a 5 stati: confronto Kelly indipendenti vs ottimo congiunto.

    g_ind/sigma_ind possono essere None (Kelly indipendenti con somma >= 1:
    rischio rovina, crescita non definita).
    """
    i1 = mh351_num(f1_ind, "f1_ind")
    i2 = mh351_num(f2_ind, "f2_ind")
    o1 = mh351_num(f1_opt, "f1_opt")
    o2 = mh351_num(f2_opt, "f2_opt")
    go = mh351_num(g_opt, "g_opt")
    so = mh351_num(sigma_opt, "sigma_opt")
    if i1 < 0.0 or i2 < 0.0 or o1 < 0.0 or o2 < 0.0:
        raise ValueError("frazioni: devono essere >= 0")
    if o1 + o2 >= 1.0:
        raise ValueError("f1_opt+f2_opt: deve stare < 1")
    if o1 <= 0.0 and o2 <= 0.0:
        return ("NESSUN EDGE — NON TRADARE: nessuna delle due posizioni ha "
                "edge positivo, il sizing ottimale e' zero.")
    if i1 <= 0.0:
        return (f"SOLO POSIZIONE 2: la posizione 1 non ha edge (f1*=0). "
                f"Size ottima f2={o2:.2%} con g={go:+.3%}/round e "
                f"σ={so:.2%}/round.")
    if i2 <= 0.0:
        return (f"SOLO POSIZIONE 1: la posizione 2 non ha edge (f2*=0). "
                f"Size ottima f1={o1:.2%} con g={go:+.3%}/round e "
                f"σ={so:.2%}/round.")
    somma = i1 + i2
    if g_ind is None or sigma_ind is None:
        return (f"RISCHIO ROVINA: le Kelly indipendenti sommano al {somma:.0%} "
                f">= 100%: nello scenario peggiore (doppia perdita) il "
                f"capitale si azzera. L'ottimo congiunto usa f1={o1:.2%}, "
                f"f2={o2:.2%} (somma {o1+o2:.0%}) con g={go:+.3%}/round e "
                f"σ={so:.2%}/round.")
    gi = mh351_num(g_ind, "g_ind")
    si = mh351_num(sigma_ind, "sigma_ind")
    if si <= 0.0:
        raise ValueError("sigma_ind: deve essere > 0")
    rid_sig = (si - so) / si
    dg = go - gi
    if rid_sig > 0.05 or dg > 0.0005:
        return (f"RIDUCI LE SIZE: le Kelly indipendenti (f1={i1:.2%}, "
                f"f2={i2:.2%}) sovrastimano la size congiunta. L'ottimo "
                f"(f1={o1:.2%}, f2={o2:.2%}) dà g={go:+.3%}/round contro "
                f"{gi:+.3%} ({dg:+.2%}) con σ={so:.2%} contro {si:.2%} "
                f"({rid_sig:+.0%} di volatilità). Due posizioni simultanee "
                f"condividono il rischio: la size va ridotta.")
    return (f"OTTIMO ≈ INDIPENDENTI: con f1={i1:.2%} e f2={i2:.2%} le due "
            f"posizioni sono quasi indipendenti nel sizing (ottimo congiunto "
            f"f1={o1:.2%}, f2={o2:.2%}, Δg={dg:+.3%}/round). Puoi usare le "
            f"Kelly calcolate separatamente.")


def mh351_confronto(p1, win1, loss1, p2, win2, loss2):
    """Wrapper: Kelly indipendenti, ottimo congiunto, strategie, verdetto."""
    pp1 = mh351_num(p1, "p1")
    pp2 = mh351_num(p2, "p2")
    if not 0.0 < pp1 < 1.0:
        raise ValueError("p1: deve stare in (0, 1)")
    if not 0.0 < pp2 < 1.0:
        raise ValueError("p2: deve stare in (0, 1)")
    w1 = mh351_num(win1, "vincita 1")
    l1 = mh351_num(loss1, "perdita 1")
    w2 = mh351_num(win2, "vincita 2")
    l2 = mh351_num(loss2, "perdita 2")
    if w1 <= 0.0 or l1 <= 0.0 or w2 <= 0.0 or l2 <= 0.0:
        raise ValueError("vincite/perdite: devono essere > 0")
    b1, b2 = w1 / l1, w2 / l2
    f1_ind = mh351_kelly_f(pp1, b1)
    f2_ind = mh351_kelly_f(pp2, b2)
    opt = mh351_ottimo(pp1, b1, pp2, b2)
    if f1_ind + f2_ind < 1.0:
        s_ind = mh351_logstats2(pp1, b1, f1_ind, pp2, b2, f2_ind)
        g_ind, sigma_ind = s_ind["g"], s_ind["sigma"]
    else:
        g_ind, sigma_ind = None, None
    s_half = mh351_logstats2(pp1, b1, f1_ind / 2.0, pp2, b2, f2_ind / 2.0)
    strategie = [
        {"strategia": "Kelly indipendenti", "f1": f1_ind, "f2": f2_ind,
         "somma": f1_ind + f2_ind, "g": g_ind, "sigma": sigma_ind},
        {"strategia": "Half-Kelly indipendenti", "f1": f1_ind / 2.0,
         "f2": f2_ind / 2.0, "somma": (f1_ind + f2_ind) / 2.0,
         "g": s_half["g"], "sigma": s_half["sigma"]},
        {"strategia": "Ottimo congiunto", "f1": opt["f1"], "f2": opt["f2"],
         "somma": opt["f1"] + opt["f2"], "g": opt["g"],
         "sigma": opt["sigma"]},
    ]
    verdetto = mh351_verdetto(f1_ind, f2_ind, opt["f1"], opt["f2"],
                              g_ind, sigma_ind, opt["g"], opt["sigma"])
    return {"p1": pp1, "p2": pp2, "win1": w1, "loss1": l1, "win2": w2,
            "loss2": l2, "b1": b1, "b2": b2, "f1_ind": f1_ind,
            "f2_ind": f2_ind, "f1_opt": opt["f1"], "f2_opt": opt["f2"],
            "g_opt": opt["g"], "sigma_opt": opt["sigma"], "g_ind": g_ind,
            "sigma_ind": sigma_ind, "strategie": strategie,
            "verdetto": verdetto}

def mh350_num(x, nome):
    """Valida uno scalare numerico reale: no bool, no NaN/inf."""
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh350_kelly_f(p, b):
    """Frazione di Kelly f* = (p*b - q)/b; 0.0 se l'edge e' <= 0."""
    pp = mh350_num(p, "p")
    bb = mh350_num(b, "b")
    if not 0.0 < pp < 1.0:
        raise ValueError("p: deve stare in (0, 1)")
    if bb <= 0.0:
        raise ValueError("b: deve essere > 0")
    edge = pp * bb - (1.0 - pp)
    if edge <= 0.0:
        return 0.0
    return edge / bb


def mh350_logstats(p, b, f):
    """Statistiche del log-return per trade con frazione f di capitale.

    Ritorna {"g", "sigma", "ratio"}: g = crescita logaritmica attesa,
    sigma = deviazione standard del log-return, ratio = g/sigma
    (0.0 se sigma e' 0).
    """
    import math
    pp = mh350_num(p, "p")
    bb = mh350_num(b, "b")
    ff = mh350_num(f, "f")
    if not 0.0 < pp < 1.0:
        raise ValueError("p: deve stare in (0, 1)")
    if bb <= 0.0:
        raise ValueError("b: deve essere > 0")
    if not 0.0 <= ff < 1.0:
        raise ValueError("f: deve stare in [0, 1)")
    x1 = math.log(1.0 + ff * bb)
    x2 = math.log(1.0 - ff)
    g = pp * x1 + (1.0 - pp) * x2
    var = pp * x1 * x1 + (1.0 - pp) * x2 * x2 - g * g
    sigma = math.sqrt(max(var, 0.0))
    return {"g": g, "sigma": sigma,
            "ratio": g / sigma if sigma > 0.0 else 0.0}


def mh350_lambda_max(f_hat, p_lo, b):
    """Max λ in (0, 2] con g(λ·f̂; p_lo) >= 0; 0.0 se f̂ <= 0 o edge
    worst <= 0. Scansione deterministica a passo 0.001."""
    fh = mh350_num(f_hat, "f_hat")
    pl = mh350_num(p_lo, "p_lo")
    bb = mh350_num(b, "b")
    if not 0.0 < pl < 1.0:
        raise ValueError("p_lo: deve stare in (0, 1)")
    if bb <= 0.0:
        raise ValueError("b: deve essere > 0")
    if fh <= 0.0:
        return 0.0
    if mh350_kelly_f(pl, bb) <= 0.0:
        return 0.0
    best = 0.0
    for i in range(1, 2001):
        lam = i / 1000.0
        if mh350_logstats(pl, bb, lam * fh)["g"] >= 0.0:
            best = lam
    return best


def mh350_verdetto(f_hat, f_lo, lam_max, lam, g_lo, p_lo):
    """Verdetto in 4 stati: NESSUN EDGE / EDGE FRAGILE / OVERBET / ROBUSTO."""
    fs = mh350_num(f_hat, "f_hat")
    fl = mh350_num(f_lo, "f_lo")
    lm = mh350_num(lam_max, "lam_max")
    la = mh350_num(lam, "lam")
    gl = mh350_num(g_lo, "g_lo")
    pl = mh350_num(p_lo, "p_lo")
    if not 0.0 < la <= 2.0:
        raise ValueError("lam: deve stare in (0, 2]")
    if not 0.0 < pl < 1.0:
        raise ValueError("p_lo: deve stare in (0, 1)")
    if fs <= 0.0:
        return ("NESSUN EDGE — NON TRADARE: il Kelly alla probabilita' "
                "stimata e' zero (edge <= 0): nessun sizing puo' far "
                "crescere il capitale.")
    if fl <= 0.0:
        return (f"EDGE FRAGILE — NON SIZARE SUL PUNTO CENTRALE: se la vera "
                f"probabilita' e' p-e = {pl:.0%}, il Kelly vero e' zero e "
                f"qualsiasi size positiva distrugge capitale nel worst "
                f"case. Riduci l'incertezza della stima (piu' dati) o "
                f"resta fuori.")
    if gl < 0.0:
        return (f"OVERBET NEL WORST CASE — la size λ·f* = {la * fs:.2%} "
                f"con p-e = {pl:.0%} ha crescita NEGATIVA "
                f"({gl:+.3%}/trade): superi ~2x il Kelly vero. Riduci a "
                f"λ ≤ {lm:.2f} (size ≤ {lm * fs:.2%}) oppure resta fuori.")
    return (f"ROBUSTO — con λ = {la:.2f} la size f = {la * fs:.2%} cresce "
            f"anche nel worst case p-e = {pl:.0%} ({gl:+.3%}/trade); "
            f"λ_max ≈ {lm:.2f}: oltre quella frazione la crescita nel "
            f"worst case diventa negativa.")


def mh350_robusto(p, e, win, loss, lam=0.5):
    """Wrapper: Kelly sui 3 scenari (p-e, p, p+e), size λ·f̂, worst case,
    λ_max e verdetto."""
    pp = mh350_num(p, "p")
    if not 0.0 < pp < 1.0:
        raise ValueError("p: deve stare in (0, 1)")
    ee = mh350_num(e, "e")
    if ee <= 0.0:
        raise ValueError("e: deve essere > 0")
    p_lo = pp - ee
    p_hi = pp + ee
    if p_lo <= 0.0:
        raise ValueError("p - e: deve restare > 0")
    if p_hi >= 1.0:
        raise ValueError("p + e: deve restare < 1")
    w = mh350_num(win, "vincita")
    l = mh350_num(loss, "perdita")
    if w <= 0.0 or l <= 0.0:
        raise ValueError("vincita/perdita: devono essere > 0")
    la = mh350_num(lam, "lam")
    if not 0.0 < la <= 2.0:
        raise ValueError("lam: deve stare in (0, 2]")
    b = w / l
    f_hat = mh350_kelly_f(pp, b)
    f_lo = mh350_kelly_f(p_lo, b)
    f_hi = mh350_kelly_f(p_hi, b)
    f_scelta = la * f_hat
    if f_scelta >= 1.0:
        raise ValueError("λ·f*: deve restare < 1")
    s_lo = mh350_logstats(p_lo, b, f_scelta)
    s_mid = mh350_logstats(pp, b, f_scelta)
    s_hi = mh350_logstats(p_hi, b, f_scelta)
    lam_max = mh350_lambda_max(f_hat, p_lo, b)
    righe = []
    for ps, nm in ((p_lo, "pessimistico (p-e)"), (pp, "centrale (p)"),
                   (p_hi, "ottimistico (p+e)")):
        s = mh350_logstats(ps, b, f_scelta)
        righe.append({"scenario": nm, "p": ps,
                      "f_star": mh350_kelly_f(ps, b), "g": s["g"],
                      "sigma": s["sigma"], "ratio": s["ratio"]})
    verdetto = mh350_verdetto(f_hat, f_lo, lam_max, la, s_lo["g"], p_lo)
    return {"p": pp, "e": ee, "p_lo": p_lo, "p_hi": p_hi, "b": b,
            "f_hat": f_hat, "f_lo": f_lo, "f_hi": f_hi,
            "lam": la, "f_scelta": f_scelta,
            "g_lo": s_lo["g"], "sigma_lo": s_lo["sigma"],
            "g": s_mid["g"], "sigma": s_mid["sigma"],
            "ratio": (s_mid["g"] / s_mid["sigma"]
                      if s_mid["sigma"] > 0.0 else 0.0),
            "lam_max": lam_max, "righe": righe, "verdetto": verdetto}

def mh349_num(x, nome):
    """Valida uno scalare numerico reale: no bool, no NaN/inf."""
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh349_kelly_f(p, b):
    """Frazione di Kelly f* = (p*b - q)/b; 0.0 se l'edge e' <= 0."""
    pp = mh349_num(p, "p")
    bb = mh349_num(b, "b")
    if not 0.0 < pp < 1.0:
        raise ValueError("p: deve stare in (0, 1)")
    if bb <= 0.0:
        raise ValueError("b: deve essere > 0")
    edge = pp * bb - (1.0 - pp)
    if edge <= 0.0:
        return 0.0
    return edge / bb


def mh349_logstats(p, b, f):
    """Statistiche del log-return per trade con frazione f di capitale.

    Ritorna {"g", "sigma", "ratio"}: g = crescita logaritmica attesa,
    sigma = deviazione standard del log-return, ratio = g/sigma
    (0.0 se sigma e' 0).
    """
    import math
    pp = mh349_num(p, "p")
    bb = mh349_num(b, "b")
    ff = mh349_num(f, "f")
    if not 0.0 < pp < 1.0:
        raise ValueError("p: deve stare in (0, 1)")
    if bb <= 0.0:
        raise ValueError("b: deve essere > 0")
    if not 0.0 <= ff < 1.0:
        raise ValueError("f: deve stare in [0, 1)")
    x1 = math.log(1.0 + ff * bb)
    x2 = math.log(1.0 - ff)
    g = pp * x1 + (1.0 - pp) * x2
    var = pp * x1 * x1 + (1.0 - pp) * x2 * x2 - g * g
    sigma = math.sqrt(max(var, 0.0))
    return {"g": g, "sigma": sigma,
            "ratio": g / sigma if sigma > 0.0 else 0.0}


def mh349_dd_prob(g, sigma, d):
    """P(drawdown >= d) ≈ exp(-2·g·|ln(1-d)|/σ²), clip in [0, 1].

    Approssimazione per moto browniano con drift (g, sigma per trade).
    Se g <= 0 il drawdown e' quasi certo -> 1.0.
    """
    import math
    gg = mh349_num(g, "g")
    ss = mh349_num(sigma, "sigma")
    dd = mh349_num(d, "d")
    if ss < 0.0:
        raise ValueError("sigma: deve essere >= 0")
    if not 0.0 < dd < 1.0:
        raise ValueError("d: deve stare in (0, 1)")
    if gg <= 0.0 or ss <= 0.0:
        return 1.0
    p = math.exp(-2.0 * gg * abs(math.log(1.0 - dd)) / (ss * ss))
    return min(1.0, max(0.0, p))


def mh349_verdetto(f_star, g_half, quota_half, sigma_half, sigma_full,
                   pdd_half, pdd_full, d):
    """Verdetto: half-Kelly vs full Kelly con i numeri calcolati."""
    fs = mh349_num(f_star, "f_star")
    gh = mh349_num(g_half, "g_half")
    qh = mh349_num(quota_half, "quota_half")
    sh = mh349_num(sigma_half, "sigma_half")
    sf = mh349_num(sigma_full, "sigma_full")
    ph = mh349_num(pdd_half, "pdd_half")
    pf = mh349_num(pdd_full, "pdd_full")
    dd = mh349_num(d, "d")
    if not 0.0 < dd < 1.0:
        raise ValueError("d: deve stare in (0, 1)")
    if fs <= 0.0:
        return ("NESSUN EDGE — NON TRADARE: il Kelly e' zero, nessuna "
                "frazione di Kelly puo' far crescere il capitale.")
    vol_raz = sh / sf if sf > 0.0 else 0.0
    return (f"HALF-KELLY: con λ=0.50 ottieni il {qh:.0%} della crescita "
            f"massima ({gh:+.3%}/trade) con solo il {vol_raz:.0%} della "
            f"volatilita' del full Kelly ({sh:.2%} vs {sf:.2%}/trade); "
            f"P(drawdown ≥ {dd:.0%}) scende da {pf:.0%} a {ph:.0%}. Il full "
            f"Kelly massimizza la crescita ma alza molto il rischio di "
            f"drawdown.")


def mh349_confronto(p, win, loss, lam_scelta=0.5, d=0.20,
                    lambdas=(0.25, 0.5, 0.75, 1.0, 1.5)):
    """Wrapper: Kelly, frazione scelta, tabella frazioni, verdetto."""
    pp = mh349_num(p, "p")
    if not 0.0 < pp < 1.0:
        raise ValueError("p: deve stare in (0, 1)")
    w = mh349_num(win, "vincita")
    l = mh349_num(loss, "perdita")
    if w <= 0.0 or l <= 0.0:
        raise ValueError("vincita/perdita: devono essere > 0")
    lam = mh349_num(lam_scelta, "lambda")
    if not 0.0 < lam <= 2.0:
        raise ValueError("lambda: deve stare in (0, 2]")
    dd = mh349_num(d, "d")
    if not 0.0 < dd < 1.0:
        raise ValueError("d: deve stare in (0, 1)")
    b = w / l
    f_star = mh349_kelly_f(pp, b)
    s_full = mh349_logstats(pp, b, f_star)
    righe = []
    for L in lambdas:
        LL = mh349_num(L, "lambda_tabella")
        if not 0.0 < LL <= 2.0:
            raise ValueError("lambda_tabella: deve stare in (0, 2]")
        s = mh349_logstats(pp, b, LL * f_star)
        righe.append({"lambda": LL, "f": LL * f_star, "g": s["g"],
                      "sigma": s["sigma"], "ratio": s["ratio"],
                      "quota_crescita": (s["g"] / s_full["g"]
                                         if s_full["g"] > 0.0 else 0.0),
                      "p_dd": mh349_dd_prob(s["g"], s["sigma"], dd)})
    s_sel = mh349_logstats(pp, b, lam * f_star)
    s_half = mh349_logstats(pp, b, 0.5 * f_star)
    pdd_half = mh349_dd_prob(s_half["g"], s_half["sigma"], dd)
    pdd_full = mh349_dd_prob(s_full["g"], s_full["sigma"], dd)
    quota_half = (s_half["g"] / s_full["g"]
                  if s_full["g"] > 0.0 else 0.0)
    verdetto = mh349_verdetto(f_star, s_half["g"], quota_half,
                              s_half["sigma"], s_full["sigma"],
                              pdd_half, pdd_full, dd)
    return {"p": pp, "win": w, "loss": l, "b": b, "f_star": f_star,
            "lam_scelta": lam, "f_scelta": lam * f_star,
            "g": s_sel["g"], "sigma": s_sel["sigma"],
            "ratio": s_sel["ratio"],
            "p_dd": mh349_dd_prob(s_sel["g"], s_sel["sigma"], dd),
            "d": dd, "righe": righe,
            "g_full": s_full["g"], "sigma_full": s_full["sigma"],
            "verdetto": verdetto}

def mh348_num(x, nome):
    """Valida uno scalare numerico reale: no bool, no NaN/inf."""
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh348_int(x, nome, minimo, massimo):
    """Valida un intero in [minimo, massimo]: no bool."""
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Integral):
        raise ValueError(f"{nome}: deve essere un intero")
    v = int(x)
    if not minimo <= v <= massimo:
        raise ValueError(f"{nome}: deve stare in [{minimo}, {massimo}]")
    return v


def mh348_b_netto(win, loss, costo):
    """Payoff netto b = (win - c)/(loss + c).

    Richiede win > 0, loss > 0, 0 <= c < win: se il costo mangia tutta
    la vincita l'edge netto e' azzerato e il trade non ha senso.
    """
    w = mh348_num(win, "vincita")
    l = mh348_num(loss, "perdita")
    c = mh348_num(costo, "costo")
    if w <= 0.0:
        raise ValueError("vincita: deve essere > 0")
    if l <= 0.0:
        raise ValueError("perdita: deve essere > 0")
    if c < 0.0:
        raise ValueError("costo: deve essere >= 0")
    if c >= w:
        raise ValueError("costo: deve essere < vincita (edge netto azzerato)")
    return (w - c) / (l + c)


def mh348_f_star(p, b):
    """Frazione di Kelly f* = (p*b - q)/b; 0.0 se l'edge e' <= 0."""
    pp = mh348_num(p, "p")
    bb = mh348_num(b, "b")
    if not 0.0 < pp < 1.0:
        raise ValueError("p: deve stare in (0, 1)")
    if bb <= 0.0:
        raise ValueError("b: deve essere > 0")
    edge = pp * bb - (1.0 - pp)
    if edge <= 0.0:
        return 0.0
    return edge / bb


def mh348_g(p, b, f):
    """Crescita logaritmica attesa per trade: p*ln(1+f*b) + q*ln(1-f)."""
    import math
    pp = mh348_num(p, "p")
    bb = mh348_num(b, "b")
    ff = mh348_num(f, "f")
    if not 0.0 < pp < 1.0:
        raise ValueError("p: deve stare in (0, 1)")
    if bb <= 0.0:
        raise ValueError("b: deve essere > 0")
    if not 0.0 <= ff < 1.0:
        raise ValueError("f: deve stare in [0, 1)")
    return pp * math.log(1.0 + ff * bb) + (1.0 - pp) * math.log(1.0 - ff)


def mh348_verdetto(edge_netto, f_netto, f_lordo, f_min):
    """Verdetto a 3 stati: costi sostenibili / erosivi / edge azzerato."""
    en = mh348_num(edge_netto, "edge_netto")
    fn = mh348_num(f_netto, "f_netto")
    fl = mh348_num(f_lordo, "f_lordo")
    fm = mh348_num(f_min, "f_min")
    if not 0.0 < fm < 1.0:
        raise ValueError("f_min: deve stare in (0, 1)")
    if en <= 0.0 or fn <= 0.0:
        return ("EDGE AZZERATO — NON TRADARE: i costi mangiano tutto il "
                "vantaggio statistico (f* netto = 0).")
    if fn < fm:
        return (f"COSTI EROSIVI — RIDURRE f: il sizing netto ({fn:.2%}) "
                f"scende sotto la soglia operativa ({fm:.2%}).")
    erosione = 1.0 - fn / fl if fl > 0.0 else 0.0
    return (f"COSTI SOSTENIBILI: f* netto {fn:.2%} contro f* lordo "
            f"{fl:.2%} (erosione {erosione:.1%}).")


def mh348_misure(p, win, loss, costo, f_min,
                 livelli_costo=(0.0, 1.0, 2.0, 5.0, 10.0)):
    """Wrapper completo: Kelly lordo/netto, crescita, tabella, verdetto."""
    pp = mh348_num(p, "p")
    if not 0.0 < pp < 1.0:
        raise ValueError("p: deve stare in (0, 1)")
    fm = mh348_num(f_min, "f_min")
    if not 0.0 < fm < 1.0:
        raise ValueError("f_min: deve stare in (0, 1)")
    w = mh348_num(win, "vincita")
    l = mh348_num(loss, "perdita")
    if w <= 0.0 or l <= 0.0:
        raise ValueError("vincita/perdita: devono essere > 0")
    b_lordo = w / l
    f_lordo = mh348_f_star(pp, b_lordo)
    g_lordo = mh348_g(pp, b_lordo, f_lordo)
    b_netto = mh348_b_netto(w, l, costo)
    f_netto = mh348_f_star(pp, b_netto)
    g_netto = mh348_g(pp, b_netto, f_netto)
    edge_netto = pp * b_netto - (1.0 - pp)
    erosione = 1.0 - f_netto / f_lordo if f_lordo > 0.0 else 0.0
    tabella = []
    for c in livelli_costo:
        cc = mh348_num(c, "livello_costo")
        if cc < 0.0 or cc >= w:
            tabella.append({"costo": cc, "b_netto": None, "f_star": 0.0,
                            "g": 0.0, "stato": "edge azzerato"})
            continue
        bc = (w - cc) / (l + cc)
        fc = mh348_f_star(pp, bc)
        tabella.append({"costo": cc, "b_netto": bc, "f_star": fc,
                        "g": mh348_g(pp, bc, fc),
                        "stato": "ok" if fc > 0.0 else "edge azzerato"})
    return {"p": pp, "win": w, "loss": l, "costo": mh348_num(costo, "costo"),
            "f_min": fm, "b_lordo": b_lordo, "f_lordo": f_lordo,
            "g_lordo": g_lordo, "b_netto": b_netto, "f_netto": f_netto,
            "g_netto": g_netto, "edge_netto": edge_netto,
            "erosione": erosione, "tabella": tabella,
            "verdetto": mh348_verdetto(edge_netto, f_netto, f_lordo, fm)}

def mh347_num(x, nome):
    """Valida uno scalare numerico reale: no bool, no NaN/inf."""
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh347_int(x, nome, minimo, massimo):
    """Valida un intero in [minimo, massimo]: no bool."""
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Integral):
        raise ValueError(f"{nome}: deve essere un intero")
    v = int(x)
    if not minimo <= v <= massimo:
        raise ValueError(f"{nome}: deve stare in [{minimo}, {massimo}]")
    return v


def mh347_norm_ppf(q):
    """Quantile della normale standard (approssimazione di Acklam).

    q in (0, 1) esclusi. Precisione ~1e-9: ppf(0.975) = 1.9599639845.
    """
    import math
    qq = mh347_num(q, "quantile")
    if not 0.0 < qq < 1.0:
        raise ValueError("quantile: deve stare in (0, 1)")
    a = (-3.969683028665376e+01, 2.209460984245205e+02,
         -2.759285104469687e+02, 1.383577518672690e+02,
         -3.066479806614716e+01, 2.506628277459239e+00)
    b = (-5.447609879822406e+01, 1.615858368580409e+02,
         -1.556989798598866e+02, 6.680131188771972e+01,
         -1.328068155288572e+01)
    c = (-7.784894002430293e-03, -3.223964580411365e-01,
         -2.400758277161838e+00, -2.549732539343734e+00,
         4.374664141464968e+00, 2.938163982698783e+00)
    d = (7.784695709041462e-03, 3.224671290700398e-01,
         2.445134137142996e+00, 3.754408661907416e+00)
    plow, phigh = 0.02425, 1.0 - 0.02425
    if qq < plow:
        x = math.sqrt(-2.0 * math.log(qq))
        num = (((((c[0] * x + c[1]) * x + c[2]) * x + c[3]) * x + c[4]) * x
               + c[5])
        den = ((((d[0] * x + d[1]) * x + d[2]) * x + d[3]) * x + 1.0)
        return num / den
    if qq <= phigh:
        x = qq - 0.5
        r = x * x
        num = (((((a[0] * r + a[1]) * r + a[2]) * r + a[3]) * r + a[4]) * r
               + a[5]) * x
        den = (((((b[0] * r + b[1]) * r + b[2]) * r + b[3]) * r + b[4]) * r
               + 1.0)
        return num / den
    x = math.sqrt(-2.0 * math.log(1.0 - qq))
    num = (((((c[0] * x + c[1]) * x + c[2]) * x + c[3]) * x + c[4]) * x
            + c[5])
    den = ((((d[0] * x + d[1]) * x + d[2]) * x + d[3]) * x + 1.0)
    return -num / den


def mh347_var_es(p, b, f, n_trade, n_sim, conf, seed):
    """VaR ed Expected Shortfall del P&L dopo n_trade trade.

    Riusa mh346_simula (stessi parametri, barriera interna 0.5 non usata
    qui). Perdite relative L_i = 1 - C_i. VaR(conf) = percentile di L a
    conf; ES(conf) = media delle L_i >= VaR. Cross-check analitico con la
    normale su log C_N: VaR_analitico = 1 - exp(N*g + z_{1-conf}*sd_N),
    sd_N = sqrt(N*p*q)*|ln((1+f*b)/(1-f))|. Ritorna dict con parametri,
    var, es, var_analitico, perdite (lista L_i), n_coda (trade oltre il
    VaR), capitale mediano e P5 per riferimento.
    """
    import math
    pp = mh347_num(p, "probabilita' di vincita")
    bb = mh347_num(b, "rapporto vincita/perdita")
    ff = mh347_num(f, "frazione scommessa")
    if not 0.0 < pp < 1.0:
        raise ValueError("probabilita' di vincita: deve stare in (0, 1)")
    if bb <= 0.0:
        raise ValueError("rapporto vincita/perdita: deve essere > 0")
    if not 0.0 <= ff < 1.0:
        raise ValueError("frazione scommessa: deve stare in [0, 1)")
    nt = mh347_int(n_trade, "numero di trade", 1, 100000)
    ns = mh347_int(n_sim, "numero di simulazioni", 100, 200000)
    cf = mh347_num(conf, "confidenza")
    if not 0.5 < cf < 1.0:
        raise ValueError("confidenza: deve stare in (0.5, 1)")
    sd = mh347_int(seed, "seed", 0, 2 ** 31 - 1)
    sim = mh346_simula(pp, bb, ff, nt, ns, 0.5, sd)
    perdite = [1.0 - c for c in sim["finali"]]
    var = mh346_percentile(perdite, cf)
    coda = [x for x in perdite if x >= var]
    es = sum(coda) / len(coda)
    g = sim["g"]
    up = 1.0 + ff * bb
    down = 1.0 - ff
    sig2 = pp * (1.0 - pp) * (math.log(up / down)) ** 2
    sd_n = math.sqrt(nt * sig2)
    z = mh347_norm_ppf(1.0 - cf)
    var_analitico = 1.0 - math.exp(nt * g + z * sd_n)
    return {"p": pp, "b": bb, "f": ff, "n_trade": nt, "n_sim": ns,
            "conf": cf, "seed": sd, "g": g, "var": var, "es": es,
            "var_analitico": var_analitico, "perdite": perdite,
            "n_coda": len(coda), "cap_mediana": sim["cap_mediana"],
            "cap_p5": sim["cap_p5"]}


def mh347_verdetto(var, var_max):
    """Verdetto operativo a 3 stati contro la soglia var_max.

    var_max in (0, 1). var <= var_max -> VAR NEI LIMITI;
    var <= 1.5*var_max -> SOTTO OSSERVAZIONE; altrimenti RIDURRE f.
    """
    vv = mh347_num(var, "VaR")
    vm = mh347_num(var_max, "soglia VaR_max")
    if not 0.0 < vm < 1.0:
        raise ValueError("soglia VaR_max: deve stare in (0, 1)")
    if vv <= vm:
        return (f"VAR NEI LIMITI (VaR = {vv:.1%} <= {vm:.0%}): il P&L di "
                f"coda resta entro la soglia del desk.")
    if vv <= 1.5 * vm:
        return (f"SOTTO OSSERVAZIONE (VaR = {vv:.1%} > {vm:.0%}): la coda "
                f"sfonda la soglia ma resta contenuta, monitorare o "
                f"tagliare f.")
    return (f"RIDURRE f (VaR = {vv:.1%} >> {vm:.0%}): la coda delle "
            f"perdite e' troppo pesante per questa soglia.")


def mh347_misure(p, win, loss, f, n_trade, n_sim, conf, var_max, seed):
    """Wrapper: da p/win/loss al VaR/ES + verdetto.

    win, loss > 0 (stessa unita', conta solo b = win/loss). var_max in
    (0, 1). Ritorna il dict di mh347_var_es arricchito con win, loss,
    var_max e verdetto testuale.
    """
    ww = mh347_num(win, "vincita media")
    ll = mh347_num(loss, "perdita media")
    if ww <= 0.0:
        raise ValueError("vincita media: deve essere > 0")
    if ll <= 0.0:
        raise ValueError("perdita media: deve essere > 0")
    vm = mh347_num(var_max, "soglia VaR_max")
    if not 0.0 < vm < 1.0:
        raise ValueError("soglia VaR_max: deve stare in (0, 1)")
    ve = mh347_var_es(p, ww / ll, f, n_trade, n_sim, conf, seed)
    out = dict(ve)
    out.update({"win": ww, "loss": ll, "var_max": vm,
                "verdetto": mh347_verdetto(ve["var"], vm)})
    return out

def mh346_num(x, nome):
    """Valida uno scalare numerico reale: no bool, no NaN/inf."""
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh346_int(x, nome, minimo, massimo):
    """Valida un intero in [minimo, massimo]: no bool."""
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Integral):
        raise ValueError(f"{nome}: deve essere un intero")
    v = int(x)
    if not minimo <= v <= massimo:
        raise ValueError(f"{nome}: deve stare in [{minimo}, {massimo}]")
    return v


def mh346_g(p, b, f):
    """Crescita logaritmica attesa per trade.

    g = p*ln(1+f*b) + q*ln(1-f), con q = 1-p. p in (0, 1) esclusi,
    b > 0, f in [0, 1). g > 0 se e solo se c'e' edge (Kelly).
    """
    import math
    pp = mh346_num(p, "probabilita' di vincita")
    bb = mh346_num(b, "rapporto vincita/perdita")
    ff = mh346_num(f, "frazione scommessa")
    if not 0.0 < pp < 1.0:
        raise ValueError("probabilita' di vincita: deve stare in (0, 1)")
    if bb <= 0.0:
        raise ValueError("rapporto vincita/perdita: deve essere > 0")
    if not 0.0 <= ff < 1.0:
        raise ValueError("frazione scommessa: deve stare in [0, 1)")
    return pp * math.log(1.0 + ff * bb) + (1.0 - pp) * math.log(1.0 - ff)


def mh346_percentile(xs, q):
    """Percentile q in [0, 1] di una lista (interpolazione lineare)."""
    s = sorted(xs)
    n = len(s)
    if n == 1:
        return s[0]
    pos = q * (n - 1)
    lo = int(pos)
    hi = min(lo + 1, n - 1)
    return s[lo] + (s[hi] - s[lo]) * (pos - lo)


def mh346_simula(p, b, f, n_trade, n_sim, barriera, seed):
    """Monte Carlo del capitale con frazione fissa f (deterministico).

    p in (0, 1) esclusi, b > 0, f in [0, 1), n_trade >= 1, n_sim >= 100,
    barriera in (0, 1), seed intero. Ritorna dict con parametri, g,
    cap_medio_atteso (E[C_N] aritmetico), cap_mediano_atteso (exp(N*g)),
    finali (capitali terminali), dd_max (drawdown massimi), cap_mediana,
    cap_p5, cap_p95, p_hit_barriera (frazione di traiettorie che toccano
    la barriera), dd_mediano e curve (percentili P5/P25/mediana/P75/P95
    del capitale per trade t = 0..n_trade).
    """
    import math
    import random
    pp = mh346_num(p, "probabilita' di vincita")
    bb = mh346_num(b, "rapporto vincita/perdita")
    ff = mh346_num(f, "frazione scommessa")
    if not 0.0 < pp < 1.0:
        raise ValueError("probabilita' di vincita: deve stare in (0, 1)")
    if bb <= 0.0:
        raise ValueError("rapporto vincita/perdita: deve essere > 0")
    if not 0.0 <= ff < 1.0:
        raise ValueError("frazione scommessa: deve stare in [0, 1)")
    nt = mh346_int(n_trade, "numero di trade", 1, 100000)
    ns = mh346_int(n_sim, "numero di simulazioni", 100, 200000)
    br = mh346_num(barriera, "barriera di drawdown")
    if not 0.0 < br < 1.0:
        raise ValueError("barriera di drawdown: deve stare in (0, 1)")
    sd = mh346_int(seed, "seed", 0, 2 ** 31 - 1)
    rng = random.Random(sd)
    up = 1.0 + ff * bb
    down = 1.0 - ff
    soglia = 1.0 - br
    cols = [[1.0] * ns]
    mins = [1.0] * ns
    for _ in range(nt):
        prev = cols[-1]
        col = [c * (up if rng.random() < pp else down) for c in prev]
        cols.append(col)
        for i, c in enumerate(col):
            if c < mins[i]:
                mins[i] = c
    nomi = ("p5", "p25", "mediana", "p75", "p95")
    qs = (0.05, 0.25, 0.5, 0.75, 0.95)
    curve = {nm: [] for nm in nomi}
    for col in cols:
        for nm, q in zip(nomi, qs):
            curve[nm].append(mh346_percentile(col, q))
    finali = cols[-1]
    dd_max = [1.0 - m for m in mins]
    hit = sum(1 for m in mins if m <= soglia)
    g = mh346_g(pp, bb, ff)
    edge_trade = pp * bb - (1.0 - pp)
    return {"p": pp, "b": bb, "f": ff, "n_trade": nt, "n_sim": ns,
            "barriera": br, "seed": sd, "g": g,
            "cap_medio_atteso": (1.0 + ff * edge_trade) ** nt,
            "cap_mediano_atteso": math.exp(nt * g),
            "finali": finali, "dd_max": dd_max,
            "cap_mediana": mh346_percentile(finali, 0.5),
            "cap_p5": mh346_percentile(finali, 0.05),
            "cap_p95": mh346_percentile(finali, 0.95),
            "p_hit_barriera": hit / ns,
            "dd_mediano": mh346_percentile(dd_max, 0.5),
            "curve": curve}


def mh346_verdetto(p_hit, pmax):
    """Verdetto operativo a 3 stati contro la tolleranza pmax.

    p_hit in [0, 1], pmax in (0, 1). p_hit <= pmax -> SIZING COMPATIBILE;
    p_hit <= 3*pmax -> RISCHIO SOPRA SOGLIA; altrimenti RIDURRE f.
    """
    ph = mh346_num(p_hit, "probabilita' di tocco barriera")
    pm = mh346_num(pmax, "tolleranza Pmax")
    if not 0.0 <= ph <= 1.0:
        raise ValueError("probabilita' di tocco barriera: deve stare in [0, 1]")
    if not 0.0 < pm < 1.0:
        raise ValueError("tolleranza Pmax: deve stare in (0, 1)")
    if ph <= pm:
        return (f"SIZING COMPATIBILE (P tocco barriera = {ph:.2%} <= "
                f"{pm:.0%}): la frazione regge N trade simulati entro la "
                f"tolleranza del desk.")
    if ph <= 3.0 * pm:
        return (f"RISCHIO SOPRA SOGLIA (P tocco barriera = {ph:.2%} > "
                f"{pm:.0%}): valutare se tagliare f o alzare la tolleranza.")
    return (f"RIDURRE f (P tocco barriera = {ph:.2%} >> {pm:.0%}): la "
            f"frazione e' troppo aggressiva per questa barriera.")


def mh346_misure(p, win, loss, f, n_trade, n_sim, barriera, pmax, seed):
    """Wrapper: da p/win/loss alla simulazione + verdetto.

    win, loss > 0 (stessa unita', conta solo b = win/loss). pmax in
    (0, 1). Ritorna il dict di mh346_simula arricchito con win, loss,
    pmax e verdetto testuale.
    """
    ww = mh346_num(win, "vincita media")
    ll = mh346_num(loss, "perdita media")
    if ww <= 0.0:
        raise ValueError("vincita media: deve essere > 0")
    if ll <= 0.0:
        raise ValueError("perdita media: deve essere > 0")
    pm = mh346_num(pmax, "tolleranza Pmax")
    if not 0.0 < pm < 1.0:
        raise ValueError("tolleranza Pmax: deve stare in (0, 1)")
    sim = mh346_simula(p, ww / ll, f, n_trade, n_sim, barriera, seed)
    out = dict(sim)
    out.update({"win": ww, "loss": ll, "pmax": pm,
                "verdetto": mh346_verdetto(sim["p_hit_barriera"], pm)})
    return out

def mh345_num(x, nome):
    """Valida uno scalare numerico reale: no bool, no NaN/inf."""
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh345_kelly(p, b):
    """Kelly pieno: f* = max(0, (p*(b+1)-1)/b).

    p in (0, 1) esclusi, b > 0. Se f* <= 0 (nessun edge) ritorna 0.0.
    """
    pp = mh345_num(p, "probabilita' di vincita")
    bb = mh345_num(b, "rapporto vincita/perdita")
    if not 0.0 < pp < 1.0:
        raise ValueError("probabilita' di vincita: deve stare in (0, 1)")
    if bb <= 0.0:
        raise ValueError("rapporto vincita/perdita: deve essere > 0")
    return max(0.0, (pp * (bb + 1.0) - 1.0) / bb)


def mh345_theta(p, b, f):
    """Coefficiente di Lundberg theta > 0 del processo moltiplicativo.

    Radice di p*(1+f*b)^(-theta) + q*(1-f)^(-theta) = 1, con q = 1-p
    (bisezione, 200 iterazioni). Se il drift logaritmico e' <= 0 non
    esiste radice positiva: ritorna 0.0. p in (0, 1) esclusi, b > 0,
    f in (0, 1).
    """
    import math
    pp = mh345_num(p, "probabilita' di vincita")
    bb = mh345_num(b, "rapporto vincita/perdita")
    ff = mh345_num(f, "frazione scommessa")
    if not 0.0 < pp < 1.0:
        raise ValueError("probabilita' di vincita: deve stare in (0, 1)")
    if bb <= 0.0:
        raise ValueError("rapporto vincita/perdita: deve essere > 0")
    if not 0.0 < ff < 1.0:
        raise ValueError("frazione scommessa: deve stare in (0, 1)")
    up = 1.0 + ff * bb
    down = 1.0 - ff
    drift = pp * math.log(up) + (1.0 - pp) * math.log(down)
    if drift <= 0.0:
        return 0.0

    def _g(th):
        return pp * up ** (-th) + (1.0 - pp) * down ** (-th) - 1.0

    lo, hi = 0.0, 1.0
    while _g(hi) <= 0.0:
        hi *= 2.0
        if hi > 1e12:
            raise ValueError("coefficiente di Lundberg: radice non trovata")
    for _ in range(200):
        mid = (lo + hi) / 2.0
        if _g(mid) <= 0.0:
            lo = mid
        else:
            hi = mid
    return (lo + hi) / 2.0


def mh345_ror(p, b, f, barriera):
    """Risk of ruin R = barriera^theta (Cramer-Lundberg, rovina "ultima").

    theta = coefficiente di Lundberg. theta <= 0 (drift nullo o negativo)
    -> 1.0: rovina certa nel lungo periodo. Ritorno sempre in [0, 1].
    """
    th = mh345_theta(p, b, f)
    br = mh345_num(barriera, "barriera di drawdown")
    if not 0.0 < br < 1.0:
        raise ValueError("barriera di drawdown: deve stare in (0, 1)")
    if th <= 0.0:
        return 1.0
    r = br ** th
    return min(1.0, max(0.0, r))


def mh345_edge(p, b, f):
    """Edge atteso per trade e = f*(p*b - q), in frazione del capitale.

    p in (0, 1) esclusi, b > 0, f in [0, 1).
    """
    pp = mh345_num(p, "probabilita' di vincita")
    bb = mh345_num(b, "rapporto vincita/perdita")
    ff = mh345_num(f, "frazione scommessa")
    if not 0.0 < pp < 1.0:
        raise ValueError("probabilita' di vincita: deve stare in (0, 1)")
    if bb <= 0.0:
        raise ValueError("rapporto vincita/perdita: deve essere > 0")
    if not 0.0 <= ff < 1.0:
        raise ValueError("frazione scommessa: deve stare in [0, 1)")
    return ff * (pp * bb - (1.0 - pp))


def mh345_f_safe(p, b, barriera, rmax):
    """Frazione massima f_safe con R(f) <= rmax (bisezione).

    R(f) = risk of ruin di Cramer-Lundberg, monotono crescente in f:
    esiste un'unica f con R(f) = rmax. f in [1e-6, 0.99]. Se anche la f
    minima viola il vincolo (nessun edge: R = 1 ovunque) ritorna 0.0. Se
    la f massima rispetta il vincolo ritorna 0.99. rmax in (0, 1).
    """
    pp = mh345_num(p, "probabilita' di vincita")
    bb = mh345_num(b, "rapporto vincita/perdita")
    br = mh345_num(barriera, "barriera di drawdown")
    rm = mh345_num(rmax, "ROR massimo accettabile")
    if not 0.0 < pp < 1.0:
        raise ValueError("probabilita' di vincita: deve stare in (0, 1)")
    if bb <= 0.0:
        raise ValueError("rapporto vincita/perdita: deve essere > 0")
    if not 0.0 < br < 1.0:
        raise ValueError("barriera di drawdown: deve stare in (0, 1)")
    if not 0.0 < rm < 1.0:
        raise ValueError("ROR massimo accettabile: deve stare in (0, 1)")
    f_lo, f_hi = 1e-6, 0.99
    if mh345_ror(pp, bb, f_lo, br) > rm:
        return 0.0
    if mh345_ror(pp, bb, f_hi, br) <= rm:
        return f_hi
    for _ in range(200):
        mid = (f_lo + f_hi) / 2.0
        if mh345_ror(pp, bb, mid, br) <= rm:
            f_lo = mid
        else:
            f_hi = mid
    return (f_lo + f_hi) / 2.0


def mh345_misure(p, win, loss, barriera, rmax):
    """Sizing vincolato dal rischio di rovina.

    win, loss > 0 (stessa unita', conta solo il rapporto b = win/loss).
    barriera, rmax in (0, 1). Ritorna b, f_star, f_half, f_safe (bisezione
    su R(f) = rmax), f_rec = min(f_half, f_safe), vincolo_attivo,
    theta/edge/ror alla f raccomandata e verdetto testuale.
    """
    ww = mh345_num(win, "vincita media")
    ll = mh345_num(loss, "perdita media")
    if ww <= 0.0:
        raise ValueError("vincita media: deve essere > 0")
    if ll <= 0.0:
        raise ValueError("perdita media: deve essere > 0")
    pp = mh345_num(p, "probabilita' di vincita")
    if not 0.0 < pp < 1.0:
        raise ValueError("probabilita' di vincita: deve stare in (0, 1)")
    br = mh345_num(barriera, "barriera di drawdown")
    rm = mh345_num(rmax, "ROR massimo accettabile")
    b = ww / ll
    f_star = mh345_kelly(pp, b)
    f_half = f_star / 2.0
    f_safe = mh345_f_safe(pp, b, br, rm)
    f_rec = min(f_half, f_safe)
    return {"p": pp, "win": ww, "loss": ll, "b": b, "f_star": f_star,
            "f_half": f_half, "f_safe": f_safe, "f_rec": f_rec,
            "vincolo_attivo": f_safe < f_half,
            "barriera": br, "rmax": rm,
            "theta": mh345_theta(pp, b, f_rec) if f_rec > 0.0 else 0.0,
            "edge": mh345_edge(pp, b, f_rec),
            "ror": mh345_ror(pp, b, f_rec, br) if f_rec > 0.0 else 1.0,
            "verdetto": mh345_verdetto(f_safe, f_half,
                                       mh345_ror(pp, b, f_rec, br)
                                       if f_rec > 0.0 else 1.0, rm)}


def mh345_verdetto(f_safe, f_half, ror, rmax):
    """Verdetto operativo sul sizing vincolato, a 3 stati.

    f_safe <= 0 (nessun edge) -> SIZING BLOCCATO. f_safe < f_half ->
    VINCOLO ROVINA ATTIVO (tagliare half-Kelly a f_safe). Altrimenti
    HALF-KELLY ENTRO RMAX (nessun taglio necessario).
    """
    fs = mh345_num(f_safe, "frazione anti-rovina")
    fh = mh345_num(f_half, "half-Kelly")
    rr = mh345_num(ror, "risk of ruin")
    rm = mh345_num(rmax, "ROR massimo accettabile")
    if fs <= 0.0:
        return (f"SIZING BLOCCATO (R = {rr:.2%}): con questi parametri non "
                f"esiste sizing con edge positivo e rischio di rovina sotto "
                f"il {rm:.0%}: rivedere la stima di p o del rapporto b.")
    if fs < fh:
        return (f"VINCOLO ROVINA ATTIVO (f_safe = {fs:.2%} < half-Kelly "
                f"{fh:.2%}): half-Kelly ha ROR oltre il limite {rm:.0%}: "
                f"tagliare la frazione a {fs:.2%} (ROR = {rm:.0%} al limite).")
    return (f"HALF-KELLY ENTRO RMAX (ROR = {rr:.2%} <= {rm:.0%}): il "
            f"sizing half-Kelly {fh:.2%} rispetta il vincolo di rovina: "
            f"nessun taglio necessario.")
def mh344_num(x, nome):
    """Valida uno scalare numerico reale: no bool, no NaN/inf."""
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh344_kelly_half(p, b):
    """Half-Kelly: f_h = max(0, f*)/2 con f* = (p*(b+1)-1)/b.

    p in (0, 1) esclusi, b > 0. Se f* <= 0 (nessun edge) ritorna 0.0.
    Default di sizing ereditato dalla tab343.
    """
    pp = mh344_num(p, "probabilita' di vincita")
    bb = mh344_num(b, "rapporto vincita/perdita")
    if not 0.0 < pp < 1.0:
        raise ValueError("probabilita' di vincita: deve stare in (0, 1)")
    if bb <= 0.0:
        raise ValueError("rapporto vincita/perdita: deve essere > 0")
    f_star = (pp * (bb + 1.0) - 1.0) / bb
    return max(0.0, f_star) / 2.0


def mh344_units(f, barriera):
    """Unita' di capitale u = ln(barriera) / ln(1-f).

    Quante perdite di fila servono per toccare la barriera di drawdown.
    f e barriera in (0, 1) esclusi.
    """
    import math
    ff = mh344_num(f, "frazione scommessa")
    br = mh344_num(barriera, "barriera di drawdown")
    if not 0.0 < ff < 1.0:
        raise ValueError("frazione scommessa: deve stare in (0, 1)")
    if not 0.0 < br < 1.0:
        raise ValueError("barriera di drawdown: deve stare in (0, 1)")
    return math.log(br) / math.log(1.0 - ff)


def mh344_edge(p, b, f):
    """Edge atteso per trade e = f*(p*b - q), in frazione del capitale.

    p in (0, 1) esclusi, b > 0, f in [0, 1).
    """
    pp = mh344_num(p, "probabilita' di vincita")
    bb = mh344_num(b, "rapporto vincita/perdita")
    ff = mh344_num(f, "frazione scommessa")
    if not 0.0 < pp < 1.0:
        raise ValueError("probabilita' di vincita: deve stare in (0, 1)")
    if bb <= 0.0:
        raise ValueError("rapporto vincita/perdita: deve essere > 0")
    if not 0.0 <= ff < 1.0:
        raise ValueError("frazione scommessa: deve stare in [0, 1)")
    return ff * (pp * bb - (1.0 - pp))


def mh344_lundberg(p, b, f):
    """Coefficiente di Lundberg theta > 0 del processo moltiplicativo.

    Radice di p*(1+f*b)^(-theta) + q*(1-f)^(-theta) = 1, con q = 1-p
    (bisezione: g(0) = 0, g'(0) = -drift logaritmico < 0, g -> +inf).
    Se il drift logaritmico e' <= 0 non esiste radice positiva: ritorna 0.0
    (il chiamante mappa a R = 1). p in (0, 1) esclusi, b > 0, f in (0, 1).
    """
    import math
    pp = mh344_num(p, "probabilita' di vincita")
    bb = mh344_num(b, "rapporto vincita/perdita")
    ff = mh344_num(f, "frazione scommessa")
    if not 0.0 < pp < 1.0:
        raise ValueError("probabilita' di vincita: deve stare in (0, 1)")
    if bb <= 0.0:
        raise ValueError("rapporto vincita/perdita: deve essere > 0")
    if not 0.0 < ff < 1.0:
        raise ValueError("frazione scommessa: deve stare in (0, 1)")
    up = 1.0 + ff * bb
    down = 1.0 - ff
    drift = pp * math.log(up) + (1.0 - pp) * math.log(down)
    if drift <= 0.0:
        return 0.0

    def _g(th):
        return pp * up ** (-th) + (1.0 - pp) * down ** (-th) - 1.0

    lo, hi = 0.0, 1.0
    while _g(hi) <= 0.0:
        hi *= 2.0
        if hi > 1e12:
            raise ValueError("coefficiente di Lundberg: radice non trovata")
    for _ in range(200):
        mid = (lo + hi) / 2.0
        if _g(mid) <= 0.0:
            lo = mid
        else:
            hi = mid
    return (lo + hi) / 2.0


def mh344_ror(p, b, f, barriera):
    """Risk of ruin R = barriera^theta (Cramer-Lundberg, rovina "ultima").

    theta = coefficiente di Lundberg del processo moltiplicativo del
    capitale. theta <= 0 (drift nullo o negativo) -> 1.0: rovina certa nel
    lungo periodo. Ritorno sempre in [0, 1].
    """
    th = mh344_lundberg(p, b, f)
    br = mh344_num(barriera, "barriera di drawdown")
    if not 0.0 < br < 1.0:
        raise ValueError("barriera di drawdown: deve stare in (0, 1)")
    if th <= 0.0:
        return 1.0
    r = br ** th
    return min(1.0, max(0.0, r))


def mh344_ror_mc(p, b, f, barriera, n_paths=5000, max_trades=2000, seed=344):
    """Monte Carlo deterministico del risk of ruin.

    Simula n_paths percorsi di max_trades trade: vincita -> capitale*(1+f*b),
    perdita -> capitale*(1-f). Conta i percorsi che toccano la barriera.
    seed fisso -> risultato riproducibile. Ritorna la frazione in [0, 1].
    """
    import random
    pp = mh344_num(p, "probabilita' di vincita")
    bb = mh344_num(b, "rapporto vincita/perdita")
    ff = mh344_num(f, "frazione scommessa")
    br = mh344_num(barriera, "barriera di drawdown")
    if not 0.0 < pp < 1.0:
        raise ValueError("probabilita' di vincita: deve stare in (0, 1)")
    if bb <= 0.0:
        raise ValueError("rapporto vincita/perdita: deve essere > 0")
    if not 0.0 < ff < 1.0:
        raise ValueError("frazione scommessa: deve stare in (0, 1)")
    if not 0.0 < br < 1.0:
        raise ValueError("barriera di drawdown: deve stare in (0, 1)")
    nn = int(n_paths)
    mm = int(max_trades)
    if nn <= 0 or mm <= 0:
        raise ValueError("n_paths e max_trades devono essere > 0")
    rng = random.Random(int(seed))
    up = 1.0 + ff * bb
    down = 1.0 - ff
    hits = 0
    for _ in range(nn):
        cap = 1.0
        for _ in range(mm):
            if rng.random() < pp:
                cap *= up
            else:
                cap *= down
            if cap <= br:
                hits += 1
                break
    return hits / nn


def mh344_misure(p, win, loss, f, barriera):
    """Risk of ruin da edge stimato e sizing scelto.

    win, loss > 0 (stessa unita', conta solo il rapporto b = win/loss).
    f, barriera in (0, 1). Ritorna b, f_star, f_half, f usata, unita' u,
    edge per trade, R formula, R Monte Carlo e verdetto testuale.
    """
    ww = mh344_num(win, "vincita media")
    ll = mh344_num(loss, "perdita media")
    if ww <= 0.0:
        raise ValueError("vincita media: deve essere > 0")
    if ll <= 0.0:
        raise ValueError("perdita media: deve essere > 0")
    pp = mh344_num(p, "probabilita' di vincita")
    if not 0.0 < pp < 1.0:
        raise ValueError("probabilita' di vincita: deve stare in (0, 1)")
    ff = mh344_num(f, "frazione scommessa")
    br = mh344_num(barriera, "barriera di drawdown")
    b = ww / ll
    f_star = max(0.0, (pp * (b + 1.0) - 1.0) / b)
    th = mh344_lundberg(pp, b, ff)
    ror = mh344_ror(pp, b, ff, br)
    return {"p": pp, "win": ww, "loss": ll, "b": b, "f_star": f_star,
            "f_half": f_star / 2.0, "f": ff, "barriera": br,
            "u": mh344_units(ff, br), "edge": mh344_edge(pp, b, ff),
            "theta": th, "ror": ror,
            "ror_mc": mh344_ror_mc(pp, b, ff, br),
            "verdetto": mh344_verdetto(ror)}


def mh344_verdetto(ror):
    """Verdetto operativo sul risk of ruin a 3 stati.

    R < 1% SICURO; R < 10% ACCETTABILE; altrimenti PERICOLOSO: ridurre f.
    """
    rr = mh344_num(ror, "risk of ruin")
    if rr < 0.01:
        return (f"ROR SICURO (R = {rr:.2%}): la probabilita' di toccare la "
                f"barriera nel lungo periodo e' sotto l'1%: il sizing regge.")
    if rr < 0.10:
        return (f"ROR ACCETTABILE (R = {rr:.2%}): tra 1% e 10%: sizing "
                f"sostenibile ma da monitorare: tagliare la frazione se la "
                f"stima di p o b e' incerta.")
    return (f"ROR PERICOLOSO (R = {rr:.2%}): oltre il 10%: il sizing e' "
            f"troppo aggressivo per la barriera scelta: dimezzare la "
            f"frazione (quarter-Kelly) o alzare la tolleranza al drawdown.")
def mh343_num(x, nome):
    """Valida uno scalare numerico reale: no bool, no NaN/inf."""
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh343_kelly(p, b):
    """Frazione di Kelly f* = (p*(b+1) - 1) / b.

    p in (0, 1) esclusi, b > 0. f* <= 0 = nessun edge: non scommettere.
    """
    pp = mh343_num(p, "probabilita' di vincita")
    bb = mh343_num(b, "rapporto vincita/perdita")
    if not 0.0 < pp < 1.0:
        raise ValueError("probabilita' di vincita: deve stare in (0, 1)")
    if bb <= 0.0:
        raise ValueError("rapporto vincita/perdita: deve essere > 0")
    return (pp * (bb + 1.0) - 1.0) / bb


def mh343_growth(f, p, b):
    """Tasso di crescita geometrica g(f) = p*ln(1+f*b) + q*ln(1-f).

    None se f >= 1 (una perdita piena azzera il capitale). f deve essere
    >= 0; per f=0 vale 0.
    """
    import math
    ff = mh343_num(f, "frazione di capitale")
    pp = mh343_num(p, "probabilita' di vincita")
    bb = mh343_num(b, "rapporto vincita/perdita")
    if ff < 0.0:
        raise ValueError("frazione di capitale: deve essere >= 0")
    if not 0.0 < pp < 1.0:
        raise ValueError("probabilita' di vincita: deve stare in (0, 1)")
    if bb <= 0.0:
        raise ValueError("rapporto vincita/perdita: deve essere > 0")
    if ff >= 1.0:
        return None
    q = 1.0 - pp
    return pp * math.log(1.0 + ff * bb) + q * math.log(1.0 - ff)


def mh343_misure(p, win, loss):
    """Sizing di Kelly da edge stimato.

    win, loss > 0 (vincita/perdita media per operazione, stessa unita').
    Ritorna b, f* (full Kelly), f_half, f_quarter, EV per operazione e
    il verdetto testuale.
    """
    ww = mh343_num(win, "vincita media")
    ll = mh343_num(loss, "perdita media")
    if ww <= 0.0:
        raise ValueError("vincita media: deve essere > 0")
    if ll <= 0.0:
        raise ValueError("perdita media: deve essere > 0")
    pp = mh343_num(p, "probabilita' di vincita")
    if not 0.0 < pp < 1.0:
        raise ValueError("probabilita' di vincita: deve stare in (0, 1)")
    b = ww / ll
    f_star = mh343_kelly(pp, b)
    q = 1.0 - pp
    ev = pp * ww - q * ll
    return {"p": pp, "win": ww, "loss": ll, "b": b, "f_star": f_star,
            "f_half": f_star / 2.0, "f_quarter": f_star / 4.0, "ev": ev}


def mh343_verdetto(f_star, p, b, ev):
    """Verdetto operativo sul sizing a 3 stati.

    NESSUN EDGE (f* <= 0): l'aspettativa e' nulla o negativa.
    EDGE ECCESSIVO (f* > 1): l'edge richiederebbe leva: tagliare.
    EDGE POSITIVO: scommettere half-Kelly (f*/2), prudenza standard.
    """
    fs = mh343_num(f_star, "frazione di Kelly")
    pp = mh343_num(p, "probabilita' di vincita")
    bb = mh343_num(b, "rapporto vincita/perdita")
    ee = mh343_num(ev, "valore atteso")
    if fs <= 0.0:
        return (f"KELLY NESSUN EDGE (f* = {fs:.2%}): aspettativa "
                f"{ee:+.2f} per operazione con p = {pp:.0%} e b = {bb:.2f}: "
                f"non scommettere: nessuna frazione di capitale ha senso.")
    if fs > 1.0:
        return (f"KELLY EDGE ECCESSIVO (f* = {fs:.2%}): la frazione ottima "
                f"supera il 100% del capitale: servirebbe leva: tagliare "
                f"comunque la taglia (half-Kelly = {fs / 2:.2%}) e verificare "
                f"i vincoli di rischio del desk.")
    return (f"KELLY EDGE POSITIVO (f* = {fs:.2%}): aspettativa {ee:+.2f} per "
            f"operazione: taglia prudente half-Kelly = {fs / 2:.2%} del "
            f"capitale: massimizza la crescita geometrica g(f) lasciando "
            f"margine di errore sulla stima di p e b.")
def mh342_num(x, nome):
    """Valida uno scalare numerico reale: no bool, no NaN/inf."""
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh342_parse_serie(txt, nome):
    """Parsa una serie di rendimenti %: un valore per riga.

    La virgola e' il separatore decimale. Richiede almeno 12 valori.
    Ritorna np.array float (unita' %: 1.5 = 1.5%).
    """
    import math
    if not isinstance(txt, str):
        raise ValueError(f"{nome}: deve essere testo")
    vals = []
    for ln in txt.strip().splitlines():
        ln = ln.strip()
        if not ln:
            continue
        try:
            v = float(ln.replace(",", "."))
        except ValueError:
            raise ValueError(f"{nome}: '{ln}' non numerico")
        if math.isnan(v) or math.isinf(v):
            raise ValueError(f"{nome}: NaN/inf in '{ln}'")
        vals.append(v)
    if len(vals) < 12:
        raise ValueError(
            f"{nome}: servono almeno 12 periodi, trovati {len(vals)}")
    import numpy as np
    return np.asarray(vals, dtype=float)


def mh342_vol_ann(r, ppy):
    """Volatilita' annualizzata % da una serie di rendimenti % periodali.

    std campionaria (ddof=1) * sqrt(periodi per anno).
    """
    import numpy as np
    a = np.asarray(r, dtype=float).ravel()
    if a.size < 2:
        raise ValueError("vol_ann: servono almeno 2 periodi")
    p = mh342_num(ppy, "periodi per anno")
    if p < 1:
        raise ValueError("periodi per anno: deve essere >= 1")
    return float(a.std(ddof=1) * (p ** 0.5))


def mh342_misure(r, ppy, vol_target, lev_max):
    """Volatility targeting: moltiplicatore per stare nel budget di rischio.

    vol_real = volatilita' annualizzata realizzata (%),
    m_raw = vol_target / vol_real (None se vol_real ~ 0),
    m = min(m_raw, lev_max), capped = m_raw > lev_max.
    Ritorna anche equity 1x ed equity con leva m (base 100, None se m None).
    Richiede almeno 12 periodi, vol_target > 0, lev_max >= 1.
    """
    import numpy as np
    a = np.asarray(r, dtype=float).ravel()
    if a.size < 12:
        raise ValueError("misure: servono almeno 12 periodi")
    vt = mh342_num(vol_target, "volatilita' target")
    if vt <= 0:
        raise ValueError("volatilita' target: deve essere > 0")
    lm = mh342_num(lev_max, "leva massima")
    if lm < 1:
        raise ValueError("leva massima: deve essere >= 1")
    vol_real = mh342_vol_ann(a, ppy)
    eq_1x = np.empty(a.size + 1)
    eq_1x[0] = 100.0
    eq_1x[1:] = 100.0 * np.cumprod(1.0 + a / 100.0)
    if vol_real < 1e-9:
        m_raw, m_cap, capped, eq_lev = None, None, False, None
    else:
        m_raw = vt / vol_real
        m_cap = min(m_raw, lm)
        capped = m_raw > lm
        eq_lev = np.empty(a.size + 1)
        eq_lev[0] = 100.0
        eq_lev[1:] = 100.0 * np.cumprod(1.0 + m_cap * a / 100.0)
        eq_lev = eq_lev.tolist()
    return {"n": int(a.size), "ppy": int(ppy), "vol_real": vol_real,
            "vol_target": vt, "lev_max": lm, "m_raw": m_raw, "m": m_cap,
            "capped": capped, "eq_1x": eq_1x.tolist(), "eq_lev": eq_lev}


def mh342_verdetto(m_raw, m, capped, vol_real, vol_target):
    """Verdetto operativo sul sizing a 5 stati.

    IN LINEA (0.9 <= m_raw <= 1.1): nessuna ribilanciatura.
    AUMENTA / RIDUCI ESPOSIZIONE: scala per rientrare nel budget.
    LEVA AL MASSIMO: il vincolo di leva impedisce di raggiungere il target.
    NON MISURABILE: vol realizzata nulla o dati incompleti.
    """
    mr = (None if m_raw is None else mh342_num(m_raw, "moltiplicatore grezzo"))
    mm = (None if m is None else mh342_num(m, "moltiplicatore"))
    vr = (None if vol_real is None
          else mh342_num(vol_real, "volatilita' realizzata"))
    vt = (None if vol_target is None
          else mh342_num(vol_target, "volatilita' target"))
    if mr is None or mm is None or vr is None or vt is None:
        return ("SIZING NON MISURABILE: volatilita' realizzata nulla o dati "
                "incompleti: il rapporto vol target / vol realizzata non e' "
                "definito.")
    nota = (f" Vol realizzata {vr:.2f}% annua contro target {vt:.2f}%.")
    if capped:
        return (f"SIZING LEVA AL MASSIMO ({mm:.2f}x): il moltiplicatore "
                f"grezzo {mr:.2f}x supera la leva massima: il desk resta "
                f"sotto il vol target per vincolo di rischio.{nota}")
    if 0.9 <= mr <= 1.1:
        return (f"SIZING IN LINEA ({mr:.2f}x): l'esposizione e' gia' quella "
                f"del vol target: nessuna ribilanciatura.{nota}")
    if mr > 1.1:
        return (f"AUMENTA ESPOSIZIONE ({mr:.2f}x): la strategia e' meno "
                f"volatile del target: si puo' scalare su restando nel budget "
                f"di rischio.{nota}")
    return (f"RIDUCI ESPOSIZIONE ({mr:.2f}x): la strategia e' piu' volatile "
            f"del target: tagliare l'esposizione per rientrare nel budget di "
            f"rischio.{nota}")
