def mh341_equity(r):
    """Equity curve da una serie di rendimenti % (base 100)."""
    import numpy as np
    a = np.asarray(r, dtype=float).ravel()
    eq = np.empty(a.size + 1)
    eq[0] = 100.0
    eq[1:] = 100.0 * np.cumprod(1.0 + a / 100.0)
    return eq


def mh341_misure(r):
    """K-ratio di Zephyr e misure collegate alla regolarita'.

    Regressione OLS dell'equity (base 100) sul tempo t = 0..n:
    slope = pendenza (punti equity per periodo),
    se = errore standard dei residui (il 'rumore' attorno al trend),
    k = slope * sqrt(n_punti) / se (n_punti = n + 1);
    k = None se se ~ 0 (equity perfettamente lineare: regolarita' ideale).
    Ritorna anche eq e trend (valori fittati) per il grafico.
    Richiede almeno 12 periodi.
    """
    import numpy as np
    a = np.asarray(r, dtype=float).ravel()
    if a.size < 12:
        raise ValueError("misure: servono almeno 12 periodi")
    eq = mh341_equity(a)
    npt = eq.size
    t = np.arange(npt, dtype=float)
    X = np.column_stack([np.ones(npt), t])
    beta, _res, _rnk, _sv = np.linalg.lstsq(X, eq, rcond=None)
    trend = X @ beta
    slope = float(beta[1])
    sse = float(((eq - trend) ** 2).sum())
    se = float((sse / (npt - 2)) ** 0.5)
    k = None if se < 1e-9 else slope * (npt ** 0.5) / se
    return {"n": int(a.size), "n_punti": int(npt), "slope": slope,
            "se": se, "k": k, "eq": eq.tolist(),
            "trend": trend.tolist()}


def mh341_verdetto(k, slope, se, n):
    """Verdetto a 4 stati sul K-ratio.

    La nota dice quanto cresce l'equity per periodo (pendenza) e quanto
    rumore c'e' attorno al trend (SE): e' la costanza che il sizing puo'
    sopportare. SE ~ 0 (k None) = regolarita' perfetta.
    """
    kk = (None if k is None else mh341_num(k, "K-ratio"))
    sl = (None if slope is None else mh341_num(slope, "pendenza"))
    s = (None if se is None else mh341_num(se, "errore standard"))
    if kk is None or sl is None or s is None or n is None:
        nn = (None if n is None else mh341_num(n, "periodi totali"))
        if kk is None and sl is not None and s is not None and nn is not None:
            return (f"K-ratio ECCELLENTE (regolarita' perfetta): l'equity "
                    f"cresce di {sl:+.2f} punti per periodo su una retta, "
                    f"senza scarti dal trend ({int(nn)} periodi). Sizing "
                    f"massimo: il compounding non ha sorprese.")
        return ("K-ratio NON MISURABILE: servono K-ratio, pendenza, errore "
                "standard e conteggio periodi (almeno 12 periodi).")
    nn = mh341_num(n, "periodi totali")
    nota = (f" L'equity cresce di {sl:+.2f} punti per periodo con un rumore "
            f"di {s:.2f} punti attorno al trend ({int(nn)} periodi).")
    if kk >= 1.5:
        return (f"K-ratio ECCELLENTE ({kk:.2f}): compounding molto regolare, "
                f"il percorso e' quasi una retta.{nota}")
    if kk >= 0.75:
        return (f"K-ratio BUONO ({kk:.2f}): crescita costante con scarti "
                f"contenuti dal trend: sizing sereno.{nota}")
    if kk >= 0.0:
        return (f"K-ratio MODERATO ({kk:.2f}): crescita a singhiozzo, il "
                f"rendimento arriva a scatti: sizing contenuto.{nota}")
    return (f"K-ratio DEBOLE ({kk:.2f}): l'equity tende a scendere o oscilla "
            f"troppo attorno al trend: non e' un percorso finanziabile "
            f"cosi' com'e'.{nota}")
