def mh338_misure(rs, rb, periodi_annuo=12, rf=0.0):
    """M² di Modigliani-Modigliani e misure collegate vs benchmark.

    exp_ann = media(rs)*p (rendimento strategia annuo, pp),
    rf_ann = rf*p, bm_ann = media(rb)*p (rendimento benchmark annuo, pp),
    sd_s/sd_b = std per-periodo (ddof=1),
    scala = sd_b/sd_s (leva implicita: <1 la strategia e' piu' rischiosa
    del benchmark e nel M² viene de-levata, >1 viceversa),
    m2 = rf_ann + scala*(exp_ann - rf_ann) (rendimento strategia riscalato
    al rischio del benchmark, pp/anno),
    delta = m2 - bm_ann (valore aggiunto a parita' di rischio, pp/anno),
    vol_s_ann/vol_b_ann = volatilita' annualizzate (sd*sqrt(p), pp).
    Richiede almeno 12 periodi per serie, stessa numerosita', sd_s > 0 e
    sd_b > 0 (benchmark non piatto: senza volatilita' di riferimento la
    ri-scalatura non ha senso).
    """
    import numpy as np
    p = mh338_num(periodi_annuo, "periodi_annuo")
    if p <= 0:
        raise ValueError("periodi_annuo: deve essere > 0")
    r = mh338_num(rf, "risk-free")
    a = np.asarray(rs, dtype=float).ravel()
    b = np.asarray(rb, dtype=float).ravel()
    if a.size < 12 or b.size < 12:
        raise ValueError("misure: servono almeno 12 periodi per serie")
    if a.size != b.size:
        raise ValueError("misure: le due serie devono avere la stessa "
                         f"numerosita' ({a.size} vs {b.size})")
    sd_s = float(np.std(a, ddof=1))
    sd_b = float(np.std(b, ddof=1))
    if sd_s <= 1e-12:
        raise ValueError("misure: strategia quasi piatta "
                         "(volatilita' ~ 0): M² non calcolabile")
    if sd_b <= 1e-12:
        raise ValueError("misure: benchmark quasi piatto "
                         "(volatilita' ~ 0): nessuna volatilita' di "
                         "riferimento per la ri-scalatura")
    exp_ann = float(a.mean() * p)
    bm_ann = float(b.mean() * p)
    rf_ann = float(r * p)
    scala = sd_b / sd_s
    m2 = rf_ann + scala * (exp_ann - rf_ann)
    delta = m2 - bm_ann
    return {"n": int(a.size), "exp_ann": exp_ann, "bm_ann": bm_ann,
            "rf_ann": rf_ann, "sd_s": sd_s, "sd_b": sd_b, "scala": scala,
            "m2": m2, "delta": delta,
            "vol_s_ann": float(sd_s * (p ** 0.5)),
            "vol_b_ann": float(sd_b * (p ** 0.5))}


def mh338_verdetto(delta, scala, m2, bm_ann):
    """Verdetto a 4 stati sul delta a parita' di rischio (pp/anno).

    Le note dicono se la strategia e' piu' o meno rischiosa del benchmark
    (leva implicita scala: <0.9 de-levata nel M², >1.1 levata, altrimenti
    rischio simile).
    """
    d = (None if delta is None else mh338_num(delta, "delta"))
    s = (None if scala is None else mh338_num(scala, "scala"))
    q = (None if m2 is None else mh338_num(m2, "M²"))
    ba = (None if bm_ann is None else mh338_num(bm_ann, "benchmark annuo"))
    if d is None or s is None or q is None or ba is None:
        return ("M² Modigliani NON MISURABILE: servono delta a parita' di "
                "rischio, scala, M² e rendimento benchmark (almeno 12 "
                "periodi, benchmark non piatto).")
    if s < 0.9:
        nota_s = (f" La strategia e' piu' rischiosa del benchmark (scala "
                  f"{s:.2f} < 1): nel M² viene de-levata, il rendimento "
                  "grezzo va letto con cautela.")
    elif s > 1.1:
        nota_s = (f" La strategia e' meno rischiosa del benchmark (scala "
                  f"{s:.2f} > 1): nel M² viene levata per reggere il "
                  "confronto a parita' di rischio.")
    else:
        nota_s = (f" Rischio simile al benchmark (scala {s:.2f}): la "
                  "ri-scalatura cambia poco il rendimento grezzo.")
    if d >= 3.0:
        return (f"M² Modigliani ECCELLENTE (Δ {d:+.2f} pp/anno): a parita' "
                "di rischio col benchmark la strategia rende molto di "
                f"piu' (M² {q:.2f} pp/anno vs benchmark {ba:.2f}). "
                f"Valore aggiunto reale, non solo leva sul rischio.{nota_s}")
    if d >= 1.0:
        return (f"M² Modigliani BUONO (Δ {d:+.2f} pp/anno): a parita' di "
                "rischio col benchmark la strategia rende di piu' "
                f"(M² {q:.2f} pp/anno vs benchmark {ba:.2f}). "
                f"C'e' valore aggiunto oltre il rischio corso.{nota_s}")
    if d >= 0.0:
        return (f"M² Modigliani MODERATO (Δ {d:+.2f} pp/anno): a parita' di "
                "rischio la strategia e' in linea col benchmark "
                f"(M² {q:.2f} pp/anno vs {ba:.2f}). Il maggior rendimento "
                f"grezzo, se c'e', si spiega col maggior rischio.{nota_s}")
    return (f"M² Modigliani DEBOLE (Δ {d:+.2f} pp/anno): a parita' di "
            "rischio col benchmark la strategia rende meno "
            f"(M² {q:.2f} pp/anno vs benchmark {ba:.2f}). Il rischio corso "
            f"non e' ripagato: rivedere sizing o timing.{nota_s}")
def mh337_num(x, nome):
    """Valida uno scalare numerico reale: no bool, no NaN/inf."""
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh337_parse_serie(txt, nome):
    """Parsa una serie di rendimenti %: un valore per riga.

    La virgola e' il separatore decimale. Richiede almeno 12 valori.
    Ritorna np.array float (unita' %: 1.5 = 1.5%).
    """
    import math
    if not isinstance(txt, str):
        raise ValueError(f"{nome}: deve essere testo")
    vals = []
    for ln in txt.strip().splitlines():
        ln = ln.strip()
        if not ln:
            continue
        try:
            v = float(ln.replace(",", "."))
        except ValueError:
            raise ValueError(f"{nome}: '{ln}' non numerico")
        if math.isnan(v) or math.isinf(v):
            raise ValueError(f"{nome}: NaN/inf in '{ln}'")
        vals.append(v)
    if len(vals) < 12:
        raise ValueError(
            f"{nome}: servono almeno 12 periodi, trovati {len(vals)}")
    import numpy as np
    return np.asarray(vals, dtype=float)


def mh337_regressione(rs, rb):
    """Regressione OLS dei rendimenti strategia sui rendimenti benchmark.

    Ritorna dict {n, beta, alpha, r2, corr, var_bm, cov}: beta = cov/var_bm,
    alpha = media(rs) - beta*media(rb) (alpha di Jensen per periodo, in pp),
    r2 = corr^2 (quota di varianza della strategia spiegata dal benchmark).
    Richiede almeno 12 periodi per serie, stessa numerosita', var_bm > 0
    (benchmark non piatto).
    """
    import numpy as np
    rs = np.asarray(rs, dtype=float).ravel()
    rb = np.asarray(rb, dtype=float).ravel()
    if rs.size < 12 or rb.size < 12:
        raise ValueError("regressione: servono almeno 12 periodi per serie")
    if rs.size != rb.size:
        raise ValueError("regressione: le due serie devono avere la stessa "
                         f"numerosita' ({rs.size} vs {rb.size})")
    var_bm = float(np.var(rb, ddof=1))
    if var_bm <= 1e-12:
        raise ValueError("regressione: benchmark quasi piatto "
                         "(varianza ~ 0): beta non stimabile")
    cov = float(np.cov(rs, rb, ddof=1)[0, 1])
    beta = cov / var_bm
    alpha = float(rs.mean() - beta * rb.mean())
    sd_s = float(np.std(rs, ddof=1))
    sd_b = float(np.std(rb, ddof=1))
    corr = cov / (sd_s * sd_b) if sd_s > 0 and sd_b > 0 else 0.0
    return {"n": int(rs.size), "beta": beta, "alpha": alpha,
            "r2": float(corr ** 2), "corr": float(corr),
            "var_bm": var_bm, "cov": cov}


def mh337_misure(rs, rb, periodi_annuo=12, rf=0.0):
    """Treynor, Jensen's alpha e misure collegate vs benchmark.

    Gli excess sono rendimenti - risk-free; la regressione gira sugli
    excess (con rf costante, beta e' lo stesso della regressione sui
    rendimenti grezzi). exp_ann = media(excess_s) * periodi_annuo,
    jensen_ann = alpha * periodi_annuo, treynor = exp_ann / beta
    (None se beta <= 0: il ratio non ha senso), te_ann = tracking error
    annualizzato (std degli attivi * sqrt(p)), appraisal = jensen_ann /
    te_ann (excess non spiegato dal beta per unita' di rischio attivo).
    """
    import numpy as np
    p = mh337_num(periodi_annuo, "periodi_annuo")
    if p <= 0:
        raise ValueError("periodi_annuo: deve essere > 0")
    r = mh337_num(rf, "risk-free")
    es = np.asarray(rs, dtype=float).ravel() - r
    eb = np.asarray(rb, dtype=float).ravel() - r
    reg = mh337_regressione(es, eb)
    exp_ann = float(es.mean() * p)
    jensen_ann = float(reg["alpha"] * p)
    treynor = exp_ann / reg["beta"] if reg["beta"] > 0 else None
    te_ann = float(np.std(es - eb, ddof=1) * (p ** 0.5))
    appraisal = jensen_ann / te_ann if te_ann > 1e-12 else None
    return {"n": reg["n"], "beta": reg["beta"], "alpha": reg["alpha"],
            "r2": reg["r2"], "corr": reg["corr"], "exp_ann": exp_ann,
            "jensen_ann": jensen_ann, "treynor": treynor,
            "te_ann": te_ann, "appraisal": appraisal}


def mh337_verdetto(treynor, jensen_ann, beta, r2):
    """Verdetto a 4 stati sul Treynor ratio annualizzato (pp).

    Se beta <= 0 il Treynor non e' interpretabile (il denominatore non
    misura rischio sistematico). Le note dicono se l'alpha di Jensen e'
    positiva (valore aggiunto oltre il beta), quanto la regressione e'
    affidabile (R2) e se il profilo e' difensivo (beta < 0.7), in linea
    col benchmark o aggressivo (beta > 1.3).
    """
    t = (None if treynor is None else mh337_num(treynor, "treynor"))
    j = (None if jensen_ann is None
         else mh337_num(jensen_ann, "alpha di Jensen"))
    b = None if beta is None else mh337_num(beta, "beta")
    q = None if r2 is None else mh337_num(r2, "R2")
    if b is not None and b <= 0:
        return ("Treynor & Jensen NON MISURABILE: beta non positivo "
                f"({b:.2f}): la strategia non segue il benchmark (o si muove "
                "in controfase) e il Treynor ratio perde significato. "
                "Valutare la strategia con metriche assolute (Sharpe) o "
                "controllare i dati.")
    if t is None or j is None or b is None or q is None:
        return ("Treynor & Jensen NON MISURABILE: servono Treynor, alpha di "
                "Jensen, beta e R2 (almeno 12 periodi e benchmark non "
                "piatto).")
    if j > 0:
        nota_j = (f" L'alpha di Jensen e' positiva ({j:+.2f} pp/anno): la "
                  "strategia crea valore oltre quanto spiegato dal beta.")
    else:
        nota_j = (f" L'alpha di Jensen ({j:+.2f} pp/anno) non e' positiva: "
                  "il rendimento si spiega tutto con l'esposizione al "
                  "benchmark, nessun valore aggiunto oltre il beta.")
    if q >= 0.9:
        nota_q = (f" La regressione e' molto affidabile (R2 = {q:.3f}): "
                  "beta e alpha sono stimati con precisione.")
    elif q >= 0.5:
        nota_q = (f" La regressione e' accettabile (R2 = {q:.3f}): beta e "
                  "alpha sono indicativi, verificare con piu' dati.")
    else:
        nota_q = (f" Attenzione: regressione poco affidabile (R2 = {q:.3f}): "
                  "la strategia segue poco il benchmark, beta e alpha sono "
                  "rumorosi.")
    if b > 1.3:
        nota_b = (f" Profilo aggressivo (beta = {b:.2f} > 1.3): la strategia "
                  "amplifica i movimenti del benchmark.")
    elif b < 0.7:
        nota_b = (f" Profilo difensivo (beta = {b:.2f} < 0.7): la strategia "
                  "si muove meno del benchmark.")
    else:
        nota_b = (f" Profilo in linea col benchmark (beta = {b:.2f}).")
    if t >= 8.0:
        return (f"Treynor & Jensen ECCELLENTE (Treynor {t:+.2f} pp/anno): il "
                "premio per unita' di rischio sistematico e' molto alto. La "
                f"strategia e' pagata bene per il rischio di mercato che si "
                f"assume.{nota_j}{nota_q}{nota_b}")
    if t >= 3.0:
        return (f"Treynor & Jensen BUONO (Treynor {t:+.2f} pp/anno): il "
                "premio per unita' di rischio sistematico e' solido. "
                f"Strategia efficiente rispetto al mercato.{nota_j}{nota_q}"
                f"{nota_b}")
    if t > 0:
        return (f"Treynor & Jensen MODERATO (Treynor {t:+.2f} pp/anno): il "
                "premio per unita' di rischio sistematico e' positivo ma "
                "sottile. Verificare se il rischio di mercato corso vale il "
                f"premio.{nota_j}{nota_q}{nota_b}")
    return (f"Treynor & Jensen DEBOLE (Treynor {t:+.2f} pp/anno): il premio "
            "per unita' di rischio sistematico non e' positivo. La strategia "
            "non ripaga il rischio di mercato che si assume: rivedere "
            f"sizing, timing o coerenza col mandato.{nota_j}{nota_q}{nota_b}")

def mh336_num(x, nome):
    """Valida uno scalare numerico reale: no bool, no NaN/inf."""
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh336_parse_serie(txt, nome):
    """Parsa una serie di rendimenti %: un valore per riga.

    La virgola e' il separatore decimale. Richiede almeno 12 valori.
    Ritorna np.array float (unita' %: 1.5 = 1.5%).
    """
    import math
    if not isinstance(txt, str):
        raise ValueError(f"{nome}: deve essere testo")
    vals = []
    for ln in txt.strip().splitlines():
        ln = ln.strip()
        if not ln:
            continue
        try:
            v = float(ln.replace(",", "."))
        except ValueError:
            raise ValueError(f"{nome}: '{ln}' non numerico")
        if math.isnan(v) or math.isinf(v):
            raise ValueError(f"{nome}: NaN/inf in '{ln}'")
        vals.append(v)
    if len(vals) < 12:
        raise ValueError(
            f"{nome}: servono almeno 12 periodi, trovati {len(vals)}")
    import numpy as np
    return np.asarray(vals, dtype=float)


def mh336_statistiche(rs, rb, periodi_annuo=12):
    """Max drawdown relativo della strategia vs benchmark.

    Rendimento attivo = strategia - benchmark (punti %). Il cumulato attivo
    e' la somma dei rendimenti attivi (convenzione additiva); il drawdown
    relativo di ogni periodo e' picco_cumulato - cumulato. Ritorna dict
    {n, max_dd, dd_corrente, durata_max, pct_sottacqua, picco_max,
    valle_min, exp_active_ann}: max_dd e' il peggior scivolone in pp,
    dd_corrente il drawdown dell'ultimo periodo, durata_max la piu' lunga
    sequenza consecutiva di periodi sott'acqua, pct_sottacqua la quota %
    di periodi con drawdown > 0, exp_active_ann = media(attivo) *
    periodi_annuo.
    """
    import numpy as np
    p = mh336_num(periodi_annuo, "periodi_annuo")
    if p <= 0:
        raise ValueError("periodi_annuo: deve essere > 0")
    rs = np.asarray(rs, dtype=float).ravel()
    rb = np.asarray(rb, dtype=float).ravel()
    if rs.size < 12 or rb.size < 12:
        raise ValueError("statistiche: servono almeno 12 periodi per serie")
    if rs.size != rb.size:
        raise ValueError("statistiche: le due serie devono avere la stessa "
                         f"numerosita' ({rs.size} vs {rb.size})")
    act = rs - rb
    cum = np.cumsum(act)
    peak = np.maximum.accumulate(cum)
    dd = peak - cum
    durata_max = 0
    cur = 0
    for u in dd > 0:
        if u:
            cur += 1
            if cur > durata_max:
                durata_max = cur
        else:
            cur = 0
    return {
        "n": int(rs.size),
        "max_dd": float(dd.max()),
        "dd_corrente": float(dd[-1]),
        "durata_max": int(durata_max),
        "pct_sottacqua": float((dd > 0).mean() * 100.0),
        "picco_max": float(cum.max()),
        "valle_min": float(cum.min()),
        "exp_active_ann": float(act.mean() * p),
    }


def mh336_verdetto(max_dd, dd_corrente, exp_active_ann):
    """Verdetto a 4 stati sul max drawdown relativo % (pp).

    La nota di recupero dice se la strategia ha gia' recuperato lo
    scivolone oppure e' ancora sott'acqua; la nota finale dice se
    l'excess return annualizzato ripaga il rischio attivo corso.
    """
    t = (None if max_dd is None else mh336_num(max_dd, "max drawdown %"))
    c = (None if dd_corrente is None
         else mh336_num(dd_corrente, "drawdown corrente"))
    e = (None if exp_active_ann is None
         else mh336_num(exp_active_ann, "excess return annuo"))
    if t is None or c is None or e is None:
        return ("max drawdown relativo NON MISURABILE: servono almeno 12 "
                "periodi per misurare il peggior scivolone rispetto al "
                "benchmark.")
    if c > 0.01:
        nota_rec = (f" Attenzione: la strategia e' ancora in drawdown "
                    f"relativo ({c:.2f} pp sotto il picco attivo): non ha "
                    "ancora recuperato lo scivolone.")
    else:
        nota_rec = (" Il drawdown e' stato interamente recuperato: il "
                    "rendimento attivo cumulato e' ai massimi.")
    if e > 0:
        nota_exc = (f" L'excess return annualizzato e' positivo ({e:+.2f} "
                    "pp): nel complesso il rischio attivo corso e' stato "
                    "ripagato.")
    else:
        nota_exc = (f" L'excess return annualizzato ({e:+.2f} pp) non e' "
                    "positivo: oltre allo scivolone, la strategia non ha "
                    "battuto il benchmark nel periodo.")
    if t < 5.0:
        return (f"max drawdown relativo LIEVE ({t:.2f} pp): il peggior "
                "scivolone rispetto al benchmark resta contenuto. La "
                "strategia non si e' mai allontanata troppo dal suo picco "
                f"attivo.{nota_rec}{nota_exc}")
    if t < 10.0:
        return (f"max drawdown relativo MODERATO ({t:.2f} pp): la strategia "
                "ha vissuto fasi di sottoperformance marcate rispetto al "
                "benchmark, ma entro limiti gestibili. Monitorare che non "
                f"si allunghino.{nota_rec}{nota_exc}")
    if t < 20.0:
        return (f"max drawdown relativo ELEVATO ({t:.2f} pp): la strategia "
                "ha attraversato uno scivolone profondo rispetto al "
                "benchmark. Accettabile solo se l'excess return di lungo "
                "periodo lo ripaga e il mandato tollera oscillazioni "
                f"ampie.{nota_rec}{nota_exc}")
    return (f"max drawdown relativo SEVERO ({t:.2f} pp): il peggior "
            "scivolone rispetto al benchmark e' molto profondo. Profilo ad "
            "alto rischio attivo: rivedere sizing, stop o coerenza col "
            f"mandato.{nota_rec}{nota_exc}")

