def mh335_statistiche(rs, rb, periodi_annuo=12):
    """Tracking error della strategia vs benchmark.

    Rendimento attivo = strategia - benchmark (punti %). Ritorna dict
    {n, exp_active, te, te_ann, exp_active_ann, ir, max_act, min_act,
    pct_fuori}: exp_active/te in punti % per periodo, te_ann annualizzato
    con sqrt(periodi_annuo), exp_active_ann = exp_active * periodi_annuo,
    ir = exp_active/te (None se te == 0), pct_fuori = quota % di periodi
    con |attivo| > te.
    """
    import numpy as np
    p = mh335_num(periodi_annuo, "periodi_annuo")
    if p <= 0:
        raise ValueError("periodi_annuo: deve essere > 0")
    rs = np.asarray(rs, dtype=float).ravel()
    rb = np.asarray(rb, dtype=float).ravel()
    if rs.size < 12 or rb.size < 12:
        raise ValueError("statistiche: servono almeno 12 periodi per serie")
    if rs.size != rb.size:
        raise ValueError("statistiche: le due serie devono avere la stessa "
                         f"numerosita' ({rs.size} vs {rb.size})")
    act = rs - rb
    exp_active = float(act.mean())
    te = float(act.std(ddof=1)) if act.size > 1 else 0.0
    return {
        "n": int(rs.size),
        "exp_active": exp_active,
        "te": te,
        "te_ann": te * (p ** 0.5),
        "exp_active_ann": exp_active * p,
        "ir": (exp_active / te if te > 0 else None),
        "max_act": float(act.max()),
        "min_act": float(act.min()),
        "pct_fuori": float((np.abs(act) > te).mean() * 100.0),
    }


def mh335_verdetto(te_ann, exp_active_ann):
    """Verdetto a 4 stati sul tracking error annualizzato %.

    La nota finale dice se l'excess return annualizzato compensa il rischio
    attivo oppure no.
    """
    t = None if te_ann is None else mh335_num(te_ann, "tracking error %")
    e = (None if exp_active_ann is None
         else mh335_num(exp_active_ann, "excess return annuo"))
    if t is None or e is None:
        return ("tracking error NON MISURABILE: servono almeno 12 periodi "
                "per stimare la volatilita' del rendimento attivo.")
    if e > 0:
        nota = (f" L'excess return annualizzato e' positivo ({e:+.2f} pp): "
                "il rischio attivo paga, la strategia viene ripagata per "
                "discostarsi dal benchmark.")
    else:
        nota = (f" L'excess return annualizzato ({e:+.2f} pp) non e' "
                "positivo: la strategia si discosta dal benchmark senza "
                "esserne ripagata.")
    if t < 2.0:
        return (f"tracking error PASSIVA (TE {t:.2f}%): la strategia replica "
                "quasi il benchmark, deviazioni minime. Rischio attivo "
                f"trascurabile.{nota}")
    if t < 6.0:
        return (f"tracking error CONTROLLATA (TE {t:.2f}%): la strategia si "
                "discosta dal benchmark in misura moderata, tipica di una "
                f"gestione attiva disciplinata.{nota}")
    if t < 12.0:
        return (f"tracking error ATTIVA (TE {t:.2f}%): la strategia prende "
                "posizioni marcate rispetto al benchmark. Deviazioni ampie: "
                "va bene solo se l'excess return le giustifica nel tempo."
                f"{nota}")
    return (f"tracking error MOLTO ATTIVA (TE {t:.2f}%): la strategia vive "
            "lontano dal benchmark, con oscillazioni del rendimento attivo "
            "molto ampie. Profilo ad alto rischio attivo: monitorare "
            f"drawdown e coerenza col mandato.{nota}")

