def mh331_parse_equity(txt):
    """Parsa i livelli cumulati dell'equity: un valore per riga.

    La virgola e' il separatore decimale. Richiede almeno 30 valori,
    tutti strettamente positivi. Ritorna np.array float.
    """
    import math
    if not isinstance(txt, str):
        raise ValueError("equity: deve essere testo")
    vals = []
    for ln in txt.strip().splitlines():
        ln = ln.strip()
        if not ln:
            continue
        try:
            v = float(ln.replace(",", "."))
        except ValueError:
            raise ValueError(f"equity: '{ln}' non numerico")
        if math.isnan(v) or math.isinf(v):
            raise ValueError(f"equity: NaN/inf in '{ln}'")
        if v <= 0.0:
            raise ValueError(f"equity: i livelli devono essere > 0 "
                             f"(trovato '{ln}')")
        vals.append(v)
    if len(vals) < 30:
        raise ValueError(
            f"equity: servono almeno 30 periodi, trovati {len(vals)}")
    import numpy as np
    return np.asarray(vals, dtype=float)


def mh331_episodi(eq):
    """Scompone la serie in episodi di drawdown.

    Ogni episodio e' un dict {picco, profondita_max, durata, recuperato,
    periodi_sottacqua}: picco = periodo 1-based del massimo da cui parte il
    drawdown; profondita_max = drawdown massimo (frazione); durata = periodi
    dal picco al recupero (None se l'episodio e' ancora aperto a fine serie);
    periodi_sottacqua = periodi con drawdown > 0 dell'episodio.
    """
    import numpy as np
    eq = np.asarray(eq, dtype=float)
    if len(eq) < 30:
        raise ValueError("episodi: servono almeno 30 periodi")
    n = len(eq)
    peak = np.maximum.accumulate(eq)
    dd = (peak - eq) / peak
    episodi = []
    i = 0
    while i < n:
        if dd[i] > 0.0:
            a = i
            while i < n and dd[i] > 0.0:
                i += 1
            b = i - 1
            recuperato = (b + 1) < n
            episodi.append({
                "picco": a,  # periodo 1-based del picco (indice a-1 -> periodo a)
                "profondita_max": float(np.max(dd[a:b + 1])),
                "durata": (b - a + 2) if recuperato else None,
                "recuperato": recuperato,
                "periodi_sottacqua": b - a + 1,
            })
        else:
            i += 1
    return episodi


def mh331_statistiche(eq, periodi_anno):
    """Statistiche sui tempi di recupero.

    Ritorna dict {n, n_recuperati, durata_media, durata_max, pct_sottacqua,
    max_dd, mesi_medi, mesi_max, in_corso, sottacqua_da}: durata_media/max e
    mesi_medi/max sono None se nessun episodio si e' chiuso; pct_sottacqua in
    %; in_corso True se l'ultimo episodio e' ancora aperto.
    """
    p = mh331_num(periodi_anno, "periodi/anno")
    if p <= 0.0:
        raise ValueError("periodi/anno: deve essere > 0")
    eq = list(eq)
    if len(eq) < 30:
        raise ValueError("statistiche: servono almeno 30 periodi")
    eps = mh331_episodi(eq)
    n = len(eq)
    chiusi = [e["durata"] for e in eps if e["recuperato"]]
    sub_tot = sum(e["periodi_sottacqua"] for e in eps)
    in_corso = bool(eps) and not eps[-1]["recuperato"]
    durata_media = (sum(chiusi) / len(chiusi)) if chiusi else None
    durata_max = max(chiusi) if chiusi else None
    return {
        "n": len(eps),
        "n_recuperati": len(chiusi),
        "durata_media": durata_media,
        "durata_max": durata_max,
        "pct_sottacqua": 100.0 * sub_tot / n,
        "max_dd": max((e["profondita_max"] for e in eps),
                      default=0.0),
        "mesi_medi": (durata_media * 12.0 / p) if durata_media else None,
        "mesi_max": (durata_max * 12.0 / p) if durata_max else None,
        "in_corso": in_corso,
        "sottacqua_da": (eps[-1]["periodi_sottacqua"]
                         if in_corso else None),
    }


def mh331_verdetto(mesi_medi, pct_sottacqua, in_corso, sottacqua_da=None):
    """Verdetto a 3 stati sul tempo medio di recupero (mesi_medi puo' essere None)."""
    pct = mh331_num(pct_sottacqua, "tempo sott'acqua %")
    if mesi_medi is not None:
        mesi_medi = mh331_num(mesi_medi, "mesi medi")
    if not isinstance(in_corso, bool):
        raise ValueError("in_corso: deve essere True/False")
    nota = ""
    if in_corso:
        da = mh331_num(sottacqua_da, "sottacqua da") if sottacqua_da else None
        nota = (f" Attenzione: un episodio e' ancora aperto "
                f"(sott'acqua da {int(da)} periodi): il recupero non e' "
                f"completato.") if da else \
               (" Attenzione: un episodio e' ancora aperto: il recupero "
                "non e' completato.")
    if mesi_medi is None:
        if in_corso:
            return ("tempo di recupero NON MISURABILE: nessun episodio si e' "
                    "ancora chiuso, l'equity non ha mai recuperato il picco: "
                    "segnale di allerta massimo, rivedere strategia e sizing." +
                    nota)
        return ("nessun episodio di drawdown: l'equity non e' mai scesa dal "
                "picco, niente da recuperare: profilo ideale.")
    if mesi_medi <= 3.0:
        base = (f"tempo di recupero ECCELLENTE: in media l'equity torna al "
                f"picco in {mesi_medi:.1f} mesi (sott'acqua solo il "
                f"{pct:.1f}% del tempo): i drawdown si chiudono in fretta, "
                f"capitale raramente bloccato sotto il massimo.")
    elif mesi_medi <= 9.0:
        base = (f"tempo di recupero MODERATO: in media l'equity torna al "
                f"picco in {mesi_medi:.1f} mesi (sott'acqua il {pct:.1f}% "
                f"del tempo): i drawdown si chiudono ma il capitale resta "
                f"bloccato per trimestri, pianificare liquidita' e margin.")
    else:
        base = (f"tempo di recupero DEBOLE: in media l'equity torna al picco "
                f"in {mesi_medi:.1f} mesi (sott'acqua il {pct:.1f}% del "
                f"tempo): il capitale resta bloccato sotto il massimo per "
                f"troppo tempo, costo opportunita' e rischio margin call "
                f"elevati: ridimensionare o fermare.")
    return base + nota

