def mh330_drawdown(eq):
    """Serie dei drawdown (frazione >= 0) rispetto al running max."""
    import numpy as np
    eq = np.asarray(eq, dtype=float)
    if len(eq) < 30:
        raise ValueError("drawdown: servono almeno 30 periodi")
    peak = np.maximum.accumulate(eq)
    return (peak - eq) / peak


def mh330_ulcer(eq):
    """Ulcer Index (frazione): media quadratica dei drawdown dell'intera serie.

    0.0 se la serie non scende mai dal picco.
    """
    import numpy as np
    dd = mh330_drawdown(eq)
    return float(np.sqrt(np.mean(dd ** 2)))


def mh330_cagr(eq, periodi_anno):
    """Tasso di crescita annuo composto (frazione, es. 0.13 = 13%)."""
    p = mh330_num(periodi_anno, "periodi/anno")
    if p <= 0.0:
        raise ValueError("periodi/anno: deve essere > 0")
    eq = list(eq)
    if len(eq) < 30:
        raise ValueError("cagr: servono almeno 30 periodi")
    return (eq[-1] / eq[0]) ** (p / (len(eq) - 1)) - 1.0


def mh330_martin(eq, periodi_anno):
    """Martin ratio = CAGR / Ulcer Index.

    cagr e ulcer come frazioni. martin = inf se ulcer == 0 (serie senza
    drawdown). Ritorna dict {n, cagr, ulcer, max_dd, martin}.
    """
    p = mh330_num(periodi_anno, "periodi/anno")
    if p <= 0.0:
        raise ValueError("periodi/anno: deve essere > 0")
    import numpy as np
    eq = list(eq)
    if len(eq) < 30:
        raise ValueError("martin: servono almeno 30 periodi")
    ulcer = mh330_ulcer(eq)
    cagr = mh330_cagr(eq, p)
    max_dd = float(np.max(mh330_drawdown(eq)))
    martin = cagr / ulcer if ulcer > 0.0 else float("inf")
    return {"n": len(eq), "cagr": cagr, "ulcer": ulcer,
            "max_dd": max_dd, "martin": martin}


def mh330_verdetto(martin, ulcer_pct):
    """Verdetto a 3 stati sul Martin ratio (martin puo' essere inf)."""
    import math
    ulcer_pct = mh330_num(ulcer_pct, "ulcer %")
    if isinstance(martin, bool) or not isinstance(martin, (int, float)):
        raise ValueError("martin: deve essere un numero")
    if isinstance(martin, float) and math.isnan(martin):
        raise ValueError("martin: NaN non ammesso")
    m = float(martin)
    if math.isinf(m):
        return ("martin ratio ECCELLENTE: nessun drawdown nella serie "
                "(Ulcer Index 0.00%): l'equity non e' mai scesa dal picco, "
                "profilo ideale.")
    if m >= 2.0:
        return (f"martin ratio ECCELLENTE: {m:.2f}: il rendimento annuo paga "
                f"ampiamente il dolore continuo (Ulcer Index {ulcer_pct:.2f}%): "
                f"l'equity cresce senza sanguinare spesso, profilo solido.")
    if m >= 1.0:
        return (f"martin ratio MODERATO: {m:.2f}: il rendimento copre a malapena "
                f"il dolore continuo (Ulcer Index {ulcer_pct:.2f}%): drawdown "
                f"frequenti anche senza colpi profondissimi, rivedere sizing "
                f"e stop-loss prima di scalare.")
    return (f"martin ratio DEBOLE: {m:.2f}: il dolore continuo (Ulcer Index "
            f"{ulcer_pct:.2f}%) mangia il rendimento: l'equity sanguina troppo "
            f"spesso, ridimensionare o fermare finche' il profilo non cambia.")

