def mh329_cagr(eq, periodi_anno):
    """Tasso di crescita annuo composto (frazione, es. 0.13 = 13%)."""
    p = mh329_num(periodi_anno, "periodi/anno")
    if p <= 0.0:
        raise ValueError("periodi/anno: deve essere > 0")
    eq = list(eq)
    if len(eq) < 30:
        raise ValueError("cagr: servono almeno 30 periodi")
    return (eq[-1] / eq[0]) ** (p / (len(eq) - 1)) - 1.0


def mh329_cdar(eq, alpha):
    """DaR/CDaR sulla serie dei drawdown.

    dar = quantile_alpha dei drawdown (soglia di coda, frazione).
    cdar = media dei drawdown >= dar (frazione). max_dd = drawdown massimo.
    n_tail = quanti periodi stanno in coda. Se la serie non ha drawdown
    (tutti a zero): dar = cdar = max_dd = 0.0.
    """
    alpha = mh329_num(alpha, "alpha")
    if not 0.5 < alpha < 1.0:
        raise ValueError("alpha: deve stare tra 0.5 e 1 (es. 0.95)")
    import numpy as np
    dd = mh329_drawdown(eq)
    dar = float(np.quantile(dd, alpha))
    tail = dd[dd >= dar]
    cdar = float(np.mean(tail)) if len(tail) else 0.0
    return {"dar": dar, "cdar": cdar, "max_dd": float(np.max(dd)),
            "n_tail": int(len(tail)), "n": int(len(dd))}


def mh329_verdetto(cdar_pct, cagr_pct):
    """Verdetto a 3 stati: il CAGR copre il CDaR?"""
    import math
    cdar_pct = mh329_num(cdar_pct, "cdar %")
    cagr_pct = mh329_num(cagr_pct, "cagr %")
    if cdar_pct <= 0.0:
        return ("cdar ECCELLENTE: 0.00%: nessun drawdown nella serie: "
                "l'equity non e' mai scesa dal picco, profilo ideale.")
    copertura = cagr_pct / cdar_pct
    if copertura >= 1.5:
        return (f"cdar ECCELLENTE: {cdar_pct:.2f}%: il rendimento annuo "
                f"({cagr_pct:+.2f}%) copre la coda media dei drawdown con "
                f"margine ({copertura:.1f}x): quando va male non va "
                f"male davvero, profilo solido.")
    if copertura >= 0.7:
        return (f"cdar MODERATO: {cdar_pct:.2f}%: il rendimento "
                f"({cagr_pct:+.2f}%) copre a malapena la coda media dei "
                f"drawdown ({copertura:.1f}x): un episodio di coda piu' "
                f"profondo erode il margine, rivedere sizing e stop-loss "
                f"prima di scalare.")
    return (f"cdar DEBOLE: {cdar_pct:.2f}%: la coda media dei drawdown "
            f"supera il rendimento annuo ({cagr_pct:+.2f}%, copertura "
            f"{copertura:.1f}x): la strategia vive di colpi di coda, "
            f"ridimensionare o fermare finche' il profilo non cambia.")


