# W489 (16/10/2026) - tab489 "🪓🌪️ Component Stressed VaR: quale linea tagliare sotto stress?"
# Dopo lo Stressed VaR di portafoglio (tab488), la domanda operativa del risk
# manager quando il limite e' sfondato sotto stress: QUALE linea tagliare per
# prima? Component Stressed VaR (attribuzione di Eulero in regime stressato):
#   var_stress_i = z x mult x sigma_mtm_i   (per linea)
#   VaR_stress_cons = somma var_stress_i    (corr=1: l'attribuzione e' lineare,
#                                            il component della linea i e' var_stress_i)
#   VaR_stress_ind  = sqrt(somma var_stress_i^2)   (indipendenza, RSS)
#   component_ind_i = VaR_stress_ind x var_stress_i^2 / somma var_stress_j^2
# La linea peggiore e' quella col component conservativo massimo; il taglio
# necessario su di essa per rientrare nel limite e':
#   taglio_MWh = (VaR_stress_cons - limite) / (var_stress_peggiore / volume_peggiore)
# (il VaR stressato scala linearmente col volume). Verdetto:
# NESSUN TAGLIO NECESSARIO se VaR_stress_cons <= limite, altrimenti
# TAGLIARE <linea>: <X> MWh — LIMITE SFONDATO SOTTO STRESS.
# ===========================================================================


def mh489_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh489_segno(v, nome):
    _v489 = mh489_num(v, nome)
    if _v489 not in (1.0, -1.0):
        raise ValueError(f"{nome}: segno deve essere +1.0 o -1.0")
    return _v489


def mh489_mese(s, nome):
    if not isinstance(s, str):
        raise ValueError(f"{nome}: scadenza deve essere stringa YYYY-MM")
    _s489 = s.strip()
    _p489 = _s489.split("-")
    if len(_p489) != 2 or len(_p489[0]) != 4 or len(_p489[1]) != 2:
        raise ValueError(f"{nome}: scadenza formato YYYY-MM, got {s!r}")
    _a489, _m489 = int(_p489[0]), int(_p489[1])
    if not (2000 <= _a489 <= 2100 and 1 <= _m489 <= 12):
        raise ValueError(f"{nome}: mese non valido, got {s!r}")
    return f"{_a489:04d}-{_m489:02d}"


def mh489_z(conf, nome):
    _c489 = mh489_num(conf, nome)
    if _c489 == 0.99:
        return 2.3263478740408408
    if _c489 == 0.975:
        return 1.959963984540054
    raise ValueError(f"{nome}: confidenza 0.99 o 0.975, got {conf!r}")


def mh489_mult(m, nome="moltiplicatore"):
    _m489 = mh489_num(m, nome)
    if not (0.0 < _m489 <= 10.0):
        raise ValueError(f"{nome}: in (0,10], got {m!r}")
    return _m489


def mh489_limite(l, nome="limite"):
    _l489 = mh489_num(l, nome)
    if _l489 <= 0.0:
        raise ValueError(f"{nome}: limite positivo, got {l!r}")
    return _l489


def mh489_dv01_linea(segno, volume, nome="dv01"):
    """DV01 della linea: segno * volume (EUR per +1 EUR/MWh)."""
    _s489 = mh489_segno(segno, nome)
    _v489 = mh489_num(volume, nome)
    if _v489 < 0.0:
        raise ValueError(f"{nome}: volume non negativo ({volume!r})")
    return _s489 * _v489


def mh489_sigma_mtm_linea(dv01, sigma_pct, prezzo, nome="sigma"):
    """Volatilita' giornaliera del MtM: |DV01| * sigma_pct/100 * prezzo."""
    _sg489 = mh489_num(sigma_pct, nome)
    if not (0.0 < _sg489 <= 100.0):
        raise ValueError(
            f"{nome}: sigma_pct in (0,100] percento, got {sigma_pct!r}")
    _p489 = mh489_num(prezzo, nome)
    if _p489 < 0.0:
        raise ValueError(f"{nome}: prezzo non negativo ({prezzo!r})")
    return abs(mh489_num(dv01, nome)) * _sg489 / 100.0 * _p489


def mh489_var_stress_linea(sigma_mtm, z, mult, nome="linea"):
    """Stressed VaR della linea: z * mult * sigma_mtm."""
    _sm489 = mh489_num(sigma_mtm, nome)
    _z489 = mh489_num(z, nome)
    _m489 = mh489_mult(mult, nome)
    if _sm489 < 0.0:
        raise ValueError(f"{nome}: sigma_mtm non negativa ({sigma_mtm!r})")
    if _z489 <= 0.0:
        raise ValueError(f"{nome}: z deve essere positivo ({z!r})")
    return _z489 * _m489 * _sm489


def mh489_riga(commodity, scadenza, volume, segno, f_fix, f_now, sigma_pct,
               nome="riga"):
    """Riga posizione: validatori + dv01/sigma_mtm/var_stress della linea."""
    _sc489 = mh489_mese(scadenza, nome)
    _dv489 = mh489_dv01_linea(segno, volume, nome)
    _sg489 = mh489_sigma_mtm_linea(_dv489, sigma_pct, f_now, nome)
    _ff489 = mh489_num(f_fix, nome)
    _fn489 = mh489_num(f_now, nome)
    if _ff489 < 0.0 or _fn489 < 0.0:
        raise ValueError(f"{nome}: prezzi forward non negativi")
    return {"commodity": str(commodity), "scadenza": _sc489,
            "volume_mwh": mh489_num(volume, nome),
            "segno": mh489_segno(segno, nome),
            "f_fix": _ff489, "f_now": _fn489,
            "sigma_pct": mh489_num(sigma_pct, nome),
            "dv01": _dv489, "sigma_mtm": _sg489}


def mh489_componenti(righe, z, mult, nome="componenti"):
    """Component Stressed VaR: attribuzione conservativa (corr=1, lineare)
    e per indipendenza (RSS, Eulero)."""
    import math
    _z489 = mh489_num(z, nome)
    _m489 = mh489_mult(mult, nome)
    if _z489 <= 0.0:
        raise ValueError(f"{nome}: z deve essere positivo ({z!r})")
    if not righe:
        raise ValueError(f"{nome}: almeno una riga di posizione")
    _vs489 = [mh489_var_stress_linea(r["sigma_mtm"], _z489, _m489, nome)
              for r in righe]
    _cons489 = sum(_vs489)
    _sq489 = sum(_v489 * _v489 for _v489 in _vs489)
    _ind489 = math.sqrt(_sq489)
    _comp_ind489 = [(_ind489 * _v489 * _v489 / _sq489 if _sq489 > 0.0 else 0.0)
                    for _v489 in _vs489]
    _share489 = [(_v489 / _cons489 if _cons489 > 0.0 else 0.0)
                 for _v489 in _vs489]
    return {"var_stress": _vs489, "var_stress_cons": _cons489,
            "var_stress_ind": _ind489, "comp_ind": _comp_ind489,
            "share_cons": _share489,
            "div_benefit": ((_cons489 - _ind489) / _cons489
                            if _cons489 > 0.0 else 0.0)}


def mh489_taglio(righe, z, mult, limite, nome="taglio"):
    """Quale linea tagliare per prima sotto stress e di quanto (MWh)."""
    _l489 = mh489_limite(limite, nome)
    _c489 = mh489_componenti(righe, z, mult, nome)
    _vc489 = _c489["var_stress_cons"]
    if _vc489 <= _l489:
        return {"verdetto": "NESSUN TAGLIO NECESSARIO — "
                            "ENTRO IL LIMITE SOTTO STRESS",
                "var_stress_cons": _vc489, "limite": _l489,
                "peggiore": None, "taglio_mwh": None,
                "var_dopo_taglio": _vc489}
    _i489 = max(range(len(righe)),
                key=lambda k: _c489["var_stress"][k])
    _r489 = righe[_i489]
    _vol489 = _r489["volume_mwh"]
    _vs_i489 = _c489["var_stress"][_i489]
    # Nota: _vc489 > _l489 > 0 implica _vs_i489 > 0 e _vol489 > 0
    # (il VaR stressato scala col volume), quindi la divisione e' sicura.
    _per_mwh489 = _vs_i489 / _vol489
    _taglio489 = (_vc489 - _l489) / _per_mwh489
    _dopo489 = _vc489 - _vs_i489 + (_vol489 - _taglio489) * _per_mwh489
    _label489 = f"{_r489['commodity']} {_r489['scadenza']}"
    return {"verdetto": (f"TAGLIARE {_label489}: {_taglio489:,.0f} MWh — "
                         f"LIMITE SFONDATO SOTTO STRESS"),
            "var_stress_cons": _vc489, "limite": _l489,
            "peggiore": _label489, "taglio_mwh": _taglio489,
            "var_dopo_taglio": _dopo489}


# W492 (16/10/2026) - tab492 "⏳🌪️ Decadimento dello stress: aspettare o coprire?"
# Dopo tab491 — che dimensionava l'hedge IMMEDIATO per riportare l'ES stressato
# entro il limite — la domanda operativa complementare: lo shock di volatilita'
# DECADRE (la vol mean-reverte: dopo un evento di crisi la vol giornaliera
# rientra verso il livello base con un'emivita misurabile in giorni). Coprire
# OGGI paga il bid-ask su h*(0) MWh; aspettare t* giorni costa zero e l'ES
# rientra nel limite da solo. Modello conservativo (corr=1):
#   es_base_cons  = Somma |lambda(z) * sigma_mtm_i|          (vol base)
#   es_stress_cons= Somma |lambda(z) * mult * sigma_mtm_i|   (vol stressata)
#   es(t) = es_base + (es_stress - es_base) * exp(-t * ln2 / halflife)
# L'ES e' lineare nella vol, quindi decade esattamente esponenziale.
#   t* = hl/ln2 * ln((es_stress - es_base) / (limite - es_base))
# Verdetti:
#   OK_STRESS:       es_stress <= limite      -> nessuna azione
#   MAI:             es_base >= limite        -> l'attesa non basta mai,
#                                            serve hedge/chiusura strutturale
#   ASPETTARE:       t* <= orizzonte         -> aspettare t* giorni;
#                                            hedging oggi costerebbe C EUR
#                                            (risparmio atteso = C)
#   OLTRE_ORIZZONTE: t* > orizzonte          -> rientro troppo lento,
#                                            valutare l'hedge immediato
# Per la traiettoria dell'hedge: h*(t) = max(0, (es(t)-limite)/es_per_mwh_hedge)
# con es_per_mwh_hedge = lambda(z)*mult*f_hedge*sigma_hedge_pct/100
# (stessa ipotesi conservativa di tab491: l'hedge e' sulla linea coperta e la
# vol dell'hedge decade con la stessa emivita della linea coperta).
# Costo(t) = h*(t) * f_hedge * spread_bps / 10000.
# ===========================================================================


def mh492_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh492_segno(v, nome):
    _v492 = mh492_num(v, nome)
    if _v492 not in (1.0, -1.0):
        raise ValueError(f"{nome}: segno deve essere +1.0 o -1.0")
    return _v492


def mh492_mese(s, nome):
    if not isinstance(s, str):
        raise ValueError(f"{nome}: scadenza deve essere stringa YYYY-MM")
    _s492 = s.strip()
    _p492 = _s492.split("-")
    if len(_p492) != 2 or len(_p492[0]) != 4 or len(_p492[1]) != 2:
        raise ValueError(f"{nome}: scadenza formato YYYY-MM, got {s!r}")
    _a492, _m492 = int(_p492[0]), int(_p492[1])
    if not (2000 <= _a492 <= 2100 and 1 <= _m492 <= 12):
        raise ValueError(f"{nome}: mese non valido, got {s!r}")
    return f"{_a492:04d}-{_m492:02d}"


def mh492_z(conf, nome):
    _c492 = mh492_num(conf, nome)
    if _c492 == 0.99:
        return 2.3263478740408408
    if _c492 == 0.975:
        return 1.959963984540054
    raise ValueError(f"{nome}: confidenza 0.99 o 0.975, got {conf!r}")


def mh492_phi(z):
    """Densita' normale standard."""
    import math
    _z492 = mh492_num(z, "z")
    return math.exp(-_z492 * _z492 / 2.0) / math.sqrt(2.0 * math.pi)


def mh492_Phi(z):
    """Ripartizione normale standard (via erf)."""
    import math
    _z492 = mh492_num(z, "z")
    return 0.5 * (1.0 + math.erf(_z492 / math.sqrt(2.0)))


def mh492_lambda(z, nome="lambda"):
    """Moltiplicatore ES/VaR: phi(z)/(1-Phi(z)), sempre >= z."""
    _z492 = mh492_num(z, nome)
    _p492 = mh492_Phi(_z492)
    if _p492 >= 1.0:
        raise ValueError(f"{nome}: z troppo grande, coda nulla ({z!r})")
    return mh492_phi(_z492) / (1.0 - _p492)


def mh492_mult(m, nome="moltiplicatore"):
    """Moltiplicatore di stress della volatilita', in [1, 10]."""
    _m492 = mh492_num(m, nome)
    if not (1.0 <= _m492 <= 10.0):
        raise ValueError(f"{nome}: moltiplicatore stress in [1,10], got {m!r}")
    return _m492


def mh492_limite(l, nome="limite"):
    """Limite di rischio ES in EUR, positivo."""
    _l492 = mh492_num(l, nome)
    if _l492 <= 0.0:
        raise ValueError(f"{nome}: limite ES positivo in EUR, got {l!r}")
    return _l492


def mh492_halflife(h, nome="emivita"):
    """Emivita del decadimento della volatilita' stressata, in giorni [0.5, 365]."""
    _h492 = mh492_num(h, nome)
    if not (0.5 <= _h492 <= 365.0):
        raise ValueError(f"{nome}: emivita in giorni [0.5,365], got {h!r}")
    return _h492


def mh492_orizzonte(n, nome="orizzonte"):
    """Orizzonte di simulazione in giorni interi [7, 365]."""
    _n492 = mh492_num(n, nome)
    _i492 = int(round(_n492))
    if not (7 <= _i492 <= 365):
        raise ValueError(f"{nome}: orizzonte in giorni [7,365], got {n!r}")
    return _i492


def mh492_dv01_linea(segno, volume, nome="dv01"):
    """DV01 della linea: segno * volume (EUR per +1 EUR/MWh)."""
    _s492 = mh492_segno(segno, nome)
    _v492 = mh492_num(volume, nome)
    if _v492 < 0.0:
        raise ValueError(f"{nome}: volume non negativo ({volume!r})")
    return _s492 * _v492


def mh492_sigma_mtm_linea(dv01, sigma_pct, prezzo, nome="sigma"):
    """Volatilita' giornaliera del MtM: |DV01| * sigma_pct/100 * prezzo."""
    _sg492 = mh492_num(sigma_pct, nome)
    if not (0.0 < _sg492 <= 100.0):
        raise ValueError(
            f"{nome}: sigma_pct in (0,100] percento, got {sigma_pct!r}")
    _p492 = mh492_num(prezzo, nome)
    if _p492 < 0.0:
        raise ValueError(f"{nome}: prezzo non negativo ({prezzo!r})")
    return abs(mh492_num(dv01, nome)) * _sg492 / 100.0 * _p492


def mh492_es_linea(sigma_mtm, z, mult, nome="linea"):
    """ES della linea a vol moltiplicata: lambda(z) * mult * sigma_mtm."""
    _sm492 = mh492_num(sigma_mtm, nome)
    _z492 = mh492_num(z, nome)
    _m492 = mh492_num(mult, nome)
    if _sm492 < 0.0:
        raise ValueError(f"{nome}: sigma_mtm non negativa ({sigma_mtm!r})")
    if _z492 <= 0.0:
        raise ValueError(f"{nome}: z deve essere positivo ({z!r})")
    if _m492 < 1.0:
        raise ValueError(f"{nome}: moltiplicatore vol >= 1 ({mult!r})")
    return mh492_lambda(_z492) * _m492 * _sm492


def mh492_riga(commodity, scadenza, volume, segno, f_fix, f_now, sigma_pct,
               nome="riga"):
    """Riga posizione: validatori + dv01/sigma_mtm/es_base/es_stress."""
    _r492 = {
        "commodity": commodity if isinstance(commodity, str) else str(commodity),
        "scadenza": mh492_mese(scadenza, nome),
        "volume_mwh": mh492_num(volume, nome),
        "segno": mh492_segno(segno, nome),
        "f_fix": mh492_num(f_fix, nome),
        "f_now": mh492_num(f_now, nome),
        "sigma_pct": mh492_num(sigma_pct, nome),
    }
    _dv492 = mh492_dv01_linea(_r492["segno"], _r492["volume_mwh"], nome)
    _r492["dv01"] = _dv492
    _sm492 = mh492_sigma_mtm_linea(_dv492, _r492["sigma_pct"], _r492["f_now"],
                                   nome)
    _r492["sigma_mtm"] = _sm492
    return _r492


def mh492_portafoglio(righe, z, mult, nome="portafoglio"):
    """ES base e stressato conservativi (corr=1) del portafoglio."""
    _z492 = mh492_num(z, nome)
    _m492 = mh492_mult(mult, nome)
    _eb492 = [_e492 for _e492 in
              (abs(mh492_es_linea(r["sigma_mtm"], _z492, 1.0, nome))
               for r in righe)]
    _es492 = [_e492 for _e492 in
              (abs(mh492_es_linea(r["sigma_mtm"], _z492, _m492, nome))
               for r in righe)]
    return {"es_base_linee": _eb492, "es_stress_linee": _es492,
            "es_base_cons": sum(_eb492), "es_stress_cons": sum(_es492)}


def mh492_decay(t_giorni, halflife, nome="decadimento"):
    """Fattore di decadimento esponenziale: exp(-t*ln2/halflife)."""
    import math
    _t492 = mh492_num(t_giorni, nome)
    _h492 = mh492_halflife(halflife, nome)
    if _t492 < 0.0:
        raise ValueError(f"{nome}: t non negativo ({t_giorni!r})")
    return math.exp(-_t492 * math.log(2.0) / _h492)


def mh492_es_t(es_base, es_stress, t_giorni, halflife, nome="es_t"):
    """ES conservativo al giorno t: base + (stress-base) * decay(t)."""
    _b492 = mh492_num(es_base, nome)
    _s492 = mh492_num(es_stress, nome)
    if _b492 < 0.0 or _s492 < 0.0:
        raise ValueError(f"{nome}: ES non negativi ({es_base!r},{es_stress!r})")
    if _s492 < _b492:
        raise ValueError(f"{nome}: ES stressato >= base ({es_base!r},{es_stress!r})")
    return _b492 + (_s492 - _b492) * mh492_decay(t_giorni, halflife, nome)


def mh492_curva_es(es_base, es_stress, halflife, orizzonte, passo=1.0,
                   nome="curva"):
    """Traiettoria giornaliera dell'ES: lista di (giorno, es_t)."""
    import math
    _h492 = mh492_halflife(halflife, nome)
    _n492 = mh492_orizzonte(orizzonte, nome)
    _p492 = mh492_num(passo, nome)
    if _p492 <= 0.0:
        raise ValueError(f"{nome}: passo positivo ({passo!r})")
    _t492 = 0.0
    _out492 = []
    while _t492 <= float(_n492) + 1e-9:
        _out492.append((_t492, mh492_es_t(es_base, es_stress, _t492, _h492,
                                         nome)))
        _t492 += _p492
    return _out492


def mh492_t_rientro(es_base, es_stress, limite, halflife, nome="rientro"):
    """Giorni affinche' l'ES rientri nel limite col decadimento della vol.

    0.0 se gia' sotto limite sotto stress; None se non rientra mai
    (ES base >= limite).
    """
    import math
    _b492 = mh492_num(es_base, nome)
    _s492 = mh492_num(es_stress, nome)
    _l492 = mh492_limite(limite, nome)
    _h492 = mh492_halflife(halflife, nome)
    if _b492 < 0.0 or _s492 < 0.0:
        raise ValueError(f"{nome}: ES non negativi ({es_base!r},{es_stress!r})")
    if _s492 < _b492:
        raise ValueError(f"{nome}: ES stressato >= base ({es_base!r},{es_stress!r})")
    if _s492 <= _l492:
        return 0.0
    if _b492 >= _l492:
        return None
    return _h492 / math.log(2.0) * math.log(
        (_s492 - _b492) / (_l492 - _b492))


def mh492_es_per_mwh_hedge(z, mult, f_hedge, sigma_hedge_pct, nome="hedge"):
    """ES stressato per MWh coperto (stessa ipotesi conservativa di tab491)."""
    _f492 = mh492_num(f_hedge, nome)
    _sg492 = mh492_num(sigma_hedge_pct, nome)
    if _f492 <= 0.0:
        raise ValueError(f"{nome}: f_hedge positivo ({f_hedge!r})")
    if not (0.0 < _sg492 <= 100.0):
        raise ValueError(f"{nome}: sigma_hedge in (0,100] ({sigma_hedge_pct!r})")
    return (mh492_lambda(mh492_num(z, nome)) * mh492_mult(mult, nome)
            * _sg492 / 100.0 * _f492)


def mh492_spread_bps(s, nome="spread"):
    _s492 = mh492_num(s, nome)
    if not (0.0 <= _s492 <= 1000.0):
        raise ValueError(f"{nome}: spread bps in [0,1000], got {s!r}")
    return _s492


def mh492_hedge_t(es_t, limite, es_per_mwh, volume_linea, nome="hedge_t"):
    """Hedge necessario al giorno t (MWh), clip [0, volume_linea]."""
    _e492 = mh492_num(es_t, nome)
    _l492 = mh492_limite(limite, nome)
    _u492 = mh492_num(es_per_mwh, nome)
    _v492 = mh492_num(volume_linea, nome)
    if _u492 <= 0.0:
        raise ValueError(f"{nome}: es_per_mwh positivo ({es_per_mwh!r})")
    if _v492 < 0.0:
        raise ValueError(f"{nome}: volume non negativo ({volume_linea!r})")
    if _e492 <= _l492:
        return 0.0
    return min(_v492, (_e492 - _l492) / _u492)


def mh492_costo(h_mwh, f_hedge, spread_bps, nome="costo"):
    """Bid-ask pagato sull'eseguito: h * f_hedge * spread_bps/10000."""
    _h492 = mh492_num(h_mwh, nome)
    _f492 = mh492_num(f_hedge, nome)
    _s492 = mh492_spread_bps(spread_bps, nome)
    if _h492 < 0.0:
        raise ValueError(f"{nome}: hedge non negativo ({h_mwh!r})")
    if _f492 <= 0.0:
        raise ValueError(f"{nome}: f_hedge positivo ({f_hedge!r})")
    return _h492 * _f492 * _s492 / 10000.0


def mh492_verdetto(es_base, es_stress, limite, halflife, orizzonte,
                   es_per_mwh_hedge, volume_linea, f_hedge, spread_bps,
                   nome="verdetto"):
    """Verdetto operativo: codice + testo + numeri chiave."""
    _t492 = mh492_t_rientro(es_base, es_stress, limite, halflife, nome)
    _n492 = mh492_orizzonte(orizzonte, nome)
    _u492 = mh492_num(es_per_mwh_hedge, nome)
    _c_oggi492 = mh492_costo(
        mh492_hedge_t(es_stress, limite, _u492, volume_linea, nome),
        f_hedge, spread_bps, nome)
    if _t492 == 0.0:
        return {"codice": "OK_STRESS", "t_rientro_giorni": 0.0,
                "hedge_oggi_mwh": 0.0, "costo_oggi_eur": 0.0,
                "risparmio_eur": 0.0,
                "testo": ("NESSUNA AZIONE NECESSARIA — l'ES stressato "
                          "resta sotto il limite.")}
    if _t492 is None:
        _h492 = mh492_hedge_t(es_base, limite, _u492, volume_linea, nome)
        return {"codice": "MAI", "t_rientro_giorni": None,
                "hedge_oggi_mwh": mh492_hedge_t(es_stress, limite, _u492,
                                                volume_linea, nome),
                "costo_oggi_eur": _c_oggi492, "risparmio_eur": 0.0,
                "testo": ("IL LIMITE RESTA SFONDATO ANCHE A STRESS RIENTRATO — "
                          "l'attesa non basta: serve hedge o chiusura "
                          f"strutturale (hedge sulla linea oggi: {_h492:,.0f} "
                          "MWh).")}
    if _t492 <= float(_n492):
        return {"codice": "ASPETTARE", "t_rientro_giorni": _t492,
                "hedge_oggi_mwh": mh492_hedge_t(es_stress, limite, _u492,
                                                volume_linea, nome),
                "costo_oggi_eur": _c_oggi492, "risparmio_eur": _c_oggi492,
                "testo": (f"ASPETTARE {_t492:,.1f} GIORNI — l'ES rientra nel "
                          f"limite col decadimento della volatilita'. "
                          f"Hedging oggi costerebbe {_c_oggi492:,.0f} EUR di "
                          "bid-ask: aspettare fa risparmiare l'intero costo.")}
    return {"codice": "OLTRE_ORIZZONTE", "t_rientro_giorni": _t492,
            "hedge_oggi_mwh": mh492_hedge_t(es_stress, limite, _u492,
                                            volume_linea, nome),
            "costo_oggi_eur": _c_oggi492, "risparmio_eur": 0.0,
            "testo": (f"RIENTRO OLTRE L'ORIZZONTE ({_t492:,.0f} > {_n492} "
                      "giorni): il decadimento e' troppo lento — valutare "
                      f"l'hedge immediato (costo stimato {_c_oggi492:,.0f} "
                      "EUR).")}



# ===========================================================================
# W493 (16/10/2026) - tab493 "💸⏳ Costo dell'attesa: il budget di rischio consumato"
# Dopo tab492 — che diceva "aspetta t* giorni invece di hedgiare subito" —
# la domanda operativa mancante: mentre aspetti, il portafoglio resta SOPRA
# il limite ES. Quella permanenza sopra il limite CONSUMA budget di rischio.
# Un risk desk ragiona in EUR*giorni di eccesso: budget mensile B, consumo
# I = integrale dell'eccesso sopra il limite durante l'attesa.
# Modello conservativo (corr=1), stesso ES(t) di tab492:
#   es(t) = es_base + (es_stress - es_base) * exp(-t * ln2 / halflife)
#   X(t)  = max(0, es(t) - limite)                      (eccesso sopra limite)
#   t*    = hl/ln2 * ln((es_stress-es_base)/(limite-es_base))  (giorni al rientro)
# Forma chiusa (X(t) >= 0 per t in [0, t*], zero a t*):
#   I = (es_base-limite)*t* + (es_stress-es_base)*(hl/ln2)*(1-exp(-t**ln2/hl))
# KPI derivati:
#   N_eq  = I / limite          (giorni-equivalenti di limite consumati:
#                                aspettare t* gg a eccesso decrescente equivale
#                                a N_eq giorni a limite pieno)
#   frac  = I / budget          (frazione del budget mensile consumata)
# Verdetti (soglie di policy 50% / 100%):
#   OK_STRESS:       t* == 0          -> nessun consumo, nessuna azione
#   MAI:             t* is None       -> sfondamento strutturale: l'attesa non
#                                        basta, il budget non c'entra
#   OLTRE_ORIZZONTE: t* > orizzonte   -> rientro troppo lento, meglio coprire
#   SOSTENIBILE:     frac < 0.50      -> l'attesa conviene
#   ELEVATO:         0.50 <= frac < 1 -> l'attesa costa quasi tutto il budget
#   BUDGET_SFONDATO: frac >= 1        -> il budget non regge l'attesa: coprire
# ===========================================================================


def mh493_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh493_segno(v, nome):
    _v493 = mh493_num(v, nome)
    if _v493 not in (1.0, -1.0):
        raise ValueError(f"{nome}: segno deve essere +1.0 o -1.0")
    return _v493


def mh493_mese(s, nome):
    if not isinstance(s, str):
        raise ValueError(f"{nome}: scadenza deve essere stringa YYYY-MM")
    _s493 = s.strip()
    _p493 = _s493.split("-")
    if len(_p493) != 2 or len(_p493[0]) != 4 or len(_p493[1]) != 2:
        raise ValueError(f"{nome}: scadenza formato YYYY-MM, got {s!r}")
    _a493, _m493 = int(_p493[0]), int(_p493[1])
    if not (2000 <= _a493 <= 2100 and 1 <= _m493 <= 12):
        raise ValueError(f"{nome}: mese non valido, got {s!r}")
    return f"{_a493:04d}-{_m493:02d}"


def mh493_z(conf, nome):
    _c493 = mh493_num(conf, nome)
    if _c493 == 0.99:
        return 2.3263478740408408
    if _c493 == 0.975:
        return 1.959963984540054
    raise ValueError(f"{nome}: confidenza 0.99 o 0.975, got {conf!r}")


def mh493_phi(z):
    """Densita' normale standard."""
    import math
    _z493 = mh493_num(z, "z")
    return math.exp(-_z493 * _z493 / 2.0) / math.sqrt(2.0 * math.pi)


def mh493_Phi(z):
    """Ripartizione normale standard (via erf)."""
    import math
    _z493 = mh493_num(z, "z")
    return 0.5 * (1.0 + math.erf(_z493 / math.sqrt(2.0)))


def mh493_lambda(z, nome="lambda"):
    """Moltiplicatore ES/VaR: phi(z)/(1-Phi(z)), sempre >= z."""
    _z493 = mh493_num(z, nome)
    _p493 = mh493_Phi(_z493)
    if _p493 >= 1.0:
        raise ValueError(f"{nome}: z troppo grande, coda nulla ({z!r})")
    return mh493_phi(_z493) / (1.0 - _p493)


def mh493_mult(m, nome="moltiplicatore"):
    """Moltiplicatore di stress della volatilita', in [1, 10]."""
    _m493 = mh493_num(m, nome)
    if not (1.0 <= _m493 <= 10.0):
        raise ValueError(f"{nome}: moltiplicatore stress in [1,10], got {m!r}")
    return _m493


def mh493_limite(l, nome="limite"):
    """Limite di rischio ES in EUR, positivo."""
    _l493 = mh493_num(l, nome)
    if _l493 <= 0.0:
        raise ValueError(f"{nome}: limite ES positivo in EUR, got {l!r}")
    return _l493


def mh493_halflife(h, nome="emivita"):
    """Emivita del decadimento della volatilita' stressata, in giorni [0.5, 365]."""
    _h493 = mh493_num(h, nome)
    if not (0.5 <= _h493 <= 365.0):
        raise ValueError(f"{nome}: emivita in giorni [0.5,365], got {h!r}")
    return _h493


def mh493_orizzonte(n, nome="orizzonte"):
    """Orizzonte di simulazione in giorni interi [7, 365]."""
    _n493 = mh493_num(n, nome)
    _i493 = int(round(_n493))
    if not (7 <= _i493 <= 365):
        raise ValueError(f"{nome}: orizzonte in giorni [7,365], got {n!r}")
    return _i493


def mh493_budget(b, nome="budget"):
    """Budget di rischio mensile in EUR*giorni di eccesso sopra il limite."""
    _b493 = mh493_num(b, nome)
    if _b493 <= 0.0:
        raise ValueError(f"{nome}: budget positivo in EUR*giorni, got {b!r}")
    return _b493


def mh493_dv01_linea(segno, volume, nome="dv01"):
    """DV01 della linea: segno * volume (EUR per +1 EUR/MWh)."""
    _s493 = mh493_segno(segno, nome)
    _v493 = mh493_num(volume, nome)
    if _v493 < 0.0:
        raise ValueError(f"{nome}: volume non negativo ({volume!r})")
    return _s493 * _v493


def mh493_sigma_mtm_linea(dv01, sigma_pct, prezzo, nome="sigma"):
    """Volatilita' giornaliera del MtM: |DV01| * sigma_pct/100 * prezzo."""
    _sg493 = mh493_num(sigma_pct, nome)
    if not (0.0 < _sg493 <= 100.0):
        raise ValueError(
            f"{nome}: sigma_pct in (0,100] percento, got {sigma_pct!r}")
    _p493 = mh493_num(prezzo, nome)
    if _p493 < 0.0:
        raise ValueError(f"{nome}: prezzo non negativo ({prezzo!r})")
    return abs(mh493_num(dv01, nome)) * _sg493 / 100.0 * _p493


def mh493_es_linea(sigma_mtm, z, mult, nome="linea"):
    """ES della linea a vol moltiplicata: lambda(z) * mult * sigma_mtm."""
    _sm493 = mh493_num(sigma_mtm, nome)
    _z493 = mh493_num(z, nome)
    _m493 = mh493_num(mult, nome)
    if _sm493 < 0.0:
        raise ValueError(f"{nome}: sigma_mtm non negativa ({sigma_mtm!r})")
    if _z493 <= 0.0:
        raise ValueError(f"{nome}: z deve essere positivo ({z!r})")
    if _m493 < 1.0:
        raise ValueError(f"{nome}: moltiplicatore vol >= 1 ({mult!r})")
    return mh493_lambda(_z493) * _m493 * _sm493


def mh493_riga(commodity, scadenza, volume, segno, f_fix, f_now, sigma_pct,
               nome="riga"):
    """Riga posizione: validatori + dv01/sigma_mtm."""
    _r493 = {
        "commodity": commodity if isinstance(commodity, str) else str(commodity),
        "scadenza": mh493_mese(scadenza, nome),
        "volume_mwh": mh493_num(volume, nome),
        "segno": mh493_segno(segno, nome),
        "f_fix": mh493_num(f_fix, nome),
        "f_now": mh493_num(f_now, nome),
        "sigma_pct": mh493_num(sigma_pct, nome),
    }
    _dv493 = mh493_dv01_linea(_r493["segno"], _r493["volume_mwh"], nome)
    _r493["dv01"] = _dv493
    _sm493 = mh493_sigma_mtm_linea(_dv493, _r493["sigma_pct"], _r493["f_now"],
                                   nome)
    _r493["sigma_mtm"] = _sm493
    return _r493


def mh493_portafoglio(righe, z, mult, nome="portafoglio"):
    """ES base e stressato conservativi (corr=1) del portafoglio."""
    _z493 = mh493_num(z, nome)
    _m493 = mh493_mult(mult, nome)
    _eb493 = [_e493 for _e493 in
              (abs(mh493_es_linea(r["sigma_mtm"], _z493, 1.0, nome))
               for r in righe)]
    _es493 = [_e493 for _e493 in
              (abs(mh493_es_linea(r["sigma_mtm"], _z493, _m493, nome))
               for r in righe)]
    return {"es_base_linee": _eb493, "es_stress_linee": _es493,
            "es_base_cons": sum(_eb493), "es_stress_cons": sum(_es493)}


def mh493_es_t(es_base, es_stress, t_giorni, halflife, nome="es_t"):
    """ES conservativo al giorno t: base + (stress-base) * exp(-t*ln2/hl)."""
    import math
    _b493 = mh493_num(es_base, nome)
    _s493 = mh493_num(es_stress, nome)
    if _b493 < 0.0 or _s493 < 0.0:
        raise ValueError(f"{nome}: ES non negativi ({es_base!r},{es_stress!r})")
    if _s493 < _b493:
        raise ValueError(f"{nome}: ES stressato >= base ({es_base!r},{es_stress!r})")
    _t493 = mh493_num(t_giorni, nome)
    if _t493 < 0.0:
        raise ValueError(f"{nome}: t non negativo ({t_giorni!r})")
    _h493 = mh493_halflife(halflife, nome)
    return _b493 + (_s493 - _b493) * math.exp(-_t493 * math.log(2.0) / _h493)


def mh493_t_rientro(es_base, es_stress, limite, halflife, nome="rientro"):
    """Giorni affinche' l'ES rientri nel limite col decadimento della vol.

    0.0 se gia' sotto limite sotto stress; None se non rientra mai
    (ES base >= limite).
    """
    import math
    _b493 = mh493_num(es_base, nome)
    _s493 = mh493_num(es_stress, nome)
    _l493 = mh493_limite(limite, nome)
    _h493 = mh493_halflife(halflife, nome)
    if _b493 < 0.0 or _s493 < 0.0:
        raise ValueError(f"{nome}: ES non negativi ({es_base!r},{es_stress!r})")
    if _s493 < _b493:
        raise ValueError(f"{nome}: ES stressato >= base ({es_base!r},{es_stress!r})")
    if _s493 <= _l493:
        return 0.0
    if _b493 >= _l493:
        return None
    return _h493 / math.log(2.0) * math.log(
        (_s493 - _b493) / (_l493 - _b493))


def mh493_eccesso_t(es_base, es_stress, limite, halflife, t_giorni,
                    nome="eccesso"):
    """Eccesso dell'ES sopra il limite al giorno t: max(0, es(t)-limite)."""
    _l493 = mh493_limite(limite, nome)
    _e493 = mh493_es_t(es_base, es_stress, t_giorni, halflife, nome)
    return max(0.0, _e493 - _l493)


def mh493_integrale_chiusa(es_base, es_stress, limite, halflife, t_capo,
                            nome):
    """Forma chiusa di integrale_0^t_capo X(t) dt, con X>=0 su [0, t_capo]."""
    import math
    _b493 = mh493_num(es_base, nome)
    _s493 = mh493_num(es_stress, nome)
    _l493 = mh493_limite(limite, nome)
    _h493 = mh493_halflife(halflife, nome)
    _tc493 = mh493_num(t_capo, nome)
    if _tc493 < 0.0:
        raise ValueError(f"{nome}: t non negativo ({t_capo!r})")
    _k493 = math.log(2.0) / _h493
    return ((_b493 - _l493) * _tc493
            + (_s493 - _b493) / _k493 * (1.0 - math.exp(-_k493 * _tc493)))


def mh493_integrale_eccesso(es_base, es_stress, limite, halflife, t_rientro,
                            nome="integrale"):
    """Eccesso integrato sopra il limite durante l'attesa (EUR*giorni).

    t_rientro: giorni al rientro (0.0 se gia' dentro). None non ammesso:
    senza rientro l'integrale diverge concettualmente (attesa inutile).
    """
    if t_rientro is None:
        raise ValueError(f"{nome}: t_rientro None (nessun rientro): "
                         "l'integrale non e' definito, l'attesa non basta")
    _t493 = mh493_num(t_rientro, nome)
    if _t493 < 0.0:
        raise ValueError(f"{nome}: t_rientro non negativo ({t_rientro!r})")
    if _t493 == 0.0:
        return 0.0
    _i493 = mh493_integrale_chiusa(es_base, es_stress, limite, halflife,
                                    _t493, nome)
    # Per costruzione X(t) >= 0 su [0, t*]; guardia numerica anti -0.0.
    return max(0.0, _i493)


def mh493_giorni_equivalenti(integrale, limite, nome="giorni_eq"):
    """Giorni-equivalenti di limite: I / limite.

    Aspettare t* giorni a eccesso decrescente equivale a N_eq giorni
    a limite pieno sopra il limite.
    """
    _i493 = mh493_num(integrale, nome)
    _l493 = mh493_limite(limite, nome)
    if _i493 < 0.0:
        raise ValueError(f"{nome}: integrale non negativo ({integrale!r})")
    return _i493 / _l493


def mh493_frazione_budget(integrale, budget, nome="frazione"):
    """Frazione del budget mensile consumata dall'attesa: I / budget."""
    _i493 = mh493_num(integrale, nome)
    _b493 = mh493_budget(budget, nome)
    if _i493 < 0.0:
        raise ValueError(f"{nome}: integrale non negativo ({integrale!r})")
    return _i493 / _b493


def mh493_cumulata(es_base, es_stress, limite, halflife, t_rientro, t_giorni,
                   nome="cumulata"):
    """Eccesso cumulato fino al giorno t: integrale_0^min(t,t*) X(s) ds.

    Monotona non decrescente, piatta a I per t >= t*.
    """
    if t_rientro is None:
        raise ValueError(f"{nome}: t_rientro None (nessun rientro)")
    _tr493 = mh493_num(t_rientro, nome)
    _t493 = mh493_num(t_giorni, nome)
    if _tr493 < 0.0 or _t493 < 0.0:
        raise ValueError(f"{nome}: tempi non negativi ({t_rientro!r},{t_giorni!r})")
    if _tr493 == 0.0:
        return 0.0
    return max(0.0, mh493_integrale_chiusa(es_base, es_stress, limite,
                                            halflife, min(_t493, _tr493),
                                            nome))


def mh493_curva(es_base, es_stress, limite, halflife, orizzonte, t_rientro,
                passo=1.0, nome="curva"):
    """Traiettoria giornaliera: lista di (giorno, es_t, eccesso, cumulata)."""
    _n493 = mh493_orizzonte(orizzonte, nome)
    _p493 = mh493_num(passo, nome)
    if _p493 <= 0.0:
        raise ValueError(f"{nome}: passo positivo ({passo!r})")
    _t493 = 0.0
    _out493 = []
    while _t493 <= float(_n493) + 1e-9:
        _out493.append((_t493,
                        mh493_es_t(es_base, es_stress, _t493, halflife, nome),
                        mh493_eccesso_t(es_base, es_stress, limite, halflife,
                                        _t493, nome),
                        mh493_cumulata(es_base, es_stress, limite, halflife,
                                       t_rientro, _t493, nome)))
        _t493 += _p493
    return _out493


def mh493_verdetto(es_base, es_stress, limite, halflife, orizzonte, budget,
                   nome="verdetto"):
    """Verdetto operativo: codice + testo + numeri chiave."""
    _t493 = mh493_t_rientro(es_base, es_stress, limite, halflife, nome)
    _n493 = mh493_orizzonte(orizzonte, nome)
    _b493 = mh493_budget(budget, nome)
    _l493 = mh493_limite(limite, nome)
    if _t493 == 0.0:
        return {"codice": "OK_STRESS", "t_rientro_giorni": 0.0,
                "integrale_eur_giorni": 0.0, "giorni_equivalenti": 0.0,
                "frazione_budget": 0.0,
                "testo": ("NESSUN CONSUMO DI BUDGET — l'ES stressato resta "
                          "sotto il limite: non serve aspettare ne' coprire.")}
    if _t493 is None:
        return {"codice": "MAI", "t_rientro_giorni": None,
                "integrale_eur_giorni": None, "giorni_equivalenti": None,
                "frazione_budget": None,
                "testo": ("SFONDAMENTO STRUTTURALE — l'ES resta sopra il limite "
                          "anche a stress rientrato: l'attesa non basta mai, "
                          "il budget non c'entra (serve hedge o chiusura).")}
    _i493 = mh493_integrale_eccesso(es_base, es_stress, limite, halflife,
                                    _t493, nome)
    _neq493 = mh493_giorni_equivalenti(_i493, _l493, nome)
    _fr493 = mh493_frazione_budget(_i493, _b493, nome)
    _base493 = {"t_rientro_giorni": _t493, "integrale_eur_giorni": _i493,
                "giorni_equivalenti": _neq493, "frazione_budget": _fr493}
    if _t493 > float(_n493):
        _d493 = dict(_base493)
        _d493["codice"] = "OLTRE_ORIZZONTE"
        _d493["testo"] = (
            f"RIENTRO OLTRE L'ORIZZONTE ({_t493:,.0f} > {_n493} giorni): "
            f"l'attesa consumerebbe {_i493:,.0f} EUR*giorni "
            f"({_fr493:.1%} del budget) prima di rientrare — "
            "meglio valutare l'hedge immediato.")
        return _d493
    if _fr493 >= 1.0:
        _d493 = dict(_base493)
        _d493["codice"] = "BUDGET_SFONDATO"
        _d493["testo"] = (
            f"BUDGET SFONDATO — aspettare {_t493:,.1f} giorni consumerebbe "
            f"{_i493:,.0f} EUR*giorni ({_fr493:.1%} del budget mensile, "
            f"={_neq493:,.1f} giorni-equivalenti di limite): il budget non "
            "regge l'attesa, coprire subito.")
        return _d493
    if _fr493 >= 0.5:
        _d493 = dict(_base493)
        _d493["codice"] = "ELEVATO"
        _d493["testo"] = (
            f"ATTESA COSTOSA — {_t493:,.1f} giorni di attesa consumano "
            f"{_i493:,.0f} EUR*giorni ({_fr493:.1%} del budget, "
            f"={_neq493:,.1f} giorni-equivalenti): monitorare il decadimento "
            "della vol ed escalation se non rientra.")
        return _d493
    _d493 = dict(_base493)
    _d493["codice"] = "SOSTENIBILE"
    _d493["testo"] = (
        f"ATTESA SOSTENIBILE — {_t493:,.1f} giorni di attesa consumano solo "
        f"{_i493:,.0f} EUR*giorni ({_fr493:.1%} del budget mensile, "
        f"={_neq493:,.1f} giorni-equivalenti di limite): l'attesa conviene.")
    return _d493


