# W624 (21/10/2026) - tab624 "🧪⛽ Power-to-Methanol: il metanolo verde da CO₂ (sintesi catalitica)"
#
# Power-to-Methanol: CO2 + 3 H2 -> CH3OH + H2O (idrogenazione catalitica
# della CO2, analoga al processo di sintesi del metanolo a bassa pressione).
# L'H2 verde (il cui costo e' il LCOH di tab620) piu' CO2 catturata diventa
# e-metanolo: bunker fuel drop-in (vedi il confronto di tab595), feedstock
# chimico e carrier liquido dell'idrogeno (densita' energetica superiore
# all'ammoniaca). Decarbonizza il metanolo fossile da gas naturale (SMR +
# sintesi, ~0,8 tCO2/t). Domanda operativa: "produrre CH3OH verde costa
# meno del metanolo fossile piu' il carbonio che sposta?" Quarto pilastro
# della famiglia PtX dopo tab620 (LCOH), tab622 (metanazione) e tab623
# (Power-to-Ammonia).
#
#   kg_h2_annui    = portata_kg_h * ore_annue                  [kg/anno]
#   kg_co2_annue   = kg_h2 * 44,009 / 6,048                     [kg/anno]
#                    (stechiometria: 7,2766 kg CO2 per kg H2)
#   t_meoh_annue   = kg_h2 * 32,042 / 6,048 * eta / 1000        [t/anno]
#                    (5,2979 kg CH3OH per kg H2, x efficienza sintesi)
#   costo_h2       = kg_h2 * lcoh                              [eur/anno]
#   costo_co2      = t_co2 * prezzo_co2                         [eur/anno]
#                    (CO2 catturata: DAC o puntuale, in €/t)
#   costo_sintesi  = t_meoh * costo_loop                      [eur/anno]
#                    (capex annualizzato + opex del loop in €/t CH3OH)
#   costo_totale   = h2 + co2 + sintesi                        [eur/anno]
#   lcome          = costo_totale / t_meoh                     [eur/t CH3OH]
#                    (None se niente metanolo prodotto)
#   metanolo_spostato = t_meoh * prezzo_fossile                [eur/anno]
#                    (l'e-metanolo sostituisce 1:1 il metanolo fossile)
#   valore_co2     = t_meoh * ef_fossile * prezzo_ets          [eur/anno]
#   costo_netto    = totale - spostato - valore_co2            [eur/anno]
#                    (puo' essere negativo: allora l'e-metanolo rende)
#   benchmark      = prezzo_fossile + ef_fossile * prezzo_ets  [eur/t]
#   verdetto       = CONVIENTE      (lcome <= benchmark)
#                  / MARGINALE     (lcome <= benchmark * 1,15)
#                  / NON_CONVIENTE (oltre)
#                  / NON_CALCOLABILE (lcome None)
# Ipotesi: CO2 catturata con costo in €/t, niente costi di stoccaggio/
# distillazione del metanolo, screening preliminare come tab620-tab623.


def mh624_num(x, nome):
    """Valida un numero reale finito (bool e stringhe rifiutati)."""
    if isinstance(x, bool) or not isinstance(x, (int, float)):
        raise ValueError(f"{nome}: atteso numero, ricevuto {type(x).__name__}")
    v = float(x)
    if v != v or v in (float("inf"), float("-inf")):
        raise ValueError(f"{nome}: valore non finito")
    return v


def mh624_nneg(x, nome):
    """Numero finito non negativo."""
    v = mh624_num(x, nome)
    if v < 0.0:
        raise ValueError(f"{nome}: atteso >= 0, ricevuto {v}")
    return v


def mh624_pos(x, nome):
    """Numero finito strettamente positivo."""
    v = mh624_num(x, nome)
    if v <= 0.0:
        raise ValueError(f"{nome}: atteso > 0, ricevuto {v}")
    return v


def mh624_frac01(x, nome):
    """Frazione in [0, 1]."""
    v = mh624_num(x, nome)
    if v < 0.0 or v > 1.0:
        raise ValueError(f"{nome}: atteso in [0, 1], ricevuto {v}")
    return v


def mh624_kg_h2_annui(portata_kg_h, ore_annue):
    """kg/anno di H2 in ingresso al loop di sintesi: portata x ore."""
    return mh624_pos(portata_kg_h, "portata_kg_h") * \
        mh624_pos(ore_annue, "ore_annue")


def mh624_kg_co2_annue(kg_h2_annui):
    """kg/anno di CO2: 44,009 / (3 x 2,016) = 7,2766 kg CO2 per kg H2."""
    kg = mh624_nneg(kg_h2_annui, "kg_h2_annui")
    return kg * 44.009 / (3.0 * 2.016)


def mh624_t_meoh_annue(kg_h2_annui, eta_sintesi):
    """t/anno di CH3OH: 32,042 / (3 x 2,016) = 5,2979 kg metanolo per
    kg H2, x efficienza di conversione del loop, in tonnellate."""
    kg = mh624_nneg(kg_h2_annui, "kg_h2_annui")
    eta = mh624_frac01(eta_sintesi, "eta_sintesi")
    return kg * 32.042 / (3.0 * 2.016) * eta / 1000.0


def mh624_costo_h2(kg_h2_annui, lcoh_eur_kg):
    """Costo annuo dell'idrogeno: kg x LCOH (€/kg)."""
    return mh624_nneg(kg_h2_annui, "kg_h2_annui") * \
        mh624_nneg(lcoh_eur_kg, "lcoh_eur_kg")


def mh624_costo_co2(kg_co2_annue, prezzo_co2_eur_t):
    """Costo annuo della CO2 catturata: t x €/t."""
    return mh624_nneg(kg_co2_annue, "kg_co2_annue") / 1000.0 * \
        mh624_nneg(prezzo_co2_eur_t, "prezzo_co2_eur_t")


def mh624_costo_sintesi(t_meoh_annue, costo_loop_eur_t):
    """Costo annuo del loop di sintesi (capex annualizzato + opex in
    €/t CH3OH): t x €/t."""
    return mh624_nneg(t_meoh_annue, "t_meoh_annue") * \
        mh624_nneg(costo_loop_eur_t, "costo_loop_eur_t")


def mh624_costo_totale(costo_h2, costo_co2, costo_sintesi):
    """Costo annuo totale dell'e-metanolo: H2 + CO2 + sintesi."""
    return mh624_num(costo_h2, "costo_h2") + \
        mh624_num(costo_co2, "costo_co2") + \
        mh624_num(costo_sintesi, "costo_sintesi")


def mh624_lcome(costo_totale, t_meoh_annue):
    """LCoMe (€/t di metanolo): costo totale diviso tonnellate prodotte.
    None se niente metanolo prodotto (il costo per tonnellata non esiste)."""
    t = mh624_nneg(t_meoh_annue, "t_meoh_annue")
    if t == 0.0:
        return None
    return mh624_num(costo_totale, "costo_totale") / t


def mh624_metanolo_spostato(t_meoh_annue, prezzo_fossile_eur_t):
    """Valore del metanolo fossile sostituito 1:1 (€/anno)."""
    return mh624_nneg(t_meoh_annue, "t_meoh_annue") * \
        mh624_nneg(prezzo_fossile_eur_t, "prezzo_fossile_eur_t")


def mh624_valore_co2(t_meoh_annue, ef_fossile_tco2_t, prezzo_ets_eur_t):
    """CO2 valorizzata all'ETS: l'e-metanolo sposta fossile al suo fattore
    di emissione (~0,8 tCO2/t da gas naturale)."""
    return mh624_nneg(t_meoh_annue, "t_meoh_annue") * \
        mh624_nneg(ef_fossile_tco2_t, "ef_fossile_tco2_t") * \
        mh624_nneg(prezzo_ets_eur_t, "prezzo_ets_eur_t")


def mh624_costo_netto(costo_totale, metanolo_spostato, valore_co2):
    """Costo aggiuntivo annuo: e-metanolo pagato meno fossile risparmiato
    e CO2 valorizzata (puo' essere negativo: allora l'e-metanolo rende)."""
    return mh624_num(costo_totale, "costo_totale") - \
        mh624_num(metanolo_spostato, "metanolo_spostato") - \
        mh624_num(valore_co2, "valore_co2")


def mh624_benchmark(prezzo_fossile_eur_t, ef_fossile_tco2_t,
                    prezzo_ets_eur_t):
    """Costo evitato per tonnellata: metanolo fossile + CO2 all'ETS (€/t)."""
    return mh624_nneg(prezzo_fossile_eur_t, "prezzo_fossile_eur_t") + \
        mh624_nneg(ef_fossile_tco2_t, "ef_fossile_tco2_t") * \
        mh624_nneg(prezzo_ets_eur_t, "prezzo_ets_eur_t")


def mh624_verdetto(lcome, benchmark_eur_t):
    """CONVIENTE se il LCoMe non supera il benchmark (fossile + CO2/ETS),
    MARGINALE entro +15 %, NON_CONVIENTE oltre, NON_CALCOLABILE se il
    LCoMe e' None."""
    bm = mh624_nneg(benchmark_eur_t, "benchmark_eur_t")
    if lcome is None:
        return {"lcome": None, "verdetto": "NON_CALCOLABILE",
                "msg": "nessun metanolo prodotto: il LCoMe non e' "
                       "calcolabile"}
    l = mh624_num(lcome, "lcome")
    if l <= bm:
        v = "CONVIENTE"
        msg = (f"LCoMe € {l:,.0f}/t contro benchmark € {bm:,.0f}/t "
               "(fossile + CO2 all'ETS): l'e-metanolo regge")
    elif l <= bm * 1.15:
        v = "MARGINALE"
        sopra = (l / bm - 1.0) * 100.0
        msg = (f"LCoMe € {l:,.0f}/t sopra il benchmark del {sopra:,.1f} % "
               "(entro il 15 %): dipende dal prezzo futuro di H2/CO2")
    else:
        v = "NON_CONVIENTE"
        msg = (f"LCoMe € {l:,.0f}/t contro benchmark € {bm:,.0f}/t: "
               "con queste ipotesi il Power-to-Methanol non regge")
    return {"lcome": l, "benchmark_eur_t": bm, "verdetto": v, "msg": msg}


def mh624_sensibilita(portata_kg_h, ore_annue, eta_sintesi,
                      prezzo_co2_eur_t, costo_loop_eur_t,
                      prezzo_fossile_eur_t, ef_fossile_tco2_t,
                      lcoh_list, ets_list):
    """Griglia 2D: LCoMe al variare del LCOH dell'H2 e del prezzo ETS
    (le due leve che contano davvero: l'H2 e' ~73 % del costo del loop)."""
    if not lcoh_list:
        raise ValueError("lcoh_list: lista vuota")
    if not ets_list:
        raise ValueError("ets_list: lista vuota")
    kg = mh624_kg_h2_annui(portata_kg_h, ore_annue)
    kg_co2 = mh624_kg_co2_annue(kg)
    meoh = mh624_t_meoh_annue(kg, eta_sintesi)
    co2 = mh624_costo_co2(kg_co2, prezzo_co2_eur_t)
    sin = mh624_costo_sintesi(meoh, costo_loop_eur_t)
    spost = mh624_metanolo_spostato(meoh, prezzo_fossile_eur_t)
    rows = []
    for lc in lcoh_list:
        for pe in ets_list:
            lc_v = mh624_nneg(lc, "lcoh_eur_kg")
            pe_v = mh624_nneg(pe, "prezzo_ets")
            h2 = mh624_costo_h2(kg, lc_v)
            tot = mh624_costo_totale(h2, co2, sin)
            lcome = mh624_lcome(tot, meoh)
            bm = mh624_benchmark(prezzo_fossile_eur_t, ef_fossile_tco2_t,
                                 pe_v)
            val = mh624_valore_co2(meoh, ef_fossile_tco2_t, pe_v)
            ver = mh624_verdetto(lcome, bm)
            rows.append({"lcoh_eur_kg": lc_v, "ets_eur_t": pe_v,
                         "meoh_t_annue": meoh,
                         "costo_netto": mh624_costo_netto(tot, spost, val),
                         "lcome": lcome, "benchmark": bm,
                         "giudizio": ver["verdetto"]})
    return rows


def mh624_demo():
    """Demo: 100 kg/h per 4000 ore/anno -> 400.000 kg H2; stechiometria ->
    2.910,65 t CO2; eta 90 % -> 1.907,26 t CH3OH/anno; LCOH 5,13 -> H2
    2.052.000; CO2 a 100 €/t -> 291.064,81; sintesi 250 €/t ->
    476.815,48; totale 2.819.880,29; LCoMe 1.478,4966259562 €/t contro
    benchmark 680 (fossile 600 + 0,8 x ETS 100) -> NON_CONVIENTE;
    metanolo spostato 1.144.357,14, CO2 valorizzata 152.580,95, netto
    1.522.942,20 €/anno."""
    return {"portata_kg_h": 100.0, "ore_annue": 4000.0,
            "lcoh_eur_kg": 5.13, "eta_sintesi": 0.90,
            "prezzo_co2_eur_t": 100.0,
            "costo_loop_eur_t": 250.0,
            "prezzo_fossile_eur_t": 600.0, "ef_fossile_tco2_t": 0.8,
            "prezzo_ets_eur_t": 100.0}


# W623 (21/10/2026) - tab623 "⚗️💚 Power-to-Ammonia: l'ammoniaca verde da H2 (Haber-Bosch)"
#
# Power-to-Ammonia: 3 H2 + N2 -> 2 NH3 (Haber-Bosch). L'H2 verde (il cui
# costo e' il LCOH di tab620) piu' N2 da separazione dell'aria diventa
# ammoniaca verde, carrier dell'idrogeno trasportabile in nave e
# feedstock per fertilizzanti, decarbonizzando l'ammoniaca grigia
# (SMR + Haber-Bosch, ~1,8 tCO2/t). Domanda operativa: "produrre NH3
# verde costa meno dell'ammoniaca fossile piu' il carbonio che sposta?"
# Terzo pilastro della famiglia PtX dopo tab622 (metanazione).
#
#   kg_h2_annui    = portata_kg_h * ore_annue                  [kg/anno]
#   n2_t_annue     = kg_h2 * 28,014 / 6,048 / 1000             [t/anno]
#                    (stechiometria: 4,6319 kg N2 per kg H2)
#   nh3_t_annue    = kg_h2 * 34,062 / 6,048 * eta / 1000       [t/anno]
#                    (5,6319 kg NH3 per kg H2, x efficienza sintesi)
#   costo_h2       = kg_h2 * lcoh                              [eur/anno]
#   costo_n2       = n2_t * prezzo_n2                           [eur/anno]
#   costo_sintesi  = nh3_t * costo_haber_bosch                 [eur/anno]
#                    (capex annualizzato + opex del loop in €/t NH3)
#   costo_totale   = h2 + n2 + sintesi                         [eur/anno]
#   lcoa           = costo_totale / nh3_t                      [eur/t NH3]
#                    (None se niente NH3 prodotta)
#   ammoniaca_spostata = nh3_t * prezzo_fossile                [eur/anno]
#                    (l'NH3 verde sostituisce 1:1 l'ammoniaca grigia)
#   valore_co2     = nh3_t * ef_grigia * prezzo_ets            [eur/anno]
#   costo_netto    = totale - spostata - valore_co2            [eur/anno]
#                    (puo' essere negativo: allora l'NH3 verde rende)
#   benchmark      = prezzo_fossile + ef_grigia * prezzo_ets   [eur/t]
#   verdetto       = CONVIENTE      (lcoa <= benchmark)
#                  / MARGINALE     (lcoa <= benchmark * 1,15)
#                  / NON_CONVIENTE (oltre)
#                  / NON_CALCOLABILE (lcoa None)
# Ipotesi: N2 da ASU con costo in €/t, niente costi di stoccaggio/
# liquefazione NH3, screening preliminare come tab620-tab622.


def mh623_num(x, nome):
    """Valida un numero reale finito (bool e stringhe rifiutati)."""
    if isinstance(x, bool) or not isinstance(x, (int, float)):
        raise ValueError(f"{nome}: atteso numero, ricevuto {type(x).__name__}")
    v = float(x)
    if v != v or v in (float("inf"), float("-inf")):
        raise ValueError(f"{nome}: valore non finito")
    return v


def mh623_nneg(x, nome):
    """Numero finito non negativo."""
    v = mh623_num(x, nome)
    if v < 0.0:
        raise ValueError(f"{nome}: atteso >= 0, ricevuto {v}")
    return v


def mh623_pos(x, nome):
    """Numero finito strettamente positivo."""
    v = mh623_num(x, nome)
    if v <= 0.0:
        raise ValueError(f"{nome}: atteso > 0, ricevuto {v}")
    return v


def mh623_frac01(x, nome):
    """Frazione in [0, 1]."""
    v = mh623_num(x, nome)
    if v < 0.0 or v > 1.0:
        raise ValueError(f"{nome}: atteso in [0, 1], ricevuto {v}")
    return v


def mh623_kg_h2_annui(portata_kg_h, ore_annue):
    """kg/anno di H2 in ingresso al loop Haber-Bosch: portata x ore."""
    return mh623_pos(portata_kg_h, "portata_kg_h") * \
        mh623_pos(ore_annue, "ore_annue")


def mh623_kg_n2_annue(kg_h2_annui):
    """kg/anno di N2: 28,014 / (3 x 2,016) = 4,6319 kg N2 per kg H2."""
    kg = mh623_nneg(kg_h2_annui, "kg_h2_annui")
    return kg * 28.014 / (3.0 * 2.016)


def mh623_t_nh3_annue(kg_h2_annui, eta_sintesi):
    """t/anno di NH3: 2 x 17,031 / (3 x 2,016) = 5,6319 kg NH3 per kg H2,
    x efficienza di conversione del loop, in tonnellate."""
    kg = mh623_nneg(kg_h2_annui, "kg_h2_annui")
    eta = mh623_frac01(eta_sintesi, "eta_sintesi")
    return kg * (2.0 * 17.031) / (3.0 * 2.016) * eta / 1000.0


def mh623_costo_h2(kg_h2_annui, lcoh_eur_kg):
    """Costo annuo dell'idrogeno: kg x LCOH (€/kg)."""
    return mh623_nneg(kg_h2_annui, "kg_h2_annui") * \
        mh623_nneg(lcoh_eur_kg, "lcoh_eur_kg")


def mh623_costo_n2(kg_n2_annui, prezzo_n2_eur_t):
    """Costo annuo dell'azoto da ASU: t x €/t."""
    return mh623_nneg(kg_n2_annui, "kg_n2_annui") / 1000.0 * \
        mh623_nneg(prezzo_n2_eur_t, "prezzo_n2_eur_t")


def mh623_costo_sintesi(t_nh3_annue, costo_haber_bosch_eur_t):
    """Costo annuo del loop Haber-Bosch (capex annualizzato + opex in
    €/t NH3): t x €/t."""
    return mh623_nneg(t_nh3_annue, "t_nh3_annue") * \
        mh623_nneg(costo_haber_bosch_eur_t, "costo_haber_bosch_eur_t")


def mh623_costo_totale(costo_h2, costo_n2, costo_sintesi):
    """Costo annuo totale dell'ammoniaca verde: H2 + N2 + sintesi."""
    return mh623_num(costo_h2, "costo_h2") + \
        mh623_num(costo_n2, "costo_n2") + \
        mh623_num(costo_sintesi, "costo_sintesi")


def mh623_lcoa(costo_totale, t_nh3_annue):
    """LCoA (€/t di NH3): costo totale diviso tonnellate prodotte.
    None se niente ammoniaca prodotta (il costo per tonnellata non esiste)."""
    t = mh623_nneg(t_nh3_annue, "t_nh3_annue")
    if t == 0.0:
        return None
    return mh623_num(costo_totale, "costo_totale") / t


def mh623_ammoniaca_spostata(t_nh3_annue, prezzo_fossile_eur_t):
    """Valore dell'ammoniaca grigia sostituita 1:1 (€/anno)."""
    return mh623_nneg(t_nh3_annue, "t_nh3_annue") * \
        mh623_nneg(prezzo_fossile_eur_t, "prezzo_fossile_eur_t")


def mh623_valore_co2(t_nh3_annue, ef_grigia_tco2_t, prezzo_ets_eur_t):
    """CO2 valorizzata all'ETS: l'NH3 verde sposta grigia al suo fattore
    di emissione (~1,8 tCO2/t da SMR)."""
    return mh623_nneg(t_nh3_annue, "t_nh3_annue") * \
        mh623_nneg(ef_grigia_tco2_t, "ef_grigia_tco2_t") * \
        mh623_nneg(prezzo_ets_eur_t, "prezzo_ets_eur_t")


def mh623_costo_netto(costo_totale, ammoniaca_spostata, valore_co2):
    """Costo aggiuntivo annuo: NH3 verde pagata meno fossile risparmiata
    e CO2 valorizzata (puo' essere negativo: allora l'NH3 verde rende)."""
    return mh623_num(costo_totale, "costo_totale") - \
        mh623_num(ammoniaca_spostata, "ammoniaca_spostata") - \
        mh623_num(valore_co2, "valore_co2")


def mh623_benchmark(prezzo_fossile_eur_t, ef_grigia_tco2_t, prezzo_ets_eur_t):
    """Costo evitato per tonnellata: ammoniaca grigia + CO2 all'ETS (€/t)."""
    return mh623_nneg(prezzo_fossile_eur_t, "prezzo_fossile_eur_t") + \
        mh623_nneg(ef_grigia_tco2_t, "ef_grigia_tco2_t") * \
        mh623_nneg(prezzo_ets_eur_t, "prezzo_ets_eur_t")


def mh623_verdetto(lcoa, benchmark_eur_t):
    """CONVIENTE se il LCoA non supera il benchmark (fossile + CO2/ETS),
    MARGINALE entro +15 %, NON_CONVIENTE oltre, NON_CALCOLABILE se il
    LCoA e' None."""
    bm = mh623_nneg(benchmark_eur_t, "benchmark_eur_t")
    if lcoa is None:
        return {"lcoa": None, "verdetto": "NON_CALCOLABILE",
                "msg": "nessuna NH3 prodotta: il LCoA non e' calcolabile"}
    l = mh623_num(lcoa, "lcoa")
    if l <= bm:
        v = "CONVIENTE"
        msg = (f"LCoA € {l:,.0f}/t contro benchmark € {bm:,.0f}/t "
               "(grigia + CO2 all'ETS): l'ammoniaca verde regge")
    elif l <= bm * 1.15:
        v = "MARGINALE"
        sopra = (l / bm - 1.0) * 100.0
        msg = (f"LCoA € {l:,.0f}/t sopra il benchmark del {sopra:,.1f} % "
               "(entro il 15 %): dipende dal prezzo futuro del gas/CO2")
    else:
        v = "NON_CONVIENTE"
        msg = (f"LCoA € {l:,.0f}/t contro benchmark € {bm:,.0f}/t: "
               "con queste ipotesi il Power-to-Ammonia non regge")
    return {"lcoa": l, "benchmark_eur_t": bm, "verdetto": v, "msg": msg}


def mh623_sensibilita(portata_kg_h, ore_annue, eta_sintesi,
                      prezzo_n2_eur_t, costo_haber_bosch_eur_t,
                      prezzo_fossile_eur_t, ef_grigia_tco2_t,
                      lcoh_list, ets_list):
    """Griglia 2D: LCoA al variare del LCOH dell'H2 e del prezzo ETS
    (le due leve che contano davvero: l'H2 e' ~84 % del costo del loop)."""
    if not lcoh_list:
        raise ValueError("lcoh_list: lista vuota")
    if not ets_list:
        raise ValueError("ets_list: lista vuota")
    kg = mh623_kg_h2_annui(portata_kg_h, ore_annue)
    kg_n2 = mh623_kg_n2_annue(kg)
    nh3 = mh623_t_nh3_annue(kg, eta_sintesi)
    n2 = mh623_costo_n2(kg_n2, prezzo_n2_eur_t)
    sin = mh623_costo_sintesi(nh3, costo_haber_bosch_eur_t)
    spost = mh623_ammoniaca_spostata(nh3, prezzo_fossile_eur_t)
    rows = []
    for lc in lcoh_list:
        for pe in ets_list:
            lc_v = mh623_nneg(lc, "lcoh_eur_kg")
            pe_v = mh623_nneg(pe, "prezzo_ets")
            h2 = mh623_costo_h2(kg, lc_v)
            tot = mh623_costo_totale(h2, n2, sin)
            lcoa = mh623_lcoa(tot, nh3)
            bm = mh623_benchmark(prezzo_fossile_eur_t, ef_grigia_tco2_t,
                                 pe_v)
            val = mh623_valore_co2(nh3, ef_grigia_tco2_t, pe_v)
            ver = mh623_verdetto(lcoa, bm)
            rows.append({"lcoh_eur_kg": lc_v, "ets_eur_t": pe_v,
                         "nh3_t_annue": nh3,
                         "costo_netto": mh623_costo_netto(tot, spost, val),
                         "lcoa": lcoa, "benchmark": bm,
                         "giudizio": ver["verdetto"]})
    return rows


def mh623_demo():
    """Demo: 100 kg/h per 4000 ore/anno -> 400.000 kg H2; stechiometria ->
    1.852,78 t N2; eta 92 % -> 2.072,56 t NH3/anno; LCOH 5,13 -> H2
    2.052.000; N2 a 50 €/t -> 92.638,89; sintesi 150 €/t -> 310.883,33;
    totale 2.455.522,22; LCoA 1.184,77992816169 €/t contro benchmark 980
    (fossile 800 + 1,8 x ETS 100) -> NON_CONVIENTE; ammoniaca spostata
    1.658.044,44, CO2 valorizzata 373.060,00, netto 424.417,78 €/anno."""
    return {"portata_kg_h": 100.0, "ore_annue": 4000.0,
            "lcoh_eur_kg": 5.13, "eta_sintesi": 0.92,
            "prezzo_n2_eur_t": 50.0,
            "costo_haber_bosch_eur_t": 150.0,
            "prezzo_fossile_eur_t": 800.0, "ef_grigia_tco2_t": 1.8,
            "prezzo_ets_eur_t": 100.0}


# W622 (21/10/2026) - tab622 "🔥⛽ Metanazione (Power-to-Methane): il metano sintetico da CO2 catturata"
#
# Metanazione (Sabatier): 4 H2 + CO2 -> CH4 + 2 H2O. L'H2 verde (il cui
# costo e' il LCOH di tab620) piu' CO2 catturata diventa metano sintetico
# (SNG) drop-in nella rete gas: niente limiti di blend (tab621) perche' il
# CH4 e' indistinguibile dal gas fossile. Domanda operativa: "produrre SNG
# dall'H2 costa meno del gas fossile piu' il carbonio che sposta?"
# Complementa tab620 (LCOH) e tab621 (blending): quella costa la
# produzione, questa il destino chimico dell'H2 in metano.
#
#   kg_annui       = portata_kg_h * ore_annue                    [kg/anno]
#   co2_t          = kg_annui * 44,01 / (4 * 2,016) / 1000       [tCO2/anno]
#                    (stechiometria: 5,4576 kg CO2 per kg H2)
#   sng_mwh        = kg_annui * 33,33 / 1000 * eta               [MWh/anno]
#                    (LHV H2 x efficienza di metanazione)
#   costo_h2       = kg_annui * lcoh                             [eur/anno]
#   costo_co2      = co2_t * prezzo_co2                          [eur/anno]
#   costo_met      = sng_mwh * costo_metanazione                 [eur/MWh]
#   costo_totale   = h2 + co2 + met                              [eur/anno]
#   lcom           = costo_totale / sng_mwh                      [eur/MWh]
#                    (None se sng_mwh = 0: niente metano da costare)
#   gas_evitato    = sng_mwh * prezzo_gas                        [eur/anno]
#   valore_co2     = sng_mwh * ef_gas * prezzo_ets                [eur/anno]
#                    (il SNG da H2 verde + CO2 non fossile sposta gas
#                    fossile 1:1 in LHV)
#   costo_netto    = totale - gas_evitato - valore_co2          [eur/anno]
#   benchmark      = prezzo_gas + ef_gas * prezzo_ets            [eur/MWh]
#   verdetto       = CONVIENTE      (lcom <= benchmark)
#                  / MARGINALE     (lcom <= benchmark * 1,15)
#                  / NON_CONVIENTE (oltre)
#                  / NON_CALCOLABILE (lcom None)
# Ipotesi: CO2 biogenica o da DAC (non fossile: il CH4 bruciato riemette
# solo la CO2 gia' catturata), niente costi di adeguamento della rete,
# screening preliminare come tab620/tab621.


def mh622_num(x, nome):
    """Valida un numero reale finito (bool e stringhe rifiutati)."""
    if isinstance(x, bool) or not isinstance(x, (int, float)):
        raise ValueError(f"{nome}: atteso numero, ricevuto {type(x).__name__}")
    v = float(x)
    if v != v or v in (float("inf"), float("-inf")):
        raise ValueError(f"{nome}: valore non finito")
    return v


def mh622_nneg(x, nome):
    """Numero finito non negativo."""
    v = mh622_num(x, nome)
    if v < 0.0:
        raise ValueError(f"{nome}: atteso >= 0, ricevuto {v}")
    return v


def mh622_pos(x, nome):
    """Numero finito strettamente positivo."""
    v = mh622_num(x, nome)
    if v <= 0.0:
        raise ValueError(f"{nome}: atteso > 0, ricevuto {v}")
    return v


def mh622_frac01(x, nome):
    """Frazione in [0, 1]."""
    v = mh622_num(x, nome)
    if v < 0.0 or v > 1.0:
        raise ValueError(f"{nome}: atteso in [0, 1], ricevuto {v}")
    return v


def mh622_kg_annui(portata_kg_h, ore_annue):
    """kg/anno di H2 in ingresso al metanatore: portata x ore annue."""
    return mh622_pos(portata_kg_h, "portata_kg_h") * \
        mh622_pos(ore_annue, "ore_annue")


def mh622_co2_tco2_annue(kg_annui):
    """tCO2/anno richieste: 5,4576 kg CO2 per kg H2 (44,01 / (4 x 2,016))."""
    kg = mh622_nneg(kg_annui, "kg_annui")
    return kg * 44.01 / (4.0 * 2.016) / 1000.0


def mh622_energia_sng_mwh(kg_annui, eta_metanazione):
    """MWh/anno di SNG (LHV): 1 kg H2 = 33,33 kWh, x efficienza."""
    kg = mh622_nneg(kg_annui, "kg_annui")
    eta = mh622_frac01(eta_metanazione, "eta_metanazione")
    return kg * 33.33 / 1000.0 * eta


def mh622_costo_h2(kg_annui, lcoh_eur_kg):
    """Costo annuo dell'idrogeno: kg x LCOH (€/kg)."""
    return mh622_nneg(kg_annui, "kg_annui") * \
        mh622_nneg(lcoh_eur_kg, "lcoh_eur_kg")


def mh622_costo_co2(tco2_annue, prezzo_co2_eur_t):
    """Costo annuo della CO2 catturata: t x €/t (biogenica ~50-100, DAC più)."""
    return mh622_nneg(tco2_annue, "tco2_annue") * \
        mh622_nneg(prezzo_co2_eur_t, "prezzo_co2_eur_t")


def mh622_costo_metanazione(sng_mwh, costo_eur_mwh):
    """Costo annuo di metanazione (capex annualizzato + opex in €/MWh SNG)."""
    return mh622_nneg(sng_mwh, "sng_mwh") * \
        mh622_nneg(costo_eur_mwh, "costo_eur_mwh")


def mh622_costo_totale(costo_h2, costo_co2, costo_metanazione):
    """Costo annuo totale del SNG: H2 + CO2 + metanazione."""
    return mh622_num(costo_h2, "costo_h2") + \
        mh622_num(costo_co2, "costo_co2") + \
        mh622_num(costo_metanazione, "costo_metanazione")


def mh622_lcom(costo_totale, sng_mwh):
    """LCoM (€/MWh di SNG): costo totale diviso energia prodotta.
    None se niente metano prodotto (il costo per MWh non esiste)."""
    mwh = mh622_nneg(sng_mwh, "sng_mwh")
    if mwh == 0.0:
        return None
    return mh622_num(costo_totale, "costo_totale") / mwh


def mh622_gas_evitato(sng_mwh, prezzo_gas_eur_mwh):
    """Valore del gas fossile sostituito (1:1 in LHV)."""
    return mh622_nneg(sng_mwh, "sng_mwh") * \
        mh622_nneg(prezzo_gas_eur_mwh, "prezzo_gas_eur_mwh")


def mh622_valore_co2(sng_mwh, ef_gas_tco2_mwh, prezzo_ets_eur_t):
    """CO2 valorizzata all'ETS: il SNG sposta gas fossile al suo EF."""
    return mh622_nneg(sng_mwh, "sng_mwh") * \
        mh622_nneg(ef_gas_tco2_mwh, "ef_gas_tco2_mwh") * \
        mh622_nneg(prezzo_ets_eur_t, "prezzo_ets_eur_t")


def mh622_costo_netto(costo_totale, gas_evitato, valore_co2):
    """Costo aggiuntivo annuo: SNG pagato meno gas risparmiato e CO2
    valorizzata (puo' essere negativo: allora il SNG rende da solo)."""
    return mh622_num(costo_totale, "costo_totale") - \
        mh622_num(gas_evitato, "gas_evitato") - \
        mh622_num(valore_co2, "valore_co2")


def mh622_benchmark(prezzo_gas_eur_mwh, ef_gas_tco2_mwh, prezzo_ets_eur_t):
    """Costo evitato per MWh: gas fossile + CO2 all'ETS (€/MWh)."""
    return mh622_nneg(prezzo_gas_eur_mwh, "prezzo_gas_eur_mwh") + \
        mh622_nneg(ef_gas_tco2_mwh, "ef_gas_tco2_mwh") * \
        mh622_nneg(prezzo_ets_eur_t, "prezzo_ets_eur_t")


def mh622_verdetto(lcom, benchmark_eur_mwh):
    """CONVIENTE se il LCoM non supera il benchmark (gas + CO2/ETS),
    MARGINALE entro +15 %, NON_CONVIENTE oltre, NON_CALCOLABILE se il
    LCoM e' None."""
    bm = mh622_nneg(benchmark_eur_mwh, "benchmark_eur_mwh")
    if lcom is None:
        return {"lcom": None, "verdetto": "NON_CALCOLABILE",
                "msg": "nessun SNG prodotto: il LCoM non e' calcolabile"}
    l = mh622_num(lcom, "lcom")
    if l <= bm:
        v = "CONVIENTE"
        msg = (f"LCoM € {l:,.2f}/MWh contro benchmark € {bm:,.2f}/MWh "
               "(gas + CO2 all'ETS): il metano sintetico regge")
    elif l <= bm * 1.15:
        v = "MARGINALE"
        sopra = (l / bm - 1.0) * 100.0
        msg = (f"LCoM € {l:,.2f}/MWh sopra il benchmark del {sopra:,.1f} % "
               "(entro il 15 %): dipende dal prezzo futuro del gas/CO2")
    else:
        v = "NON_CONVIENTE"
        msg = (f"LCoM € {l:,.2f}/MWh contro benchmark € {bm:,.2f}/MWh: "
               "con queste ipotesi la metanazione non regge")
    return {"lcom": l, "benchmark_eur_mwh": bm, "verdetto": v, "msg": msg}


def mh622_sensibilita(portata_kg_h, ore_annue, eta_metanazione,
                      prezzo_co2_eur_t, costo_metanazione_eur_mwh,
                      prezzo_gas_eur_mwh, ef_gas_tco2_mwh,
                      lcoh_list, ets_list):
    """Griglia 2D: LCoM al variare del LCOH dell'H2 e del prezzo ETS
    (le due leve che contano davvero; la metanazione e' un moltiplicatore
    di entrambi)."""
    if not lcoh_list:
        raise ValueError("lcoh_list: lista vuota")
    if not ets_list:
        raise ValueError("ets_list: lista vuota")
    kg = mh622_kg_annui(portata_kg_h, ore_annue)
    sng = mh622_energia_sng_mwh(kg, eta_metanazione)
    tco2 = mh622_co2_tco2_annue(kg)
    co2 = mh622_costo_co2(tco2, prezzo_co2_eur_t)
    met = mh622_costo_metanazione(sng, costo_metanazione_eur_mwh)
    gas_ev = mh622_gas_evitato(sng, prezzo_gas_eur_mwh)
    rows = []
    for lc in lcoh_list:
        for pe in ets_list:
            lc_v = mh622_nneg(lc, "lcoh_eur_kg")
            pe_v = mh622_nneg(pe, "prezzo_ets")
            h2 = mh622_costo_h2(kg, lc_v)
            tot = mh622_costo_totale(h2, co2, met)
            lcom = mh622_lcom(tot, sng)
            bm = mh622_benchmark(prezzo_gas_eur_mwh, ef_gas_tco2_mwh, pe_v)
            val = mh622_valore_co2(sng, ef_gas_tco2_mwh, pe_v)
            ver = mh622_verdetto(lcom, bm)
            rows.append({"lcoh_eur_kg": lc_v, "ets_eur_t": pe_v,
                         "kg_annui": kg, "sng_mwh": sng,
                         "tco2_richieste": tco2,
                         "costo_netto": mh622_costo_netto(tot, gas_ev, val),
                         "lcom": lcom, "benchmark": bm,
                         "giudizio": ver["verdetto"]})
    return rows


def mh622_demo():
    """Demo: 100 kg/h per 4000 ore/anno -> 400.000 kg H2; stechiometria ->
    2.183,04 tCO2 catturate; eta 78 % -> 10.398,96 MWh SNG; LCOH 5,13 ->
    H2 2.052.000; CO2 a 100 €/t -> 218.303,57; metanazione 25 €/MWh ->
    259.974,00; totale 2.530.277,57; LCoM 243,3202523549058 €/MWh contro
    benchmark 70,2 (gas 50 + 0,202 x ETS 100) -> NON_CONVIENTE;
    gas evitato 519.948,00, CO2 valorizzata 210.058,99, netto
    1.800.270,58 €/anno."""
    return {"portata_kg_h": 100.0, "ore_annue": 4000.0,
            "lcoh_eur_kg": 5.13, "eta_metanazione": 0.78,
            "prezzo_co2_eur_t": 100.0,
            "costo_metanazione_eur_mwh": 25.0,
            "prezzo_gas_eur_mwh": 50.0, "ef_gas_tco2_mwh": 0.202,
            "prezzo_ets_eur_t": 100.0}


# W621 (21/10/2026) - tab621 "💧⚗️ Blending idrogeno in rete gas: il premium per decarbonizzare"
#
# Blending H2 in rete gas: business case deterministico dell'immissione
# di idrogeno verde nella rete gas a una quota volumetrica (drop-in
# senza cambiare bruciatori). Domanda operativa: "il premium pagato per
# l'H2 verde, al netto del gas risparmiato e della CO2 valorizzata,
# conviene rispetto al prezzo ETS?" Complementa tab620 (LCOH): quello
# quantifica il costo di produzione, questa il destino in rete del gas.
#
#   kg_annui       = portata_kg_h * ore_annue                    [kg/anno]
#   nm3_h2         = kg_annui * 11,12                            [Nm3/anno]
#   energia_mwh    = kg_annui * 33,33 / 1000   (LHV H2)          [MWh/anno]
#   tco2_evitate   = energia_mwh * ef_tco2_mwh                   [tCO2/anno]
#   costo_h2       = kg_annui * lcoh                             [eur/anno]
#   gas_evitato    = energia_mwh * prezzo_gas                    [eur/anno]
#   valore_co2     = tco2_evitate * prezzo_co2                   [eur/anno]
#   costo_netto    = costo_h2 - gas_evitato - valore_co2         [eur/anno]
#   mac            = costo_netto / tco2_evitate                  [eur/tCO2]
#                    (None se tCO2 = 0: nessun abbatimento da pagare)
#   quota_blend_%  = nm3_h2 / (nm3_h2 + gas_msm3 * 1e6) * 100    [% vol]
#   verdetto       = CONVIENTE      (mac <= prezzo_co2)
#                  / MARGINALE     (mac <= prezzo_co2 * 1,15)
#                  / NON_CONVIENTE (oltre)
#                  / NON_CALCOLABILE (mac None)
# Ipotesi: sostituzione energetica 1:1 in LHV (H2 e gas naturale hanno
# efficienze di combustione comparabili in miscela), fattore di emissione
# del gas naturale di default 0,202 tCO2/MWh, niente costi di adeguamento
# della rete (compressione, blending station) — screening preliminare.


def mh621_num(x, nome):
    """Valida un numero reale finito (bool e stringhe rifiutati)."""
    if isinstance(x, bool) or not isinstance(x, (int, float)):
        raise ValueError(f"{nome}: atteso numero, ricevuto {type(x).__name__}")
    v = float(x)
    if v != v or v in (float("inf"), float("-inf")):
        raise ValueError(f"{nome}: valore non finito")
    return v


def mh621_nneg(x, nome):
    """Numero finito non negativo."""
    v = mh621_num(x, nome)
    if v < 0.0:
        raise ValueError(f"{nome}: atteso >= 0, ricevuto {v}")
    return v


def mh621_pos(x, nome):
    """Numero finito strettamente positivo."""
    v = mh621_num(x, nome)
    if v <= 0.0:
        raise ValueError(f"{nome}: atteso > 0, ricevuto {v}")
    return v


def mh621_frac01(x, nome):
    """Frazione in [0, 1]."""
    v = mh621_num(x, nome)
    if v < 0.0 or v > 1.0:
        raise ValueError(f"{nome}: atteso in [0, 1], ricevuto {v}")
    return v


def mh621_kg_annui(portata_kg_h, ore_annue):
    """kg/anno di H2 immessi: portata oraria x ore annue."""
    return mh621_pos(portata_kg_h, "portata_kg_h") * \
        mh621_pos(ore_annue, "ore_annue")


def mh621_nm3_annui(kg_annui):
    """Nm3/anno di H2: 1 kg = 11,12 Nm3 (densita' 0,0899 kg/Nm3)."""
    return mh621_nneg(kg_annui, "kg_annui") * 11.12


def mh621_energia_mwh(kg_annui):
    """MWh/anno (LHV): 1 kg H2 = 33,33 kWh (120 MJ/kg)."""
    return mh621_nneg(kg_annui, "kg_annui") * 33.33 / 1000.0


def mh621_tco2_evitate(energia_mwh, ef_tco2_mwh):
    """tCO2/anno evitate: l'H2 sostituisce gas naturale al suo
    fattore di emissione (default 0,202 tCO2/MWh)."""
    return mh621_nneg(energia_mwh, "energia_mwh") * \
        mh621_nneg(ef_tco2_mwh, "ef_tco2_mwh")


def mh621_costo_h2(kg_annui, lcoh_eur_kg):
    """Costo annuo dell'idrogeno: kg x LCOH (€/kg)."""
    return mh621_nneg(kg_annui, "kg_annui") * \
        mh621_nneg(lcoh_eur_kg, "lcoh_eur_kg")


def mh621_gas_evitato(energia_mwh, prezzo_gas_eur_mwh):
    """Valore del gas naturale risparmiato (sostituzione 1:1 in LHV)."""
    return mh621_nneg(energia_mwh, "energia_mwh") * \
        mh621_nneg(prezzo_gas_eur_mwh, "prezzo_gas_eur_mwh")


def mh621_valore_co2(tco2_evitate, prezzo_co2_eur_t):
    """Valore delle tonnellate abbattute al prezzo ETS di benchmark."""
    return mh621_nneg(tco2_evitate, "tco2_evitate") * \
        mh621_nneg(prezzo_co2_eur_t, "prezzo_co2_eur_t")


def mh621_costo_netto(costo_h2, gas_evitato, valore_co2):
    """Costo aggiuntivo annuo: H2 pagato meno gas risparmiato e CO2
    valorizzata (puo' essere negativo: allora lo switch rende da solo)."""
    return mh621_num(costo_h2, "costo_h2") - \
        mh621_num(gas_evitato, "gas_evitato") - \
        mh621_num(valore_co2, "valore_co2")


def mh621_mac(costo_h2, gas_evitato, valore_co2, tco2_evitate):
    """MAC (€/tCO2): costo netto diviso tonnellate abbattute.
    None se nessuna tonnellata (niente da pagare: il MAC non esiste)."""
    tco2 = mh621_nneg(tco2_evitate, "tco2_evitate")
    if tco2 == 0.0:
        return None
    netto = mh621_costo_netto(costo_h2, gas_evitato, valore_co2)
    return netto / tco2


def mh621_quota_blend_pct(nm3_h2, gas_msm3_annui):
    """Quota volumetrica di blending: Nm3 H2 / (H2 + gas servito).
    100 % se il gas servito e' zero (rete solo-H2)."""
    h2 = mh621_nneg(nm3_h2, "nm3_h2")
    gas = mh621_nneg(gas_msm3_annui, "gas_msm3_annui")
    totale = h2 + gas * 1e6
    if totale == 0.0:
        raise ValueError("quota_blend: H2 e gas entrambi a zero")
    return 100.0 * h2 / totale


def mh621_verdetto(mac, prezzo_co2_benchmark):
    """CONVIENTE se il MAC non supera il prezzo ETS (il mercato del
    carbonio paga lo switch), MARGINALE entro +15 %, NON_CONVIENTE
    oltre, NON_CALCOLABILE se il MAC e' None."""
    bm = mh621_nneg(prezzo_co2_benchmark, "prezzo_co2_benchmark")
    if mac is None:
        return {"mac": None, "verdetto": "NON_CALCOLABILE",
                "msg": "nessuna tCO2 abbattuta: il MAC non e' calcolabile"}
    m = mh621_num(mac, "mac")
    if m <= bm:
        v = "CONVIENTE"
        msg = (f"MAC € {m:,.2f}/t contro ETS € {bm:,.2f}/t: il mercato "
               "del carbonio ripaga il premium dell'H2")
    elif m <= bm * 1.15:
        v = "MARGINALE"
        sopra = (m / bm - 1.0) * 100.0
        msg = (f"MAC € {m:,.2f}/t sopra l'ETS del {sopra:,.1f} % "
               "(entro il 15 %): dipende dal prezzo futuro del carbonio")
    else:
        v = "NON_CONVIENTE"
        msg = (f"MAC € {m:,.2f}/t contro ETS € {bm:,.2f}/t: con queste "
               "ipotesi il blending in rete non regge")
    return {"mac": m, "prezzo_co2_benchmark": bm, "verdetto": v, "msg": msg}


def mh621_sensibilita(portata_kg_h, ore_annue, ef_tco2_mwh,
                      prezzo_gas_eur_mwh, gas_msm3_annui,
                      lcoh_list, co2_list):
    """Griglia 2D: MAC al variare del LCOH dell'H2 e del prezzo CO2
    (le due leve che contano davvero)."""
    if not lcoh_list:
        raise ValueError("lcoh_list: lista vuota")
    if not co2_list:
        raise ValueError("co2_list: lista vuota")
    kg = mh621_kg_annui(portata_kg_h, ore_annue)
    en = mh621_energia_mwh(kg)
    tco2 = mh621_tco2_evitate(en, ef_tco2_mwh)
    gas_ev = mh621_gas_evitato(en, prezzo_gas_eur_mwh)
    rows = []
    for lc in lcoh_list:
        for pc in co2_list:
            lc_v = mh621_nneg(lc, "lcoh_eur_kg")
            pc_v = mh621_nneg(pc, "prezzo_co2")
            co = mh621_costo_h2(kg, lc_v)
            val = mh621_valore_co2(tco2, pc_v)
            mac = mh621_mac(co, gas_ev, val, tco2)
            ver = mh621_verdetto(mac, pc_v)
            rows.append({"lcoh_eur_kg": lc_v, "prezzo_co2_eur_t": pc_v,
                         "kg_annui": kg, "tco2_evitate": tco2,
                         "costo_netto": mh621_costo_netto(co, gas_ev, val),
                         "mac": mac, "giudizio": ver["verdetto"]})
    return rows


def mh621_demo():
    """Demo: 100 kg/h per 4000 ore/anno -> 400.000 kg/anno = 4.448.000
    Nm3 = 13.332 MWh LHV; EF gas 0,202 -> 2.693,064 tCO2/anno; LCOH
    5,13 eur/kg -> costo 2.052.000; gas 50 eur/MWh -> 666.600 evitati;
    CO2 100 eur/t -> 269.306,4 valorizzati; costo netto 1.116.093,6;
    MAC 414,43263138195005 eur/t contro ETS 100 -> NON_CONVIENTE;
    quota blend 8,169262415515721 % su 50 MSm3 serviti."""
    return {"portata_kg_h": 100.0, "ore_annue": 4000.0,
            "lcoh_eur_kg": 5.13, "prezzo_gas_eur_mwh": 50.0,
            "prezzo_co2_eur_t": 100.0, "ef_tco2_mwh": 0.202,
            "gas_msm3_annui": 50.0, "limite_blend_pct": 20.0}


# W620 (21/10/2026) - tab620 "🧪 LCOH: il costo dell'idrogeno verde (quando l'elettrolisi conviene)"
#
# LCOH (Levelized Cost of Hydrogen): costo livellato dell'idrogeno
# prodotto per elettrolisi. Domanda operativa: "a che prezzo al kg
# l'elettrolizzatore ripaga capex + stack + energia?" Complementa
# tab619 (LACE): stesso impianto logico di costo livellato, ma sul
# prodotto H2 invece che sui MWh elettrici.
#
#   energia_annua  = potenza_mw * ore_annue                  [MWh/anno]
#   kg_annui       = potenza_mw * 1000 * ore_annue
#                    / consumo_specifico_kwh_kg              [kg/anno]
#   capex_ann      = capex_tot * CRF(wacc, vita_anni)         [eur/anno]
#   stack_ann      = costo_stack_tot * CRF(wacc, vita_stack_anni)
#                    vita_stack_anni = vita_stack_ore / ore_annue
#   opex_fisso     = capex_tot * opex_fisso_pct               [eur/anno]
#   costo_energia  = energia_annua * prezzo_energia           [eur/anno]
#   costo_acqua    = kg_annui * costo_acqua_eur_kg            [eur/anno]
#   lcoh           = (capex_ann + stack_ann + opex_fisso
#                     + costo_energia + costo_acqua) / kg_annui  [eur/kg]
#   prezzo_pareggio_energia = prezzo dell'energia a cui
#     lcoh == prezzo_riferimento (negativo = irraggiungibile con
#     questi capex)                                            [eur/MWh]
#   verdetto       = CONVIENTE     (lcoh <= prezzo_riferimento)
#                  / NON_CONVIENTE (lcoh > prezzo_riferimento + soglia)
#                  / MARGINALE     (in mezzo, soglia = 1,0 eur/kg)
# Ipotesi: consumo specifico costante, stack sostituito a fine vita
# utile (quota annualizzata con CRF), niente ricavi da servizi di rete
# o ossigeno. Screening preliminare: non sostituisce un business plan.


def mh620_num(x, nome):
    """Valida un numero reale finito (bool e stringhe rifiutati)."""
    if isinstance(x, bool) or not isinstance(x, (int, float)):
        raise ValueError(f"{nome}: atteso numero, ricevuto {type(x).__name__}")
    v = float(x)
    if v != v or v in (float("inf"), float("-inf")):
        raise ValueError(f"{nome}: valore non finito")
    return v


def mh620_nneg(x, nome):
    """Numero >= 0."""
    v = mh620_num(x, nome)
    if v < 0.0:
        raise ValueError(f"{nome}: deve essere >= 0, ricevuto {v}")
    return v


def mh620_pos(x, nome):
    """Numero > 0."""
    v = mh620_num(x, nome)
    if v <= 0.0:
        raise ValueError(f"{nome}: deve essere > 0, ricevuto {v}")
    return v


def mh620_frac01(x, nome):
    """Frazione nell'intervallo chiuso [0, 1]."""
    v = mh620_num(x, nome)
    if not 0.0 <= v <= 1.0:
        raise ValueError(f"{nome}: deve stare in [0, 1], ricevuto {v}")
    return v


def mh620_crf(tasso, anni):
    """Capital Recovery Factor: quota annua di ammortamento del capex."""
    r = mh620_nneg(tasso, "tasso")
    n = mh620_pos(anni, "anni")
    if r == 0.0:
        return 1.0 / n
    f = (1.0 + r) ** n
    return r * f / (f - 1.0)


def mh620_energia_annua_mwh(potenza_mw, ore_annue):
    """Energia elettrica assorbita in un anno [MWh/anno]."""
    p = mh620_pos(potenza_mw, "potenza_mw")
    o = mh620_pos(ore_annue, "ore_annue")
    if o > 8760.0:
        raise ValueError(f"ore_annue: massimo 8760, ricevuto {o}")
    return p * o


def mh620_kg_annui(potenza_mw, ore_annue, consumo_kwh_kg):
    """Idrogeno prodotto in un anno [kg/anno]."""
    p = mh620_pos(potenza_mw, "potenza_mw")
    o = mh620_pos(ore_annue, "ore_annue")
    if o > 8760.0:
        raise ValueError(f"ore_annue: massimo 8760, ricevuto {o}")
    c = mh620_pos(consumo_kwh_kg, "consumo_kwh_kg")
    return p * 1000.0 * o / c


def mh620_lcoh(potenza_mw, ore_annue, consumo_kwh_kg, capex_eur_kw,
               opex_fisso_pct, costo_stack_eur_kw, vita_stack_ore,
               prezzo_energia_eur_mwh, costo_acqua_eur_kg, vita_anni,
               wacc):
    """Costo livellato dell'idrogeno [eur/kg] con dettaglio per voce.
    Lo stack di prima dotazione e' incluso nel capex; stack_ann e' la
    quota annualizzata delle SOSTITUZIONI (approssimazione di
    screening con CRF sulla vita utile dello stack in anni)."""
    p = mh620_pos(potenza_mw, "potenza_mw")
    o = mh620_pos(ore_annue, "ore_annue")
    if o > 8760.0:
        raise ValueError(f"ore_annue: massimo 8760, ricevuto {o}")
    consumo = mh620_pos(consumo_kwh_kg, "consumo_kwh_kg")
    capex_kw = mh620_nneg(capex_eur_kw, "capex_eur_kw")
    opex_pct = mh620_frac01(opex_fisso_pct, "opex_fisso_pct")
    stack_kw = mh620_nneg(costo_stack_eur_kw, "costo_stack_eur_kw")
    vita_stack = mh620_pos(vita_stack_ore, "vita_stack_ore")
    prezzo_el = mh620_nneg(prezzo_energia_eur_mwh,
                           "prezzo_energia_eur_mwh")
    acqua = mh620_nneg(costo_acqua_eur_kg, "costo_acqua_eur_kg")
    vita = mh620_pos(vita_anni, "vita_anni")
    r = mh620_nneg(wacc, "wacc")
    energia_mwh = p * o
    kg = p * 1000.0 * o / consumo
    capex_tot = capex_kw * p * 1000.0
    stack_tot = stack_kw * p * 1000.0
    capex_ann = capex_tot * mh620_crf(r, vita)
    stack_ann = stack_tot * mh620_crf(r, vita_stack / o)
    opex_fisso_ann = capex_tot * opex_pct
    costo_energia_ann = energia_mwh * prezzo_el
    costo_acqua_ann = kg * acqua
    totale_ann = (capex_ann + stack_ann + opex_fisso_ann
                  + costo_energia_ann + costo_acqua_ann)
    lcoh = totale_ann / kg
    return {"kg_annui": kg, "energia_annua_mwh": energia_mwh,
            "capex_ann": capex_ann, "stack_ann": stack_ann,
            "opex_fisso_ann": opex_fisso_ann,
            "costo_energia_ann": costo_energia_ann,
            "costo_acqua_ann": costo_acqua_ann,
            "totale_ann": totale_ann, "lcoh": lcoh,
            "quota_energia_pct": costo_energia_ann / totale_ann * 100.0}


def mh620_prezzo_pareggio_energia(potenza_mw, ore_annue, consumo_kwh_kg,
                                  capex_eur_kw, opex_fisso_pct,
                                  costo_stack_eur_kw, vita_stack_ore,
                                  costo_acqua_eur_kg, vita_anni, wacc,
                                  prezzo_riferimento_eur_kg):
    """Prezzo dell'energia a cui LCOH == prezzo di riferimento
    [eur/MWh]. Negativo = irraggiungibile: nemmeno con energia gratis
    il LCOH scende al prezzo di riferimento (capex/stack troppo alti)."""
    rif = mh620_nneg(prezzo_riferimento_eur_kg,
                     "prezzo_riferimento_eur_kg")
    det = mh620_lcoh(potenza_mw, ore_annue, consumo_kwh_kg, capex_eur_kw,
                     opex_fisso_pct, costo_stack_eur_kw, vita_stack_ore,
                     0.0, costo_acqua_eur_kg, vita_anni, wacc)
    fisso = (det["capex_ann"] + det["stack_ann"]
             + det["opex_fisso_ann"] + det["costo_acqua_ann"])
    return (rif * det["kg_annui"] - fisso) / det["energia_annua_mwh"]


def mh620_verdetto(lcoh, prezzo_riferimento, soglia=1.0):
    """Verdetto del LCOH contro il prezzo di riferimento (es. H2
    grigio da SMR). Soglia di materialita' 1,0 eur/kg."""
    lc = mh620_nneg(lcoh, "lcoh")
    rif = mh620_nneg(prezzo_riferimento, "prezzo_riferimento")
    s = mh620_pos(soglia, "soglia")
    diff = lc - rif
    if diff <= 0.0:
        v = "CONVIENTE"
        msg = (f"LCOH € {lc:,.2f}/kg <= prezzo di riferimento "
               f"€ {rif:,.2f}/kg: l'idrogeno verde costa meno o uguale")
    elif diff <= s:
        v = "MARGINALE"
        msg = (f"LCOH € {lc:,.2f}/kg contro € {rif:,.2f}/kg "
               f"(+€ {diff:,.2f}, entro la soglia di € {s:,.0f}): "
               "gap colmabile con energia piu' economica, piu' ore di "
               "utilizzo o capex piu' bassi")
    else:
        v = "NON_CONVIENTE"
        msg = (f"LCOH € {lc:,.2f}/kg contro € {rif:,.2f}/kg "
               f"(+€ {diff:,.2f}): con queste ipotesi l'elettrolisi non "
               "regge il confronto")
    return {"lcoh": lc, "prezzo_riferimento": rif, "diff": diff,
            "verdetto": v, "msg": msg}


def mh620_sensibilita(potenza_mw, consumo_kwh_kg, capex_eur_kw,
                      opex_fisso_pct, costo_stack_eur_kw, vita_stack_ore,
                      costo_acqua_eur_kg, vita_anni, wacc,
                      prezzo_riferimento_eur_kg, prezzi_energia,
                      ore_annue_list):
    """Griglia 2D: LCOH al variare del prezzo dell'energia e delle ore
    annue di utilizzo (le due leve che contano davvero)."""
    if not prezzi_energia:
        raise ValueError("prezzi_energia: lista vuota")
    if not ore_annue_list:
        raise ValueError("ore_annue_list: lista vuota")
    rows = []
    for pe in prezzi_energia:
        for ore in ore_annue_list:
            det = mh620_lcoh(potenza_mw, ore, consumo_kwh_kg,
                             capex_eur_kw, opex_fisso_pct,
                             costo_stack_eur_kw, vita_stack_ore, pe,
                             costo_acqua_eur_kg, vita_anni, wacc)
            lc = det["lcoh"]
            diff = lc - mh620_nneg(prezzo_riferimento_eur_kg,
                                   "prezzo_riferimento_eur_kg")
            giudizio = ("CONVIENTE" if diff <= 0.0
                        else "MARGINALE" if diff <= 1.0
                        else "NON_CONVIENTE")
            rows.append({"prezzo_energia_eur_mwh":
                         float(mh620_nneg(pe, "prezzo_energia")),
                         "ore_annue": float(mh620_pos(ore, "ore_annue")),
                         "kg_annui": det["kg_annui"], "lcoh": lc,
                         "quota_energia_pct":
                         det["quota_energia_pct"],
                         "giudizio": giudizio})
    return rows


def mh620_demo():
    """Demo: elettrolizzatore PEM 10 MW, 5000 ore/anno, consumo
    55 kWh/kg -> 909.091 kg/anno; capex 1200 eur/kW, opex fisso 4 %,
    stack 400 eur/kW con vita 60.000 h, vita progetto 20 anni, WACC
    7 %, energia 50 eur/MWh, acqua 0,05 eur/kg -> LCOH
    5,127955369893065 eur/kg (quota energia 53,6 %); contro H2 grigio
    2,2 eur/kg -> NON_CONVIENTE, prezzo di pareggio dell'energia
    -3,24 eur/MWh (irraggiungibile con questi capex)."""
    return {"potenza_mw": 10.0, "ore_annue": 5000.0,
            "consumo_kwh_kg": 55.0, "capex_eur_kw": 1200.0,
            "opex_fisso_pct": 0.04, "costo_stack_eur_kw": 400.0,
            "vita_stack_ore": 60000.0,
            "prezzo_energia_eur_mwh": 50.0,
            "costo_acqua_eur_kg": 0.05, "vita_anni": 20.0,
            "wacc": 0.07, "prezzo_riferimento_eur_kg": 2.2}


# W619 (21/10/2026) - tab619 "📐 LACE: il costo che la rete evita (il vero valore di un impianto)"
#
# LACE (Levelized Avoided Cost of Electricity, metrica EIA): il costo
# che la rete EVITA se costruisce l'impianto, cioe' il valore che
# l'impianto restituisce al sistema. Domanda operativa: "l'impianto
# ripaga il suo costo con quello che fa risparmiare alla rete?"
# Complementa "🏗️ LCOE vs prezzo" (che confronta solo costo e prezzo):
# il LACE aggiunge il valore di capacita' (ELCC) che un impianto
# dispacciabile o con profilo favorevole evita di procurare altrove.
#
#   e_annua        = potenza_mw * cf * 8760                    [MWh/anno]
#   lcoe           = (capex_tot * CRF(wacc, vita) + opex_fisso_tot)
#                    / e_annua + opex_var                     [eur/MWh]
#   prezzo_cattura = prezzo_medio * value_factor               [eur/MWh]
#   valore_cap     = elcc * potenza_mw * costo_cap_eur_mw_anno
#                    / e_annua                                 [eur/MWh]
#   lace           = prezzo_cattura + valore_cap               [eur/MWh]
#   netto          = lace - lcoe                               [eur/MWh]
#   verdetto       = NETTO_POSITIVO   (netto >= soglia)
#                  / DISTRUGGE_VALORE (netto <= -soglia)
#                  / MARGINALE        (in mezzo, soglia = 5 eur/MWh)
# Ipotesi: value factor = rapporto prezzo di cattura / prezzo medio
# (profilo di produzione vs profilo dei prezzi); ELCC = quota di
# capacita' accreditata alla punta; costo capacita' = costo annuo del
# MW di capacita' evitata (asta capacita'/peaker). Screening
# preliminare: non sostituisce uno studio di adeguatezza.


def mh619_num(x, nome):
    """Valida un numero reale finito (bool e stringhe rifiutati)."""
    if isinstance(x, bool) or not isinstance(x, (int, float)):
        raise ValueError(f"{nome}: atteso numero, ricevuto {type(x).__name__}")
    v = float(x)
    if v != v or v in (float("inf"), float("-inf")):
        raise ValueError(f"{nome}: valore non finito")
    return v


def mh619_nneg(x, nome):
    """Numero >= 0."""
    v = mh619_num(x, nome)
    if v < 0.0:
        raise ValueError(f"{nome}: deve essere >= 0, ricevuto {v}")
    return v


def mh619_pos(x, nome):
    """Numero > 0."""
    v = mh619_num(x, nome)
    if v <= 0.0:
        raise ValueError(f"{nome}: deve essere > 0, ricevuto {v}")
    return v


def mh619_frac01(x, nome):
    """Frazione nell'intervallo chiuso [0, 1]."""
    v = mh619_num(x, nome)
    if not 0.0 <= v <= 1.0:
        raise ValueError(f"{nome}: deve stare in [0, 1], ricevuto {v}")
    return v


def mh619_crf(tasso, anni):
    """Capital Recovery Factor: quota annua di ammortamento del capex."""
    r = mh619_nneg(tasso, "tasso")
    n = mh619_pos(anni, "anni")
    if r == 0.0:
        return 1.0 / n
    f = (1.0 + r) ** n
    return r * f / (f - 1.0)


def mh619_energia_annua(potenza_mw, cf):
    """Energia annua prodotta [MWh/anno]."""
    p = mh619_pos(potenza_mw, "potenza_mw")
    c = mh619_frac01(cf, "cf")
    return p * c * 8760.0


def mh619_lcoe(potenza_mw, cf, capex_eur_kw, opex_fisso_eur_kw_anno,
               opex_var_eur_mwh, vita_anni, wacc):
    """Costo livellato dell'energia [eur/MWh]. None-ish: ValueError se
    l'energia annua e' nulla (CF = 0 o potenza non valida)."""
    e = mh619_energia_annua(potenza_mw, cf)
    if e <= 0.0:
        raise ValueError("energia annua nulla: LCOE non calcolabile")
    capex_tot = mh619_nneg(capex_eur_kw, "capex_eur_kw") * \
        mh619_pos(potenza_mw, "potenza_mw") * 1000.0
    opex_fisso_tot = mh619_nneg(opex_fisso_eur_kw_anno,
                                "opex_fisso_eur_kw_anno") * \
        mh619_pos(potenza_mw, "potenza_mw") * 1000.0
    opex_var = mh619_nneg(opex_var_eur_mwh, "opex_var_eur_mwh")
    vita = mh619_pos(vita_anni, "vita_anni")
    r = mh619_nneg(wacc, "wacc")
    return (capex_tot * mh619_crf(r, vita) + opex_fisso_tot) / e + opex_var


def mh619_prezzo_cattura(prezzo_medio, value_factor):
    """Prezzo di cattura = prezzo medio x value factor [eur/MWh]."""
    p = mh619_nneg(prezzo_medio, "prezzo_medio")
    vf = mh619_nneg(value_factor, "value_factor")
    return p * vf


def mh619_valore_capacita_mwh(potenza_mw, elcc, costo_cap_eur_mw_anno,
                             energia_annua):
    """Valore di capacita' per MWh prodotto [eur/MWh]: il costo annuo
    della capacita' accreditata (ELCC x P x costo) spalmato sull'energia."""
    p = mh619_pos(potenza_mw, "potenza_mw")
    e = mh619_frac01(elcc, "elcc")
    cc = mh619_nneg(costo_cap_eur_mw_anno, "costo_cap_eur_mw_anno")
    ea = mh619_pos(energia_annua, "energia_annua")
    return e * p * cc / ea


def mh619_lace(prezzo_cattura, valore_cap_mwh):
    """LACE = valore energia evitata + valore capacita' evitata."""
    pc = mh619_nneg(prezzo_cattura, "prezzo_cattura")
    vc = mh619_nneg(valore_cap_mwh, "valore_cap_mwh")
    return pc + vc


def mh619_valore_netto(lace, lcoe):
    """Valore netto = LACE - LCOE [eur/MWh]: quanto l'impianto rende
    alla rete oltre il suo costo."""
    la = mh619_nneg(lace, "lace")
    lc = mh619_nneg(lcoe, "lcoe")
    return la - lc


def mh619_verdetto(lace, lcoe, soglia=5.0):
    """Verdetto sul valore netto con soglia di materialita'."""
    s = mh619_pos(soglia, "soglia")
    netto = mh619_valore_netto(lace, lcoe)
    if netto >= s:
        v = "NETTO_POSITIVO"
        msg = (f"valore netto +{netto:.1f} eur/MWh (>= +{s:.0f}): "
               "l'impianto ripaga il suo costo con il risparmio di "
               "sistema che genera")
    elif netto <= -s:
        v = "DISTRUGGE_VALORE"
        msg = (f"valore netto {netto:.1f} eur/MWh (<= -{s:.0f}): "
               "il costo supera il valore che l'impianto restituisce "
               "alla rete")
    else:
        v = "MARGINALE"
        msg = (f"valore netto {netto:+.1f} eur/MWh entro +/-{s:.0f}: "
               "il progetto sta sul filo, la decisione dipende dalle "
               "ipotesi (prezzo, ELCC, costo capacita')")
    return {"lace": float(lace), "lcoe": float(lcoe), "netto": netto,
            "verdetto": v, "msg": msg}


def mh619_sensibilita(potenza_mw, cf, capex_eur_kw, opex_fisso_eur_kw_anno,
                      opex_var_eur_mwh, vita_anni, wacc, value_factor,
                      elcc, costo_cap_eur_mw_anno, prezzi_medi):
    """Griglia: LACE e valore netto al variare del prezzo medio
    dell'energia (il LCOE non dipende dal prezzo, resta fisso)."""
    if not prezzi_medi:
        raise ValueError("prezzi_medi: lista vuota")
    e = mh619_energia_annua(potenza_mw, cf)
    lc = mh619_lcoe(potenza_mw, cf, capex_eur_kw, opex_fisso_eur_kw_anno,
                    opex_var_eur_mwh, vita_anni, wacc)
    vc = mh619_valore_capacita_mwh(potenza_mw, elcc, costo_cap_eur_mw_anno, e)
    rows = []
    for pm in prezzi_medi:
        pc = mh619_prezzo_cattura(pm, value_factor)
        la = mh619_lace(pc, vc)
        nt = mh619_valore_netto(la, lc)
        rows.append({"prezzo_medio_eur_mwh": float(mh619_nneg(pm, "prezzo")),
                     "prezzo_cattura": pc, "valore_cap_mwh": vc,
                     "lace": la, "lcoe": lc, "valore_netto": nt,
                     "giudizio": "OK" if nt >= 5.0 else
                     ("KO" if nt <= -5.0 else "filo")})
    return rows


def mh619_demo():
    """Demo: FV utility-scale 100 MW, CF 14 %, capex 800 eur/kW, opex
    fisso 15 eur/kW/anno, vita 25 anni, WACC 6 %; prezzo medio 85
    eur/MWh, value factor 0,9, ELCC 15 %, costo capacita' 60.000
    eur/MW/anno -> LACE 83,84 vs LCOE 63,26 = netto +20,58 eur/MWh
    -> NETTO_POSITIVO."""
    return {"potenza_mw": 100.0, "cf": 0.14, "capex_eur_kw": 800.0,
            "opex_fisso_eur_kw_anno": 15.0, "opex_var_eur_mwh": 0.0,
            "vita_anni": 25.0, "wacc": 0.06, "prezzo_medio": 85.0,
            "value_factor": 0.9, "elcc": 0.15,
            "costo_cap_eur_mw_anno": 60000.0}


# W618 (21/10/2026) - tab618 "🔋🧂 Batterie al sodio (Na-ion): l'accumulo senza litio conviene?"
#
# Confronto deterministico del costo livellato di accumulo (LCOS, eur/kWh
# scaricato) tra batterie sodio-ione (Na-ion) e litio-ferro-fosfato (LFP)
# per uno storage stazionario. Domanda operativa: "a parita' di servizio
# (stessi cicli/anno e DoD), il capex piu' basso del sodio compensa la
# minore durata ciclica e il rendimento inferiore?"
#
#   e_annua      = capacita_kwh * cicli_anno * dod          [kWh/anno scaricati]
#   n_anni       = min(cicli_vita / cicli_anno, vita_calendario)
#   capex_ann    = capacita_kwh * capex_eur_kwh * CRF(tasso, n_anni)
#   opex_ann     = capacita_kwh * capex_eur_kwh * opex_frac
#   ricarica_ann = e_annua / rte * prezzo_ricarica_eur_kwh
#   LCOS         = (capex_ann + opex_ann + ricarica_ann) / e_annua  [eur/kWh]
#   verdetto     = SODIO_CONVIENE  (LCOS_na <= LCOS_lfp * 0,95)
#                / LITIO_CONVIENE  (LCOS_na >= LCOS_lfp * 1,05)
#                / PARITA'         (entro +/-5 %)
# Ipotesi: stesso profilo di utilizzo per le due chimiche, degrado incluso
# nei cicli di vita equivalenti, prezzo di ricarica costante, nessun
# ricavo da servizi di rete (puro confronto di costo). Screening
# preliminare, non due diligence di fornitore.


def mh618_num(x, nome):
    """Valida un numero reale finito (bool e stringhe rifiutati)."""
    if isinstance(x, bool) or not isinstance(x, (int, float)):
        raise ValueError(f"{nome}: atteso numero, ricevuto {type(x).__name__}")
    v = float(x)
    if v != v or v in (float("inf"), float("-inf")):
        raise ValueError(f"{nome}: valore non finito")
    return v


def mh618_nneg(x, nome):
    """Numero >= 0."""
    v = mh618_num(x, nome)
    if v < 0.0:
        raise ValueError(f"{nome}: deve essere >= 0, ricevuto {v}")
    return v


def mh618_pos(x, nome):
    """Numero > 0."""
    v = mh618_num(x, nome)
    if v <= 0.0:
        raise ValueError(f"{nome}: deve essere > 0, ricevuto {v}")
    return v


def mh618_frac01(x, nome):
    """Frazione nell'intervallo chiuso [0, 1]."""
    v = mh618_num(x, nome)
    if not 0.0 <= v <= 1.0:
        raise ValueError(f"{nome}: deve stare in [0, 1], ricevuto {v}")
    return v


def mh618_crf(tasso, anni):
    """Capital Recovery Factor: quota annua di ammortamento del capex."""
    r = mh618_nneg(tasso, "tasso")
    n = mh618_pos(anni, "anni")
    if r == 0.0:
        return 1.0 / n
    f = (1.0 + r) ** n
    return r * f / (f - 1.0)


def mh618_anni_vita(cicli_vita, cicli_anno, vita_calendario):
    """Anni di vita utile: il primo tra esaurimento dei cicli e calendario."""
    cv = mh618_pos(cicli_vita, "cicli_vita")
    ca = mh618_pos(cicli_anno, "cicli_anno")
    vc = mh618_pos(vita_calendario, "vita_calendario")
    return min(cv / ca, vc)


def mh618_energia_annua(capacita_kwh, cicli_anno, dod):
    """Energia scaricata in un anno [kWh/anno]."""
    return (mh618_pos(capacita_kwh, "capacita_kwh")
            * mh618_pos(cicli_anno, "cicli_anno")
            * mh618_frac01(dod, "dod"))


def mh618_lcos(capacita_kwh, cicli_anno, dod, capex_eur_kwh, cicli_vita,
               vita_calendario, rte, prezzo_ricarica_eur_kwh, tasso,
               opex_frac):
    """LCOS [eur/kWh scaricato]: (capex annualizzato + opex + ricarica) / energia."""
    cap = mh618_pos(capacita_kwh, "capacita_kwh")
    ca = mh618_pos(cicli_anno, "cicli_anno")
    d = mh618_frac01(dod, "dod")
    ck = mh618_nneg(capex_eur_kwh, "capex_eur_kwh")
    cv = mh618_pos(cicli_vita, "cicli_vita")
    vc = mh618_pos(vita_calendario, "vita_calendario")
    e = mh618_num(rte, "rte")
    if not 0.0 < e <= 1.0:
        raise ValueError(f"rte: deve stare in (0, 1], ricevuto {e}")
    pr = mh618_nneg(prezzo_ricarica_eur_kwh, "prezzo_ricarica_eur_kwh")
    r = mh618_nneg(tasso, "tasso")
    of = mh618_frac01(opex_frac, "opex_frac")
    e_ann = cap * ca * d
    if e_ann == 0.0:
        raise ValueError("energia annua nulla: aumentare cicli_anno o dod")
    capex_tot = cap * ck
    n_anni = min(cv / ca, vc)
    capex_ann = capex_tot * mh618_crf(r, n_anni)
    opex_ann = capex_tot * of
    ricarica_ann = e_ann / e * pr
    return (capex_ann + opex_ann + ricarica_ann) / e_ann


def mh618_verdetto(lcos_na, lcos_lfp):
    """Verdetto del confronto Na-ion vs LFP (soglia +/-5 %)."""
    na = mh618_pos(lcos_na, "lcos_na")
    lfp = mh618_pos(lcos_lfp, "lcos_lfp")
    risparmio = (lfp - na) / lfp * 100.0
    if na <= lfp * 0.95:
        v = "SODIO_CONVIENE"
        msg = (f"il sodio-ione costa il {risparmio:.1f} % in meno "
               f"per kWh scaricato rispetto all'LFP")
    elif na >= lfp * 1.05:
        v = "LITIO_CONVIENE"
        msg = (f"l'LFP costa il {-risparmio:.1f} % in meno per kWh "
               f"scaricato rispetto al sodio-ione")
    else:
        v = "PARITA"
        msg = (f"differenza di LCOS entro il 5 % "
               f"({risparmio:+.1f} % a favore del sodio-ione)")
    return {"verdetto": v, "msg": msg, "lcos_na": na, "lcos_lfp": lfp,
            "risparmio_pct": risparmio}


def mh618_sensibilita(capacita_kwh, cicli_anno_base, dod,
                      capex_lfp_eur_kwh, cicli_vita_lfp, rte_lfp,
                      vita_calendario, prezzo_ricarica_eur_kwh, tasso,
                      opex_frac, capex_na_grid, cicli_anno_grid,
                      cicli_vita_na, rte_na):
    """Griglia capex Na-ion x cicli/anno -> LCOS Na-ion e vincitore vs LFP."""
    if not capex_na_grid:
        raise ValueError("capex_na_grid: lista vuota")
    if not cicli_anno_grid:
        raise ValueError("cicli_anno_grid: lista vuota")
    cap = mh618_pos(capacita_kwh, "capacita_kwh")
    lfp = mh618_lcos(cap, mh618_pos(cicli_anno_base, "cicli_anno_base"),
                     dod, capex_lfp_eur_kwh, cicli_vita_lfp,
                     vita_calendario, rte_lfp, prezzo_ricarica_eur_kwh,
                     tasso, opex_frac)
    rows = []
    for ck_na in capex_na_grid:
        for ca in cicli_anno_grid:
            na = mh618_lcos(cap, ca, dod, ck_na, cicli_vita_na,
                            vita_calendario, rte_na,
                            prezzo_ricarica_eur_kwh, tasso, opex_frac)
            v = mh618_verdetto(na, lfp)["verdetto"]
            vinc = ("Na-ion" if v == "SODIO_CONVIENE"
                    else "LFP" if v == "LITIO_CONVIENE" else "Parita'")
            rows.append({"capex_na_eur_kwh": float(mh618_nneg(ck_na, "capex_na")),
                         "cicli_anno": float(mh618_pos(ca, "cicli_anno")),
                         "lcos_na": na, "lcos_lfp": lfp,
                         "vincitore": vinc})
    return rows


def mh618_demo():
    """Input demo: 1 MWh utile, 300 cicli/anno, DoD 90 %."""
    return {"capacita_kwh": 1000.0, "cicli_anno": 300.0, "dod": 0.90,
            "capex_na_eur_kwh": 170.0, "cicli_vita_na": 4000.0,
            "rte_na": 0.90,
            "capex_lfp_eur_kwh": 220.0, "cicli_vita_lfp": 6000.0,
            "rte_lfp": 0.93,
            "vita_calendario": 15.0, "prezzo_ricarica_eur_kwh": 0.08,
            "tasso": 0.06, "opex_frac": 0.015}


# W617 (21/10/2026) - tab617 "⛽🌱 Biocarburanti (HVO): il premium per decarbonizzare"
#
# Business case deterministico dello switch diesel -> HVO (olio vegetale
# idrotrattato, drop-in) per decarbonizzare una flotta: il premium pagato
# sul litro HVO diventa un costo di abbattimento della CO2 (MAC).
# Domanda operativa: "quanti €/tCO2 mi costa passare a HVO e il MAC
# batte il prezzo del carbonio (benchmark ETS2)?"
#
#   litri_hvo      = litri_anno * quota_blend                [L/anno]
#   costo_agg      = litri_hvo * premium_eur_l               [eur/anno]
#   tco2_evitate   = litri_hvo * kgco2_l / 1000 * riduzione   [tCO2e/anno]
#   MAC            = costo_agg / tco2_evitate                [eur/tCO2e]
#                    None se tco2_evitate == 0 (nessuna
#                    tonnellata abbattuta -> costo indefinito)
#   incidenza_l    = costo_agg / litri_anno                  [eur/L]
#   verdetto       = CONVIENE     (MAC <= benchmark)
#                  / MARGINALE    (MAC <= benchmark * 1,15)
#                  / NON_CONVIENE (MAC > benchmark * 1,15)
#                  / NON_CALCOLABILE (MAC None)
# Ipotesi: premium costante tutto l'anno, HVO drop-in senza modifiche
# ai motori, fattore di emissione diesel e riduzione GHG costanti,
# nessuna penalita' di consumo (stesso PCI), niente vincoli di
# disponibilita' dell'HVO. Screening preliminare, non LCA completa.


def mh617_num(x, nome):
    """Valida un numero reale finito (bool e stringhe rifiutati)."""
    if isinstance(x, bool) or not isinstance(x, (int, float)):
        raise ValueError(f"{nome}: atteso numero, ricevuto {type(x).__name__}")
    v = float(x)
    if v != v or v in (float("inf"), float("-inf")):
        raise ValueError(f"{nome}: valore non finito")
    return v


def mh617_nneg(x, nome):
    """Numero >= 0."""
    v = mh617_num(x, nome)
    if v < 0.0:
        raise ValueError(f"{nome}: deve essere >= 0, ricevuto {v}")
    return v


def mh617_pos(x, nome):
    """Numero > 0."""
    v = mh617_num(x, nome)
    if v <= 0.0:
        raise ValueError(f"{nome}: deve essere > 0, ricevuto {v}")
    return v


def mh617_frac01(x, nome):
    """Frazione nell'intervallo chiuso [0, 1]."""
    v = mh617_num(x, nome)
    if not 0.0 <= v <= 1.0:
        raise ValueError(f"{nome}: deve stare in [0, 1], ricevuto {v}")
    return v


def mh617_litri_hvo(litri_anno, quota_blend):
    """Litri annui coperti da HVO [L/anno]."""
    return mh617_nneg(litri_anno, "litri_anno") * \
        mh617_frac01(quota_blend, "quota_blend")


def mh617_costo_aggiuntivo(litri_anno, premium_eur_l, quota_blend):
    """Costo aggiuntivo annuo del premium HVO [eur/anno]."""
    return mh617_litri_hvo(litri_anno, quota_blend) * \
        mh617_nneg(premium_eur_l, "premium_eur_l")


def mh617_tco2_evitate(litri_anno, quota_blend, kgco2_l, riduzione_ghg):
    """Tonnellate di CO2e evitate in un anno [tCO2e/anno]."""
    k = mh617_nneg(kgco2_l, "kgco2_l")
    r = mh617_frac01(riduzione_ghg, "riduzione_ghg")
    return mh617_litri_hvo(litri_anno, quota_blend) * k / 1000.0 * r


def mh617_mac(costo_aggiuntivo, tco2_evitate):
    """MAC: costo di abbattimento [eur/tCO2e]; None se nessuna tCO2."""
    c = mh617_nneg(costo_aggiuntivo, "costo_aggiuntivo")
    t = mh617_nneg(tco2_evitate, "tco2_evitate")
    if t == 0.0:
        return None
    return c / t


def mh617_incidenza_l(costo_aggiuntivo, litri_anno):
    """Incidenza del premium sul litro di consumo totale [eur/L]."""
    c = mh617_nneg(costo_aggiuntivo, "costo_aggiuntivo")
    l = mh617_pos(litri_anno, "litri_anno")
    return c / l


def mh617_verdetto(mac, benchmark_eur_t):
    """Verdetto sul business case dal MAC vs benchmark carbonio."""
    b = mh617_nneg(benchmark_eur_t, "benchmark_eur_t")
    if mac is None:
        return {"verdetto": "NON_CALCOLABILE",
                "mac": None,
                "msg": "nessuna tonnellata di CO2 abbattuta "
                       "(quota blend o riduzione GHG a zero): il MAC non "
                       "e' definito."}
    m = mh617_nneg(mac, "mac")
    if m <= b:
        v = "CONVIENE"
        msg = (f"MAC {m:,.1f} eur/tCO2 sotto il benchmark carbonio "
               f"{b:,.0f} eur/tCO2: abbattere con HVO costa meno del "
               f"prezzo del carbonio.")
    elif m <= b * 1.15:
        v = "MARGINALE"
        msg = (f"MAC {m:,.1f} eur/tCO2 sopra il benchmark {b:,.0f} "
               f"eur/tCO2 solo del {(m / b - 1.0) * 100:,.1f} % (< 15 %): "
               f"il premium HVO va negoziato verso il basso.")
    else:
        v = "NON_CONVIENE"
        msg = (f"MAC {m:,.1f} eur/tCO2 sopra il benchmark {b:,.0f} "
               f"eur/tCO2 del {(m / b - 1.0) * 100:,.1f} %: conviene "
               f"pagare il carbonio o abbattere con altre leve.")
    return {"verdetto": v, "mac": m, "msg": msg}


def mh617_sensitivita(litri_anno, kgco2_l, riduzione_ghg, benchmark_eur_t,
                      premium_list, quota_list):
    """Griglia premium x quota blend: costo, tCO2, MAC, verdetto.

    Il costo cresce col premium e con la quota; il MAC e' invariante
    alla quota (stesso rapporto) e cresce col premium."""
    pls = [mh617_nneg(x, "premium_list") for x in premium_list]
    qls = [mh617_frac01(x, "quota_list") for x in quota_list]
    if not pls or not qls:
        raise ValueError("premium_list e quota_list: liste non vuote")
    righe = []
    for pl in pls:
        for ql in qls:
            ca = mh617_costo_aggiuntivo(litri_anno, pl, ql)
            tc = mh617_tco2_evitate(litri_anno, ql, kgco2_l, riduzione_ghg)
            mc = mh617_mac(ca, tc)
            vd = mh617_verdetto(mc, benchmark_eur_t)
            righe.append({"premium_eur_l": float(pl),
                          "quota_blend": float(ql),
                          "costo_aggiuntivo": ca,
                          "tco2_evitate": tc,
                          "mac": mc,
                          "verdetto": vd["verdetto"]})
    return righe


def mh617_demo():
    """Parametri demo: flotta da 500.000 L/anno, HVO al 100 %."""
    return {"litri_anno": 500000.0,
            "premium_eur_l": 0.25,
            "quota_blend": 1.0,
            "kgco2_l": 2.68,
            "riduzione_ghg": 0.85,
            "benchmark_eur_t": 100.0}


# W616 (21/10/2026) - tab616 "🔋🌊 Batterie a flusso (VRFB): accumulo long-duration"
#
# Business case deterministico di una batteria a flusso redox al
# vanadio (VRFB) che fa arbitraggio giornaliero sull'energia piu'
# un eventuale ricavo da capacita'. Domanda operativa: "il prezzo
# di vendita dell'energia scaricata ripaga il costo livellato
# (LCOS) di una batteria a flusso?"
#
#   E_MWh          = P_MW * durata_h                    [MWh]
#   capex          = P*1000*eur_kw + E_MWh*1000*eur_kwh  [eur]
#                    (il capex a flusso e' disaccoppiato:
#                     potenza = stack+inverter, energia =
#                     elettrolita+serbatoi)
#   E_d            = P * durata_h * cicli_anno           [MWh/anno scaricati]
#   E_ch           = E_d / rte                          [MWh/anno caricati]
#   R_vendita      = E_d * p_vendita                    [eur/anno]
#   C_ricarica     = E_ch * p_acquisto                  [eur/anno]
#   R_capacita     = P * eur_mw_anno                    [eur/anno]
#   opex           = capex * opex_frac                  [eur/anno]
#   margine        = R_vendita + R_capacita
#                    - C_ricarica - opex                [eur/anno]
#   factor         = (1 - (1+r)^-n) / r   (r = 0 -> n)
#   flussi         = [-capex, margine x n]
#   VAN            = somma flussi attualizzati          [eur]
#   TIR            = bisezione (None se flussi a segno costante)
#   payback        = primo anno con cumulato >= 0 (None se mai)
#   LCOS           = VAN(capex + opex + C_ricarica annui)
#                    / VAN(E_d annui)                   [eur/MWh scaricato]
#                    costo livellato dell'energia scaricata:
#                    prezzo di vendita di break-even
#   marg_sic       = (p_vendita - LCOS) / LCOS          [frazione]
#   verdetto       = CONVIENE     (marg_sic >= 0.15)
#                  / MARGINALE    (marg_sic >= 0.00)
#                  / NON_CONVIENE (marg_sic < 0)
# Ipotesi: prezzi di acquisto/vendita costanti, efficienza di
# round-trip costante, cicli annui pieni, nessun degrado da ciclo
# (l'elettrolita VRFB non degrada come il litio — punto di forza
# della tecnologia), vita utile 20-25 anni, niente costo
# opportunita' verso altri servizi di rete.


def mh616_num(x, nome):
    """Valida un numero reale finito (bool e stringhe rifiutati)."""
    if isinstance(x, bool) or not isinstance(x, (int, float)):
        raise ValueError(f"{nome}: atteso numero, ricevuto {type(x).__name__}")
    v = float(x)
    if v != v or v in (float("inf"), float("-inf")):
        raise ValueError(f"{nome}: valore non finito")
    return v


def mh616_nneg(x, nome):
    """Numero >= 0."""
    v = mh616_num(x, nome)
    if v < 0.0:
        raise ValueError(f"{nome}: deve essere >= 0, ricevuto {v}")
    return v


def mh616_pos(x, nome):
    """Numero > 0."""
    v = mh616_num(x, nome)
    if v <= 0.0:
        raise ValueError(f"{nome}: deve essere > 0, ricevuto {v}")
    return v


def mh616_frac01(x, nome):
    """Frazione nell'intervallo chiuso [0, 1]."""
    v = mh616_num(x, nome)
    if not 0.0 <= v <= 1.0:
        raise ValueError(f"{nome}: deve stare in [0, 1], ricevuto {v}")
    return v


def mh616_intero(x, nome, vmin, vmax):
    """Intero nell'intervallo chiuso [vmin, vmax] (bool rifiutato)."""
    if isinstance(x, bool) or not isinstance(x, (int, float)):
        raise ValueError(f"{nome}: atteso intero, ricevuto {type(x).__name__}")
    v = float(x)
    if v != int(v):
        raise ValueError(f"{nome}: atteso intero, ricevuto {v}")
    vi = int(v)
    if not vmin <= vi <= vmax:
        raise ValueError(f"{nome}: deve stare in [{vmin}, {vmax}]")
    return vi


def mh616_energia_mwh(potenza_mw, durata_h):
    """Capacita' energetica utile [MWh]."""
    p = mh616_pos(potenza_mw, "potenza_mw")
    h = mh616_pos(durata_h, "durata_h")
    return p * h


def mh616_capex(potenza_mw, durata_h, eur_per_kw, eur_per_kwh):
    """Investimento iniziale [eur]: parte potenza + parte energia."""
    e = mh616_energia_mwh(potenza_mw, durata_h)
    ck = mh616_nneg(eur_per_kw, "eur_per_kw")
    ce = mh616_nneg(eur_per_kwh, "eur_per_kwh")
    return potenza_mw * 1000.0 * ck + e * 1000.0 * ce


def mh616_energia_scaricata_annua(potenza_mw, durata_h, cicli_anno):
    """Energia scaricata in un anno [MWh/anno]."""
    c = mh616_nneg(cicli_anno, "cicli_anno")
    return mh616_energia_mwh(potenza_mw, durata_h) * c


def mh616_energia_caricata_annua(e_scaricata_annua, rte):
    """Energia da caricare in un anno [MWh/anno] (perdite di RTE)."""
    e = mh616_nneg(e_scaricata_annua, "e_scaricata_annua")
    r = mh616_pos(rte, "rte")
    return e / r


def mh616_ricavo_vendita(e_scaricata_annua, p_vendita):
    """Ricavo annuo dalla vendita dell'energia scaricata [eur/anno]."""
    return mh616_nneg(e_scaricata_annua, "e_scaricata_annua") * \
        mh616_nneg(p_vendita, "p_vendita")


def mh616_costo_ricarica(e_caricata_annua, p_acquisto):
    """Costo annuo dell'energia di ricarica [eur/anno]."""
    return mh616_nneg(e_caricata_annua, "e_caricata_annua") * \
        mh616_nneg(p_acquisto, "p_acquisto")


def mh616_ricavo_capacita(potenza_mw, eur_mw_anno):
    """Ricavo annuo da capacita'/servizi [eur/anno]."""
    return mh616_pos(potenza_mw, "potenza_mw") * \
        mh616_nneg(eur_mw_anno, "eur_mw_anno")


def mh616_opex_annuo(capex, opex_frac):
    """Opex annuo come frazione del capex [eur/anno]."""
    return mh616_nneg(capex, "capex") * mh616_frac01(opex_frac, "opex_frac")


def mh616_margine_annuo(ric_vendita, ric_capacita, costo_ricarica, opex):
    """Margine operativo annuo [eur/anno]."""
    return (mh616_nneg(ric_vendita, "ric_vendita")
            + mh616_nneg(ric_capacita, "ric_capacita")
            - mh616_nneg(costo_ricarica, "costo_ricarica")
            - mh616_nneg(opex, "opex"))


def mh616_factor(tasso, anni):
    """Fattore di attualizzazione di una rendita annua costante."""
    r = mh616_nneg(tasso, "tasso")
    n = mh616_intero(anni, "anni", 1, 60)
    if r == 0.0:
        return float(n)
    return (1.0 - (1.0 + r) ** (-n)) / r


def mh616_flussi(capex, margine_annuo, anni):
    """Flussi di cassa [-capex, margine x anni]."""
    c = mh616_nneg(capex, "capex")
    m = mh616_num(margine_annuo, "margine_annuo")
    n = mh616_intero(anni, "anni", 1, 60)
    return [-c] + [m] * n


def mh616_van(flussi, tasso):
    """VAN dei flussi al tasso dato [eur]."""
    r = mh616_nneg(tasso, "tasso")
    return sum(f / (1.0 + r) ** t for t, f in enumerate(flussi))


def mh616_tir(flussi, tol=1e-9, maxit=200):
    """TIR via bisezione; None se i flussi non cambiano segno.

    Gestisce anche TIR > 100 % (estremo superiore espanso per
    raddoppi) e TIR negativi (ricerca tra -99,99 % e 0)."""
    if not flussi:
        return None
    fs = [mh616_num(f, "flussi") for f in flussi]
    if not (any(f > 0.0 for f in fs) and any(f < 0.0 for f in fs)):
        return None

    def _npv(r):
        return sum(f / (1.0 + r) ** t for t, f in enumerate(fs))

    n_zero = _npv(0.0)
    if n_zero > 0.0:
        # radice in (0, +inf): espandi hi finche' il VAN diventa < 0
        lo, n_lo, hi = 0.0, n_zero, 1.0
        n_hi = _npv(hi)
        k = 0
        while n_hi > 0.0 and k < 100:
            hi *= 2.0
            n_hi = _npv(hi)
            k += 1
        if n_hi > 0.0:
            return None
    else:
        # possibile radice in (-99,99 %, 0]: serve VAN(-99,99 %) > 0
        n_neg = _npv(-0.9999)
        if n_neg <= 0.0:
            return None
        lo, n_lo, hi, n_hi = -0.9999, n_neg, 0.0, n_zero
    for _ in range(maxit):
        mid = 0.5 * (lo + hi)
        n_mid = _npv(mid)
        if abs(n_mid) < tol * max(1.0, abs(fs[0])):
            return mid
        if n_lo * n_mid <= 0.0:
            hi, n_hi = mid, n_mid
        else:
            lo, n_lo = mid, n_mid
    return 0.5 * (lo + hi)


def mh616_payback(flussi):
    """Primo anno con cumulato >= 0; None se mai."""
    cum = 0.0
    for t, f in enumerate(flussi):
        cum += f
        if t > 0 and cum >= 0.0:
            return t
    return None


def mh616_lcos(capex, opex_annuo, costo_ricarica_annuo, e_scaricata_annua,
               tasso, anni):
    """LCOS: VAN(capex+opex+ricarica) / VAN(MWh scaricati) [eur/MWh].

    Prezzo di vendita di break-even dell'energia scaricata."""
    e = mh616_pos(e_scaricata_annua, "e_scaricata_annua")
    n = mh616_intero(anni, "anni", 1, 60)
    r = mh616_nneg(tasso, "tasso")
    costo_annuo = (mh616_nneg(opex_annuo, "opex_annuo")
                   + mh616_nneg(costo_ricarica_annuo, "costo_ricarica_annuo"))
    van_costi = (mh616_nneg(capex, "capex")
                 + costo_annuo * mh616_factor(r, n))
    van_energia = e * mh616_factor(r, n)
    return van_costi / van_energia


def mh616_verdetto(p_vendita, lcos):
    """Verdetto sul business case da margine di sicurezza vs LCOS."""
    p = mh616_nneg(p_vendita, "p_vendita")
    c = mh616_pos(lcos, "lcos")
    ms = (p - c) / c
    if ms >= 0.15:
        v = "CONVIENE"
        msg = (f"prezzo di vendita {p:,.0f} eur/MWh sopra il LCOS "
               f"{c:,.2f} eur/MWh del {ms * 100:,.1f} % (>= 15 %).")
    elif ms >= 0.0:
        v = "MARGINALE"
        msg = (f"prezzo di vendita {p:,.0f} eur/MWh sopra il LCOS "
               f"{c:,.2f} eur/MWh solo del {ms * 100:,.1f} % (< 15 %).")
    else:
        v = "NON_CONVIENE"
        msg = (f"prezzo di vendita {p:,.0f} eur/MWh sotto il LCOS "
               f"{c:,.2f} eur/MWh del {-ms * 100:,.1f} %.")
    return {"verdetto": v, "margine_sicurezza": ms, "msg": msg}


def mh616_sensitivita(potenza_mw, durata_h, eur_per_kw, opex_frac, rte,
                      cicli_anno, p_acquisto, eur_mw_anno, tasso, anni,
                      prezzi_vendita, capex_eur_kwh_list):
    """Griglia prezzo vendita x capex energia: LCOS, margine, VAN, verdetto.

    Il LCOS cresce col capex energia ed e' invariante al prezzo di
    vendita; il margine di sicurezza e il VAN crescono col prezzo."""
    pvs = [mh616_nneg(x, "prezzi_vendita") for x in prezzi_vendita]
    ces = [mh616_pos(x, "capex_eur_kwh_list") for x in capex_eur_kwh_list]
    if not pvs or not ces:
        raise ValueError("prezzi_vendita e capex_eur_kwh_list: liste non vuote")
    righe = []
    for pv in pvs:
        for ce in ces:
            cx = mh616_capex(potenza_mw, durata_h, eur_per_kw, ce)
            ed = mh616_energia_scaricata_annua(potenza_mw, durata_h,
                                               cicli_anno)
            ech = mh616_energia_caricata_annua(ed, rte)
            rv = mh616_ricavo_vendita(ed, pv)
            rc = mh616_ricavo_capacita(potenza_mw, eur_mw_anno)
            cr = mh616_costo_ricarica(ech, p_acquisto)
            ox = mh616_opex_annuo(cx, opex_frac)
            mg = mh616_margine_annuo(rv, rc, cr, ox)
            vn = mh616_van(mh616_flussi(cx, mg, anni), tasso)
            lc = mh616_lcos(cx, ox, cr, ed, tasso, anni)
            vd = mh616_verdetto(pv, lc)
            righe.append({"prezzo_vendita": float(pv),
                          "capex_eur_kwh": float(ce),
                          "capex": cx,
                          "lcos": lc,
                          "margine_sicurezza": vd["margine_sicurezza"],
                          "van": vn,
                          "verdetto": vd["verdetto"]})
    return righe


def mh616_demo():
    """Parametri demo: VRFB 2 MW / 6 h per arbitraggio giornaliero."""
    return {"potenza_mw": 2.0,
            "durata_h": 6.0,
            "capex_kw": 350.0,
            "capex_kwh": 180.0,
            "rte": 0.72,
            "cicli_anno": 330.0,
            "p_acquisto": 45.0,
            "p_vendita": 160.0,
            "eur_mw_anno": 0.0,
            "opex_frac": 0.015,
            "tasso": 0.06,
            "anni": 25}


# W615 (21/10/2026) - tab615 "🌀 Volano (flywheel): accumulo cinetico per FCR e servizi di rete"
#
# Business case deterministico di un volano (flywheel) che vende
# potenza di riserva primaria (FCR). Domanda operativa: "il prezzo
# della riserva primaria ripaga il costo livellato di un volano?"
#
#   capex          = P_MW * 1000 * eur_per_kw              [eur]
#   E_standby      = P_MW * standby_frac * 8760            [MWh/anno]
#                    (perdite a vuoto del rotore: il volano va tenuto
#                     in rotazione anche quando non eroga)
#   C_standby      = E_standby * p_energia                 [eur/anno]
#   opex           = capex * opex_frac                     [eur/anno]
#   R_fcr          = P_MW * p_fcr * disp * 8760            [eur/anno]
#   margine        = R_fcr - opex - C_standby               [eur/anno]
#   factor         = (1 - (1+r)^-n) / r   (r = 0 -> n)
#   flussi         = [-capex, margine x n]
#   VAN            = somma flussi attualizzati             [eur]
#   TIR            = bisezione (None se flussi a segno costante)
#   payback        = primo anno con cumulato >= 0 (None se mai)
#   c_fcr          = VAN(costi) / VAN(MW*anni disponibili) [eur/MW/h]
#                    costo livellato della capacita' FCR offerta
#   marg_sic       = (p_fcr - c_fcr) / c_fcr               [frazione]
#   verdetto       = CONVIENE     (marg_sic >= 0.15)
#                  / MARGINALE    (marg_sic >= 0.00)
#                  / NON_CONVIENE (marg_sic < 0)
# Ipotesi: prezzo FCR e disponibilita' costanti, perdite a vuoto
# costanti, nessun degrado della macchina (vita utile 20 anni
# tipica dei volani), niente costo opportunita' vs arbitraggio.


def mh615_num(x, nome):
    """Valida un numero reale finito (bool e stringhe rifiutati)."""
    if isinstance(x, bool) or not isinstance(x, (int, float)):
        raise ValueError(f"{nome}: atteso numero, ricevuto {type(x).__name__}")
    v = float(x)
    if v != v or v in (float("inf"), float("-inf")):
        raise ValueError(f"{nome}: valore non finito")
    return v


def mh615_nneg(x, nome):
    """Numero >= 0."""
    v = mh615_num(x, nome)
    if v < 0.0:
        raise ValueError(f"{nome}: deve essere >= 0, ricevuto {v}")
    return v


def mh615_pos(x, nome):
    """Numero > 0."""
    v = mh615_num(x, nome)
    if v <= 0.0:
        raise ValueError(f"{nome}: deve essere > 0, ricevuto {v}")
    return v


def mh615_frac01(x, nome):
    """Frazione nell'intervallo chiuso [0, 1]."""
    v = mh615_num(x, nome)
    if not 0.0 <= v <= 1.0:
        raise ValueError(f"{nome}: deve stare in [0, 1], ricevuto {v}")
    return v


def mh615_intero(x, nome, vmin, vmax):
    """Intero nell'intervallo chiuso [vmin, vmax] (bool rifiutato)."""
    if isinstance(x, bool) or not isinstance(x, (int, float)):
        raise ValueError(f"{nome}: atteso intero, ricevuto {type(x).__name__}")
    v = float(x)
    if v != int(v):
        raise ValueError(f"{nome}: atteso intero, ricevuto {v}")
    vi = int(v)
    if not vmin <= vi <= vmax:
        raise ValueError(f"{nome}: deve stare in [{vmin}, {vmax}]")
    return vi


def mh615_capex(potenza_mw, eur_per_kw):
    """Investimento iniziale del volano [eur]."""
    p = mh615_pos(potenza_mw, "potenza_mw")
    c = mh615_pos(eur_per_kw, "eur_per_kw")
    return p * 1000.0 * c


def mh615_energia_standby(potenza_mw, standby_frac, ore=8760.0):
    """Energia annua delle perdite a vuoto [MWh/anno]."""
    p = mh615_pos(potenza_mw, "potenza_mw")
    s = mh615_frac01(standby_frac, "standby_frac")
    h = mh615_pos(ore, "ore")
    return p * s * h


def mh615_costo_standby(potenza_mw, standby_frac, prezzo_mwh):
    """Costo annuo delle perdite a vuoto [eur/anno]."""
    e = mh615_energia_standby(potenza_mw, standby_frac)
    pe = mh615_nneg(prezzo_mwh, "prezzo_mwh")
    return e * pe


def mh615_opex_annuo(capex, opex_frac):
    """O&M annuo come frazione del capex [eur/anno]."""
    c = mh615_nneg(capex, "capex")
    f = mh615_frac01(opex_frac, "opex_frac")
    return c * f


def mh615_ricavo_fcr(potenza_mw, prezzo_mw_h, disponibilita, ore=8760.0):
    """Ricavo annuo da riserva primaria FCR [eur/anno]."""
    p = mh615_pos(potenza_mw, "potenza_mw")
    pf = mh615_nneg(prezzo_mw_h, "prezzo_mw_h")
    d = mh615_frac01(disponibilita, "disponibilita")
    h = mh615_pos(ore, "ore")
    return p * pf * d * h


def mh615_margine_annuo(ricavo, opex, costo_standby):
    """Margine operativo annuo [eur/anno]."""
    r = mh615_nneg(ricavo, "ricavo")
    o = mh615_nneg(opex, "opex")
    s = mh615_nneg(costo_standby, "costo_standby")
    return r - o - s


def mh615_factor(tasso, anni):
    """Fattore di attualizzazione di una rendita annua; tasso = 0 -> anni."""
    r = mh615_nneg(tasso, "tasso")
    n = mh615_intero(anni, "anni", 1, 40)
    if r == 0.0:
        return float(n)
    return (1.0 - (1.0 + r) ** (-n)) / r


def mh615_flussi(capex, margine_annuo, anni):
    """Flussi di cassa: [-capex, margine x anni]."""
    c = mh615_nneg(capex, "capex")
    m = mh615_num(margine_annuo, "margine_annuo")
    n = mh615_intero(anni, "anni", 1, 40)
    return [-c] + [m] * n


def mh615_van(flussi, tasso):
    """VAN dei flussi di cassa [eur]."""
    r = mh615_nneg(tasso, "tasso")
    if not flussi:
        raise ValueError("flussi: lista non vuota")
    return sum(f / (1.0 + r) ** t for t, f in enumerate(flussi))


def mh615_tir(flussi):
    """Tasso interno di rendimento per bisezione; None se non esiste."""
    if not flussi:
        raise ValueError("flussi: lista non vuota")
    fs = [mh615_num(f, "flussi") for f in flussi]

    def _npv(r):
        return sum(f / (1.0 + r) ** t for t, f in enumerate(fs))
    lo, hi = -0.9999, 10.0
    n_lo, n_hi = _npv(lo), _npv(hi)
    if n_lo * n_hi > 0.0:
        return None
    for _ in range(200):
        mid = (lo + hi) / 2.0
        n_mid = _npv(mid)
        if n_lo * n_mid <= 0.0:
            hi, n_hi = mid, n_mid
        else:
            lo, n_lo = mid, n_mid
        if hi - lo < 1e-10:
            break
    return (lo + hi) / 2.0


def mh615_payback(flussi):
    """Primo anno con cumulato >= 0; None se mai."""
    if not flussi:
        raise ValueError("flussi: lista non vuota")
    cum = 0.0
    for t, f in enumerate(flussi):
        cum += f
        if cum >= 0.0:
            return t
    return None


def mh615_costo_fcr_livellato(capex, opex_annuo, costo_standby_annuo,
                              potenza_mw, disponibilita, tasso, anni):
    """Costo livellato della capacita' FCR offerta [eur/MW/h].

    VAN(costi) / VAN(MW*anni disponibili) / 8760: quanto deve pagare
    il mercato della riserva primaria per ripagare il volano.
    """
    c = mh615_nneg(capex, "capex")
    o = mh615_nneg(opex_annuo, "opex_annuo")
    s = mh615_nneg(costo_standby_annuo, "costo_standby_annuo")
    p = mh615_pos(potenza_mw, "potenza_mw")
    d = mh615_frac01(disponibilita, "disponibilita")
    f = mh615_factor(tasso, anni)
    van_costi = c + (o + s) * f
    van_mwanni = p * d * f
    return van_costi / van_mwanni / 8760.0


def mh615_verdetto(prezzo_fcr, costo_fcr):
    """Classifica il business case sul margine di sicurezza.

    CONVIENE se il prezzo FCR supera il costo livellato di almeno
    il 15 %; MARGINALE se lo supera ma con margine inferiore;
    NON_CONVIENE se il costo livellato supera il prezzo.
    """
    pf = mh615_nneg(prezzo_fcr, "prezzo_fcr")
    cf = mh615_pos(costo_fcr, "costo_fcr")
    ms = (pf - cf) / cf
    if ms >= 0.15:
        return {"verdetto": "CONVIENE", "margine_sicurezza": ms,
                "msg": "il prezzo FCR supera il costo livellato di "
                       "almeno il 15 %: il volano ripaga l'investimento "
                       "con margine di sicurezza"}
    if ms >= 0.0:
        return {"verdetto": "MARGINALE", "margine_sicurezza": ms,
                "msg": "il prezzo FCR copre il costo livellato ma con "
                       "margine sotto il 15 %: il caso e' sensibile a "
                       "prezzo FCR e disponibilita'"}
    return {"verdetto": "NON_CONVIENE", "margine_sicurezza": ms,
            "msg": "il costo livellato supera il prezzo FCR: a questi "
                   "prezzi il volano non ripaga l'investimento"}


def mh615_sensitivita(potenza_mw, energia_mwh, opex_frac, standby_frac,
                      prezzo_mwh, disponibilita, tasso, anni,
                      prezzi_fcr, capex_kw_lista):
    """Griglia prezzo FCR x capex unitario.

    Ritorna lista di dict {"prezzo_fcr", "capex_kw", "costo_fcr",
    "margine_sicurezza", "van", "verdetto"}.
    """
    p = mh615_pos(potenza_mw, "potenza_mw")
    e = mh615_pos(energia_mwh, "energia_mwh")
    pfs = [mh615_nneg(x, "prezzi_fcr") for x in prezzi_fcr]
    cks = [mh615_pos(x, "capex_kw_lista") for x in capex_kw_lista]
    if not pfs or not cks:
        raise ValueError("prezzi_fcr e capex_kw_lista: liste non vuote")
    righe = []
    for pf in pfs:
        for ck in cks:
            cx = mh615_capex(p, ck)
            op = mh615_opex_annuo(cx, opex_frac)
            cs = mh615_costo_standby(p, standby_frac, prezzo_mwh)
            rc = mh615_ricavo_fcr(p, pf, disponibilita)
            mg = mh615_margine_annuo(rc, op, cs)
            cf = mh615_costo_fcr_livellato(cx, op, cs, p, disponibilita,
                                           tasso, anni)
            vv = mh615_verdetto(pf, cf)
            fl = mh615_flussi(cx, mg, anni)
            righe.append({"prezzo_fcr": pf, "capex_kw": ck,
                          "costo_fcr": cf,
                          "margine_sicurezza": vv["margine_sicurezza"],
                          "van": mh615_van(fl, tasso),
                          "verdetto": vv["verdetto"]})
    return righe


def mh615_demo():
    """Parametri demo: volano 1 MW / 0,25 MWh, FCR 28 eur/MW/h."""
    return {
        "potenza_mw": 1.0,
        "energia_mwh": 0.25,
        "capex_kw": 1500.0,
        "opex_frac": 0.02,
        "standby_frac": 0.03,
        "prezzo_mwh": 80.0,
        "prezzo_fcr": 28.0,
        "disponibilita": 0.95,
        "tasso": 0.06,
        "anni": 20,
    }


# W614 (21/10/2026) - tab614 "🟢📄 PPA vs merchant: il prezzo fisso vale lo sconto?"
#
# Confronto deterministico tra un PPA a prezzo fisso e la vendita
# sul mercato merchant per lo stesso volume di energia.
# Domanda operativa: "lo sconto implicito del PPA (prezzo fisso
# sotto il prezzo di mercato atteso) e' ripagato dall'eliminazione
# del rischio di prezzo?"
#
#   R_ppa      = E * p_ppa                                [eur/anno]
#   R_mer      = E * p_mer                                [eur/anno]
#   sconto     = (p_mer - p_ppa) / p_mer                   [frazione]
#   haircut    = 1.645 * vol                              [frazione]
#                (scostamento VaR95 unilaterale del prezzo merchant;
#                 1.645 e' il quantile 95 % della normale standard)
#   p_prudente = p_mer * (1 - haircut)                     [eur/MWh]
#   R_prudente = E * p_prudente                           [eur/anno]
#   factor     = (1 - (1+r)^-n) / r   (r = 0 -> n)
#   VAN        = ricavo_annuo * factor
#   verdetto   = CONVIENE     (sconto <= haircut)
#              / MARGINALE    (sconto <= haircut + 0.03)
#              / NON_CONVIENE (oltre)
# Regola decisionale: il PPA conviene se lo sconto che si paga e'
# minore o uguale all'haircut di rischio che si evita.


def mh614_num(x, nome):
    """Valida un numero reale finito (bool e stringhe rifiutati)."""
    if isinstance(x, bool) or not isinstance(x, (int, float)):
        raise ValueError(f"{nome}: atteso numero, ricevuto {type(x).__name__}")
    v = float(x)
    if v != v or v in (float("inf"), float("-inf")):
        raise ValueError(f"{nome}: valore non finito")
    return v


def mh614_nneg(x, nome):
    """Numero >= 0."""
    v = mh614_num(x, nome)
    if v < 0.0:
        raise ValueError(f"{nome}: deve essere >= 0, ricevuto {v}")
    return v


def mh614_pos(x, nome):
    """Numero > 0."""
    v = mh614_num(x, nome)
    if v <= 0.0:
        raise ValueError(f"{nome}: deve essere > 0, ricevuto {v}")
    return v


def mh614_frac01(x, nome):
    """Frazione nell'intervallo chiuso [0, 1]."""
    v = mh614_num(x, nome)
    if not 0.0 <= v <= 1.0:
        raise ValueError(f"{nome}: deve stare in [0, 1], ricevuto {v}")
    return v


def mh614_intero(x, nome, vmin, vmax):
    """Intero nell'intervallo chiuso [vmin, vmax] (bool rifiutato)."""
    if isinstance(x, bool) or not isinstance(x, (int, float)):
        raise ValueError(f"{nome}: atteso intero, ricevuto {type(x).__name__}")
    v = float(x)
    if v != int(v):
        raise ValueError(f"{nome}: atteso intero, ricevuto {v}")
    vi = int(v)
    if not vmin <= vi <= vmax:
        raise ValueError(f"{nome}: deve stare in [{vmin}, {vmax}]")
    return vi


def mh614_factor(tasso, anni):
    """Fattore di attualizzazione di una rendita annua; tasso = 0 -> anni."""
    r = mh614_nneg(tasso, "tasso")
    n = mh614_intero(anni, "anni", 1, 40)
    if r == 0.0:
        return float(n)
    return (1.0 - (1.0 + r) ** (-n)) / r


def mh614_ricavo(energia_mwh, prezzo):
    """Ricavo annuo = energia x prezzo [eur/anno]."""
    e = mh614_pos(energia_mwh, "energia_mwh")
    p = mh614_nneg(prezzo, "prezzo")
    return e * p


def mh614_sconto(p_ppa, p_mer):
    """Sconto del PPA sul prezzo merchant atteso [frazione].

    > 0 = il PPA e' scontato (prezzo fisso sotto il mercato);
    < 0 = il PPA e' a premio.
    """
    pp = mh614_nneg(p_ppa, "p_ppa")
    pm = mh614_pos(p_mer, "p_mer")
    return (pm - pp) / pm


def mh614_haircut(vol):
    """Haircut VaR95 unilaterale sul prezzo [frazione] = 1.645 x vol."""
    v = mh614_nneg(vol, "vol")
    return 1.645 * v


def mh614_prezzo_prudente(p_mer, vol):
    """Prezzo merchant 'prudente' (VaR95) [eur/MWh]."""
    pm = mh614_pos(p_mer, "p_mer")
    return pm * (1.0 - mh614_haircut(vol))


def mh614_van(ricavo_annuo, tasso, anni):
    """VAN di una rendita annua costante [eur]."""
    ra = mh614_nneg(ricavo_annuo, "ricavo_annuo")
    return ra * mh614_factor(tasso, anni)


def mh614_delta(p_ppa, p_mer, energia_mwh):
    """Differenza annua PPA - merchant [eur/anno]; > 0 = il PPA incassa di piu'."""
    pp = mh614_nneg(p_ppa, "p_ppa")
    pm = mh614_nneg(p_mer, "p_mer")
    e = mh614_pos(energia_mwh, "energia_mwh")
    return e * (pp - pm)


def mh614_verdetto(sconto, haircut):
    """Classifica il PPA contro il rischio di prezzo merchant.

    Lo sconto conviene se e' minore o uguale all'haircut di rischio
    che il PPA elimina; soglia di materialita' 3 punti percentuali.
    """
    s = mh614_num(sconto, "sconto")
    h = mh614_nneg(haircut, "haircut")
    if s <= h:
        return {"verdetto": "CONVIENE",
                "msg": "lo sconto del PPA e' minore o uguale all'haircut "
                       "di rischio (VaR95) del mercato: il prezzo fisso "
                       "ripaga il rischio eliminato"}
    if s <= h + 0.03:
        return {"verdetto": "MARGINALE",
                "msg": "lo sconto supera di poco l'haircut di rischio: "
                       "decisione sensibile a volatilita' e orizzonte"}
    return {"verdetto": "NON_CONVIENE",
            "msg": "lo sconto del PPA supera ampiamente il rischio di "
                   "prezzo che elimina: il mercato merchant conviene di piu'"}


def mh614_sensitivita(energia_mwh, p_ppa, prezzi_mer, vols, tasso, anni):
    """Griglia sconto vs haircut su liste di prezzi merchant e volatilita'.

    Ritorna lista di dict {"p_mer", "vol", "sconto", "haircut",
    "ricavo_ppa", "ricavo_prudente", "delta_prudente", "verdetto"}.
    """
    e = mh614_pos(energia_mwh, "energia_mwh")
    pp = mh614_nneg(p_ppa, "p_ppa")
    pms = [mh614_pos(p, "prezzi_mer") for p in prezzi_mer]
    vs = [mh614_nneg(v, "vols") for v in vols]
    if not pms or not vs:
        raise ValueError("prezzi_mer e vols: liste non vuote")
    r_ppa = e * pp
    righe = []
    for pm in pms:
        for v in vs:
            sc = mh614_sconto(pp, pm)
            hc = mh614_haircut(v)
            p_pr = mh614_prezzo_prudente(pm, v)
            r_pr = e * p_pr
            vd = mh614_verdetto(sc, hc)
            righe.append({"p_mer": pm, "vol": v, "sconto": sc,
                          "haircut": hc, "ricavo_ppa": r_ppa,
                          "ricavo_prudente": r_pr,
                          "delta_prudente": r_ppa - r_pr,
                          "verdetto": vd["verdetto"]})
    return righe


def mh614_demo():
    """Parametri demo: 50 GWh/anno, PPA 70, merchant 85, vol 30 %."""
    return {
        "energia_mwh": 50000.0,
        "p_ppa": 70.0,
        "p_mer": 85.0,
        "vol": 0.30,
        "tasso": 0.06,
        "anni": 10,
    }


# W613 (21/10/2026) - tab613 "☀️🪞 FV bifacciale: il guadagno posteriore ripaga il sovraccosto?"
#
# Confronto deterministico monofacciale vs bifacciale per un impianto FV.
# Domanda operativa: "il guadagno di produzione dal lato posteriore
# (albedo) ripaga il sovrapprezzo dei moduli bifacciali?"
#
#   CRF(r, n)  = r*(1+r)^n / ((1+r)^n - 1)  (r = 0 -> 1/n)
#   E_mono     = pot_kwp * yield_front / 1000              [MWh/anno]
#   E_bif      = E_mono * (1 + gain)                        [MWh/anno]
#   capex_bif  = pot_kwp * capex_mono_kwp * (1 + premium)    [eur]
#   LCOE       = (capex_tot * CRF + opex_annuo) / E_annua    [eur/MWh]
#   delta      = LCOE_mono - LCOE_bif                        [eur/MWh]
#   g*         = (capex_bif_kwp*CRF + opex_kwp)
#                / (capex_mono_kwp*CRF + opex_kwp) - 1       [frazione]
#              (gain di break-even: LCOE_bif(g*) = LCOE_mono;
#               premium = 0 -> g* = 0)
#   verdetto   = CONVIENE (delta >= 1.0 eur/MWh, soglia di materialita')
#              / MARGINALE (0 < delta < 1.0) / NON_CONVIENE (delta <= 0)
#
# Ipotesi: stesso opex per le due tecnologie, degrado e disponibilita'
# identici (si elidono nel confronto), anno da 365 giorni implicito
# nello yield, nessun costo del terreno differenziale.


def mh613_num(x, nome):
    """Valida un numero reale finito (bool e stringhe rifiutati)."""
    if isinstance(x, bool) or not isinstance(x, (int, float)):
        raise ValueError(f"{nome}: atteso numero, ricevuto {type(x).__name__}")
    v = float(x)
    if v != v or v in (float("inf"), float("-inf")):
        raise ValueError(f"{nome}: valore non finito")
    return v


def mh613_nneg(x, nome):
    """Numero >= 0."""
    v = mh613_num(x, nome)
    if v < 0.0:
        raise ValueError(f"{nome}: deve essere >= 0, ricevuto {v}")
    return v


def mh613_pos(x, nome):
    """Numero > 0."""
    v = mh613_num(x, nome)
    if v <= 0.0:
        raise ValueError(f"{nome}: deve essere > 0, ricevuto {v}")
    return v


def mh613_frac01(x, nome):
    """Frazione nell'intervallo chiuso [0, 1]."""
    v = mh613_num(x, nome)
    if not 0.0 <= v <= 1.0:
        raise ValueError(f"{nome}: deve stare in [0, 1], ricevuto {v}")
    return v


def mh613_frac01_open(x, nome):
    """Frazione nell'intervallo aperto (0, 1)."""
    v = mh613_num(x, nome)
    if not 0.0 < v < 1.0:
        raise ValueError(f"{nome}: deve stare in (0, 1), ricevuto {v}")
    return v


def mh613_intero(x, nome, vmin, vmax):
    """Intero nell'intervallo chiuso [vmin, vmax] (bool rifiutato)."""
    if isinstance(x, bool) or not isinstance(x, (int, float)):
        raise ValueError(f"{nome}: atteso intero, ricevuto {type(x).__name__}")
    v = float(x)
    if v != int(v):
        raise ValueError(f"{nome}: atteso intero, ricevuto {v}")
    vi = int(v)
    if not vmin <= vi <= vmax:
        raise ValueError(f"{nome}: deve stare in [{vmin}, {vmax}]")
    return vi


def mh613_crf(tasso, anni):
    """Capital recovery factor; tasso = 0 -> 1/anni."""
    r = mh613_nneg(tasso, "tasso")
    n = mh613_intero(anni, "anni", 1, 60)
    if r == 0.0:
        return 1.0 / n
    f = (1.0 + r) ** n
    return r * f / (f - 1.0)


def mh613_energia_annua(pot_kwp, yield_kwh_kwp, gain):
    """Energia annua prodotta [MWh/anno]; gain >= 0 (0 = monofacciale)."""
    pot = mh613_pos(pot_kwp, "pot_kwp")
    yld = mh613_pos(yield_kwh_kwp, "yield_kwh_kwp")
    g = mh613_nneg(gain, "gain")
    return pot * yld / 1000.0 * (1.0 + g)


def mh613_capex_tot(pot_kwp, capex_kwp, premium):
    """Capex totale con sovrapprezzo [eur]; premium >= 0."""
    pot = mh613_pos(pot_kwp, "pot_kwp")
    cx = mh613_nneg(capex_kwp, "capex_kwp")
    pr = mh613_nneg(premium, "premium")
    return pot * cx * (1.0 + pr)


def mh613_opex_annuo(pot_kwp, opex_kwp):
    """Opex annuo totale [eur/anno]."""
    pot = mh613_pos(pot_kwp, "pot_kwp")
    ox = mh613_nneg(opex_kwp, "opex_kwp")
    return pot * ox


def mh613_lcoe(capex_tot, opex_annuo, energia_mwh, tasso, anni):
    """LCOE = (capex*CRF + opex) / energia annua [eur/MWh]."""
    cx = mh613_nneg(capex_tot, "capex_tot")
    ox = mh613_nneg(opex_annuo, "opex_annuo")
    e = mh613_pos(energia_mwh, "energia_mwh")
    crf = mh613_crf(tasso, anni)
    return (cx * crf + ox) / e


def mh613_gain_breakeven(capex_mono_kwp, premium, opex_kwp, tasso, anni):
    """Gain di break-even [frazione]: LCOE_bif(g*) = LCOE_mono.

    premium = 0 -> 0.0 (senza sovrapprezzo basta un gain nullo).
    """
    cx = mh613_nneg(capex_mono_kwp, "capex_mono_kwp")
    pr = mh613_nneg(premium, "premium")
    ox = mh613_nneg(opex_kwp, "opex_kwp")
    if pr == 0.0:
        return 0.0
    crf = mh613_crf(tasso, anni)
    return (cx * (1.0 + pr) * crf + ox) / (cx * crf + ox) - 1.0


def mh613_delta_lcoe(lcoe_mono, lcoe_bif):
    """Differenza LCOE_mono - LCOE_bif [eur/MWh]; > 0 = bifacciale vince."""
    lm = mh613_nneg(lcoe_mono, "lcoe_mono")
    lb = mh613_nneg(lcoe_bif, "lcoe_bif")
    return lm - lb


def mh613_verdetto(delta_lcoe):
    """Classifica il confronto (soglia di materialita' 1 eur/MWh)."""
    d = mh613_num(delta_lcoe, "delta_lcoe")
    if d >= 1.0:
        return {"verdetto": "CONVIENE",
                "msg": "il guadagno posteriore ripaga il sovrapprezzo "
                       "con margine (>= 1 eur/MWh)"}
    if d > 0.0:
        return {"verdetto": "MARGINALE",
                "msg": "bifacciale vince ma di poco (< 1 eur/MWh): "
                       "sensibile alle ipotesi di albedo e opex"}
    return {"verdetto": "NON_CONVIENE",
            "msg": "il sovrapprezzo non e' ripagato dal guadagno posteriore"}


def mh613_sensitivita(pot_kwp, yield_kwh_kwp, capex_mono_kwp, opex_kwp,
                      tasso, anni, gains, premiums):
    """Griglia delta-LCOE su liste di gain e premium [frazioni].

    Ritorna lista di dict {"gain": g, "premium": p, "delta_lcoe": d}.
    """
    pot = mh613_pos(pot_kwp, "pot_kwp")
    yld = mh613_pos(yield_kwh_kwp, "yield_kwh_kwp")
    cx = mh613_nneg(capex_mono_kwp, "capex_mono_kwp")
    ox = mh613_nneg(opex_kwp, "opex_kwp")
    gs = [mh613_nneg(g, "gains") for g in gains]
    ps = [mh613_nneg(p, "premiums") for p in premiums]
    if not gs or not ps:
        raise ValueError("gains e premiums: liste non vuote")
    crf = mh613_crf(tasso, anni)
    ann_mono = pot * cx * crf + pot * ox
    e_mono = pot * yld / 1000.0
    lcoe_mono = ann_mono / e_mono
    righe = []
    for g in gs:
        e_bif = e_mono * (1.0 + g)
        for p in ps:
            ann_bif = pot * cx * (1.0 + p) * crf + pot * ox
            righe.append({"gain": g, "premium": p,
                          "delta_lcoe": lcoe_mono - ann_bif / e_bif})
    return righe


def mh613_demo():
    """Parametri demo: 10 MWp, yield 1150, gain 8 %, premium 4 %."""
    return {
        "pot_kwp": 10000.0,
        "yield_kwh_kwp": 1150.0,
        "gain": 0.08,
        "capex_mono_kwp": 750.0,
        "premium": 0.04,
        "opex_kwp": 12.0,
        "tasso": 0.05,
        "anni": 25,
    }


# W612 (21/10/2026) - tab612 "🔋♻️ Second-life: batterie EV → storage stazionario"
#
# Business case deterministico di uno storage stazionario costruito con
# pacchi batteria da veicoli elettrici a fine vita automotive (second-life).
# Domanda operativa: "con X kWh residui acquistati a prezzo refurbished,
# degrado accelerato e valore di riciclo a fine vita, il VAN e' positivo?"
#
#   E_dis0     = cap_kwh * cicli_giorno * dod / 1000         [MWh/giorno]
#   E_ch0      = E_dis0 / eta                               [MWh/giorno]
#   margine_g  = E_dis0*p_dis - E_ch0*p_ch                   [eur/giorno]
#   cap_t      = cap_kwh * (1 - degrado)^t                   [kWh, t = 0..anni]
#   E_dis_t    = E_dis0 * (1 - degrado)^(t-1) * 365          [MWh/anno]
#   E_ch_t     = E_dis_t / eta                              [MWh/anno]
#   margine_t  = E_dis_t*p_dis - E_ch_t*p_ch                 [eur/anno]
#   capex      = cap_kwh*costo_acq_kwh
#                + cap_kwh*costo_ric_kwh + capex_fisso        [eur]
#   opex_a     = opex_frac * capex                           [eur/anno]
#   riciclo    = cap_anni * valore_riciclo_kwh  (solo t=anni)[eur]
#   flusso_0   = -capex
#   flusso_t   = margine_t - opex_a (+ riciclo se t == anni)  (t = 1..anni)
#   VAN        = somma_t flusso_t / (1+r)^t                   [eur]
#   TIR        = r : VAN(r) = 0 (bisezione su [-0,9999; 10])  [None se assente]
#   payback    = primo t con cumulato >= 0                   [None se mai]
#   LCOS       = VAN(costi) / VAN(E scaricata)               [eur/MWh]
#                costi_0 = capex; costi_t = opex + E_ch_t*p_ch (t>=1);
#                il riciclo NON entra nei costi (e' un incasso)
#   verdetto   = CONVIENE (VAN > 0 e payback <= anni/2)
#              / MARGINALE (VAN > 0) / NON_CONVIENE (altrimenti)
#


def mh612_num(x, nome):
    """Valida un numero reale finito (bool e stringhe rifiutati)."""
    if isinstance(x, bool) or not isinstance(x, (int, float)):
        raise ValueError(f"{nome}: atteso numero, ricevuto {type(x).__name__}")
    v = float(x)
    if v != v or v in (float("inf"), float("-inf")):
        raise ValueError(f"{nome}: valore non finito")
    return v


def mh612_nneg(x, nome):
    """Numero >= 0."""
    v = mh612_num(x, nome)
    if v < 0.0:
        raise ValueError(f"{nome}: deve essere >= 0, ricevuto {v}")
    return v


def mh612_pos(x, nome):
    """Numero > 0."""
    v = mh612_num(x, nome)
    if v <= 0.0:
        raise ValueError(f"{nome}: deve essere > 0, ricevuto {v}")
    return v


def mh612_frac01(x, nome):
    """Frazione nell'intervallo chiuso [0, 1]."""
    v = mh612_num(x, nome)
    if not 0.0 <= v <= 1.0:
        raise ValueError(f"{nome}: deve stare in [0, 1], ricevuto {v}")
    return v


def mh612_frac01_open(x, nome):
    """Frazione nell'intervallo aperto (0, 1)."""
    v = mh612_num(x, nome)
    if not 0.0 < v < 1.0:
        raise ValueError(f"{nome}: deve stare in (0, 1), ricevuto {v}")
    return v


def mh612_intero(x, nome, vmin, vmax):
    """Intero nell'intervallo chiuso [vmin, vmax] (bool rifiutato)."""
    if isinstance(x, bool) or not isinstance(x, (int, float)):
        raise ValueError(f"{nome}: atteso intero, ricevuto {type(x).__name__}")
    v = float(x)
    if v != int(v):
        raise ValueError(f"{nome}: atteso intero, ricevuto {v}")
    vi = int(v)
    if not vmin <= vi <= vmax:
        raise ValueError(f"{nome}: deve stare in [{vmin}, {vmax}]")
    return vi


def mh612_energia_scarica_giorno(cap_kwh, cicli_giorno, dod):
    """Energia scaricabile al giorno con capacita' piena [MWh/giorno]."""
    cap = mh612_pos(cap_kwh, "cap_kwh")
    cicli = mh612_pos(cicli_giorno, "cicli_giorno")
    d = mh612_frac01_open(dod, "dod")
    return cap * cicli * d / 1000.0


def mh612_capacita_residua(cap_kwh, degrado, anno):
    """Capacita' residua a fine anno `anno` con degrado composto [kWh]."""
    cap = mh612_pos(cap_kwh, "cap_kwh")
    d = mh612_frac01_open(degrado, "degrado")
    a = mh612_intero(anno, "anno", 0, 60)
    return cap * (1.0 - d) ** a


def mh612_energie_annue(cap_kwh, cicli_giorno, dod, eta, degrado, anni):
    """Liste annue (anni 1..N) di energia scarica e di carica [MWh/anno].

    Il degrado si applica a fine anno: l'anno t usa il fattore
    (1 - degrado)^(t-1).
    """
    e0 = mh612_energia_scarica_giorno(cap_kwh, cicli_giorno, dod)
    r = mh612_frac01_open(eta, "eta")
    d = mh612_frac01_open(degrado, "degrado")
    n = mh612_intero(anni, "anni", 1, 60)
    e_dis, e_ch = [], []
    for t in range(1, n + 1):
        e = e0 * 365.0 * (1.0 - d) ** (t - 1)
        e_dis.append(e)
        e_ch.append(e / r)
    return {"e_dis": e_dis, "e_ch": e_ch}


def mh612_margine_giorno(e_dis_mwh, eta, p_dis, p_ch):
    """Margine di arbitraggio di un giorno a capacita' piena [eur/giorno]."""
    e = mh612_nneg(e_dis_mwh, "e_dis_mwh")
    r = mh612_frac01_open(eta, "eta")
    pd = mh612_nneg(p_dis, "p_dis")
    pc = mh612_nneg(p_ch, "p_ch")
    return e * pd - (e / r) * pc


def mh612_capex(cap_kwh, costo_acq_kwh, costo_ric_kwh, capex_fisso):
    """Capex: acquisto pacchi + riconversione/test + fisso [eur]."""
    cap = mh612_pos(cap_kwh, "cap_kwh")
    ca = mh612_nneg(costo_acq_kwh, "costo_acq_kwh")
    cr = mh612_nneg(costo_ric_kwh, "costo_ric_kwh")
    cf = mh612_nneg(capex_fisso, "capex_fisso")
    return cap * ca + cap * cr + cf


def mh612_riciclo_fine_vita(cap_kwh, degrado, anni, valore_riciclo_kwh):
    """Incasso dal riciclo dei materiali a fine vita [eur]."""
    cap_n = mh612_capacita_residua(cap_kwh, degrado, anni)
    v = mh612_nneg(valore_riciclo_kwh, "valore_riciclo_kwh")
    return cap_n * v


def mh612_flussi(cap_kwh, cicli_giorno, dod, eta, degrado, p_dis, p_ch,
                 costo_acq_kwh, costo_ric_kwh, capex_fisso, opex_frac,
                 valore_riciclo_kwh, anni):
    """Flussi di cassa anno 0..N [eur]. Anno 0 = -capex."""
    n = mh612_intero(anni, "anni", 1, 60)
    capex = mh612_capex(cap_kwh, costo_acq_kwh, costo_ric_kwh, capex_fisso)
    ox = mh612_frac01(opex_frac, "opex_frac")
    en = mh612_energie_annue(cap_kwh, cicli_giorno, dod, eta, degrado, n)
    pd = mh612_nneg(p_dis, "p_dis")
    pc = mh612_nneg(p_ch, "p_ch")
    opex_a = ox * capex
    riciclo = mh612_riciclo_fine_vita(cap_kwh, degrado, n,
                                      valore_riciclo_kwh)
    flussi = [-capex]
    for t in range(n):
        margine = en["e_dis"][t] * pd - en["e_ch"][t] * pc
        f = margine - opex_a
        if t == n - 1:
            f += riciclo
        flussi.append(f)
    return flussi


def mh612_van(flussi, tasso):
    """Valore attuale netto dei flussi [eur]."""
    if not isinstance(flussi, (list, tuple)) or len(flussi) < 2:
        raise ValueError("flussi: lista con almeno 2 elementi")
    r = mh612_num(tasso, "tasso")
    if r <= -1.0:
        raise ValueError("tasso: deve essere > -1")
    return sum(float(f) / (1.0 + r) ** t
               for t, f in enumerate(flussi))


def mh612_tir(flussi):
    """Tasso interno di rendimento per bisezione; None se non esiste."""
    def _npv(r):
        return sum(float(f) / (1.0 + r) ** t
                   for t, f in enumerate(flussi))
    lo, hi = -0.9999, 10.0
    n_lo, n_hi = _npv(lo), _npv(hi)
    if n_lo * n_hi > 0.0:
        return None
    for _ in range(200):
        mid = (lo + hi) / 2.0
        n_mid = _npv(mid)
        if n_lo * n_mid <= 0.0:
            hi, n_hi = mid, n_mid
        else:
            lo, n_lo = mid, n_mid
        if hi - lo < 1e-10:
            break
    return (lo + hi) / 2.0


def mh612_payback(flussi):
    """Primo anno con cumulato >= 0; None se mai."""
    cum = 0.0
    for t, f in enumerate(flussi):
        cum += float(f)
        if cum >= 0.0:
            return t
    return None


def mh612_lcos(capex, opex_annuo, e_ch_annua, p_ch, e_dis_annua, anni,
               tasso):
    """LCOS = VAN(costi) / VAN(energia scaricata) [eur/MWh].

    Costi: capex all'anno 0, poi opex + energia di carica acquistata.
    Il riciclo e' un incasso e non riduce i costi.
    """
    n = mh612_intero(anni, "anni", 1, 60)
    cx = mh612_nneg(capex, "capex")
    ox = mh612_nneg(opex_annuo, "opex_annuo")
    pc = mh612_nneg(p_ch, "p_ch")
    e_ch = [mh612_nneg(e, "e_ch_annua") for e in e_ch_annua]
    e_dis = [mh612_nneg(e, "e_dis_annua") for e in e_dis_annua]
    if len(e_ch) != n or len(e_dis) != n:
        raise ValueError("liste energia: lunghezza deve essere pari ad anni")
    r = mh612_num(tasso, "tasso")
    if r <= -1.0:
        raise ValueError("tasso: deve essere > -1")
    van_costi = cx
    van_e = 0.0
    for t in range(1, n + 1):
        van_costi += (ox + e_ch[t - 1] * pc) / (1.0 + r) ** t
        van_e += e_dis[t - 1] / (1.0 + r) ** t
    if van_e <= 0.0:
        return None
    return van_costi / van_e


def mh612_verdetto(van, payback, anni):
    """Classifica il business case."""
    v = mh612_num(van, "van")
    anni = mh612_intero(anni, "anni", 1, 60)
    if payback is not None:
        payback = mh612_intero(payback, "payback", 1, 60)
    if v > 0.0 and payback is not None and payback <= anni / 2.0:
        return {"verdetto": "CONVIENE",
                "msg": "VAN positivo con rientro entro meta' vita utile"}
    if v > 0.0:
        return {"verdetto": "MARGINALE",
                "msg": "VAN positivo ma rientro lento o mai entro la vita"}
    return {"verdetto": "NON_CONVIENE",
            "msg": "VAN non positivo: spread, degrado o costi eccessivi"}


