# W611 (21/10/2026) - tab611 "🌬️📦 CAES: l'accumulo ad aria compressa"
#
# Business case deterministico di un impianto CAES (Compressed Air Energy
# Storage) ad aria compressa in caverna salina. Domanda operativa:
# "con P MW di potenza di scarica, h ore/giorno e spread di prezzo
# carica/scarica, il VAN e' positivo?"
#
#   E_dis    = P * h_dis                                    [MWh/giorno]
#   adiabatico: E_ch = E_dis / eta ;  E_fuel = 0
#   diabatico:  E_fuel = HR * E_dis ;                        [MWh_th/giorno]
#               E_ch = E_dis / eta - E_fuel                  [MWh_e/giorno]
#               (eta = E_dis / (E_ch + E_fuel); rifiuta se E_ch < 0)
#   margine_g  = E_dis*p_dis - E_ch*p_ch - E_fuel*costo_fuel [eur/giorno]
#   margine_a  = margine_g * 365 * cicli_giorno              [eur/anno]
#   cap_annuo  = P*1000 * prezzo_cap_kw  (capacity payment)  [eur/anno]
#   capacita   = P*1000*h_dis                              [kWh utili]
#   capex      = P*1000*capex_kw + capacita*capex_kwh
#                + capex_fisso                               [eur]
#   opex_a     = opex_frac * capex                           [eur/anno]
#   flusso_0   = -capex
#   flusso_t   = margine_a + cap_annuo - opex_a  (t = 1..anni)
#   VAN        = somma_t flusso_t / (1+r)^t                  [eur]
#   TIR        = r : VAN(r) = 0 (bisezione su [-0,9999; 10])  [None se assente]
#   payback    = primo t con cumulato >= 0                   [None se mai]
#   LCOS       = VAN(costi) / VAN(E scaricata)               [eur/MWh]
#                costi_t = opex + E_ch*p_ch*365*cicli
#                          + E_fuel*costo_fuel*365*cicli (t>=1), capex in t=0
#   verdetto   = CONVIENE (VAN > 0 e payback <= anni/2)
#              / MARGINALE (VAN > 0) / NON_CONVIENE (altrimenti)
#
# Ipotesi dichiarate in UI: ciclo giornaliero identico tutto l'anno,
# efficienza costante, nessun degrado, anno da 365 giorni, nessun valore
# residuo, capex tutto in anno 0. Screening preliminare, non sostituisce
# uno studio di fattibilita'.
#
# Tutti gli input sono validati (ValueError su bool/non numerici/NaN/inf,
# fuori range dove dichiarato). I letterali sono inline (i test compilano
# ogni funzione in un namespace isolato: le costanti di modulo NON sono
# visibili).


def mh611_num(x, nome):
    """Numero reale finito (rifiuta bool, non numerici, NaN, inf)."""
    import math
    if isinstance(x, bool) or not isinstance(x, (int, float)):
        raise ValueError(f"{nome}: numero atteso")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh611_nneg(x, nome):
    """Numero >= 0."""
    v = mh611_num(x, nome)
    if v < 0.0:
        raise ValueError(f"{nome}: deve essere >= 0")
    return v


def mh611_pos(x, nome):
    """Numero > 0."""
    v = mh611_num(x, nome)
    if v <= 0.0:
        raise ValueError(f"{nome}: deve essere > 0")
    return v


def mh611_frac01(x, nome):
    """Frazione in [0, 1]."""
    v = mh611_num(x, nome)
    if not 0.0 <= v <= 1.0:
        raise ValueError(f"{nome}: deve stare in [0, 1]")
    return v


def mh611_frac01_open(x, nome):
    """Frazione in (0, 1)."""
    v = mh611_num(x, nome)
    if not 0.0 < v < 1.0:
        raise ValueError(f"{nome}: deve stare in (0, 1)")
    return v


def mh611_ore(x, nome):
    """Ore al giorno in [0, 24]."""
    v = mh611_num(x, nome)
    if not 0.0 <= v <= 24.0:
        raise ValueError(f"{nome}: deve stare in [0, 24]")
    return v


def mh611_intero(x, nome, vmin, vmax):
    """Intero in [vmin, vmax] (rifiuta bool, non interi, NaN/inf)."""
    import math
    if isinstance(x, bool) or not isinstance(x, (int, float)):
        raise ValueError(f"{nome}: intero atteso")
    if math.isnan(x) or math.isinf(x) or x != int(x):
        raise ValueError(f"{nome}: deve essere un intero")
    v = int(x)
    if not vmin <= v <= vmax:
        raise ValueError(f"{nome}: deve stare in [{vmin}, {vmax}]")
    return v


def mh611_tipo(t):
    """Tipo impianto: 'adiabatico' o 'diabatico' (normalizzato)."""
    if not isinstance(t, str):
        raise ValueError("tipo: 'adiabatico' o 'diabatico'")
    v = t.strip().lower()
    if v not in ("adiabatico", "diabatico"):
        raise ValueError("tipo: 'adiabatico' o 'diabatico'")
    return v


def mh611_energia_scarica_giorno(potenza_mw, ore_scarica):
    """Energia scaricata in un giorno [MWh/giorno]."""
    p = mh611_pos(potenza_mw, "potenza_mw")
    h = mh611_ore(ore_scarica, "ore_scarica")
    return p * h


def mh611_energia_carica_giorno(e_dis, eta, tipo, heat_rate):
    """Ritorna (E_ch, E_fuel) in MWh/giorno.

    Adiabatico: E_ch = E_dis/eta, E_fuel = 0.
    Diabatico: E_fuel = HR*E_dis, E_ch = E_dis/eta - E_fuel
    (ValueError se eta e' troppo bassa rispetto all'heat rate)."""
    e = mh611_nneg(e_dis, "e_dis")
    r = mh611_frac01_open(eta, "eta")
    tp = mh611_tipo(tipo)
    hr = mh611_nneg(heat_rate, "heat_rate")
    if tp == "adiabatico":
        return e / r, 0.0
    e_fuel = hr * e
    e_ch = e / r - e_fuel
    if e_ch < 0.0:
        raise ValueError("eta troppo bassa rispetto all'heat rate: "
                         "E_ch negativa")
    return e_ch, e_fuel


def mh611_margine_giorno(e_dis, e_ch, e_fuel, p_dis, p_ch, costo_fuel):
    """Margine lordo di un giorno di arbitraggio [eur/giorno]."""
    ed = mh611_nneg(e_dis, "e_dis")
    ec = mh611_nneg(e_ch, "e_ch")
    ef = mh611_nneg(e_fuel, "e_fuel")
    pd = mh611_nneg(p_dis, "p_dis")
    pc = mh611_nneg(p_ch, "p_ch")
    cf = mh611_nneg(costo_fuel, "costo_fuel")
    return ed * pd - ec * pc - ef * cf


def mh611_capex(potenza_mw, e_dis_giorno, capex_kw, capex_kwh, capex_fisso):
    """Capex totale: potenza + capacita' (E_dis in kWh) + fisso [eur]."""
    p = mh611_pos(potenza_mw, "potenza_mw")
    e = mh611_nneg(e_dis_giorno, "e_dis_giorno")
    ck = mh611_nneg(capex_kw, "capex_kw")
    ce = mh611_nneg(capex_kwh, "capex_kwh")
    cf = mh611_nneg(capex_fisso, "capex_fisso")
    return p * 1000.0 * ck + e * 1000.0 * ce + cf


def mh611_flussi(potenza_mw, ore_scarica, eta, tipo, heat_rate, p_dis, p_ch,
                 costo_fuel, capex_kw, capex_kwh, capex_fisso, opex_frac,
                 prezzo_cap_kw, cicli_giorno, anni):
    """Flussi di cassa annui (lista: anno 0 .. anni) [eur]."""
    e_dis = mh611_energia_scarica_giorno(potenza_mw, ore_scarica)
    e_ch, e_fuel = mh611_energia_carica_giorno(e_dis, eta, tipo, heat_rate)
    mg = mh611_margine_giorno(e_dis, e_ch, e_fuel, p_dis, p_ch, costo_fuel)
    cg = mh611_pos(cicli_giorno, "cicli_giorno")
    margine_a = mg * 365.0 * cg
    ck = mh611_nneg(capex_kw, "capex_kw")
    ce = mh611_nneg(capex_kwh, "capex_kwh")
    cfx = mh611_nneg(capex_fisso, "capex_fisso")
    capex = mh611_capex(potenza_mw, e_dis, ck, ce, cfx)
    of = mh611_frac01(opex_frac, "opex_frac")
    opex_a = of * capex
    pk = mh611_nneg(prezzo_cap_kw, "prezzo_cap_kw")
    cap_a = mh611_pos(potenza_mw, "potenza_mw") * 1000.0 * pk
    n = mh611_intero(anni, "anni", 1, 60)
    flusso_a = margine_a + cap_a - opex_a
    return [-capex] + [flusso_a] * n


def mh611_van(flussi, tasso):
    """Valore attuale netto di una lista di flussi (t=0..n) [eur]."""
    if not isinstance(flussi, (list, tuple)) or len(flussi) == 0:
        raise ValueError("flussi: lista non vuota richiesta")
    r = mh611_nneg(tasso, "tasso")
    tot = 0.0
    for t, f in enumerate(flussi):
        tot += mh611_num(f, f"flussi[{t}]") / ((1.0 + r) ** t)
    return tot


def mh611_tir(flussi):
    """Tasso interno di rendimento via bisezione; None se non esiste."""
    if not isinstance(flussi, (list, tuple)) or len(flussi) == 0:
        raise ValueError("flussi: lista non vuota richiesta")
    vals = [mh611_num(f, f"flussi[{i}]") for i, f in enumerate(flussi)]
    if all(v == 0.0 for v in vals):
        return None

    def _npv(r):
        return sum(v / ((1.0 + r) ** t) for t, v in enumerate(vals))

    lo, hi = -0.9999, 10.0
    n_lo, n_hi = _npv(lo), _npv(hi)
    if n_lo == 0.0:
        return lo
    if n_hi == 0.0:
        return hi
    if (n_lo > 0.0) == (n_hi > 0.0):
        return None
    for _ in range(200):
        mid = (lo + hi) / 2.0
        n_mid = _npv(mid)
        if n_mid == 0.0:
            return mid
        if (n_lo > 0.0) == (n_mid > 0.0):
            lo, n_lo = mid, n_mid
        else:
            hi = mid
    return (lo + hi) / 2.0


def mh611_payback(flussi):
    """Primo anno con cumulato >= 0; None se mai (flussi = lista)."""
    if not isinstance(flussi, (list, tuple)) or len(flussi) == 0:
        raise ValueError("flussi: lista non vuota richiesta")
    cum = 0.0
    for t, f in enumerate(flussi):
        cum += mh611_num(f, f"flussi[{t}]")
        if t >= 1 and cum >= 0.0:
            return t
    return None


def mh611_lcos(capex, costo_energia_annuo, e_dis_annua, anni, tasso):
    """LCOS = VAN(costi) / VAN(energia scaricata) [eur/MWh].

    costi_t = costo_energia_annuo (t>=1), capex in t=0."""
    cx = mh611_nneg(capex, "capex")
    ce = mh611_nneg(costo_energia_annuo, "costo_energia_annuo")
    ee = mh611_nneg(e_dis_annua, "e_dis_annua")
    n = mh611_intero(anni, "anni", 1, 60)
    r = mh611_nneg(tasso, "tasso")
    vanc = cx + sum(ce / ((1.0 + r) ** t) for t in range(1, n + 1))
    vane = sum(ee / ((1.0 + r) ** t) for t in range(1, n + 1))
    if vane <= 0.0:
        return None
    return vanc / vane


def mh611_verdetto(van, payback, anni):
    """Classifica il business case."""
    v = mh611_num(van, "van")
    anni = mh611_intero(anni, "anni", 1, 60)
    if payback is not None:
        payback = mh611_intero(payback, "payback", 1, 60)
    if v > 0.0 and payback is not None and payback <= anni / 2.0:
        return {"verdetto": "CONVIENE",
                "msg": "VAN positivo con rientro entro meta' vita utile"}
    if v > 0.0:
        return {"verdetto": "MARGINALE",
                "msg": "VAN positivo ma rientro lento o mai entro la vita"}
    return {"verdetto": "NON_CONVIENE",
            "msg": "VAN non positivo: spread o eta' insufficienti"}


