# W590 (20/10/2026) - tab590 "🧱📐 Bootstrap curva forward (mensile→oraria)"
#
# Bootstrap di una curva forward oraria da 12 prezzi forward mensili
# baseload (€/MWh) e da un profilo orario storico (24 fattori di shape):
# il fattore di ogni ora h e' normalizzato per media = 1
#   f_h = shape_h / media(shape)
# e il prezzo orario del mese m e' monthly[m] * f_h, cosi' la media
# mensile della curva ricostruita coincide con il forward mensile di
# input (coerenza di non-arbitraggio). Restituisce la curva completa
# (12 x 24 = 288 prezzi orari), le medie mensili ricostruite con la
# deviazione massima, le statistiche operative (min, max, media annua,
# media ore di picco 8-19, media ore fuori picco, spread di shape) e un
# verdetto sulla forma: CURVA_PIATTA (ratio max/min < 1,2),
# CURVA_MODERATA (< 3,0), CURVA_ESTREMA (oltre).
# I forward mensili devono essere > 0; i fattori di shape devono essere
# > 0 (un fattore non positivo produrrebbe prezzi nulli o negativi
# incoerenti col forward baseload mensile).
# ValueError: tipi errati, bool, NaN/inf, conteggi diversi da 12 o 24,
# valori non numerici, forward <= 0, shape <= 0.


def mh590_num(x, nome):
    if isinstance(x, bool) or not isinstance(x, (int, float)):
        raise ValueError(f"{nome}: numero atteso")
    import math
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh590_str(x, nome):
    if not isinstance(x, str):
        raise ValueError(f"{nome}: testo atteso")
    _s = x.strip()
    if not _s:
        raise ValueError(f"{nome}: vuoto non ammesso")
    return _s


def mh590_parse_lista(testo, attesi, nome):
    """Parsa `attesi` numeri da testo (virgole, spazi, punti e virgola
    o a capo). ValueError se il conteggio e' diverso da `attesi` o i
    valori non sono numeri finiti."""
    _t = mh590_str(testo, nome)
    import re
    _pezzi = [p for p in re.split(r"[\s,;]+", _t.strip()) if p]
    if len(_pezzi) != attesi:
        raise ValueError(f"{nome}: attesi {attesi} valori, trovati "
                         f"{len(_pezzi)}")
    try:
        _vals = [float(p) for p in _pezzi]
    except ValueError:
        raise ValueError(f"{nome}: valori non numerici")
    return [mh590_num(_v, f"{nome}[{_i}]")
            for _i, _v in enumerate(_vals)]


def mh590_bootstrap(monthly, shape):
    """Bootstrap mensile -> orario della curva forward.

    monthly: 12 forward mensili baseload (€/MWh), tutti > 0.
    shape: 24 fattori di shape oraria, tutti > 0 (profilo storico).
    Ritorna dict con: shape_norm (24 fattori normalizzati, media 1),
    oraria (lista di 288 prezzi: mese m, ora h), medie_mensili (12),
    deviazione_max_ass (max |media ricostruita - forward|),
    min, max, media_annua, media_picco (ore 8..19), media_offpeak,
    spread_shape_pct ((max-min)/1*100, la media normalizzata e' 1),
    ratio_max_min, verdetto (CURVA_PIATTA / CURVA_MODERATA /
    CURVA_ESTREMA) e note.
    """
    if not isinstance(monthly, (list, tuple)) or len(monthly) != 12:
        raise ValueError("monthly: lista di 12 forward mensili")
    if not isinstance(shape, (list, tuple)) or len(shape) != 24:
        raise ValueError("shape: lista di 24 fattori orari")
    _m = [mh590_num(v, f"monthly[{i}]") for i, v in enumerate(monthly)]
    _s = [mh590_num(v, f"shape[{i}]") for i, v in enumerate(shape)]
    for _i, _v in enumerate(_m):
        if _v <= 0:
            raise ValueError(f"monthly[{_i}]: forward deve essere > 0")
    for _i, _v in enumerate(_s):
        if _v <= 0:
            raise ValueError(f"shape[{_i}]: fattore deve essere > 0")
    _media_s = sum(_s) / 24.0
    _fn = [_v / _media_s for _v in _s]
    _oraria = []
    for _mm in range(12):
        for _hh in range(24):
            _oraria.append(_m[_mm] * _fn[_hh])
    _medie = [sum(_oraria[_mm * 24:(_mm + 1) * 24]) / 24.0
              for _mm in range(12)]
    _dev = max(abs(_medie[_mm] - _m[_mm]) for _mm in range(12))
    _min = min(_oraria)
    _max = max(_oraria)
    _media_annua = sum(_oraria) / 288.0
    _picco = [_oraria[_mm * 24 + _hh] for _mm in range(12)
              for _hh in range(8, 20)]
    _offp = [_oraria[_mm * 24 + _hh] for _mm in range(12)
             for _hh in list(range(0, 8)) + list(range(20, 24))]
    _media_picco = sum(_picco) / len(_picco)
    _media_off = sum(_offp) / len(_offp)
    _ratio = max(_fn) / min(_fn)
    if _ratio < 1.2:
        _verd = "CURVA_PIATTA"
    elif _ratio < 3.0:
        _verd = "CURVA_MODERATA"
    else:
        _verd = "CURVA_ESTREMA"
    _note = []
    _note.append("Fattori di shape normalizzati per media = 1: la media "
                 "mensile della curva oraria ricostruita coincide col "
                 "forward mensile di input (non-arbitraggio).")
    _mese_max = max(range(12), key=lambda i: _m[i])
    _mese_min = min(range(12), key=lambda i: _m[i])
    _mesi = ["Gen", "Feb", "Mar", "Apr", "Mag", "Giu", "Lug", "Ago",
             "Set", "Ott", "Nov", "Dic"]
    _note.append(f"Mese piu' caro: {_mesi[_mese_max]} "
                 f"({_m[_mese_max]:.2f} €/MWh); mese piu' economico: "
                 f"{_mesi[_mese_min]} ({_m[_mese_min]:.2f} €/MWh).")
    if _verd == "CURVA_ESTREMA":
        _note.append("Shape molto piccata (ratio max/min >= 3): "
                     "verificare che il profilo storico sia "
                     "rappresentativo, altrimenti la curva sovrastima "
                     "il premio di picco.")
    if _verd == "CURVA_PIATTA":
        _note.append("Shape quasi piatta (ratio < 1,2): la curva oraria "
                     "e' vicina a un baseload mensile costante.")
    return {"shape_norm": _fn, "oraria": _oraria, "medie_mensili": _medie,
            "deviazione_max_ass": _dev, "min": _min, "max": _max,
            "media_annua": _media_annua, "media_picco": _media_picco,
            "media_offpeak": _media_off,
            "spread_shape_pct": (max(_fn) - min(_fn)) * 100.0,
            "ratio_max_min": _ratio, "verdetto": _verd, "note": _note}


def mh590_demo():
    """Default demo: 12 forward mensili (€/MWh) con stagionalita'
    invernale e shape oraria con picco serale."""
    _monthly = [95.0, 92.0, 85.0, 72.0, 65.0, 62.0, 60.0, 63.0,
                70.0, 80.0, 88.0, 96.0]
    _shape = [0.78, 0.74, 0.72, 0.71, 0.72, 0.78, 0.92, 1.08, 1.18,
              1.22, 1.20, 1.16, 1.14, 1.12, 1.10, 1.12, 1.18, 1.28,
              1.38, 1.34, 1.24, 1.10, 0.96, 0.86]
    return {"monthly": _monthly, "shape": _shape}


# W589 (20/10/2026) - tab589 "📉⏳ Curva di durata prezzi"
#
# Curva di durata dei prezzi (price duration curve): data una serie di
# prezzi orari (€/MWh), li ordina in senso decrescente e calcola le
# statistiche che un energy analyst usa per valutare la convenienza di
# un profilo di prelievo/immissione: media (= ricavo di un baseload),
# ore sopra una soglia (strike), prezzo medio delle N ore piu' care
# (= ricavo di un profilo flessibile che produce solo al picco).
# Accetta 24..9000 valori (>= 24 ore = 1 giorno); i prezzi negativi sono
# ammessi (spot puo' andare sotto zero) e segnalati nelle note.
# Verdetti sulla forma della curva, dal rapporto spread/media:
# CURVA_PIATTA (spread < 10% di |media|), CURVA_MODERATA (< 50%),
# CURVA_VOLATILE (oltre). Se la media e' ~0 il denominatore e' lo
# spread stesso (ratio in (0, 1]).
# Note: prezzi tutti uguali, ore con prezzi negativi, strike sopra il
# massimo (nessuna ora sopra soglia) o sotto il minimo (tutte le ore
# sopra soglia).
# ValueError: tipi errati, bool, NaN/inf, numero di valori fuori
# [24, 9000], top_n non intero o fuori [1, n].


def mh589_num(x, nome):
    if isinstance(x, bool) or not isinstance(x, (int, float)):
        raise ValueError(f"{nome}: numero atteso")
    import math
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh589_str(x, nome):
    if not isinstance(x, str):
        raise ValueError(f"{nome}: testo atteso")
    _s = x.strip()
    if not _s:
        raise ValueError(f"{nome}: vuoto non ammesso")
    return _s


def mh589_parse_serie(testo, nome="serie"):
    """Parsa 24..9000 prezzi da testo: numeri (anche negativi) separati
    da virgole, spazi, punti e virgola o a capo. Ritorna la lista di
    float. ValueError se il conteggio e' fuori [24, 9000] o i valori
    non sono numeri finiti."""
    _t = mh589_str(testo, nome)
    import re
    _pezzi = [p for p in re.split(r"[\s,;]+", _t.strip()) if p]
    if len(_pezzi) < 24 or len(_pezzi) > 9000:
        raise ValueError(f"{nome}: attesi 24..9000 valori, trovati "
                         f"{len(_pezzi)}")
    try:
        _vals = [float(p) for p in _pezzi]
    except ValueError:
        raise ValueError(f"{nome}: valori non numerici")
    return [mh589_num(_v, f"{nome}[{_i}]")
            for _i, _v in enumerate(_vals)]


def mh589_percentile(ordinata_asc, q):
    """Percentile q (0..1) con interpolazione lineare su lista
    ordinata crescente."""
    _n = len(ordinata_asc)
    if _n == 1:
        return ordinata_asc[0]
    _pos = q * (_n - 1)
    _lo = int(_pos)
    _hi = min(_lo + 1, _n - 1)
    _f = _pos - _lo
    return ordinata_asc[_lo] * (1.0 - _f) + ordinata_asc[_hi] * _f


def mh589_duration_curve(prezzi, strike, top_n):
    """Curva di durata dei prezzi.

    prezzi: lista di 24..9000 numeri finiti (€/MWh, negativi ammessi).
    strike: soglia €/MWh (numero finito). top_n: intero in [1, n].
    Ritorna dict con: ordinata (decrescente), n, min, max, mean,
    median, std (popolazione), p5, p95, strike, ore_sopra_strike,
    pct_sopra, media_sopra_strike (None se nessuna ora), top_n,
    media_top_n, somma_top_n, n_negativi, quota_negativi_pct,
    verdetto (CURVA_PIATTA / CURVA_MODERATA / CURVA_VOLATILE) e
    note (lista).
    """
    _p = [mh589_num(_v, f"prezzi[{_i}]")
          for _i, _v in enumerate(prezzi)]
    if len(_p) < 24 or len(_p) > 9000:
        raise ValueError("prezzi: attesi 24..9000 valori")
    _s = mh589_num(strike, "strike")
    if isinstance(top_n, bool) or not isinstance(top_n, int):
        raise ValueError("top_n: intero atteso")
    _tn = top_n
    if _tn < 1 or _tn > len(_p):
        raise ValueError("top_n: atteso in [1, n]")
    _n = len(_p)
    _ord = sorted(_p, reverse=True)
    _asc = sorted(_p)
    _mn = _asc[0]
    _mx = _asc[-1]
    _mean = sum(_p) / _n
    _med = mh589_percentile(_asc, 0.5)
    _var = sum((_v - _mean) ** 2 for _v in _p) / _n
    _std = _var ** 0.5
    _p5 = mh589_percentile(_asc, 0.05)
    _p95 = mh589_percentile(_asc, 0.95)
    _sopra = [_v for _v in _p if _v > _s]
    _n_sopra = len(_sopra)
    _media_sopra = (sum(_sopra) / _n_sopra) if _n_sopra else None
    _top = _ord[:_tn]
    _neg = [_v for _v in _p if _v < 0.0]
    _spread = _mx - _mn
    _note = []
    if _spread <= 0.0:
        _verdetto = "CURVA_PIATTA"
        _note.append("Prezzi tutti uguali: la curva di durata e' "
                     "piatta (spread nullo).")
    else:
        _den = abs(_mean) if abs(_mean) > 1e-9 else _spread
        _ratio = _spread / _den
        if _ratio < 0.10:
            _verdetto = "CURVA_PIATTA"
        elif _ratio < 0.50:
            _verdetto = "CURVA_MODERATA"
        else:
            _verdetto = "CURVA_VOLATILE"
    if _neg:
        _note.append(f"{len(_neg)} ore con prezzi negativi "
                     f"(min {_mn:.2f} €/MWh).")
    if _s >= _mx:
        _note.append("Strike sopra il massimo: nessuna ora sopra "
                     "soglia.")
    elif _s < _mn:
        _note.append("Strike sotto il minimo: tutte le ore sopra "
                     "soglia.")
    return {
        "ordinata": _ord,
        "n": _n,
        "min": _mn,
        "max": _mx,
        "mean": _mean,
        "median": _med,
        "std": _std,
        "p5": _p5,
        "p95": _p95,
        "strike": _s,
        "ore_sopra_strike": _n_sopra,
        "pct_sopra": 100.0 * _n_sopra / _n,
        "media_sopra_strike": _media_sopra,
        "top_n": _tn,
        "media_top_n": sum(_top) / _tn,
        "somma_top_n": sum(_top),
        "n_negativi": len(_neg),
        "quota_negativi_pct": 100.0 * len(_neg) / _n,
        "verdetto": _verdetto,
        "note": _note,
    }


def mh589_demo():
    """Demo: 24 prezzi day-ahead (€/MWh) con picco serale, strike
    100 €/MWh, top_n 4."""
    return {
        "serie": [42.0, 38.5, 35.0, 33.2, 34.8, 40.1, 52.3, 68.7,
                  74.2, 70.5, 62.8, 58.4, 55.9, 57.2, 61.6, 69.3,
                  82.4, 98.6, 118.2, 128.4, 112.7, 88.3, 64.2, 50.8],
        "strike": 100.0,
        "top_n": 4,
    }


# W588 (20/10/2026) - tab588 "🔋⏱️ Dispatch ottimale accumulo day-ahead"
#
# Dispatch ottimale giornaliero di un sistema di accumulo sui prezzi
# day-ahead orari: data la curva dei 24 prezzi (€/MWh), trova la
# sequenza di carica/scarica che massimizza il profitto con
# programmazione dinamica sullo stato di carica (SoC) discretizzato.
# Complemento operativo di tab196 (business case con formula chiusa
# Pmax/Pmin, senza struttura temporale): qui la struttura oraria dei
# prezzi decide QUANDO caricare e scaricare.
# Parametri: capacita' E_max (MWh), potenza P_max (MW, limite di
# variazione SoC per ora), efficienze di carica/scarica eta_c/eta_d
# in (0, 1] (lato AC: caricare dE di SoC costa P*dE/eta_c, scaricare
# dE rende P*dE*eta_d), SoC iniziale, vincoli soc_min/soc_max,
# costo di degrado c_deg (€/MWh di throughput lato AC, >= 0),
# risoluzione della discretizzazione (livelli >= 10), SoC finale
# libero oppure vincolato a un valore.
# La DP massimizza il cash flow: V[t][k] = miglior profitto
# all'ora t con SoC al livello k; transizioni |j-k|*dE <= P_max.
# Ricostruzione del percorso ottimo via predecessori.
# Verdetti: NESSUN_ARBITRAGGIO (profitto <= 0: meglio restare fermi,
# es. prezzi piatti o degrado che annulla lo spread) /
# ARBITRAGGIO_PROFITTEVOLE. Note: prezzi piatti, sottoutilizzo della
# capacita' (swing < 5%), throughput nullo.
# ValueError: tipi errati, bool, NaN/inf, prezzi non 24 valori >= 0,
# E_max/P_max <= 0, efficienze non in (0, 100], SoC incoerenti
# (soc_min > soc_max, fuori [0, E_max], soc_ini fuori dai vincoli,
# soc_max == soc_min), c_deg < 0, livelli intero < 10, soc_finale
# fuori dai vincoli.


def mh588_num(x, nome):
    if isinstance(x, bool) or not isinstance(x, (int, float)):
        raise ValueError(f"{nome}: numero atteso")
    import math
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh588_num_nneg(x, nome):
    _v = mh588_num(x, nome)
    if _v < 0.0:
        raise ValueError(f"{nome}: negativo non ammesso")
    return _v


def mh588_pos(x, nome):
    _v = mh588_num(x, nome)
    if _v <= 0.0:
        raise ValueError(f"{nome}: deve essere > 0")
    return _v


def mh588_pctpos(x, nome):
    """Percentuale in (0, 100] (efficienze)."""
    _v = mh588_num(x, nome)
    if _v <= 0.0 or _v > 100.0:
        raise ValueError(f"{nome}: atteso in (0, 100]")
    return _v


def mh588_str(x, nome):
    if not isinstance(x, str):
        raise ValueError(f"{nome}: testo atteso")
    _s = x.strip()
    if not _s:
        raise ValueError(f"{nome}: vuoto non ammesso")
    return _s


def mh588_parse24(testo, nome):
    """Parsa 24 prezzi orari da testo: numeri >= 0 separati da
    virgole, spazi, punti e virgola o a capo. Ritorna la lista di
    24 float. ValueError se il conteggio non e' 24 o i valori non
    sono validi."""
    _t = mh588_str(testo, nome)
    import re
    _pezzi = [p for p in re.split(r"[\s,;]+", _t.strip()) if p]
    if len(_pezzi) != 24:
        raise ValueError(f"{nome}: attesi 24 valori, trovati "
                         f"{len(_pezzi)}")
    try:
        _vals = [float(p) for p in _pezzi]
    except ValueError:
        raise ValueError(f"{nome}: valori non numerici")
    return [mh588_num_nneg(_v, f"{nome}[{_i}]")
            for _i, _v in enumerate(_vals)]


def mh588_dispatch(prezzi, e_max, p_max, eta_c_pct, eta_d_pct, soc_ini,
                   soc_min=0.0, soc_max=None, c_deg=0.0, livelli=100,
                   soc_finale=None):
    """Dispatch ottimale day-ahead via programmazione dinamica.

    prezzi: 24 prezzi orari €/MWh (>= 0). e_max: capacita' MWh > 0.
    p_max: potenza MW > 0 (max |delta SoC| per ora). eta_c_pct /
    eta_d_pct: efficienze % in (0, 100]. soc_ini: SoC iniziale MWh.
    soc_min/soc_max: vincoli (default 0 / e_max). c_deg: €/MWh di
    throughput AC >= 0. livelli: discretizzazione SoC (int >= 10).
    soc_finale: None (libero) o valore vincolato in [soc_min,
    soc_max].
    Ritorna dict con profitto, energie SoC caricata/scaricata,
    throughput AC, cicli equivalenti (= scaricata / e_max),
    costo degrado, ricavo lordo energia, SoC finale, swing max %,
    profilo orario (24 dict: ora, prezzo, soc, delta_soc,
    flusso_rete_mw (+ = immissione), cash), verdetto e note.
    """
    _p = [mh588_num_nneg(_v, f"prezzi[{_i}]")
          for _i, _v in enumerate(prezzi)]
    if len(_p) != 24:
        raise ValueError("prezzi: attesi 24 valori")
    _e = mh588_pos(e_max, "e_max")
    _pw = mh588_pos(p_max, "p_max")
    _ec = mh588_pctpos(eta_c_pct, "eta_c_pct") / 100.0
    _ed = mh588_pctpos(eta_d_pct, "eta_d_pct") / 100.0
    _smin = mh588_num_nneg(soc_min, "soc_min")
    _smax = mh588_num_nneg(e_max if soc_max is None else soc_max,
                           "soc_max")
    if _smin > _smax:
        raise ValueError("soc_min > soc_max")
    if _smax > _e:
        raise ValueError("soc_max > e_max")
    if _smax == _smin:
        raise ValueError("soc_max == soc_min: nessuno spazio di manovra")
    _s0 = mh588_num(soc_ini, "soc_ini")
    if _s0 < _smin or _s0 > _smax:
        raise ValueError("soc_ini fuori dai vincoli [soc_min, soc_max]")
    _cd = mh588_num_nneg(c_deg, "c_deg")
    if not isinstance(livelli, int) or isinstance(livelli, bool) \
            or livelli < 10:
        raise ValueError("livelli: intero >= 10 atteso")
    if soc_finale is not None:
        _sf = mh588_num(soc_finale, "soc_finale")
        if _sf < _smin or _sf > _smax:
            raise ValueError("soc_finale fuori dai vincoli")
    else:
        _sf = None

    _dE = (_smax - _smin) / livelli
    _k0 = min(livelli, max(0, round((_s0 - _smin) / _dE)))
    _step = max(0, int(_pw / _dE))
    _neg = float("-inf")
    # Epsilon anti-cicli-spuri: a parita' di profitto la DP preferisce
    # il percorso con meno movimenti (evita wash-trading a prezzi
    # piatti). 1e-9 € per livello << qualsiasi spread reale.
    _EPS = 1e-9

    # V[k]: miglior profitto all'ora corrente con SoC al livello k
    _V = [_neg] * (livelli + 1)
    _V[_k0] = 0.0
    _pred = []  # _pred[t][k] = livello precedente ottimo
    for _t in range(24):
        _pr = _p[_t]
        _V2 = [_neg] * (livelli + 1)
        _prv = [-1] * (livelli + 1)
        for _k in range(livelli + 1):
            _vk = _V[_k]
            if _vk == _neg:
                continue
            _jmin = max(0, _k - _step)
            _jmax = min(livelli, _k + _step)
            for _j in range(_jmin, _jmax + 1):
                _d = (_j - _k) * _dE  # delta SoC (MWh)
                if _d >= 0.0:
                    _ac = _d / _ec          # energia prelevata da rete
                    _cash = -_pr * _ac - _cd * _ac
                else:
                    _ac = -_d * _ed         # energia immessa in rete
                    _cash = _pr * _ac - _cd * _ac
                _cand = _vk + _cash - _EPS * abs(_j - _k)
                if _cand > _V2[_j]:
                    _V2[_j] = _cand
                    _prv[_j] = _k
        _V = _V2
        _pred.append(_prv)

    if _sf is None:
        _kf = max(range(livelli + 1), key=lambda k: _V[k])
    else:
        _kf = min(livelli, max(0, round((_sf - _smin) / _dE)))
    _profitto = _V[_kf]

    # Ricostruzione del percorso ottimo
    _liv = [_kf]
    for _t in range(23, -1, -1):
        _liv.append(_pred[_t][_liv[-1]])
    _liv.reverse()  # _liv[t] = livello SoC all'INIZIO dell'ora t
    # _liv ha 25 elementi: _liv[24] = livello alla FINE dell'ora 23

    _ore = []
    _car = 0.0
    _sca = 0.0
    _thr = 0.0
    _cdeg = 0.0
    _ric = 0.0
    _smax_visto = _smin + _liv[0] * _dE
    _smin_visto = _smax_visto
    for _t in range(24):
        _k_a = _liv[_t]
        _k_b = _liv[_t + 1]
        _d = (_k_b - _k_a) * _dE
        _soc_a = _smin + _k_a * _dE
        _soc_b = _smin + _k_b * _dE
        if _d >= 0.0:
            _ac = _d / _ec
            _cash = -_p[_t] * _ac - _cd * _ac
            _flusso = -_ac  # prelievo da rete (negativo)
            _car += _d
        else:
            _ac = -_d * _ed
            _cash = _p[_t] * _ac - _cd * _ac
            _flusso = _ac  # immissione in rete (positivo)
            _sca += -_d
        _thr += _ac
        _cdeg += _cd * _ac
        _ric += _cash + _cd * _ac  # ricavo energia al lordo del degrado
        _smax_visto = max(_smax_visto, _soc_b)
        _smin_visto = min(_smin_visto, _soc_b)
        _ore.append({"ora": _t, "prezzo": _p[_t],
                     "soc_inizio": _soc_a, "soc_fine": _soc_b,
                     "delta_soc": _d, "flusso_rete_mw": _flusso,
                     "cash": _cash})
    _swing = (_smax_visto - _smin_visto) / _e * 100.0
    _cicli = _sca / _e if _e > 0 else 0.0

    _note = []
    if len(set(round(_v, 9) for _v in _p)) == 1:
        _note.append("Prezzi piatti sulle 24 ore: nessuno spread da "
                     "arbitrare.")
    if _thr == 0.0 and _profitto <= 0.0:
        _note.append("Dispatch ottimo: restare fermi (nessun ciclo "
                     "profittevole con questi parametri).")
    if 0.0 < _swing < 5.0:
        _note.append(f"Swing di SoC limitato ({_swing:.1f}% della "
                     f"capacita'): capacita' sotto-utilizzata.")
    _verdetto = ("ARBITRAGGIO_PROFITTEVOLE" if _profitto > 0.0
                 else "NESSUN_ARBITRAGGIO")
    return {"profitto": _profitto, "energia_caricata_soc": _car,
            "energia_scaricata_soc": _sca, "throughput_ac": _thr,
            "cicli_equivalenti": _cicli, "costo_degrado": _cdeg,
            "ricavo_lordo_energia": _ric,
            "soc_finale": _smin + _kf * _dE, "swing_max_pct": _swing,
            "ore": _ore, "verdetto": _verdetto, "note": _note,
            "livelli": livelli, "de": _dE}


def mh588_demo():
    """Demo: curva day-ahead realistica (picco serale, flessione
    meridiana da fotovoltaico, minimi notturni)."""
