def mh561_riepilogo(voci, soglia_dominanza=0.5):
    """Analizza le esposizioni -> dict con totali, verdetto, anomalie.

    voci: lista di dict da mh561_voce (puo' essere vuota ->
    NESSUNA_ESPOSIZIONE). quota = esposizione / esposizione totale.
    delta_tot_pct = (tot - tot_prec) / tot_prec (None se tot_prec
    nullo). Verdetti: NESSUNA_ESPOSIZIONE / ANOMALIE_DA_VERIFICARE /
    <TIPO>_DOMINANTE (quota >= soglia_dominanza) /
    ESPOSIZIONI_DIVERSIFICATE.
    """
    _EPS = 1e-9
    _sd = mh561_num(soglia_dominanza, "soglia_dominanza")
    if not 0 < _sd < 1:
        raise ValueError("soglia_dominanza: in (0, 1)")
    if not voci:
        return {"esposizione_totale": 0.0,
                "esposizione_precedente_totale": 0.0,
                "delta_tot_pct": None, "n_voci": 0, "n_tipi": 0,
                "n_anomalie": 0, "verdetto": "NESSUNA_ESPOSIZIONE",
                "per_tipo": [], "analizzate": []}
    _tot = sum(_v["esposizione"] for _v in voci)
    _tot_p = sum(_v["esposizione_precedente"] for _v in voci)
    _per_tipo = {}
    _visti = set()
    _an = []
    _n_an = 0
    for _v in voci:
        _tp = _v["tipo"]
        _pt = _per_tipo.setdefault(_tp, {"esposizione": 0.0, "n": 0})
        _pt["esposizione"] += _v["esposizione"]
        _pt["n"] += 1
        _ano = []
        if _tp in _visti:
            _ano.append("tipo di rischio duplicato (doppia disclosure "
                        "dello stesso tipo)")
        _visti.add(_tp)
        if _v["esposizione"] <= _EPS and (
                _v["origine"] or _v["politiche"] or _v["metodo"]):
            _ano.append("esposizione nulla ma informativa presente "
                        "(incoerenza 7.31)")
        if not _v["origine"]:
            _ano.append("origine non descritta (come si origina "
                        "l'esposizione - IFRS 7.31(a))")
        if not _v["politiche"]:
            _ano.append("politiche di gestione non descritte "
                        "(IFRS 7.31(b))")
        if not _v["metodo"]:
            _ano.append("metodo di misurazione del rischio non indicato "
                        "(IFRS 7.31(b))")
        _n_an += len(_ano)
        _an.append({**_v, "anomalie": _ano,
                    "quota": (_v["esposizione"] / _tot
                              if _tot > _EPS else 0.0)})
    _pt_list = [{"tipo": _tp, "esposizione": _d["esposizione"],
                 "n_voci": _d["n"],
                 "quota": (_d["esposizione"] / _tot
                           if _tot > _EPS else 0.0)}
                for _tp, _d in _per_tipo.items()]
    _dom = max(_pt_list, key=lambda _d: _d["quota"])
    _verdetto = ("ANOMALIE_DA_VERIFICARE" if _n_an > 0
                 else f"{_dom['tipo']}_DOMINANTE"
                 if _dom["quota"] >= _sd
                 else "ESPOSIZIONI_DIVERSIFICATE")
    _dl = ((_tot - _tot_p) / _tot_p) if _tot_p > _EPS else None
    return {"esposizione_totale": _tot,
            "esposizione_precedente_totale": _tot_p,
            "delta_tot_pct": _dl, "n_voci": len(voci),
            "n_tipi": len(_per_tipo), "n_anomalie": _n_an,
            "verdetto": _verdetto, "per_tipo": _pt_list,
            "analizzate": _an}


# W560 (19/10/2026) - tab560 "🧾📝 Informativa sull'hedge accounting (IFRS 7.24A-24F)"
#
# Informativa sull'hedge accounting (IFRS 7 par. 24A-24F): per ogni relazione
# di copertura designata si raccolgono gli elementi qualitativi (24A:
# descrizione della relazione, strumenti di copertura usati e rischi coperti,
# per categoria di rischio e tipo di copertura) e quelli quantitativi (24B:
# valori contabili e nozionali degli strumenti, variazioni di fair value
# dello strumento e dell'elemento coperto usate come base per misurare
# l'inefficacia; 24C: movimenti della riserva OCI per i cash flow hedge e
# importi riclassificati a P&L; 24D: inefficacia dei fair value hedge a P&L).
# L'inefficacia della relazione e' calcolata come
#   inefficacia = delta_fv_strumento + delta_valore_item
# (in una copertura perfetta le due variazioni si compensano); il rapporto
# di inefficacia = |inefficacia| / max(|delta_fv|, |delta_item|) e' la base
# della disclosure 24B. Soglia documentata qui: rapporto >= 10% ->
# INEFFICACIA_SIGNIFICATIVA. Anomalie di coerenza: ID duplicato (doppia
# disclosure della stessa relazione), nozionale nullo (strumento senza
# nozionale da informare, 24A), variazioni nulle (informativa 24B vuota),
# variazioni non compensative (stesso segno di delta_fv e delta_item:
# designazione da verificare). Verdetti: NESSUNA_RELAZIONE /
# ANOMALIE_DA_VERIFICARE / INEFFICACIA_SIGNIFICATIVA (quota =
# somma(|inefficacia|) / nozionale_totale >= 1%) / INFORMATIVA_ADEGUATA.
# Caso tipico energy/ETRM: cash flow hedge su swap gas TTF e forward power
# con riserva OCI movimentata, piu' un fair value hedge sulle scorte.


def mh560_num(x, nome):
    if isinstance(x, bool) or not isinstance(x, (int, float)):
        raise ValueError(f"{nome}: numero atteso")
    import math
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh560_str(x, nome):
    if not isinstance(x, str):
        raise ValueError(f"{nome}: testo atteso")
    _s = x.strip()
    if not _s:
        raise ValueError(f"{nome}: vuoto non ammesso")
    return _s


def mh560_ge0(x, nome):
    _v = mh560_num(x, nome)
    if _v < 0:
        raise ValueError(f"{nome}: non negativo")
    return _v


def mh560_tipo(x):
    _ok = ("CASH_FLOW", "FAIR_VALUE", "NET_INVESTMENT")
    if not isinstance(x, str):
        raise ValueError("tipo: testo atteso")
    _c = x.strip().upper()
    if _c not in _ok:
        raise ValueError(f"tipo: attesa una di {_ok}")
    return _c


def mh560_rischio(x):
    _ok = ("GAS", "POWER", "TASSO_INTERESSE", "CAMBIO")
    if not isinstance(x, str):
        raise ValueError("categoria_rischio: testo atteso")
    _c = x.strip().upper()
    if _c not in _ok:
        raise ValueError(f"categoria_rischio: attesa una di {_ok}")
    return _c


def mh560_relazione(id, tipo, categoria_rischio, strumento, nozionale,
                    vc_strumento, d_fv_strumento, d_valore_item,
                    riserva_oci, riclassificato_pnl):
    """Valida una relazione di copertura e calcola l'inefficacia -> dict.

    id: testo non vuoto; tipo: CASH_FLOW / FAIR_VALUE / NET_INVESTMENT;
    categoria_rischio: GAS / POWER / TASSO_INTERESSE / CAMBIO; strumento:
    descrizione testo; nozionale: EUR >= 0; vc_strumento: valore contabile
    EUR (con segno); d_fv_strumento: variazione di fair value dello
    strumento (base inefficacia, 24B); d_valore_item: variazione di valore
    dell'elemento coperto (base inefficacia, 24B); riserva_oci: saldo
    riserva OCI della relazione (24C, 0 se non cash flow hedge);
    riclassificato_pnl: importo riclassificato da OCI a P&L (24C).
    inefficacia = d_fv_strumento + d_valore_item; rapporto =
    |inefficacia| / max(|d_fv|, |d_val|); esito INEFFICACIA_SIGNIFICATIVA
    se rapporto >= 10% altrimenti INEFFICACIA_CONTENUTA (NESSUNA_VARIAZIONE
    se entrambe le variazioni sono nulle).
    """
    _EPS = 1e-9
    _id = mh560_str(id, "id")
    _tp = mh560_tipo(tipo)
    _rs = mh560_rischio(categoria_rischio)
    _st = mh560_str(strumento, "strumento")
    _no = mh560_ge0(nozionale, "nozionale")
    _vc = mh560_num(vc_strumento, "vc_strumento")
    _df = mh560_num(d_fv_strumento, "d_fv_strumento")
    _di = mh560_num(d_valore_item, "d_valore_item")
    _oc = mh560_num(riserva_oci, "riserva_oci")
    _rp = mh560_num(riclassificato_pnl, "riclassificato_pnl")
    _ineff = _df + _di
    _den = max(abs(_df), abs(_di))
    _rap = abs(_ineff) / _den if _den > _EPS else 0.0
    _esito = ("NESSUNA_VARIAZIONE" if _den <= _EPS
              else "INEFFICACIA_SIGNIFICATIVA" if _rap >= 0.10
              else "INEFFICACIA_CONTENUTA")
    return {"id": _id, "tipo": _tp, "categoria_rischio": _rs,
            "strumento": _st, "nozionale": _no, "vc_strumento": _vc,
            "d_fv_strumento": _df, "d_valore_item": _di,
            "riserva_oci": _oc, "riclassificato_pnl": _rp,
            "inefficacia": _ineff, "rapporto_inefficacia": _rap,
            "esito": _esito}


def mh560_demo():
    """Tre relazioni tipiche di un book energy/ETRM."""
    return [
        mh560_relazione("HR-001", "CASH_FLOW", "GAS", "Swap TTF Cal-27",
                        42000000.0, 3200000.0, 1850000.0, -1790000.0,
                        1790000.0, 220000.0),
        mh560_relazione("HR-002", "CASH_FLOW", "POWER",
                        "Forward baseload DE Q1-27",
                        28000000.0, -1150000.0, -960000.0, 900000.0,
                        900000.0, 85000.0),
        mh560_relazione("HR-003", "FAIR_VALUE", "GAS",
                        "Swap fixed/float su scorte stoccaggio",
                        15000000.0, -480000.0, -410000.0, 385000.0,
                        0.0, 0.0),
    ]


def mh560_riepilogo(relazioni):
    """Analizza le relazioni di copertura -> dict con totali, verdetto,
    anomalie.

    relazioni: lista di dict da mh560_relazione (puo' essere vuota ->
    NESSUNA_RELAZIONE). quota = somma(|inefficacia|) / nozionale_totale.
    Verdetti: NESSUNA_RELAZIONE / ANOMALIE_DA_VERIFICARE /
    INEFFICACIA_SIGNIFICATIVA (quota >= 1%) / INFORMATIVA_ADEGUATA.
    """
    _EPS = 1e-9
    _an = []
    _noz = 0.0
    _ineff = 0.0
    _ineff_abs = 0.0
    _n_an = 0
    _visti = set()
    _tipi = {"CASH_FLOW": 0, "FAIR_VALUE": 0, "NET_INVESTMENT": 0}
    for _r in relazioni:
        _noz += _r["nozionale"]
        _ineff += _r["inefficacia"]
        _ineff_abs += abs(_r["inefficacia"])
        _tipi[_r["tipo"]] += 1
        _ano = []
        _k = _r["id"].strip().lower()
        if _k in _visti:
            _ano.append("ID duplicato (doppia disclosure della stessa "
                        "relazione)")
        _visti.add(_k)
        if _r["nozionale"] <= _EPS:
            _ano.append("nozionale nullo (strumento senza nozionale da "
                        "informare - IFRS 7.24A)")
        _df = _r["d_fv_strumento"]
        _di = _r["d_valore_item"]
        if abs(_df) <= _EPS and abs(_di) <= _EPS:
            _ano.append("variazioni nulle (informativa quantitativa "
                        "24B vuota)")
        elif _df * _di > _EPS:
            _ano.append("variazioni non compensative: stesso segno di "
                        "delta_fv_strumento e delta_valore_item "
                        "(designazione da verificare)")
        _n_an += len(_ano)
        _an.append({**_r, "anomalie": _ano})
    _quota = (_ineff_abs / _noz) if _noz > _EPS else 0.0
    _verdetto = ("NESSUNA_RELAZIONE" if not relazioni
                 else "ANOMALIE_DA_VERIFICARE" if _n_an > 0
                 else "INEFFICACIA_SIGNIFICATIVA" if _quota >= 0.01
                 else "INFORMATIVA_ADEGUATA")
    return {"nozionale_totale": _noz, "inefficacia_totale": _ineff,
            "inefficacia_ass_totale": _ineff_abs,
            "n_relazioni": len(relazioni), "quota_inefficacia": _quota,
            "n_anomalie": _n_an, "verdetto": _verdetto,
            "per_tipo": _tipi, "analizzate": _an}


# W559 (19/10/2026) - tab559 "💸📊 FVA: funding valuation adjustment del portafoglio"
#
# FVA (Funding Valuation Adjustment): costo del finanziamento dell'esposizione
# attesa verso la controparte su derivati OTC non (o parzialmente)
# collateralizzati. Per ciascun netting set:
#   FVA_lordo = somma_b  EE_b * spread_funding * dt_b * DF_b
# dove EE_b = expected exposure in EUR nella fascia b, spread_funding = costo
# del funding proprio (in bps), dt_b = ampiezza della fascia in anni,
# DF_b = 1/(1+r)^t_mid_b con r = tasso di sconto annuo e t_mid_b = punto
# medio della fascia in anni. Fasce fisse (mesi): 0-3, 3-6, 6-12, 12-24,
# 24-60, 60+. Con CSA (collateral agreement) attivo il fabbisogno di funding
# si riduce: FVA = FVA_lordo * 0.5 (haircut semplificato, documentato qui).
# Verdetti: NESSUNA_ESPOSIZIONE / ANOMALIE_DA_VERIFICARE /
# FVA_SIGNIFICATIVO (FVA / EE_totale >= 2%) / FVA_CONTENUTO.
# Anomalie di coerenza: ID duplicato (doppia disclosure dello stesso netting
# set), EE totale nullo (netting set senza esposizione), spread di funding
# nullo (funding non valorizzato). Caso tipico energy/ETRM: portafoglio di
# swap gas/power OTC con un trader senza CSA, dove il desk deve prezzare il
# costo di funding dell'esposizione attesa nel fair value (IFRS 13).


def mh559_num(x, nome):
    if isinstance(x, bool) or not isinstance(x, (int, float)):
        raise ValueError(f"{nome}: numero atteso")
    import math
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    _f = float(x)
    if _f < 0:
        raise ValueError(f"{nome}: non negativo")
    return _f


def mh559_str(x, nome):
    if not isinstance(x, str):
        raise ValueError(f"{nome}: testo atteso")
    _s = x.strip()
    if not _s:
        raise ValueError(f"{nome}: vuoto non ammesso")
    return _s


def mh559_ge0(x, nome):
    return mh559_num(x, nome)


def mh559_bps(x, nome="spread_bps"):
    _v = mh559_num(x, nome)
    if _v > 10000:
        raise ValueError(f"{nome}: max 10000 bps")
    return _v


def mh559_csa(x):
    _ok = ("CSA_SI", "CSA_NO")
    if not isinstance(x, str):
        raise ValueError("csa: testo atteso")
    _c = x.strip().upper()
    if _c not in _ok:
        raise ValueError(f"csa: attesa una di {_ok}")
    return _c


def mh559_netting(id, controparte, ee, spread_bps, tasso_pct, csa):
    """Valida un netting set e calcola il FVA -> dict.

    id: testo non vuoto; controparte: testo non vuoto; ee: sequenza di 6
    numeri >= 0 (expected exposure EUR per fascia 0-3M, 3-6M, 6-12M,
    12-24M, 24-60M, 60M+); spread_bps: 0..10000; tasso_pct: >= 0 (sconto
    annuo); csa: CSA_SI / CSA_NO.
    FVA_lordo = somma_b EE_b * (spread_bps/10000) * dt_b / (1+r)^t_mid_b;
    FVA = FVA_lordo * 0.5 se CSA_SI.
    """
    import math
    _id = mh559_str(id, "id")
    _cp = mh559_str(controparte, "controparte")
    try:
        _ee = [mh559_ge0(_v, f"ee[{_i}]") for _i, _v in enumerate(ee)]
    except TypeError:
        raise ValueError("ee: sequenza di 6 numeri attesa")
    if len(_ee) != 6:
        raise ValueError("ee: attesi 6 valori (fasce 0-3M..60M+)")
    _sp = mh559_bps(spread_bps) / 10000.0
    _r = mh559_ge0(tasso_pct, "tasso_pct") / 100.0
    _cs = mh559_csa(csa)
    _DT = (0.25, 0.25, 0.5, 1.0, 3.0, 3.0)
    _TM = (0.125, 0.375, 0.75, 1.5, 3.5, 7.5)
    _lordo = 0.0
    for _b in range(6):
        _lordo += _ee[_b] * _sp * _DT[_b] * (1.0 + _r) ** (-_TM[_b])
    _fva = _lordo * (0.5 if _cs == "CSA_SI" else 1.0)
    return {"id": _id, "controparte": _cp, "ee": _ee,
            "spread_bps": mh559_bps(spread_bps),
            "tasso_pct": mh559_ge0(tasso_pct, "tasso_pct"),
            "csa": _cs, "ee_totale": sum(_ee),
            "fva_lordo": _lordo, "fva": _fva}


def mh559_demo():
    """Quattro netting set tipici di un book energy/ETRM."""
    return [
        mh559_netting("NET-001", "Utility DE",
                     (8000000.0, 7500000.0, 6000000.0, 4500000.0,
                      2000000.0, 500000.0),
                     85.0, 3.5, "CSA_NO"),
        mh559_netting("NET-002", "Trader TTF",
                     (5000000.0, 6200000.0, 5800000.0, 3000000.0,
                      1200000.0, 300000.0),
                     120.0, 3.5, "CSA_SI"),
        mh559_netting("NET-003", "Offtaker PSV",
                     (2500000.0, 2400000.0, 2200000.0, 1800000.0,
                      1000000.0, 400000.0),
                     200.0, 3.5, "CSA_NO"),
        mh559_netting("NET-004", "Cliente industriale",
                     (1200000.0, 1000000.0, 800000.0, 500000.0,
                      200000.0, 0.0),
                     150.0, 3.5, "CSA_SI"),
    ]


def mh559_riepilogo(nettings):
    """Analizza i netting set -> dict con totali FVA, verdetto, anomalie.

    nettings: lista di dict da mh559_netting (non vuota).
    Verdetti: NESSUNA_ESPOSIZIONE / ANOMALIE_DA_VERIFICARE /
    FVA_SIGNIFICATIVO (FVA / EE_totale >= 2%) / FVA_CONTENUTO.
    """
    if not nettings:
        raise ValueError("nettings: lista non vuota richiesta")
    _EPS = 1e-9
    _an = []
    _ee_tot = 0.0
    _fva_tot = 0.0
    _n_an = 0
    _visti = set()
    for _n in nettings:
        _ee_tot += _n["ee_totale"]
        _fva_tot += _n["fva"]
        _ano = []
        _k = _n["id"].strip().lower()
        if _k in _visti:
            _ano.append("ID duplicato (doppia disclosure dello stesso "
                        "netting set)")
        _visti.add(_k)
        if _n["ee_totale"] <= _EPS:
            _ano.append("EE totale nullo (netting set senza esposizione)")
        if _n["spread_bps"] <= _EPS:
            _ano.append("spread di funding nullo (funding non "
                        "valorizzato)")
        _n_an += len(_ano)
        _q = (_n["fva"] / _n["ee_totale"]) if _n["ee_totale"] > _EPS else 0.0
        _an.append({**_n, "anomalie": _ano, "fva_su_ee": _q})
    _ratio = (_fva_tot / _ee_tot) if _ee_tot > _EPS else 0.0
    _verdetto = ("NESSUNA_ESPOSIZIONE" if _ee_tot <= _EPS
                 else "ANOMALIE_DA_VERIFICARE" if _n_an > 0
                 else "FVA_SIGNIFICATIVO" if _ratio >= 0.02
                 else "FVA_CONTENUTO")
    return {"ee_totale": _ee_tot, "fva_totale": _fva_tot,
            "n_netting": len(nettings), "fva_su_ee": _ratio,
            "n_anomalie": _n_an, "verdetto": _verdetto,
            "analizzati": _an}


# W558 (19/10/2026) - tab558 "📊🔀 Trasferimenti tra livelli fair value (IFRS 7.30)"
#
# IFRS 7.30: per ciascuna classe di strumenti finanziari l'entita' fornisce
# l'informativa sui trasferimenti significativi tra Livello 1 e Livello 2
# della gerarchia del fair value (IFRS 13), indicando:
#   (a) l'importo di ciascun trasferimento tra Livello 1 e Livello 2,
#   (b) i motivi dei trasferimenti,
#   (c) la politica dell'entita' per determinare quando i trasferimenti
#       tra i livelli si considerano avvenuti (inizio periodo / fine
#       periodo / data dell'evento).
# Implementato: registro dei trasferimenti con classe di strumenti,
# direzione (L2_VERSO_L1 = lo strumento passa a prezzi quotati su mercato
# attivo; L1_VERSO_L2 = esce dal mercato attivo e torna a input osservabili
# di modello), importo del fair value trasferito in EUR 7.30(a), motivo
# 7.30(b), politica di rilevazione 7.30(c). Totali per direzione e saldo
# netto verso L1 = trasferito_L2->L1 - trasferito_L1->L2. Anomalie di
# coerenza: importo nullo (trasferimento senza importo), ID duplicato
# (doppia disclosure dello stesso trasferimento), politica di rilevazione
# non uniforme nel registro (7.30(c) richiede una politica coerente).
# Verdetti: NESSUN_TRASFERIMENTO / ANOMALIE_DA_VERIFICARE /
# MIGLIORAMENTO_LIQUIDITA (solo L2->L1: piu' strumenti a prezzi quotati) /
# DETERIORAMENTO_LIQUIDITA (solo L1->L2: strumenti escono dal mercato
# attivo) / TRASFERIMENTI_BILANCIATI. Caso tipico energy/ETRM: un forward
# OTC (L2) che passa a future quotato EEX (L1) quando la consegna diventa
# liquida, o un'opzione che esce dal mercato attivo (L1->L2) per calo dei
# volumi scambiati.


def mh558_num(x, nome):
    if isinstance(x, bool) or not isinstance(x, (int, float)):
        raise ValueError(f"{nome}: numero atteso")
    import math
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    _f = float(x)
    if _f < 0:
        raise ValueError(f"{nome}: non negativo")
    return _f


def mh558_str(x, nome):
    if not isinstance(x, str):
        raise ValueError(f"{nome}: testo atteso")
    _s = x.strip()
    if not _s:
        raise ValueError(f"{nome}: vuoto non ammesso")
    return _s


def mh558_ge0(x, nome):
    return mh558_num(x, nome)


def mh558_direzione(x):
    _ok = ("L2_VERSO_L1", "L1_VERSO_L2")
    if not isinstance(x, str):
        raise ValueError("direzione: testo atteso")
    _d = x.strip().upper()
    if _d not in _ok:
        raise ValueError(f"direzione: attesa una di {_ok}")
    return _d


def mh558_politica(x):
    _ok = ("INIZIO_PERIODO", "FINE_PERIODO", "DATA_EVENTO")
    if not isinstance(x, str):
        raise ValueError("politica: testo atteso")
    _p = x.strip().upper()
    if _p not in _ok:
        raise ValueError(f"politica: attesa una di {_ok}")
    return _p


def mh558_trasferimento(id, classe, direzione, importo_fv, motivo,
                        politica):
    """Valida un trasferimento tra livelli fair value -> dict (IFRS 7.30).

    id: testo non vuoto; classe: classe di strumenti finanziari, testo
    non vuoto; direzione: L2_VERSO_L1 / L1_VERSO_L2; importo_fv: fair value
    trasferito in EUR >= 0 (7.30(a)); motivo: testo non vuoto (7.30(b));
    politica: INIZIO_PERIODO / FINE_PERIODO / DATA_EVENTO (7.30(c)).
    """
    _id = mh558_str(id, "id")
    _cl = mh558_str(classe, "classe")
    _di = mh558_direzione(direzione)
    _im = mh558_ge0(importo_fv, "importo_fv")
    _mo = mh558_str(motivo, "motivo")
    _po = mh558_politica(politica)
    return {"id": _id, "classe": _cl, "direzione": _di,
            "importo_fv": _im, "motivo": _mo, "politica": _po}


