def mh556_riepilogo(classi, soglia_scostamento=0.05):
    if not isinstance(classi, list) or not classi:
        raise ValueError("classi: lista non vuota attesa")
    _sg = soglia_scostamento
    if isinstance(_sg, bool) or not isinstance(_sg, (int, float)):
        raise ValueError("soglia_scostamento: numero atteso")
    import math
    if math.isnan(_sg) or math.isinf(_sg):
        raise ValueError("soglia_scostamento: NaN/inf non ammessi")
    if not 0.0 < float(_sg) <= 1.0:
        raise ValueError("soglia_scostamento: attesa in (0, 1]")
    _sg = float(_sg)
    _an = [mh556_classe(c) for c in classi]
    for _o in _an:
        if (_o["motivo"] == "CV_APPROSSIMA_FV"
                and _o["fair_value"] is not None
                and _o["scostamento"] is not None
                and abs(_o["scostamento"]) > _sg):
            _o["anomalie"].append(
                f"Scostamento {_o['scostamento'] * 100:.2f}% oltre la "
                f"soglia {_sg * 100:.0f}%: l'approssimazione CV=Fair "
                "value non e' credibile (IFRS 7.29(a))")
            _o["status"] = "DA_VERIFICARE"
    _cv = sum(_o["valore_contabile"] for _o in _an)
    _fv = sum(_o["fair_value"] for _o in _an
              if _o["fair_value"] is not None)
    _n_es = sum(1 for _o in _an
                if _o["status"] in ("ESENTE_APPROSSIMAZIONE",
                                    "ESENTE_NON_MISURABILE"))
    _n_an = sum(len(_o["anomalie"]) for _o in _an)
    if _cv == 0:
        _verd = "NESSUNA_CLASSE"
    elif _n_an > 0:
        _verd = "ANOMALIE_DA_VERIFICARE"
    elif _n_es > 0:
        _verd = "ESENZIONI_DOCUMENTATE"
    else:
        _verd = "INFORMATIVA_COMPLETA"
    return {"n_classi": len(_an), "valore_contabile_tot": _cv,
            "fair_value_tot": _fv, "n_esenti": _n_es,
            "n_anomalie": _n_an, "verdetto": _verd, "classi": _an}


# W555 (18/10/2026) - tab555 "📐⚖️ Fair value: movimenti livello 3 (IFRS 7.28)"
#
# IFRS 7.28: per gli strumenti valutati al fair value con tecniche che
# usano input NON osservabili (Livello 3 della gerarchia IFRS 13),
# l'entita' fornisce una riconciliazione dall'apertura alla chiusura del
# periodo, evidenziando separatamente: (a) utili/perdite totali di periodo
# rilevati a conto economico e a OCI; (b) acquisti, emissioni, vendite,
# regolamenti; (c) trasferimenti in entrata e in uscita dal Livello 3.
# Implementato: registro delle posizioni Livello 3 con apertura,
# utili/perdite a P&L (con segno), utili/perdite a OCI (con segno),
# acquisti/emissioni, regolamenti/vendite, trasferimenti in/out; chiusura
# di voce = apertura + P&L + OCI + acquisti - regolamenti + trasf_in -
# trasf_out; variazione netta = chiusura - apertura (in % sull'apertura,
# None se apertura zero) con soglie personalizzabili crescita (default
# 10%) e riduzione (default 10%); anomalie di coerenza: regolamenti oltre
# il detenuto (apertura + acquisti/emissioni + trasferimenti in),
# trasferimenti out oltre il detenuto, chiusura negativa, voce ferma
# senza movimenti di periodo. Verdetti: NESSUNA_VOCE /
# ANOMALIE_DA_VERIFICARE / LIVELLO3_IN_CRESCITA (variazione >= soglia
# crescita) / LIVELLO3_IN_RIDUZIONE (variazione <= -soglia riduzione) /
# LIVELLO3_STABILE.
# Caso tipico energy/ETRM: forward power calendar oltre la curva quotata,
# PPA strutturati e opzioni swing valutati con modelli interni su
# volatilita'/curve non osservabili.


def mh555_num(x, nome):
    if isinstance(x, bool) or not isinstance(x, (int, float)):
        raise ValueError(f"{nome}: numero atteso")
    import math
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    _f = float(x)
    if _f < 0:
        raise ValueError(f"{nome}: non negativo")
    return _f


def mh555_num_signed(x, nome):
    if isinstance(x, bool) or not isinstance(x, (int, float)):
        raise ValueError(f"{nome}: numero atteso")
    import math
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh555_str(x, nome):
    if not isinstance(x, str):
        raise ValueError(f"{nome}: testo atteso")
    _s = x.strip()
    if not _s:
        raise ValueError(f"{nome}: vuoto non ammesso")
    return _s


def mh555_voce(d):
    if not isinstance(d, dict):
        raise ValueError("voce: dict atteso")
    _id = mh555_str(d.get("id"), "id")
    _de = mh555_str(d.get("descrizione"), "descrizione")
    _ap = mh555_num(d.get("apertura"), "apertura")
    _pl = mh555_num_signed(d.get("utili_perdite_pl"), "utili_perdite_pl")
    _oc = mh555_num_signed(d.get("utili_perdite_oci"), "utili_perdite_oci")
    _ac = mh555_num(d.get("acquisti_emissioni"), "acquisti_emissioni")
    _rg = mh555_num(d.get("regolamenti"), "regolamenti")
    _ti = mh555_num(d.get("trasferimenti_in"), "trasferimenti_in")
    _to = mh555_num(d.get("trasferimenti_out"), "trasferimenti_out")
    _chi = _ap + _pl + _oc + _ac - _rg + _ti - _to
    _vn = _chi - _ap
    _vp = _vn / abs(_ap) if _ap != 0 else None
    _det = _ap + _ac + _ti
    _an = []
    if _rg > _det:
        _an.append("Regolamenti/vendite oltre il detenuto (apertura + "
                   "acquisti/emissioni + trasferimenti in) - verificare i "
                   "movimenti (IFRS 7.28(b))")
    if _to > _det:
        _an.append("Trasferimenti in uscita oltre il detenuto (apertura + "
                   "acquisti/emissioni + trasferimenti in) - verificare i "
                   "movimenti (IFRS 7.28(c))")
    if _chi < 0:
        _an.append("Chiusura negativa: i movimenti di periodo superano "
                   "apertura + utili + acquisti - verificare la coerenza "
                   "(IFRS 7.28)")
    if (_ap > 0 and _pl == 0 and _oc == 0 and _ac == 0 and _rg == 0
            and _ti == 0 and _to == 0):
        _an.append("Voce ferma: apertura senza movimenti di periodo - "
                   "verificare la valutazione (IFRS 7.28)")
    return {"id": _id, "descrizione": _de, "apertura": _ap,
            "utili_perdite_pl": _pl, "utili_perdite_oci": _oc,
            "acquisti_emissioni": _ac, "regolamenti": _rg,
            "trasferimenti_in": _ti, "trasferimenti_out": _to,
            "chiusura": _chi, "variazione_netta": _vn,
            "variazione_pct": _vp, "anomalie": _an}


