def mh545_riepilogo(righe):
    if not isinstance(righe, list) or not righe:
        raise ValueError("righe: lista non vuota attesa")
    _an = [mh545_voce(r) for r in righe]
    _vct_tot = sum(_o["valore_contabile_trasferito"] for _o in _an)
    _esp_tot = sum(_o["esposizione_residua"] for _o in _an)
    _quota = (_esp_tot / _vct_tot) if _vct_tot > 0 else None
    _per_esito = {}
    _per_tipo = {}
    for _o in _an:
        _per_esito[_o["esito"]] = _per_esito.get(_o["esito"], 0) + 1
        _per_tipo[_o["tipo"]] = _per_tipo.get(_o["tipo"], 0) + 1
    _n_an = sum(len(_o["anomalie"]) for _o in _an)
    if _quota is not None and _quota >= 0.40:
        _verd = "ESPOSIZIONE_RESIDUA_CRITICA"
    elif _quota is not None and _quota >= 0.20:
        _verd = "ESPOSIZIONE_RESIDUA_TESA"
    else:
        _verd = "INFORMATIVA_ADEGUATA"
    return {"n_voci": len(_an), "valore_contabile_tot": _vct_tot,
            "esposizione_residua_tot": _esp_tot, "quota_residua_pct": _quota,
            "per_esito": _per_esito, "per_tipo": _per_tipo,
            "n_anomalie": _n_an, "verdetto": _verd, "voci": _an}
# W544 (18/10/2026) - tab544 "🏦📥 Collateral & garanzie reali (IFRS 7.15)"
#
# IFRS 7.15: informativa sul collateral (garanzie reali) detenuto o dato
# in pegno a fronte di attivita'/passivita' finanziarie:
#  7.15(a) fair value del collateral detenuto che l'entita' puo' vendere o
#  riescutere in assenza di default (al reporting date);
#  7.15(b) fair value del collateral venduto/riescusso + termini e
#  condizioni di restituzione;
#  7.15(c) termini e condizioni del collateral dato in pegno a garanzia.
# Copertura = FV garanzia / esposizione: COPERTA (>= 100%), SOTTO_GARANZIA
# (50-99%), CRITICA (< 50%), NESSUNA_COPERTURA (FV nullo). Anomalie di
# coerenza: garanzia senza esposizione; collateral escusso ma non
# escutibile (7.15(a) vs 7.15(b)). Il riepilogo aggrega per direzione
# (RICEVUTA/DATA) con copertura di portafoglio.
# Caso tipico energy/ETRM: cash collateral sulle margin call dei derivati
# power/gas, lettere di credito a copertura degli offtaker PPA, pegni su
# titoli per gli shipper gas.


def mh544_num(x, nome):
    if isinstance(x, bool) or not isinstance(x, (int, float)):
        raise ValueError(f"{nome}: numero atteso")
    import math
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh544_str(x, nome):
    if not isinstance(x, str) or not x.strip():
        raise ValueError(f"{nome}: testo non vuoto atteso")
    return x.strip()


def mh544_bool(x, nome):
    if not isinstance(x, bool):
        raise ValueError(f"{nome}: booleano atteso")
    return x


def mh544_dir(x, nome):
    _t = ("RICEVUTA", "DATA")
    if x not in _t:
        raise ValueError(f"{nome}: direzione attesa in {_t}")
    return x


def mh544_tipo(x, nome):
    _t = ("CONTANTE", "TITOLI", "LETTERA_CREDITO", "PEGNO_CREDITI",
          "PEGNO_SCORTE", "GARANZIA_CORPORATE", "ALTRO")
    if x not in _t:
        raise ValueError(f"{nome}: tipo atteso in {_t}")
    return x


def mh544_voce(d):
    if not isinstance(d, dict):
        raise ValueError("voce: dict atteso")
    _id = mh544_str(d.get("id"), "id")
    _desc = mh544_str(d.get("descrizione"), "descrizione")
    _cp = mh544_str(d.get("controparte"), "controparte")
    _esp = mh544_num(d.get("esposizione_eur"), "esposizione_eur")
    _dr = mh544_dir(d.get("direzione"), "direzione")
    _tp = mh544_tipo(d.get("tipo"), "tipo")
    _fv = mh544_num(d.get("fair_value_garanzia"), "fair_value_garanzia")
    _esc = mh544_bool(d.get("escutibile"), "escutibile")
    _esc2 = mh544_bool(d.get("escussa"), "escussa")
    if _esp < 0:
        raise ValueError("esposizione_eur: non negativa")
    if _fv < 0:
        raise ValueError("fair_value_garanzia: non negativo")
    _an = []
    if _esp == 0 and _fv > 0:
        _an.append("garanzia senza esposizione")
    if _esc2 and not _esc:
        _an.append("collateral escusso ma non escutibile (7.15(a) vs 7.15(b))")
    if _esp > 0 and _fv == 0:
        _cop, _esito = 0.0, "NESSUNA_COPERTURA"
    elif _esp == 0:
        _cop, _esito = None, ("COPERTA" if _fv > 0 else "NESSUNA_COPERTURA")
    else:
        _cop = _fv / _esp
        if _cop >= 1.0:
            _esito = "COPERTA"
        elif _cop >= 0.5:
            _esito = "SOTTO_GARANZIA"
        else:
            _esito = "CRITICA"
    return {"id": _id, "descrizione": _desc, "controparte": _cp,
            "esposizione_eur": _esp, "direzione": _dr, "tipo": _tp,
            "fair_value_garanzia": _fv, "escutibile": _esc,
            "escussa": _esc2, "copertura": _cop, "esito": _esito,
            "anomalie": _an}


