def mh543_riepilogo(righe):
    _cat_ok = ("FVTPL", "COSTO_AMMORTIZZATO", "FVOCI")
    if not isinstance(righe, list) or not righe:
        raise ValueError("righe: lista non vuota di voci valutate")
    if len(righe) > 4:
        raise ValueError("righe: massimo 4 voci")
    for _r in righe:
        if not isinstance(_r, dict) or _r.get("categoria") not in _cat_ok:
            raise ValueError("righe: voce non valida")
    _n = len(righe)
    _per = {}
    for _r in righe:
        _per[_r["categoria"]] = _per.get(_r["categoria"], 0.0) + _r[
            "pl_netto"]
    _tot = sum(_r["pl_netto"] for _r in righe)
    _nan = sum(len(_r["anomalie"]) for _r in righe)
    _sabs = sum(abs(_v) for _v in _per.values())
    _dom = max(_per, key=lambda _k: abs(_per[_k]))
    _quota = (abs(_per[_dom]) / _sabs * 100.0) if _sabs > 0 else 0.0
    if _nan > 0:
        _v = "ANOMALIE_DA_VERIFICARE"
    elif _tot > 0.0:
        _v = "REDDITO_NETTO_POSITIVO"
    elif _tot < 0.0:
        _v = "REDDITO_NETTO_NEGATIVO"
    else:
        _v = "PAREGGIO"
    return {"n": _n, "per_categoria": _per, "pl_totale": _tot,
            "categoria_dominante": _dom,
            "quota_dominante_pct": _quota, "n_anomalie": _nan,
            "verdetto": _v}


# W542 (18/10/2026) - tab542 "⚖️📑 Compensazione attività/passività finanziarie (IFRS 7.13A-13F)"
#
# IFRS 7.13A-13F: informativa sulla compensazione (offsetting) di attività
# e passività finanziarie, per classe di strumento o controparte:
#  13C(a) importi lordi rilevati; 13C(b) importi compensati in bilancio
#  secondo IAS 32.42; 13C(c) importi netti presentati nel prospetto;
#  13C(d) importi soggetti ad accordi quadro di compensazione (master
#  netting) o garanzie NON compensati — strumenti finanziari + garanzie in
#  contanti; 13C(e) importo netto dopo (d).
# IAS 32.42: la compensazione in bilancio è ammessa SOLO con (i) diritto
# legale attualmente esigibile di compensare gli importi rilevati e
# (ii) intenzione di regolare su base netta (o di realizzare l'attività e
# regolare la passività simultaneamente). Senza entrambi i requisiti gli
# importi restano lordi in bilancio e il netting va solo in informativa.
# Caso tipico energy/ETRM: MtM dei derivati power/gas per controparte sotto
# accordi quadro ISDA/EEI — il netting riduce l'esposizione creditizia, ma
# in bilancio si compensa solo con diritto + intenzione.


def mh542_num(x, nome):
    if isinstance(x, bool) or not isinstance(x, (int, float)):
        raise ValueError(f"{nome}: numero atteso")
    import math
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh542_str(x, nome):
    if not isinstance(x, str) or not x.strip():
        raise ValueError(f"{nome}: testo non vuoto atteso")
    return x.strip()


def mh542_bool(x, nome):
    if not isinstance(x, bool):
        raise ValueError(f"{nome}: booleano atteso")
    return x


def mh542_voce(d):
    _req = ("id", "descrizione", "controparte", "attivo_lordo",
            "passivo_lordo", "comp_attivo", "comp_passivo",
            "diritto_legale", "intenzione_netto",
            "strumenti_netting", "collateral_cash")
    if not isinstance(d, dict):
        raise ValueError("voce: dict atteso")
    for _k in _req:
        if _k not in d:
            raise ValueError(f"voce: chiave mancante '{_k}'")
    _id = mh542_str(d["id"], "id")
    _de = mh542_str(d["descrizione"], "descrizione")
    _cp = mh542_str(d["controparte"], "controparte")
    _al = mh542_num(d["attivo_lordo"], "attivo_lordo")
    if _al < 0:
        raise ValueError("attivo_lordo: >= 0 atteso")
    _pl = mh542_num(d["passivo_lordo"], "passivo_lordo")
    if _pl < 0:
        raise ValueError("passivo_lordo: >= 0 atteso")
    _ca = mh542_num(d["comp_attivo"], "comp_attivo")
    if _ca < 0 or _ca > _al:
        raise ValueError("comp_attivo: tra 0 e attivo_lordo atteso")
    _cp2 = mh542_num(d["comp_passivo"], "comp_passivo")
    if _cp2 < 0 or _cp2 > _pl:
        raise ValueError("comp_passivo: tra 0 e passivo_lordo atteso")
    _dl = mh542_bool(d["diritto_legale"], "diritto_legale")
    _in = mh542_bool(d["intenzione_netto"], "intenzione_netto")
    _sn = mh542_num(d["strumenti_netting"], "strumenti_netting")
    if _sn < 0:
        raise ValueError("strumenti_netting: >= 0 atteso")
    _cc = mh542_num(d["collateral_cash"], "collateral_cash")
    if _cc < 0:
        raise ValueError("collateral_cash: >= 0 atteso")
    _an = []
    _ammessa = _dl and _in
    if _ca > 0 or _cp2 > 0:
        if _ammessa:
            _es = "COMPENSATA"
            _nota = ("Compensazione in bilancio secondo IAS 32.42: diritto "
                     "legale esigibile + intenzione di regolamento netto "
                     "(IFRS 7.13C(b)-(c)).")
            _anetto = _al - _ca
            _pnetto = _pl - _cp2
        else:
            _es = "COMPENSAZIONE_NON_AMMESSA"
            _nota = ("Importi compensati indicati ma SENZA diritto legale "
                     "esigibile e/o intenzione di regolamento netto: la "
                     "compensazione in bilancio NON è ammessa (IAS 32.42) — "
                     "gli importi restano lordi, verificare l'informativa.")
            _an.append("compensazione senza diritto legale e/o intenzione "
                       "di regolamento netto (IAS 32.42)")
            _anetto = _al
            _pnetto = _pl
    elif _sn > 0 or _cc > 0:
        _es = "SOLO_INFORMATIVA"
        _nota = ("Accordo quadro di compensazione / garanzie esistenti ma "
                 "nessuna compensazione in bilancio (manca diritto o "
                 "intenzione IAS 32.42): solo informativa IFRS 7.13C(d).")
        _anetto = _al
        _pnetto = _pl
    else:
        _es = "NESSUNA_COMPENSAZIONE"
        _nota = "Nessuna compensazione né accordo di netting."
        _anetto = _al
        _pnetto = _pl
    _esp = _anetto - _sn - _cc
    if _sn + _cc > _anetto:
        _an.append("strumenti in netting + garanzie eccedono l'attivo netto "
                   "presentato")
    return {"id": _id, "descrizione": _de, "controparte": _cp,
            "attivo_lordo": _al, "passivo_lordo": _pl,
            "comp_attivo": _ca, "comp_passivo": _cp2,
            "diritto_legale": _dl, "intenzione_netto": _in,
            "strumenti_netting": _sn, "collateral_cash": _cc,
            "compensazione_ammessa": _ammessa,
            "attivo_netto": _anetto, "passivo_netto": _pnetto,
            "esposizione_residua": _esp, "esito": _es, "nota": _nota,
            "anomalie": _an}


