# W508 (17/10/2026) - tab508 "📝 Documentazione della copertura (IFRS 9)"
#
# Checklist di completezza della DOCUMENTAZIONE FORMALE della relazione di
# copertura (IFRS 9 B6.4.13, richiesta alla data di designazione iniziale).
# Senza documentazione formale non c'e' hedge accounting: e' il passo che
# precede i test quantitativi dei tab506 (retrospettivo) e tab507
# (prospettico).
#
# Campi della relazione, con criticita':
#   CRITICI (senza anche uno solo: NON_DESIGNABILE)
#     relazione_id, data_designazione (YYYY-MM-DD, non futura),
#     obiettivo_gestione_rischio, elemento_coperto, strumento_copertura,
#     natura_rischio, hedge_ratio (>0), metodo_valutazione_efficacia
#   OPZIONALI (mancanti -> DOCUMENTAZIONE_PARZIALE)
#     periodicita_rivalutazione, n_scenari_allegati (>=0)
#
# Verdetti: almeno un critico mancante -> NON_DESIGNABILE; critici OK ma
# opzionali mancanti -> DOCUMENTAZIONE_PARZIALE; tutto presente ->
# DOCUMENTAZIONE_COMPLETA. Punteggi: share critici presenti e share totale.
#
# NOTA: le funzioni sono estratte da app.py via AST (tests/appfuncs.py) e
# devono essere autocontenute: import inline, nessuna costante di modulo.
# ===========================================================================


def mh508_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh508_data(x, nome="data_designazione"):
    """Valida YYYY-MM-DD e rifiuta date future. Ritorna datetime.date o None."""
    import datetime as _dt508
    if x is None:
        return None
    if not isinstance(x, str) or not x.strip():
        return None
    _t = x.strip()
    try:
        _p = _t.split("-")
        if len(_p) != 3 or len(_t) != 10 or _t[4] != "-" or _t[7] != "-":
            raise ValueError()
        _d = _dt508.date(int(_p[0]), int(_p[1]), int(_p[2]))
    except (ValueError, TypeError):
        raise ValueError(f"{nome}: formato YYYY-MM-DD richiesto")
    if _d > _dt508.date.today():
        raise ValueError(f"{nome}: non puo' essere futura")
    return _d


def mh508_campo(nome, valore, critico):
    """Valuta un singolo campo: presente/mancante, con motivo.

    Ritorna dict {nome, etichetta, critico, presente, valore, nota}.
    None/"" -> mancante (non errore). Tipi incoerenti sui campi tipizzati
    (hedge_ratio, data, n_scenari) -> ValueError.
    """
    _etichette = {
        "relazione_id": "ID relazione",
        "data_designazione": "Data designazione",
        "obiettivo_gestione_rischio": "Obiettivo gestione rischio",
        "elemento_coperto": "Elemento coperto",
        "strumento_copertura": "Strumento di copertura",
        "natura_rischio": "Natura del rischio",
        "hedge_ratio": "Hedge ratio",
        "metodo_valutazione_efficacia": "Metodo valutazione efficacia",
        "periodicita_rivalutazione": "Periodicita' rivalutazione",
        "n_scenari_allegati": "Scenari allegati",
    }
    if nome not in _etichette:
        raise ValueError(f"campo sconosciuto: {nome}")
    _base = {"nome": nome, "etichetta": _etichette[nome],
             "critico": bool(critico)}
    if nome == "data_designazione":
        _d = mh508_data(valore)
        _ok = _d is not None
        _base.update({"presente": _ok,
                      "valore": _d.isoformat() if _d else "",
                      "nota": "" if _ok else "data mancante o non valida"})
        return _base
    if nome == "hedge_ratio":
        if valore is None or (isinstance(valore, str)
                              and not valore.strip()):
            _base.update({"presente": False, "valore": "",
                          "nota": "hedge ratio mancante"})
            return _base
        _r = mh508_num(valore, "hedge_ratio")
        if _r <= 0.0:
            raise ValueError("hedge_ratio: deve essere > 0")
        _base.update({"presente": True, "valore": f"{_r:.4f}", "nota": ""})
        return _base
    if nome == "n_scenari_allegati":
        if valore is None or (isinstance(valore, str)
                              and not valore.strip()):
            _base.update({"presente": False, "valore": "",
                          "nota": "n. scenari non indicato"})
            return _base
        if isinstance(valore, bool):
            raise ValueError("n_scenari_allegati: intero >= 0 richiesto")
        _iv = int(valore) if isinstance(valore, (int, float)) and \
            float(valore).is_integer() else None
        if _iv is None or _iv < 0:
            raise ValueError("n_scenari_allegati: intero >= 0 richiesto")
        _base.update({"presente": True, "valore": str(_iv), "nota": ""})
        return _base
    # campi testo: presente solo se stringa non vuota (dopo strip)
    _ok = isinstance(valore, str) and bool(valore.strip())
    _base.update({"presente": _ok,
                  "valore": valore.strip() if _ok else "",
                  "nota": "" if _ok else "campo mancante"})
    return _base


def mh508_doc(relazione_id, data_designazione, obiettivo_gestione_rischio,
              elemento_coperto, strumento_copertura, natura_rischio,
              hedge_ratio, metodo_valutazione_efficacia,
              periodicita_rivalutazione=None, n_scenari_allegati=None):
    """Valuta la completezza del dossier di designazione.

    Ritorna verdetto, punteggi, conteggi mancanti e checklist riga per riga.
    """
    _critici = ("relazione_id", "data_designazione",
                "obiettivo_gestione_rischio", "elemento_coperto",
                "strumento_copertura", "natura_rischio", "hedge_ratio",
                "metodo_valutazione_efficacia")
    _in = [("relazione_id", relazione_id, True),
           ("data_designazione", data_designazione, True),
           ("obiettivo_gestione_rischio", obiettivo_gestione_rischio, True),
           ("elemento_coperto", elemento_coperto, True),
           ("strumento_copertura", strumento_copertura, True),
           ("natura_rischio", natura_rischio, True),
           ("hedge_ratio", hedge_ratio, True),
           ("metodo_valutazione_efficacia", metodo_valutazione_efficacia,
            True),
           ("periodicita_rivalutazione", periodicita_rivalutazione, False),
           ("n_scenari_allegati", n_scenari_allegati, False)]
    _campi = [mh508_campo(n, v, c) for n, v, c in _in]
    _miss_c = sum(1 for c in _campi if c["critico"] and not c["presente"])
    _miss_o = sum(1 for c in _campi if not c["critico"] and not c["presente"])
    _n_c = len(_critici)
    _n_t = len(_in)
    if _miss_c:
        _vd = "NON_DESIGNABILE"
    elif _miss_o:
        _vd = "DOCUMENTAZIONE_PARZIALE"
    else:
        _vd = "DOCUMENTAZIONE_COMPLETA"
    return {"verdetto": _vd,
            "punteggio_critici": (_n_c - _miss_c) / _n_c,
            "punteggio_totale": (_n_t - _miss_c - _miss_o) / _n_t,
            "mancanti_critici": _miss_c,
            "mancanti_opzionali": _miss_o,
            "n_campi": _n_t,
            "campi": _campi}


def mh508_riepilogo(relazione_id, data_designazione,
                    obiettivo_gestione_rischio, elemento_coperto,
                    strumento_copertura, natura_rischio, hedge_ratio,
                    metodo_valutazione_efficacia,
                    periodicita_rivalutazione=None,
                    n_scenari_allegati=None):
    """Sintesi della checklist (alias di mh508_doc, per la UI)."""
    return mh508_doc(relazione_id, data_designazione,
                     obiettivo_gestione_rischio, elemento_coperto,
                     strumento_copertura, natura_rischio, hedge_ratio,
                     metodo_valutazione_efficacia,
                     periodicita_rivalutazione, n_scenari_allegati)


# W507 (16/10/2026) - tab507 "🔭 Test prospettico di efficacia (scenari forward)"
#
# Test PROSPETTICO di efficacia di una cash-flow hedge (IFRS 9): mentre il
# tab506 valuta retrospettivamente la copertura con l'OLS sui ΔFV osservati,
# qui si verifica che il rapporto di copertura regga in AVANTI su scenari
# di movimento del sottostante (forward price moves), con sensibilita'
# (DV01) eventualmente diverse per scenario (es. convessita' dello
# strumento di copertura).
#
# Modello (per scenario s, con move m in €/MWh del sottostante):
#   ΔH_s = dv01_h_s * m            (ΔFV elemento coperto)
#   ΔI_s = -dv01_i_s * n * m       (ΔFV strumento, n = n. contratti)
#   ratio_s = -ΔI_s / ΔH_s = dv01_i_s * n / dv01_h_s   (m si semplifica;
#              e' > 0 quando le sensibilita' sono positive)
#   rapporto_credito_s = ecl / |ΔI_s|   (ecl = perdita creditizia attesa
#              stimata sul derivato, CVA; IFRS 9: l'effetto del rischio di
#              credito non deve dominare la relazione di copertura)
#
# Verdetti per scenario (EPS=1e-9 sui bordi):
#   |m| <= 1e-12                             -> NON_VALUTABILE
#   rapporto_credito > soglia_credito         -> RISCHIO_CREDITO
#   banda_inf <= ratio <= banda_sup           -> IN_BANDA
#   altrimenti                               -> FUORI_BANDA
# Verdetto complessivo:
#   almeno un FUORI_BANDA  -> NON_EFFICACE
#   almeno un RISCHIO_CREDITO -> A_RISCHIO
#   almeno un IN_BANDA      -> PROSPETTICAMENTE_EFFICACE
#   solo NON_VALUTABILE     -> NON_VALUTABILE
#
# Hedge ratio ottimale (contratti per offset pieno al move unitario):
#   hr* = dv01_h_base / dv01_i_base
#
# Vincoli: >= 3 scenari, liste stessa lunghezza, numeri finiti (NaN/inf
# vietati); dv01_h, dv01_i, n_contratti > 0; ecl >= 0;
# 0 < banda_inf <= banda_sup; 0 <= soglia_credito <= 1.
# ===========================================================================


def mh507_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh507_pos(x, nome):
    _v = mh507_num(x, nome)
    if _v <= 0.0:
        raise ValueError(f"{nome}: deve essere > 0")
    return _v


def mh507_nonneg(x, nome):
    _v = mh507_num(x, nome)
    if _v < 0.0:
        raise ValueError(f"{nome}: deve essere >= 0")
    return _v


def mh507_str(x, nome):
    if not isinstance(x, str) or not x.strip():
        raise ValueError(f"{nome}: testo non vuoto richiesto")
    return x.strip()


def mh507_scenario(move, dv01_h, dv01_i, n, ecl, banda_inf=0.8,
                   banda_sup=1.25, soglia_credito=0.05):
    """Valuta un singolo scenario forward. Ritorna il dict di scenario."""
    _m = mh507_num(move, "move")
    _dh = mh507_pos(dv01_h, "dv01_coperto")
    _di = mh507_pos(dv01_i, "dv01_strumento")
    _n = mh507_pos(n, "n_contratti")
    _ecl = mh507_nonneg(ecl, "ecl")
    _bi = mh507_num(banda_inf, "banda_inf")
    _bs = mh507_num(banda_sup, "banda_sup")
    _sc = mh507_num(soglia_credito, "soglia_credito")
    if not 0.0 < _bi <= _bs:
        raise ValueError("banda_inf/banda_sup: 0 < inf <= sup richiesto")
    if not 0.0 <= _sc <= 1.0:
        raise ValueError("soglia_credito: compresa tra 0 e 1 richiesta")
    _EPS = 1e-9
    _dH = _dh * _m
    _dI = -_di * _n * _m
    if abs(_m) <= 1e-12:
        return {"move_eur_mwh": _m, "dv01_coperto": _dh,
                "dv01_strumento": _di, "delta_coperto_eur": _dH,
                "delta_strumento_eur": _dI, "ratio_offset": None,
                "rapporto_credito": None, "verdetto": "NON_VALUTABILE"}
    _ratio = -_dI / _dH
    _cred = _ecl / abs(_dI) if abs(_dI) > 0.0 else float("inf")
    if _cred > _sc + _EPS:
        _vd = "RISCHIO_CREDITO"
    elif _bi - _EPS <= _ratio <= _bs + _EPS:
        _vd = "IN_BANDA"
    else:
        _vd = "FUORI_BANDA"
    return {"move_eur_mwh": _m, "dv01_coperto": _dh,
            "dv01_strumento": _di, "delta_coperto_eur": _dH,
            "delta_strumento_eur": _dI, "ratio_offset": _ratio,
            "rapporto_credito": _cred, "verdetto": _vd}


def mh507_test(etichette, moves, dv01hs, dv01is, n_contratti, ecl,
               dv01_h_base, dv01_i_base, banda_inf=0.8, banda_sup=1.25,
               soglia_credito=0.05):
    """Test prospettico sugli scenari: statistiche + verdetto complessivo.

    moves/dv01hs/dv01is: liste di pari lunghezza (>= 3 scenari).
    dv01_h_base/dv01_i_base: sensibilita' di riferimento per l'hedge ratio
    ottimale. Ritorna verdetto, hedge_ratio_ottimale, ratio min/max e righe.
    """
    _labs = [mh507_str(e, f"etichetta[{i}]")
             for i, e in enumerate(etichette)] if etichette is not None \
        else []
    _n = len(_labs)
    for nome, lst in (("moves", moves), ("dv01_coperto", dv01hs),
                      ("dv01_strumento", dv01is)):
        if not isinstance(lst, (list, tuple)) or len(lst) != _n:
            raise ValueError(f"{nome}: stessa lunghezza delle etichette "
                             "richiesta")
    if _n < 3:
        raise ValueError("servono almeno 3 scenari")
    _nct = mh507_pos(n_contratti, "n_contratti")
    _dhb = mh507_pos(dv01_h_base, "dv01_coperto_base")
    _dib = mh507_pos(dv01_i_base, "dv01_strumento_base")
    _hr = _dhb / _dib
    _righe = [dict({"scenario": _labs[i]},
                   **mh507_scenario(moves[i], dv01hs[i], dv01is[i], _nct,
                                    ecl, banda_inf, banda_sup,
                                    soglia_credito)) for i in range(_n)]
    _vds = [_r["verdetto"] for _r in _righe]
    if "FUORI_BANDA" in _vds:
        _vd = "NON_EFFICACE"
    elif "RISCHIO_CREDITO" in _vds:
        _vd = "A_RISCHIO"
    elif "IN_BANDA" in _vds:
        _vd = "PROSPETTICAMENTE_EFFICACE"
    else:
        _vd = "NON_VALUTABILE"
    _ratios = [_r["ratio_offset"] for _r in _righe
               if _r["ratio_offset"] is not None]
    return {"n_scenari": _n, "verdetto": _vd,
            "hedge_ratio_ottimale": _hr,
            "ratio_min": min(_ratios) if _ratios else None,
            "ratio_max": max(_ratios) if _ratios else None,
            "n_contratti": _nct,
            "banda": (mh507_num(banda_inf, "banda_inf"),
                      mh507_num(banda_sup, "banda_sup")),
            "soglia_credito": mh507_num(soglia_credito, "soglia_credito"),
            "righe": _righe}


def mh507_riepilogo(etichette, moves, dv01hs, dv01is, n_contratti, ecl,
                    dv01_h_base, dv01_i_base, banda_inf=0.8, banda_sup=1.25,
                    soglia_credito=0.05):
    """Sintesi del test prospettico (alias di mh507_test, per la UI)."""
    return mh507_test(etichette, moves, dv01hs, dv01is, n_contratti, ecl,
                      dv01_h_base, dv01_i_base, banda_inf, banda_sup,
                      soglia_credito)


# W506 (16/10/2026) - tab506 "📉 Regressione di efficacia (OLS)"
#
# Test quantitativo di efficacia di una cash-flow hedge (IFRS 9): regressione
# OLS dei ΔFV dello strumento di copertura (y) sui ΔFV dell'elemento coperto
# (x), una osservazione per periodo. La copertura e' efficace se lo strumento
# compensa l'elemento coperto in modo stabile e proporzionale.
#
# Modello:
#   y = a + b*x + eps ;  b_hat = Sxy/Sxx ;  a_hat = ybar - b_hat*xbar
#   R2 = 1 - SSE/SST ;  se(b) = sqrt(s2/Sxx) con s2 = SSE/(n-2)
#   t = (b+1)/se(b) ;  p = 2*P(T>|t|), T ~ t(n-2)  (H0: b = -1, offset pieno)
#
# Verdetti (EPS=1e-9 sui bordi; la banda eredita lo standard 80-125% dello
# IAS 39; IFRS 9 non impone soglie rigide: i parametri sono modificabili
# in UI; t e p-value sono informativi e NON entrano nel verdetto):
#   b >= 0                              -> INEFFICACE (segno errato: lo
#                                          strumento amplifica invece di
#                                          compensare)
#   b < 0, banda_inf <= |b| <= banda_sup,
#   R2 >= r2_min                        -> EFFICACE
#   b < 0, in banda ma R2 < r2_min       -> EFFICACE_CON_RISERVA (fit debole:
#                                          la compensazione media c'e' ma
#                                          e' instabile nel tempo)
#   altrimenti (|b| fuori banda)        -> INEFFICACE
#
# Vincoli: serie di >= 3 osservazioni, stessa lunghezza, numeri finiti
# (NaN/inf vietati); varianza di x > 0 (Sxx <= 0 -> ValueError);
# 0 < banda_inf <= banda_sup; 0 <= r2_min <= 1.
# ===========================================================================


def mh506_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh506_str(x, nome):
    if not isinstance(x, str) or not x.strip():
        raise ValueError(f"{nome}: testo non vuoto richiesto")
    return x.strip()


def mh506_serie(vals, nome):
    """Valida una serie di ΔFV: sequenza di >= 3 numeri finiti."""
    if not isinstance(vals, (list, tuple)) or len(vals) < 3:
        raise ValueError(f"{nome}: servono almeno 3 osservazioni")
    return [mh506_num(v, f"{nome}[{i}]")
            for i, v in enumerate(vals)]


def mh506_ols(x, y):
    """OLS di y su x: ritorna slope, intercept, r2, se_slope, t, p_value, n.

    t e p_value: test bilaterale H0: slope = -1 (offset pieno della
    copertura) con T ~ t(n-2). p e' informativo, non entra nei verdetti.
    """
    import numpy as np
    from scipy.stats import t as _tdist
    _x = np.array(mh506_serie(x, "delta_coperto"), dtype=float)
    _y = np.array(mh506_serie(y, "delta_strumento"), dtype=float)
    if _x.shape[0] != _y.shape[0]:
        raise ValueError("delta_coperto e delta_strumento: stessa lunghezza "
                         "richiesta")
    _n = int(_x.shape[0])
    _EPS = 1e-9
    _xb, _yb = float(_x.mean()), float(_y.mean())
    _Sxx = float(((_x - _xb) ** 2).sum())
    if _Sxx <= 0.0:
        raise ValueError("delta_coperto: varianza nulla, regressione "
                         "impossibile")
    _Sxy = float(((_x - _xb) * (_y - _yb)).sum())
    _Syy = float(((_y - _yb) ** 2).sum())
    _b = _Sxy / _Sxx
    _a = _yb - _b * _xb
    _yhat = _a + _b * _x
    _SSE = float(((_y - _yhat) ** 2).sum())
    _r2 = 0.0 if _Syy <= _EPS else max(0.0, 1.0 - _SSE / _Syy)
    _s2 = _SSE / (_n - 2)
    _se = (_s2 / _Sxx) ** 0.5
    if _se <= 0.0:
        _t, _p = (0.0, 1.0) if abs(_b + 1.0) <= _EPS else (
            float("inf") if _b + 1.0 > 0 else float("-inf"), 0.0)
    else:
        _t = (_b + 1.0) / _se
        _p = float(2.0 * _tdist.sf(abs(_t), _n - 2))
    return {"n": _n, "slope": _b, "intercept": _a, "r2": _r2,
            "se_slope": _se, "t_stat": _t, "p_value": _p}


def mh506_test(x, y, banda_inf=0.8, banda_sup=1.25, r2_min=0.8):
    """Verdetto di efficacia della copertura dai ΔFV per periodo.

    x: ΔFV elemento coperto; y: ΔFV strumento di copertura.
    banda_inf/banda_sup: banda accettabile per |slope| (default 0.8/1.25);
    r2_min: R2 minimo (default 0.8). Ritorna le statistiche OLS +
    verdict: EFFICACE / EFFICACE_CON_RISERVA / INEFFICACE.
    """
    _bi = mh506_num(banda_inf, "banda_inf")
    _bs = mh506_num(banda_sup, "banda_sup")
    _r2m = mh506_num(r2_min, "r2_min")
    if not 0.0 < _bi <= _bs:
        raise ValueError("banda_inf/banda_sup: 0 < inf <= sup richiesto")
    if not 0.0 <= _r2m <= 1.0:
        raise ValueError("r2_min: compreso tra 0 e 1 richiesto")
    _st = mh506_ols(x, y)
    _EPS = 1e-9
    _absb = abs(_st["slope"])
    if _st["slope"] >= -_EPS:
        _vd = "INEFFICACE"
    elif _bi - _EPS <= _absb <= _bs + _EPS and _st["r2"] >= _r2m - _EPS:
        _vd = "EFFICACE"
    elif _bi - _EPS <= _absb <= _bs + _EPS:
        _vd = "EFFICACE_CON_RISERVA"
    else:
        _vd = "INEFFICACE"
    _st.update({"banda_inf": _bi, "banda_sup": _bs, "r2_min": _r2m,
                "verdetto": _vd,
                "h0_non_rifiutata": _st["p_value"] >= 0.05})
    return _st


def mh506_riepilogo(etichette, x, y, banda_inf=0.8, banda_sup=1.25,
                    r2_min=0.8):
    """Sintesi del test di efficacia: statistiche + righe per periodo."""
    _st = mh506_test(x, y, banda_inf, banda_sup, r2_min)
    _n = _st["n"]
    _lab = [mh506_str(e, f"etichetta[{i}]")
            for i, e in enumerate(etichette)] if etichette is not None else \
        [f"P{i + 1}" for i in range(_n)]
    if len(_lab) != _n:
        raise ValueError("etichette: una per osservazione richiesta")
    _xs = mh506_serie(x, "delta_coperto")
    _ys = mh506_serie(y, "delta_strumento")
    _righe = [{"periodo": _lab[i], "delta_coperto_eur": _xs[i],
               "delta_strumento_eur": _ys[i],
               "offset_eur": _xs[i] + _ys[i]} for i in range(_n)]
    return {"n_periodi": _n, "verdetto": _st["verdetto"],
            "slope": _st["slope"], "intercept": _st["intercept"],
            "r2": _st["r2"], "se_slope": _st["se_slope"],
            "t_stat": _st["t_stat"], "p_value": _st["p_value"],
            "h0_non_rifiutata": _st["h0_non_rifiutata"],
            "banda": (_st["banda_inf"], _st["banda_sup"]),
            "r2_min": _st["r2_min"], "righe": _righe}


# W505 (16/10/2026) - tab505 "♻️ Recycling OCI: rilascio della riserva a P&L"
#
# Recycling della riserva OCI (IFRS 9, cash-flow hedge): quando l'elemento
# coperto impatta il conto economico (es. la fornitura energetica coperta
# viene rilevata a costo), la quota corrispondente della riserva OCI va
# RICLASSIFICATA ("recycling") a P&L. Ordine FIFO sulle voci di impatto.
#
# Modello:
#   riserva_oci  = saldo della riserva OCI (EUR; puo' essere + o -; NaN/inf
#                  vietati). segno s = sign(riserva), R = |riserva|.
#   voci         = lista di (nome, quota_eur >= 0): importo del coperto che
#                  impatta P&L nel periodo e chiede il rilascio della riserva.
#   rilascio     = per voce in ordine: rel = min(quota, residuo); la voce
#                  riceve s*rel; residuo -= rel.
#   tolleranza   = soglia di materialita' (EUR >= 0): un residuo <= tolleranza
#                  conta come rilascio completo.
#
# Verdetti per voce (EPS=1e-9 sui bordi):
#   quota <= EPS                      -> NESSUN_RILASCIO
#   rel >= quota - EPS                 -> RILASCIATA
#   rel > EPS                          -> RILASCIATA_PARZIALE
#   altrimenti                         -> NON_RILASCIATA (riserva esaurita)
# Verdetto complessivo:
#   |R| <= EPS                         -> RISERVA_VUOTA
#   residuo <= max(EPS, tolleranza)     -> RILASCIO_COMPLETO
#   rilasciato <= EPS                   -> NESSUN_RILASCIO
#   altrimenti                         -> RILASCIO_PARZIALE
# ===========================================================================


def mh505_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh505_str(x, nome):
    if not isinstance(x, str) or not x.strip():
        raise ValueError(f"{nome}: testo non vuoto richiesto")
    return x.strip()


def mh505_ge0(x, nome):
    _v = mh505_num(x, nome)
    if _v < 0.0:
        raise ValueError(f"{nome}: non puo' essere negativo")
    return _v


def mh505_voce(nome, quota_eur):
    """Valida una voce di impatto: nome + quota di rilascio richiesta (>= 0)."""
    return {"nome": mh505_str(nome, "nome"),
            "quota": mh505_ge0(quota_eur, "quota_eur")}


def mh505_rilascio(voci, riserva_oci, tolleranza_eur=0.0):
    """Rilascio FIFO della riserva OCI sulle voci, in ordine di lista.

    voci: lista di dict da mh505_voce; riserva_oci: saldo riserva (EUR);
    tolleranza_eur: soglia di materialita' sul residuo (>= 0).
    Ritorna la lista righe con quota, rilasciato (col segno della riserva),
    residuo_dopo e verdetto di voce.
    """
    _tol = mh505_ge0(tolleranza_eur, "tolleranza_eur")
    _R0 = mh505_num(riserva_oci, "riserva_oci")
    if not voci:
        raise ValueError("voci: lista non vuota richiesta")
    _EPS = 1e-9
    _R = abs(_R0)
    _s = 0.0 if _R <= _EPS else (1.0 if _R0 > 0 else -1.0)
    _residuo = _R
    _righe = []
    for _v in voci:
        _q = mh505_ge0(_v["quota"], f"quota[{_v.get('nome', '?')}]")
        _rel = min(_q, _residuo)
        _residuo -= _rel
        if _q <= _EPS:
            _vd = "NESSUN_RILASCIO"
        elif _rel >= _q - _EPS:
            _vd = "RILASCIATA"
        elif _rel > _EPS:
            _vd = "RILASCIATA_PARZIALE"
        else:
            _vd = "NON_RILASCIATA"
        _righe.append({"nome": mh505_str(_v["nome"], "nome"),
                       "quota": _q, "rilasciato": _s * _rel,
                       "residuo_dopo": _s * _residuo, "verdetto": _vd})
    return _righe


def mh505_riepilogo(voci, riserva_oci, tolleranza_eur=0.0):
    """Sintesi del recycling: rilasciato, residuo, ratio, verdetto complessivo."""
    _righe = mh505_rilascio(voci, riserva_oci, tolleranza_eur)
    _R0 = mh505_num(riserva_oci, "riserva_oci")
    _R = abs(_R0)
    _ril = sum(abs(_r["rilasciato"]) for _r in _righe)
    _res = _R - _ril
    _EPS = 1e-9
    _cont = {"RILASCIATA": 0, "RILASCIATA_PARZIALE": 0,
             "NON_RILASCIATA": 0, "NESSUN_RILASCIO": 0}
    for _r in _righe:
        _cont[_r["verdetto"]] += 1
    if _R <= _EPS:
        _vc = "RISERVA_VUOTA"
    elif _res <= max(_EPS, float(tolleranza_eur)):
        _vc = "RILASCIO_COMPLETO"
    elif _ril <= _EPS:
        _vc = "NESSUN_RILASCIO"
    else:
        _vc = "RILASCIO_PARZIALE"
    return {"n_voci": len(_righe), "conteggi": _cont,
            "verdetto_complessivo": _vc,
            "riserva_iniziale_eur": _R0, "rilasciato_eur": _ril,
            "residuo_eur": _res,
            "ratio_rilasciata": _ril / _R if _R > _EPS else 0.0,
            "voci_con_rilascio": sum(1 for _r in _righe
                                     if abs(_r["rilasciato"]) > _EPS),
            "righe": _righe}


# ===========================================================================
# W504 (16/10/2026) - tab504 "📊📓 Diario dell'inefficacia: OCI vs P&L per periodo"
#
# Diario di inefficacia della copertura (IFRS 9, cash-flow hedge, "lower of"):
#   per ogni periodo:  d_hedge = ΔFV strumento di copertura (EUR)
#                      d_item  = ΔFV elemento coperto attribuibile al rischio (EUR)
#   cumulati:          H_t = Σ d_hedge,  I_t = Σ d_item
#   efficace cumulata: E_t = sign(H_t) * min(|H_t|, |I_t|)        -> OCI
#                      (la parte efficace e' il "lower of" cumulato)
#   inefficace cumul.: X_t = H_t - E_t                            -> P&L
#   inefficace periodo: x_t = X_t - X_{t-1};  eff_periodo = d_hedge_t - x_t
#
# Verdetti per periodo (EPS=1e-9 sui bordi):
#   |x_t| <= EPS                        -> EFFICACE
#   |x_t| <= tolleranza% * |d_hedge_t|   -> INEFFICACE_ENTRO_SOGLIA
#   altrimenti                           -> INEFFICACE_OLTRE_SOGLIA
# Verdetto complessivo: il piu' SEVERO
#   INEFFICACE_OLTRE_SOGLIA > INEFFICACE_ENTRO_SOGLIA > EFFICACE.
# ===========================================================================


def mh504_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh504_str(x, nome):
    if not isinstance(x, str) or not x.strip():
        raise ValueError(f"{nome}: testo non vuoto richiesto")
    return x.strip()


def mh504_pct(x, nome):
    _v = mh504_num(x, nome)
    if not 0.0 <= _v <= 100.0:
        raise ValueError(f"{nome}: deve stare in [0, 100]")
    return _v


def mh504_periodo(nome, d_hedge, d_item):
    """Valida un periodo del diario: nome + ΔFV strumento + ΔFV elemento coperto."""
    return {"nome": mh504_str(nome, "nome"),
            "d_hedge": mh504_num(d_hedge, "delta_hedge"),
            "d_item": mh504_num(d_item, "delta_item")}


def mh504_lower_of(cum_hedge, cum_item):
    """Parte efficace cumulata ('lower of'): sign(H)*min(|H|,|I|); H=0 -> 0."""
    _H = mh504_num(cum_hedge, "cum_hedge")
    _I = mh504_num(cum_item, "cum_item")
    if abs(_H) <= 1e-9:
        return 0.0
    return (1.0 if _H > 0 else -1.0) * min(abs(_H), abs(_I))


def mh504_inefficacia(periodi, tolleranza_pct):
    """Diario per periodo: cumulati, ripartizione OCI/P&L, verdetti.

    periodi: lista di dict da mh504_periodo; tolleranza_pct: soglia di
    tolleranza sull'inefficace di periodo in % di |d_hedge|.
    """
    _tol = mh504_pct(tolleranza_pct, "tolleranza")
    if not periodi:
        raise ValueError("periodi: lista non vuota richiesta")
    _EPS = 1e-9
    _H = 0.0
    _I = 0.0
    _Xprev = 0.0
    _righe = []
    for _p in periodi:
        _H += _p["d_hedge"]
        _I += _p["d_item"]
        _E = mh504_lower_of(_H, _I)
        _X = _H - _E
        _x = _X - _Xprev
        _eff_p = _p["d_hedge"] - _x
        _soglia = _tol / 100.0 * abs(_p["d_hedge"])
        if abs(_x) <= _EPS:
            _v = "EFFICACE"
        elif abs(_x) <= _soglia + _EPS:
            _v = "INEFFICACE_ENTRO_SOGLIA"
        else:
            _v = "INEFFICACE_OLTRE_SOGLIA"
        _righe.append({"nome": _p["nome"], "d_hedge": _p["d_hedge"],
                       "d_item": _p["d_item"], "cum_hedge": _H,
                       "cum_item": _I, "eff_cum": _E, "ineff_cum": _X,
                       "eff_periodo": _eff_p, "ineff_periodo": _x,
                       "soglia": _soglia, "verdetto": _v})
        _Xprev = _X
    return _righe


def mh504_riepilogo(periodi, tolleranza_pct):
    """Sintesi del diario: OCI/P&L cumulati, ratio, verdetto complessivo."""
    _righe = mh504_inefficacia(periodi, tolleranza_pct)
    _cont = {"EFFICACE": 0, "INEFFICACE_ENTRO_SOGLIA": 0,
             "INEFFICACE_OLTRE_SOGLIA": 0}
    for _r in _righe:
        _cont[_r["verdetto"]] += 1
    _sev = {"EFFICACE": 0, "INEFFICACE_ENTRO_SOGLIA": 1,
            "INEFFICACE_OLTRE_SOGLIA": 2}
    _vc = max((_r["verdetto"] for _r in _righe), key=lambda v: _sev[v])
    _ult = _righe[-1]
    _ratio = abs(_ult["ineff_cum"]) / max(abs(_ult["cum_hedge"]), 1e-9)
    return {"n_periodi": len(_righe), "conteggi": _cont,
            "verdetto_complessivo": _vc,
            "oci_cum_eur": _ult["eff_cum"], "pnl_cum_eur": _ult["ineff_cum"],
            "ratio_inefficacia": _ratio,
            "periodi_con_inefficacia": sum(1 for _r in _righe
                                          if abs(_r["ineff_periodo"]) > 1e-9),
            "righe": _righe}


# ===========================================================================
# W503 (16/10/2026) - tab503 "📦 Cost-of-carry: scomponi il premio del forward"
#
# Modello cost-of-carry (capitalizzazione continua):
#   F = S * e^(c*T)            c = ln(F/S) / T   (carry netto annualizzato)
#   c = r + u - y              r = tasso risk-free, u = costo stoccaggio,
#                              y = convenience yield implicita
#   => y = r + u - c
#
# Componenti del premio (EUR/MWh, additive sul prezzo):
#   comp_tasso = S * (e^(r*T) - 1)                  (finanziamento)
#   comp_stocc = S * e^(r*T) * (e^(u*T) - 1)        (stoccaggio fisico)
#   comp_conv  = F - S * e^((r+u)*T)                (convenience: <0 = benefit)
#   premio     = F - S = comp_tasso + comp_stocc + comp_conv  (a meno di arrotondamenti)
#
# Verdetti (EPS=1e-9 sui bordi per robustezza float):
#   c < 0        -> BACKWARDATION     (mercato paga la disponibilita' immediata:
#                                     scarsita'/convenience alta)
#   c > r + u    -> CONTANGO_ANOMALO  (y < 0: forward troppo caro rispetto a
#                                     tasso+stoccaggio, oppure u/r sottostimati;
#                                     arbitraggio teorico: vendi forward, compra
#                                     spot e stocca)
#   altrimenti   -> CONTANGO_EQUO     (premio spiegato da tasso + stoccaggio)
#
# Verdetto complessivo del book: il piu' SEVERO tra
# CONTANGO_ANOMALO > BACKWARDATION > CONTANGO_EQUO.
# Per le commodity non stoccabili (power, EUA) u e' forzato a 0.
# ===========================================================================


def mh503_num(x, nome):
    import math
    import numbers
    if isinstance(x, bool) or not isinstance(x, numbers.Real):
        raise ValueError(f"{nome}: deve essere un numero")
    if math.isnan(x) or math.isinf(x):
        raise ValueError(f"{nome}: NaN/inf non ammessi")
    return float(x)


def mh503_str(x, nome):
    if not isinstance(x, str) or not x.strip():
        raise ValueError(f"{nome}: testo non vuoto richiesto")
    return x.strip()


def mh503_ge0(x, nome):
    _v = mh503_num(x, nome)
    if _v < 0.0:
        raise ValueError(f"{nome}: non puo' essere negativo")
    return _v


def mh503_pos(x, nome):
    _v = mh503_num(x, nome)
    if _v <= 0.0:
        raise ValueError(f"{nome}: deve essere positivo")
    return _v


def mh503_pct(x, nome):
    _v = mh503_num(x, nome)
    if not 0.0 <= _v <= 100.0:
        raise ValueError(f"{nome}: deve stare in [0, 100]")
    return _v


def mh503_contratto(nome, spot, fwd, giorni):
    """Valida un contratto forward.

    spot > 0 (EUR/MWh), fwd > 0 (EUR/MWh), giorni > 0 (scadenza).
    """
    _nm = mh503_str(nome, "nome")
    _s = mh503_pos(spot, "spot")
    _f = mh503_pos(fwd, "forward")
    _g = mh503_pos(giorni, "giorni")
    return {"nome": _nm, "spot": _s, "fwd": _f, "giorni": _g}


def mh503_carry(c, r_pct, u_pct, stoccabile):
    """Scompone il premio del forward in tasso + stoccaggio + convenience.

    c: dict da mh503_contratto; r_pct: tasso discreto annuo % (>=0);
    u_pct: costo stoccaggio annuo % su spot (>=0); stoccabile: bool
    (per le commodity non stoccabili u e' forzato a 0).
    """
    import math
    _spot = c["spot"]
    _fwd = c["fwd"]
    _giorni = c["giorni"]
    _r = mh503_ge0(r_pct, "tasso")
    _u = mh503_ge0(u_pct, "stoccaggio")
    if not isinstance(stoccabile, bool):
        raise ValueError("stoccabile: deve essere un booleano")
    _EPS = 1e-9
    _rc = math.log1p(_r / 100.0)          # tasso continuo
    _uc = (_u / 100.0) if stoccabile else 0.0
    _T = _giorni / 365.0
    _carry = math.log(_fwd / _spot) / _T  # carry netto annualizzato
    _y = _rc + _uc - _carry               # convenience yield implicita
    _f_teo = _spot * math.exp((_rc + _uc) * _T)
    _comp_tasso = _spot * (math.exp(_rc * _T) - 1.0)
    _comp_stocc = _spot * math.exp(_rc * _T) * (math.exp(_uc * _T) - 1.0)
    _comp_conv = _fwd - _f_teo
    if _carry < -_EPS:
        _verdetto = "BACKWARDATION"
    elif _carry > _rc + _uc + _EPS:
        _verdetto = "CONTANGO_ANOMALO"
    else:
        _verdetto = "CONTANGO_EQUO"
    return {
        "nome": c["nome"],
        "spot": _spot,
        "fwd": _fwd,
        "giorni": _giorni,
        "stoccabile": stoccabile,
        "T_anni": _T,
        "carry_netto_annuo": _carry,
        "convenience_yield": _y,
        "f_teorico": _f_teo,
        "comp_tasso_eur_mwh": _comp_tasso,
        "comp_stoccaggio_eur_mwh": _comp_stocc,
        "comp_convenience_eur_mwh": _comp_conv,
        "premio_eur_mwh": _fwd - _spot,
        "verdetto": _verdetto,
    }


def mh503_riepilogo(contratti, r_pct, u_pct, stoccabili):
    """Applica mh503_carry a tutti i contratti e sintetizza il book.

    stoccabili: lista di bool parallela ai contratti.
    """
    if not contratti:
        raise ValueError("contratti: lista non vuota richiesta")
    if len(stoccabili) != len(contratti):
        raise ValueError("stoccabili: deve avere la stessa lunghezza dei contratti")
    _righe = [mh503_carry(c, r_pct, u_pct, s)
              for c, s in zip(contratti, stoccabili)]
    _cont = {"BACKWARDATION": 0, "CONTANGO_EQUO": 0, "CONTANGO_ANOMALO": 0}
    for _r in _righe:
        _cont[_r["verdetto"]] += 1
    _sev = {"CONTANGO_EQUO": 0, "BACKWARDATION": 1, "CONTANGO_ANOMALO": 2}
    _vc = max((_r["verdetto"] for _r in _righe), key=lambda v: _sev[v])
    _y_media = sum(_r["convenience_yield"] for _r in _righe) / len(_righe)
    _max_res = max(abs(_r["comp_convenience_eur_mwh"]) for _r in _righe)
    return {
        "n_contratti": len(_righe),
        "conteggi": _cont,
        "verdetto_complessivo": _vc,
        "convenience_yield_media": _y_media,
        "max_residuo_eur_mwh": _max_res,
        "righe": _righe,
    }


