            st.caption(f"💡 Profilo: F1 {vf_f1} MW, F2 {vf_f2} MW, F3 {vf_f3} MW — taglio {vf_taglio} MW nelle {vf_ore} ore più care: {vf['mwh']:,.0f} MWh per {vf['totale']:,.0f} € nel periodo ({vf['n_ore']:,} ore).")

            col_v1, col_v2 = st.columns(2)
