        st.markdown(f"<h1>🔀💰 {titolo290}</h1>", unsafe_allow_html=True)
        st.caption("Valutazione diritti di trasmissione transfrontaliera (aste tipo JAO): il modello di Bachelier dice se il prezzo d'asta e' equo.")
