            fig_360.add_trace(go.Scatter(
                y=m360["eqb_path"], mode="lines",
                name="Kelly pieno",
                line=dict(color="gray", width=2, dash="dash")))
            fig_360.update_layout(
                xaxis_title="trade",
                yaxis_title="equity", height=360)
            st.plotly_chart(fig_360, use_container_width=True)
