                    _npt592 = 120
                    _qq592 = [_i * _qmax592 / _npt592
                              for _i in range(_npt592 + 1)]
                    _stk592 = sorted(_units592,
                                     key=lambda u: (u["offerta"],
                                                    -u["derated_mw"], u["id"]))
                    _off592 = []
                    for _q in _qq592:
                        _cumq = 0.0
                        _bq = None
